-- ============================================================================
-- seed-exercises.sql  —  backup of the public.exercises workout library.
-- 1393 exercises: names, muscles, gif_url, youtube_id, instructions.
-- Idempotent (ON CONFLICT DO NOTHING). Run AFTER schema.sql.
-- Regenerate with scripts/export-exercises.js whenever the library changes.
-- NOTE: the GIF files live in the exercise-gifs Storage bucket, not here.
-- ============================================================================

-- Columns the live table has beyond the original schema.sql (safe no-ops if present):
ALTER TABLE public.exercises ADD COLUMN IF NOT EXISTS youtube_id   TEXT;
ALTER TABLE public.exercises ADD COLUMN IF NOT EXISTS instructions TEXT[];

INSERT INTO public.exercises
SELECT * FROM jsonb_populate_recordset(
  null::public.exercises,
  $exercises_seed$[{"id":"1","name":"3/4 sit-up","body_part":"waist","target":"abs","secondary_muscles":["hip flexors","lower back"],"equipment":"body weight","difficulty":"beginner","description":"The 3/4 sit-up is an abdominal exercise performed with body weight. It involves curling the torso up to a 45-degree angle, engaging the abs, hip flexors, and lower back. This movement is commonly used to build core strength and stability.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0001.gif","youtube_id":null,"instructions":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"10","name":"assisted hanging knee raise with throw down","body_part":"waist","target":"abs","secondary_muscles":["hip flexors","lower back"],"equipment":"assisted","difficulty":"advanced","description":"The assisted hanging knee raise with throw down is an advanced core exercise that targets the abdominal muscles, with additional engagement of the hip flexors and lower back. The movement involves hanging from a pull-up bar, raising the knees to the chest, and then explosively throwing the legs downward, requiring significant core strength, coordination, and control.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0010.gif","youtube_id":null,"instructions":["Hang from a pull-up bar with your arms fully extended and your palms facing away from you.","Engage your core and lift your knees towards your chest, keeping your legs together.","Once your knees are at chest level, explosively throw your legs down towards the ground, extending them fully.","Allow your legs to swing back up and repeat the movement for the desired number of repetitions."]},{"id":"100","name":"barbell skier","body_part":"shoulders","target":"delts","secondary_muscles":["triceps","core"],"equipment":"barbell","difficulty":"intermediate","description":"The barbell skier is a dynamic shoulder exercise that involves lifting a barbell while performing a small jump, targeting the deltoids and engaging the triceps and core for stability.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0100.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and hold a barbell in front of your thighs with an overhand grip.","Bend your knees slightly and hinge forward at the hips, keeping your back straight and chest up.","Simultaneously lift the barbell up towards your shoulders while jumping slightly off the ground.","As you reach the top of the movement, quickly reverse the motion and lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1000","name":"band single leg reverse calf raise","body_part":"lower legs","target":"calves","secondary_muscles":["hamstrings","glutes"],"equipment":"band","difficulty":"intermediate","description":"The band single leg reverse calf raise is a lower leg exercise that targets the calves, with secondary emphasis on the hamstrings and glutes. It uses a resistance band and requires balance and control as you raise your heel off the ground on one leg.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1000.gif","youtube_id":null,"instructions":["Stand with your feet hip-width apart and place the band around the ball of your foot.","Hold onto a stable object for balance.","Slowly raise your heel off the ground, lifting your body weight onto the ball of your foot.","Pause for a moment at the top, then slowly lower your heel back down to the starting position.","Repeat for the desired number of repetitions, then switch to the other leg."]},{"id":"1001","name":"band single leg split squat","body_part":"upper legs","target":"quads","secondary_muscles":["glutes","hamstrings"],"equipment":"band","difficulty":"intermediate","description":"The band single leg split squat is a lower body exercise targeting the quads, with secondary emphasis on the glutes and hamstrings. It uses a resistance band for added tension and requires balance and coordination.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1001.gif","youtube_id":null,"instructions":["Stand with your feet hip-width apart and place a resistance band around your ankles.","Take a big step forward with your right foot and a smaller step back with your left foot.","Bend your knees and lower your body until your right thigh is parallel to the ground, keeping your left knee slightly above the ground.","Push through your right heel to return to the starting position.","Repeat on the other side."]},{"id":"1002","name":"band lying straight leg raise","body_part":"waist","target":"abs","secondary_muscles":["hip flexors"],"equipment":"band","difficulty":"intermediate","description":"The band lying straight leg raise is an abdominal exercise that also engages the hip flexors. It uses a resistance band to add difficulty and helps strengthen the core and lower body.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1002.gif","youtube_id":null,"instructions":["Lie flat on your back with your legs straight and your feet together.","Place the band around the arches of your feet and hold the ends of the band with your hands.","Engaging your abs, lift both legs off the ground until they are perpendicular to the floor.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1003","name":"band squat row","body_part":"upper legs","target":"glutes","secondary_muscles":["hamstrings","quadriceps","back"],"equipment":"band","difficulty":"beginner","description":"The band squat row is a compound exercise that targets the glutes while also engaging the hamstrings, quadriceps, and back. It combines a squat with a rowing motion using a resistance band, making it effective for both lower and upper body strength.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1003.gif","youtube_id":null,"instructions":["Attach the band to a sturdy anchor point at waist height.","Stand facing the anchor point with your feet shoulder-width apart.","Hold the band handles with your palms facing each other and your arms extended in front of you.","Bend your knees and lower into a squat position, keeping your back straight and chest lifted.","From the squat position, pull the band handles towards your body, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1004","name":"band squat","body_part":"upper legs","target":"glutes","secondary_muscles":["quadriceps","hamstrings","calves"],"equipment":"band","difficulty":"beginner","description":"The band squat is a lower body exercise that targets the glutes using a resistance band placed above the knees. It also engages the quadriceps, hamstrings, and calves. This exercise helps build strength and stability in the lower body.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1004.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, with the band placed just above your knees.","Keeping your chest up and core engaged, push your hips back and bend your knees to lower into a squat position.","Make sure your knees are tracking over your toes and your weight is in your heels.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1005","name":"band standing crunch","body_part":"waist","target":"abs","secondary_muscles":["obliques"],"equipment":"band","difficulty":"beginner","description":"The band standing crunch is an abdominal exercise performed with a resistance band anchored at waist height. It targets the abs and also engages the obliques. The movement involves crunching forward against the resistance of the band while standing, which can help strengthen the core.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1005.gif","youtube_id":null,"instructions":["Attach the band to a sturdy anchor point at waist height.","Stand facing away from the anchor point with your feet shoulder-width apart.","Hold the band with both hands and bring it up to your chest, keeping your elbows bent and close to your body.","Engage your abs and slowly crunch forward, bringing your chest towards your knees.","Pause for a moment at the top of the crunch, then slowly return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1007","name":"band standing twisting crunch","body_part":"waist","target":"abs","secondary_muscles":["obliques"],"equipment":"band","difficulty":"beginner","description":"The band standing twisting crunch is an abdominal exercise that targets the abs and obliques using a resistance band. It involves twisting the torso while performing a crunch motion, engaging the core muscles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1007.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and place the band around your upper back, crossing it in front of your chest.","Hold the ends of the band with your hands, keeping your elbows bent and close to your sides.","Engage your abs and twist your torso to one side, bringing your elbow towards the opposite knee.","Pause for a moment, then return to the starting position.","Repeat on the other side.","Continue alternating sides for the desired number of repetitions."]},{"id":"1008","name":"band step-up","body_part":"upper legs","target":"glutes","secondary_muscles":["quadriceps","hamstrings","calves"],"equipment":"band","difficulty":"beginner","description":"The band step-up is a lower body exercise that targets the glutes, with secondary emphasis on the quadriceps, hamstrings, and calves. It involves stepping onto a platform with resistance provided by a band around the thighs, enhancing muscle activation and stability.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1008.gif","youtube_id":null,"instructions":["Place a band around your thighs, just above your knees.","Stand facing a step or platform with your feet hip-width apart.","Step up onto the platform with your right foot, pushing through your heel.","Extend your left leg behind you, keeping it straight.","Lower your left foot back down to the ground.","Repeat with your left foot stepping up onto the platform.","Continue alternating legs for the desired number of repetitions."]},{"id":"1009","name":"band stiff leg deadlift","body_part":"upper legs","target":"glutes","secondary_muscles":["hamstrings","lower back"],"equipment":"band","difficulty":"beginner","description":"The band stiff leg deadlift is a lower body exercise targeting the glutes, with secondary emphasis on the hamstrings and lower back. It uses a resistance band to provide tension throughout the movement, focusing on hip hinging and posterior chain activation.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1009.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and place the band around your ankles.","Hold the band with both hands in front of your thighs, palms facing your body.","Keeping your back straight and your core engaged, hinge at the hips and slowly lower your upper body towards the ground.","As you lower, push your hips back and allow your knees to bend slightly.","Lower the band towards the ground, feeling a stretch in your hamstrings.","Pause for a moment at the bottom, then engage your glutes and hamstrings to lift your upper body back up to the starting position.","Repeat for the desired number of repetitions."]},{"id":"101","name":"barbell speed squat","body_part":"upper legs","target":"glutes","secondary_muscles":["quadriceps","hamstrings","calves"],"equipment":"barbell","difficulty":"intermediate","description":"The barbell speed squat is a dynamic variation of the traditional squat, performed with a focus on explosive movement and speed. This exercise targets the glutes as the primary muscle group, with significant involvement from the quadriceps, hamstrings, and calves. It requires good technique, balance, and strength to perform safely, especially with added weight.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0101.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, toes slightly turned out.","Hold the barbell across your upper back, resting it on your traps or rear delts.","Engage your core and keep your chest up as you lower your hips back and down, as if sitting into a chair.","Lower until your thighs are parallel to the ground, or as low as you can comfortably go.","Drive through your heels to stand back up, squeezing your glutes at the top.","Repeat for the desired number of repetitions."]},{"id":"1010","name":"band straight leg deadlift","body_part":"back","target":"spine","secondary_muscles":["hamstrings","glutes"],"equipment":"band","difficulty":"beginner","description":"The band straight leg deadlift is a resistance exercise targeting the muscles of the lower back, hamstrings, and glutes. Using a resistance band, it mimics the movement of a traditional straight leg deadlift, focusing on hip hinging and posterior chain activation.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1010.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and place the band around your feet.","Hold the band with both hands, palms facing your body, and keep your arms straight.","Engage your core and maintain a slight bend in your knees.","Slowly hinge forward at your hips, keeping your back straight and chest lifted.","Lower the band towards the ground while keeping your legs straight.","Pause for a moment at the bottom, then squeeze your glutes and hamstrings to return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1011","name":"band seated twist","body_part":"waist","target":"abs","secondary_muscles":["obliques"],"equipment":"band","difficulty":"beginner","description":"The band seated twist is an exercise that targets the abdominal muscles, particularly the obliques, by incorporating rotational movement with resistance from a band. It is performed seated on the ground with legs extended and involves twisting the torso side to side.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1011.gif","youtube_id":null,"instructions":["Sit on the ground with your legs extended in front of you and your back straight.","Wrap the band around your waist and hold the ends with both hands.","Engage your abs and slowly twist your torso to one side, keeping your back straight and your feet on the ground.","Pause for a moment at the end of the twist, then slowly return to the starting position.","Repeat the twist to the other side.","Continue alternating sides for the desired number of repetitions."]},{"id":"1012","name":"band twisting overhead press","body_part":"shoulders","target":"delts","secondary_muscles":["triceps","upper back"],"equipment":"band","difficulty":"intermediate","description":"The band twisting overhead press is a dynamic shoulder exercise that combines an overhead press with a torso twist, engaging the deltoids, triceps, and upper back while also challenging core stability and coordination.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1012.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and place the band under your feet.","Hold the band handles at shoulder height with your palms facing forward.","Engage your core and press the band overhead, fully extending your arms.","As you press, twist your torso to one side, keeping your hips stable.","Pause for a moment at the top, then return to the starting position.","Repeat the press and twist on the opposite side.","Continue alternating sides for the desired number of repetitions."]},{"id":"1013","name":"band underhand pulldown","body_part":"back","target":"lats","secondary_muscles":["biceps","forearms"],"equipment":"band","difficulty":"beginner","description":"The band underhand pulldown is a resistance band exercise targeting the latissimus dorsi (lats) and also engaging the biceps and forearms. It mimics the movement of a lat pulldown machine but uses a resistance band anchored overhead.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1013.gif","youtube_id":null,"instructions":["Attach the band to a high anchor point, such as a pull-up bar or sturdy beam.","Stand facing the anchor point with your feet shoulder-width apart.","Grasp the band with an underhand grip, hands slightly wider than shoulder-width apart.","Extend your arms fully overhead, keeping your elbows slightly bent.","Engage your lats and pull the band down towards your chest, squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, then slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1014","name":"band v-up","body_part":"waist","target":"abs","secondary_muscles":["hip flexors"],"equipment":"band","difficulty":"intermediate","description":"The band v-up is an abdominal exercise that uses a resistance band to increase the challenge. It targets the abs and also engages the hip flexors, requiring core strength and coordination to perform the simultaneous lifting of the upper and lower body.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1014.gif","youtube_id":null,"instructions":["Lie flat on your back with your legs straight and your arms extended overhead, holding the band.","Engaging your abs, lift your legs and upper body off the ground simultaneously, reaching your hands towards your toes.","Pause for a moment at the top, then slowly lower your legs and upper body back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1015","name":"band vertical pallof press","body_part":"waist","target":"abs","secondary_muscles":["obliques","glutes"],"equipment":"band","difficulty":"beginner","description":"The band vertical Pallof press is an anti-rotation core exercise that targets the abs and also engages the obliques and glutes. It is performed by pressing a resistance band away from the chest while resisting rotational forces, helping to build core stability and strength.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1015.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and wrap the band around a sturdy object at chest height.","Hold the band with both hands and step away from the anchor point, creating tension in the band.","Position yourself perpendicular to the anchor point, with your side facing the band.","Extend your arms straight out in front of you, keeping your hands at chest height.","Engage your core and press the band away from your chest, fully extending your arms.","Hold the position for a few seconds, then slowly bring the band back towards your chest.","Repeat for the desired number of repetitions, then switch sides."]},{"id":"1016","name":"band wrist curl","body_part":"lower arms","target":"forearms","secondary_muscles":["biceps","triceps"],"equipment":"band","difficulty":"beginner","description":"The band wrist curl is an isolation exercise targeting the forearms using a resistance band. It is performed seated, with the forearms resting on the thighs, and involves curling the wrists upward to strengthen the forearm muscles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1016.gif","youtube_id":null,"instructions":["Sit on a bench or chair with your feet flat on the ground.","Hold the band with both hands, palms facing up, and rest your forearms on your thighs.","Slowly curl your wrists upward, squeezing your forearms.","Pause for a moment at the top, then slowly lower your wrists back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1017","name":"band y-raise","body_part":"shoulders","target":"delts","secondary_muscles":["traps","rhomboids"],"equipment":"band","difficulty":"beginner","description":"The band Y-raise is a shoulder exercise that targets the deltoids and also engages the traps and rhomboids. It is performed using a resistance band and involves raising the arms in a 'Y' shape to strengthen the upper back and shoulders.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1017.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and hold the band in front of your thighs with your palms facing inwards.","Keep your arms straight and lift them up and out to the sides, forming a 'Y' shape with your body.","Squeeze your shoulder blades together at the top of the movement.","Slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1018","name":"band shrug","body_part":"back","target":"traps","secondary_muscles":["shoulders"],"equipment":"band","difficulty":"beginner","description":"The band shrug is an exercise targeting the trapezius muscles using a resistance band. It is performed by standing on the band, holding the ends, and shrugging the shoulders upward to engage the traps.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1018.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and place the band under your feet, holding the ends with your hands.","Keep your arms straight and relaxed, and let the band hang in front of your thighs.","Engage your traps by shrugging your shoulders upward, lifting the band as high as possible.","Hold the contraction for a moment, then slowly lower your shoulders back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"102","name":"barbell squat (on knees)","body_part":"upper legs","target":"quads","secondary_muscles":["glutes","hamstrings","calves"],"equipment":"barbell","difficulty":"intermediate","description":"The barbell squat (on knees) is a variation of the traditional squat performed from a kneeling position. This exercise targets the quadriceps while also engaging the glutes, hamstrings, and calves. It requires good core stability and balance, as well as proper technique to safely handle the barbell.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0102.gif","youtube_id":null,"instructions":["Start by kneeling on the ground with your knees hip-width apart and your toes pointing forward.","Place a barbell across your shoulders, gripping it with an overhand grip and your hands slightly wider than shoulder-width apart.","Engage your core and keep your chest lifted as you slowly lower your body down by bending your knees, keeping your back straight.","Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1022","name":"band standing rear delt row","body_part":"shoulders","target":"delts","secondary_muscles":["trapezius","rhomboids","biceps"],"equipment":"band","difficulty":"beginner","description":"The band standing rear delt row is an exercise targeting the rear deltoids, with secondary emphasis on the trapezius, rhomboids, and biceps. It uses a resistance band and involves pulling the band towards the chest while hinging at the hips, focusing on squeezing the shoulder blades together.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1022.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and place the band under your feet.","Hold the band handles with your palms facing each other and your arms extended in front of you.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Pull the band towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1023","name":"band straight back stiff leg deadlift","body_part":"upper legs","target":"glutes","secondary_muscles":["hamstrings","lower back"],"equipment":"band","difficulty":"beginner","description":"The band straight back stiff leg deadlift is a lower body exercise targeting the glutes, with secondary emphasis on the hamstrings and lower back. It uses a resistance band and requires maintaining a straight back while hinging at the hips, focusing on posterior chain strength.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1023.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and place the band around your upper legs.","Hold the band with both hands in front of your thighs, palms facing your body.","Keeping your back straight and your knees slightly bent, hinge at the hips and lower the band towards the ground.","Feel the stretch in your hamstrings as you lower the band.","Engage your glutes and hamstrings to lift your body back up to the starting position.","Repeat for the desired number of repetitions."]},{"id":"103","name":"barbell standing ab rollerout","body_part":"waist","target":"abs","secondary_muscles":["shoulders","lower back"],"equipment":"barbell","difficulty":"advanced","description":"The barbell standing ab rollerout is an advanced core exercise that targets the abs, with secondary emphasis on the shoulders and lower back. It requires significant core strength, stability, and control to perform safely and effectively.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0103.gif","youtube_id":null,"instructions":["Stand upright with your feet shoulder-width apart and hold the barbell with both hands in front of your thighs.","Engage your core and slowly roll the barbell down towards the ground, keeping your back straight and your arms extended.","Continue rolling the barbell forward until your body is fully extended and your hands are directly above your head.","Pause for a moment, then slowly roll the barbell back towards your thighs, maintaining control and keeping your core engaged.","Repeat for the desired number of repetitions."]},{"id":"104","name":"barbell standing back wrist curl","body_part":"lower arms","target":"forearms","secondary_muscles":["biceps","shoulders"],"equipment":"barbell","difficulty":"beginner","description":"The barbell standing back wrist curl is an isolation exercise targeting the forearms, specifically the wrist extensors. It involves curling the barbell upwards using only the wrists while standing.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0104.gif","youtube_id":null,"instructions":["Stand up straight with your feet shoulder-width apart and hold a barbell with an overhand grip.","Rest the barbell on the back of your hands with your palms facing down and your fingers pointing towards your body.","Keeping your upper arms stationary, exhale and curl your wrists upwards as far as possible.","Hold the contracted position for a brief pause, then inhale and slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"105","name":"barbell standing bradford press","body_part":"shoulders","target":"delts","secondary_muscles":["triceps","upper back"],"equipment":"barbell","difficulty":"intermediate","description":"The barbell standing Bradford press is a shoulder exercise that targets the deltoids and also works the triceps and upper back. It involves pressing a barbell overhead from the front of the shoulders, requiring strength, coordination, and shoulder mobility.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0105.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and hold the barbell in front of your shoulders with an overhand grip.","Press the barbell overhead, fully extending your arms.","Lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"106","name":"barbell standing close grip curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"barbell","difficulty":"beginner","description":"The barbell standing close grip curl is a strength exercise that targets the biceps and also works the forearms. It involves curling a barbell with a close grip, emphasizing the inner part of the biceps.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0106.gif","youtube_id":null,"instructions":["Stand up straight with your feet shoulder-width apart and hold a barbell with an underhand grip, hands close together.","Keep your elbows close to your torso and your upper arms stationary throughout the movement.","Exhale as you curl the weights while contracting your biceps. Continue to raise the bar until your biceps are fully contracted and the bar is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale as you slowly begin to bring the barbell back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"107","name":"barbell standing front raise over head","body_part":"shoulders","target":"delts","secondary_muscles":["triceps","upper back"],"equipment":"barbell","difficulty":"intermediate","description":"The barbell standing front raise over head is a shoulder exercise that targets the deltoids, with secondary emphasis on the triceps and upper back. It involves lifting a barbell from thigh level to overhead while standing, requiring control and shoulder strength.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0107.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, holding a barbell in front of your thighs with an overhand grip.","Keep your back straight and engage your core.","Slowly raise the barbell in front of you, keeping your arms straight and your palms facing down.","Continue lifting until the barbell is slightly above shoulder level.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"108","name":"barbell standing leg calf raise","body_part":"lower legs","target":"calves","secondary_muscles":["hamstrings","glutes"],"equipment":"barbell","difficulty":"intermediate","description":"The barbell standing leg calf raise is a strength exercise targeting the calves. It involves standing with a barbell across your upper back and raising your heels off the ground to engage the calf muscles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0108.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and place a barbell across your upper back.","Raise your heels off the ground as high as possible, using your calves.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"109","name":"barbell standing overhead triceps extension","body_part":"upper arms","target":"triceps","secondary_muscles":["shoulders"],"equipment":"barbell","difficulty":"intermediate","description":"The barbell standing overhead triceps extension is a strength exercise targeting the triceps, performed by holding a barbell overhead and lowering it behind the head before extending the arms to the starting position.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0109.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and hold a barbell with an overhand grip.","Raise the barbell overhead, fully extending your arms.","Keeping your upper arms close to your head, slowly lower the barbell behind your head by bending your elbows.","Pause for a moment, then raise the barbell back to the starting position by extending your arms.","Repeat for the desired number of repetitions."]},{"id":"11","name":"assisted hanging knee raise","body_part":"waist","target":"abs","secondary_muscles":["hip flexors"],"equipment":"assisted","difficulty":"beginner","description":"The assisted hanging knee raise is an abdominal exercise performed while hanging from a pull-up bar, using assistance to help lift the knees toward the chest. It primarily targets the abs and also works the hip flexors.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0011.gif","youtube_id":null,"instructions":["Hang from a pull-up bar with your arms fully extended and your palms facing away from you.","Engage your core muscles and lift your knees towards your chest, bending at the hips and knees.","Pause for a moment at the top of the movement, squeezing your abs.","Slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"110","name":"barbell standing reverse grip curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"barbell","difficulty":"beginner","description":"The barbell standing reverse grip curl is an exercise targeting the biceps and forearms. It is performed by holding a barbell with an underhand grip, curling the weight up while keeping the elbows close to the torso, and then lowering it back down.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0110.gif","youtube_id":null,"instructions":["Stand up straight with your feet shoulder-width apart and hold a barbell with an underhand grip, palms facing up.","Keep your elbows close to your torso and your upper arms stationary.","Exhale and curl the weights while contracting your biceps, bringing the barbell as close to your shoulders as possible.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"111","name":"barbell standing rocking leg calf raise","body_part":"lower legs","target":"calves","secondary_muscles":["hamstrings","quadriceps"],"equipment":"barbell","difficulty":"intermediate","description":"The barbell standing rocking leg calf raise targets the calves and involves raising your heels while balancing a barbell across your upper back. This exercise also engages the hamstrings and quadriceps as secondary muscles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0111.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and hold a barbell across your upper back.","Raise your heels off the ground as high as possible, balancing on the balls of your feet.","Slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"112","name":"barbell standing twist","body_part":"waist","target":"abs","secondary_muscles":["obliques","lower back"],"equipment":"barbell","difficulty":"beginner","description":"The barbell standing twist is an exercise targeting the abdominal muscles, particularly the obliques and lower back, by rotating the torso while holding a barbell. It helps improve core strength and rotational stability.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0112.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and hold a barbell in front of your chest with both hands, palms facing down.","Engage your core and keep your back straight throughout the exercise.","Slowly twist your torso to the right, pivoting on your feet and hips, while keeping your lower body stable.","Pause for a moment at the end of the twist, then slowly return to the starting position.","Repeat the twist to the left side.","Continue alternating twists for the desired number of repetitions."]},{"id":"113","name":"barbell standing wide-grip curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms","shoulders"],"equipment":"barbell","difficulty":"beginner","description":"The barbell standing wide-grip curl is a biceps-focused exercise performed with a barbell using a grip wider than shoulder-width. This variation emphasizes the outer part of the biceps and also engages the forearms and shoulders.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0113.gif","youtube_id":null,"instructions":["Stand up straight with your feet shoulder-width apart and hold a barbell with an overhand grip, hands wider than shoulder-width apart.","Let the barbell hang at arm's length in front of your thighs, with your palms facing away from your body.","Keeping your upper arms stationary, exhale and curl the barbell upward by contracting your biceps.","Continue to raise the barbell until your biceps are fully contracted and the barbell is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the barbell back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"114","name":"barbell step-up","body_part":"upper legs","target":"glutes","secondary_muscles":["quadriceps","hamstrings","calves"],"equipment":"barbell","difficulty":"intermediate","description":"The barbell step-up is a compound lower body exercise that targets the glutes, quadriceps, and hamstrings by stepping onto a raised platform while holding a barbell on the upper back.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0114.gif","youtube_id":null,"instructions":["Stand in front of a bench or step with a barbell resting on your upper back.","Place one foot on the bench or step, ensuring your entire foot is in contact with the surface.","Push through your heel and step up onto the bench or step, fully extending your hip and knee.","Pause briefly at the top, then lower yourself back down to the starting position.","Repeat with the opposite leg.","Continue alternating legs for the desired number of repetitions."]},{"id":"115","name":"barbell stiff leg good morning","body_part":"upper legs","target":"glutes","secondary_muscles":["hamstrings","lower back"],"equipment":"barbell","difficulty":"advanced","description":"The barbell stiff leg good morning is a compound exercise that targets the glutes, hamstrings, and lower back. It involves hinging at the hips with a barbell across your upper back, emphasizing posterior chain strength and flexibility.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0115.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and your knees slightly bent.","Hold the barbell across your upper back, resting it on your traps.","Keeping your back straight, hinge forward at the hips, pushing your glutes back.","Lower your torso until it is parallel to the ground, feeling a stretch in your hamstrings.","Engage your glutes and hamstrings to return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"116","name":"barbell straight leg deadlift","body_part":"upper legs","target":"hamstrings","secondary_muscles":["glutes","lower back"],"equipment":"barbell","difficulty":"intermediate","description":"The barbell straight leg deadlift is a compound exercise targeting the hamstrings, with secondary emphasis on the glutes and lower back. It requires maintaining a straight back and proper hip hinge to safely stretch and strengthen the posterior chain.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0116.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and your toes pointing forward.","Hold the barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Bend at your hips and lower the barbell towards the ground, keeping your back straight and your knees slightly bent.","Lower the barbell until you feel a stretch in your hamstrings.","Engage your hamstrings and glutes to lift the barbell back up to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1160","name":"burpee","body_part":"cardio","target":"cardiovascular system","secondary_muscles":["quadriceps","hamstrings","calves","shoulders","chest"],"equipment":"body weight","difficulty":"intermediate","description":"The burpee is a full-body exercise that combines a squat, push-up, and jump to elevate heart rate and build strength and endurance.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1160.gif","youtube_id":null,"instructions":["Start in a standing position with your feet shoulder-width apart.","Lower your body into a squat position by bending your knees and placing your hands on the floor in front of you.","Kick your feet back into a push-up position.","Perform a push-up, keeping your body in a straight line.","Jump your feet back into the squat position.","Jump up explosively, reaching your arms overhead.","Land softly and immediately lower back into a squat position to begin the next repetition."]},{"id":"1167","name":"dynamic chest stretch (male)","body_part":"chest","target":"pectorals","secondary_muscles":["shoulders","triceps"],"equipment":"body weight","difficulty":"beginner","description":"The dynamic chest stretch (male) is a bodyweight exercise designed to increase flexibility and mobility in the chest, shoulders, and triceps. It involves controlled arm movements to stretch the pectoral muscles dynamically.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1167.gif","youtube_id":null,"instructions":["Stand tall with your feet shoulder-width apart.","Extend your arms straight out to the sides, parallel to the ground.","Slowly bring your arms forward, crossing them in front of your body.","Feel the stretch in your chest muscles.","Hold the stretch for 10-30 seconds.","Return to the starting position and repeat for the desired number of repetitions."]},{"id":"117","name":"barbell sumo deadlift","body_part":"upper legs","target":"glutes","secondary_muscles":["hamstrings","quadriceps","lower back"],"equipment":"barbell","difficulty":"intermediate","description":"The barbell sumo deadlift is a compound strength exercise that targets the glutes, with significant involvement of the hamstrings, quadriceps, and lower back. It requires a wide stance and emphasizes hip and leg strength.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0117.gif","youtube_id":null,"instructions":["Stand with your feet wider than shoulder-width apart, toes pointing outwards.","Place a barbell on the ground in front of you, centered between your feet.","Bend your knees and lower your hips, keeping your back straight and chest up, to grip the barbell with an overhand grip.","Engage your core and drive through your heels to lift the barbell off the ground, extending your hips and knees simultaneously.","As you lift, keep your chest up and back straight, and push your hips forward to fully engage your glutes.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position, maintaining control throughout the movement.","Repeat for the desired number of repetitions."]},{"id":"118","name":"barbell reverse grip bent over row","body_part":"back","target":"upper back","secondary_muscles":["biceps","forearms"],"equipment":"barbell","difficulty":"intermediate","description":"The barbell reverse grip bent over row is a compound exercise targeting the upper back, with secondary emphasis on the biceps and forearms. It involves pulling a barbell towards the lower chest while bent over, requiring good form and core stability.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0118.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and knees slightly bent.","Hold a barbell with an overhand grip, palms facing down, and hands slightly wider than shoulder-width apart.","Bend forward at the hips, keeping your back straight and chest up, until your torso is almost parallel to the floor.","Pull the barbell towards your lower chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"119","name":"barbell upright row v. 2","body_part":"shoulders","target":"delts","secondary_muscles":["traps","biceps"],"equipment":"barbell","difficulty":"intermediate","description":"The barbell upright row v. 2 is a compound exercise targeting the deltoids, with secondary emphasis on the traps and biceps. It involves lifting a barbell from the thighs to the upper chest by leading with the elbows, requiring good form to avoid shoulder impingement.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0119.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Let the barbell hang in front of your thighs, arms fully extended.","Keeping your back straight, exhale and lift the barbell straight up towards your chin, leading with your elbows.","Pause for a moment at the top, then inhale and slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"12","name":"assisted lying leg raise with lateral throw down","body_part":"waist","target":"abs","secondary_muscles":["hip flexors","obliques"],"equipment":"assisted","difficulty":"intermediate","description":"The assisted lying leg raise with lateral throw down is an abdominal exercise that targets the abs while also engaging the hip flexors and obliques. The movement involves lifting the legs while lying on your back, then lowering them to each side in a controlled manner, which challenges core stability and strength.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0012.gif","youtube_id":null,"instructions":["Lie flat on your back with your legs extended and your arms by your sides.","Place your hands under your glutes for support.","Engage your abs and lift your legs off the ground, keeping them straight.","While keeping your legs together, lower them to one side until they are a few inches above the ground.","Pause for a moment, then lift your legs back to the starting position.","Repeat the movement to the other side.","Continue alternating sides for the desired number of repetitions."]},{"id":"120","name":"barbell upright row","body_part":"shoulders","target":"delts","secondary_muscles":["traps","biceps"],"equipment":"barbell","difficulty":"intermediate","description":"The barbell upright row is a compound exercise that targets the deltoids and also works the traps and biceps. It involves lifting a barbell from the thighs to the upper chest, leading with the elbows.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0120.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Let the barbell hang in front of your thighs, arms fully extended.","Keeping your back straight and core engaged, exhale and lift the barbell straight up towards your chin, leading with your elbows.","Pause for a moment at the top, then inhale and slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1201","name":"dumbbell burpee","body_part":"cardio","target":"cardiovascular system","secondary_muscles":["quadriceps","hamstrings","calves","shoulders","triceps","core"],"equipment":"dumbbell","difficulty":"advanced","description":"The dumbbell burpee is a full-body exercise that combines a squat, push-up, and overhead press using dumbbells. It targets the cardiovascular system while also engaging multiple muscle groups, including the legs, shoulders, triceps, and core.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1201.gif","youtube_id":null,"instructions":["Start in a standing position with your feet shoulder-width apart and a dumbbell in each hand.","Lower your body into a squat position, placing the dumbbells on the ground in front of you.","Kick your feet back into a push-up position, keeping your body in a straight line.","Perform a push-up, bending your elbows and lowering your chest towards the ground.","Jump your feet back towards your hands, landing in a squat position.","Stand up explosively, lifting the dumbbells off the ground and bringing them to your shoulders.","Press the dumbbells overhead, fully extending your arms.","Lower the dumbbells back to your shoulders and repeat the entire sequence for the desired number of repetitions."]},{"id":"121","name":"barbell upright row v. 3","body_part":"shoulders","target":"delts","secondary_muscles":["traps","biceps"],"equipment":"barbell","difficulty":"intermediate","description":"The barbell upright row v. 3 is a compound exercise targeting the deltoids, with secondary emphasis on the traps and biceps. It involves lifting a barbell from thigh level to chin height, leading with the elbows.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0121.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Let the barbell hang in front of your thighs, arms fully extended.","Keeping your core engaged and back straight, exhale as you lift the barbell straight up towards your chin, leading with your elbows.","Pause for a moment at the top, then inhale as you slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"122","name":"barbell wide bench press","body_part":"chest","target":"pectorals","secondary_muscles":["shoulders","triceps"],"equipment":"barbell","difficulty":"intermediate","description":"The barbell wide bench press is a compound strength exercise targeting the pectoral muscles, with secondary emphasis on the shoulders and triceps. It requires a barbell and a bench, and involves lowering the barbell to the chest with a wide grip before pressing it back up.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0122.gif","youtube_id":null,"instructions":["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Grasp the barbell with a wide grip, slightly wider than shoulder-width apart.","Lift the barbell off the rack and hold it directly above your chest with your arms fully extended.","Lower the barbell slowly towards your chest, keeping your elbows slightly flared out.","Pause for a moment when the barbell touches your chest, then push it back up to the starting position.","Repeat for the desired number of repetitions."]},{"id":"123","name":"barbell wide-grip upright row","body_part":"shoulders","target":"delts","secondary_muscles":["traps","biceps"],"equipment":"barbell","difficulty":"intermediate","description":"The barbell wide-grip upright row is a compound exercise targeting the deltoids, with secondary emphasis on the traps and biceps. It involves lifting a barbell with a wide grip from the thighs to the upper chest, focusing on leading with the elbows.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0123.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, hands wider than shoulder-width apart.","Let the barbell hang in front of your thighs, arms fully extended.","Keeping your back straight, exhale and lift the barbell straight up towards your chin, leading with your elbows.","Pause for a moment at the top, then inhale and slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"124","name":"barbell wide squat","body_part":"upper legs","target":"quads","secondary_muscles":["glutes","hamstrings","calves"],"equipment":"barbell","difficulty":"intermediate","description":"The barbell wide squat is a compound lower body exercise that targets the quadriceps, with secondary emphasis on the glutes, hamstrings, and calves. It involves holding a barbell across the upper back and performing a squat with a wide stance.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0124.gif","youtube_id":null,"instructions":["Stand with your feet wider than shoulder-width apart, toes pointing slightly outward.","Hold the barbell across your upper back, resting it on your traps or rear delts.","Engage your core and keep your chest up as you lower your body down into a squat, pushing your hips back and bending your knees.","Lower until your thighs are parallel to the ground, or as low as you can comfortably go.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"125","name":"barbell wrist curl v. 2","body_part":"lower arms","target":"forearms","secondary_muscles":["biceps","brachialis"],"equipment":"barbell","difficulty":"beginner","description":"The barbell wrist curl v. 2 is an isolation exercise that targets the forearm muscles, specifically the wrist flexors. It is performed seated, with the forearms resting on the thighs and the wrists hanging off the edge, curling a barbell upward using only the wrists.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0125.gif","youtube_id":null,"instructions":["Sit on a bench with your feet flat on the ground and your knees bent.","Hold a barbell with an underhand grip, palms facing up, and your hands shoulder-width apart.","Rest your forearms on your thighs, allowing your wrists to hang off the edge.","Slowly curl your wrists upward, bringing the barbell towards your forearms.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1250","name":"weighted crunch (behind head)","body_part":"waist","target":"abs","secondary_muscles":["spine","delts"],"equipment":"weighted","difficulty":"intermediate","description":"Lie supine on a flat bench with knees bent and feet planted. Hold a small weight plate behind your head (not on the neck) and perform a controlled spinal curl to crunch up, then return slowly.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1250.gif","youtube_id":null,"instructions":["Lie on a flat bench with knees bent, feet flat, and lower back lightly pressed into the bench.","Grip a small plate with both hands and place it behind your head at the base of the skull; keep elbows slightly in and avoid pulling on the neck.","Brace your core and exhale as you curl your upper spine off the bench, bringing ribs toward pelvis; keep the chin gently tucked.","Pause briefly when shoulder blades are just off the bench, maintaining tension in the abs.","Inhale and lower your torso back down under control until shoulder blades touch, without relaxing the core.","Keep movement small and segmental (about 15–30° of spinal flexion), and use a load you can control without pulling with the arms."]},{"id":"1253","name":"lever donkey calf raise","body_part":"lower legs","target":"calves","secondary_muscles":["hamstrings","glutes"],"equipment":"leverage machine","difficulty":"beginner","description":"The lever donkey calf raise is a machine-based exercise targeting the calf muscles. It involves standing on a platform with your heels hanging off, then raising and lowering your heels to work the calves. The leverage machine provides resistance and support, making it a controlled movement.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1253.gif","youtube_id":null,"instructions":["Adjust the leverage machine to the appropriate height for your body.","Position yourself facing the machine, with your toes on the foot platform and your heels hanging off the edge.","Place your hands on the handles or the support bars for stability.","Engage your calves and lift your heels as high as possible, using the balls of your feet.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1254","name":"band bench press","body_part":"chest","target":"pectorals","secondary_muscles":["triceps","shoulders"],"equipment":"band","difficulty":"beginner","description":"The band bench press is a resistance exercise targeting the pectoral muscles using a resistance band. It mimics the traditional bench press but uses bands instead of weights, making it accessible and effective for building chest strength with less equipment.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1254.gif","youtube_id":null,"instructions":["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Grasp the band handles with an overhand grip, slightly wider than shoulder-width apart.","Extend your arms fully, pushing the bands away from your chest.","Slowly lower the bands back down to your chest, keeping your elbows at a 90-degree angle.","Repeat for the desired number of repetitions."]},{"id":"1255","name":"barbell decline pullover","body_part":"chest","target":"pectorals","secondary_muscles":["triceps","shoulders"],"equipment":"barbell","difficulty":"intermediate","description":"The barbell decline pullover is a chest exercise performed on a decline bench, targeting the pectorals with secondary emphasis on the triceps and shoulders. It involves lowering a barbell in an arc behind the head and returning to the starting position, requiring control and stability.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1255.gif","youtube_id":null,"instructions":["Lie down on a decline bench with your head lower than your hips and your feet secured.","Hold the barbell with a pronated grip (palms facing away from you) and your hands slightly wider than shoulder-width apart.","Extend your arms above your chest, keeping a slight bend in your elbows.","Lower the barbell in an arc motion behind your head, feeling a stretch in your chest and shoulders.","Pause for a moment, then return the barbell to the starting position by reversing the motion.","Repeat for the desired number of repetitions."]},{"id":"1256","name":"barbell reverse grip decline bench press","body_part":"chest","target":"pectorals","secondary_muscles":["triceps","shoulders"],"equipment":"barbell","difficulty":"advanced","description":"The barbell reverse grip decline bench press is a chest exercise performed on a decline bench using a barbell with a reverse (underhand) grip. This variation targets the lower chest and places additional emphasis on the triceps and shoulders.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1256.gif","youtube_id":null,"instructions":["Lie on a decline bench with your feet secured and your head lower than your hips.","Grasp the barbell with a reverse grip, slightly wider than shoulder-width apart.","Unrack the barbell and lower it slowly towards your chest, keeping your elbows tucked in.","Pause for a moment at the bottom, then push the barbell back up to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1257","name":"barbell reverse grip incline bench press","body_part":"chest","target":"pectorals","secondary_muscles":["triceps","shoulders"],"equipment":"barbell","difficulty":"advanced","description":"The barbell reverse grip incline bench press is a chest exercise performed on an incline bench using a barbell with a reverse (underhand) grip. This variation targets the upper chest and also involves the triceps and shoulders. It requires good technique and control to perform safely, especially due to the unusual grip and incline position.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1257.gif","youtube_id":null,"instructions":["Set up an incline bench at a 45-degree angle.","Lie down on the bench with your feet flat on the ground.","Grasp the barbell with a reverse grip, hands slightly wider than shoulder-width apart.","Unrack the barbell and lower it slowly towards your chest, keeping your elbows tucked in.","Pause for a moment when the barbell touches your chest.","Push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]},{"id":"1258","name":"barbell wide reverse grip bench press","body_part":"chest","target":"pectorals","secondary_muscles":["triceps","shoulders"],"equipment":"barbell","difficulty":"advanced","description":"The barbell wide reverse grip bench press is a chest exercise that targets the pectorals, with secondary emphasis on the triceps and shoulders. It involves lying on a bench and pressing a barbell with a wide, reverse (underhand) grip.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1258.gif","youtube_id":null,"instructions":["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Grasp the barbell with a wide reverse grip, slightly wider than shoulder-width apart.","Lift the barbell off the rack and hold it directly above your chest with your arms fully extended.","Lower the barbell slowly towards your chest, keeping your elbows tucked in and your wrists straight.","Pause for a moment when the barbell touches your chest, then push it back up to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1259","name":"behind head chest stretch","body_part":"chest","target":"pectorals","secondary_muscles":["shoulders","triceps"],"equipment":"assisted","difficulty":"beginner","description":"The behind head chest stretch is a flexibility exercise that targets the pectoral muscles. It is performed by standing tall, interlacing the fingers behind the head, and gently squeezing the shoulder blades together to stretch the chest.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1259.gif","youtube_id":null,"instructions":["Stand tall with your feet shoulder-width apart.","Interlace your fingers behind your head with your elbows pointing outwards.","Slowly squeeze your shoulder blades together and push your chest forward.","Hold the stretch for 15-30 seconds.","Release the stretch and repeat as desired."]},{"id":"126","name":"barbell wrist curl","body_part":"lower arms","target":"forearms","secondary_muscles":["biceps","brachialis"],"equipment":"barbell","difficulty":"beginner","description":"The barbell wrist curl is an isolation exercise targeting the forearm muscles, particularly the wrist flexors. It is performed seated, with the forearms resting on the thighs and the wrists curling a barbell upward.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0126.gif","youtube_id":null,"instructions":["Sit on a bench with your feet flat on the ground and your forearms resting on your thighs, holding a barbell with an underhand grip.","Allow the barbell to roll down to your fingertips, keeping your wrists straight.","Slowly curl the barbell up towards your forearms by flexing your wrists.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1260","name":"cable decline one arm press","body_part":"chest","target":"pectorals","secondary_muscles":["triceps","shoulders"],"equipment":"cable","difficulty":"intermediate","description":"The cable decline one arm press is a unilateral chest exercise performed on a cable machine, targeting the lower pectorals while also engaging the triceps and shoulders. It requires stabilization and control, especially due to the single-arm nature and the decline angle.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1260.gif","youtube_id":null,"instructions":["Adjust the cable machine to a decline position.","Stand facing away from the machine and grab the handle with one hand.","Position yourself with your back against the decline bench and your arm extended straight in front of you.","Bend your elbow and lower the handle towards your chest while keeping your upper arm stationary.","Pause for a moment at the bottom, then push the handle back up to the starting position.","Repeat for the desired number of repetitions, then switch arms."]},{"id":"1261","name":"cable decline press","body_part":"chest","target":"pectorals","secondary_muscles":["triceps","shoulders"],"equipment":"cable","difficulty":"intermediate","description":"The cable decline press is a chest exercise performed on a cable machine with a decline bench. It targets the lower portion of the pectoral muscles and also engages the triceps and shoulders. The movement involves pressing the handles away from the body in a decline position, providing constant tension through the range of motion.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1261.gif","youtube_id":null,"instructions":["Adjust the cable machine to a decline position.","Sit on the decline bench facing the cable machine.","Grasp the handles with an overhand grip and position them at chest level.","Keep your feet flat on the ground and your back firmly against the bench.","Exhale and push the handles away from your body, extending your arms fully.","Pause for a moment at the end of the movement, squeezing your chest muscles.","Inhale and slowly return the handles back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1262","name":"cable one arm decline chest fly","body_part":"chest","target":"pectorals","secondary_muscles":["shoulders","triceps"],"equipment":"cable","difficulty":"intermediate","description":"The cable one arm decline chest fly is an isolation exercise targeting the pectoral muscles using a cable machine and a decline bench. It emphasizes unilateral strength and control, helping to improve muscle symmetry and chest development.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1262.gif","youtube_id":null,"instructions":["Attach a D-handle to a low pulley cable machine and set the bench to a decline angle.","Lie down on the bench with your head towards the machine and grab the handle with your right hand.","Extend your arm straight up above your chest, keeping a slight bend in your elbow.","With a controlled motion, lower your arm out to the side until your hand is in line with your shoulder.","Pause for a moment, then reverse the motion and bring your arm back to the starting position.","Repeat for the desired number of repetitions, then switch to your left arm and repeat the exercise."]},{"id":"1263","name":"cable one arm fly on exercise ball","body_part":"chest","target":"pectorals","secondary_muscles":["deltoids","triceps"],"equipment":"cable","difficulty":"intermediate","description":"The cable one arm fly on exercise ball is a unilateral chest exercise performed while seated on an exercise ball, which adds a balance component to the traditional cable fly movement. It targets the pectorals while also engaging the deltoids and triceps, and requires core stability to maintain posture on the ball.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1263.gif","youtube_id":null,"instructions":["Sit on an exercise ball with your feet flat on the ground and your back straight.","Hold a cable handle in one hand and extend your arm out to the side, parallel to the ground.","Keep your elbow slightly bent and your palm facing forward.","Slowly bring your arm across your body, squeezing your chest muscles.","Pause for a moment at the end of the movement, then slowly return to the starting position.","Repeat for the desired number of repetitions, then switch sides."]},{"id":"1264","name":"cable one arm incline fly on exercise ball","body_part":"chest","target":"pectorals","secondary_muscles":["deltoids","triceps"],"equipment":"cable","difficulty":"advanced","description":"The cable one arm incline fly on exercise ball is a chest exercise performed using a cable machine and an exercise ball, targeting the pectorals while also engaging the deltoids and triceps. The exercise requires balance and coordination due to the unstable surface of the exercise ball and the unilateral movement.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1264.gif","youtube_id":null,"instructions":["Sit on an exercise ball with your feet flat on the ground and your back against an incline bench.","Hold a cable handle in one hand with your arm extended and palm facing inward.","Keeping a slight bend in your elbow, slowly lower your arm out to the side until your hand is in line with your shoulder.","Pause for a moment, then squeeze your chest muscles to bring your arm back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]},{"id":"1265","name":"cable one arm incline press","body_part":"chest","target":"pectorals","secondary_muscles":["deltoids","triceps"],"equipment":"cable","difficulty":"intermediate","description":"The cable one arm incline press is a unilateral chest exercise performed on an incline bench using a cable machine. It targets the pectoral muscles while also engaging the deltoids and triceps. This movement requires stability and coordination as you press the cable handle upward with one arm at a time.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1265.gif","youtube_id":null,"instructions":["Adjust the cable machine to a low pulley position.","Sit on an incline bench facing away from the cable machine.","Grasp the handle with one hand and bring it up to shoulder height.","Position your feet firmly on the ground and maintain a stable position.","Press the handle forward and upward, extending your arm fully.","Pause for a moment at the top, then slowly lower the handle back to the starting position.","Repeat for the desired number of repetitions, then switch sides."]},{"id":"1266","name":"cable one arm incline press on exercise ball","body_part":"chest","target":"pectorals","secondary_muscles":["shoulders","triceps"],"equipment":"cable","difficulty":"advanced","description":"The cable one arm incline press on exercise ball is a unilateral chest exercise performed on an unstable surface, targeting the pectorals while also engaging the shoulders and triceps. The use of the exercise ball increases the demand for balance and core stability.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1266.gif","youtube_id":null,"instructions":["Sit on an exercise ball with your feet flat on the ground and your back resting against an incline bench.","Hold a cable handle in one hand and position your arm at a 90-degree angle with your elbow bent.","Press the cable handle forward and upward, extending your arm fully.","Pause for a moment at the top, then slowly lower the cable handle back to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]},{"id":"1267","name":"cable one arm press on exercise ball","body_part":"chest","target":"pectorals","secondary_muscles":["shoulders","triceps"],"equipment":"cable","difficulty":"intermediate","description":"The cable one arm press on exercise ball is a unilateral chest exercise that also challenges core stability and balance by having the user sit on an unstable surface while pressing a cable handle forward.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1267.gif","youtube_id":null,"instructions":["Sit on an exercise ball with your feet flat on the ground and your back straight.","Hold a cable handle in one hand and position your arm at chest height, elbow bent.","Place your other hand on your hip for stability.","Press the cable handle forward, extending your arm fully.","Pause for a moment, then slowly return to the starting position.","Repeat for the desired number of repetitions, then switch arms."]},{"id":"1268","name":"cable press on exercise ball","body_part":"chest","target":"pectorals","secondary_muscles":["shoulders","triceps"],"equipment":"cable","difficulty":"intermediate","description":"The cable press on exercise ball is a chest exercise that also engages the shoulders and triceps. It is performed by sitting on an exercise ball, holding cable handles, and pressing them forward while maintaining balance and core stability.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1268.gif","youtube_id":null,"instructions":["Sit on an exercise ball with your feet flat on the ground and your knees at a 90-degree angle.","Hold the cable handles at chest height with your palms facing down and your elbows bent.","Engage your core and press the cable handles forward until your arms are fully extended.","Pause for a moment, then slowly release the tension and bring the cable handles back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1269","name":"cable standing up straight crossovers","body_part":"chest","target":"pectorals","secondary_muscles":["deltoids","triceps"],"equipment":"cable","difficulty":"intermediate","description":"Cable standing up straight crossovers are a chest exercise performed using a cable machine. The movement involves bringing the arms together in front of the body, crossing them over each other, which targets the pectoral muscles and also engages the deltoids and triceps.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1269.gif","youtube_id":null,"instructions":["Stand in the middle of a cable machine with your feet shoulder-width apart.","Hold the handles of the cables with your palms facing down and your arms extended straight out to the sides.","Keeping your arms straight, bring your hands together in front of your body, crossing them over each other.","Pause for a moment, then slowly return to the starting position, keeping your arms extended.","Repeat for the desired number of repetitions."]},{"id":"127","name":"barbell zercher squat","body_part":"upper legs","target":"glutes","secondary_muscles":["quadriceps","hamstrings","calves","core"],"equipment":"barbell","difficulty":"advanced","description":"The barbell Zercher squat is a lower body exercise where the barbell is held in the crooks of the elbows, emphasizing the glutes, quadriceps, hamstrings, calves, and core. It requires significant core stability, upper body strength, and proper squat mechanics.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0127.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and toes slightly turned out.","Hold the barbell in the crooks of your elbows, with your hands gripping the bar for stability.","Engage your core and keep your chest lifted as you lower your hips back and down into a squat position.","Keep your knees in line with your toes and your weight in your heels.","Pause for a moment at the bottom of the squat, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1270","name":"cable upper chest crossovers","body_part":"chest","target":"pectorals","secondary_muscles":["deltoids","triceps"],"equipment":"cable","difficulty":"intermediate","description":"Cable upper chest crossovers target the pectoral muscles using a cable machine, emphasizing the upper chest. The movement involves crossing the cables in front of the body, which also engages the deltoids and triceps.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1270.gif","youtube_id":null,"instructions":["Attach the handles to the cables at chest height.","Stand in the center of the cable machine with one foot slightly in front of the other.","Grasp the handles with your palms facing down and your arms extended out to the sides.","Keep a slight bend in your elbows and engage your core.","Pull the cables together in front of your chest, crossing them over each other.","Squeeze your chest muscles at the peak of the movement.","Slowly release the cables back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1271","name":"chest and front of shoulder stretch","body_part":"chest","target":"pectorals","secondary_muscles":["deltoids"],"equipment":"body weight","difficulty":"beginner","description":"A stretch targeting the chest and front of the shoulders, performed by crossing the arms in front of the body and pressing the palms together to open up the pectorals and deltoids.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1271.gif","youtube_id":null,"instructions":["Stand tall with your feet shoulder-width apart.","Extend your arms straight out in front of you at shoulder height.","Cross your arms in front of your body, with your right arm on top of your left arm.","Interlace your fingers and press your palms together.","Gently squeeze your shoulder blades together and push your hands forward, feeling a stretch in your chest and front of your shoulders.","Hold the stretch for 20-30 seconds, then release.","Repeat for the desired number of repetitions."]},{"id":"1272","name":"chest stretch with exercise ball","body_part":"chest","target":"pectorals","secondary_muscles":["shoulders","triceps"],"equipment":"stability ball","difficulty":"beginner","description":"A chest stretch performed using a stability ball to help open up the pectoral muscles, with some engagement of the shoulders and triceps. This exercise focuses on flexibility and mobility rather than strength or cardio.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1272.gif","youtube_id":null,"instructions":["Sit on the stability ball with your feet flat on the ground and your back straight.","Hold the exercise ball with both hands and extend your arms straight out in front of you.","Slowly bring the exercise ball towards your chest, feeling a stretch in your chest muscles.","Hold the stretch for a few seconds, then slowly return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1273","name":"clap push up","body_part":"chest","target":"pectorals","secondary_muscles":["triceps","shoulders"],"equipment":"body weight","difficulty":"advanced","description":"The clap push up is a plyometric bodyweight exercise that targets the pectorals, triceps, and shoulders. It involves an explosive push off the ground, clapping the hands in mid-air, and landing back in the push-up position. This movement requires significant upper body strength, power, and coordination.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1273.gif","youtube_id":null,"instructions":["Start in a high plank position with your hands slightly wider than shoulder-width apart.","Lower your body towards the ground by bending your elbows, keeping your core engaged.","Push through your palms explosively to propel your body off the ground.","While in mid-air, clap your hands together before landing back in the starting position.","Repeat for the desired number of repetitions."]},{"id":"1274","name":"deep push up","body_part":"chest","target":"pectorals","secondary_muscles":["triceps","shoulders"],"equipment":"dumbbell (used as handles for deeper range)","difficulty":"intermediate","description":"The deep push up is a variation of the traditional push up that increases the range of motion, targeting the pectorals more intensely and also engaging the triceps and shoulders.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1274.gif","youtube_id":null,"instructions":["Start in a high plank position with your hands slightly wider than shoulder-width apart and your body in a straight line.","Lower your chest towards the ground by bending your elbows, keeping them close to your body.","Push through your palms to extend your arms and return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1275","name":"drop push up","body_part":"chest","target":"pectorals","secondary_muscles":["triceps","shoulders"],"equipment":"body weight","difficulty":"beginner","description":"The drop push up is a bodyweight exercise that targets the pectorals and also works the triceps and shoulders. It involves lowering the chest towards the ground in a plank position, dropping the knees to the ground at the bottom, and then pushing back up.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1275.gif","youtube_id":null,"instructions":["Start in a high plank position with your hands slightly wider than shoulder-width apart.","Lower your chest towards the ground, keeping your elbows close to your body.","Once your chest is just above the ground, quickly drop your knees to the ground.","Push yourself back up to the starting position by extending your arms.","Repeat for the desired number of repetitions."]},{"id":"1276","name":"dumbbell decline one arm fly","body_part":"chest","target":"pectorals","secondary_muscles":["shoulders"],"equipment":"dumbbell","difficulty":"advanced","description":"The dumbbell decline one arm fly is a unilateral chest exercise performed on a decline bench, targeting the pectoral muscles and also engaging the shoulders. It requires good control and stability to perform safely, especially due to the decline angle and single-arm movement.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1276.gif","youtube_id":null,"instructions":["Lie down on a decline bench with a dumbbell in one hand, resting it on your thigh.","Using your thigh to help raise the dumbbell, lift it up to shoulder width with your palm facing your torso.","Rotate your wrist so that the palm of your hand is facing forward.","As you breathe in, lower the dumbbell slowly to the side until you feel a stretch in your chest.","Exhale and use your chest muscles to bring the dumbbell back up to the starting position.","Repeat for the desired number of repetitions, then switch arms."]},{"id":"1277","name":"dumbbell fly on exercise ball","body_part":"chest","target":"pectorals","secondary_muscles":["shoulders","triceps"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell fly on exercise ball is a chest exercise that also challenges your core and stability by performing the movement on an unstable surface. It targets the pectorals, with secondary emphasis on the shoulders and triceps.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1277.gif","youtube_id":null,"instructions":["Sit on an exercise ball and hold a dumbbell in each hand.","Walk your feet forward and roll your body down until your head, neck, and upper back are supported by the ball.","Extend your arms straight up above your chest, palms facing each other.","Bend your elbows slightly and lower your arms out to the sides in a wide arc until you feel a stretch in your chest.","Pause for a moment, then reverse the movement and squeeze your chest muscles as you bring the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1278","name":"dumbbell incline fly on exercise ball","body_part":"chest","target":"pectorals","secondary_muscles":["shoulders"],"equipment":"dumbbell, exercise ball","difficulty":"intermediate","description":"The dumbbell incline fly on exercise ball is a chest exercise that targets the pectorals while also engaging the shoulders and core for stability. It is performed by lying back on an exercise ball with dumbbells and performing a fly motion.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1278.gif","youtube_id":null,"instructions":["Set up an incline bench at a 45-degree angle.","Sit on an exercise ball and roll forward until your upper back is resting on the incline bench.","Hold a dumbbell in each hand with your palms facing each other and your arms extended above your chest.","Lower the dumbbells out to the sides in a wide arc until you feel a stretch in your chest.","Pause for a moment, then squeeze your chest muscles to bring the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1279","name":"dumbbell incline one arm fly","body_part":"chest","target":"pectorals","secondary_muscles":["deltoids","triceps"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell incline one arm fly is a unilateral chest exercise performed on an incline bench. It targets the pectoral muscles and also engages the deltoids and triceps. The movement requires control and stability, as only one arm is working at a time, increasing the demand on core and shoulder stabilizers.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1279.gif","youtube_id":null,"instructions":["Adjust the incline bench to a 30-45 degree angle.","Sit on the bench with a dumbbell in one hand, resting it on your thigh.","Lie back on the bench, keeping your feet flat on the ground.","Hold the dumbbell with your arm extended straight up over your chest.","Lower the dumbbell out to the side in a wide arc, keeping a slight bend in your elbow.","Pause when your arm is parallel to the ground, then reverse the motion to bring the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]},{"id":"128","name":"battling ropes","body_part":"shoulders","target":"delts","secondary_muscles":["forearms","core"],"equipment":"rope","difficulty":"intermediate","description":"Battling ropes is a dynamic exercise that targets the deltoids while also engaging the forearms and core. It involves making rapid, alternating waves with heavy ropes, providing both a strength and cardiovascular challenge.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0128.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and knees slightly bent.","Hold one end of the rope in each hand, with your palms facing each other.","Raise your arms to shoulder height, keeping your elbows slightly bent.","Begin making alternating waves with the ropes by rapidly raising and lowering each arm.","Continue for the desired duration or number of repetitions."]},{"id":"1280","name":"dumbbell incline one arm fly on exercise ball","body_part":"chest","target":"pectorals","secondary_muscles":["shoulders"],"equipment":"dumbbell","difficulty":"advanced","description":"The dumbbell incline one arm fly on exercise ball is a chest exercise that also challenges stability and balance by using an exercise ball. It targets the pectorals and also engages the shoulders and core for stabilization.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1280.gif","youtube_id":null,"instructions":["Sit on an exercise ball with a dumbbell in one hand.","Walk your feet forward and roll your body down until your head, neck, and upper back are supported on the ball.","Hold the dumbbell with your arm extended straight up over your chest, palm facing inwards.","Slowly lower the dumbbell out to the side, keeping a slight bend in your elbow.","Pause for a moment when your arm is parallel to the ground.","Engage your chest muscles to bring the dumbbell back up to the starting position.","Repeat for the desired number of repetitions, then switch arms."]},{"id":"1281","name":"dumbbell incline one arm press","body_part":"chest","target":"pectorals","secondary_muscles":["shoulders","triceps"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell incline one arm press is a unilateral chest exercise performed on an incline bench, targeting the upper pectorals while also engaging the shoulders and triceps. It requires balance and coordination due to the single-arm movement.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1281.gif","youtube_id":null,"instructions":["Sit on an incline bench with a dumbbell in one hand, resting on your thigh.","Lie back on the bench and position the dumbbell at shoulder level, palm facing forward.","Press the dumbbell upward and slightly inward, extending your arm fully.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]},{"id":"1282","name":"dumbbell incline one arm press on exercise ball","body_part":"chest","target":"pectorals","secondary_muscles":["shoulders","triceps"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell incline one arm press on exercise ball is a chest exercise that also engages the shoulders and triceps. It requires balance and core stability due to the use of an exercise ball and the unilateral pressing movement.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1282.gif","youtube_id":null,"instructions":["Sit on an exercise ball with a dumbbell in one hand, feet flat on the ground.","Slowly walk your feet forward, rolling the ball until your head, neck, and upper back are supported on the ball.","Hold the dumbbell at shoulder height with your palm facing forward.","Press the dumbbell upward until your arm is fully extended.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]},{"id":"1283","name":"dumbbell incline press on exercise ball","body_part":"chest","target":"pectorals","secondary_muscles":["shoulders","triceps"],"equipment":"dumbbell, exercise ball","difficulty":"intermediate","description":"The dumbbell incline press on exercise ball is a chest exercise that also engages the shoulders and triceps. Performing this movement on an exercise ball increases the demand for balance and core stability compared to a traditional incline press on a bench.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1283.gif","youtube_id":null,"instructions":["Sit on an exercise ball with a dumbbell in each hand, palms facing forward.","Slowly walk your feet forward, rolling your body down the ball until your head, neck, and upper back are supported on the ball.","Hold the dumbbells at shoulder level, elbows bent and pointing out to the sides.","Press the dumbbells upward, extending your arms fully.","Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1284","name":"dumbbell lying pullover on exercise ball","body_part":"chest","target":"pectorals","secondary_muscles":["triceps","shoulders","back"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell lying pullover on exercise ball is a chest exercise that also engages the triceps, shoulders, and back. It requires balance and stability due to the use of the exercise ball, making it more challenging than the standard pullover.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1284.gif","youtube_id":null,"instructions":["Sit on an exercise ball and roll forward until your upper back is resting on the ball.","Hold a dumbbell with both hands and extend your arms straight up over your chest.","Slowly lower the dumbbell behind your head while keeping your arms straight.","Pause for a moment, then raise the dumbbell back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1285","name":"dumbbell one arm bench fly","body_part":"chest","target":"pectorals","secondary_muscles":["shoulders"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell one arm bench fly is a unilateral chest exercise that targets the pectoral muscles and also engages the shoulders. It requires balance and control to stabilize the weight with one arm while lying on a bench.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1285.gif","youtube_id":null,"instructions":["Sit on a flat bench with a dumbbell in one hand, resting it on top of your thigh.","Lie back on the bench, keeping the dumbbell pressed against your thigh.","Using your free hand, help lift the dumbbell up to the starting position.","Hold the dumbbell directly above your shoulder with your arm extended and palm facing inward.","Lower the dumbbell out to the side in a wide arc, keeping a slight bend in your elbow.","Pause when your arm is parallel to the ground, then reverse the movement and bring the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms and repeat."]},{"id":"1286","name":"dumbbell one arm chest fly on exercise ball","body_part":"chest","target":"pectorals","secondary_muscles":["shoulders","triceps"],"equipment":"dumbbell","difficulty":"advanced","description":"The dumbbell one arm chest fly on exercise ball is a unilateral chest exercise that also challenges core stability and balance by using an exercise ball as the base of support. It targets the pectoral muscles and also works the shoulders and triceps.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1286.gif","youtube_id":null,"instructions":["Sit on an exercise ball with a dumbbell in one hand and your feet flat on the ground.","Walk your feet forward, rolling the ball until your upper back is supported on the ball and your head, neck, and shoulders are off the ball.","Extend your arm with the dumbbell straight up above your chest, palm facing inward.","Slowly lower the dumbbell out to the side, keeping a slight bend in your elbow.","Pause for a moment when your arm is parallel to the ground.","Engage your chest muscles to bring the dumbbell back up to the starting position.","Repeat for the desired number of repetitions, then switch arms."]},{"id":"1287","name":"dumbbell one arm decline chest press","body_part":"chest","target":"pectorals","secondary_muscles":["triceps","shoulders"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell one arm decline chest press is a unilateral chest exercise performed on a decline bench, targeting the pectorals while also engaging the triceps and shoulders. It requires good stability and control due to the single-arm movement and the decline angle.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1287.gif","youtube_id":null,"instructions":["Lie on a decline bench with a dumbbell in one hand, resting on your chest.","Place your feet flat on the ground and keep your back pressed against the bench.","Extend your arm and push the dumbbell up towards the ceiling, fully extending your elbow.","Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]},{"id":"1288","name":"dumbbell one arm fly on exercise ball","body_part":"chest","target":"pectorals","secondary_muscles":["shoulders","triceps"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell one arm fly on exercise ball is a chest exercise that also challenges balance and core stability. It involves performing a single-arm fly movement while lying with your upper back on an exercise ball, which increases the demand on stabilizing muscles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1288.gif","youtube_id":null,"instructions":["Sit on an exercise ball with a dumbbell in one hand and your feet flat on the ground.","Walk your feet forward and roll your body down until your upper back is resting on the exercise ball.","Extend your arm with the dumbbell straight up above your chest, palm facing inwards.","Slowly lower the dumbbell out to the side, keeping a slight bend in your elbow.","Pause for a moment, then squeeze your chest muscles to bring the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]},{"id":"1289","name":"dumbbell one arm incline chest press","body_part":"chest","target":"pectorals","secondary_muscles":["shoulders","triceps"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell one arm incline chest press is a unilateral upper body exercise that targets the pectoral muscles, with secondary emphasis on the shoulders and triceps. It is performed on an incline bench using a single dumbbell, which increases the demand for core stability and coordination.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1289.gif","youtube_id":null,"instructions":["Adjust the incline bench to a 45-degree angle.","Sit on the bench with your back against the pad and feet flat on the ground.","Hold a dumbbell in one hand with an overhand grip, resting it on your shoulder.","Push the dumbbell up and away from your body, extending your arm fully.","Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]},{"id":"129","name":"bench dip (knees bent)","body_part":"upper arms","target":"triceps","secondary_muscles":["chest","shoulders"],"equipment":"body weight","difficulty":"beginner","description":"The bench dip (knees bent) is a bodyweight exercise that primarily targets the triceps, with secondary emphasis on the chest and shoulders. It is performed using a bench or chair and is suitable for building upper arm strength.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0129.gif","youtube_id":null,"instructions":["Sit on the edge of a bench or chair with your hands gripping the edge next to your hips.","Slide your butt off the bench and straighten your legs in front of you, keeping your heels on the ground.","Bend your elbows and lower your body towards the ground, keeping your back close to the bench.","Pause for a moment at the bottom, then push yourself back up to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1290","name":"dumbbell one arm press on exercise ball","body_part":"chest","target":"pectorals","secondary_muscles":["shoulders","triceps","core"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell one arm press on exercise ball is a unilateral chest exercise that also challenges your core and balance by performing the movement on an unstable surface. It targets the pectorals while also engaging the shoulders, triceps, and core muscles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1290.gif","youtube_id":null,"instructions":["Sit on an exercise ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Hold a dumbbell in one hand and position it at shoulder height, with your elbow bent and palm facing forward.","Slowly press the dumbbell upward until your arm is fully extended, while keeping your core engaged and maintaining balance on the exercise ball.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]},{"id":"1291","name":"dumbbell one arm pullover on exercise ball","body_part":"chest","target":"pectorals","secondary_muscles":["triceps","latissimus dorsi","rhomboids"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell one arm pullover on exercise ball is a chest exercise that also engages the triceps, latissimus dorsi, and rhomboids. It requires balance and core stability due to the use of the exercise ball, as well as unilateral strength and coordination.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1291.gif","youtube_id":null,"instructions":["Sit on an exercise ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Hold a dumbbell with one hand and extend your arm straight up above your chest.","Slowly lower the dumbbell behind your head while keeping your arm straight.","Pause for a moment, then raise the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]},{"id":"1292","name":"dumbbell one leg fly on exercise ball","body_part":"chest","target":"pectorals","secondary_muscles":["shoulders","triceps"],"equipment":"dumbbell, exercise ball","difficulty":"advanced","description":"The dumbbell one leg fly on exercise ball is a chest exercise that also challenges balance and core stability. It involves performing a dumbbell fly while balancing on one leg on an exercise ball, targeting the pectorals with secondary emphasis on shoulders and triceps.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1292.gif","youtube_id":null,"instructions":["Sit on an exercise ball with a dumbbell in each hand, palms facing each other.","Place one foot on the ground and extend the other leg straight out in front of you.","Lean forward slightly and bring your arms out to the sides, keeping a slight bend in your elbows.","Slowly lower the dumbbells down and out to the sides, feeling a stretch in your chest.","Pause for a moment at the bottom, then squeeze your chest muscles to bring the dumbbells back up to the starting position.","Repeat for the desired number of repetitions, then switch legs and repeat."]},{"id":"1293","name":"dumbbell press on exercise ball","body_part":"chest","target":"pectorals","secondary_muscles":["shoulders","triceps"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell press on exercise ball is a chest exercise that also engages the shoulders and triceps, performed while balancing on an exercise ball to increase core activation and stability demands.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1293.gif","youtube_id":null,"instructions":["Sit on an exercise ball with your feet flat on the ground and dumbbells in each hand, resting on your thighs.","Slowly walk your feet forward, rolling the exercise ball until your lower back is supported on the ball and your knees are at a 90-degree angle.","Raise the dumbbells to shoulder height, palms facing forward.","Press the dumbbells upward until your arms are fully extended.","Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1294","name":"dumbbell pullover hip extension on exercise ball","body_part":"chest","target":"pectorals","secondary_muscles":["triceps","shoulders","core"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell pullover hip extension on exercise ball is a compound exercise that targets the pectorals while also engaging the triceps, shoulders, and core. It combines a pullover movement with a hip extension, performed on an unstable surface (exercise ball), which increases the demand for balance and coordination.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1294.gif","youtube_id":null,"instructions":["Sit on an exercise ball with your feet flat on the ground and the dumbbell resting on your thighs.","Slowly walk your feet forward, rolling the exercise ball down your back until your head, neck, and upper back are supported on the ball.","Hold the dumbbell with both hands and extend your arms straight up over your chest, keeping a slight bend in your elbows.","Lower the dumbbell behind your head, keeping your arms straight and maintaining control.","Pause for a moment, then raise the dumbbell back to the starting position.","While keeping your arms extended, lift your hips off the ground, squeezing your glutes and engaging your core.","Lower your hips back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1295","name":"dumbbell pullover on exercise ball","body_part":"chest","target":"pectorals","secondary_muscles":["triceps","latissimus dorsi"],"equipment":"dumbbell, exercise ball","difficulty":"intermediate","description":"The dumbbell pullover on exercise ball is a chest exercise that also engages the triceps and latissimus dorsi. It is performed by lying on an exercise ball, holding a dumbbell above the chest, and lowering it behind the head before returning to the starting position.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1295.gif","youtube_id":null,"instructions":["Sit on an exercise ball and hold a dumbbell with both hands above your chest, arms extended.","Slowly lower the dumbbell behind your head while keeping your arms straight.","Pause for a moment, then raise the dumbbell back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1296","name":"exercise ball pike push up","body_part":"chest","target":"pectorals","secondary_muscles":["shoulders","triceps","core"],"equipment":"stability ball","difficulty":"advanced","description":"The exercise ball pike push up is a challenging upper body and core exercise that combines a pike movement with a push-up, performed with the shins on a stability ball. This exercise targets the pectorals while also engaging the shoulders, triceps, and core for stabilization and strength.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1296.gif","youtube_id":null,"instructions":["Start in a push-up position with your hands on the floor and your shins resting on the stability ball.","Engage your core and lift your hips up towards the ceiling, rolling the ball towards your hands.","Keep your legs straight and your body in a pike position, forming an inverted V shape.","Bend your elbows and lower your upper body towards the floor, keeping your head in line with your hands.","Push through your hands and extend your arms to return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1297","name":"isometric chest squeeze","body_part":"chest","target":"pectorals","secondary_muscles":["triceps","shoulders"],"equipment":"body weight","difficulty":"beginner","description":"The isometric chest squeeze is a bodyweight exercise that targets the pectoral muscles by requiring you to contract and hold tension in your chest while your arms are extended in front of you.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1297.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and your knees slightly bent.","Extend your arms straight out in front of you, parallel to the ground, with your palms facing each other.","Squeeze your chest muscles together as hard as you can, while keeping your arms straight.","Hold this position for a few seconds, focusing on contracting your chest muscles.","Release the squeeze and relax your chest muscles.","Repeat for the desired number of repetitions."]},{"id":"1298","name":"kettlebell one arm floor press","body_part":"chest","target":"pectorals","secondary_muscles":["triceps","shoulders"],"equipment":"kettlebell","difficulty":"intermediate","description":"The kettlebell one arm floor press is a unilateral chest exercise performed lying on the floor, pressing a kettlebell with one arm at a time. It targets the pectorals while also engaging the triceps and shoulders, and requires stability and control.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1298.gif","youtube_id":null,"instructions":["Lie flat on your back on the floor with your knees bent and feet flat on the ground.","Hold the kettlebell in one hand with your palm facing towards your feet and your arm extended straight up towards the ceiling.","Slowly lower the kettlebell towards your chest by bending your elbow, keeping your upper arm close to your body.","Pause for a moment when the kettlebell is just above your chest, then push it back up to the starting position by extending your elbow.","Repeat for the desired number of repetitions, then switch to the other arm."]},{"id":"1299","name":"lever incline chest press","body_part":"chest","target":"pectorals","secondary_muscles":["shoulders","triceps"],"equipment":"leverage machine","difficulty":"beginner","description":"The lever incline chest press is a machine-based exercise targeting the upper chest (pectorals), with secondary emphasis on the shoulders and triceps. It is performed on a leverage machine, providing guided movement for safety and stability.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1299.gif","youtube_id":null,"instructions":["Adjust the seat and backrest of the leverage machine to a comfortable position.","Sit on the machine with your back against the backrest and your feet flat on the floor.","Grasp the handles with an overhand grip and position your hands slightly wider than shoulder-width apart.","Push the handles forward and away from your body until your arms are fully extended.","Pause for a moment, then slowly bend your elbows and lower the handles back towards your chest.","Repeat for the desired number of repetitions."]},{"id":"13","name":"assisted lying leg raise with throw down","body_part":"waist","target":"abs","secondary_muscles":["hip flexors","quadriceps"],"equipment":"assisted","difficulty":"intermediate","description":"The assisted lying leg raise with throw down is an abdominal exercise that targets the abs while also engaging the hip flexors and quadriceps. The movement involves raising the legs while lying on your back, then forcefully lowering them (throwing them down) and raising them again, often with a partner providing resistance or assistance.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0013.gif","youtube_id":null,"instructions":["Lie flat on your back with your legs extended and your arms by your sides.","Place your hands under your glutes for support.","Engage your core and lift your legs off the ground, keeping them straight.","Raise your legs until they are perpendicular to the ground.","Lower your legs back down to the starting position.","Simultaneously, throw your legs down towards the ground, keeping them straight.","Raise your legs back up to the starting position.","Repeat for the desired number of repetitions."]},{"id":"130","name":"bench hip extension","body_part":"upper legs","target":"glutes","secondary_muscles":["hamstrings"],"equipment":"body weight","difficulty":"beginner","description":"The bench hip extension is a bodyweight exercise targeting the glutes and hamstrings. It involves lifting the hips off a bench to form a straight line from knees to shoulders, emphasizing glute activation and hip extension strength.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0130.gif","youtube_id":null,"instructions":["Sit on a bench with your back against the bench and your feet flat on the ground.","Place your hands on the bench for support.","Engage your glutes and hamstrings, then lift your hips off the bench until your body forms a straight line from your knees to your shoulders.","Pause for a moment at the top, then slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1300","name":"lever decline chest press","body_part":"chest","target":"pectorals","secondary_muscles":["triceps","shoulders"],"equipment":"leverage machine","difficulty":"beginner","description":"The lever decline chest press is a machine-based exercise targeting the pectoral muscles, with secondary emphasis on the triceps and shoulders. It is performed on a leverage machine, providing guided movement for safety and stability.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1300.gif","youtube_id":null,"instructions":["Adjust the seat height and backrest of the leverage machine to a comfortable position.","Sit on the machine with your back against the backrest and your feet flat on the floor.","Grasp the handles with an overhand grip and position your hands slightly wider than shoulder-width apart.","Push the handles forward and away from your body until your arms are fully extended.","Slowly lower the handles back towards your chest, keeping your elbows slightly bent.","Pause for a moment at the bottom, then push the handles back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1301","name":"machine inner chest press","body_part":"chest","target":"pectorals","secondary_muscles":["triceps","shoulders"],"equipment":"leverage machine","difficulty":"beginner","description":"The machine inner chest press is a chest-focused exercise performed on a leverage machine. It targets the pectoral muscles and also works the triceps and shoulders. The machine provides stability and guided movement, making it accessible for most users.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1301.gif","youtube_id":null,"instructions":["Adjust the seat height and position yourself on the machine with your back flat against the pad.","Grasp the handles with an overhand grip and position your elbows at a 90-degree angle.","Push the handles forward until your arms are fully extended, exhaling during the movement.","Pause for a moment at the end of the movement, then slowly return to the starting position, inhaling as you do so.","Repeat for the desired number of repetitions."]},{"id":"1302","name":"medicine ball chest pass","body_part":"chest","target":"pectorals","secondary_muscles":["shoulders","triceps"],"equipment":"medicine ball","difficulty":"beginner","description":"The medicine ball chest pass is an explosive upper body exercise that targets the pectorals, shoulders, and triceps. It involves forcefully passing a medicine ball from the chest, often against a wall or to a partner, and catching it on the rebound.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1302.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, holding the medicine ball at chest level.","Extend your arms forward, pushing the medicine ball away from your chest with force.","As you release the ball, follow through with your arms and torso, transferring your weight from your back foot to your front foot.","Catch the ball as it rebounds off the wall or partner, and immediately repeat the movement.","Continue for the desired number of repetitions."]},{"id":"1303","name":"medicine ball chest push from 3 point stance","body_part":"chest","target":"pectorals","secondary_muscles":["shoulders","triceps"],"equipment":"medicine ball","difficulty":"intermediate","description":"The medicine ball chest push from a 3 point stance is a dynamic exercise targeting the pectoral muscles, with additional engagement of the shoulders and triceps. It involves starting in a 3 point stance, lowering the chest towards the ground, and explosively pushing the medicine ball away from the body.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1303.gif","youtube_id":null,"instructions":["Start in a 3 point stance with one hand on the medicine ball and the other hand on the ground.","Extend your legs and position your body in a straight line.","Lower your chest towards the ground while keeping your back straight.","Push the medicine ball away from your body, extending your arm fully.","Return to the starting position and repeat for the desired number of repetitions."]},{"id":"1304","name":"medicine ball chest push multiple response","body_part":"chest","target":"pectorals","secondary_muscles":["triceps","shoulders"],"equipment":"medicine ball","difficulty":"beginner","description":"A chest-focused exercise using a medicine ball to develop pressing strength and coordination. The movement involves pushing the medicine ball away from the chest and returning it, engaging the pectorals, triceps, and shoulders.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1304.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, holding a medicine ball at chest level.","Extend your arms forward, pushing the medicine ball away from your chest.","Pause for a moment, then slowly bring the medicine ball back to your chest.","Repeat for the desired number of repetitions."]},{"id":"1305","name":"medicine ball chest push single response","body_part":"chest","target":"pectorals","secondary_muscles":["triceps","shoulders"],"equipment":"medicine ball","difficulty":"beginner","description":"The medicine ball chest push single response is an exercise that targets the pectoral muscles by pushing a medicine ball away from the chest, engaging the triceps and shoulders as secondary muscles. It is performed standing and requires coordination and strength to execute the movement effectively.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1305.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, holding the medicine ball at chest level.","Extend your arms forward, pushing the medicine ball away from your chest.","Pause for a moment, then slowly bring the medicine ball back to your chest.","Repeat for the desired number of repetitions."]},{"id":"1306","name":"plyo push up","body_part":"chest","target":"pectorals","secondary_muscles":["triceps","shoulders","core"],"equipment":"body weight","difficulty":"advanced","description":"The plyo push up is an explosive bodyweight exercise that targets the pectoral muscles and also works the triceps, shoulders, and core. It involves pushing off the ground with enough force for your hands to leave the floor, requiring power, coordination, and upper body strength.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1306.gif","youtube_id":null,"instructions":["Start in a high plank position with your hands slightly wider than shoulder-width apart.","Lower your chest towards the ground by bending your elbows, keeping your body in a straight line.","Push explosively off the ground, using your chest muscles to propel your upper body off the ground.","Land softly with your hands back in the starting position.","Repeat for the desired number of repetitions."]},{"id":"1307","name":"push up on bosu ball","body_part":"chest","target":"pectorals","secondary_muscles":["triceps","shoulders","core"],"equipment":"bosu ball","difficulty":"intermediate","description":"A push-up variation performed with hands on a BOSU ball (flat side up), increasing instability and core engagement.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1307.gif","youtube_id":null,"instructions":["Place the bosu ball on the ground with the flat side facing up.","Position yourself in a push-up position with your hands on the outer edges of the bosu ball.","Engage your core and lower your body down towards the bosu ball by bending your elbows.","Push yourself back up to the starting position by extending your arms.","Repeat for the desired number of repetitions."]},{"id":"1308","name":"smith wide grip bench press","body_part":"chest","target":"pectorals","secondary_muscles":["triceps","shoulders"],"equipment":"smith machine","difficulty":"beginner","description":"The smith wide grip bench press is a chest exercise performed on a smith machine with a wide grip to target the pectoral muscles. It also engages the triceps and shoulders as secondary muscles. The smith machine provides stability, making it accessible to those with less experience, but proper form and control are still required.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1308.gif","youtube_id":null,"instructions":["Adjust the bench to a comfortable position on the smith machine.","Lie down on the bench with your feet flat on the ground.","Grasp the barbell with a wide grip, slightly wider than shoulder-width apart.","Unrack the barbell and lower it slowly towards your chest, keeping your elbows out to the sides.","Pause for a moment when the barbell touches your chest.","Push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]},{"id":"1309","name":"smith wide grip decline bench press","body_part":"chest","target":"pectorals","secondary_muscles":["triceps","shoulders"],"equipment":"smith machine","difficulty":"intermediate","description":"The smith wide grip decline bench press is a chest exercise performed on a smith machine with a wide grip, targeting the lower pectorals and also engaging the triceps and shoulders. The decline angle and wide grip emphasize the lower chest and require good control and technique.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1309.gif","youtube_id":null,"instructions":["Adjust the decline bench to the desired angle.","Lie down on the bench with your feet secured under the foot pads.","Grasp the barbell with a wide grip, slightly wider than shoulder-width apart.","Unrack the barbell and lower it slowly towards your chest, keeping your elbows pointed outwards.","Pause for a moment when the barbell touches your chest.","Push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]},{"id":"1310","name":"weighted drop push up","body_part":"chest","target":"pectorals","secondary_muscles":["triceps","shoulders"],"equipment":"weighted","difficulty":"advanced","description":"The weighted drop push up is an advanced plyometric chest exercise that involves explosive push-ups with alternating hand positions, performed with added weight for increased resistance. This movement challenges strength, power, coordination, and control, making it suitable for experienced individuals.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1310.gif","youtube_id":null,"instructions":["Start in a high plank position with your hands slightly wider than shoulder-width apart and your feet together.","Lower your chest towards the ground, keeping your elbows close to your body.","Once your chest is just above the ground, explosively push yourself up, lifting your hands off the ground.","As you push up, quickly move your hands out to the sides and slightly forward, allowing your body to drop down towards the ground.","Catch yourself with your hands in the wider position and immediately lower your chest towards the ground again.","Repeat the push-up motion, dropping down and catching yourself with your hands in the narrower position.","Continue alternating between the wider and narrower hand positions for the desired number of repetitions."]},{"id":"1311","name":"wide hand push up","body_part":"chest","target":"pectorals","secondary_muscles":["triceps","shoulders"],"equipment":"body weight","difficulty":"intermediate","description":"The wide hand push up is a bodyweight exercise that targets the pectoral muscles by increasing the distance between the hands, placing more emphasis on the chest compared to a standard push up. It also engages the triceps and shoulders as secondary muscles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1311.gif","youtube_id":null,"instructions":["Start in a high plank position with your hands wider than shoulder-width apart.","Keep your body in a straight line from head to toe.","Lower your chest towards the ground by bending your elbows, keeping them close to your sides.","Push through your palms to extend your arms and return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1312","name":"medicine ball chest push with run release","body_part":"chest","target":"pectorals","secondary_muscles":["triceps","shoulders","core"],"equipment":"medicine ball","difficulty":"intermediate","description":"A dynamic exercise that combines a chest push with a running release and catch, targeting the pectorals while also engaging the triceps, shoulders, and core. This movement requires coordination, explosive power, and agility.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1312.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, holding a medicine ball at chest level.","Step forward with your right foot and simultaneously push the medicine ball forward, extending your arms fully.","As you push the ball forward, release it and let it roll forward.","Quickly run forward and catch the ball before it hits the ground.","Once you catch the ball, bring it back to your chest and repeat the movement with your left foot forward.","Continue alternating legs and repeating the exercise for the desired number of repetitions."]},{"id":"1313","name":"lever unilateral row","body_part":"back","target":"upper back","secondary_muscles":["biceps","forearms"],"equipment":"leverage machine","difficulty":"beginner","description":"The lever unilateral row is a machine-based exercise targeting the upper back. It involves pulling a lever arm with one side of the body at a time, focusing on the upper back muscles while also engaging the biceps and forearms. This exercise is performed on a leverage machine, providing stability and controlled resistance.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1313.gif","youtube_id":null,"instructions":["Adjust the seat height and position yourself facing the machine.","Grasp the handles with an overhand grip and keep your back straight.","Pull the handles towards your body, squeezing your shoulder blades together.","Pause for a moment at the peak of the movement, then slowly release and extend your arms back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1314","name":"back extension on exercise ball","body_part":"back","target":"spine","secondary_muscles":["glutes","hamstrings"],"equipment":"stability ball","difficulty":"intermediate","description":"The back extension on an exercise ball is a bodyweight exercise that targets the spinal erectors and helps strengthen the lower back. It also engages the glutes and hamstrings as secondary muscles. The use of a stability ball requires core engagement and balance, making it more challenging than a standard floor back extension.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1314.gif","youtube_id":null,"instructions":["Place the stability ball on the ground and lie face down on top of it, with your hips resting on the ball and your feet against a wall or other stable surface.","Position your hands behind your head or crossed over your chest.","Engage your core and slowly lift your upper body off the ball, extending your back until your body forms a straight line from your head to your heels.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1316","name":"barbell bent arm pullover","body_part":"back","target":"lats","secondary_muscles":["triceps","chest"],"equipment":"barbell","difficulty":"intermediate","description":"The barbell bent arm pullover is a compound exercise that targets the lats, with secondary emphasis on the triceps and chest. It involves lying on a bench and moving a barbell in an arc over and behind the head, requiring control and strength.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1316.gif","youtube_id":null,"instructions":["Lie flat on a bench with your head at one end and your feet on the floor.","Hold a barbell with a shoulder-width grip and extend your arms straight above your chest.","Lower the barbell behind your head while keeping your arms slightly bent.","Pause for a moment, then raise the barbell back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1317","name":"barbell reverse grip incline bench row","body_part":"back","target":"upper back","secondary_muscles":["biceps","forearms"],"equipment":"barbell","difficulty":"intermediate","description":"The barbell reverse grip incline bench row targets the upper back and also engages the biceps and forearms. It is performed on an incline bench with a reverse grip on the barbell, focusing on pulling the weight towards the upper abdomen while maintaining a strong, stable posture.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1317.gif","youtube_id":null,"instructions":["Set up an incline bench at a 45-degree angle.","Sit on the bench facing the backrest with your chest against it.","Grab the barbell with a reverse grip (palms facing down) and hands slightly wider than shoulder-width apart.","Keep your back straight and core engaged.","Pull the barbell towards your upper abdomen, squeezing your shoulder blades together.","Pause for a moment at the top of the movement.","Slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1318","name":"cable incline bench row","body_part":"back","target":"upper back","secondary_muscles":["biceps","rear deltoids"],"equipment":"cable","difficulty":"intermediate","description":"The cable incline bench row is a strength exercise targeting the upper back, performed using a cable machine and an incline bench. It also engages the biceps and rear deltoids as secondary muscles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1318.gif","youtube_id":null,"instructions":["Set up an incline bench at a 45-degree angle and attach a cable handle to the low pulley.","Sit on the bench facing the cable machine with your feet flat on the floor and your knees slightly bent.","Grasp the cable handle with an overhand grip and extend your arms fully in front of you.","Lean forward from your hips while keeping your back straight and your core engaged.","Pull the cable handle towards your chest by retracting your shoulder blades and bending your elbows.","Squeeze your back muscles at the top of the movement, then slowly extend your arms back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1319","name":"cable palm rotational row","body_part":"back","target":"upper back","secondary_muscles":["biceps","forearms"],"equipment":"cable","difficulty":"intermediate","description":"The cable palm rotational row is a cable-based exercise targeting the upper back, with secondary emphasis on the biceps and forearms. It involves pulling a cable handle towards the body while rotating the palms, engaging the upper back muscles and improving grip strength.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1319.gif","youtube_id":null,"instructions":["Attach a handle to a cable machine at waist height.","Stand facing the machine with your feet shoulder-width apart.","Grasp the handle with an overhand grip, palms facing down.","Step back to create tension on the cable, keeping your back straight and knees slightly bent.","Pull the handle towards your body, rotating your palms to face upwards as you do so.","Squeeze your shoulder blades together at the end of the movement.","Slowly release the handle back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1320","name":"cable rope crossover seated row","body_part":"back","target":"upper back","secondary_muscles":["biceps","forearms"],"equipment":"cable","difficulty":"intermediate","description":"The cable rope crossover seated row is a strength exercise targeting the upper back, performed on a cable machine using rope attachments. It also engages the biceps and forearms as secondary muscles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1320.gif","youtube_id":null,"instructions":["Sit on the rowing machine with your feet flat on the footrests and your knees slightly bent.","Grasp the cable ropes with an overhand grip, palms facing each other.","Lean back slightly, keeping your back straight and your core engaged.","Pull the cable ropes towards your chest, squeezing your shoulder blades together.","Pause for a moment at the peak of the movement, then slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1321","name":"cable rope elevated seated row","body_part":"back","target":"upper back","secondary_muscles":["biceps","forearms"],"equipment":"cable","difficulty":"intermediate","description":"The cable rope elevated seated row is a strength exercise targeting the upper back, performed on an elevated seat using a cable machine with rope handles. It emphasizes scapular retraction and upper back engagement while also working the biceps and forearms.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1321.gif","youtube_id":null,"instructions":["Sit on the elevated seat facing the cable machine.","Grab the cable rope handles with an overhand grip, palms facing each other.","Keep your back straight and lean slightly back, maintaining a slight bend in your knees.","Pull the cable towards your body by retracting your shoulder blades and squeezing your back muscles.","Pause for a moment at the fully contracted position.","Slowly release the tension and extend your arms back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1322","name":"cable rope extension incline bench row","body_part":"back","target":"upper back","secondary_muscles":["biceps","shoulders"],"equipment":"cable","difficulty":"intermediate","description":"The cable rope extension incline bench row targets the upper back using a cable machine and an incline bench. It requires pulling a rope attachment towards the upper chest while seated on an incline bench, emphasizing scapular retraction and upper back engagement.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1322.gif","youtube_id":null,"instructions":["Set up an incline bench at a 45-degree angle and attach a cable machine to the low pulley.","Attach a rope handle to the cable machine and sit on the incline bench facing the machine.","Grab the rope handle with an overhand grip and lean forward, keeping your back straight.","Extend your arms fully, pulling the rope towards your upper chest while keeping your elbows close to your body.","Squeeze your shoulder blades together at the end of the movement.","Slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1323","name":"cable rope seated row","body_part":"back","target":"upper back","secondary_muscles":["biceps","forearms"],"equipment":"cable","difficulty":"beginner","description":"The cable rope seated row is a strength exercise targeting the upper back, performed using a cable machine with rope attachment. It also engages the biceps and forearms as secondary muscles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1323.gif","youtube_id":null,"instructions":["Sit on the rowing machine with your feet flat on the footrests and knees slightly bent.","Grasp the cable ropes with an overhand grip, palms facing each other.","Keep your back straight and lean slightly forward, maintaining a slight bend in your elbows.","Pull the cable ropes towards your body, squeezing your shoulder blades together.","Pause for a moment at the peak of the movement, then slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1324","name":"cable upper row","body_part":"back","target":"upper back","secondary_muscles":["biceps","shoulders"],"equipment":"cable","difficulty":"beginner","description":"The cable upper row is a compound exercise targeting the upper back, performed using a cable machine and a straight bar. It involves pulling the bar towards the upper chest, engaging the upper back, biceps, and shoulders.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1324.gif","youtube_id":null,"instructions":["Attach a straight bar to a cable machine at chest height.","Stand facing the machine with your feet shoulder-width apart.","Grasp the bar with an overhand grip, hands slightly wider than shoulder-width apart.","Keep your back straight and your core engaged.","Pull the bar towards your upper chest, squeezing your shoulder blades together.","Pause for a moment at the top of the movement.","Slowly release the bar back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1325","name":"cable wide grip rear pulldown behind neck","body_part":"back","target":"lats","secondary_muscles":["biceps","rhomboids","rear deltoids"],"equipment":"cable","difficulty":"advanced","description":"The cable wide grip rear pulldown behind neck is a strength exercise targeting the latissimus dorsi (lats) and also engaging the biceps, rhomboids, and rear deltoids. It involves pulling a cable bar behind the neck while seated, requiring good shoulder mobility and control.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1325.gif","youtube_id":null,"instructions":["Adjust the cable machine so that the pulldown bar is at a height above your head.","Sit down on the seat and grab the pulldown bar with a wide overhand grip.","Keep your back straight and your chest up as you lean back slightly.","Pull the bar down towards your upper chest, squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, then slowly release the bar back up to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1326","name":"chin-up","body_part":"back","target":"lats","secondary_muscles":["biceps","forearms"],"equipment":"body weight","difficulty":"intermediate","description":"The chin-up is a bodyweight exercise that targets the latissimus dorsi (lats) and also works the biceps and forearms. It involves pulling your body up towards a bar with an underhand grip until your chin clears the bar.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1326.gif","youtube_id":null,"instructions":["Hang from a pull-up bar with your palms facing towards you and your hands shoulder-width apart.","Engage your core and pull your body up towards the bar, leading with your chest.","Continue pulling until your chin is above the bar.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1327","name":"close grip chin-up","body_part":"back","target":"lats","secondary_muscles":["biceps","forearms"],"equipment":"body weight","difficulty":"intermediate","description":"The close grip chin-up is a bodyweight exercise targeting the lats, with significant involvement of the biceps and forearms. It requires pulling your body up to a bar with a close, underhand grip, emphasizing upper body strength.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1327.gif","youtube_id":null,"instructions":["Grab the pull-up bar with your palms facing towards you and your hands shoulder-width apart.","Hang from the bar with your arms fully extended and your feet off the ground.","Engage your back muscles and pull your body up towards the bar, keeping your elbows close to your body.","Continue pulling until your chin is above the bar.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1328","name":"dumbbell lying rear delt row","body_part":"back","target":"upper back","secondary_muscles":["shoulders","biceps"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell lying rear delt row targets the upper back and rear deltoids, performed while lying face down on a bench and rowing dumbbells upward.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1328.gif","youtube_id":null,"instructions":["Lie face down on a flat bench with a dumbbell in each hand, palms facing inwards.","Extend your arms straight down towards the floor, keeping a slight bend in your elbows.","Engaging your back muscles, lift the dumbbells up towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1329","name":"dumbbell palm rotational bent over row","body_part":"back","target":"upper back","secondary_muscles":["biceps","forearms"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell palm rotational bent over row is a compound exercise targeting the upper back, with additional engagement of the biceps and forearms. The rotational component adds a coordination challenge and increases muscle activation.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1329.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.","Bend forward at the hips, keeping your back straight and your knees slightly bent.","Let your arms hang straight down, palms facing your body.","Engage your core and pull the dumbbells up towards your chest, keeping your elbows close to your body.","As you pull the dumbbells up, rotate your palms so they face away from your body.","Squeeze your shoulder blades together at the top of the movement.","Slowly lower the dumbbells back down to the starting position, rotating your palms back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1330","name":"dumbbell reverse grip incline bench one arm row","body_part":"back","target":"upper back","secondary_muscles":["biceps","shoulders"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell reverse grip incline bench one arm row is a strength exercise targeting the upper back, performed on an incline bench using a single dumbbell and a reverse grip.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1330.gif","youtube_id":null,"instructions":["Set up an incline bench at a 45-degree angle.","Place a dumbbell on the floor next to the bench.","Stand facing the bench with your feet shoulder-width apart.","Bend at the waist and place your left knee and left hand on the bench for support.","Pick up the dumbbell with your right hand using a reverse grip (palm facing down).","Keep your back straight and your core engaged.","Pull the dumbbell up towards your chest, keeping your elbow close to your body.","Squeeze your back muscles at the top of the movement.","Lower the dumbbell back down to the starting position in a controlled manner.","Repeat for the desired number of repetitions.","Switch sides and repeat the exercise with your left arm."]},{"id":"1331","name":"dumbbell reverse grip incline bench two arm row","body_part":"back","target":"upper back","secondary_muscles":["biceps","forearms"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell reverse grip incline bench two arm row is a strength exercise targeting the upper back, performed on an incline bench with dumbbells using an underhand grip. It also engages the biceps and forearms.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1331.gif","youtube_id":null,"instructions":["Set up an incline bench at a 45-degree angle.","Sit on the bench with your chest against the backrest and your feet flat on the ground.","Hold a dumbbell in each hand with an underhand grip.","Lean forward and let your arms hang straight down, fully extended.","Pull the dumbbells up towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1332","name":"exercise ball alternating arm ups","body_part":"back","target":"lats","secondary_muscles":["shoulders","core"],"equipment":"stability ball","difficulty":"beginner","description":"This exercise targets the latissimus dorsi (lats) and involves alternating arm lifts while seated on a stability ball, engaging the core and shoulders for balance and control.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1332.gif","youtube_id":null,"instructions":["Sit on the stability ball with your feet flat on the ground and your back straight.","Hold a dumbbell in each hand with your palms facing inwards and your arms extended down by your sides.","Engage your core and slowly lift one arm up towards your shoulder, keeping your elbow slightly bent.","Pause for a moment at the top, then slowly lower your arm back down to the starting position.","Repeat the movement with the other arm.","Continue alternating arms for the desired number of repetitions."]},{"id":"1333","name":"exercise ball back extension with arms extended","body_part":"back","target":"spine","secondary_muscles":["glutes","hamstrings"],"equipment":"stability ball","difficulty":"intermediate","description":"The exercise ball back extension with arms extended targets the spinal erectors and helps strengthen the lower back, glutes, and hamstrings. It requires balance and core engagement due to the instability of the ball and the extended arm position.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1333.gif","youtube_id":null,"instructions":["Place the stability ball on the ground and lie face down on top of it, with your hips resting on the ball and your feet against a wall for stability.","Extend your arms straight out in front of you, with your palms facing down.","Engage your core and slowly lift your upper body off the ball, keeping your back straight and your neck in line with your spine.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1334","name":"exercise ball back extension with hands behind head","body_part":"back","target":"spine","secondary_muscles":["glutes","hamstrings"],"equipment":"stability ball","difficulty":"intermediate","description":"This exercise targets the spinal erectors and involves performing back extensions while lying face down on a stability ball, with hands placed behind the head for increased difficulty. It also engages the glutes and hamstrings as secondary muscles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1334.gif","youtube_id":null,"instructions":["Place the stability ball on the ground and lie face down on top of it with your hips resting on the ball.","Position your feet against a wall or other stable surface for support.","Cross your arms behind your head, with your hands touching the back of your head.","Engage your core and slowly lift your upper body off the ball, extending your back until your body forms a straight line from your head to your hips.","Pause for a moment at the top of the movement, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1335","name":"exercise ball back extension with knees off ground","body_part":"back","target":"spine","secondary_muscles":["glutes","hamstrings"],"equipment":"stability ball","difficulty":"intermediate","description":"This exercise targets the spinal erectors and requires you to perform a back extension while balancing your hips on a stability ball with your knees off the ground. It challenges your core, glutes, and hamstrings, and requires balance and coordination.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1335.gif","youtube_id":null,"instructions":["Place the stability ball on the ground and lie face down on top of it, with your hips resting on the ball and your feet against a wall for stability.","Position your hands behind your head or crossed over your chest.","Engage your core and slowly lift your upper body off the ball, extending your back until your body forms a straight line from your head to your heels.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1336","name":"exercise ball back extension with rotation","body_part":"back","target":"spine","secondary_muscles":["glutes","hamstrings"],"equipment":"stability ball","difficulty":"intermediate","description":"The exercise ball back extension with rotation is a movement that targets the spinal erectors and involves extending the back while lying face down on a stability ball, then adding a rotational component to engage the obliques and improve core stability.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1336.gif","youtube_id":null,"instructions":["Start by lying face down on the stability ball with your hips resting on the ball and your feet firmly planted on the ground.","Place your hands behind your head or cross them over your chest.","Engage your core and slowly lift your upper body off the ball, extending your back until your body forms a straight line from your head to your heels.","Pause for a moment at the top, then slowly rotate your torso to one side, keeping your hips and legs stable.","Return to the center and repeat the rotation to the other side.","Lower your upper body back down to the starting position and repeat for the desired number of repetitions."]},{"id":"1338","name":"exercise ball hug","body_part":"back","target":"spine","secondary_muscles":["shoulders","chest"],"equipment":"stability ball","difficulty":"beginner","description":"The exercise ball hug is a gentle movement performed on a stability ball, focusing on stretching and mobilizing the spine while engaging the core. It is suitable for improving flexibility and mobility in the back, with secondary engagement of the shoulders and chest.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1338.gif","youtube_id":null,"instructions":["Sit on the stability ball with your feet flat on the ground and your back straight.","Hold the stability ball with both hands, hugging it close to your chest.","Engage your core muscles and slowly lean back, keeping your back straight and your feet planted on the ground.","Continue leaning back until you feel a stretch in your back muscles.","Hold the position for a few seconds, then slowly return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1339","name":"exercise ball lat stretch","body_part":"back","target":"lats","secondary_muscles":["shoulders","triceps"],"equipment":"stability ball","difficulty":"beginner","description":"The exercise ball lat stretch is a flexibility movement that targets the latissimus dorsi muscles. It involves sitting on a stability ball and leaning to the side while holding a dumbbell overhead, providing a deep stretch to the lats and engaging the shoulders and triceps as secondary muscles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1339.gif","youtube_id":null,"instructions":["Sit on a stability ball with your feet flat on the ground and your back straight.","Hold a dumbbell in one hand and extend your arm straight up overhead.","Slowly lean to the opposite side, feeling a stretch in your lat muscle.","Hold the stretch for 20-30 seconds, then return to the starting position.","Repeat on the other side."]},{"id":"1341","name":"exercise ball lower back stretch (pyramid)","body_part":"back","target":"lats","secondary_muscles":["glutes","hamstrings"],"equipment":"stability ball","difficulty":"beginner","description":"A stretch performed on a stability ball to target the lower back and lats, also engaging the glutes and hamstrings. It involves rolling the ball under your lower back and gently extending over it to stretch the muscles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1341.gif","youtube_id":null,"instructions":["Sit on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Slowly walk your feet forward, rolling the ball down your back until your lower back is resting on the ball.","Place your hands behind your head or cross them over your chest.","Engage your core and slowly lower your upper body towards the ground, allowing your lower back to stretch over the ball.","Hold the stretch for a few seconds, then slowly return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1342","name":"exercise ball lying side lat stretch","body_part":"back","target":"lats","secondary_muscles":["shoulders","triceps"],"equipment":"stability ball","difficulty":"beginner","description":"A stretch performed lying on your side over a stability ball to target the lat muscles, with additional stretching for the shoulders and triceps.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1342.gif","youtube_id":null,"instructions":["Lie on your side with your legs extended and your head supported by the stability ball.","Place your top arm on the ball for stability.","Reach your top arm overhead and allow your torso to rotate slightly.","Feel the stretch in your lat muscles on the side of your body.","Hold the stretch for 20-30 seconds, then switch sides and repeat."]},{"id":"1343","name":"exercise ball prone leg raise","body_part":"back","target":"spine","secondary_muscles":["abdominals","glutes"],"equipment":"stability ball","difficulty":"intermediate","description":"The exercise ball prone leg raise is performed by lying face down with your legs extended and toes resting on a stability ball. You lift your legs using your lower back and glutes, targeting the spine and core stabilizers.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1343.gif","youtube_id":null,"instructions":["Lie face down on a mat with your legs extended and your toes resting on top of the stability ball.","Place your hands on the ground, shoulder-width apart, and engage your core muscles.","Keeping your legs straight, slowly lift them off the ground, using your lower back and glutes to raise them as high as possible.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1344","name":"ez bar reverse grip bent over row","body_part":"back","target":"upper back","secondary_muscles":["biceps","forearms"],"equipment":"ez barbell","difficulty":"intermediate","description":"The EZ bar reverse grip bent over row is a compound exercise targeting the upper back, with secondary emphasis on the biceps and forearms. It involves pulling an EZ barbell towards the lower chest while bent over, using an underhand grip.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1344.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and knees slightly bent.","Hold the ez barbell with an underhand grip, palms facing up, and hands shoulder-width apart.","Bend forward at the hips, keeping your back straight and chest up, until your torso is almost parallel to the floor.","Pull the ez barbell towards your lower chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the ez barbell back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1345","name":"kettlebell two arm row","body_part":"back","target":"upper back","secondary_muscles":["biceps","forearms"],"equipment":"kettlebell","difficulty":"intermediate","description":"The kettlebell two arm row is a compound exercise targeting the upper back, performed by pulling two kettlebells towards the chest while maintaining a bent-over position.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1345.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, knees slightly bent, and hold a kettlebell in each hand with your palms facing your body.","Bend forward at the hips, keeping your back straight and your core engaged.","Pull the kettlebells up towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the kettlebells back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1346","name":"kneeling lat stretch","body_part":"back","target":"lats","secondary_muscles":["shoulders","triceps"],"equipment":"body weight","difficulty":"beginner","description":"The kneeling lat stretch is a bodyweight exercise that targets the latissimus dorsi (lats) and helps improve flexibility and mobility in the upper back and shoulders. It is performed by kneeling, extending the arms overhead, and leaning side to side to stretch each lat muscle.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1346.gif","youtube_id":null,"instructions":["Kneel on the ground with your knees hip-width apart and your toes pointing back.","Extend your arms overhead and interlace your fingers.","Keeping your back straight, slowly lean to the right side, feeling a stretch in your left lat muscle.","Hold the stretch for 20-30 seconds, then return to the starting position.","Repeat the stretch on the left side, leaning to the left and feeling a stretch in your right lat muscle.","Continue alternating sides for the desired number of repetitions."]},{"id":"1347","name":"lever one arm lateral wide pulldown","body_part":"back","target":"lats","secondary_muscles":["biceps","rhomboids","rear deltoids"],"equipment":"leverage machine","difficulty":"intermediate","description":"The lever one arm lateral wide pulldown is a machine-based exercise targeting the latissimus dorsi, performed one arm at a time for unilateral strength and muscle development.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1347.gif","youtube_id":null,"instructions":["Adjust the seat height and position yourself on the machine with your chest against the pad and your feet flat on the floor.","Grasp the handle with an overhand grip and fully extend your arm, keeping a slight bend in your elbow.","Pull the handle down and across your body towards your opposite hip, squeezing your lat muscle at the bottom of the movement.","Slowly return the handle to the starting position, fully extending your arm.","Repeat for the desired number of repetitions, then switch sides."]},{"id":"1348","name":"lever reverse grip vertical row","body_part":"back","target":"upper back","secondary_muscles":["biceps","forearms"],"equipment":"leverage machine","difficulty":"beginner","description":"The lever reverse grip vertical row is a machine-based exercise targeting the upper back, with secondary emphasis on the biceps and forearms. It involves pulling handles with an underhand grip while seated, focusing on squeezing the shoulder blades together.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1348.gif","youtube_id":null,"instructions":["Adjust the seat height and footplate position to ensure proper alignment.","Sit on the machine with your chest against the pad and your feet flat on the footplate.","Grasp the handles with an underhand grip, palms facing up.","Keep your back straight and engage your core.","Pull the handles towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top of the movement, then slowly release and extend your arms back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1349","name":"lever reverse t-bar row","body_part":"back","target":"upper back","secondary_muscles":["biceps","forearms"],"equipment":"leverage machine","difficulty":"beginner","description":"The lever reverse t-bar row is a machine-based exercise targeting the upper back. It involves pulling handles towards the chest while seated, emphasizing scapular retraction and upper back engagement.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1349.gif","youtube_id":null,"instructions":["Adjust the seat height and footplate position on the leverage machine.","Sit on the machine with your chest against the pad and your feet flat on the footplate.","Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.","Keep your back straight and engage your core.","Pull the handles towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top of the movement, then slowly release and extend your arms back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1350","name":"lever seated row","body_part":"back","target":"upper back","secondary_muscles":["biceps","forearms"],"equipment":"leverage machine","difficulty":"beginner","description":"The lever seated row is a machine-based exercise targeting the upper back. It involves pulling handles towards the torso while seated, focusing on squeezing the shoulder blades together.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1350.gif","youtube_id":null,"instructions":["Adjust the seat height and footrests to a comfortable position.","Sit on the machine with your chest against the pad and your feet on the footrests.","Grasp the handles with an overhand grip, shoulder-width apart.","Keep your back straight and your core engaged.","Pull the handles towards your body, squeezing your shoulder blades together.","Pause for a moment at the peak of the movement.","Slowly release the handles and return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1351","name":"lever t-bar reverse grip row","body_part":"back","target":"upper back","secondary_muscles":["biceps","forearms"],"equipment":"leverage machine","difficulty":"intermediate","description":"The lever t-bar reverse grip row is a machine-based exercise targeting the upper back, with secondary emphasis on the biceps and forearms. It involves pulling a lever towards the chest while keeping the chest supported on a pad, promoting upper back strength and muscle development.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1351.gif","youtube_id":null,"instructions":["Adjust the seat height and position yourself on the machine with your chest against the pad and your feet flat on the floor.","Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.","Keep your back straight and engage your core.","Pull the handles towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top of the movement, then slowly release and extend your arms back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1352","name":"lower back curl","body_part":"back","target":"spine","secondary_muscles":["glutes","hamstrings"],"equipment":"body weight","difficulty":"beginner","description":"The lower back curl is a bodyweight exercise that targets the muscles of the lower back (spine) and also engages the glutes and hamstrings. It involves lying face down and curling the upper body off the ground by contracting the lower back muscles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1352.gif","youtube_id":null,"instructions":["Lie flat on your stomach with your legs extended and your arms by your sides.","Engage your glutes and hamstrings, and slowly lift your upper body off the ground, curling your back upwards.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1353","name":"medicine ball catch and overhead throw","body_part":"back","target":"lats","secondary_muscles":["shoulders","core"],"equipment":"medicine ball","difficulty":"intermediate","description":"The medicine ball catch and overhead throw is a dynamic exercise targeting the lats, shoulders, and core. It involves catching and explosively throwing a medicine ball overhead, combining elements of strength and power.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1353.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, holding a medicine ball in both hands at chest level.","Bend your knees slightly and engage your core.","Lower your body into a squat position, keeping your back straight and chest up.","Explosively extend your hips and legs, while simultaneously throwing the medicine ball overhead.","Release the ball at the top of the movement and catch it on the way down.","Lower your body back into the squat position and repeat for the desired number of repetitions."]},{"id":"1354","name":"medicine ball overhead slam","body_part":"back","target":"upper back","secondary_muscles":["shoulders","core"],"equipment":"medicine ball","difficulty":"intermediate","description":"The medicine ball overhead slam is a dynamic exercise that targets the upper back, shoulders, and core by forcefully slamming a medicine ball to the ground from an overhead position. It requires coordination, power, and full-body engagement.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1354.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, holding a medicine ball with both hands above your head.","Engage your core and keep your back straight.","Bend your knees slightly and forcefully slam the medicine ball down to the ground in front of you.","As you slam the ball down, use your entire body to generate power, including your shoulders and core.","Catch the ball on the bounce and repeat for the desired number of repetitions."]},{"id":"1355","name":"one arm against wall","body_part":"back","target":"lats","secondary_muscles":["shoulders","triceps"],"equipment":"body weight","difficulty":"beginner","description":"A bodyweight exercise where you stand facing a wall, extend one arm to press against the wall, and engage your lats by pushing, focusing on lat activation and shoulder stability.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1355.gif","youtube_id":null,"instructions":["Stand facing a wall with your feet shoulder-width apart.","Extend one arm straight out in front of you and place your palm against the wall.","Engage your core and lean your body forward, keeping your arm straight and your back flat.","Slowly push against the wall with your palm, activating your lat muscles.","Hold the position for a few seconds, then release and repeat with the other arm."]},{"id":"1356","name":"lever one arm lateral high row","body_part":"back","target":"upper back","secondary_muscles":["biceps","shoulders"],"equipment":"leverage machine","difficulty":"intermediate","description":"The lever one arm lateral high row is a machine-based exercise targeting the upper back, with secondary emphasis on the biceps and shoulders. It involves pulling a handle toward the body with one arm, focusing on squeezing the back muscles at the top of the movement.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1356.gif","youtube_id":null,"instructions":["Adjust the seat height and position yourself facing the machine.","Grasp the handle with one hand and keep your back straight.","Pull the handle towards your body, keeping your elbow close to your side.","Squeeze your back muscles at the top of the movement.","Slowly release the handle back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1358","name":"side lying floor stretch","body_part":"back","target":"lats","secondary_muscles":["obliques","glutes"],"equipment":"body weight","difficulty":"beginner","description":"The side lying floor stretch is a bodyweight exercise targeting the lats, with secondary emphasis on the obliques and glutes. It is performed lying on your side, reaching overhead, and lifting the bottom leg to create a stretch along the side of the body.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1358.gif","youtube_id":null,"instructions":["Lie on your side with your legs straight and your bottom arm extended straight overhead.","Bend your top knee and place your foot on the ground in front of your bottom leg.","Reach your top arm over your head and grab onto something stable, like a wall or a piece of furniture.","Slowly lift your bottom leg off the ground, keeping it straight, until you feel a stretch in your side.","Hold the stretch for 20-30 seconds, then slowly lower your leg back down.","Repeat on the other side."]},{"id":"1359","name":"smith bent over row","body_part":"back","target":"upper back","secondary_muscles":["biceps","forearms"],"equipment":"smith machine","difficulty":"intermediate","description":"The smith bent over row is a compound exercise performed using a smith machine. It targets the upper back and also works the biceps and forearms. The exercise involves hinging at the hips, maintaining a straight back, and pulling the bar towards the lower chest.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1359.gif","youtube_id":null,"instructions":["Set up the smith machine with the bar at hip height.","Stand facing the bar with your feet shoulder-width apart.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Grasp the bar with an overhand grip, hands slightly wider than shoulder-width apart.","Pull the bar towards your lower chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the bar back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1360","name":"smith one arm row","body_part":"back","target":"upper back","secondary_muscles":["biceps","forearms"],"equipment":"smith machine","difficulty":"intermediate","description":"The smith one arm row is a unilateral back exercise performed on a smith machine, targeting the upper back and engaging the biceps and forearms as secondary muscles. It requires stability, coordination, and proper form to execute safely and effectively.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1360.gif","youtube_id":null,"instructions":["Adjust the height of the smith machine bar to waist level.","Stand facing the smith machine with your feet shoulder-width apart.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Grasp the bar with one hand using an overhand grip, with your palm facing down.","Keep your elbow close to your body and pull the bar towards your waist, squeezing your shoulder blades together.","Pause for a moment at the top of the movement, then slowly lower the bar back to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]},{"id":"1361","name":"smith reverse grip bent over row","body_part":"back","target":"upper back","secondary_muscles":["biceps","forearms"],"equipment":"smith machine","difficulty":"intermediate","description":"The smith reverse grip bent over row is a compound exercise targeting the upper back, performed using a smith machine. It involves pulling a bar with an underhand grip while bent over, focusing on the upper back, biceps, and forearms.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1361.gif","youtube_id":null,"instructions":["Set up the smith machine with the bar at hip height.","Stand facing the bar with your feet shoulder-width apart.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Grasp the bar with an underhand grip, hands shoulder-width apart.","Pull the bar towards your lower chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the bar back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1362","name":"sphinx","body_part":"back","target":"spine","secondary_muscles":["glutes","hamstrings"],"equipment":"body weight","difficulty":"beginner","description":"The sphinx exercise is a gentle back extension movement that targets the spine and helps improve flexibility and mobility in the lower back. It is performed lying face down, lifting the chest off the ground while keeping the forearms and toes on the floor.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1362.gif","youtube_id":null,"instructions":["Lie face down on the ground with your forearms flat on the floor, elbows directly under your shoulders.","Engage your core and lift your chest off the ground, keeping your forearms and toes on the floor.","Hold this position for a few seconds, making sure to keep your neck in a neutral position.","Slowly lower your chest back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1363","name":"spine stretch","body_part":"back","target":"spine","secondary_muscles":["hamstrings","glutes"],"equipment":"body weight","difficulty":"beginner","description":"The spine stretch is a bodyweight exercise that focuses on stretching and mobilizing the spine. It also provides a gentle stretch to the hamstrings and glutes. This movement is performed seated and emphasizes spinal flexibility and posture.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1363.gif","youtube_id":null,"instructions":["Sit on the ground with your legs extended in front of you.","Place your hands on the ground behind you, fingers pointing towards your body.","Engage your core and slowly lean back, keeping your back straight.","Continue leaning back until you feel a stretch in your spine.","Hold the stretch for a few seconds, then slowly return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1364","name":"standing pelvic tilt","body_part":"back","target":"spine","secondary_muscles":["abdominals"],"equipment":"body weight","difficulty":"beginner","description":"The standing pelvic tilt is a bodyweight exercise that targets the spine and helps improve core engagement and lower back mobility. It is performed by tilting the pelvis forward while standing, engaging the core and gently mobilizing the lower back.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1364.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and your knees slightly bent.","Place your hands on your hips or let them hang by your sides.","Engage your core muscles and tilt your pelvis forward, pushing your lower back towards the wall behind you.","Hold the position for a few seconds, then release and return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1365","name":"upper back stretch","body_part":"back","target":"upper back","secondary_muscles":["shoulders"],"equipment":"body weight","difficulty":"beginner","description":"The upper back stretch is a bodyweight exercise designed to stretch and mobilize the upper back and shoulders. It is performed by extending the arms, interlacing the fingers, and raising the arms overhead while squeezing the shoulder blades together.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1365.gif","youtube_id":null,"instructions":["Stand up straight with your feet shoulder-width apart.","Extend your arms straight in front of you, parallel to the ground.","Interlace your fingers and rotate your palms away from your body.","Slowly raise your arms overhead, keeping them straight and parallel to each other.","As you raise your arms, squeeze your shoulder blades together.","Hold the stretch for 15-30 seconds, then release and repeat."]},{"id":"1366","name":"upward facing dog","body_part":"back","target":"spine","secondary_muscles":["shoulders","chest"],"equipment":"body weight","difficulty":"beginner","description":"Upward Facing Dog is a yoga pose that stretches the spine, chest, and shoulders while strengthening the arms and back. It is commonly used to improve spinal mobility and posture.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1366.gif","youtube_id":null,"instructions":["Lie face down on the floor with your legs extended behind you.","Place your hands on the floor next to your lower ribs, fingers pointing forward.","Press your hands firmly into the floor and straighten your arms, lifting your torso and thighs off the ground.","Roll your shoulders back and down, opening your chest and lifting your gaze towards the ceiling.","Hold this position for a few breaths, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1367","name":"wide grip rear pull-up","body_part":"back","target":"lats","secondary_muscles":["biceps","forearms"],"equipment":"body weight","difficulty":"advanced","description":"The wide grip rear pull-up is a bodyweight exercise targeting the latissimus dorsi (lats) and also engaging the biceps and forearms. It requires the user to pull their body up to a bar using a wide overhand grip, emphasizing upper back development.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1367.gif","youtube_id":null,"instructions":["Grab the pull-up bar with a wide overhand grip, hands slightly wider than shoulder-width apart.","Hang from the bar with your arms fully extended and your body straight.","Engage your back muscles and pull your body up towards the bar, leading with your chest.","Continue pulling until your chin is above the bar.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1368","name":"ankle circles","body_part":"lower legs","target":"calves","secondary_muscles":["ankle stabilizers"],"equipment":"body weight","difficulty":"beginner","description":"Ankle circles are a bodyweight exercise that targets the calves and ankle stabilizers. This movement involves rotating the ankle in a circular motion while seated, helping to improve mobility and flexibility in the ankle joint.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1368.gif","youtube_id":null,"instructions":["Sit on the ground with your legs extended in front of you.","Lift one leg off the ground and rotate your ankle in a circular motion.","Perform the desired number of circles in one direction, then switch to the other direction.","Repeat with the other leg."]},{"id":"1369","name":"band two legs calf raise - (band under both legs) v. 2","body_part":"lower legs","target":"calves","secondary_muscles":["ankles","feet"],"equipment":"band","difficulty":"beginner","description":"A resistance band calf raise performed with the band under both feet, targeting the calves and also engaging the ankles and feet.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1369.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and place a resistance band under both feet.","Hold the ends of the band with your hands for stability.","Raise your heels off the ground as high as possible, using your calves.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"137","name":"body-up","body_part":"upper arms","target":"triceps","secondary_muscles":["chest","shoulders"],"equipment":"body weight","difficulty":"beginner","description":"The body-up is a bodyweight exercise targeting the triceps, with secondary emphasis on the chest and shoulders. It involves lowering and raising your body using your arms while keeping your body straight, similar to a triceps dip but with feet on the ground.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0137.gif","youtube_id":null,"instructions":["Start by placing your hands on a raised surface, such as a bench or parallel bars, with your palms facing down and fingers pointing forward.","Extend your legs out in front of you, keeping your heels on the ground and your body straight.","Lower your body by bending your elbows, keeping them close to your sides, until your upper arms are parallel to the ground.","Pause for a moment, then push through your palms to straighten your arms and lift your body back up to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1370","name":"barbell floor calf raise","body_part":"lower legs","target":"calves","secondary_muscles":["hamstrings"],"equipment":"barbell","difficulty":"beginner","description":"The barbell floor calf raise is a strength exercise targeting the calves. It involves standing with the balls of your feet on a barbell and raising your heels to work the calf muscles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1370.gif","youtube_id":null,"instructions":["Place a barbell on the floor in front of you.","Stand with the balls of your feet on the edge of the barbell, with your heels hanging off.","Hold onto a stable object for balance if needed.","Raise your heels as high as possible, using your calves to lift your body.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1371","name":"barbell seated calf raise","body_part":"lower legs","target":"calves","secondary_muscles":["hamstrings"],"equipment":"barbell","difficulty":"beginner","description":"The barbell seated calf raise targets the calf muscles by having the lifter sit on a bench with a barbell resting on their thighs, raising and lowering their heels to work the calves through a full range of motion.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1371.gif","youtube_id":null,"instructions":["Sit on a bench with your feet flat on the floor and a barbell resting on your thighs.","Place the balls of your feet on a raised platform, such as a block or step.","Lower your heels as far as possible, feeling a stretch in your calves.","Raise your heels as high as possible, contracting your calves.","Repeat for the desired number of repetitions."]},{"id":"1372","name":"barbell standing calf raise","body_part":"lower legs","target":"calves","secondary_muscles":["hamstrings","glutes"],"equipment":"barbell","difficulty":"intermediate","description":"The barbell standing calf raise is a strength exercise targeting the calves. It involves standing with a barbell across your upper back and raising your heels off the ground to work the calf muscles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1372.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and place a barbell across your upper back.","Raise your heels off the ground as high as possible, using only your toes.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1373","name":"bodyweight standing calf raise","body_part":"lower legs","target":"calves","secondary_muscles":["ankles","feet"],"equipment":"body weight","difficulty":"beginner","description":"The bodyweight standing calf raise is a simple exercise that targets the calf muscles. It involves lifting your heels off the ground while standing, using only your body weight for resistance. This movement helps to strengthen and tone the calves, and can also improve ankle stability.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1373.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, toes pointing forward.","Place your hands on a wall or stable surface for balance.","Slowly raise your heels off the ground, lifting your body weight onto the balls of your feet.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1374","name":"box jump down with one leg stabilization","body_part":"lower legs","target":"calves","secondary_muscles":["quadriceps","hamstrings","glutes"],"equipment":"body weight","difficulty":"advanced","description":"The box jump down with one leg stabilization is a plyometric exercise that targets the calves and challenges balance and stability. It involves jumping onto a box and stabilizing on one leg, which also engages the quadriceps, hamstrings, and glutes.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1374.gif","youtube_id":null,"instructions":["Stand in front of a box or platform with your feet shoulder-width apart.","Bend your knees and jump onto the box, landing softly with one foot on the box and the other foot hanging off the edge.","Stabilize yourself on the box with the foot that is on it, while keeping the other foot off the ground.","Hold this position for a few seconds, engaging your calf muscles to maintain balance.","Slowly step down with the foot that is on the box, returning to the starting position.","Repeat the exercise with the other leg."]},{"id":"1375","name":"cable standing calf raise","body_part":"lower legs","target":"calves","secondary_muscles":["hamstrings","glutes"],"equipment":"cable","difficulty":"beginner","description":"The cable standing calf raise is an exercise that targets the calf muscles using a cable machine for resistance. It involves standing upright and raising your heels off the ground to engage the calves, with secondary activation of the hamstrings and glutes.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1375.gif","youtube_id":null,"instructions":["Stand facing a cable machine with your feet shoulder-width apart.","Hold onto the cable machine handles or attach a cable ankle strap to your ankles.","Raise your heels off the ground by extending your ankles as high as possible.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1376","name":"cable standing one leg calf raise","body_part":"lower legs","target":"calves","secondary_muscles":["ankles","feet"],"equipment":"cable","difficulty":"intermediate","description":"The cable standing one leg calf raise is a lower leg exercise that targets the calves using a cable machine for resistance. It is performed on one leg at a time, which increases the balance and stabilization demands.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1376.gif","youtube_id":null,"instructions":["Stand facing a cable machine with your feet shoulder-width apart.","Hold onto the cable machine for support.","Lift one leg off the ground and balance on the other leg.","Slowly raise your heel off the ground, lifting your body up onto your toes.","Pause for a moment at the top, then slowly lower your heel back down to the starting position.","Repeat for the desired number of repetitions, then switch legs."]},{"id":"1377","name":"calf stretch with hands against wall","body_part":"lower legs","target":"calves","secondary_muscles":["hamstrings"],"equipment":"body weight","difficulty":"beginner","description":"A stretch targeting the calves, performed by leaning against a wall with one leg extended back and the heel pressed to the ground.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1377.gif","youtube_id":null,"instructions":["Stand facing a wall with your feet hip-width apart.","Place your hands against the wall at shoulder height.","Step your right foot back, keeping your heel on the ground and your leg straight.","Bend your left knee and lean forward, keeping your back leg straight and your heel on the ground.","Hold the stretch for 20-30 seconds.","Switch legs and repeat the stretch."]},{"id":"1378","name":"calf stretch with rope","body_part":"lower legs","target":"calves","secondary_muscles":["hamstrings"],"equipment":"rope","difficulty":"beginner","description":"A static stretching exercise using a rope to increase flexibility in the calves and hamstrings.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1378.gif","youtube_id":null,"instructions":["Stand facing a wall or sturdy object with your feet hip-width apart.","Hold the ends of the rope in each hand and place the middle of the rope around the ball of your right foot.","Step back with your left foot, keeping your heel on the ground and your leg straight.","Lean forward, keeping your back straight, and gently pull on the rope to stretch your calf.","Hold the stretch for 20-30 seconds, then release.","Repeat on the other leg."]},{"id":"1379","name":"dumbbell seated calf raise","body_part":"lower legs","target":"calves","secondary_muscles":["hamstrings"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell seated calf raise is an isolation exercise targeting the calf muscles, performed while seated with a dumbbell resting on the thighs. It is effective for building strength and muscle in the calves.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1379.gif","youtube_id":null,"instructions":["Sit on a bench or chair with your feet flat on the ground and a dumbbell resting on your thighs.","Place the balls of your feet on a raised surface such as a step or block, with your heels hanging off the edge.","Hold onto the dumbbell for stability.","Raise your heels as high as possible, lifting your body weight onto the balls of your feet.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"138","name":"bottoms-up","body_part":"waist","target":"abs","secondary_muscles":["obliques","hip flexors"],"equipment":"body weight","difficulty":"intermediate","description":"The bottoms-up exercise is a bodyweight movement targeting the abdominal muscles. It involves lying on your back, bringing your knees toward your chest, and lifting your hips off the ground to engage your core.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0138.gif","youtube_id":null,"instructions":["Lie flat on your back with your legs extended and your arms by your sides.","Bend your knees and bring them towards your chest, keeping your feet off the ground.","Engaging your abs, lift your hips off the ground, bringing your knees towards your head.","Pause for a moment at the top, then slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1380","name":"dumbbell seated one leg calf raise - hammer grip","body_part":"lower legs","target":"calves","secondary_muscles":["hamstrings","glutes"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell seated one leg calf raise - hammer grip is a lower leg exercise that targets the calves, with secondary emphasis on the hamstrings and glutes. It is performed seated, using a dumbbell for resistance, and involves raising and lowering the heel to strengthen the calf muscles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1380.gif","youtube_id":null,"instructions":["Sit on a bench or chair with your feet flat on the ground and a dumbbell resting on your thighs.","Place one foot on a raised surface, such as a step or block, with your heel hanging off the edge.","Hold the dumbbell with a hammer grip, meaning your palms are facing each other and your fingers are wrapped around the handle.","Keeping your core engaged and your back straight, slowly raise your heel as high as possible by pushing through the ball of your foot.","Pause for a moment at the top, then slowly lower your heel back down to the starting position.","Repeat for the desired number of repetitions, then switch to the other leg."]},{"id":"1381","name":"dumbbell seated one leg calf raise - palm up","body_part":"lower legs","target":"calves","secondary_muscles":["hamstrings","glutes"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell seated one leg calf raise - palm up is an isolation exercise targeting the calf muscles, performed while seated with a dumbbell placed on the thigh. It helps build strength and muscle endurance in the calves, with some secondary activation of the hamstrings and glutes.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1381.gif","youtube_id":null,"instructions":["Sit on a bench or chair with your back straight and your feet flat on the ground.","Hold a dumbbell in one hand and place it on top of your thigh, palm facing up.","Lift one leg off the ground and extend it in front of you, keeping your knee slightly bent.","Raise your heel as high as possible by pushing through the ball of your foot.","Pause for a moment at the top, then slowly lower your heel back down.","Repeat for the desired number of repetitions, then switch legs and repeat."]},{"id":"1382","name":"exercise ball on the wall calf raise","body_part":"lower legs","target":"calves","secondary_muscles":["hamstrings","quadriceps"],"equipment":"dumbbell","difficulty":"beginner","description":"This exercise targets the calves by performing a calf raise while standing against a wall with an exercise ball for support and holding dumbbells for added resistance.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1382.gif","youtube_id":null,"instructions":["Stand with your back against a wall and place an exercise ball between your lower back and the wall.","Position your feet shoulder-width apart, with your toes pointing forward.","Hold a dumbbell in each hand, with your arms extended by your sides.","Raise your heels off the ground, lifting your body weight onto the balls of your feet.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1383","name":"hack calf raise","body_part":"lower legs","target":"calves","secondary_muscles":["hamstrings","glutes"],"equipment":"sled machine","difficulty":"beginner","description":"The hack calf raise is a lower leg exercise performed on a sled machine, primarily targeting the calves. It involves raising and lowering the heels while standing on the platform, focusing on calf muscle contraction.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1383.gif","youtube_id":null,"instructions":["Adjust the sled machine to a comfortable weight.","Stand on the sled machine with your toes on the platform and your heels hanging off.","Hold onto the handles for stability.","Raise your heels as high as possible by pushing through the balls of your feet.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1384","name":"hack one leg calf raise","body_part":"lower legs","target":"calves","secondary_muscles":["hamstrings","glutes"],"equipment":"sled machine","difficulty":"intermediate","description":"The hack one leg calf raise is performed on a sled machine, targeting the calves with additional engagement of the hamstrings and glutes. It is executed one leg at a time, requiring balance and unilateral strength.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1384.gif","youtube_id":null,"instructions":["Adjust the sled machine to an appropriate weight.","Stand on the sled machine with one foot, keeping the other foot off the ground.","Hold onto the handles for stability.","Raise your heel as high as possible, lifting your body up on the ball of your foot.","Pause for a moment at the top, then slowly lower your heel back down to the starting position.","Repeat for the desired number of repetitions.","Switch legs and repeat the exercise."]},{"id":"1385","name":"lever seated squat calf raise on leg press machine","body_part":"lower legs","target":"calves","secondary_muscles":["quadriceps","hamstrings","glutes"],"equipment":"leverage machine","difficulty":"beginner","description":"The lever seated squat calf raise on leg press machine is an isolation exercise targeting the calves, performed on a leg press machine by extending and flexing the ankles while seated.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1385.gif","youtube_id":null,"instructions":["Adjust the seat of the leg press machine so that your knees are slightly bent when your feet are on the footplate.","Sit on the machine with your back against the backrest and your feet flat on the footplate, shoulder-width apart.","Place your toes and the balls of your feet on the footplate, keeping your heels off the edge.","Release the safety handles and push the footplate away from you by extending your knees.","Once your knees are fully extended, slowly lower your heels by flexing your calves.","Pause for a moment at the bottom, then push the footplate back up by extending your calves.","Repeat for the desired number of repetitions."]},{"id":"1386","name":"one leg donkey calf raise","body_part":"lower legs","target":"calves","secondary_muscles":["hamstrings","glutes"],"equipment":"body weight","difficulty":"intermediate","description":"The one leg donkey calf raise is a bodyweight exercise targeting the calves, performed by raising the heel of one foot while the other leg is lifted, often using a wall or bar for balance.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1386.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, toes pointing forward.","Place your hands on a stable surface for support, such as a wall or a bar.","Lift one leg off the ground, keeping your knee slightly bent.","Raise your heel as high as possible, using your calf muscles.","Pause for a moment at the top, then slowly lower your heel back down.","Repeat for the desired number of repetitions, then switch legs."]},{"id":"1387","name":"one leg floor calf raise","body_part":"lower legs","target":"calves","secondary_muscles":["ankles","feet"],"equipment":"body weight","difficulty":"beginner","description":"The one leg floor calf raise is a bodyweight exercise targeting the calves, performed by standing on one leg and raising the heel to engage the calf muscles. It also involves the ankles and feet as secondary muscles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1387.gif","youtube_id":null,"instructions":["Stand with your feet hip-width apart and place your hands on a wall or sturdy object for balance.","Lift one foot off the ground and balance on the other foot.","Slowly raise your heel off the ground, lifting your body up onto the ball of your foot.","Pause for a moment at the top, then slowly lower your heel back down to the starting position.","Repeat for the desired number of repetitions, then switch legs and repeat."]},{"id":"1388","name":"peroneals stretch","body_part":"lower legs","target":"calves","secondary_muscles":["ankles","feet"],"equipment":"rope","difficulty":"beginner","description":"The peroneals stretch is a flexibility exercise targeting the calf muscles, ankles, and feet. It uses a rope to assist in stretching the lower leg, improving mobility and reducing tightness.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1388.gif","youtube_id":null,"instructions":["Sit on the ground with your legs extended in front of you.","Loop the rope around the ball of your foot and hold the ends of the rope with your hands.","Gently pull the rope towards you, flexing your foot and stretching your calf muscles.","Hold the stretch for 15-30 seconds.","Release the tension on the rope and repeat the stretch on the other leg.","Repeat for the desired number of repetitions."]},{"id":"1389","name":"posterior tibialis stretch","body_part":"lower legs","target":"calves","secondary_muscles":["hamstrings","quadriceps"],"equipment":"rope","difficulty":"beginner","description":"A stretch targeting the calves using a rope to assist in flexing the foot and lengthening the posterior tibialis and calf muscles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1389.gif","youtube_id":null,"instructions":["Sit on the ground with your legs extended in front of you.","Loop the rope around the ball of your foot and hold the ends of the rope with your hands.","Gently pull the rope towards you, flexing your foot and stretching your calf muscles.","Hold the stretch for 20-30 seconds.","Release the tension on the rope and relax your foot.","Repeat the stretch on the other leg."]},{"id":"139","name":"biceps narrow pull-ups","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms","shoulders"],"equipment":"body weight","difficulty":"advanced","description":"Biceps narrow pull-ups are a bodyweight exercise that primarily targets the biceps, with secondary emphasis on the forearms and shoulders. The movement involves pulling your body up to a bar with a narrow, underhand grip, requiring significant upper body strength and coordination.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0139.gif","youtube_id":null,"instructions":["Hang from a pull-up bar with your palms facing towards you and your hands shoulder-width apart.","Engage your core and pull yourself up towards the bar, focusing on using your biceps to lift your body.","Pause for a moment at the top, then slowly lower yourself back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1390","name":"seated calf stretch (male)","body_part":"lower legs","target":"calves","secondary_muscles":["hamstrings"],"equipment":"body weight","difficulty":"beginner","description":"The seated calf stretch (male) is a flexibility exercise targeting the calf muscles. It is performed while seated, requiring no equipment other than a chair or bench, and focuses on stretching the calves and, to a lesser extent, the hamstrings.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1390.gif","youtube_id":null,"instructions":["Sit on the edge of a chair or bench with your feet flat on the ground.","Extend one leg straight out in front of you, keeping your heel on the ground.","Lean forward slightly, feeling a stretch in your calf muscle.","Hold the stretch for 20-30 seconds.","Switch legs and repeat the stretch."]},{"id":"1391","name":"sled calf press on leg press","body_part":"lower legs","target":"calves","secondary_muscles":["hamstrings","quadriceps"],"equipment":"sled machine","difficulty":"beginner","description":"The sled calf press on leg press is an exercise that targets the calves using a sled (leg press) machine. It also engages the hamstrings and quadriceps as secondary muscles. The movement involves pressing the sled away using the balls of your feet, focusing on ankle extension.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1391.gif","youtube_id":null,"instructions":["Adjust the seat of the leg press machine so that your knees are slightly bent when your feet are on the sled.","Place your feet shoulder-width apart on the sled, with your toes pointing forward.","Release the safety handles and push the sled away from you by extending your knees and ankles.","Pause for a moment at the top of the movement, then slowly lower the sled back down by bending your knees and ankles.","Repeat for the desired number of repetitions."]},{"id":"1392","name":"sled one leg calf press on leg press","body_part":"lower legs","target":"calves","secondary_muscles":["hamstrings","glutes"],"equipment":"sled machine","difficulty":"intermediate","description":"The sled one leg calf press on leg press is a machine-based exercise targeting the calves, performed one leg at a time for increased isolation and intensity. It also engages the hamstrings and glutes as secondary muscles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1392.gif","youtube_id":null,"instructions":["Adjust the seat of the leg press machine so that your knees are slightly bent when your feet are on the sled.","Sit on the machine with your back against the backrest and your feet on the sled, shoulder-width apart.","Place your toes and the balls of your feet on the sled, keeping your heels off.","Push the sled forward by extending your ankles, keeping your knees slightly bent.","Pause for a moment at the top, then slowly lower the sled back down by flexing your ankles.","Repeat for the desired number of repetitions."]},{"id":"1393","name":"smith one leg floor calf raise","body_part":"lower legs","target":"calves","secondary_muscles":["hamstrings","glutes"],"equipment":"smith machine","difficulty":"intermediate","description":"The smith one leg floor calf raise is a lower leg exercise performed using a Smith machine. It targets the calves and also engages the hamstrings and glutes as secondary muscles. The exercise involves raising your heel off the ground while balancing on one leg, with the Smith machine bar providing resistance.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1393.gif","youtube_id":null,"instructions":["Position yourself on the floor under the smith machine bar, facing away from the machine.","Place the balls of your feet on a raised surface, such as a weight plate or block.","Position the smith machine bar across your lower legs, just above your ankles.","Hold onto the bar with your hands for stability.","Raise your heels off the ground by extending your ankles, lifting your body up.","Pause at the top of the movement, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1394","name":"smith reverse calf raises","body_part":"lower legs","target":"calves","secondary_muscles":["hamstrings"],"equipment":"smith machine","difficulty":"intermediate","description":"Smith reverse calf raises are performed using a Smith machine and primarily target the calves, with secondary emphasis on the hamstrings. The exercise involves raising the heels while standing on the balls of the feet on a step or platform, using the Smith machine bar for support.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1394.gif","youtube_id":null,"instructions":["Adjust the smith machine bar to a height just below your shoulders.","Stand facing the bar with your feet hip-width apart and toes pointing forward.","Place the balls of your feet on the edge of a step or platform, with your heels hanging off.","Hold onto the bar for support.","Raise your heels as high as possible, lifting your body up onto your toes.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1395","name":"smith seated one leg calf raise","body_part":"lower legs","target":"calves","secondary_muscles":["hamstrings"],"equipment":"smith machine","difficulty":"intermediate","description":"The smith seated one leg calf raise is a lower leg exercise performed on a smith machine, targeting the calf muscles by raising one heel at a time while seated.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1395.gif","youtube_id":null,"instructions":["Sit on the machine with your back against the pad and your feet on the footrest.","Place one leg on the footrest and keep the other leg off the footrest.","Using your calf muscles, raise your heel as high as possible.","Pause for a moment at the top, then slowly lower your heel back down to the starting position.","Repeat for the desired number of repetitions, then switch legs and repeat."]},{"id":"1396","name":"smith toe raise","body_part":"lower legs","target":"calves","secondary_muscles":["ankles","shins"],"equipment":"smith machine","difficulty":"beginner","description":"The smith toe raise is a calf exercise performed on a Smith machine, focusing on raising the heels to strengthen the calves. It uses a raised platform to increase the range of motion and is performed with the barbell resting on the shoulders.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1396.gif","youtube_id":null,"instructions":["Adjust the smith machine bar to a height that allows you to comfortably stand with your feet flat on the ground.","Position yourself under the bar with your shoulders directly below it and your feet shoulder-width apart.","Place the balls of your feet on a raised platform or weight plates, with your heels hanging off the edge.","Grasp the bar with an overhand grip, slightly wider than shoulder-width apart.","Engage your core and keep your back straight throughout the exercise.","Slowly raise your heels as high as possible, lifting your body weight onto the balls of your feet.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1397","name":"standing calves","body_part":"lower legs","target":"calves","secondary_muscles":["hamstrings","glutes"],"equipment":"body weight","difficulty":"beginner","description":"The standing calves exercise is a bodyweight movement targeting the calf muscles. It involves raising your heels off the ground to stand on your toes, then lowering them back down, which helps build strength and endurance in the calves.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1397.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, toes pointing forward.","Raise your heels off the ground as high as possible, standing on your toes.","Hold the position for a moment, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1398","name":"standing calves calf stretch","body_part":"lower legs","target":"calves","secondary_muscles":["hamstrings","glutes"],"equipment":"body weight","difficulty":"beginner","description":"The standing calves calf stretch is a bodyweight exercise designed to stretch the calf muscles. It is performed by standing facing a wall, placing your hands on the wall, stepping one foot back, and leaning forward to stretch the calf of the back leg.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1398.gif","youtube_id":null,"instructions":["Stand facing a wall or sturdy object, about an arm's length away.","Place your hands on the wall or object at shoulder height.","Step back with one foot, keeping your heel flat on the ground.","Bend your front knee slightly and lean forward, keeping your back leg straight.","You should feel a stretch in your calf muscle.","Hold the stretch for 20-30 seconds.","Repeat on the other leg."]},{"id":"1399","name":"bench dip on floor","body_part":"upper arms","target":"triceps","secondary_muscles":["chest","shoulders"],"equipment":"body weight","difficulty":"beginner","description":"The bench dip on floor is a bodyweight exercise targeting the triceps, with secondary activation of the chest and shoulders. It is performed by supporting your body on your hands at the edge of a bench or chair, lowering your body by bending your elbows, and then pressing back up.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1399.gif","youtube_id":null,"instructions":["Sit on the edge of a bench or chair with your hands gripping the edge, fingers pointing forward.","Slide your butt off the bench, supporting your weight with your hands.","Lower your body by bending your elbows until your upper arms are parallel to the floor.","Push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."]},{"id":"14","name":"assisted motion russian twist","body_part":"waist","target":"abs","secondary_muscles":["obliques","lower back"],"equipment":"medicine ball","difficulty":"beginner","description":"The assisted motion Russian twist is a core exercise performed with a medicine ball. It targets the abdominal muscles and also engages the obliques and lower back. The movement involves twisting the torso from side to side while holding a medicine ball, which adds resistance and helps build core strength and stability.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0014.gif","youtube_id":null,"instructions":["Sit on the ground with your knees bent and feet flat on the floor.","Hold the medicine ball with both hands in front of your chest.","Lean back slightly, engaging your abs and keeping your back straight.","Slowly twist your torso to the right, bringing the medicine ball towards the right side of your body.","Pause for a moment, then twist your torso to the left, bringing the medicine ball towards the left side of your body.","Continue alternating sides for the desired number of repetitions."]},{"id":"140","name":"biceps pull-up","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms","shoulders"],"equipment":"body weight","difficulty":"advanced","description":"The biceps pull-up is a bodyweight exercise that targets the biceps, with secondary emphasis on the forearms and shoulders. It involves pulling your body up to a bar with an overhand grip, focusing on elbow flexion to maximize biceps engagement.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0140.gif","youtube_id":null,"instructions":["Hang from a pull-up bar with your palms facing away from you and your hands shoulder-width apart.","Engage your core and pull yourself up by bending your elbows, bringing your chest towards the bar.","Pause at the top of the movement, then slowly lower yourself back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1401","name":"muscle-up (on vertical bar)","body_part":"back","target":"lats","secondary_muscles":["biceps","triceps","forearms"],"equipment":"body weight","difficulty":"advanced","description":"The muscle-up on a vertical bar is a challenging bodyweight exercise that combines a pull-up with a dip, requiring significant upper body strength, coordination, and technique. It primarily targets the lats, with secondary emphasis on the biceps, triceps, and forearms.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1401.gif","youtube_id":null,"instructions":["Start by hanging from a vertical bar with your palms facing away from you and your arms fully extended.","Engage your core and pull your body up towards the bar, leading with your chest.","As you pull yourself up, lean back slightly and bring your elbows towards your sides.","Continue pulling until your chest reaches the bar and your elbows are fully bent.","Pause for a moment at the top, then slowly lower yourself back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1403","name":"neck side stretch","body_part":"neck","target":"levator scapulae","secondary_muscles":["trapezius","sternocleidomastoid"],"equipment":"body weight","difficulty":"beginner","description":"A gentle stretch targeting the side of the neck, primarily the levator scapulae, performed by tilting the head to the side while standing or sitting.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1403.gif","youtube_id":null,"instructions":["Stand or sit up straight with your shoulders relaxed.","Tilt your head to one side, bringing your ear towards your shoulder.","Hold the stretch for 15-30 seconds.","Repeat on the other side.","Perform 2-4 sets on each side."]},{"id":"1405","name":"back pec stretch","body_part":"back","target":"lats","secondary_muscles":["shoulders","chest"],"equipment":"body weight","difficulty":"beginner","description":"The back pec stretch is a bodyweight exercise designed to stretch the lats, shoulders, and chest. It involves crossing the arms, interlocking the fingers, and raising the arms to feel a stretch across the upper back and chest.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1405.gif","youtube_id":null,"instructions":["Stand tall with your feet shoulder-width apart.","Extend your arms straight out in front of you, parallel to the ground.","Cross your arms in front of your body, with your right arm over your left arm.","Interlock your fingers and rotate your palms away from your body.","Slowly raise your arms up and away from your body, feeling a stretch in your back and chest.","Hold the stretch for 15-30 seconds, then release.","Repeat on the opposite side."]},{"id":"1407","name":"calf push stretch with hands against wall","body_part":"lower legs","target":"calves","secondary_muscles":["hamstrings"],"equipment":"body weight","difficulty":"beginner","description":"The calf push stretch with hands against wall is a bodyweight exercise that targets the calves and also stretches the hamstrings. It is performed by standing facing a wall, placing your hands against it, stepping one foot back, and leaning forward to stretch the calf muscle.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1407.gif","youtube_id":null,"instructions":["Stand facing a wall with your feet hip-width apart.","Place your hands against the wall at shoulder height.","Step back with one foot, keeping your heel on the ground and your leg straight.","Bend your front knee slightly and lean forward, feeling a stretch in your calf.","Hold the stretch for 20-30 seconds.","Switch legs and repeat the stretch."]},{"id":"1408","name":"band hip lift","body_part":"upper legs","target":"glutes","secondary_muscles":["hamstrings","quadriceps"],"equipment":"band","difficulty":"beginner","description":"The band hip lift is a glute-focused exercise performed on the floor with a resistance band placed above the knees. It targets the glutes and also works the hamstrings and quadriceps. The movement involves lifting the hips off the ground while keeping the core engaged and squeezing the glutes at the top.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1408.gif","youtube_id":null,"instructions":["Lie on your back with your knees bent and feet flat on the ground.","Place a resistance band just above your knees.","Engage your glutes and core muscles.","Press your heels into the ground and lift your hips off the floor, squeezing your glutes at the top.","Pause for a moment at the top, then slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1409","name":"barbell glute bridge","body_part":"upper legs","target":"glutes","secondary_muscles":["hamstrings","lower back"],"equipment":"barbell","difficulty":"intermediate","description":"The barbell glute bridge is a strength exercise that targets the glutes, with secondary emphasis on the hamstrings and lower back. It involves lifting the hips off the ground while supporting a barbell across the hips, requiring core engagement and proper form to ensure safety and effectiveness.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1409.gif","youtube_id":null,"instructions":["Start by lying flat on your back on the ground with your knees bent and feet flat on the floor.","Place a barbell across your hips, holding it securely with both hands.","Engage your glutes and core muscles, then lift your hips off the ground until your body forms a straight line from your knees to your shoulders.","Pause for a moment at the top, squeezing your glutes.","Slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1410","name":"barbell lateral lunge","body_part":"upper legs","target":"glutes","secondary_muscles":["quadriceps","hamstrings","calves"],"equipment":"barbell","difficulty":"intermediate","description":"The barbell lateral lunge is a lower body exercise that targets the glutes and also works the quadriceps, hamstrings, and calves. It involves stepping laterally while supporting a barbell on your upper back, requiring strength, balance, and coordination.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1410.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, holding a barbell across your upper back.","Take a big step to the side with your right foot, keeping your left foot planted.","Bend your right knee and lower your body down into a lunge position, keeping your left leg straight.","Push off with your right foot and return to the starting position.","Repeat on the other side, stepping with your left foot."]},{"id":"1411","name":"barbell palms down wrist curl over a bench","body_part":"lower arms","target":"forearms","secondary_muscles":["biceps","brachialis"],"equipment":"barbell","difficulty":"beginner","description":"The barbell palms down wrist curl over a bench is an isolation exercise targeting the forearms, specifically the wrist extensors. It is performed by sitting on a bench, resting the forearms on the thighs or a bench, and curling a barbell upward using only the wrists.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1411.gif","youtube_id":null,"instructions":["Sit on a bench with your feet flat on the ground and your forearms resting on your thighs, palms facing down.","Hold a barbell with an overhand grip, hands shoulder-width apart.","Lower the barbell towards the ground by flexing your wrists, keeping your forearms stationary.","Pause for a moment at the bottom, then slowly raise the barbell back up by extending your wrists.","Repeat for the desired number of repetitions."]},{"id":"1412","name":"barbell palms up wrist curl over a bench","body_part":"lower arms","target":"forearms","secondary_muscles":["biceps","shoulders"],"equipment":"barbell","difficulty":"beginner","description":"The barbell palms up wrist curl over a bench is an isolation exercise targeting the forearms, specifically the wrist flexors. It is performed by sitting on a bench, resting the forearms on the bench with wrists hanging off, and curling a barbell upwards using only the wrists.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1412.gif","youtube_id":null,"instructions":["Sit on a bench with your feet flat on the ground and hold a barbell with an underhand grip, palms facing up.","Rest your forearms on the bench, allowing your wrists to hang off the edge.","Keeping your forearms stationary, exhale and curl your wrists upwards as far as possible.","Hold the contracted position for a brief pause, then inhale and slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1413","name":"cable reverse one arm curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"cable","difficulty":"beginner","description":"The cable reverse one arm curl is an isolation exercise targeting the biceps and forearms, performed using a cable machine. It involves curling the handle with a reverse grip to emphasize the forearms and brachialis.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1413.gif","youtube_id":null,"instructions":["Stand facing a cable machine with your feet shoulder-width apart.","Grasp the cable handle with an underhand grip, palm facing down.","Keep your elbow close to your side and slowly curl your forearm up towards your shoulder.","Pause for a moment at the top, then slowly lower your forearm back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1414","name":"dumbbell one arm reverse preacher curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell one arm reverse preacher curl is an isolation exercise targeting the biceps, performed on a preacher bench with a single dumbbell. It emphasizes strict form and control, helping to build biceps and forearm strength.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1414.gif","youtube_id":null,"instructions":["Sit on a preacher bench with your chest against the pad and your arm extended over the edge of the bench, holding a dumbbell with an underhand grip.","Lower the dumbbell slowly until your arm is fully extended.","Curl the dumbbell back up towards your shoulder, keeping your upper arm stationary.","Squeeze your biceps at the top of the movement, then slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch arms."]},{"id":"1415","name":"dumbbell one arm seated neutral wrist curl","body_part":"lower arms","target":"forearms","secondary_muscles":["biceps","brachialis"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell one arm seated neutral wrist curl is an isolation exercise targeting the forearm muscles, particularly the wrist flexors. It is performed seated, with the forearm resting on the thigh and the wrist curling a dumbbell upward.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1415.gif","youtube_id":null,"instructions":["Sit on a bench with your feet flat on the ground and hold a dumbbell in one hand, palm facing up.","Rest your forearm on your thigh, allowing your wrist to hang off the edge.","Keeping your forearm stationary, curl your wrist upward as far as possible.","Pause for a moment at the top, then slowly lower your wrist back down to the starting position.","Repeat for the desired number of repetitions, then switch to the other hand."]},{"id":"1416","name":"exercise ball one leg prone lower body rotation","body_part":"upper legs","target":"glutes","secondary_muscles":["hamstrings","quadriceps","core"],"equipment":"stability ball","difficulty":"intermediate","description":"This exercise involves lying face down on a stability ball and performing one-leg lower body rotations, targeting the glutes and engaging the core for stabilization.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1416.gif","youtube_id":null,"instructions":["Lie face down on the stability ball with your hips resting on the ball and your legs extended straight behind you.","Place your hands on the ground in front of you for support.","Engage your glutes and core muscles to stabilize your body.","Slowly lift one leg off the ground, keeping it straight and parallel to the floor.","Rotate your leg outward, away from your body, while keeping your hips and upper body stable.","Pause for a moment at the end of the rotation, then slowly return your leg to the starting position.","Repeat the rotation with the other leg.","Continue alternating legs for the desired number of repetitions."]},{"id":"1417","name":"exercise ball one legged diagonal kick hamstring curl","body_part":"upper legs","target":"glutes","secondary_muscles":["hamstrings","calves"],"equipment":"stability ball","difficulty":"advanced","description":"This exercise targets the glutes and also works the hamstrings and calves. It requires balance and coordination as you perform a single-leg hamstring curl and diagonal kick on a stability ball.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1417.gif","youtube_id":null,"instructions":["Start by lying on your back with your legs extended and your heels resting on top of the stability ball.","Place your arms by your sides for stability.","Engage your glutes and core muscles to lift your hips off the ground, creating a straight line from your shoulders to your heels.","Bend your right knee and bring it towards your chest, keeping your left leg extended and your foot flexed.","Kick your right leg diagonally across your body, extending it fully and engaging your hamstrings.","Slowly return your right leg to the starting position, maintaining control and stability.","Repeat the movement with your left leg, alternating sides for the desired number of repetitions."]},{"id":"1418","name":"hug knees to chest","body_part":"upper legs","target":"glutes","secondary_muscles":["hamstrings","quadriceps"],"equipment":"body weight","difficulty":"beginner","description":"The 'hug knees to chest' exercise is a bodyweight movement that involves squatting down and hugging your knees to your chest, targeting the glutes and also engaging the hamstrings and quadriceps.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1418.gif","youtube_id":null,"instructions":["Start by standing with your feet shoulder-width apart.","Bend your knees and lower your body down into a squat position.","As you squat down, bring your knees up towards your chest and hug them with your arms.","Hold this position for a moment, then slowly return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1419","name":"iron cross stretch","body_part":"upper legs","target":"glutes","secondary_muscles":["hamstrings","quadriceps"],"equipment":"body weight","difficulty":"beginner","description":"The iron cross stretch is a dynamic movement that targets the glutes and also stretches the hamstrings and quadriceps. It involves lying on your back, raising your legs, and rotating them side to side to touch the floor, promoting flexibility and mobility in the hips and lower back.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1419.gif","youtube_id":null,"instructions":["Lie flat on your back with your arms extended out to the sides.","Raise your legs up towards the ceiling, keeping them straight.","Slowly lower your legs to one side, aiming to touch the floor with your feet.","Hold the stretch for a few seconds, then return your legs to the starting position.","Repeat the stretch on the other side.","Continue alternating sides for the desired number of repetitions."]},{"id":"1420","name":"kneeling jump squat","body_part":"upper legs","target":"glutes","secondary_muscles":["quadriceps","hamstrings","calves"],"equipment":"barbell","difficulty":"advanced","description":"The kneeling jump squat is a dynamic lower body exercise that targets the glutes and also works the quadriceps, hamstrings, and calves. It involves starting from a kneeling position and explosively jumping into the air while holding a barbell across the upper back.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1420.gif","youtube_id":null,"instructions":["Start by kneeling on the ground with your feet hip-width apart and your toes pointing forward.","Hold a barbell across your upper back, resting it on your shoulders.","Engage your core and glutes, then explosively jump up into the air, extending your hips and knees.","As you jump, push through your toes and fully extend your ankles, knees, and hips.","Land softly back on the ground, bending your knees to absorb the impact.","Immediately go into the next repetition, repeating the jump squat motion."]},{"id":"1421","name":"modified push up to lower arms","body_part":"lower arms","target":"forearms","secondary_muscles":["triceps","chest","shoulders"],"equipment":"body weight","difficulty":"intermediate","description":"The modified push up to lower arms is a bodyweight exercise targeting the forearms, with secondary emphasis on the triceps, chest, and shoulders. It involves transitioning from a push-up position to lowering the forearms to the ground and then pressing back up.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1421.gif","youtube_id":null,"instructions":["Start in a push-up position with your hands directly under your shoulders and your body in a straight line.","Lower your body down towards the ground by bending your elbows, keeping them close to your sides.","Once your elbows are at a 90-degree angle, lower your forearms to the ground, keeping your elbows directly under your shoulders.","Pause for a moment, then push through your palms to lift your forearms back up to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1422","name":"pelvic tilt into bridge","body_part":"upper legs","target":"glutes","secondary_muscles":["hamstrings","core"],"equipment":"body weight","difficulty":"beginner","description":"The pelvic tilt into bridge is a bodyweight exercise that targets the glutes, while also engaging the hamstrings and core. It involves tilting the pelvis and lifting the hips off the ground to form a bridge, then lowering back down.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1422.gif","youtube_id":null,"instructions":["Lie on your back with your knees bent and feet flat on the ground.","Place your arms by your sides with your palms facing down.","Engage your glutes and core muscles.","Tilt your pelvis upward, lifting your hips off the ground.","Hold the bridge position for a few seconds.","Slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1423","name":"reverse hyper on flat bench","body_part":"upper legs","target":"glutes","secondary_muscles":["hamstrings","lower back"],"equipment":"body weight","difficulty":"beginner","description":"The reverse hyper on flat bench is a bodyweight exercise targeting the glutes, with secondary emphasis on the hamstrings and lower back. It involves lying face down on a flat bench and lifting the legs upward, focusing on squeezing the glutes at the top of the movement.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1423.gif","youtube_id":null,"instructions":["Lie face down on a flat bench with your hips at the edge and your legs hanging off the bench.","Hold onto the bench for stability.","Keeping your legs straight, raise them up towards the ceiling as high as you can.","Squeeze your glutes at the top of the movement.","Slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1424","name":"seated glute stretch","body_part":"upper legs","target":"glutes","secondary_muscles":["hamstrings"],"equipment":"body weight","difficulty":"beginner","description":"The seated glute stretch is a flexibility exercise targeting the gluteal muscles. It is performed seated on the ground, crossing one ankle over the opposite thigh and gently pressing down on the knee to deepen the stretch. This exercise helps improve hip mobility and relieve tension in the glutes and hamstrings.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1424.gif","youtube_id":null,"instructions":["Sit on the ground with your legs extended in front of you.","Bend your right knee and cross your right ankle over your left thigh.","Place your right hand on the ground behind you for support.","With your left hand, gently press down on your right knee to deepen the stretch.","Hold the stretch for 30 seconds to 1 minute.","Switch sides and repeat."]},{"id":"1425","name":"sled 45 degrees one leg press","body_part":"upper legs","target":"glutes","secondary_muscles":["quadriceps","hamstrings","calves"],"equipment":"sled machine","difficulty":"intermediate","description":"The sled 45 degrees one leg press is a lower body exercise performed on a sled machine at a 45-degree angle, focusing on one leg at a time to target the glutes, quadriceps, hamstrings, and calves. It helps build unilateral leg strength and muscle balance.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1425.gif","youtube_id":null,"instructions":["Adjust the sled machine to a 45-degree angle.","Sit on the sled machine with your back against the pad and your feet on the footplate.","Place one foot on the footplate and extend your leg, pushing the sled away from you.","Slowly bend your knee and lower the sled back to the starting position.","Repeat with the other leg.","Continue alternating legs for the desired number of repetitions."]},{"id":"1426","name":"smith seated wrist curl","body_part":"lower arms","target":"forearms","secondary_muscles":["biceps","brachialis"],"equipment":"smith machine","difficulty":"beginner","description":"The smith seated wrist curl is an isolation exercise targeting the forearms, performed using a Smith machine. It involves curling the wrists upward while seated, with the forearms resting on the thighs.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1426.gif","youtube_id":null,"instructions":["Sit on a bench in front of a Smith machine with your feet flat on the ground.","Grasp the barbell with an underhand grip, hands shoulder-width apart.","Rest your forearms on your thighs, allowing your wrists to hang off.","Slowly curl your wrists upward, bringing the barbell towards your forearms.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1427","name":"straight leg outer hip abductor","body_part":"upper legs","target":"abductors","secondary_muscles":["glutes","hamstrings"],"equipment":"body weight","difficulty":"beginner","description":"The straight leg outer hip abductor is a bodyweight exercise performed lying on your side, targeting the hip abductor muscles. It helps strengthen the outer thighs and hips, and also engages the glutes and hamstrings.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1427.gif","youtube_id":null,"instructions":["Lie on your side with your legs straight and stacked on top of each other.","Place your bottom arm under your head for support.","Engage your core and lift your top leg as high as possible without rotating your hips or leaning backward.","Pause for a moment at the top, then slowly lower your leg back down to the starting position.","Repeat for the desired number of repetitions, then switch sides."]},{"id":"1428","name":"wrist circles","body_part":"lower arms","target":"forearms","secondary_muscles":["hands","wrists"],"equipment":"body weight","difficulty":"beginner","description":"Wrist circles are a bodyweight exercise focused on improving mobility and flexibility in the wrists and forearms. This movement is commonly used as a warm-up or rehabilitation exercise to increase blood flow and prepare the wrists for more strenuous activities.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1428.gif","youtube_id":null,"instructions":["Extend your arms straight out in front of you.","Make a fist with both hands.","Rotate your wrists in a circular motion, keeping your arms still.","Continue the wrist circles for the desired number of repetitions."]},{"id":"1429","name":"wide grip pull-up","body_part":"back","target":"lats","secondary_muscles":["biceps","forearms"],"equipment":"body weight","difficulty":"advanced","description":"The wide grip pull-up is a bodyweight exercise targeting the latissimus dorsi (lats) with significant involvement of the biceps and forearms. It requires hanging from a pull-up bar with a grip wider than shoulder-width, pulling the chin above the bar, and lowering back down with control.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1429.gif","youtube_id":null,"instructions":["Hang from a pull-up bar with your palms facing away from you and your hands wider than shoulder-width apart.","Engage your core and squeeze your shoulder blades together.","Pull your body up towards the bar until your chin is above the bar.","Lower your body back down to the starting position with control.","Repeat for the desired number of repetitions."]},{"id":"1430","name":"chest dip (on dip-pull-up cage)","body_part":"chest","target":"pectorals","secondary_muscles":["triceps","shoulders"],"equipment":"body weight","difficulty":"advanced","description":"The chest dip (on dip-pull-up cage) is a bodyweight exercise targeting the pectoral muscles, with secondary emphasis on the triceps and shoulders. It involves supporting your body weight on parallel bars, lowering yourself by bending your elbows, and then pushing back up.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1430.gif","youtube_id":null,"instructions":["Adjust the dip bars to a height that allows you to comfortably grip them.","Stand between the bars and place your hands on each bar, slightly wider than shoulder-width apart.","Jump up and straighten your arms, supporting your body weight on the bars.","Bend your knees and cross your ankles behind you.","Lower your body by bending your elbows, keeping your chest up and your shoulders down.","Continue lowering until your shoulders are below your elbows or until you feel a stretch in your chest.","Push through your palms and extend your elbows to raise your body back up to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1431","name":"assisted standing chin-up","body_part":"back","target":"lats","secondary_muscles":["biceps","forearms"],"equipment":"leverage machine","difficulty":"beginner","description":"The assisted standing chin-up is a machine-based exercise that helps users perform chin-ups with added support, making it easier to build strength in the lats, biceps, and forearms. The leverage machine reduces the amount of body weight lifted, allowing for proper form and gradual progression.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1431.gif","youtube_id":null,"instructions":["Adjust the machine to your desired assistance level.","Stand on the foot platform and grip the handles with an overhand grip, slightly wider than shoulder-width apart.","Keep your chest up and shoulders back, engage your core, and slightly bend your knees.","Pull your body up by flexing your elbows and driving your elbows down towards your sides.","Continue pulling until your chin is above the bar.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1432","name":"assisted standing pull-up","body_part":"back","target":"lats","secondary_muscles":["biceps","forearms"],"equipment":"leverage machine","difficulty":"beginner","description":"The assisted standing pull-up is a machine-based exercise targeting the latissimus dorsi (lats) with assistance to help perform the pull-up movement. It is suitable for those building strength to perform unassisted pull-ups.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1432.gif","youtube_id":null,"instructions":["Adjust the machine to your desired weight and height settings.","Stand facing the machine with your feet shoulder-width apart.","Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.","Engage your lats and biceps, and pull yourself up towards the handles.","Pause for a moment at the top, squeezing your back muscles.","Slowly lower yourself back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1433","name":"smith front squat (clean grip)","body_part":"upper legs","target":"glutes","secondary_muscles":["quadriceps","hamstrings","calves","core"],"equipment":"smith machine","difficulty":"intermediate","description":"The smith front squat (clean grip) is a lower body exercise performed on a smith machine, targeting the glutes with significant involvement from the quadriceps, hamstrings, calves, and core. The clean grip requires good shoulder and wrist mobility, and the movement demands proper technique to maintain balance and safety.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1433.gif","youtube_id":null,"instructions":["Set up the smith machine with the barbell at shoulder height.","Stand facing the barbell with your feet shoulder-width apart.","Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.","Step back and position the barbell on your front shoulders, resting it on your collarbone and deltoids.","Keep your chest up, back straight, and core engaged.","Lower your body by bending at the knees and hips, as if sitting back into a chair.","Continue lowering until your thighs are parallel to the ground or slightly below.","Pause for a moment, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1434","name":"smith low bar squat","body_part":"upper legs","target":"glutes","secondary_muscles":["quadriceps","hamstrings","calves"],"equipment":"smith machine","difficulty":"intermediate","description":"The smith low bar squat is a compound lower body exercise performed on a smith machine, targeting the glutes as the primary muscle group, with secondary emphasis on the quadriceps, hamstrings, and calves. The smith machine provides stability, making it accessible for those learning squat mechanics while still offering a challenging strength workout.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1434.gif","youtube_id":null,"instructions":["Set up the smith machine with the barbell at a height that allows you to comfortably rest it on your upper back.","Stand with your feet shoulder-width apart, toes slightly turned outwards.","Step under the bar and position it across your upper back, resting it on your traps.","Grip the bar with your hands slightly wider than shoulder-width apart.","Unrack the bar by straightening your legs and stepping back from the rack.","Take a deep breath and brace your core.","Initiate the squat by pushing your hips back and bending your knees.","Lower your body until your thighs are parallel to the ground or slightly below.","Keep your chest up and your back straight throughout the movement.","Drive through your heels to stand back up, extending your hips and knees.","Repeat for the desired number of repetitions."]},{"id":"1435","name":"barbell low bar squat","body_part":"upper legs","target":"glutes","secondary_muscles":["quadriceps","hamstrings","calves"],"equipment":"barbell","difficulty":"intermediate","description":"The barbell low bar squat is a compound lower body exercise that targets the glutes, with significant involvement of the quadriceps, hamstrings, and calves. It is performed with a barbell positioned lower on the back (across the rear deltoids), requiring good technique, core stability, and hip mobility.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1435.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and the barbell resting on your upper back.","Keeping your chest up and core engaged, slowly lower your body by bending your knees and pushing your hips back.","Continue lowering until your thighs are parallel to the ground or slightly below.","Pause for a moment, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1436","name":"barbell high bar squat","body_part":"upper legs","target":"glutes","secondary_muscles":["quadriceps","hamstrings","calves","core"],"equipment":"barbell","difficulty":"intermediate","description":"The barbell high bar squat is a compound lower body exercise that primarily targets the glutes, with significant involvement from the quadriceps, hamstrings, calves, and core. It requires placing a barbell on the upper back (traps) and performing a squat movement.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1436.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, toes slightly turned out.","Place the barbell on your upper back, resting it on your traps.","Engage your core and keep your chest up as you begin to squat down, pushing your hips back and bending your knees.","Lower yourself until your thighs are parallel to the ground, or as low as you can comfortably go.","Drive through your heels to stand back up, extending your hips and knees.","Repeat for the desired number of repetitions."]},{"id":"1437","name":"dumbbell finger curls","body_part":"lower arms","target":"forearms","secondary_muscles":["wrist flexors","wrist extensors"],"equipment":"dumbbell","difficulty":"beginner","description":"Dumbbell finger curls are an isolation exercise targeting the forearms, specifically the muscles responsible for finger flexion. This exercise helps improve grip strength and forearm development.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1437.gif","youtube_id":null,"instructions":["Sit on a bench or chair with your feet flat on the ground and your back straight.","Hold a dumbbell in one hand with an underhand grip, resting your forearm on your thigh, palm facing up.","Allow the dumbbell to roll down to your fingertips, then curl it back up by flexing your fingers.","Repeat for the desired number of repetitions, then switch to the other hand."]},{"id":"1438","name":"kettlebell seated two arm military press","body_part":"shoulders","target":"delts","secondary_muscles":["triceps","upper back"],"equipment":"kettlebell","difficulty":"intermediate","description":"The kettlebell seated two arm military press is a shoulder exercise performed while seated, pressing two kettlebells overhead to target the deltoids, with secondary emphasis on the triceps and upper back.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1438.gif","youtube_id":null,"instructions":["Sit on a bench with your back straight and feet flat on the ground.","Hold a kettlebell in each hand at shoulder level with your palms facing forward.","Press the kettlebells overhead by extending your arms fully.","Pause for a moment at the top, then slowly lower the kettlebells back to shoulder level.","Repeat for the desired number of repetitions."]},{"id":"1439","name":"lever gripless shrug v. 2","body_part":"back","target":"traps","secondary_muscles":["shoulders","forearms"],"equipment":"leverage machine","difficulty":"beginner","description":"The lever gripless shrug v. 2 is performed on a leverage machine and targets the trapezius muscles. It involves elevating the shoulders while keeping the arms straight, focusing on the upper back and traps.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1439.gif","youtube_id":null,"instructions":["Adjust the seat height and position yourself on the machine with your back against the pad.","Grasp the handles or bars with an overhand grip, keeping your arms straight.","Keeping your back straight, lift your shoulders up towards your ears as high as possible.","Hold the contraction for a moment, then slowly lower your shoulders back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1441","name":"dumbbell over bench one arm reverse wrist curl","body_part":"lower arms","target":"forearms","secondary_muscles":["biceps","brachialis"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell over bench one arm reverse wrist curl targets the forearms, specifically the extensors, and is performed by curling the wrist upwards while the forearm is supported on a bench.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1441.gif","youtube_id":null,"instructions":["Sit on a bench with your feet flat on the ground and hold a dumbbell in one hand, palm facing down.","Rest your forearm on the bench with your wrist hanging off the edge.","Slowly curl your wrist upwards, bringing the dumbbell towards your forearm.","Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]},{"id":"1451","name":"lever seated dip","body_part":"upper arms","target":"triceps","secondary_muscles":["chest","shoulders"],"equipment":"leverage machine","difficulty":"beginner","description":"The lever seated dip is a machine-based exercise targeting the triceps, with secondary emphasis on the chest and shoulders. It involves pressing down on handles while seated, simulating a dip movement in a controlled environment.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1451.gif","youtube_id":null,"instructions":["Adjust the seat height so that your feet are flat on the ground and your knees are at a 90-degree angle.","Grasp the handles of the leverage machine with your palms facing down and your arms fully extended.","Slowly lower your body by bending your elbows until your upper arms are parallel to the ground.","Pause for a moment, then push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."]},{"id":"1452","name":"lever seated crunch","body_part":"waist","target":"abs","secondary_muscles":["obliques"],"equipment":"leverage machine","difficulty":"beginner","description":"The lever seated crunch is an abdominal exercise performed on a leverage machine. It targets the abs and also engages the obliques. The movement involves crunching forward against resistance, making it a controlled and effective core strengthening exercise.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1452.gif","youtube_id":null,"instructions":["Sit on the leverage machine with your back against the pad and your feet flat on the floor.","Grasp the handles or place your hands on the side pads for support.","Engage your abs and slowly lean back, allowing the pad to move with you.","Once your upper body is at a 45-degree angle, contract your abs and crunch forward, bringing your chest towards your knees.","Pause for a moment at the top, then slowly release and return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1456","name":"barbell standing close grip military press","body_part":"shoulders","target":"delts","secondary_muscles":["triceps","upper back"],"equipment":"barbell","difficulty":"intermediate","description":"The barbell standing close grip military press is a compound strength exercise targeting the deltoids, with secondary emphasis on the triceps and upper back. It is performed by pressing a barbell overhead from shoulder height with a close grip, requiring core stability and shoulder strength.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1456.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and hold the barbell with an overhand grip, hands slightly closer than shoulder-width apart.","Lift the barbell to shoulder height, keeping your elbows close to your body.","Press the barbell overhead, extending your arms fully.","Lower the barbell back to shoulder height.","Repeat for the desired number of repetitions."]},{"id":"1457","name":"barbell standing wide military press","body_part":"shoulders","target":"delts","secondary_muscles":["triceps","upper back"],"equipment":"barbell","difficulty":"intermediate","description":"The barbell standing wide military press is a compound exercise that targets the deltoid muscles of the shoulders. It also engages the triceps and upper back as secondary muscles. The movement requires pressing a barbell overhead from shoulder height while standing, with a grip wider than shoulder-width.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1457.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and hold the barbell with an overhand grip, slightly wider than shoulder-width.","Lift the barbell to shoulder height, keeping your elbows slightly in front of the bar.","Press the barbell overhead, extending your arms fully.","Lower the barbell back to shoulder height and repeat for the desired number of repetitions."]},{"id":"1458","name":"ez barbell seated curls","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"ez barbell","difficulty":"beginner","description":"The EZ barbell seated curl is an isolation exercise targeting the biceps, performed while seated to minimize body movement and focus on the arms. It uses an EZ barbell, which is easier on the wrists than a straight bar.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1458.gif","youtube_id":null,"instructions":["Sit on a bench with your feet flat on the ground and your back straight.","Hold the ez barbell with an underhand grip, palms facing up, and your hands shoulder-width apart.","Rest your upper arms on your thighs, allowing the ez barbell to hang down in front of you.","Keeping your upper arms stationary, exhale and curl the ez barbell upwards towards your shoulders.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the ez barbell back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1459","name":"dumbbell romanian deadlift","body_part":"upper legs","target":"glutes","secondary_muscles":["hamstrings","lower back"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell Romanian deadlift is a strength exercise targeting the glutes, hamstrings, and lower back. It involves hinging at the hips while holding dumbbells, emphasizing posterior chain development and hip hinge mechanics.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1459.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.","Keeping your back straight and your core engaged, hinge at the hips and lower the dumbbells towards the ground, allowing your knees to bend slightly.","Lower the dumbbells until you feel a stretch in your hamstrings, then push through your heels and engage your glutes to return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1460","name":"walking lunge","body_part":"upper legs","target":"glutes","secondary_muscles":["quadriceps","hamstrings","calves"],"equipment":"body weight","difficulty":"intermediate","description":"The walking lunge is a bodyweight exercise that targets the glutes while also engaging the quadriceps, hamstrings, and calves. It involves stepping forward into a lunge and alternating legs as you walk forward, requiring balance, coordination, and lower body strength.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1460.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart.","Take a step forward with your right leg, lowering your body into a lunge position.","Keep your torso upright and your front knee aligned with your ankle.","Push off with your right foot and bring your left foot forward, stepping into a lunge position with your left leg.","Continue alternating legs and walking forward, maintaining a controlled and steady pace.","Repeat for the desired number of repetitions."]},{"id":"1461","name":"barbell full squat (back pov)","body_part":"upper legs","target":"glutes","secondary_muscles":["quadriceps","hamstrings","calves","core"],"equipment":"barbell","difficulty":"intermediate","description":"The barbell full squat (back POV) is a compound lower body exercise that targets the glutes, quadriceps, hamstrings, calves, and core. It involves holding a barbell across the upper back and performing a deep squat, requiring strength, balance, and proper technique.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1461.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, toes slightly turned out.","Hold the barbell across your upper back, resting it on your traps or rear delts.","Engage your core and keep your chest up as you begin to lower your body down.","Bend at the knees and hips, pushing your hips back and down as if sitting into a chair.","Lower your body until your thighs are parallel to the ground or slightly below.","Keep your knees in line with your toes and your weight in your heels.","Drive through your heels to stand back up, extending your hips and knees.","Repeat for the desired number of repetitions."]},{"id":"1462","name":"barbell full squat (side pov)","body_part":"upper legs","target":"glutes","secondary_muscles":["quadriceps","hamstrings","calves","core"],"equipment":"barbell","difficulty":"intermediate","description":"The barbell full squat (side POV) is a compound lower body exercise that targets the glutes, quadriceps, and hamstrings, while also engaging the calves and core for stability. It involves lowering the body with a barbell across the upper back and then driving back up to a standing position.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1462.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, toes slightly turned out.","Hold the barbell across your upper back, resting it on your traps or rear delts.","Engage your core and keep your chest up as you begin to lower your body down.","Bend at the knees and hips, pushing your hips back and down as if sitting into a chair.","Lower your body until your thighs are parallel to the ground or slightly below.","Keep your knees in line with your toes and your weight in your heels.","Drive through your heels to stand back up, extending your hips and knees.","Repeat for the desired number of repetitions."]},{"id":"1463","name":"sled 45° leg press (side pov)","body_part":"upper legs","target":"glutes","secondary_muscles":["quadriceps","hamstrings","calves"],"equipment":"sled machine","difficulty":"beginner","description":"The sled 45° leg press (side pov) is a compound lower body exercise performed on a sled machine. It primarily targets the glutes and also works the quadriceps, hamstrings, and calves. The movement involves pressing a weighted footplate away from the body by extending the legs, then returning to the starting position by bending the knees.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1463.gif","youtube_id":null,"instructions":["Adjust the seat of the sled machine so that your knees are at a 90-degree angle when your feet are on the footplate.","Sit on the sled machine with your back flat against the backrest and your feet shoulder-width apart on the footplate.","Grip the handles on the sides of the seat for stability.","Push against the footplate to extend your legs, straightening them completely.","Pause for a moment at the top, then slowly bend your knees to lower the footplate back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1464","name":"sled 45° leg press (back pov)","body_part":"upper legs","target":"glutes","secondary_muscles":["quadriceps","hamstrings","calves"],"equipment":"sled machine","difficulty":"beginner","description":"The sled 45° leg press (back POV) is a compound lower body exercise performed on a sled machine. It primarily targets the glutes, with secondary emphasis on the quadriceps, hamstrings, and calves. The movement involves extending and flexing the legs to press a weighted footplate away from and toward the body.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1464.gif","youtube_id":null,"instructions":["Adjust the seat of the sled machine so that your knees are at a 45-degree angle.","Sit on the sled machine with your back against the backrest and your feet shoulder-width apart on the footplate.","Grip the handles on the sides of the seat for stability.","Push the footplate away from your body by extending your legs, keeping your heels on the footplate.","Pause for a moment at the fully extended position.","Slowly bend your knees and lower the footplate back towards your body, controlling the movement.","Repeat for the desired number of repetitions."]},{"id":"1466","name":"twist hip lift","body_part":"upper legs","target":"glutes","secondary_muscles":["obliques","hamstrings"],"equipment":"body weight","difficulty":"intermediate","description":"The twist hip lift is a bodyweight exercise targeting the glutes, with additional engagement of the obliques and hamstrings. It involves lifting the hips off the ground and twisting the lower body side to side, challenging core stability and hip strength.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1466.gif","youtube_id":null,"instructions":["Lie on your back with your knees bent and feet flat on the ground.","Place your hands by your sides for support.","Engage your glutes and lift your hips off the ground, forming a straight line from your knees to your shoulders.","While keeping your hips lifted, twist your lower body to the right side, bringing your knees towards the ground.","Return to the starting position and repeat the twist to the left side.","Continue alternating twists for the desired number of repetitions."]},{"id":"1467","name":"push-up on lower arms","body_part":"upper arms","target":"triceps","secondary_muscles":["chest","shoulders"],"equipment":"body weight","difficulty":"intermediate","description":"The push-up on lower arms is a bodyweight exercise targeting the triceps, performed from a plank position on the forearms. It also engages the chest and shoulders.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1467.gif","youtube_id":null,"instructions":["Start in a plank position with your forearms on the ground and elbows directly below your shoulders.","Engage your core and keep your body in a straight line from head to toe.","Lower your chest towards the ground by bending your elbows, keeping them close to your body.","Pause for a moment at the bottom, then push yourself back up to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1468","name":"crab twist toe touch","body_part":"waist","target":"abs","secondary_muscles":["obliques","hip flexors"],"equipment":"body weight","difficulty":"intermediate","description":"The crab twist toe touch is a bodyweight exercise targeting the abdominal muscles, with additional engagement of the obliques and hip flexors. It involves a dynamic movement pattern that requires coordination and balance, as you alternate reaching your hand to the opposite foot while supporting your body in a crab position.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1468.gif","youtube_id":null,"instructions":["Start by sitting on the ground with your knees bent and feet flat on the floor.","Place your hands behind you, fingers pointing towards your feet, and lift your hips off the ground.","Extend one leg straight out in front of you while simultaneously reaching your opposite hand towards your toes.","Return to the starting position and repeat on the other side.","Continue alternating sides for the desired number of repetitions."]},{"id":"1471","name":"inchworm","body_part":"waist","target":"abs","secondary_muscles":["shoulders","hamstrings"],"equipment":"body weight","difficulty":"beginner","description":"The inchworm is a bodyweight exercise that targets the abs while also engaging the shoulders and hamstrings. It involves bending forward, walking your hands out to a plank, and then returning to standing, which challenges core stability, flexibility, and coordination.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1471.gif","youtube_id":null,"instructions":["Start in a standing position with your feet hip-width apart.","Bend forward at the waist and place your hands on the ground in front of you.","Walk your hands forward until you are in a high plank position, with your body in a straight line from head to toe.","Pause for a moment, then walk your hands back towards your feet, keeping your legs as straight as possible.","Once your hands reach your feet, stand back up to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1472","name":"forward jump","body_part":"upper legs","target":"quads","secondary_muscles":["calves","hamstrings","glutes"],"equipment":"body weight","difficulty":"intermediate","description":"The forward jump is a plyometric exercise that targets the quadriceps and also works the calves, hamstrings, and glutes. It involves jumping forward explosively from a squat position and landing softly, then repeating the movement.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1472.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart.","Bend your knees and lower your body into a squat position.","Swing your arms back for momentum.","Jump forward explosively, extending your hips, knees, and ankles.","Land softly on the balls of your feet and immediately go into the next jump.","Repeat for the desired number of repetitions."]},{"id":"1473","name":"backward jump","body_part":"upper legs","target":"quads","secondary_muscles":["hamstrings","glutes","calves"],"equipment":"body weight","difficulty":"intermediate","description":"The backward jump is a plyometric exercise that targets the quadriceps while also engaging the hamstrings, glutes, and calves. It involves jumping backward from a standing position, requiring coordination, balance, and explosive power.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1473.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart.","Bend your knees slightly and jump backwards, pushing off with both feet.","Land softly on the balls of your feet, bending your knees to absorb the impact.","Repeat for the desired number of repetitions."]},{"id":"1476","name":"one leg squat","body_part":"upper legs","target":"glutes","secondary_muscles":["quadriceps","hamstrings","calves"],"equipment":"body weight","difficulty":"advanced","description":"The one leg squat, also known as a pistol squat, is a challenging lower body exercise that targets the glutes while also engaging the quadriceps, hamstrings, and calves. It requires significant balance, strength, and coordination, as you lower your body on one leg while keeping the other leg extended off the ground.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1476.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart.","Extend one leg forward, keeping it off the ground.","Bend your standing leg and lower your body down as if sitting back into a chair.","Keep your chest up and your back straight.","Push through your heel to return to the starting position.","Repeat with the other leg."]},{"id":"1479","name":"lever incline chest press v. 2","body_part":"chest","target":"pectorals","secondary_muscles":["triceps","shoulders"],"equipment":"leverage machine","difficulty":"beginner","description":"The lever incline chest press v. 2 is a machine-based exercise that targets the pectoral muscles, with secondary emphasis on the triceps and shoulders. It involves pressing handles away from the body while seated on a leverage machine, simulating an incline bench press motion.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1479.gif","youtube_id":null,"instructions":["Adjust the seat height and backrest angle on the leverage machine to a comfortable position.","Sit on the machine with your back against the backrest and your feet flat on the floor.","Grasp the handles with an overhand grip and position your hands slightly wider than shoulder-width apart.","Push the handles forward and away from your body until your arms are fully extended, but without locking your elbows.","Pause for a moment at the fully extended position, then slowly bend your elbows and lower the handles back towards your chest.","Repeat for the desired number of repetitions."]},{"id":"148","name":"cable alternate shoulder press","body_part":"shoulders","target":"delts","secondary_muscles":["triceps","upper back"],"equipment":"cable","difficulty":"intermediate","description":"The cable alternate shoulder press is a strength exercise targeting the deltoid muscles. It involves pressing one cable handle overhead at a time, alternating arms, and requires stability and coordination.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0148.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and grasp the handles of the cable machine with an overhand grip.","Position your hands at shoulder height, with your palms facing forward.","Keep your core engaged and your back straight.","Press one handle up and forward until your arm is fully extended.","Pause for a moment at the top, then slowly lower the handle back to the starting position.","Repeat with the other arm.","Alternate between arms for the desired number of repetitions."]},{"id":"1489","name":"sissy squat","body_part":"upper legs","target":"quads","secondary_muscles":["calves","glutes"],"equipment":"body weight","difficulty":"advanced","description":"The sissy squat is a challenging bodyweight exercise that targets the quadriceps by requiring a deep knee bend and significant balance, often performed with minimal support. It emphasizes quad strength and control, while also engaging the calves and glutes.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1489.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and your toes pointing slightly outward.","Hold onto a stable object for balance if needed.","Slowly lower your body by bending your knees and leaning back, keeping your torso upright.","Continue lowering until your thighs are parallel to the ground or as far as you can comfortably go.","Pause for a moment, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"149","name":"cable alternate triceps extension","body_part":"upper arms","target":"triceps","secondary_muscles":["shoulders"],"equipment":"cable","difficulty":"intermediate","description":"The cable alternate triceps extension is an isolation exercise targeting the triceps using a cable machine. It involves extending the arm at the elbow while keeping the upper arm stationary, alternating between arms.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0149.gif","youtube_id":null,"instructions":["Stand facing the cable machine with your feet shoulder-width apart.","Hold the cable handle with your right hand and bring your arm up so that your upper arm is parallel to the ground and your elbow is bent at a 90-degree angle.","Keep your upper arm stationary and extend your forearm backward, fully straightening your arm.","Pause for a moment, then slowly return to the starting position.","Repeat with your left arm.","Continue alternating arms for the desired number of repetitions."]},{"id":"1490","name":"standing calf raise (on a staircase)","body_part":"lower legs","target":"calves","secondary_muscles":["ankles","feet"],"equipment":"body weight","difficulty":"beginner","description":"The standing calf raise (on a staircase) is a bodyweight exercise that targets the calves by raising and lowering the heels while standing on the edge of a step. It also engages the ankles and feet for stabilization.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1490.gif","youtube_id":null,"instructions":["Stand on the edge of a step or a sturdy platform with your heels hanging off and your toes on the step.","Hold onto a railing or wall for balance if needed.","Slowly raise your heels as high as possible, lifting your body weight onto the balls of your feet.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1494","name":"butterfly yoga pose","body_part":"upper legs","target":"adductors","secondary_muscles":["hamstrings","groin"],"equipment":"body weight","difficulty":"beginner","description":"The butterfly yoga pose is a seated stretch that targets the adductors and inner thighs. It is commonly used to improve flexibility and mobility in the hips and groin area.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1494.gif","youtube_id":null,"instructions":["Sit on the floor with your legs extended in front of you.","Bend your knees and bring the soles of your feet together, allowing your knees to fall out to the sides.","Hold onto your ankles or feet with your hands.","Sit up tall and lengthen your spine.","Gently press your knees down towards the floor, feeling a stretch in your inner thighs.","Hold this position for a few breaths.","To release, slowly bring your knees back up and extend your legs."]},{"id":"1495","name":"oblique crunch v. 2","body_part":"waist","target":"abs","secondary_muscles":["obliques"],"equipment":"body weight","difficulty":"beginner","description":"The oblique crunch v. 2 is a bodyweight exercise targeting the abdominal muscles, with a focus on the obliques. It involves a rotational crunch movement to engage the side muscles of the core.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1495.gif","youtube_id":null,"instructions":["Lie on your back with your knees bent and feet flat on the ground.","Place your hands behind your head or cross them over your chest.","Engage your abs and lift your shoulder blades off the ground, rotating your torso to one side.","Pause for a moment, then lower your shoulder blades back down to the starting position.","Repeat on the other side.","Continue alternating sides for the desired number of repetitions."]},{"id":"1496","name":"sledge hammer","body_part":"waist","target":"abs","secondary_muscles":["forearms","shoulders"],"equipment":"hammer","difficulty":"intermediate","description":"The sledge hammer exercise involves swinging a sledge hammer down towards the ground, engaging the core, forearms, and shoulders. It requires coordination, strength, and proper technique to perform safely.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1496.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and hold the sledge hammer with both hands.","Engage your core and keep your back straight.","Swing the sledge hammer down towards the ground, using your core and upper body strength.","As you swing down, pivot your hips and transfer the force to the hammer.","Repeat for the desired number of repetitions."]},{"id":"15","name":"assisted parallel close grip pull-up","body_part":"back","target":"lats","secondary_muscles":["biceps","forearms"],"equipment":"leverage machine","difficulty":"beginner","description":"The assisted parallel close grip pull-up is a back exercise performed on a leverage machine that helps users perform pull-ups with added support, making it easier to complete the movement and focus on form.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0015.gif","youtube_id":null,"instructions":["Adjust the machine to your desired weight and height.","Place your hands on the parallel bars with a close grip, palms facing each other.","Hang from the bars with your arms fully extended and your feet off the ground.","Engage your back muscles and pull your body up towards the bars, keeping your elbows close to your body.","Continue pulling until your chin is above the bars.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"150","name":"cable bar lateral pulldown","body_part":"back","target":"lats","secondary_muscles":["biceps","rhomboids","rear deltoids"],"equipment":"cable","difficulty":"beginner","description":"The cable bar lateral pulldown is a strength exercise targeting the latissimus dorsi (lats) using a cable machine and a straight bar attachment. It also engages the biceps, rhomboids, and rear deltoids. The movement involves pulling the bar down towards the chest while maintaining proper posture and control.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0150.gif","youtube_id":null,"instructions":["Adjust the cable pulley to a high position and attach a straight bar.","Sit facing the cable machine with your feet flat on the ground and your knees slightly bent.","Grasp the bar with an overhand grip, slightly wider than shoulder-width apart.","Lean back slightly and keep your chest up, maintaining a slight arch in your lower back.","Pull the bar down towards your chest, leading with your elbows and squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, then slowly return the bar to the starting position.","Repeat for the desired number of repetitions."]},{"id":"151","name":"cable bench press","body_part":"chest","target":"pectorals","secondary_muscles":["triceps","shoulders"],"equipment":"cable","difficulty":"intermediate","description":"The cable bench press is a chest exercise performed using a cable machine. It targets the pectoral muscles and also works the triceps and shoulders. The movement is similar to a traditional bench press but uses cables for constant tension throughout the range of motion.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0151.gif","youtube_id":null,"instructions":["Adjust the cable machine to chest height and attach the handles.","Stand facing away from the machine with your feet shoulder-width apart.","Grasp the handles with an overhand grip and step forward to create tension in the cables.","Position your feet firmly on the ground and engage your core.","Bend your elbows and bring your hands to shoulder level, keeping your elbows at a 90-degree angle.","Push the handles forward, extending your arms fully in front of you.","Pause for a moment, then slowly reverse the movement, bringing your hands back to shoulder level.","Repeat for the desired number of repetitions."]},{"id":"1511","name":"hamstring stretch","body_part":"upper legs","target":"hamstrings","secondary_muscles":["glutes"],"equipment":"body weight","difficulty":"beginner","description":"The hamstring stretch is a bodyweight exercise targeting the hamstrings and also engaging the glutes. It involves stepping forward, bending at the hips, and reaching toward the foot to stretch the back of the thigh.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1511.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart.","Step forward with your right foot and shift your weight onto your right leg.","Keeping your back straight, slowly bend forward at the hips, reaching towards your right foot with both hands.","Hold the stretch for 20-30 seconds, then return to the starting position.","Repeat on the other side."]},{"id":"1512","name":"all fours squad stretch","body_part":"upper legs","target":"quads","secondary_muscles":["hamstrings","glutes"],"equipment":"body weight","difficulty":"beginner","description":"The all fours squad stretch is a bodyweight exercise that targets the quadriceps, with secondary emphasis on the hamstrings and glutes. It is performed on all fours, extending one leg back and lowering the hips to stretch the quads.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1512.gif","youtube_id":null,"instructions":["Start on all fours with your hands directly under your shoulders and your knees directly under your hips.","Extend one leg straight back, keeping your knee bent and your foot flexed.","Slowly lower your hips towards the ground, feeling a stretch in your quads.","Hold this position for 20-30 seconds.","Switch legs and repeat the stretch on the other side."]},{"id":"152","name":"cable concentration extension (on knee)","body_part":"upper arms","target":"triceps","secondary_muscles":["forearms"],"equipment":"cable","difficulty":"beginner","description":"The cable concentration extension (on knee) is an isolation exercise targeting the triceps. It is performed seated, using a cable machine, with the working arm's elbow braced against the inside of the knee to stabilize the movement and focus on triceps extension.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0152.gif","youtube_id":null,"instructions":["Sit on a bench or chair with your knees bent and feet flat on the ground.","Hold the cable handle with your right hand and place your elbow on the inside of your right knee.","Extend your arm fully, keeping your elbow stationary and close to your knee.","Pause for a moment at the top, then slowly lower your arm back to the starting position.","Repeat for the desired number of repetitions, then switch sides."]},{"id":"153","name":"cable cross-over lateral pulldown","body_part":"back","target":"lats","secondary_muscles":["biceps","rhomboids","rear deltoids"],"equipment":"cable","difficulty":"intermediate","description":"The cable cross-over lateral pulldown is a cable machine exercise targeting the latissimus dorsi, with secondary emphasis on the biceps, rhomboids, and rear deltoids. It involves pulling cables down and across the body, requiring coordination and control.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0153.gif","youtube_id":null,"instructions":["Attach a cable handle to each side of a cable machine at shoulder height.","Stand in the middle of the machine with your feet shoulder-width apart.","Grasp the handles with an overhand grip and step back to create tension in the cables.","Lean forward slightly from the hips, keeping your back straight and your chest up.","Pull the handles down and across your body, squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, then slowly return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"154","name":"cable cross-over reverse fly","body_part":"shoulders","target":"delts","secondary_muscles":["rhomboids","trapezius"],"equipment":"cable","difficulty":"intermediate","description":"The cable cross-over reverse fly is an isolation exercise targeting the rear deltoids, with secondary emphasis on the rhomboids and trapezius. It is performed using a cable crossover machine and requires good posture, control, and coordination.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0154.gif","youtube_id":null,"instructions":["Attach a D-handle to each low pulley cable and stand in the middle of the cable crossover machine.","Grasp the handles with a pronated grip (palms facing down) and take a step forward, positioning your feet shoulder-width apart.","Bend your knees slightly and lean forward at the waist, keeping your back straight and your abs engaged.","With your arms extended out to the sides and slightly bent at the elbows, exhale and squeeze your shoulder blades together as you pull the cables back and upward in a reverse fly motion.","Pause for a moment at the peak contraction, then inhale and slowly return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1545","name":"barbell full zercher squat","body_part":"upper legs","target":"glutes","secondary_muscles":["quadriceps","hamstrings","calves","core"],"equipment":"barbell","difficulty":"advanced","description":"The barbell full Zercher squat is a compound lower body exercise where the barbell is held in the crooks of the elbows. It targets the glutes and also works the quadriceps, hamstrings, calves, and core. This squat variation requires significant core strength and stability due to the bar position.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1545.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and toes slightly turned out.","Hold the barbell in the crooks of your elbows, with your hands gripping the barbell for stability.","Engage your core and keep your chest lifted as you lower your hips back and down into a squat position.","Keep your knees in line with your toes and your weight in your heels.","Lower until your thighs are parallel to the ground, or as low as you can comfortably go.","Drive through your heels to stand back up, squeezing your glutes at the top of the movement.","Repeat for the desired number of repetitions."]},{"id":"1548","name":"chair leg extended stretch","body_part":"upper legs","target":"quads","secondary_muscles":["hamstrings","calves"],"equipment":"body weight","difficulty":"beginner","description":"A seated stretch targeting the quadriceps, performed by extending one leg while sitting on a chair and leaning forward to feel the stretch.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1548.gif","youtube_id":null,"instructions":["Sit on the edge of a chair with your back straight and feet flat on the ground.","Extend one leg straight out in front of you, keeping your heel on the ground.","Lean forward slightly, feeling a stretch in your quadriceps.","Hold this position for 20-30 seconds.","Switch legs and repeat the stretch."]},{"id":"155","name":"cable cross-over variation","body_part":"chest","target":"pectorals","secondary_muscles":["deltoids","triceps"],"equipment":"cable","difficulty":"intermediate","description":"The cable cross-over variation is a chest exercise performed using a cable machine. It targets the pectoral muscles and also engages the deltoids and triceps. The movement involves bringing the handles together in front of the chest while maintaining a slight bend in the elbows.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0155.gif","youtube_id":null,"instructions":["Adjust the cable pulleys to chest height.","Stand in the center of the cable machine with one foot in front of the other.","Grasp the handles with your palms facing down and your arms extended out to the sides.","Take a step forward, keeping your arms slightly bent.","With a slight bend in your elbows, bring your hands together in front of your chest.","Pause for a moment, then slowly return your arms back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1559","name":"exercise ball hip flexor stretch","body_part":"upper legs","target":"glutes","secondary_muscles":["quadriceps","hamstrings"],"equipment":"stability ball","difficulty":"beginner","description":"The exercise ball hip flexor stretch targets the glutes and stretches the hip flexors using a stability ball. It also involves the quadriceps and hamstrings as secondary muscles. The movement requires balance and flexibility, but is generally accessible to most people with basic coordination.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1559.gif","youtube_id":null,"instructions":["Place the stability ball on the ground and kneel in front of it.","Place your right foot on top of the stability ball, with your knee bent at a 90-degree angle.","Extend your left leg behind you, keeping it straight.","Lean forward, pushing your hips towards the stability ball, until you feel a stretch in your right hip flexor.","Hold the stretch for 20-30 seconds, then switch sides and repeat."]},{"id":"1560","name":"exercise ball seated hamstring stretch","body_part":"upper legs","target":"hamstrings","secondary_muscles":["glutes","lower back"],"equipment":"stability ball","difficulty":"beginner","description":"A stretch performed using a stability ball to target the hamstrings, with secondary emphasis on the glutes and lower back. The exercise involves rolling out on the ball and lowering the upper body to stretch the hamstrings.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1560.gif","youtube_id":null,"instructions":["Sit on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Slowly roll the ball forward, walking your feet out until your upper back is resting on the ball and your legs are extended straight in front of you.","Place your hands on your hips for support.","Engage your core and slowly lower your upper body towards the ground, keeping your back straight and your chest lifted.","Stop when you feel a stretch in your hamstrings, and hold the position for 20-30 seconds.","Slowly return to the starting position by pushing through your heels and using your hamstrings to pull yourself back up.","Repeat for the desired number of repetitions."]},{"id":"1564","name":"intermediate hip flexor and quad stretch","body_part":"upper legs","target":"quads","secondary_muscles":["hamstrings","glutes"],"equipment":"rope","difficulty":"intermediate","description":"A stretch targeting the hip flexors and quadriceps using a rope for assistance, suitable for improving flexibility in the upper legs.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1564.gif","youtube_id":null,"instructions":["Stand upright with your feet shoulder-width apart.","Hold onto a stable object for support.","Bend your right knee and bring your right foot towards your glutes, grabbing the rope with your right hand.","Slowly pull your right foot towards your glutes, feeling a stretch in your right quad.","Hold the stretch for 20-30 seconds.","Release the stretch and repeat on the left side."]},{"id":"157","name":"cable deadlift","body_part":"upper legs","target":"glutes","secondary_muscles":["hamstrings","quadriceps","lower back"],"equipment":"cable","difficulty":"intermediate","description":"The cable deadlift is a compound exercise targeting the glutes, with secondary emphasis on the hamstrings, quadriceps, and lower back. It involves lifting a cable from a lowered position by hinging at the hips and extending the body to a standing position.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0157.gif","youtube_id":null,"instructions":["Stand facing the cable machine with your feet shoulder-width apart.","Bend at the hips and knees, lowering your torso until your back is parallel to the ground.","Grasp the cable handles with an overhand grip, keeping your arms straight and your shoulders back.","Engage your glutes and hamstrings to lift the cable handles, extending your hips and standing up straight.","Pause for a moment at the top, then slowly lower the cable handles back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1576","name":"leg up hamstring stretch","body_part":"upper legs","target":"hamstrings","secondary_muscles":["glutes"],"equipment":"body weight","difficulty":"beginner","description":"The leg up hamstring stretch is a flexibility exercise targeting the hamstrings and glutes. It involves lying on your back, bringing one knee toward your chest, and then straightening the leg to stretch the hamstring.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1576.gif","youtube_id":null,"instructions":["Lie flat on your back with your legs extended.","Bend one knee and bring it towards your chest, holding onto your thigh or shin.","Straighten your leg as much as possible while keeping it elevated.","Hold the stretch for 20-30 seconds.","Repeat with the other leg."]},{"id":"158","name":"cable decline fly","body_part":"chest","target":"pectorals","secondary_muscles":["shoulders","triceps"],"equipment":"cable","difficulty":"intermediate","description":"The cable decline fly is an isolation exercise targeting the pectoral muscles using a cable machine set to a decline angle. It emphasizes the lower chest and involves controlled arm movement to stretch and contract the chest muscles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0158.gif","youtube_id":null,"instructions":["Adjust the cable machine to a decline position.","Stand facing away from the machine with your feet shoulder-width apart.","Hold the handles with your palms facing forward and your arms extended straight out in front of you.","Keeping a slight bend in your elbows, open your arms out to the sides in a controlled motion.","Pause for a moment at the fully extended position, then slowly return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1582","name":"reclining big toe pose with rope","body_part":"upper legs","target":"hamstrings","secondary_muscles":["calves","glutes"],"equipment":"rope","difficulty":"beginner","description":"The reclining big toe pose with rope is a flexibility exercise that targets the hamstrings, using a rope to assist in stretching the leg while lying on your back.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1582.gif","youtube_id":null,"instructions":["Lie on your back with your legs extended and your arms by your sides.","Loop the rope around the ball of your right foot and hold the ends of the rope with your hands.","Slowly raise your right leg towards your chest, keeping your knee straight and your foot flexed.","Hold the stretch for a few seconds, then slowly lower your leg back down to the starting position.","Repeat with your left leg.","Continue alternating legs for the desired number of repetitions."]},{"id":"1585","name":"runners stretch","body_part":"upper legs","target":"hamstrings","secondary_muscles":["calves","quadriceps"],"equipment":"body weight","difficulty":"beginner","description":"The runner's stretch is a bodyweight exercise primarily targeting the hamstrings, with secondary emphasis on the calves and quadriceps. It is performed by stepping forward, bending the front knee, and keeping the back leg straight to stretch the hamstrings.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1585.gif","youtube_id":null,"instructions":["Stand with your feet hip-width apart.","Take a step forward with your right foot, keeping your left foot planted.","Bend your right knee and lower your body down, keeping your left leg straight.","Place your hands on your right thigh for support.","Hold the stretch for 20-30 seconds, then switch sides and repeat."]},{"id":"1587","name":"seated wide angle pose sequence","body_part":"upper legs","target":"hamstrings","secondary_muscles":["quadriceps","calves"],"equipment":"body weight","difficulty":"beginner","description":"The seated wide angle pose sequence is a flexibility exercise targeting the hamstrings, performed by sitting with legs extended wide, flexing the feet, and leaning forward from the hips to stretch the hamstrings.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1587.gif","youtube_id":null,"instructions":["Sit on the ground with your legs extended in a wide angle.","Flex your feet and engage your quadriceps.","Place your hands on the ground behind you for support.","Keeping your back straight, lean forward from your hips.","Continue leaning forward until you feel a stretch in your hamstrings.","Hold this position for a few breaths.","Slowly release the stretch and return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"159","name":"cable decline seated wide-grip row","body_part":"back","target":"upper back","secondary_muscles":["biceps","forearms"],"equipment":"cable","difficulty":"intermediate","description":"The cable decline seated wide-grip row is a strength exercise targeting the upper back, performed on a decline bench using a cable machine. It also engages the biceps and forearms as secondary muscles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0159.gif","youtube_id":null,"instructions":["Sit on the decline bench facing the cable machine with your feet securely placed on the footrests.","Grasp the cable attachment with a wide overhand grip, palms facing down.","Lean back slightly, keeping your back straight and your core engaged.","Pull the cable towards your lower chest, squeezing your shoulder blades together.","Pause for a moment at the peak of the contraction, then slowly release the cable back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1599","name":"standing hamstring and calf stretch with strap","body_part":"upper legs","target":"hamstrings","secondary_muscles":["calves"],"equipment":"rope","difficulty":"beginner","description":"A standing stretch using a rope or strap to target the hamstrings and calves. This exercise helps improve flexibility and mobility in the posterior chain.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1599.gif","youtube_id":null,"instructions":["Stand upright with your feet shoulder-width apart.","Hold the strap with both hands and place it around the ball of your foot.","Keep your leg straight and slowly lean forward from your hips, keeping your back straight.","Feel the stretch in your hamstring and calf muscles.","Hold the stretch for 20-30 seconds.","Release the stretch and repeat with the other leg.","Repeat for the desired number of repetitions."]},{"id":"16","name":"assisted prone hamstring","body_part":"upper legs","target":"hamstrings","secondary_muscles":["glutes","lower back"],"equipment":"assisted","difficulty":"beginner","description":"The assisted prone hamstring exercise targets the hamstrings with assistance from a partner or resistance band, making it accessible for those developing strength or needing support. It involves lying face down and curling the legs towards the glutes, focusing on hamstring engagement.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0016.gif","youtube_id":null,"instructions":["Lie face down on a mat or bench with your legs fully extended.","Have a partner or use a resistance band to secure your ankles.","Engage your hamstrings and lift your legs towards your glutes, keeping your knees straight.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"160","name":"cable floor seated wide-grip row","body_part":"back","target":"upper back","secondary_muscles":["biceps","forearms"],"equipment":"cable","difficulty":"intermediate","description":"The cable floor seated wide-grip row is a strength exercise targeting the upper back, performed seated on the floor using a cable machine. It emphasizes scapular retraction and upper back engagement, with secondary activation of the biceps and forearms.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0160.gif","youtube_id":null,"instructions":["Sit on the floor with your legs extended and your back straight.","Attach a cable handle to a low pulley and position the cable machine behind you.","Grasp the handle with a wide overhand grip, palms facing down.","Lean back slightly, keeping your back straight and your chest lifted.","Pull the handle towards your waist, squeezing your shoulder blades together.","Pause for a moment at the top of the movement, then slowly release the handle back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1604","name":"world greatest stretch","body_part":"upper legs","target":"hamstrings","secondary_muscles":["glutes","quadriceps","calves"],"equipment":"body weight","difficulty":"intermediate","description":"The world greatest stretch is a dynamic movement that targets the hamstrings and also stretches the glutes, quadriceps, and calves. It involves a lunge, torso rotation, and a deep stretch, making it excellent for improving flexibility and mobility.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1604.gif","youtube_id":null,"instructions":["Start in a lunge position with your right foot forward and your left foot back.","Place your hands on the ground on either side of your right foot.","Lower your left knee to the ground and extend your right leg, keeping your right foot flat on the ground.","Rotate your torso to the right, reaching your right arm up towards the ceiling.","Hold this position for a few seconds, then return to the starting position.","Switch sides and repeat the stretch with your left foot forward."]},{"id":"161","name":"cable forward raise","body_part":"shoulders","target":"delts","secondary_muscles":["triceps","forearms"],"equipment":"cable","difficulty":"beginner","description":"The cable forward raise is an isolation exercise targeting the deltoid muscles of the shoulders. It involves lifting a cable handle in front of the body to shoulder height, emphasizing shoulder strength and stability.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0161.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and your knees slightly bent.","Hold the cable handle with an overhand grip, palms facing down, and your arms fully extended in front of you.","Keeping your arms straight, raise the cable handle up to shoulder level.","Pause for a moment at the top, then slowly lower the cable handle back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1614","name":"lever preacher curl v. 2","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"leverage machine","difficulty":"beginner","description":"The lever preacher curl v. 2 is a machine-based biceps exercise that isolates the upper arms and forearms. It is performed seated with the upper arms resting on a pad, using a leverage machine to curl the handles upward.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1614.gif","youtube_id":null,"instructions":["Adjust the seat height and position yourself on the machine with your upper arms resting on the pad and your chest against the support.","Grasp the handles with an underhand grip, slightly wider than shoulder-width apart.","Keep your upper arms stationary and exhale as you curl the handles towards your shoulders, contracting your biceps.","Pause for a moment at the top of the movement, squeezing your biceps.","Inhale as you slowly lower the handles back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]},{"id":"1615","name":"lever hammer grip preacher curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"leverage machine","difficulty":"beginner","description":"The lever hammer grip preacher curl is an isolation exercise performed on a leverage machine, targeting the biceps with a neutral (hammer) grip. It also engages the forearms as secondary muscles. The preacher pad provides support and stability, making the movement controlled and focused on the biceps.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1615.gif","youtube_id":null,"instructions":["Adjust the seat height and position yourself on the leverage machine.","Place your upper arms on the preacher pad, ensuring your chest is pressed against it.","Grasp the handles with a hammer grip (palms facing each other).","Keeping your upper arms stationary, exhale and curl the handles towards your shoulders.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the handles back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1616","name":"lever reverse grip preacher curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"leverage machine","difficulty":"beginner","description":"The lever reverse grip preacher curl is an isolation exercise targeting the biceps, performed on a leverage machine with an underhand grip. It emphasizes the biceps and also engages the forearms, using the preacher pad to stabilize the upper arms and minimize cheating.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1616.gif","youtube_id":null,"instructions":["Adjust the seat height and position yourself on the leverage machine.","Grasp the handles with an underhand grip, palms facing up.","Rest your upper arms on the preacher pad, ensuring your elbows are fully extended.","Keeping your upper arms stationary, exhale and curl the handles towards your shoulders.","Pause for a moment at the top of the movement, squeezing your biceps.","Inhale and slowly lower the handles back to the starting position, fully extending your elbows.","Repeat for the desired number of repetitions."]},{"id":"1617","name":"dumbbell decline one arm hammer press","body_part":"upper arms","target":"triceps","secondary_muscles":["chest","shoulders"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell decline one arm hammer press is a unilateral pressing movement performed on a decline bench, targeting the triceps with secondary emphasis on the chest and shoulders. It requires core stability and coordination due to the decline angle and single-arm execution.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1617.gif","youtube_id":null,"instructions":["Lie on a decline bench with a dumbbell in one hand, resting on your chest.","Extend your arm straight up, keeping your elbow slightly bent.","Lower the dumbbell down towards your shoulder, keeping your elbow close to your body.","Press the dumbbell back up to the starting position.","Repeat for the desired number of repetitions, then switch arms."]},{"id":"1618","name":"dumbbell incline hammer press on exercise ball","body_part":"upper arms","target":"triceps","secondary_muscles":["chest","shoulders"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell incline hammer press on an exercise ball targets the triceps while also engaging the chest and shoulders. The use of an exercise ball increases the need for balance and core stability, making the movement more challenging than a standard incline press.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1618.gif","youtube_id":null,"instructions":["Sit on an exercise ball with a dumbbell in each hand, palms facing each other.","Walk your feet forward and roll your body down the ball until your head, neck, and upper back are supported on the ball.","Hold the dumbbells at shoulder level, elbows bent and pointing out to the sides.","Press the dumbbells up and slightly inward, keeping your palms facing each other.","Extend your arms fully, squeezing your triceps at the top of the movement.","Slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1619","name":"dumbbell incline one arm hammer press","body_part":"upper arms","target":"triceps","secondary_muscles":["shoulders","chest"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell incline one arm hammer press is a unilateral pressing exercise performed on an incline bench, targeting the triceps while also engaging the shoulders and chest. It requires coordination and stability due to the single-arm movement and the inclined position.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1619.gif","youtube_id":null,"instructions":["Sit on an incline bench with a dumbbell in one hand, resting on your thigh.","Lean back on the bench and use your thigh to help raise the dumbbell to shoulder height.","Rotate your wrist so that your palm is facing inward, towards your body.","Press the dumbbell up and away from your body, extending your arm fully.","Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch arms."]},{"id":"162","name":"cable front raise","body_part":"shoulders","target":"delts","secondary_muscles":["triceps","forearms"],"equipment":"cable","difficulty":"beginner","description":"The cable front raise is a shoulder exercise that targets the deltoid muscles, particularly the anterior (front) delts. It involves lifting a cable handle in front of the body to shoulder height, emphasizing controlled movement and muscle engagement.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0162.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and grasp the cable handle with an overhand grip.","Keep your back straight and your core engaged.","Raise the cable handle in front of you, keeping your arms straight and your palms facing down.","Continue lifting until your arms are parallel to the floor.","Pause for a moment at the top, then slowly lower the cable handle back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1620","name":"dumbbell incline one arm hammer press on exercise ball","body_part":"upper arms","target":"triceps","secondary_muscles":["shoulders","chest"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell incline one arm hammer press on exercise ball is a unilateral pressing exercise that targets the triceps, with secondary emphasis on the shoulders and chest. It is performed while balancing on an exercise ball, which increases core engagement and stability demands.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1620.gif","youtube_id":null,"instructions":["Sit on an exercise ball with a dumbbell in one hand.","Walk your feet forward and roll your body down until your head, neck, and upper back are supported on the ball.","Hold the dumbbell with your palm facing inward and your elbow bent at a 90-degree angle.","Press the dumbbell up towards the ceiling, straightening your arm.","Lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch arms."]},{"id":"1621","name":"dumbbell one arm hammer press on exercise ball","body_part":"upper arms","target":"triceps","secondary_muscles":["shoulders","chest"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell one arm hammer press on exercise ball is a unilateral pressing movement that targets the triceps, performed while seated on an unstable surface to engage core and stabilizer muscles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1621.gif","youtube_id":null,"instructions":["Sit on an exercise ball with your feet flat on the ground and your back straight.","Hold a dumbbell in one hand with your palm facing inwards and your elbow bent at a 90-degree angle.","Place your other hand on your hip for stability.","Press the dumbbell upwards, extending your arm fully.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]},{"id":"1622","name":"dumbbell one arm reverse grip press","body_part":"chest","target":"pectorals","secondary_muscles":["triceps","shoulders"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell one arm reverse grip press is a unilateral chest exercise that targets the pectorals with a unique grip, also engaging the triceps and shoulders. It requires stability and control due to the reverse grip and single-arm execution.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1622.gif","youtube_id":null,"instructions":["Sit on a flat bench with a dumbbell in one hand, palm facing towards your body.","Place your feet flat on the ground and keep your back straight.","Raise the dumbbell to shoulder height, keeping your elbow close to your body.","Press the dumbbell upwards until your arm is fully extended.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]},{"id":"1623","name":"dumbbell palms in incline bench press","body_part":"upper arms","target":"triceps","secondary_muscles":["chest","shoulders"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell palms in incline bench press is a strength exercise targeting the triceps, with secondary emphasis on the chest and shoulders. It is performed on an incline bench with dumbbells, using a palms-in grip to keep the elbows close to the body, which increases triceps activation.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1623.gif","youtube_id":null,"instructions":["Set up an incline bench at a 45-degree angle.","Sit on the bench with your back against the backrest and feet flat on the ground.","Hold a dumbbell in each hand with an overhand grip, palms facing inwards.","Extend your arms straight up above your chest, keeping a slight bend in your elbows.","Lower the dumbbells slowly towards your shoulders, keeping your elbows close to your body.","Pause for a moment at the bottom, then press the dumbbells back up to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1624","name":"dumbbell reverse bench press","body_part":"chest","target":"pectorals","secondary_muscles":["triceps","shoulders"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell reverse bench press is a chest exercise performed lying on a bench, pressing dumbbells upward with an overhand grip. It targets the pectorals and also works the triceps and shoulders.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1624.gif","youtube_id":null,"instructions":["Lie flat on a bench with your feet flat on the ground and your knees bent.","Hold a dumbbell in each hand with an overhand grip, palms facing towards your feet.","Extend your arms straight up towards the ceiling, keeping a slight bend in your elbows.","Slowly lower the dumbbells towards your chest, allowing your elbows to flare out to the sides.","Pause for a moment at the bottom, then push the dumbbells back up to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1625","name":"smith machine decline close grip bench press","body_part":"upper arms","target":"triceps","secondary_muscles":["chest","shoulders"],"equipment":"smith machine","difficulty":"intermediate","description":"The smith machine decline close grip bench press is a compound exercise targeting the triceps, with secondary emphasis on the chest and shoulders. It is performed on a smith machine with a decline bench and a close grip on the barbell.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1625.gif","youtube_id":null,"instructions":["Adjust the bench on the smith machine to a decline position.","Lie down on the bench with your feet firmly planted on the ground.","Grasp the barbell with a close grip, slightly narrower than shoulder-width apart.","Unrack the barbell and lower it slowly towards your chest, keeping your elbows close to your body.","Pause for a moment when the barbell is just above your chest.","Push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]},{"id":"1626","name":"smith machine reverse decline close grip bench press","body_part":"chest","target":"pectorals","secondary_muscles":["triceps","shoulders"],"equipment":"smith machine","difficulty":"intermediate","description":"The smith machine reverse decline close grip bench press is a chest exercise performed on a smith machine set to a decline position. It targets the pectorals with a close grip, also engaging the triceps and shoulders. The decline angle and close grip require good technique and control.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1626.gif","youtube_id":null,"instructions":["Adjust the smith machine to a decline position.","Lie down on the bench with your feet secured under the foot pads.","Grasp the barbell with a close grip, slightly narrower than shoulder-width apart.","Unrack the barbell and lower it slowly towards your chest, keeping your elbows tucked in.","Pause for a moment at the bottom, then push the barbell back up to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1627","name":"ez barbell close grip preacher curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"ez barbell","difficulty":"beginner","description":"The EZ barbell close grip preacher curl is an isolation exercise targeting the biceps, performed on a preacher bench with a close grip on an EZ barbell. It emphasizes strict form and biceps contraction.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1627.gif","youtube_id":null,"instructions":["Sit on a preacher curl bench and place your upper arms on the pad, gripping the ez barbell with an underhand grip.","Rest your triceps on the pad and fully extend your arms, keeping your back straight.","Slowly curl the barbell towards your shoulders, contracting your biceps.","Pause for a moment at the top, squeezing your biceps.","Lower the barbell back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]},{"id":"1628","name":"ez barbell spider curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"ez barbell","difficulty":"intermediate","description":"The EZ barbell spider curl is an isolation exercise targeting the biceps, performed with the upper arms supported on a bench or ball to minimize cheating and maximize biceps engagement.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1628.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and hold the ez barbell with an underhand grip, palms facing up.","Rest your upper arms on a preacher bench or stability ball, allowing your elbows to hang down.","Keeping your upper arms stationary, exhale and curl the barbell up towards your shoulders.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1629","name":"barbell standing wide grip biceps curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"barbell","difficulty":"beginner","description":"The barbell standing wide grip biceps curl is a strength exercise targeting the biceps, with secondary emphasis on the forearms. It involves curling a barbell with a wide grip, which can help emphasize the outer portion of the biceps.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1629.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and hold a barbell with an underhand grip, hands wider than shoulder-width apart.","Keep your back straight and your elbows close to your torso.","Exhale and curl the barbell up towards your shoulders, keeping your upper arms stationary.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the barbell back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]},{"id":"1630","name":"cable close grip curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"cable","difficulty":"beginner","description":"The cable close grip curl is an isolation exercise targeting the biceps using a cable machine. It involves curling a straight bar attached to a low pulley with a close grip, emphasizing the biceps and forearms.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1630.gif","youtube_id":null,"instructions":["Attach a straight bar to a low pulley cable machine.","Stand facing the machine with your feet shoulder-width apart and your knees slightly bent.","Grasp the bar with an underhand grip, hands shoulder-width apart.","Keep your elbows close to your sides and your upper arms stationary throughout the exercise.","Exhale and curl the bar up towards your shoulders, contracting your biceps.","Pause for a moment at the top of the movement, squeezing your biceps.","Inhale and slowly lower the bar back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]},{"id":"1631","name":"cable concentration curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"cable","difficulty":"beginner","description":"The cable concentration curl is an isolation exercise targeting the biceps, performed with a cable machine while seated. It emphasizes strict form and muscle contraction by bracing the upper arm against the thigh.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1631.gif","youtube_id":null,"instructions":["Sit on a bench or chair with your feet flat on the floor and your knees slightly bent.","Hold the cable handle with an underhand grip and rest your elbow against the inside of your thigh.","Keeping your upper arm stationary, exhale and curl the cable handle towards your shoulder while contracting your biceps.","Pause for a moment at the top of the movement, then inhale and slowly lower the cable handle back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]},{"id":"1632","name":"cable drag curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"cable","difficulty":"intermediate","description":"The cable drag curl is an isolation exercise targeting the biceps, performed using a cable machine. It emphasizes the biceps by keeping the elbows back and dragging the cable attachment up the body, minimizing shoulder involvement.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1632.gif","youtube_id":null,"instructions":["Stand facing a cable machine with your feet shoulder-width apart.","Grasp the cable attachment with an underhand grip, palms facing up, and arms fully extended.","Keeping your upper arms stationary, exhale and curl the cable attachment towards your shoulders by contracting your biceps.","Pause for a moment at the top of the movement, squeezing your biceps.","Inhale and slowly lower the cable attachment back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]},{"id":"1633","name":"cable one arm preacher curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"cable","difficulty":"intermediate","description":"The cable one arm preacher curl is an isolation exercise targeting the biceps using a cable machine and a preacher curl pad. It emphasizes strict form and constant tension on the biceps throughout the movement.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1633.gif","youtube_id":null,"instructions":["Adjust the cable machine so that the preacher curl pad is at chest height.","Stand facing the cable machine with your feet shoulder-width apart.","Grasp the cable handle with an underhand grip and position your upper arm against the preacher curl pad.","Keep your back straight and your core engaged.","Slowly curl the cable handle towards your shoulder, keeping your upper arm against the pad.","Pause for a moment at the top of the movement, squeezing your biceps.","Slowly lower the cable handle back to the starting position.","Repeat for the desired number of repetitions.","Switch arms and repeat the exercise."]},{"id":"1634","name":"cable lying bicep curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"cable","difficulty":"intermediate","description":"The cable lying bicep curl is an isolation exercise targeting the biceps using a cable machine while lying on a bench. It emphasizes constant tension on the biceps throughout the movement.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1634.gif","youtube_id":null,"instructions":["Attach a straight bar to a low pulley cable machine.","Lie face up on a flat bench with your feet flat on the ground.","Grasp the bar with an underhand grip, hands shoulder-width apart.","Extend your arms fully, keeping your elbows close to your sides.","Keeping your upper arms stationary, exhale and curl the bar up towards your shoulders.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the bar back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]},{"id":"1635","name":"cable one arm reverse preacher curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"cable","difficulty":"intermediate","description":"The cable one arm reverse preacher curl is an isolation exercise targeting the biceps, performed using a cable machine and a preacher bench. It emphasizes strict form and control to maximize biceps engagement while minimizing involvement of other muscles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1635.gif","youtube_id":null,"instructions":["Adjust the cable machine so that the pulley is at the lowest position.","Stand facing the cable machine with your feet shoulder-width apart.","Grasp the cable handle with an underhand grip and position your upper arm against the preacher bench pad.","Keep your back straight and your core engaged throughout the exercise.","Slowly curl your forearm towards your bicep, keeping your upper arm stationary against the pad.","Pause for a moment at the top of the movement, squeezing your bicep.","Slowly lower the cable handle back to the starting position.","Repeat for the desired number of repetitions.","Switch arms and repeat the exercise."]},{"id":"1636","name":"cable overhead curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms","shoulders"],"equipment":"cable","difficulty":"intermediate","description":"The cable overhead curl is an isolation exercise targeting the biceps, performed using a high pulley cable machine. It also engages the forearms and shoulders as secondary muscles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1636.gif","youtube_id":null,"instructions":["Attach a straight bar to a high pulley cable machine.","Stand facing the machine with your feet shoulder-width apart.","Grasp the bar with an underhand grip, hands shoulder-width apart.","Keep your elbows close to your sides and your upper arms stationary.","Exhale and curl the bar down towards your forehead, keeping your upper arms stationary.","Pause for a moment at the bottom of the movement, squeezing your biceps.","Inhale and slowly return the bar to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]},{"id":"1637","name":"cable overhead curl on exercise ball","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms","shoulders"],"equipment":"cable","difficulty":"intermediate","description":"The cable overhead curl on exercise ball is a biceps-focused exercise that also engages the forearms and shoulders. Sitting on an exercise ball adds a balance component, requiring core stability and coordination.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1637.gif","youtube_id":null,"instructions":["Sit on an exercise ball and hold the cable handle with an underhand grip.","Extend your arms fully overhead, keeping your elbows close to your ears.","Slowly curl the cable down towards your forehead, keeping your upper arms stationary.","Pause for a moment at the bottom of the movement, then slowly return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1638","name":"cable pulldown bicep curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"cable","difficulty":"beginner","description":"The cable pulldown bicep curl is an isolation exercise targeting the biceps using a cable machine. It involves pulling a straight bar attached to a high cable down towards the thighs, emphasizing bicep contraction and control.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1638.gif","youtube_id":null,"instructions":["Attach a straight bar to the cable machine at the highest setting.","Stand facing the machine with your feet shoulder-width apart.","Grasp the bar with an underhand grip, hands shoulder-width apart.","Keep your elbows close to your sides and your upper arms stationary.","Exhale and slowly curl the bar down towards your thighs, keeping your wrists straight.","Pause for a moment at the bottom of the movement, squeezing your biceps.","Inhale and slowly return the bar to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]},{"id":"1639","name":"cable rope hammer preacher curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"cable","difficulty":"intermediate","description":"The cable rope hammer preacher curl is an isolation exercise targeting the biceps and forearms, performed using a rope attachment on a low pulley cable machine while seated at a preacher bench.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1639.gif","youtube_id":null,"instructions":["Attach a rope attachment to a low pulley cable machine.","Stand facing the machine with your feet shoulder-width apart.","Grasp the rope with a neutral grip (palms facing each other).","Position your upper arms against the preacher bench pad, keeping your elbows slightly bent.","Keeping your upper arms stationary, exhale and curl the rope towards your shoulders by contracting your biceps.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly lower the rope back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"164","name":"cable front shoulder raise","body_part":"shoulders","target":"delts","secondary_muscles":["trapezius","biceps"],"equipment":"cable","difficulty":"intermediate","description":"The cable front shoulder raise is an isolation exercise that targets the deltoid muscles of the shoulders, using a cable machine to provide constant tension throughout the movement. It also engages the trapezius and biceps as secondary muscles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0164.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and grasp the cable handle with an overhand grip.","Keep your back straight and your core engaged.","Raise the cable handle in front of you, keeping your arms straight and your palms facing down.","Continue lifting until your arms are parallel to the floor.","Pause for a moment at the top, then slowly lower the cable handle back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1640","name":"cable rope one arm hammer preacher curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"cable","difficulty":"intermediate","description":"The cable rope one arm hammer preacher curl is an isolation exercise targeting the biceps, performed using a cable machine with a rope attachment and a preacher bench. It emphasizes the brachialis and forearm muscles due to the hammer grip and preacher support.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1640.gif","youtube_id":null,"instructions":["Attach a rope handle to a low pulley cable machine.","Stand facing the machine with your feet shoulder-width apart.","Grasp the rope handle with an underhand grip, palms facing up.","Position your upper arm against the preacher bench pad, keeping your elbow slightly bent.","Keep your back straight and your core engaged throughout the exercise.","Slowly curl the rope handle towards your shoulder, keeping your upper arm stationary.","Squeeze your biceps at the top of the movement, then slowly lower the rope handle back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]},{"id":"1641","name":"cable seated curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"cable","difficulty":"beginner","description":"The cable seated curl is an isolation exercise targeting the biceps, performed on a cable machine while seated. It emphasizes controlled movement and constant tension on the biceps throughout the range of motion.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1641.gif","youtube_id":null,"instructions":["Sit on a cable machine with your feet flat on the ground and your back straight.","Grasp the cable attachment with an underhand grip, palms facing up, and your arms fully extended.","Keeping your upper arms stationary, exhale and curl the cable attachment towards your shoulders, contracting your biceps.","Pause for a moment at the top of the movement, squeezing your biceps.","Inhale and slowly lower the cable attachment back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]},{"id":"1642","name":"cable seated one arm concentration curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"cable","difficulty":"beginner","description":"The cable seated one arm concentration curl is an isolation exercise targeting the biceps, performed using a cable machine while seated. It emphasizes strict form and muscle contraction by stabilizing the upper arm against the thigh.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1642.gif","youtube_id":null,"instructions":["Sit on a bench with your feet flat on the floor and your back straight.","Hold a cable handle with one hand and place your elbow on the inside of your thigh, just above the knee.","Keep your upper arm stationary and curl the cable handle towards your shoulder while exhaling.","Pause for a moment at the top of the movement, squeezing your biceps.","Slowly lower the cable handle back to the starting position while inhaling.","Repeat for the desired number of repetitions, then switch arms."]},{"id":"1643","name":"cable seated overhead curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms","shoulders"],"equipment":"cable","difficulty":"intermediate","description":"The cable seated overhead curl is an isolation exercise targeting the biceps, performed using a cable machine while seated. It emphasizes controlled movement and constant tension on the biceps throughout the range of motion.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1643.gif","youtube_id":null,"instructions":["Sit on a bench facing the cable machine with your feet flat on the ground.","Grasp the cable attachment with an underhand grip, palms facing up, and your hands shoulder-width apart.","Keep your upper arms stationary and your elbows close to your sides.","Exhale and curl the cable attachment towards your shoulders, contracting your biceps.","Pause for a moment at the top of the movement, squeezing your biceps.","Inhale and slowly lower the cable attachment back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]},{"id":"1644","name":"cable squatting curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"cable","difficulty":"intermediate","description":"The cable squatting curl is a compound exercise that combines a squat with a biceps curl using a cable machine, targeting the biceps and forearms while also engaging the lower body and core for stability.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1644.gif","youtube_id":null,"instructions":["Attach a cable handle to the lowest setting on a cable machine.","Stand facing the machine with your feet shoulder-width apart.","Hold the cable handle with an underhand grip, palms facing up, and arms fully extended.","Lower your body into a squat position, keeping your back straight and knees behind your toes.","As you squat down, curl the cable handle towards your shoulders, keeping your elbows close to your sides.","Pause for a moment at the top of the curl, squeezing your biceps.","Slowly lower the cable handle back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]},{"id":"1645","name":"cable two arm curl on incline bench","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"cable","difficulty":"intermediate","description":"The cable two arm curl on incline bench is an isolation exercise targeting the biceps, performed using a cable machine while seated on an incline bench. It emphasizes strict form and constant tension on the biceps throughout the movement.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1645.gif","youtube_id":null,"instructions":["Sit on an incline bench with your back against the pad and your feet flat on the ground.","Grasp the cable handles with an underhand grip, palms facing up, and your arms fully extended.","Keeping your upper arms stationary, exhale and curl the handles towards your shoulders while contracting your biceps.","Pause for a moment at the top of the movement, squeezing your biceps.","Inhale and slowly lower the handles back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]},{"id":"1646","name":"dumbbell alternate hammer preacher curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell alternate hammer preacher curl is an isolation exercise targeting the biceps, performed on a preacher bench with a neutral grip to emphasize both the biceps and forearms. It helps build arm strength and muscle definition.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1646.gif","youtube_id":null,"instructions":["Sit on a preacher bench with a dumbbell in each hand, palms facing your torso and arms fully extended.","Keep your upper arms stationary and exhale as you curl the weights while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the recommended amount of repetitions."]},{"id":"1647","name":"dumbbell alternate preacher curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell alternate preacher curl is an isolation exercise targeting the biceps, performed on a preacher bench to minimize cheating and maximize biceps engagement. It is performed by alternating arms, curling a dumbbell up while keeping the upper arm stationary on the pad.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1647.gif","youtube_id":null,"instructions":["Sit on a preacher bench with a dumbbell in each hand, palms facing up.","Rest your upper arms on the pad of the preacher bench, allowing your arms to fully extend.","Keeping your upper arms stationary, exhale and curl the dumbbell in your right hand as you contract your biceps.","Continue to curl the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.","Pause for a moment, then inhale and slowly lower the dumbbell back to the starting position.","Repeat the movement with your left arm.","Continue alternating arms for the desired number of repetitions."]},{"id":"1648","name":"dumbbell alternate seated hammer curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell alternate seated hammer curl is an upper arm exercise that targets the biceps and forearms. It is performed while seated, alternating curls with each arm using a neutral grip.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1648.gif","youtube_id":null,"instructions":["Sit on a bench with a dumbbell in each hand, palms facing your torso and arms extended down.","Keep your back straight and your elbows close to your torso.","Exhale and curl the dumbbell in your right hand towards your shoulder, keeping your upper arm stationary.","Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.","Pause for a brief moment, then inhale and slowly lower the dumbbell back to the starting position.","Repeat the movement with your left arm.","Continue alternating arms for the desired number of repetitions."]},{"id":"1649","name":"dumbbell alternating bicep curl with leg raised on exercise ball","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms","shoulders"],"equipment":"dumbbell, exercise ball","difficulty":"advanced","description":"This exercise combines a dumbbell alternating bicep curl with a balance challenge by raising one leg onto an exercise ball. It targets the biceps while also engaging the forearms, shoulders, and core for stability.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1649.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing forward.","Place an exercise ball behind you and position one foot on top of it, keeping your balance.","With your arms fully extended and elbows close to your sides, curl one dumbbell towards your shoulder while keeping your upper arm stationary.","Lower the dumbbell back down to the starting position and repeat with the other arm.","Continue alternating arms for the desired number of repetitions."]},{"id":"165","name":"cable hammer curl (with rope)","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"cable","difficulty":"beginner","description":"The cable hammer curl (with rope) is an isolation exercise targeting the biceps and forearms, performed using a cable machine with a rope attachment. It emphasizes the brachialis and brachioradialis muscles, providing constant tension throughout the movement.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0165.gif","youtube_id":null,"instructions":["Stand upright with your feet shoulder-width apart and a slight bend in your knees.","Hold the cable rope attachment with an underhand grip, palms facing each other, and your arms fully extended.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the cable rope attachment until your biceps are fully contracted and the rope is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the cable rope attachment back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1650","name":"dumbbell alternating seated bicep curl on exercise ball","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell alternating seated bicep curl on exercise ball is a biceps-focused exercise performed while seated on an unstable surface, which also engages the core for balance. It is performed by alternating curls with each arm while maintaining proper posture on the exercise ball.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1650.gif","youtube_id":null,"instructions":["Sit on an exercise ball with your feet flat on the ground and your back straight.","Hold a dumbbell in each hand with your palms facing forward and your arms fully extended.","Keeping your upper arms stationary, exhale and curl one dumbbell while rotating your forearm until your palm is facing your shoulder.","Inhale and slowly lower the dumbbell back to the starting position.","Repeat the curl with the other arm.","Continue alternating curls for the desired number of repetitions."]},{"id":"1651","name":"dumbbell bicep curl lunge with bowling motion","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms","shoulders"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell bicep curl lunge with bowling motion is a compound exercise that combines a forward lunge, a bicep curl, and a torso rotation, mimicking a bowling motion. This movement targets the biceps while also engaging the forearms, shoulders, core, and legs for stability and coordination.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1651.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing forward.","Take a step forward with your right foot, bending your right knee and lowering your body into a lunge position.","As you lunge forward, curl the dumbbells up towards your shoulders, keeping your elbows close to your body.","At the bottom of the lunge, rotate your torso to the right, as if you were bowling a ball.","Reverse the motion, stepping back with your right foot and returning to the starting position while lowering the dumbbells back down.","Repeat the lunge and curl motion, this time rotating your torso to the left.","Continue alternating sides for the desired number of repetitions."]},{"id":"1652","name":"dumbbell bicep curl on exercise ball with leg raised","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms","shoulders"],"equipment":"dumbbell","difficulty":"advanced","description":"This exercise involves performing a bicep curl with dumbbells while seated on an exercise ball and raising one leg, which challenges both the biceps and core stability.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1652.gif","youtube_id":null,"instructions":["Sit on an exercise ball with your feet flat on the ground and your back straight.","Hold a dumbbell in each hand with your palms facing forward and your arms fully extended.","Slowly curl the dumbbells towards your shoulders, keeping your elbows close to your sides.","Pause for a moment at the top of the movement, then slowly lower the dumbbells back to the starting position.","While performing the bicep curl, raise one leg off the ground and hold it in the air for the duration of the exercise.","Repeat for the desired number of repetitions, then switch legs and repeat."]},{"id":"1653","name":"dumbbell bicep curl with stork stance","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell bicep curl with stork stance is a variation of the traditional bicep curl that incorporates a balance challenge by having the exerciser stand on one leg (stork stance) while performing the curl. This exercise targets the biceps and also engages the forearms and core for stability.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1653.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing forward.","Extend one leg behind you, balancing on the toes of that foot.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions, then switch legs and repeat."]},{"id":"1654","name":"dumbbell biceps curl reverse","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell biceps curl reverse is a strength exercise targeting the biceps and forearms. It involves curling dumbbells with palms facing down, emphasizing the brachialis and forearm muscles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1654.gif","youtube_id":null,"instructions":["Stand up straight with a dumbbell in each hand, palms facing down and arms fully extended.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1655","name":"dumbbell biceps curl squat","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell biceps curl squat is a compound exercise that combines a traditional biceps curl with a squat, engaging both the upper arms and lower body. This movement targets the biceps while also requiring coordination and some lower body strength.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1655.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing forward.","Keeping your back straight and your elbows close to your sides, exhale and curl the dumbbells up towards your shoulders.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1656","name":"dumbbell biceps curl v sit on bosu ball","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms","shoulders"],"equipment":"dumbbell","difficulty":"advanced","description":"The dumbbell biceps curl v sit on bosu ball is a challenging exercise that combines a traditional biceps curl with a core-engaging V-sit position on an unstable surface (BOSU ball). This movement targets the biceps while also requiring significant balance and core stability.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1656.gif","youtube_id":null,"instructions":["Sit on a bosu ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Hold a dumbbell in each hand with your palms facing forward and your arms fully extended down by your sides.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1657","name":"dumbbell cross body hammer curl v. 2","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell cross body hammer curl v. 2 is an upper arm exercise targeting the biceps and forearms. It involves curling a dumbbell across the body toward the opposite shoulder, emphasizing the brachialis and brachioradialis muscles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1657.gif","youtube_id":null,"instructions":["Stand up straight with a dumbbell in each hand, palms facing your body.","Keep your elbows close to your torso and your upper arms stationary.","Exhale and curl the weights while contracting your biceps, bringing the dumbbells as close to your opposite shoulder as possible.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1658","name":"dumbbell lunge with bicep curl","body_part":"upper arms","target":"biceps","secondary_muscles":["quadriceps","hamstrings"],"equipment":"dumbbell","difficulty":"intermediate","description":"A compound exercise combining a forward lunge with a bicep curl, targeting both the biceps and lower body muscles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1658.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing forward.","Take a step forward with your right foot, lowering your body into a lunge position. Your right knee should be bent at a 90-degree angle and your left knee should be hovering just above the ground.","As you lunge forward, simultaneously curl the dumbbells towards your shoulders, keeping your elbows close to your body.","Pause for a moment at the bottom of the lunge, then push through your right heel to return to the starting position, lowering the dumbbells back down to your sides.","Repeat the lunge and bicep curl on the opposite side, stepping forward with your left foot.","Continue alternating sides for the desired number of repetitions."]},{"id":"1659","name":"dumbbell hammer curl on exercise ball","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"dumbbell, exercise ball","difficulty":"intermediate","description":"The dumbbell hammer curl on exercise ball is a biceps-focused exercise that also engages the forearms and core due to the instability of the exercise ball. It requires balance and coordination in addition to strength.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1659.gif","youtube_id":null,"instructions":["Sit on an exercise ball with your feet flat on the ground and your back straight.","Hold a dumbbell in each hand with your palms facing your body and your arms fully extended.","Keeping your upper arms stationary, exhale and curl the dumbbells while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1660","name":"dumbbell kneeling bicep curl exercise ball","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"dumbbell, exercise ball","difficulty":"intermediate","description":"The dumbbell kneeling bicep curl on an exercise ball is a variation of the standard bicep curl that increases the challenge to your core and stability by having you kneel and support your elbows on an unstable surface. This exercise targets the biceps and also engages the forearms and core for stabilization.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1660.gif","youtube_id":null,"instructions":["Kneel on the floor with an exercise ball in front of you.","Place your elbows on top of the exercise ball, holding a dumbbell in each hand with your palms facing up.","Keeping your upper arms stationary, exhale and curl the dumbbells while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1661","name":"dumbbell lying supine biceps curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell lying supine biceps curl is an isolation exercise targeting the biceps, performed while lying flat on a bench. It emphasizes strict form and minimizes cheating by stabilizing the upper body.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1661.gif","youtube_id":null,"instructions":["Lie flat on a bench with your back and head supported, and your feet flat on the ground.","Hold a dumbbell in each hand with your palms facing up and your arms fully extended.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1662","name":"dumbbell lying wide curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell lying wide curl is an isolation exercise targeting the biceps, performed while lying flat on a bench with dumbbells. It emphasizes the outer portion of the biceps and also engages the forearms.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1662.gif","youtube_id":null,"instructions":["Lie flat on a bench with a dumbbell in each hand, palms facing up and arms fully extended.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1663","name":"dumbbell one arm hammer preacher curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell one arm hammer preacher curl is an isolation exercise targeting the biceps and forearms, performed on a preacher bench to minimize cheating and maximize muscle engagement.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1663.gif","youtube_id":null,"instructions":["Sit on a preacher bench with a dumbbell in one hand and your upper arm resting on the pad.","Hold the dumbbell with a neutral grip (palms facing your body).","Keeping your upper arm stationary, exhale and curl the dumbbell up towards your shoulder.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]},{"id":"1664","name":"dumbbell high curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell high curl is an isolation exercise targeting the biceps, performed by curling dumbbells as high as possible while keeping the upper arms stationary.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1664.gif","youtube_id":null,"instructions":["Stand up straight with a dumbbell in each hand, palms facing forward.","Keep your upper arms stationary and curl the dumbbells as high as possible while contracting your biceps.","Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1665","name":"dumbbell one arm prone curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell one arm prone curl is an isolation exercise targeting the biceps, performed while lying face down on a bench. It emphasizes strict form and minimizes momentum, making it effective for biceps development.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1665.gif","youtube_id":null,"instructions":["Lie face down on a flat bench with a dumbbell in one hand, palm facing down.","Extend your arm fully, letting it hang straight down towards the floor.","Keeping your upper arm stationary, curl the dumbbell up towards your shoulder by contracting your biceps.","Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch arms."]},{"id":"1666","name":"dumbbell one arm prone hammer curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell one arm prone hammer curl is an isolation exercise targeting the biceps and forearms. It is performed lying face down on a bench, curling a dumbbell with a neutral grip.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1666.gif","youtube_id":null,"instructions":["Lie face down on a flat bench with a dumbbell in one hand, palm facing your body and arm fully extended.","Keep your upper arm stationary and curl the dumbbell towards your shoulder, contracting your biceps.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]},{"id":"1667","name":"dumbbell one arm reverse spider curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell one arm reverse spider curl is an isolation exercise targeting the biceps and forearms. It is performed with a dumbbell in one hand, using a reverse grip to emphasize the brachialis and forearm muscles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1667.gif","youtube_id":null,"instructions":["Stand up straight with a dumbbell in one hand, palm facing down and arm fully extended.","Keeping your upper arm stationary, curl the dumbbell towards your shoulder by flexing your elbow.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]},{"id":"1668","name":"dumbbell one arm seated bicep curl on exercise ball","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell one arm seated bicep curl on exercise ball is an isolation exercise targeting the biceps, performed while seated on an unstable surface to engage core and stabilizer muscles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1668.gif","youtube_id":null,"instructions":["Sit on an exercise ball with your feet flat on the ground and your back straight.","Hold a dumbbell in one hand with your palm facing up and your arm fully extended.","Keeping your upper arm stationary, curl the dumbbell towards your shoulder by contracting your biceps.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]},{"id":"1669","name":"dumbbell one arm seated hammer curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell one arm seated hammer curl is an isolation exercise targeting the biceps and forearms. It is performed seated, with the elbow braced against the thigh, using a neutral grip to emphasize the brachialis and brachioradialis muscles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1669.gif","youtube_id":null,"instructions":["Sit on a bench with your back straight and feet flat on the ground.","Hold a dumbbell in one hand with a neutral grip (palms facing each other).","Rest your elbow on the inside of your thigh, just above the knee.","Keeping your upper arm stationary, exhale and curl the dumbbell up towards your shoulder.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]},{"id":"167","name":"cable high row (kneeling)","body_part":"back","target":"upper back","secondary_muscles":["biceps","shoulders"],"equipment":"cable","difficulty":"intermediate","description":"The cable high row (kneeling) is a strength exercise targeting the upper back, performed using a cable machine while kneeling. It emphasizes scapular retraction and upper back engagement, with secondary involvement of the biceps and shoulders.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0167.gif","youtube_id":null,"instructions":["Attach a straight bar to a cable machine at chest height.","Kneel down in front of the cable machine and grab the bar with an overhand grip, hands shoulder-width apart.","Sit back on your heels, keeping your back straight and your core engaged.","Pull the bar towards your upper abdomen, squeezing your shoulder blades together.","Pause for a moment at the top of the movement, then slowly release the bar back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1670","name":"dumbbell one arm standing curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell one arm standing curl is a classic isolation exercise targeting the biceps. It involves curling a dumbbell with one arm while standing, focusing on strict form to maximize biceps engagement.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1670.gif","youtube_id":null,"instructions":["Stand up straight with a dumbbell in one hand, palm facing forward and arm fully extended.","Keeping your upper arm stationary, exhale and curl the weight upward while contracting your biceps.","Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]},{"id":"1671","name":"dumbbell one arm standing hammer curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell one arm standing hammer curl is an isolation exercise targeting the biceps and forearms. It is performed standing, with a dumbbell in one hand, curling the weight up while keeping the palm facing the torso throughout the movement.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1671.gif","youtube_id":null,"instructions":["Stand up straight with a dumbbell in each hand, palms facing your torso.","Keep your elbows close to your torso and your upper arms stationary.","Exhale and curl the weights while contracting your biceps.","Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1672","name":"dumbbell one arm zottman preacher curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell one arm Zottman preacher curl is an isolation exercise targeting the biceps and forearms, performed on a preacher bench with a dumbbell, emphasizing both the curl and rotational movement for forearm engagement.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1672.gif","youtube_id":null,"instructions":["Sit on a preacher curl bench and hold a dumbbell in one hand with an underhand grip.","Rest your upper arm on the preacher bench pad, allowing your arm to fully extend.","Curl the dumbbell up towards your shoulder, keeping your upper arm stationary.","At the top of the curl, rotate your wrist so that your palm faces up.","Slowly lower the dumbbell back down to the starting position, rotating your wrist back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]},{"id":"1673","name":"dumbbell preacher curl over exercise ball","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell preacher curl over exercise ball targets the biceps by isolating the muscle with the support of an exercise ball, requiring stability and control. It also engages the forearms as secondary muscles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1673.gif","youtube_id":null,"instructions":["Sit on an exercise ball with your feet flat on the ground and your back straight.","Hold a dumbbell in one hand with an underhand grip, resting your elbow on the exercise ball.","Keeping your upper arm stationary, exhale and curl the dumbbell up towards your shoulder.","Pause for a moment at the top, then inhale and slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]},{"id":"1674","name":"dumbbell prone incline hammer curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell prone incline hammer curl is an isolation exercise targeting the biceps and forearms. It is performed lying face down on an incline bench, which helps minimize momentum and focus the work on the biceps.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1674.gif","youtube_id":null,"instructions":["Adjust the bench to a 45-degree incline.","Lie face down on the bench with a dumbbell in each hand, palms facing each other.","Allow your arms to hang straight down towards the floor, keeping your elbows slightly bent.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1675","name":"dumbbell reverse spider curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell reverse spider curl is an isolation exercise targeting the biceps and forearms. It is performed standing with dumbbells, focusing on curling the weights with palms facing the body, which emphasizes the brachialis and forearm muscles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1675.gif","youtube_id":null,"instructions":["Stand up straight with a dumbbell in each hand, palms facing your body and arms fully extended.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1676","name":"dumbbell seated alternate hammer curl on exercise ball","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell seated alternate hammer curl on an exercise ball is a biceps-focused exercise that also engages the forearms and core due to the instability of the exercise ball. It involves curling dumbbells alternately while seated on an exercise ball, which requires additional balance and coordination.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1676.gif","youtube_id":null,"instructions":["Sit on an exercise ball with your feet flat on the ground and your back straight.","Hold a dumbbell in each hand with your palms facing your body and your arms fully extended.","Keeping your upper arms stationary, exhale and curl one dumbbell up towards your shoulder while keeping your palm facing your body.","Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly lower the dumbbell back to the starting position.","Repeat the movement with the opposite arm.","Continue alternating arms for the desired number of repetitions."]},{"id":"1677","name":"dumbbell seated bicep curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell seated bicep curl is a strength exercise targeting the biceps, performed while seated to minimize body movement and focus on arm muscle engagement.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1677.gif","youtube_id":null,"instructions":["Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand, palms facing up.","Keep your back straight and your elbows close to your torso.","Exhale and curl the dumbbells up towards your shoulders, contracting your biceps.","Pause for a moment at the top, then inhale and slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1678","name":"dumbbell seated hammer curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell seated hammer curl is an isolation exercise targeting the biceps and forearms. It is performed while seated, using a neutral grip (palms facing in) to emphasize the brachialis and brachioradialis muscles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1678.gif","youtube_id":null,"instructions":["Sit on a bench with a dumbbell in each hand, palms facing your torso and arms extended straight down.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1679","name":"dumbbell seated one arm bicep curl on exercise ball with leg raised","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms","shoulders"],"equipment":"dumbbell","difficulty":"advanced","description":"This exercise involves performing a seated one-arm bicep curl on an exercise ball while raising one leg, increasing the challenge to balance and core stability in addition to targeting the biceps.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1679.gif","youtube_id":null,"instructions":["Sit on an exercise ball with your feet flat on the ground and your back straight.","Hold a dumbbell in one hand with your palm facing up and your arm fully extended.","Place your other hand on your hip for stability.","Slowly curl the dumbbell towards your shoulder, keeping your upper arm stationary.","Pause for a moment at the top of the movement, squeezing your bicep.","Slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions.","Switch arms and repeat the exercise."]},{"id":"168","name":"cable hip adduction","body_part":"upper legs","target":"adductors","secondary_muscles":["glutes","quadriceps"],"equipment":"cable","difficulty":"beginner","description":"The cable hip adduction targets the adductor muscles of the inner thigh using a cable machine. It involves moving the leg across the body against resistance, helping to strengthen and tone the adductors.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0168.gif","youtube_id":null,"instructions":["Attach the ankle cuff to your ankle and stand facing the cable machine.","Position yourself far enough away from the machine so that there is tension on the cable.","Place your hands on the machine for support.","Keeping your leg straight, slowly move your leg across your body towards the midline.","Pause for a moment at the end of the movement, then slowly return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1680","name":"dumbbell standing one arm curl over incline bench","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell standing one arm curl over incline bench is an isolation exercise targeting the biceps, with additional engagement of the forearms. It requires the use of an incline bench for support and a dumbbell for resistance. The movement emphasizes strict form and control, making it effective for building biceps strength and size.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1680.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, holding a dumbbell in one hand.","Place your other hand on an incline bench for support.","Keeping your upper arm stationary, curl the dumbbell towards your shoulder by contracting your biceps.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]},{"id":"1682","name":"ez bar seated close grip concentration curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"ez barbell","difficulty":"beginner","description":"The EZ bar seated close grip concentration curl is an isolation exercise targeting the biceps, performed while seated with the elbow braced against the thigh for stability. It uses an EZ barbell and emphasizes strict form to maximize biceps engagement.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1682.gif","youtube_id":null,"instructions":["Sit on a bench with your feet flat on the ground and hold an EZ barbell with an underhand grip.","Rest your elbow on the inside of your thigh, just above the knee.","Curl the barbell up towards your shoulder while keeping your upper arm stationary.","Squeeze your biceps at the top of the movement, then slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1683","name":"smith machine bicep curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"smith machine","difficulty":"beginner","description":"The smith machine bicep curl is a strength exercise targeting the biceps, performed using a smith machine for guided movement. It is suitable for those looking to build arm strength and muscle mass with added stability from the machine.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1683.gif","youtube_id":null,"instructions":["Adjust the height of the smith machine bar to be at waist level.","Stand facing the smith machine with your feet shoulder-width apart.","Grasp the bar with an underhand grip, hands slightly wider than shoulder-width apart.","Keep your elbows close to your sides and your upper arms stationary.","Exhale and curl the bar up towards your shoulders, contracting your biceps.","Pause for a moment at the top of the movement, squeezing your biceps.","Inhale and slowly lower the bar back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1684","name":"dumbbell step up single leg balance with bicep curl","body_part":"upper arms","target":"biceps","secondary_muscles":["quadriceps","glutes","hamstrings"],"equipment":"dumbbell","difficulty":"intermediate","description":"A compound exercise combining a step-up with single-leg balance and a bicep curl, targeting the biceps and engaging the lower body and core for stability.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1684.gif","youtube_id":null,"instructions":["Stand in front of a step or platform with a dumbbell in each hand, palms facing your body.","Place your right foot on the step, ensuring your entire foot is in contact with the surface.","Engage your core and push through your right heel to lift your body up onto the step, bringing your left knee up towards your chest.","At the top of the movement, perform a bicep curl by bending your elbows and bringing the dumbbells towards your shoulders.","Lower the dumbbells back down and simultaneously lower your left foot back to the ground.","Repeat the movement on the opposite side, stepping up with your left foot and curling the dumbbells.","Continue alternating sides for the desired number of repetitions."]},{"id":"1685","name":"squat to overhead reach","body_part":"upper legs","target":"quads","secondary_muscles":["glutes","hamstrings","core"],"equipment":"body weight","difficulty":"beginner","description":"The squat to overhead reach is a bodyweight exercise that combines a traditional squat with an overhead arm extension. It targets the quadriceps while also engaging the glutes, hamstrings, and core. This movement helps improve lower body strength, mobility, and coordination.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1685.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and toes slightly turned out.","Lower your body down into a squat position by bending your knees and pushing your hips back.","As you come up from the squat, extend your arms overhead, reaching towards the ceiling.","Return to the starting position by lowering your arms and bending your knees to squat down again.","Repeat for the desired number of repetitions."]},{"id":"1686","name":"squat to overhead reach with twist","body_part":"upper legs","target":"quads","secondary_muscles":["glutes","hamstrings","core"],"equipment":"body weight","difficulty":"beginner","description":"The squat to overhead reach with twist is a dynamic bodyweight exercise that combines a traditional squat with an overhead reach and torso twist, targeting the quads, glutes, hamstrings, and core. It enhances lower body strength, core stability, and rotational mobility.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1686.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and toes slightly turned out.","Lower your body into a squat position by bending your knees and pushing your hips back.","As you come up from the squat, raise your arms overhead and twist your torso to one side.","Return to the starting position and repeat the squat, this time twisting your torso to the opposite side.","Continue alternating sides with each squat repetition."]},{"id":"1687","name":"posterior step to overhead reach","body_part":"waist","target":"abs","secondary_muscles":["glutes","hamstrings","quadriceps","shoulders"],"equipment":"body weight","difficulty":"beginner","description":"The posterior step to overhead reach is a dynamic bodyweight exercise that targets the abs while also engaging the glutes, hamstrings, quadriceps, and shoulders. It involves stepping back into a lunge and reaching overhead, promoting core stability, lower body strength, and shoulder mobility.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1687.gif","youtube_id":null,"instructions":["Stand with your feet hip-width apart and your arms by your sides.","Take a step back with your right foot, landing on the ball of your foot.","Bend your left knee and lower your body into a lunge position.","As you lower into the lunge, simultaneously reach your arms overhead.","Pause for a moment at the bottom of the lunge, then return to the starting position by pushing through your left heel and bringing your right foot forward.","Repeat the movement on the other side, stepping back with your left foot and bending your right knee.","Continue alternating sides for the desired number of repetitions."]},{"id":"1688","name":"lunge with twist","body_part":"waist","target":"abs","secondary_muscles":["quadriceps","glutes","hamstrings"],"equipment":"body weight","difficulty":"intermediate","description":"The lunge with twist is a dynamic exercise that combines a forward lunge with a torso rotation, targeting the abdominal muscles while also engaging the quadriceps, glutes, and hamstrings. This movement enhances core stability, balance, and lower body strength.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1688.gif","youtube_id":null,"instructions":["Start by standing with your feet shoulder-width apart.","Take a step forward with your right foot, lowering your body into a lunge position.","As you lunge, twist your torso to the right, bringing your left elbow towards your right knee.","Pause for a moment, then return to the starting position.","Repeat on the other side, stepping forward with your left foot and twisting your torso to the left.","Continue alternating sides for the desired number of repetitions."]},{"id":"1689","name":"push and pull bodyweight","body_part":"chest","target":"pectorals","secondary_muscles":["triceps","deltoids"],"equipment":"body weight","difficulty":"intermediate","description":"The push and pull bodyweight exercise is a variation of the push-up that emphasizes both the pushing and pulling phases of the movement, targeting the pectorals, triceps, and deltoids.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1689.gif","youtube_id":null,"instructions":["Start in a push-up position with your hands slightly wider than shoulder-width apart and your body in a straight line.","Lower your chest towards the ground by bending your elbows, keeping your body straight.","Push through your palms to extend your arms and return to the starting position.","From the push-up position, pull your chest towards the ground by bending your elbows, keeping your body straight.","Push through your palms to extend your arms and return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"169","name":"cable incline bench press","body_part":"chest","target":"pectorals","secondary_muscles":["deltoids","triceps"],"equipment":"cable","difficulty":"intermediate","description":"The cable incline bench press is a chest exercise performed on an incline bench using cable handles. It targets the upper pectorals and also works the deltoids and triceps. The cable resistance provides constant tension throughout the movement, making it effective for building strength and muscle in the upper chest.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0169.gif","youtube_id":null,"instructions":["Adjust the bench to a 45-degree incline.","Attach the cable handles to the high pulleys.","Sit on the bench facing the cable machine with your feet flat on the ground.","Grasp the handles with an overhand grip and bring them to shoulder height.","Push the handles forward and upward until your arms are fully extended.","Pause for a moment, then slowly lower the handles back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"17","name":"assisted pull-up","body_part":"back","target":"lats","secondary_muscles":["biceps","forearms"],"equipment":"leverage machine","difficulty":"beginner","description":"The assisted pull-up is a machine-based exercise that helps users perform pull-ups with added support, making it easier to lift their body weight. It primarily targets the latissimus dorsi (lats) and also engages the biceps and forearms.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0017.gif","youtube_id":null,"instructions":["Adjust the machine to your desired weight and height settings.","Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.","Hang with your arms fully extended and your feet off the ground.","Engage your back muscles and pull your body up towards the handles, keeping your elbows close to your body.","Continue pulling until your chin is above the handles.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"170","name":"cable incline fly (on stability ball)","body_part":"chest","target":"pectorals","secondary_muscles":["deltoids","triceps"],"equipment":"cable","difficulty":"advanced","description":"The cable incline fly on a stability ball is a chest isolation exercise that uses cables and a stability ball to target the pectoral muscles while also engaging the core and stabilizer muscles. The instability of the ball increases the balance and coordination required.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0170.gif","youtube_id":null,"instructions":["Set up a stability ball at an incline angle.","Attach the cable handles to the high pulleys of a cable machine.","Sit on the stability ball facing away from the machine, with your feet firmly planted on the ground.","Grasp the cable handles with an overhand grip, palms facing forward.","Lean forward slightly, keeping your back straight and core engaged.","With a controlled motion, bring your arms out to the sides, keeping a slight bend in your elbows.","Continue the motion until your arms are parallel to the ground.","Pause for a moment, then slowly return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1700","name":"dumbbell push press","body_part":"shoulders","target":"delts","secondary_muscles":["triceps","core"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell push press is a compound exercise that targets the deltoids (shoulders) and also engages the triceps and core. It involves a slight dip and drive from the legs to help press the dumbbells overhead, making it a dynamic movement that combines strength and power.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1700.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder level.","Bend your knees slightly and dip your body down, then explosively extend your legs and press the dumbbells overhead.","Lock out your arms at the top of the movement, then lower the dumbbells back to shoulder level.","Repeat for the desired number of repetitions."]},{"id":"1701","name":"medicine ball close grip push up","body_part":"upper arms","target":"triceps","secondary_muscles":["chest","shoulders"],"equipment":"medicine ball","difficulty":"advanced","description":"A push-up variation performed with hands close together on a medicine ball, targeting the triceps and engaging the chest and shoulders.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1701.gif","youtube_id":null,"instructions":["Start in a high plank position with your hands on the medicine ball, shoulder-width apart.","Lower your body towards the ground by bending your elbows, keeping them close to your sides.","Push back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]},{"id":"1705","name":"squat on bosu ball","body_part":"upper legs","target":"quads","secondary_muscles":["glutes","hamstrings","calves"],"equipment":"bosu ball","difficulty":"intermediate","description":"The squat on a BOSU ball is a lower body exercise that targets the quadriceps while also engaging the glutes, hamstrings, and calves. The unstable surface of the BOSU ball increases the challenge to balance and core stability, making the movement more demanding than a standard squat.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1705.gif","youtube_id":null,"instructions":["Place the bosu ball on the ground with the flat side up.","Stand with your feet shoulder-width apart and position yourself on top of the bosu ball.","Lower your body down by bending your knees and hips, as if sitting back into a chair.","Keep your chest up and your weight on your heels.","Lower yourself until your thighs are parallel to the ground.","Pause for a moment, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1707","name":"prone twist on stability ball","body_part":"waist","target":"abs","secondary_muscles":["obliques","lower back"],"equipment":"stability ball","difficulty":"intermediate","description":"The prone twist on stability ball is a core exercise that targets the abs, obliques, and lower back. It requires balance and coordination due to the instability of the ball, and involves rotating the torso while maintaining stability through the hips and legs.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1707.gif","youtube_id":null,"instructions":["Start by lying face down on a stability ball with your feet shoulder-width apart and your toes touching the ground.","Place your hands behind your head or cross them over your chest.","Engage your core muscles and slowly lift your upper body off the ball, keeping your back straight.","Rotate your torso to one side, bringing your shoulder towards your hip. Keep your hips and legs stable throughout the movement.","Pause for a moment, then return to the starting position.","Repeat the rotation to the other side.","Continue alternating sides for the desired number of repetitions."]},{"id":"1708","name":"assisted lying calves stretch","body_part":"lower legs","target":"calves","secondary_muscles":["hamstrings"],"equipment":"assisted","difficulty":"beginner","description":"The assisted lying calves stretch is a flexibility exercise targeting the calves, performed lying on your back and using your hands or a towel to gently pull your toes toward your body.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1708.gif","youtube_id":null,"instructions":["Lie on your back with your legs extended.","Bend one knee and place your foot flat on the ground.","Using your hands or a towel, gently pull your toes towards your body, feeling a stretch in your calf.","Hold the stretch for 20-30 seconds.","Release the stretch and repeat on the other leg."]},{"id":"1709","name":"assisted lying glutes stretch","body_part":"upper legs","target":"glutes","secondary_muscles":["hamstrings"],"equipment":"assisted","difficulty":"beginner","description":"The assisted lying glutes stretch is a flexibility exercise targeting the gluteal muscles. It is performed lying on your back, crossing one ankle over the opposite thigh, and gently pulling the thigh towards your chest to stretch the glutes and hamstrings.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1709.gif","youtube_id":null,"instructions":["Lie on your back with your legs extended.","Bend your right knee and place your right ankle on your left thigh, just above the knee.","Grasp your left thigh with both hands and gently pull it towards your chest.","Hold the stretch for 20-30 seconds.","Release and repeat on the other side."]},{"id":"171","name":"cable incline fly","body_part":"chest","target":"pectorals","secondary_muscles":["deltoids","triceps"],"equipment":"cable","difficulty":"intermediate","description":"The cable incline fly is an isolation exercise targeting the upper chest (pectorals) using a cable machine. It involves opening and closing the arms in a fly motion while lying on an incline bench, providing constant tension throughout the movement.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0171.gif","youtube_id":null,"instructions":["Adjust the cable machine to a low position and attach the handles.","Sit on an incline bench with your back against the pad and feet flat on the floor.","Grasp the handles with an overhand grip and extend your arms straight out in front of you.","Keeping a slight bend in your elbows, open your arms out to the sides in a controlled motion.","Pause for a moment at the fully extended position, then slowly return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1710","name":"assisted lying gluteus and piriformis stretch","body_part":"upper legs","target":"glutes","secondary_muscles":["hamstrings"],"equipment":"assisted","difficulty":"beginner","description":"The assisted lying gluteus and piriformis stretch is a flexibility exercise targeting the glutes and piriformis muscles. It is performed lying on your back, crossing one ankle over the opposite thigh, and gently pulling the thigh towards your chest to stretch the glutes and piriformis.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1710.gif","youtube_id":null,"instructions":["Lie on your back with your legs extended.","Bend your right knee and place your right ankle on your left thigh, just above the knee.","Grasp your left thigh with both hands and gently pull it towards your chest.","Hold the stretch for 20-30 seconds.","Release the stretch and repeat on the other side."]},{"id":"1712","name":"assisted side lying adductor stretch","body_part":"upper legs","target":"adductors","secondary_muscles":["hamstrings","glutes"],"equipment":"assisted","difficulty":"beginner","description":"The assisted side lying adductor stretch is a flexibility exercise targeting the inner thigh muscles (adductors), performed while lying on your side and using a bench or step for assistance.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1712.gif","youtube_id":null,"instructions":["Lie on your side with your legs straight and stacked on top of each other.","Bend your bottom leg slightly for stability.","Place your top foot on a stable surface, such as a bench or step.","Keeping your top leg straight, slowly lower it towards the ground, feeling a stretch in your inner thigh.","Hold the stretch for 20-30 seconds.","Return to the starting position and repeat on the other side."]},{"id":"1713","name":"assisted prone lying quads stretch","body_part":"upper legs","target":"quads","secondary_muscles":["hamstrings","glutes"],"equipment":"assisted","difficulty":"beginner","description":"The assisted prone lying quads stretch is a flexibility exercise targeting the quadriceps, performed by lying face down and using your hand to gently pull your foot towards your glutes, stretching the front of the thigh.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1713.gif","youtube_id":null,"instructions":["Lie face down on the ground with your legs extended.","Bend your left knee and reach back with your left hand to grab your left foot or ankle.","Gently pull your left foot towards your glutes, feeling a stretch in your left quad.","Hold the stretch for 20-30 seconds, then release.","Repeat with your right leg."]},{"id":"1714","name":"assisted prone rectus femoris stretch","body_part":"waist","target":"abs","secondary_muscles":["quadriceps"],"equipment":"assisted","difficulty":"beginner","description":"The assisted prone rectus femoris stretch is a flexibility exercise that targets the abdominal area and quadriceps. It is performed lying face down, bending one knee, and pulling the foot towards the glutes to stretch the front of the thigh.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1714.gif","youtube_id":null,"instructions":["Lie face down on the ground with your legs straight.","Bend your right knee and reach back with your right hand to grab your right foot or ankle.","Gently pull your right foot or ankle towards your glutes, feeling a stretch in the front of your right thigh.","Hold the stretch for 20-30 seconds.","Release and repeat on the other side."]},{"id":"1716","name":"assisted seated pectoralis major stretch with stability ball","body_part":"chest","target":"pectorals","secondary_muscles":["shoulders","triceps"],"equipment":"assisted","difficulty":"beginner","description":"The assisted seated pectoralis major stretch with a stability ball is a stretching exercise that targets the chest muscles, specifically the pectorals, and also involves the shoulders and triceps. It is performed while seated on a stability ball, using the ball to assist in deepening the stretch.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1716.gif","youtube_id":null,"instructions":["Sit on a stability ball with your feet flat on the ground and your back straight.","Hold a stability ball with both hands and extend your arms straight out in front of you.","Slowly lower the stability ball towards your chest, feeling a stretch in your pectoral muscles.","Hold the stretch for a few seconds, then slowly return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1717","name":"cable squat row (with rope attachment)","body_part":"back","target":"lats","secondary_muscles":["biceps","rhomboids","rear deltoids"],"equipment":"cable","difficulty":"intermediate","description":"The cable squat row (with rope attachment) is a compound exercise that combines a squat with a rowing motion, targeting the lats and engaging the biceps, rhomboids, and rear deltoids. It requires coordination, core stability, and strength.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1717.gif","youtube_id":null,"instructions":["Attach a rope to a cable machine at waist height.","Stand facing the cable machine with your feet shoulder-width apart.","Bend your knees and lower your body into a squat position, keeping your back straight and chest up.","Grasp the rope with an overhand grip, with your hands shoulder-width apart.","Engage your core and pull the rope towards your body, squeezing your shoulder blades together.","Keep your elbows close to your body and continue pulling until your hands reach your chest.","Pause for a moment at the top of the movement, then slowly release the rope and extend your arms back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1718","name":"barbell seated close grip behind neck triceps extension","body_part":"upper arms","target":"triceps","secondary_muscles":["shoulders"],"equipment":"barbell","difficulty":"intermediate","description":"The barbell seated close grip behind neck triceps extension is an upper arm exercise that targets the triceps and also engages the shoulders. It involves sitting on a bench, holding a barbell behind the neck with a close grip, and extending the arms upward.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1718.gif","youtube_id":null,"instructions":["Sit on a bench with your back straight and feet flat on the ground.","Hold the barbell with a close grip behind your neck, palms facing forward.","Keep your elbows close to your head and slowly lower the barbell towards the back of your head.","Pause for a moment, then extend your arms back up to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1719","name":"barbell incline close grip bench press","body_part":"upper arms","target":"triceps","secondary_muscles":["chest","shoulders"],"equipment":"barbell","difficulty":"intermediate","description":"The barbell incline close grip bench press is a compound upper body exercise that primarily targets the triceps, with secondary emphasis on the chest and shoulders. It is performed on an incline bench using a barbell with a close grip to maximize triceps activation.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1719.gif","youtube_id":null,"instructions":["Set up an incline bench at a 45-degree angle.","Lie down on the bench with your feet flat on the ground.","Grasp the barbell with a close grip, slightly narrower than shoulder-width apart.","Unrack the barbell and lower it slowly towards your chest, keeping your elbows close to your body.","Pause for a moment when the barbell touches your chest.","Push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]},{"id":"172","name":"cable incline pushdown","body_part":"back","target":"lats","secondary_muscles":["triceps","shoulders"],"equipment":"cable","difficulty":"intermediate","description":"The cable incline pushdown is an isolation exercise targeting the latissimus dorsi, performed using a cable machine with a straight bar attachment. It emphasizes controlled movement and proper form to effectively engage the lats while also involving the triceps and shoulders as secondary muscles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0172.gif","youtube_id":null,"instructions":["Attach a straight bar to a high pulley cable machine.","Stand facing away from the machine with your feet shoulder-width apart.","Grasp the bar with an overhand grip, hands slightly wider than shoulder-width apart.","Lean forward slightly and keep your back straight.","Pull the bar down towards your thighs by extending your elbows.","Pause for a moment at the bottom, then slowly return the bar to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1720","name":"barbell lying back of the head tricep extension","body_part":"upper arms","target":"triceps","secondary_muscles":["shoulders"],"equipment":"barbell","difficulty":"intermediate","description":"The barbell lying back of the head tricep extension is an isolation exercise targeting the triceps, performed lying on a bench and lowering a barbell behind the head.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1720.gif","youtube_id":null,"instructions":["Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.","Hold a barbell with an overhand grip, hands shoulder-width apart, and extend your arms straight up over your chest.","Keeping your upper arms stationary, slowly lower the barbell behind your head by bending your elbows.","Pause for a moment, then extend your arms back up to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1721","name":"barbell reverse grip skullcrusher","body_part":"upper arms","target":"triceps","secondary_muscles":["forearms"],"equipment":"barbell","difficulty":"intermediate","description":"The barbell reverse grip skullcrusher is a triceps-focused exercise performed lying on a bench, using a barbell held with a reverse (underhand) grip. It targets the triceps and also engages the forearms as secondary muscles. The movement requires control and proper form to avoid injury, especially to the elbows and wrists.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1721.gif","youtube_id":null,"instructions":["Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.","Hold the barbell with a reverse grip, palms facing towards your face, and your hands shoulder-width apart.","Extend your arms straight up over your chest, keeping your elbows in and your wrists straight.","Slowly lower the barbell towards your forehead by bending your elbows, keeping your upper arms stationary.","Pause for a moment at the bottom, then extend your arms back up to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1722","name":"cable high pulley overhead tricep extension","body_part":"upper arms","target":"triceps","secondary_muscles":["shoulders"],"equipment":"cable","difficulty":"intermediate","description":"The cable high pulley overhead tricep extension is an isolation exercise that targets the triceps using a cable machine. It requires the user to extend the arms overhead while keeping the elbows close to the head, focusing on triceps activation.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1722.gif","youtube_id":null,"instructions":["Attach a rope to a high pulley and stand facing away from the machine.","Grasp the rope with both hands and extend your arms overhead.","Keep your elbows close to your head and your upper arms stationary.","Slowly lower the rope behind your head by bending your elbows.","Pause for a moment, then extend your arms back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1723","name":"cable one arm tricep pushdown","body_part":"upper arms","target":"triceps","secondary_muscles":["forearms"],"equipment":"cable","difficulty":"beginner","description":"The cable one arm tricep pushdown is an isolation exercise targeting the triceps using a cable machine. It helps build triceps strength and definition, and also engages the forearms as secondary muscles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1723.gif","youtube_id":null,"instructions":["Stand facing a cable machine with a straight bar attachment at chest height.","Grasp the bar with an overhand grip and step back to create tension in the cable.","Position your feet shoulder-width apart and slightly bend your knees.","Keep your back straight and core engaged throughout the exercise.","Start with your arm fully extended and perpendicular to the floor.","Keeping your upper arm stationary, exhale and push the bar down until your arm is fully extended.","Pause for a moment, then inhale and slowly return to the starting position.","Repeat for the desired number of repetitions, then switch arms."]},{"id":"1724","name":"cable rope high pulley overhead tricep extension","body_part":"upper arms","target":"triceps","secondary_muscles":["shoulders"],"equipment":"cable","difficulty":"intermediate","description":"The cable rope high pulley overhead tricep extension is an isolation exercise targeting the triceps, performed using a cable machine with a rope attachment. It emphasizes triceps development and also engages the shoulders for stability.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1724.gif","youtube_id":null,"instructions":["Attach a rope to a high pulley and adjust the weight accordingly.","Stand facing away from the pulley machine with your feet shoulder-width apart.","Grasp the rope with both hands, palms facing down, and bring your hands above your head.","Keep your upper arms close to your head and perpendicular to the floor.","Slowly lower the rope behind your head by bending your elbows.","Pause for a moment, then extend your arms back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1725","name":"cable rope incline tricep extension","body_part":"upper arms","target":"triceps","secondary_muscles":["shoulders"],"equipment":"cable","difficulty":"intermediate","description":"The cable rope incline tricep extension is an isolation exercise targeting the triceps, performed on an incline bench using a rope attachment on a cable machine. It emphasizes triceps development and also engages the shoulders as secondary muscles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1725.gif","youtube_id":null,"instructions":["Attach a rope to a high pulley and adjust the incline bench to a comfortable angle.","Stand facing away from the pulley with your feet shoulder-width apart.","Grasp the rope with an overhand grip and extend your arms straight overhead.","Keep your elbows close to your head and your upper arms stationary throughout the exercise.","Lower the rope behind your head by bending your elbows until your forearms touch your biceps.","Pause for a moment, then extend your arms back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1726","name":"cable rope lying on floor tricep extension","body_part":"upper arms","target":"triceps","secondary_muscles":["shoulders"],"equipment":"cable","difficulty":"intermediate","description":"The cable rope lying on floor tricep extension is an isolation exercise targeting the triceps, performed lying on the floor with a cable machine. It requires proper form to avoid strain on the elbows and shoulders.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1726.gif","youtube_id":null,"instructions":["Attach a rope to a cable machine and set it to the lowest position.","Lie on the floor facing up, with your head towards the cable machine.","Hold the rope with both hands, palms facing each other, and extend your arms straight up towards the ceiling.","Keep your upper arms stationary and slowly lower the rope towards your forehead, bending your elbows.","Pause for a moment, then extend your arms back up to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1727","name":"cable standing reverse grip one arm overhead tricep extension","body_part":"upper arms","target":"triceps","secondary_muscles":["shoulders"],"equipment":"cable","difficulty":"intermediate","description":"The cable standing reverse grip one arm overhead tricep extension targets the triceps using a cable machine. It requires you to stand facing away from the machine, extend your arm overhead with an underhand grip, and perform an extension movement to work the triceps.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1727.gif","youtube_id":null,"instructions":["Stand facing away from the cable machine with your feet shoulder-width apart.","Hold the cable handle with an underhand grip and extend your arm overhead, keeping your elbow close to your head.","Keep your upper arm stationary and slowly lower the cable handle behind your head by bending your elbow.","Pause for a moment at the bottom, then extend your arm back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]},{"id":"1728","name":"cable two arm tricep kickback","body_part":"upper arms","target":"triceps","secondary_muscles":["shoulders"],"equipment":"cable","difficulty":"intermediate","description":"The cable two arm tricep kickback is an isolation exercise targeting the triceps using a cable machine. It requires maintaining proper posture and control to effectively engage the triceps while minimizing shoulder involvement.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1728.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and knees slightly bent.","Hold the cable handle in each hand with your palms facing inwards and your arms bent at a 90-degree angle.","Keeping your upper arms stationary, extend your forearms backwards until your arms are fully extended.","Pause for a moment, then slowly return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1729","name":"dumbbell lying alternate extension","body_part":"upper arms","target":"triceps","secondary_muscles":["shoulders"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell lying alternate extension is an isolation exercise targeting the triceps. It involves lying on a bench and alternately extending each arm with a dumbbell, focusing on controlled movement and muscle engagement.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1729.gif","youtube_id":null,"instructions":["Lie flat on a bench with a dumbbell in each hand, palms facing each other.","Extend your arms straight up over your chest, keeping a slight bend in your elbows.","Lower one dumbbell down towards your head, bending at the elbow, while keeping the other arm extended.","Pause for a moment at the bottom, then raise the dumbbell back up to the starting position.","Repeat with the other arm, alternating sides for the desired number of repetitions."]},{"id":"173","name":"cable incline triceps extension","body_part":"upper arms","target":"triceps","secondary_muscles":["shoulders"],"equipment":"cable","difficulty":"intermediate","description":"The cable incline triceps extension is an isolation exercise targeting the triceps using a cable machine. It requires the user to stand facing away from the machine and extend the arms overhead, emphasizing triceps engagement.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0173.gif","youtube_id":null,"instructions":["Adjust the cable machine to a low pulley position.","Attach a straight bar to the cable.","Stand facing away from the machine with your feet shoulder-width apart.","Grasp the bar with an overhand grip and extend your arms straight overhead.","Lean forward slightly, keeping your back straight and core engaged.","Bend your elbows and lower the bar behind your head, keeping your upper arms close to your ears.","Pause for a moment, then extend your arms back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1730","name":"dumbbell seated bent over alternate kickback","body_part":"upper arms","target":"triceps","secondary_muscles":["shoulders","back"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell seated bent over alternate kickback is an isolation exercise targeting the triceps. It is performed seated on a bench, bent forward at the waist, and involves extending each arm back alternately while holding dumbbells.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1730.gif","youtube_id":null,"instructions":["Sit on a bench with a dumbbell in each hand, palms facing inwards.","Bend forward at the waist, keeping your back straight and parallel to the ground.","Extend one arm straight back, keeping it close to your body, until your arm is fully extended.","Pause for a moment, then slowly lower the dumbbell back to the starting position.","Repeat with the other arm.","Continue alternating arms for the desired number of repetitions."]},{"id":"1731","name":"dumbbell close grip press","body_part":"upper arms","target":"triceps","secondary_muscles":["chest","shoulders"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell close grip press is a strength exercise targeting the triceps, with secondary emphasis on the chest and shoulders. It is performed by pressing dumbbells together with a close grip, focusing on triceps engagement.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1731.gif","youtube_id":null,"instructions":["Sit on a flat bench with a dumbbell in each hand, resting on your thighs.","Using your thighs to help raise the dumbbells, lift the dumbbells one at a time so that you can hold them in front of you at shoulder width.","Once at shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. This will be your starting position.","As you breathe in, slowly lower the dumbbells to your side until they are about level with your chest.","As you exhale, use your triceps to lift the dumbbells back to the starting position. Make sure to use only your triceps and do not use your forearms or biceps to help lift the dumbbells.","After a second pause at the contracted position, repeat the movement for the prescribed amount of repetitions."]},{"id":"1732","name":"dumbbell forward lunge triceps extension","body_part":"upper arms","target":"triceps","secondary_muscles":["shoulders","core"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell forward lunge triceps extension is a compound exercise that combines a lower body lunge with an overhead triceps extension, engaging the triceps, shoulders, core, and legs.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1732.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand.","Take a step forward with your right foot, lowering your body into a lunge position.","Keep your back straight and your chest up.","Extend your arms straight overhead, keeping your elbows close to your ears.","Lower the dumbbells behind your head by bending your elbows.","Pause for a moment, then straighten your arms to return to the starting position.","Repeat the movement for the desired number of repetitions, then switch legs and repeat."]},{"id":"1733","name":"dumbbell incline two arm extension","body_part":"upper arms","target":"triceps","secondary_muscles":["shoulders"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell incline two arm extension is an upper arm exercise targeting the triceps, performed on an incline bench with dumbbells. It also engages the shoulders as secondary muscles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1733.gif","youtube_id":null,"instructions":["Sit on an incline bench with a dumbbell in each hand, resting on your thighs.","Slowly lie back on the bench, keeping the dumbbells close to your chest.","Once you are fully lying down, extend your arms straight up towards the ceiling, keeping your elbows slightly bent.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1734","name":"dumbbell kickbacks on exercise ball","body_part":"upper arms","target":"triceps","secondary_muscles":["shoulders","back"],"equipment":"dumbbell","difficulty":"intermediate","description":"A triceps isolation exercise performed while seated on an exercise ball, which adds an element of balance and core engagement. The movement targets the triceps with secondary involvement from the shoulders and back.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1734.gif","youtube_id":null,"instructions":["Sit on an exercise ball with your feet flat on the ground and your back straight.","Hold a dumbbell in each hand with your palms facing inwards and your arms bent at a 90-degree angle.","Extend your arms straight back, squeezing your triceps at the top of the movement.","Pause for a moment, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1735","name":"dumbbell lying single extension","body_part":"upper arms","target":"triceps","secondary_muscles":["shoulders"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell lying single extension is an isolation exercise targeting the triceps. It is performed lying on a bench, extending one arm at a time with a dumbbell, focusing on controlled movement and triceps engagement.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1735.gif","youtube_id":null,"instructions":["Lie flat on a bench with a dumbbell in one hand and your arm fully extended above your chest.","Lower the dumbbell in a controlled manner towards your forehead, keeping your upper arm stationary.","Pause briefly at the bottom of the movement, then extend your arm back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]},{"id":"1736","name":"dumbbell one arm french press on exercise ball","body_part":"upper arms","target":"triceps","secondary_muscles":["shoulders"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell one arm French press on an exercise ball targets the triceps while also engaging the core and shoulders due to the instability of the exercise ball. This movement requires balance and coordination in addition to upper arm strength.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1736.gif","youtube_id":null,"instructions":["Sit on an exercise ball with your feet flat on the ground and your back straight.","Hold a dumbbell in one hand with your palm facing up and your elbow bent at a 90-degree angle.","Extend your arm straight up towards the ceiling, keeping your elbow stationary.","Slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch arms."]},{"id":"1737","name":"dumbbell seated bent over triceps extension","body_part":"upper arms","target":"triceps","secondary_muscles":["shoulders","back"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell seated bent over triceps extension is an isolation exercise targeting the triceps, performed while seated and bent over, extending the arms backward with dumbbells.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1737.gif","youtube_id":null,"instructions":["Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand.","Bend forward at the waist, keeping your back straight and your head up.","Extend your arms straight back, keeping your elbows close to your head.","Pause for a moment, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1738","name":"dumbbell seated reverse grip one arm overhead tricep extension","body_part":"upper arms","target":"triceps","secondary_muscles":["shoulders"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell seated reverse grip one arm overhead tricep extension is an isolation exercise targeting the triceps, performed with a single dumbbell using an underhand grip while seated. It emphasizes triceps development and also engages the shoulders for stability.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1738.gif","youtube_id":null,"instructions":["Sit on a bench with your back straight and feet flat on the ground.","Hold a dumbbell with an underhand grip and extend your arm straight up overhead.","Lower the dumbbell behind your head by bending your elbow, keeping your upper arm stationary.","Pause for a moment, then extend your arm back up to the starting position.","Repeat for the desired number of repetitions, then switch arms."]},{"id":"1739","name":"dumbbell standing alternating tricep kickback","body_part":"upper arms","target":"triceps","secondary_muscles":["shoulders"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell standing alternating tricep kickback is an isolation exercise targeting the triceps, performed while standing and alternating arms. It also engages the shoulders as secondary muscles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1739.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Extend your arms straight back, keeping your elbows close to your body.","Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Repeat with the other arm, alternating sides with each repetition."]},{"id":"174","name":"cable judo flip","body_part":"waist","target":"abs","secondary_muscles":["obliques","shoulders"],"equipment":"cable","difficulty":"intermediate","description":"The cable judo flip is a rotational core exercise that targets the abs, obliques, and shoulders using a cable machine. It mimics the motion of a judo throw, requiring coordination, core strength, and controlled movement.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0174.gif","youtube_id":null,"instructions":["Stand facing the cable machine with your feet shoulder-width apart.","Hold the cable handle with both hands at chest level, palms facing down.","Engage your core and rotate your torso to the right, pulling the cable across your body.","As you rotate, pivot your back foot and allow your hips to rotate naturally.","Extend your arms fully and finish the movement by flipping the cable handle over your shoulder.","Return to the starting position by reversing the movement, rotating your torso back to the center.","Repeat the movement on the opposite side.","Continue alternating sides for the desired number of repetitions."]},{"id":"1740","name":"dumbbell standing bent over one arm triceps extension","body_part":"upper arms","target":"triceps","secondary_muscles":["shoulders","back"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell standing bent over one arm triceps extension is an isolation exercise targeting the triceps, performed while bent over and extending the arm behind the body.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1740.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and hold a dumbbell in one hand.","Bend forward at the waist, keeping your back straight and parallel to the ground.","Extend your arm straight back, keeping your elbow close to your body.","Slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]},{"id":"1741","name":"dumbbell standing bent over two arm triceps extension","body_part":"upper arms","target":"triceps","secondary_muscles":["shoulders","back"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell standing bent over two arm triceps extension is an exercise targeting the triceps, performed by bending forward at the waist and extending the arms backward with dumbbells.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1741.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and hold a dumbbell in each hand.","Bend forward at the waist, keeping your back straight and your knees slightly bent.","Extend your arms straight back, keeping your elbows close to your body.","Slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1742","name":"dumbbell tricep kickback with stork stance","body_part":"upper arms","target":"triceps","secondary_muscles":["shoulders"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell tricep kickback with stork stance is a variation of the traditional tricep kickback that incorporates a balance challenge by having the exerciser stand on one leg (stork stance) while performing the movement. This targets the triceps while also engaging the core and stabilizing muscles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1742.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and hold a dumbbell in your right hand.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Bring your right elbow up to your side, keeping it bent at a 90-degree angle.","Extend your right arm straight back, squeezing your triceps.","Pause for a moment, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch sides."]},{"id":"1743","name":"dumbbell twisting bench press","body_part":"upper arms","target":"triceps","secondary_muscles":["chest","shoulders"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell twisting bench press is a variation of the standard dumbbell bench press that incorporates a wrist twist to further engage the triceps, chest, and shoulders. This exercise requires coordination and control to safely twist the wrists during the pressing motion.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1743.gif","youtube_id":null,"instructions":["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Hold a dumbbell in each hand with an overhand grip, palms facing away from you.","Extend your arms straight up over your chest, keeping a slight bend in your elbows.","Lower the dumbbells down towards your chest, keeping your elbows close to your body.","As you lower the dumbbells, twist your wrists so that your palms face towards you at the bottom of the movement.","Pause for a moment at the bottom, then reverse the movement by pressing the dumbbells back up to the starting position.","As you press the dumbbells up, twist your wrists back to the starting position with palms facing away from you.","Repeat for the desired number of repetitions."]},{"id":"1744","name":"exercise ball dip","body_part":"upper arms","target":"triceps","secondary_muscles":["chest","shoulders"],"equipment":"stability ball","difficulty":"intermediate","description":"The exercise ball dip is a triceps-focused movement performed using a stability ball. It challenges the triceps, chest, and shoulders while also requiring balance and core engagement due to the unstable surface.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1744.gif","youtube_id":null,"instructions":["Sit on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Place your hands on the ball beside your hips, fingers pointing forward.","Engage your triceps and push through your hands to lift your body off the ball, straightening your arms.","Lower your body back down by bending your elbows, keeping them close to your sides.","Repeat for the desired number of repetitions."]},{"id":"1745","name":"exercise ball seated triceps stretch","body_part":"upper arms","target":"triceps","secondary_muscles":["shoulders"],"equipment":"stability ball","difficulty":"beginner","description":"The exercise ball seated triceps stretch is a flexibility movement performed while seated on a stability ball, focusing on stretching the triceps and shoulders.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1745.gif","youtube_id":null,"instructions":["Sit on a stability ball with your feet flat on the ground and your back straight.","Hold a dumbbell in one hand and extend your arm straight up above your head.","Bend your elbow and lower the dumbbell behind your head, keeping your upper arm close to your ear.","Hold the stretch for a few seconds, then return to the starting position.","Repeat with the other arm."]},{"id":"1746","name":"exercise ball supine triceps extension","body_part":"upper arms","target":"triceps","secondary_muscles":["shoulders"],"equipment":"dumbbell","difficulty":"intermediate","description":"The exercise ball supine triceps extension is a strength exercise targeting the triceps, performed while lying on an exercise ball and using a dumbbell. It also engages the shoulders and requires core stability to maintain balance on the ball.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1746.gif","youtube_id":null,"instructions":["Sit on an exercise ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Hold a dumbbell with both hands and extend your arms straight up towards the ceiling.","Slowly lower the dumbbell behind your head, keeping your elbows close to your ears.","Pause for a moment, then raise the dumbbell back up to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1747","name":"ez bar french press on exercise ball","body_part":"upper arms","target":"triceps","secondary_muscles":["shoulders"],"equipment":"ez barbell, exercise ball","difficulty":"intermediate","description":"The EZ bar French press on an exercise ball is a triceps-focused exercise performed while seated on an unstable surface, which also engages the core and shoulders for stabilization. It involves lowering an EZ barbell behind the head and pressing it back up, targeting the triceps.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1747.gif","youtube_id":null,"instructions":["Sit on an exercise ball and hold an EZ barbell with an overhand grip.","Extend your arms straight up, keeping your elbows close to your head.","Slowly lower the barbell behind your head by bending your elbows.","Pause for a moment, then extend your arms back up to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1748","name":"ez bar lying close grip triceps extension behind head","body_part":"upper arms","target":"triceps","secondary_muscles":["shoulders"],"equipment":"ez barbell","difficulty":"intermediate","description":"The EZ bar lying close grip triceps extension behind head is an isolation exercise targeting the triceps, performed lying on a bench with a close grip on an EZ bar. It requires control and proper form to avoid shoulder strain and maximize triceps engagement.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1748.gif","youtube_id":null,"instructions":["Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.","Hold the ez barbell with a close grip, palms facing up, and extend your arms straight up over your chest.","Keeping your upper arms stationary, slowly lower the barbell behind your head by bending your elbows.","Pause for a moment, then extend your arms back up to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1749","name":"ez bar standing french press","body_part":"upper arms","target":"triceps","secondary_muscles":["shoulders"],"equipment":"ez barbell","difficulty":"intermediate","description":"The EZ bar standing French press is an isolation exercise targeting the triceps, performed while standing and using an EZ barbell. It involves extending the arms overhead and lowering the bar behind the head, emphasizing triceps engagement.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1749.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and hold the ez barbell with an overhand grip.","Raise the barbell above your head, fully extending your arms.","Keeping your upper arms close to your head, slowly lower the barbell behind your head by bending your elbows.","Pause for a moment, then extend your arms back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"175","name":"cable kneeling crunch","body_part":"waist","target":"abs","secondary_muscles":["obliques"],"equipment":"cable","difficulty":"intermediate","description":"The cable kneeling crunch is an abdominal exercise performed using a cable machine with a rope attachment. It targets the abs and also engages the obliques. The movement involves kneeling, holding the rope behind the head, and crunching the torso down towards the thighs.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0175.gif","youtube_id":null,"instructions":["Attach a rope handle to a high pulley and kneel down facing away from the machine.","Hold the rope handle with both hands and place it behind your head, keeping your elbows out to the sides.","Keeping your hips stationary, flex your waist and crunch your torso down towards your thighs.","Pause for a moment at the bottom, then slowly return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1750","name":"medicine ball supine chest throw","body_part":"upper arms","target":"triceps","secondary_muscles":["chest","shoulders"],"equipment":"medicine ball","difficulty":"intermediate","description":"The medicine ball supine chest throw is an explosive upper body exercise that targets the triceps, chest, and shoulders. It involves lying on your back and throwing a medicine ball upward, emphasizing power and speed.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1750.gif","youtube_id":null,"instructions":["Lie flat on your back on a bench with your knees bent and feet flat on the ground.","Hold the medicine ball with both hands, extending your arms straight up above your chest.","Lower the medicine ball towards your chest, keeping your elbows close to your body.","Explosively push the medicine ball upwards, extending your arms fully and throwing the ball as high as possible.","Catch the medicine ball and repeat for the desired number of repetitions."]},{"id":"1751","name":"barbell pin presses","body_part":"upper arms","target":"triceps","secondary_muscles":["shoulders"],"equipment":"barbell","difficulty":"intermediate","description":"Barbell pin presses are a strength exercise targeting the triceps, performed by pressing a barbell from a set height on a power rack. This movement emphasizes lockout strength and triceps development.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1751.gif","youtube_id":null,"instructions":["Set up a barbell on a power rack at chest height.","Stand facing the barbell and position yourself underneath it, with your feet shoulder-width apart.","Grip the barbell with an overhand grip, slightly wider than shoulder-width apart.","Lift the barbell off the rack and hold it directly above your chest, with your arms fully extended.","Lower the barbell down towards your chest, keeping your elbows tucked in close to your body.","Pause for a moment when the barbell touches your chest.","Push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]},{"id":"1752","name":"smith machine incline tricep extension","body_part":"upper arms","target":"triceps","secondary_muscles":["shoulders"],"equipment":"smith machine","difficulty":"intermediate","description":"The smith machine incline tricep extension is an isolation exercise that targets the triceps using a smith machine and an incline bench. It involves extending the arms to work the triceps, with some involvement of the shoulders for stabilization.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1752.gif","youtube_id":null,"instructions":["Adjust the seat of the smith machine so that the bar is at shoulder height.","Sit on the bench with your back against the pad and your feet flat on the ground.","Grasp the bar with an overhand grip, slightly wider than shoulder-width apart.","Extend your arms fully, lifting the bar off the rack and holding it directly above your chest.","Lower the bar slowly towards your forehead, keeping your elbows close to your head.","Pause for a moment at the bottom, then push the bar back up to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1753","name":"three bench dip","body_part":"upper arms","target":"triceps","secondary_muscles":["chest","shoulders"],"equipment":"body weight","difficulty":"advanced","description":"The three bench dip is a bodyweight exercise targeting the triceps, performed using three benches to elevate the feet and hands, increasing the range of motion and difficulty compared to standard dips.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1753.gif","youtube_id":null,"instructions":["Sit on a bench with your hands gripping the edge, fingers pointing forward.","Slide your butt off the bench, supporting your weight with your hands.","Place your feet on a second bench and, if using a third, elevate your legs further.","Bend your elbows and lower your body until your upper arms are parallel to the ground.","Push yourself back up to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1754","name":"weighted three bench dips","body_part":"upper arms","target":"triceps","secondary_muscles":["chest","shoulders"],"equipment":"weighted","difficulty":"advanced","description":"The weighted three bench dips is a triceps-focused exercise that involves supporting your body weight between three benches while adding extra resistance. It targets the triceps and also works the chest and shoulders. This movement requires significant upper body strength, stability, and proper form to avoid injury.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1754.gif","youtube_id":null,"instructions":["Sit on the edge of a bench with your hands gripping the edge, fingers pointing forward.","Walk your feet forward, sliding your butt off the bench and supporting your weight with your arms.","Lower your body by bending your elbows, keeping your back close to the bench.","Pause for a moment at the bottom, then push yourself back up to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1755","name":"weighted tricep dips","body_part":"upper arms","target":"triceps","secondary_muscles":["chest","shoulders"],"equipment":"weighted","difficulty":"advanced","description":"Weighted tricep dips are a challenging upper body exercise that primarily targets the triceps, with additional activation of the chest and shoulders. Adding weight increases the intensity and requires greater strength and stability compared to bodyweight dips.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1755.gif","youtube_id":null,"instructions":["Sit on the edge of a bench or chair with your hands gripping the edge next to your hips.","Slide your butt off the front of the bench with your legs extended in front of you.","Keep your back close to the bench and your elbows slightly bent.","Lower your body by bending your elbows until your upper arms are parallel to the floor.","Push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."]},{"id":"1756","name":"barbell single leg deadlift","body_part":"upper legs","target":"glutes","secondary_muscles":["hamstrings","lower back"],"equipment":"barbell","difficulty":"advanced","description":"The barbell single leg deadlift is a unilateral lower body exercise that targets the glutes, with secondary emphasis on the hamstrings and lower back. It challenges balance, coordination, and strength by requiring you to hinge at the hips on one leg while holding a barbell.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1756.gif","youtube_id":null,"instructions":["Stand with your feet hip-width apart, holding a barbell in front of your thighs with an overhand grip.","Shift your weight onto your left foot and lift your right foot slightly off the ground.","Hinge forward at the hips, keeping your back straight and your right leg extended behind you for balance.","Lower the barbell towards the ground, keeping it close to your body and your left leg slightly bent.","Pause for a moment at the bottom, then engage your glutes and hamstrings to lift your torso back up to the starting position.","Repeat for the desired number of repetitions, then switch sides."]},{"id":"1757","name":"dumbbell single leg deadlift","body_part":"upper legs","target":"glutes","secondary_muscles":["hamstrings","lower back"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell single leg deadlift is a unilateral lower body exercise that targets the glutes, hamstrings, and lower back. It challenges balance, coordination, and strength by requiring you to stabilize on one leg while hinging at the hips and lifting a dumbbell.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1757.gif","youtube_id":null,"instructions":["Stand with your feet hip-width apart, holding a dumbbell in your right hand.","Shift your weight onto your left leg and lift your right foot slightly off the ground.","Keeping your back straight, hinge forward at the hips and lower the dumbbell towards the ground.","At the same time, extend your right leg straight behind you, maintaining a slight bend in your left knee.","Lower the dumbbell until your torso and right leg are parallel to the ground.","Pause for a moment, then engage your glutes and hamstrings to return to the starting position.","Repeat for the desired number of repetitions, then switch sides."]},{"id":"1758","name":"assisted sit-up","body_part":"waist","target":"abs","secondary_muscles":["hip flexors"],"equipment":"assisted","difficulty":"beginner","description":"The assisted sit-up is a core exercise that targets the abdominal muscles with support, making it easier to perform than a standard sit-up. Assistance can come from a bench, partner, or anchored feet, reducing the strength and coordination required.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1758.gif","youtube_id":null,"instructions":["Sit on the edge of a bench or have someone hold your feet down.","Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1759","name":"single leg squat (pistol) male","body_part":"upper legs","target":"glutes","secondary_muscles":["quadriceps","hamstrings","calves"],"equipment":"body weight","difficulty":"advanced","description":"The single leg squat (pistol squat) is a challenging lower body exercise that targets the glutes, quadriceps, hamstrings, and calves. It requires significant strength, balance, and mobility to perform correctly, making it suitable for advanced practitioners.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1759.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and arms extended in front of you.","Lift your right foot off the ground and extend it forward.","Slowly lower your body down by bending your left knee and pushing your hips back.","Keep your chest up and your back straight as you lower yourself down.","Lower until your left thigh is parallel to the ground, or as low as you can comfortably go.","Pause for a moment at the bottom, then push through your left heel to return to the starting position.","Repeat for the desired number of repetitions, then switch legs."]},{"id":"176","name":"cable kneeling triceps extension","body_part":"upper arms","target":"triceps","secondary_muscles":["shoulders"],"equipment":"cable","difficulty":"intermediate","description":"The cable kneeling triceps extension is an isolation exercise targeting the triceps using a cable machine. It requires kneeling in front of a high pulley and extending the arms to work the triceps.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0176.gif","youtube_id":null,"instructions":["Attach a rope handle to a high pulley and kneel down facing the cable machine.","Grasp the rope with a neutral grip (palms facing each other) and bring your hands to the sides of your head.","Keep your elbows close to your head and your upper arms stationary throughout the exercise.","Extend your forearms by contracting your triceps until your arms are fully extended.","Pause for a moment, then slowly return to the starting position by bending your elbows.","Repeat for the desired number of repetitions."]},{"id":"1760","name":"dumbbell goblet squat","body_part":"upper legs","target":"quads","secondary_muscles":["glutes","hamstrings","calves"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell goblet squat is a lower body exercise that targets the quadriceps while also engaging the glutes, hamstrings, and calves. It is performed by holding a dumbbell close to the chest and squatting down, making it a great movement for building strength and improving squat technique.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1760.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, holding a dumbbell vertically against your chest with both hands.","Keeping your chest up and core engaged, lower your body down into a squat position by pushing your hips back and bending your knees.","Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1761","name":"hanging oblique knee raise","body_part":"waist","target":"abs","secondary_muscles":["obliques"],"equipment":"body weight","difficulty":"advanced","description":"The hanging oblique knee raise is a core exercise performed by hanging from a pull-up bar and raising the knees towards the chest while twisting the torso to target the abs and obliques.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1761.gif","youtube_id":null,"instructions":["Hang from a pull-up bar with your arms fully extended and your palms facing away from you.","Engage your core and lift your knees towards your chest, twisting your torso to the side as you do so.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat on the other side, twisting your torso in the opposite direction.","Continue alternating sides for the desired number of repetitions."]},{"id":"1763","name":"shoulder grip pull-up","body_part":"back","target":"lats","secondary_muscles":["biceps","forearms"],"equipment":"body weight","difficulty":"intermediate","description":"The shoulder grip pull-up is a bodyweight exercise targeting the latissimus dorsi (lats) and also engaging the biceps and forearms. It requires the individual to pull their body up to a bar using a shoulder-width, overhand grip.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1763.gif","youtube_id":null,"instructions":["Grab the pull-up bar with a shoulder-width grip, palms facing away from you.","Hang freely with your arms fully extended.","Engage your back muscles and pull your body up towards the bar until your chin is above the bar.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1764","name":"hanging leg hip raise","body_part":"waist","target":"abs","secondary_muscles":["hip flexors","lower back"],"equipment":"body weight","difficulty":"intermediate","description":"The hanging leg hip raise is a bodyweight exercise that targets the abdominal muscles by requiring you to hang from a pull-up bar and lift your legs, engaging your core and hip flexors.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1764.gif","youtube_id":null,"instructions":["Hang from a pull-up bar with your arms fully extended and your palms facing away from you.","Engage your core and lift your legs up by flexing your hips and knees until your thighs are parallel to the ground.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1765","name":"dumbbell upright row (back pov)","body_part":"shoulders","target":"delts","secondary_muscles":["traps","biceps"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell upright row (back pov) is a strength exercise targeting the deltoids, with secondary emphasis on the traps and biceps. It involves lifting dumbbells from thigh level to shoulder height, leading with the elbows.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1765.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.","Let the dumbbells hang in front of your thighs, with your arms fully extended and your palms facing your body.","Keeping your back straight and your core engaged, exhale and lift the dumbbells straight up towards your chin, leading with your elbows.","Continue lifting until the dumbbells are at shoulder height, with your elbows pointing out to the sides.","Pause for a moment at the top, then inhale and slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1766","name":"self assisted inverse leg curl","body_part":"upper legs","target":"hamstrings","secondary_muscles":["glutes","calves"],"equipment":"body weight","difficulty":"advanced","description":"The self assisted inverse leg curl is a bodyweight exercise targeting the hamstrings, performed by lying face down and curling the legs upward against gravity, often using the arms for assistance. It primarily works the hamstrings, with secondary emphasis on the glutes and calves.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1766.gif","youtube_id":null,"instructions":["Lie face down on a leg curl machine with your legs extended and your ankles hooked under the padded lever.","Place your hands on the side handles of the machine for support.","Keeping your upper body stationary, exhale and curl your legs upward as far as possible.","Hold the contracted position for a brief pause as you squeeze your hamstrings.","Slowly lower your legs back to the starting position while inhaling.","Repeat for the desired number of repetitions."]},{"id":"1767","name":"weighted triceps dip on high parallel bars","body_part":"upper arms","target":"triceps","secondary_muscles":["chest","shoulders"],"equipment":"weighted","difficulty":"advanced","description":"The weighted triceps dip on high parallel bars is an advanced upper body exercise that primarily targets the triceps, while also engaging the chest and shoulders. The addition of weight increases the strength and stability demands, making it suitable for experienced lifters.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1767.gif","youtube_id":null,"instructions":["Position yourself between two parallel bars with your hands gripping the bars and your arms fully extended.","Bend your elbows and lower your body until your upper arms are parallel to the ground.","Pause for a moment, then push through your palms to straighten your arms and return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1769","name":"bodyweight side lying biceps curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"body weight","difficulty":"beginner","description":"The bodyweight side lying biceps curl is a biceps-focused exercise performed lying on your side, using only your body weight for resistance. It primarily targets the biceps and also engages the forearms.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1769.gif","youtube_id":null,"instructions":["Lie on your side with your legs extended and your head supported by your arm.","Hold your upper arm against your side and bend your elbow to curl your forearm towards your shoulder.","Pause for a moment at the top, then slowly lower your forearm back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"177","name":"cable lateral pulldown (with rope attachment)","body_part":"back","target":"lats","secondary_muscles":["biceps","forearms"],"equipment":"cable","difficulty":"beginner","description":"The cable lateral pulldown (with rope attachment) is a strength exercise targeting the latissimus dorsi (lats) using a cable machine with a rope attachment. It also engages the biceps and forearms as secondary muscles. The movement involves pulling the rope down towards your sides while maintaining proper posture and squeezing the shoulder blades together.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0177.gif","youtube_id":null,"instructions":["Attach a rope attachment to the cable machine at a high position.","Stand facing the machine with your feet shoulder-width apart.","Grasp the rope with an overhand grip, palms facing each other.","Keep your back straight and lean slightly back.","Pull the rope down towards your sides, squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement.","Slowly release the tension and allow the rope to return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1770","name":"biceps leg concentration curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"body weight","difficulty":"beginner","description":"The biceps leg concentration curl is an isolation exercise targeting the biceps, performed while seated and using the leg for support. It emphasizes strict form and muscle contraction.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1770.gif","youtube_id":null,"instructions":["Sit on a bench with your legs spread apart and your feet flat on the ground.","Hold a dumbbell in one hand and place your elbow on the inside of your thigh, just above the knee.","With your palm facing up, curl the dumbbell towards your shoulder while keeping your upper arm stationary.","Squeeze your biceps at the top of the movement, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]},{"id":"1771","name":"bodyweight kneeling triceps extension","body_part":"upper arms","target":"triceps","secondary_muscles":["shoulders","chest"],"equipment":"body weight","difficulty":"intermediate","description":"The bodyweight kneeling triceps extension is a bodyweight exercise that targets the triceps, with secondary emphasis on the shoulders and chest. It involves lowering your body by bending the elbows while keeping the core engaged and then pressing back up to the starting position.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1771.gif","youtube_id":null,"instructions":["Kneel down on the ground with your knees hip-width apart.","Place your hands on the ground in front of you, shoulder-width apart, fingers pointing forward.","Extend your legs straight behind you, balancing on your toes and hands, forming a straight line from head to heels.","Bend your elbows and lower your upper body towards the ground, keeping your elbows close to your sides.","Pause for a moment at the bottom, then push through your hands to straighten your arms and return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1772","name":"elbow lift - reverse push-up","body_part":"back","target":"upper back","secondary_muscles":["triceps","shoulders"],"equipment":"body weight","difficulty":"beginner","description":"The elbow lift - reverse push-up is a bodyweight exercise that targets the upper back, with secondary emphasis on the triceps and shoulders. It involves lifting the upper body off the ground while keeping the elbows close to the sides, focusing on squeezing the upper back muscles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1772.gif","youtube_id":null,"instructions":["Start by lying face down on the ground with your legs extended and your hands placed directly under your shoulders.","Engage your core and press through your palms to lift your upper body off the ground, keeping your elbows close to your sides.","Pause at the top for a moment, squeezing your upper back muscles.","Slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"1773","name":"one arm towel row","body_part":"back","target":"upper back","secondary_muscles":["biceps","forearms"],"equipment":"body weight","difficulty":"intermediate","description":"The one arm towel row is a bodyweight exercise targeting the upper back, performed by pulling a towel with one arm while maintaining a strong core and straight back.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1773.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, knees slightly bent, and hold a towel with one hand.","Bend forward at the waist, keeping your back straight and your core engaged.","Extend your arm fully, allowing the towel to hang in front of you.","Pull the towel towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the towel back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]},{"id":"1774","name":"side bridge hip abduction","body_part":"upper legs","target":"abductors","secondary_muscles":["glutes","obliques"],"equipment":"body weight","difficulty":"intermediate","description":"The side bridge hip abduction is a bodyweight exercise that targets the hip abductors, glutes, and obliques. It involves holding a side plank position while lifting the top leg, challenging both strength and stability.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1774.gif","youtube_id":null,"instructions":["Lie on your side with your legs extended and stacked on top of each other.","Prop yourself up on your forearm, keeping your elbow directly below your shoulder.","Engage your core and lift your hips off the ground, creating a straight line from your head to your feet.","While keeping your core engaged, lift your top leg as high as possible without rotating your hips.","Pause for a moment at the top, then lower your leg back down.","Repeat for the desired number of repetitions, then switch sides."]},{"id":"1775","name":"side plank hip adduction","body_part":"upper legs","target":"adductors","secondary_muscles":["obliques","glutes"],"equipment":"body weight","difficulty":"advanced","description":"The side plank hip adduction is a bodyweight exercise that targets the adductors while also engaging the obliques and glutes. It requires maintaining a side plank position while lifting the top leg, challenging both strength and balance.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-1775.gif","youtube_id":null,"instructions":["Start by lying on your side with your legs extended and stacked on top of each other.","Prop yourself up on your forearm, keeping your elbow directly below your shoulder.","Engage your core and lift your hips off the ground, creating a straight line from your head to your feet.","While maintaining the side plank position, lift your top leg towards the ceiling, keeping it straight.","Slowly lower your leg back down to the starting position.","Repeat for the desired number of repetitions, then switch sides."]},{"id":"178","name":"cable lateral raise","body_part":"shoulders","target":"delts","secondary_muscles":["traps","triceps"],"equipment":"cable","difficulty":"intermediate","description":"The cable lateral raise is an isolation exercise that targets the deltoid muscles, particularly the lateral (middle) head. It is performed using a cable machine, which provides constant tension throughout the movement. This exercise helps build shoulder width and strength.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0178.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and grasp the cable handles with an overhand grip.","Keep your arms straight and your core engaged.","Raise your arms out to the sides until they are parallel to the floor.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"179","name":"cable low fly","body_part":"chest","target":"pectorals","secondary_muscles":["deltoids","triceps"],"equipment":"cable","difficulty":"intermediate","description":"The cable low fly is an isolation exercise targeting the pectoral muscles using a cable machine. It involves bringing the arms together in front of the body from a low starting position, emphasizing the lower and inner chest.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0179.gif","youtube_id":null,"instructions":["Attach the handles to the low pulleys of a cable machine and select an appropriate weight.","Stand in the middle of the machine with your feet shoulder-width apart and a slight bend in your knees.","Grasp the handles with an overhand grip and extend your arms out to the sides, keeping a slight bend in your elbows.","Maintaining control, slowly bring your arms forward in a sweeping motion, crossing them in front of your body.","Pause for a moment at the peak of the movement, feeling the stretch in your chest muscles.","Reverse the motion and slowly return your arms to the starting position, keeping tension on your chest muscles throughout.","Repeat for the desired number of repetitions."]},{"id":"18","name":"assisted standing triceps extension (with towel)","body_part":"upper arms","target":"triceps","secondary_muscles":["shoulders"],"equipment":"assisted (towel)","difficulty":"beginner","description":"The assisted standing triceps extension (with towel) is an exercise targeting the triceps using a towel for assistance. It is performed standing, with the towel held behind the head, extending the arms upward to work the triceps.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0018.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and hold a towel with both hands behind your head.","Keep your elbows close to your ears and your upper arms stationary.","Slowly extend your forearms upward, squeezing your triceps at the top.","Pause for a moment, then slowly lower the towel back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"180","name":"cable low seated row","body_part":"back","target":"upper back","secondary_muscles":["biceps","forearms"],"equipment":"cable","difficulty":"beginner","description":"The cable low seated row is a strength exercise targeting the upper back, performed on a cable machine. It also engages the biceps and forearms as secondary muscles. The movement involves pulling the cable handles toward the torso while maintaining a straight back and squeezing the shoulder blades together.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0180.gif","youtube_id":null,"instructions":["Sit on the machine with your feet flat on the footrests and your knees slightly bent.","Grasp the handles with an overhand grip, palms facing down.","Keep your back straight and lean slightly forward, maintaining a slight bend in your elbows.","Pull the handles towards your body, squeezing your shoulder blades together.","Pause for a moment at the peak of the movement, then slowly release the handles back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"182","name":"cable lying close-grip curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"cable","difficulty":"intermediate","description":"The cable lying close-grip curl is an isolation exercise targeting the biceps, performed lying on a bench with a cable machine. It emphasizes strict form and constant tension on the biceps.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0182.gif","youtube_id":null,"instructions":["Attach a straight bar to a low pulley cable machine.","Lie face up on a flat bench with your feet flat on the ground.","Grasp the bar with an underhand grip, hands shoulder-width apart.","Extend your arms fully, keeping your elbows close to your sides.","Keeping your upper arms stationary, curl the bar towards your chest by contracting your biceps.","Pause for a moment at the top, squeezing your biceps.","Slowly lower the bar back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]},{"id":"184","name":"cable lying extension pullover (with rope attachment)","body_part":"back","target":"lats","secondary_muscles":["triceps","shoulders"],"equipment":"cable","difficulty":"intermediate","description":"The cable lying extension pullover (with rope attachment) is an isolation exercise targeting the lats, performed lying on a bench with a cable machine. It requires maintaining proper form and control throughout the movement to effectively engage the back muscles while minimizing risk to the shoulders.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0184.gif","youtube_id":null,"instructions":["Attach a rope to a cable machine and set the pulley at the highest position.","Lie down on a bench with your head towards the cable machine.","Hold the rope with both hands and extend your arms straight up above your chest.","Keeping your arms straight, slowly lower the rope behind your head while maintaining control.","Pause for a moment at the bottom, then slowly raise the rope back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"185","name":"cable lying fly","body_part":"chest","target":"pectorals","secondary_muscles":["deltoids","triceps"],"equipment":"cable","difficulty":"intermediate","description":"The cable lying fly is a chest isolation exercise performed on a bench using cable machines. It targets the pectoral muscles and also engages the deltoids and triceps as secondary muscles. The movement involves lowering the arms in a wide arc and then bringing them back together, focusing on squeezing the chest.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0185.gif","youtube_id":null,"instructions":["Attach the handles to the cables and lie flat on a bench with your feet flat on the ground.","Hold the handles with your palms facing each other and your arms extended straight above your chest.","Keeping a slight bend in your elbows, lower your arms out to the sides in a wide arc until you feel a stretch in your chest.","Pause for a moment, then squeeze your chest muscles to bring your arms back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"186","name":"cable lying triceps extension v. 2","body_part":"upper arms","target":"triceps","secondary_muscles":["shoulders"],"equipment":"cable","difficulty":"intermediate","description":"The cable lying triceps extension v. 2 is an isolation exercise targeting the triceps, performed lying on a bench with a rope attachment on a low pulley cable machine. It emphasizes controlled elbow extension and is commonly used to build triceps strength and size.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0186.gif","youtube_id":null,"instructions":["Attach a rope handle to a low pulley cable machine.","Lie down on a flat bench facing up, with your head towards the cable machine.","Grasp the rope handle with both hands, palms facing each other, and extend your arms straight up over your chest.","Keeping your upper arms stationary, slowly lower the rope handle towards your forehead by bending your elbows.","Pause for a moment at the bottom, then extend your arms back up to the starting position.","Repeat for the desired number of repetitions."]},{"id":"188","name":"cable middle fly","body_part":"chest","target":"pectorals","secondary_muscles":["deltoids","triceps"],"equipment":"cable","difficulty":"intermediate","description":"The cable middle fly is an isolation exercise targeting the pectoral muscles using a cable machine. It emphasizes chest development and also engages the deltoids and triceps as secondary muscles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0188.gif","youtube_id":null,"instructions":["Attach cables to both sides of a cable machine at chest height.","Stand in the center of the machine with one foot slightly in front of the other.","Grasp the handles with an overhand grip and extend your arms out to the sides.","Keep a slight bend in your elbows and maintain a slight forward lean.","Engage your chest muscles and bring your arms forward in a sweeping motion.","Pause for a moment at the center, then slowly return your arms back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"189","name":"cable one arm bent over row","body_part":"back","target":"upper back","secondary_muscles":["biceps","forearms"],"equipment":"cable","difficulty":"intermediate","description":"The cable one arm bent over row is a unilateral pulling exercise that targets the upper back, requiring core stability and coordination. It is performed using a cable machine and emphasizes controlled movement and proper form.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0189.gif","youtube_id":null,"instructions":["Stand facing a cable machine with your feet shoulder-width apart.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Grasp the cable handle with one hand, palm facing inward, and extend your arm fully.","Pull the cable handle towards your body, keeping your elbow close to your side, until your hand reaches your lower chest.","Pause for a moment, then slowly extend your arm back to the starting position.","Repeat for the desired number of repetitions, then switch sides."]},{"id":"19","name":"assisted triceps dip (kneeling)","body_part":"upper arms","target":"triceps","secondary_muscles":["chest","shoulders"],"equipment":"leverage machine","difficulty":"beginner","description":"The assisted triceps dip (kneeling) is performed on a leverage machine, allowing users to target the triceps with support, making the exercise accessible for those who may not yet have the strength for unassisted dips. It also engages the chest and shoulders as secondary muscles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0019.gif","youtube_id":null,"instructions":["Adjust the machine to your desired weight and height.","Kneel down on the pad facing the machine, with your hands gripping the handles.","Lower your body by bending your elbows, keeping your back straight and close to the machine.","Pause for a moment at the bottom, then push yourself back up to the starting position.","Repeat for the desired number of repetitions."]},{"id":"190","name":"cable one arm curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"cable","difficulty":"beginner","description":"The cable one arm curl is an isolation exercise targeting the biceps using a cable machine. It allows for constant tension throughout the movement, making it effective for muscle growth and strength development in the biceps and forearms.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0190.gif","youtube_id":null,"instructions":["Stand facing the cable machine with your feet shoulder-width apart.","Grasp the cable handle with an underhand grip, palm facing up.","Keep your elbow close to your side and slowly curl your forearm up towards your shoulder.","Pause for a moment at the top, then slowly lower your forearm back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"191","name":"cable one arm lateral bent-over","body_part":"chest","target":"pectorals","secondary_muscles":["deltoids","trapezius"],"equipment":"cable","difficulty":"intermediate","description":"The cable one arm lateral bent-over is an isolation exercise targeting the pectoral muscles, performed using a cable machine. It involves extending one arm laterally while bent over, focusing on chest activation with secondary involvement of the deltoids and trapezius.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0191.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, facing a cable machine.","Grasp the handle with one hand and step back to create tension on the cable.","Bend forward at the waist, keeping your back straight and your core engaged.","Extend your arm out to the side, parallel to the ground, with a slight bend in your elbow.","Slowly bring your arm back to the starting position, maintaining control throughout the movement.","Repeat for the desired number of repetitions, then switch sides."]},{"id":"192","name":"cable one arm lateral raise","body_part":"shoulders","target":"delts","secondary_muscles":["traps","triceps"],"equipment":"cable","difficulty":"intermediate","description":"The cable one arm lateral raise is an isolation exercise targeting the deltoid muscles, particularly the lateral (side) head. It is performed using a cable machine, which provides constant tension throughout the movement. This exercise helps build shoulder width and strength.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0192.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, facing the cable machine.","Hold the cable handle with one hand, palm facing down, and stand far enough away from the machine so that there is tension on the cable.","Keep your arm straight and slowly raise it out to the side until it is parallel to the ground.","Pause for a moment at the top, then slowly lower your arm back down to the starting position.","Repeat for the desired number of repetitions, then switch sides."]},{"id":"193","name":"cable one arm straight back high row (kneeling)","body_part":"back","target":"upper back","secondary_muscles":["biceps","shoulders"],"equipment":"cable","difficulty":"intermediate","description":"The cable one arm straight back high row (kneeling) is an exercise that targets the upper back, performed using a cable machine. It also engages the biceps and shoulders, and is done in a kneeling position to help isolate the upper back muscles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0193.gif","youtube_id":null,"instructions":["Attach a handle to a cable machine at waist height.","Kneel down facing the cable machine and grab the handle with one hand.","Keep your back straight and your core engaged.","Pull the handle towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top of the movement.","Slowly release the handle back to the starting position.","Repeat for the desired number of repetitions.","Switch sides and repeat the exercise with the other arm."]},{"id":"194","name":"cable overhead triceps extension (rope attachment)","body_part":"upper arms","target":"triceps","secondary_muscles":["shoulders"],"equipment":"cable","difficulty":"intermediate","description":"The cable overhead triceps extension (rope attachment) is an isolation exercise targeting the triceps using a cable machine and rope attachment. It requires the user to extend the arms overhead, emphasizing triceps engagement while also involving the shoulders for stabilization.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0194.gif","youtube_id":null,"instructions":["Attach a rope to a cable machine at a high position.","Stand facing away from the machine with your feet shoulder-width apart.","Grasp the rope with both hands, palms facing each other, and bring your hands above your head.","Keep your upper arms close to your head and your elbows pointing forward.","Slowly lower the rope behind your head by bending your elbows.","Pause for a moment, then extend your arms back up to the starting position.","Repeat for the desired number of repetitions."]},{"id":"195","name":"cable preacher curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"cable","difficulty":"beginner","description":"The cable preacher curl is an isolation exercise targeting the biceps using a cable machine and a preacher curl pad. It emphasizes strict form and constant tension on the biceps throughout the movement.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0195.gif","youtube_id":null,"instructions":["Adjust the cable machine so that the preacher curl pad is at chest height.","Sit on the preacher curl bench and place your upper arms on the pad, gripping the cable attachment with an underhand grip.","Keep your back straight and your elbows tucked in at your sides.","Slowly curl the cable attachment up towards your shoulders, squeezing your biceps at the top of the movement.","Pause for a moment, then slowly lower the cable attachment back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"196","name":"cable pull through (with rope)","body_part":"upper legs","target":"glutes","secondary_muscles":["hamstrings","lower back"],"equipment":"cable","difficulty":"intermediate","description":"The cable pull through (with rope) is a hip hinge exercise that targets the glutes, with secondary emphasis on the hamstrings and lower back. It is performed using a cable machine and a rope attachment, focusing on hip extension and posterior chain activation.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0196.gif","youtube_id":null,"instructions":["Stand facing away from the cable machine with your feet shoulder-width apart.","Grab the rope attachment with both hands and step forward, creating tension in the cable.","Bend at the hips and lower your upper body until it is parallel to the ground, keeping your back straight.","Engage your glutes and hamstrings to pull your body back up to the starting position.","Repeat for the desired number of repetitions."]},{"id":"197","name":"cable pulldown (pro lat bar)","body_part":"back","target":"lats","secondary_muscles":["biceps","forearms"],"equipment":"cable","difficulty":"beginner","description":"The cable pulldown (pro lat bar) is a strength exercise that targets the latissimus dorsi (lats) and also works the biceps and forearms. It is performed using a cable machine with a pro lat bar attachment.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0197.gif","youtube_id":null,"instructions":["Adjust the seat height so that your thighs are parallel to the ground and your feet are flat on the floor.","Grasp the lat bar with an overhand grip, slightly wider than shoulder-width apart.","Sit down and lean back slightly, keeping your chest up and your back straight.","Pull the bar down towards your chest, squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, then slowly release the bar back up to the starting position.","Repeat for the desired number of repetitions."]},{"id":"198","name":"cable pulldown","body_part":"back","target":"lats","secondary_muscles":["biceps","forearms"],"equipment":"cable","difficulty":"beginner","description":"The cable pulldown is a strength exercise targeting the latissimus dorsi (lats) using a cable machine. It is commonly performed to build upper back strength and muscle mass.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0198.gif","youtube_id":null,"instructions":["Adjust the cable pulldown machine so that the seat is at a comfortable height and the knee pad is secured.","Sit on the seat with your back straight and your feet flat on the ground.","Grasp the cable bar with an overhand grip, slightly wider than shoulder-width apart.","Lean back slightly and engage your core.","Pull the cable bar down towards your chest, squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, then slowly release the bar back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"199","name":"cable pushdown (straight arm) v. 2","body_part":"back","target":"lats","secondary_muscles":["triceps","shoulders"],"equipment":"cable","difficulty":"beginner","description":"The cable pushdown (straight arm) v. 2 is an isolation exercise primarily targeting the latissimus dorsi (lats) using a cable machine with a straight bar attachment. It also engages the triceps and shoulders as secondary muscles. The movement requires maintaining straight arms and a stable core throughout the exercise.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0199.gif","youtube_id":null,"instructions":["Attach a straight bar to a high pulley cable machine.","Stand facing the machine with your feet shoulder-width apart and a slight bend in your knees.","Grasp the bar with an overhand grip, keeping your arms straight and your palms facing down.","Engage your core and keep your back straight as you exhale and push the bar down towards your thighs.","Pause for a moment at the bottom, then slowly return the bar to the starting position while inhaling.","Repeat for the desired number of repetitions."]},{"id":"2","name":"45° side bend","body_part":"waist","target":"abs","secondary_muscles":["obliques"],"equipment":"body weight","difficulty":"beginner","description":"The 45° side bend is a bodyweight exercise targeting the abdominal muscles, particularly the obliques. It involves bending the torso to the side while standing, engaging the core for stability and control.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0002.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and your arms extended straight down by your sides.","Keeping your back straight and your core engaged, slowly bend your torso to one side, lowering your hand towards your knee.","Pause for a moment at the bottom, then slowly return to the starting position.","Repeat on the other side.","Continue alternating sides for the desired number of repetitions."]},{"id":"20","name":"balance board","body_part":"upper legs","target":"quads","secondary_muscles":["calves","hamstrings","glutes"],"equipment":"body weight","difficulty":"intermediate","description":"The balance board exercise involves standing on a balance board with one foot, engaging the core and lower body muscles to maintain stability and balance. This exercise primarily targets the quads, while also engaging the calves, hamstrings, and glutes as secondary muscles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0020.gif","youtube_id":null,"instructions":["Place the balance board on a flat surface.","Step onto the balance board with one foot, ensuring it is centered.","Slowly shift your weight onto the foot on the balance board, keeping your core engaged.","Maintain your balance and stability as you hold the position for a desired amount of time.","Repeat the exercise with the other foot."]},{"id":"200","name":"cable pushdown (with rope attachment)","body_part":"upper arms","target":"triceps","secondary_muscles":["forearms"],"equipment":"cable","difficulty":"beginner","description":"The cable pushdown (with rope attachment) is an isolation exercise targeting the triceps. It is performed using a cable machine with a rope attachment, focusing on extending the elbows to work the triceps while also engaging the forearms as secondary muscles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0200.gif","youtube_id":null,"instructions":["Attach a rope attachment to a high pulley on a cable machine.","Stand facing the machine with your feet shoulder-width apart and a slight bend in your knees.","Grasp the rope with an overhand grip, palms facing each other.","Keep your elbows close to your sides and your upper arms stationary throughout the exercise.","Exhale and push the rope downward by extending your elbows until your arms are fully extended.","Pause for a moment, then inhale and slowly return to the starting position by allowing your elbows to flex.","Repeat for the desired number of repetitions."]},{"id":"201","name":"cable pushdown","body_part":"upper arms","target":"triceps","secondary_muscles":["forearms"],"equipment":"cable","difficulty":"beginner","description":"The cable pushdown is an isolation exercise targeting the triceps using a cable machine. It is commonly performed to build strength and size in the triceps, with some engagement of the forearms. The movement is controlled and requires proper form to maximize effectiveness and minimize risk of injury.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0201.gif","youtube_id":null,"instructions":["Attach a straight bar to a high pulley cable machine.","Stand facing the machine with your feet shoulder-width apart and a slight bend in your knees.","Grasp the bar with an overhand grip, hands shoulder-width apart.","Keep your elbows close to your sides and your upper arms stationary.","Exhale and push the bar down until your elbows are fully extended.","Pause for a moment, then inhale and slowly return the bar to the starting position.","Repeat for the desired number of repetitions."]},{"id":"202","name":"cable rear delt row (stirrups)","body_part":"shoulders","target":"delts","secondary_muscles":["trapezius","rhomboids","biceps"],"equipment":"cable","difficulty":"intermediate","description":"The cable rear delt row (stirrups) is an isolation exercise targeting the rear deltoids, with additional activation of the trapezius, rhomboids, and biceps. It is performed using a cable machine with a stirrup handle, focusing on shoulder retraction and control.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0202.gif","youtube_id":null,"instructions":["Attach a stirrup handle to a low cable pulley and stand facing the machine.","Grasp the handle with your left hand and take a step back with your right foot, positioning your body at a slight angle.","Bend your knees slightly and hinge forward at the hips, keeping your back straight and your core engaged.","With your left arm extended and your palm facing down, pull the handle towards your chest by retracting your shoulder blade.","Pause for a moment at the top of the movement, squeezing your shoulder blade.","Slowly release the handle back to the starting position and repeat for the desired number of repetitions.","Switch sides and repeat the exercise with your right arm."]},{"id":"203","name":"cable rear delt row (with rope)","body_part":"shoulders","target":"delts","secondary_muscles":["trapezius","rhomboids","biceps"],"equipment":"cable","difficulty":"intermediate","description":"The cable rear delt row (with rope) is an isolation exercise targeting the rear deltoids, with secondary emphasis on the trapezius, rhomboids, and biceps. It uses a cable machine and rope attachment to provide constant tension throughout the movement, helping to develop shoulder strength and stability.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0203.gif","youtube_id":null,"instructions":["Attach a rope handle to a low pulley cable machine.","Stand facing the machine with your feet shoulder-width apart.","Grasp the rope handle with an overhand grip, palms facing each other.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Keep your elbows slightly bent and pull the rope towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top of the movement, then slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"204","name":"cable rear drive","body_part":"upper arms","target":"triceps","secondary_muscles":["shoulders","back"],"equipment":"cable","difficulty":"intermediate","description":"The cable rear drive is an isolation exercise targeting the triceps, performed using a cable machine. It also engages the shoulders and back as secondary muscles. The movement requires control and proper form to effectively target the triceps while minimizing strain on the shoulders and elbows.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0204.gif","youtube_id":null,"instructions":["Attach a handle to a low pulley cable machine and stand facing away from the machine.","Grasp the handle with an overhand grip and extend your arms straight out in front of you.","Keeping your elbows stationary, pull the handle back towards your body, squeezing your triceps at the end of the movement.","Slowly return the handle to the starting position and repeat for the desired number of repetitions."]},{"id":"205","name":"cable rear pulldown","body_part":"back","target":"lats","secondary_muscles":["biceps","rhomboids","rear deltoids"],"equipment":"cable","difficulty":"beginner","description":"The cable rear pulldown is a strength exercise targeting the latissimus dorsi muscles, performed using a cable machine. It also engages the biceps, rhomboids, and rear deltoids. The movement involves pulling a cable attachment down towards the chest while seated, focusing on squeezing the shoulder blades together.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0205.gif","youtube_id":null,"instructions":["Adjust the cable machine so that the pulley is at the highest position.","Sit facing the machine with your feet flat on the ground and your knees slightly bent.","Grasp the cable attachment with an overhand grip, hands slightly wider than shoulder-width apart.","Lean back slightly, keeping your back straight and your chest up.","Pull the cable attachment down towards your chest, squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, then slowly release the cable back up to the starting position.","Repeat for the desired number of repetitions."]},{"id":"206","name":"cable reverse curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"cable","difficulty":"beginner","description":"The cable reverse curl is an isolation exercise targeting the biceps and forearms using a cable machine. It emphasizes the brachialis and brachioradialis muscles due to the reverse grip.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0206.gif","youtube_id":null,"instructions":["Attach a straight bar to a low pulley cable machine.","Stand facing the machine with your feet shoulder-width apart and your knees slightly bent.","Grasp the bar with an underhand grip, hands shoulder-width apart.","Keep your elbows close to your sides and your upper arms stationary throughout the exercise.","Exhale and curl the bar up towards your shoulders, contracting your biceps.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the bar back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]},{"id":"207","name":"cable reverse-grip pushdown","body_part":"upper arms","target":"triceps","secondary_muscles":["forearms"],"equipment":"cable","difficulty":"beginner","description":"The cable reverse-grip pushdown is an isolation exercise targeting the triceps, performed using a cable machine with a straight bar and an underhand grip. It emphasizes triceps activation while also engaging the forearms.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0207.gif","youtube_id":null,"instructions":["Attach a straight bar to a high pulley cable machine.","Stand facing the machine with your feet shoulder-width apart.","Grasp the bar with an underhand grip, palms facing up, and your hands shoulder-width apart.","Keep your elbows close to your sides and your upper arms stationary throughout the exercise.","Using your triceps, push the bar down until your arms are fully extended and your triceps are contracted.","Pause for a moment, then slowly return the bar to the starting position.","Repeat for the desired number of repetitions."]},{"id":"208","name":"cable reverse-grip straight back seated high row","body_part":"back","target":"upper back","secondary_muscles":["biceps","forearms"],"equipment":"cable","difficulty":"intermediate","description":"The cable reverse-grip straight back seated high row targets the upper back using a cable machine. It involves pulling a cable attachment towards your torso with an underhand grip while keeping your back straight and engaging your back muscles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0208.gif","youtube_id":null,"instructions":["Sit on the seat facing the cable machine with your feet flat on the floor.","Grasp the cable attachment with an underhand grip, palms facing up, and your hands shoulder-width apart.","Keep your back straight and lean slightly forward from your hips.","Pull the cable towards your torso by retracting your shoulder blades and squeezing your back muscles.","Pause for a moment at the peak of the contraction, then slowly release the cable back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"209","name":"cable reverse preacher curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"cable","difficulty":"intermediate","description":"The cable reverse preacher curl is an isolation exercise targeting the biceps, performed using a cable machine and a preacher curl bench. It emphasizes the brachialis and forearm muscles due to the reverse (pronated) grip.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0209.gif","youtube_id":null,"instructions":["Adjust the cable machine so that the preacher curl pad is at chest height.","Sit on the preacher curl bench and place your upper arms on the pad, with your palms facing down and your elbows fully extended.","Grab the cable handles with an underhand grip, shoulder-width apart.","Keeping your upper arms stationary, exhale and curl the handles towards your shoulders, contracting your biceps.","Pause for a moment at the top of the movement, squeezing your biceps.","Inhale and slowly lower the handles back to the starting position, fully extending your elbows.","Repeat for the desired number of repetitions."]},{"id":"210","name":"cable reverse wrist curl","body_part":"lower arms","target":"forearms","secondary_muscles":["forearms","wrists"],"equipment":"cable","difficulty":"beginner","description":"The cable reverse wrist curl is an isolation exercise targeting the forearms, specifically the wrist extensors. It is performed using a cable machine and focuses on strengthening the muscles responsible for wrist extension.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0210.gif","youtube_id":null,"instructions":["Attach a cable to a low pulley and sit on a bench facing the cable machine.","Grasp the cable handle with an overhand grip, palms facing down.","Rest your forearms on your thighs, with your wrists hanging off the edge.","Keeping your forearms stationary, exhale and curl your wrists upward as far as possible.","Pause for a moment at the top, then inhale and slowly lower your wrists back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"211","name":"cable russian twists (on stability ball)","body_part":"waist","target":"abs","secondary_muscles":["obliques","lower back"],"equipment":"cable","difficulty":"advanced","description":"Cable Russian Twists (on stability ball) are a core exercise that targets the abs, obliques, and lower back. The use of a stability ball increases the balance and coordination required, while the cable adds resistance for strength development.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0211.gif","youtube_id":null,"instructions":["Sit on a stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Hold the cable handle with both hands and extend your arms straight out in front of you.","Lean back slightly while keeping your back straight and your core engaged.","Twist your torso to the right, bringing the cable handle towards your right hip.","Pause for a moment, then twist your torso to the left, bringing the cable handle towards your left hip.","Continue alternating twists for the desired number of repetitions."]},{"id":"212","name":"cable seated crunch","body_part":"waist","target":"abs","secondary_muscles":["obliques"],"equipment":"cable","difficulty":"intermediate","description":"The cable seated crunch is an abdominal exercise performed on a cable machine. It targets the abs and also works the obliques as secondary muscles. The movement involves curling the upper body forward against resistance, focusing on contracting the core.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0212.gif","youtube_id":null,"instructions":["Sit on a cable machine with your feet flat on the ground and your knees bent.","Hold the cable handle with both hands and position it behind your head.","Engage your abs and slowly curl your upper body forward, bringing your chest towards your knees.","Pause for a moment at the top, then slowly return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"213","name":"cable seated high row (v-bar)","body_part":"back","target":"lats","secondary_muscles":["biceps","rhomboids","rear deltoids"],"equipment":"cable","difficulty":"beginner","description":"The cable seated high row (v-bar) is a compound exercise targeting the latissimus dorsi, performed on a cable machine using a v-bar attachment. It also engages the biceps, rhomboids, and rear deltoids, making it effective for developing upper back strength and muscle definition.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0213.gif","youtube_id":null,"instructions":["Sit on the cable machine with your feet flat on the floor and your knees slightly bent.","Grasp the v-bar attachment with an overhand grip, palms facing each other, and your hands shoulder-width apart.","Keep your back straight and lean slightly forward from the hips.","Pull the v-bar towards your torso by retracting your shoulder blades and squeezing your back muscles.","Pause for a moment at the peak of the contraction, then slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"2133","name":"farmers walk","body_part":"upper legs","target":"quads","secondary_muscles":["calves","forearms","core"],"equipment":"dumbbell","difficulty":"beginner","description":"The farmer's walk is a functional strength exercise where you walk while holding a dumbbell in each hand, engaging the quads, calves, forearms, and core. It improves grip strength, core stability, and overall conditioning.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2133.gif","youtube_id":null,"instructions":["Stand up straight with a dumbbell in each hand, palms facing your sides.","Keep your back straight and your shoulders back.","Take small, controlled steps forward, maintaining an upright posture.","Continue walking for the desired distance or time.","To finish, stop walking and carefully lower the dumbbells to your sides."]},{"id":"2135","name":"weighted front plank","body_part":"waist","target":"abs","secondary_muscles":["shoulders","lower back"],"equipment":"weighted","difficulty":"intermediate","description":"The weighted front plank is a core stability exercise that increases the challenge of the traditional plank by adding external weight, requiring greater strength and endurance from the abdominal muscles, shoulders, and lower back.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2135.gif","youtube_id":null,"instructions":["Start by lying face down on the floor.","Place your forearms on the ground, with your elbows directly under your shoulders.","Extend your legs straight out behind you, with your toes on the ground.","Engage your core and lift your body off the ground, balancing on your forearms and toes.","Keep your body in a straight line from your head to your heels.","Hold this position for the desired amount of time.","Lower your body back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"2136","name":"dumbbell cuban press v. 2","body_part":"shoulders","target":"delts","secondary_muscles":["triceps","upper back"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell Cuban press v. 2 is a shoulder exercise that targets the deltoids while also engaging the triceps and upper back. It involves a combination of pressing and rotational movement, making it effective for building strength and stability in the shoulder joint.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2136.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder height with your palms facing down.","Keeping your core engaged and your back straight, press the dumbbells straight up overhead until your arms are fully extended.","Rotate your wrists so that your palms are facing forward.","Lower the dumbbells back down to shoulder height, rotating your wrists back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"2137","name":"dumbbell arnold press","body_part":"shoulders","target":"delts","secondary_muscles":["triceps","upper chest"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell Arnold press is a shoulder exercise that targets the deltoids while also engaging the triceps and upper chest. It involves a rotational movement as you press the dumbbells overhead, increasing the range of motion and muscle activation compared to a standard shoulder press.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2137.gif","youtube_id":null,"instructions":["Sit on a bench with back support and hold a dumbbell in each hand at shoulder level, palms facing your body and elbows bent.","Press the dumbbells upward until your arms are fully extended and your palms are facing forward.","Rotate your wrists as you lift, so that your palms are facing forward at the top of the movement.","Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"2138","name":"stationary bike run v. 3","body_part":"cardio","target":"cardiovascular system","secondary_muscles":["quadriceps","hamstrings","calves"],"equipment":"stationary bike","difficulty":"beginner","description":"The stationary bike run v. 3 is a cardiovascular exercise performed on a stationary bike. It primarily targets the cardiovascular system and also engages the quadriceps, hamstrings, and calves. The exercise involves pedaling at a steady rhythm, adjusting resistance as needed, and maintaining proper posture throughout the workout.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2138.gif","youtube_id":null,"instructions":["Adjust the seat height and position to ensure proper alignment.","Place your feet on the pedals and secure them with the straps if available.","Start pedaling at a comfortable pace.","Maintain a steady rhythm and increase the resistance as desired.","Engage your core muscles to maintain stability and proper posture.","Continue pedaling for the desired duration of your workout.","Gradually decrease the resistance and slow down before coming to a complete stop.","Stretch your legs and cool down after the workout."]},{"id":"2139","name":"hands bike","body_part":"chest","target":"pectorals","secondary_muscles":["triceps","shoulders"],"equipment":"upper body ergometer","difficulty":"beginner","description":"The hands bike (upper body ergometer) is a cardiovascular exercise that targets the pectorals, triceps, and shoulders by requiring the user to pedal with their hands, simulating a cycling motion for the upper body.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2139.gif","youtube_id":null,"instructions":["Adjust the seat height and handlebar position to a comfortable level.","Sit on the ergometer with your back straight and feet on the pedals.","Grasp the handles with your hands and position your arms at a 90-degree angle.","Start pedaling with your hands, pushing and pulling the handles in a controlled motion.","Continue pedaling for the desired duration or number of repetitions."]},{"id":"214","name":"cable seated one arm alternate row","body_part":"back","target":"upper back","secondary_muscles":["biceps","forearms"],"equipment":"cable","difficulty":"intermediate","description":"The cable seated one arm alternate row is a strength exercise targeting the upper back, performed on a cable machine. It involves pulling a handle towards the body with one arm at a time, focusing on scapular retraction and controlled movement.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0214.gif","youtube_id":null,"instructions":["Sit on a bench facing a cable machine with your feet flat on the ground and knees slightly bent.","Grasp the handle with one hand and keep your arm fully extended in front of you.","Pull the handle towards your body, retracting your shoulder blade and keeping your elbow close to your side.","Pause for a moment at the top of the movement, squeezing your back muscles.","Slowly release the handle back to the starting position.","Repeat with the other arm.","Alternate between arms for the desired number of repetitions."]},{"id":"2140","name":"walk wave machine","body_part":"cardio","target":"cardiovascular system","secondary_muscles":["glutes","quads","hamstrings","calves","abductors","adductors"],"equipment":"elliptical machine","difficulty":"beginner","description":"Walk on a wave/lateral elliptical-style machine, moving the pedals in a smooth side-to-side path while maintaining an upright posture. Use steady cadence to elevate heart rate with low impact on the joints.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2140.gif","youtube_id":null,"instructions":["Start with a low resistance and step amplitude on the console.","Step onto the pedals with feet centered and hip-width; grasp the handles lightly and stand tall with core braced.","Begin the lateral pedaling motion smoothly, driving through the whole foot.","Keep knees tracking over toes and hips square; avoid letting knees cave inward.","Maintain a steady cadence and relaxed shoulders; do not lean on the console.","Breathe rhythmically and increase resistance or cadence to reach the desired intensity.","Finish by gradually reducing resistance and cadence for 2–3 minutes to cool down.","Stop the pedals completely before stepping off safely."]},{"id":"2141","name":"walk elliptical cross trainer","body_part":"cardio","target":"cardiovascular system","secondary_muscles":["quadriceps","hamstrings","glutes","calves"],"equipment":"elliptical machine","difficulty":"beginner","description":"The walk elliptical cross trainer is a cardiovascular exercise performed on an elliptical machine. It simulates a walking or running motion with low impact on the joints, making it suitable for a wide range of fitness levels. The exercise targets the cardiovascular system while also engaging the quadriceps, hamstrings, glutes, and calves.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2141.gif","youtube_id":null,"instructions":["Adjust the resistance level and incline of the elliptical machine to your desired settings.","Step onto the pedals of the machine and grip the handles lightly.","Begin by pushing down with your feet and pulling the handles towards your body.","Continue this motion, alternating between pushing and pulling, to simulate a walking or running motion.","Maintain a steady pace and keep your core engaged throughout the exercise.","Continue for the desired duration of your cardio workout.","Gradually decrease the intensity and speed of the machine before stepping off."]},{"id":"2142","name":"ski ergometer","body_part":"upper arms","target":"triceps","secondary_muscles":["shoulders","forearms"],"equipment":"skierg machine","difficulty":"beginner","description":"The ski ergometer exercise targets the triceps and simulates the motion of cross-country skiing using a skierg machine. It also engages the shoulders and forearms, providing a cardiovascular and strength workout.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2142.gif","youtube_id":null,"instructions":["Adjust the seat height and footrests to a comfortable position.","Grasp the handles with an overhand grip, palms facing down.","Sit up straight with your feet flat on the footrests.","Extend your arms straight out in front of you, keeping your elbows slightly bent.","Engage your triceps and push the handles down towards your thighs.","Pause for a moment at the bottom, then slowly return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"2143","name":"dumbbell standing around world","body_part":"shoulders","target":"delts","secondary_muscles":["triceps","forearms"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell standing around world is a shoulder exercise that involves moving dumbbells in a circular motion around the body, targeting the deltoids and engaging the triceps and forearms.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2143.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and hold a dumbbell in each hand.","Extend your arms straight out to the sides at shoulder height, palms facing down.","Keeping your arms straight, slowly rotate your arms in a circular motion, bringing the dumbbells in front of your body and then overhead.","Continue the circular motion, bringing the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"2144","name":"cable seated chest press","body_part":"chest","target":"pectorals","secondary_muscles":["shoulders","triceps"],"equipment":"cable","difficulty":"beginner","description":"The cable seated chest press is a resistance exercise targeting the pectoral muscles using a cable machine. It also engages the shoulders and triceps as secondary muscles. The movement is performed while seated, pressing the cable handles forward and then returning to the starting position.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2144.gif","youtube_id":null,"instructions":["Adjust the seat height and cable handles to a comfortable position.","Sit on the bench with your back straight and feet flat on the floor.","Grasp the cable handles with an overhand grip at shoulder height.","Push the handles forward and away from your body, extending your arms fully.","Pause for a moment, then slowly bring the handles back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"215","name":"cable seated rear lateral raise","body_part":"shoulders","target":"delts","secondary_muscles":["traps","rhomboids"],"equipment":"cable","difficulty":"intermediate","description":"The cable seated rear lateral raise is an isolation exercise targeting the rear deltoids, with secondary emphasis on the traps and rhomboids. It is performed seated at a cable machine, raising the arms laterally to shoulder height.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0215.gif","youtube_id":null,"instructions":["Sit on a bench facing the cable machine with your feet flat on the ground.","Grasp the cable handles with an overhand grip and extend your arms straight in front of you.","Keeping your arms straight, slowly raise them out to the sides until they are parallel to the floor.","Pause for a moment at the top, then slowly lower your arms back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"216","name":"cable seated shoulder internal rotation","body_part":"shoulders","target":"delts","secondary_muscles":["rotator cuff","triceps"],"equipment":"cable","difficulty":"beginner","description":"The cable seated shoulder internal rotation is an isolation exercise targeting the deltoids and rotator cuff muscles. It is performed seated, using a cable machine to provide resistance as you internally rotate your shoulder.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0216.gif","youtube_id":null,"instructions":["Sit on a bench or chair facing the cable machine with your feet flat on the ground.","Hold the cable handle with your arm extended straight out in front of you, parallel to the ground.","Keep your elbow slightly bent and your shoulder blades pulled back and down.","Slowly rotate your arm inward, bringing the cable handle towards the center of your body.","Pause for a moment at the end of the movement, then slowly return to the starting position.","Repeat for the desired number of repetitions, then switch arms."]},{"id":"218","name":"cable seated wide-grip row","body_part":"back","target":"upper back","secondary_muscles":["biceps","forearms"],"equipment":"cable","difficulty":"beginner","description":"The cable seated wide-grip row is a strength exercise targeting the upper back. It involves pulling a cable handle with a wide grip while seated, focusing on squeezing the shoulder blades together to engage the upper back muscles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0218.gif","youtube_id":null,"instructions":["Sit on the cable row machine with your feet flat on the footrests and your knees slightly bent.","Grasp the handle with a wide overhand grip, palms facing down.","Keep your back straight and lean slightly forward from the hips.","Pull the handle towards your lower chest, squeezing your shoulder blades together.","Pause for a moment at the peak of the contraction.","Slowly release the handle back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]},{"id":"2186","name":"ez barbell decline triceps extension","body_part":"upper arms","target":"triceps","secondary_muscles":["shoulders"],"equipment":"ez barbell","difficulty":"intermediate","description":"The EZ barbell decline triceps extension is an isolation exercise targeting the triceps, performed on a decline bench using an EZ bar. It requires good control and technique to avoid injury, especially to the elbows and shoulders.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2186.gif","youtube_id":null,"instructions":["Lie on a decline bench with your head lower than your feet and your feet secured.","Hold the ez barbell with an overhand grip, hands shoulder-width apart.","Extend your arms fully, keeping your elbows close to your head.","Lower the barbell slowly towards your forehead, bending your elbows.","Pause for a moment, then extend your arms back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"2187","name":"barbell reverse close-grip bench press","body_part":"upper arms","target":"triceps","secondary_muscles":["chest","shoulders"],"equipment":"barbell","difficulty":"intermediate","description":"The barbell reverse close-grip bench press is a compound exercise that targets the triceps, with secondary emphasis on the chest and shoulders. It involves lying on a bench and pressing a barbell with a reverse (underhand) grip, which shifts more focus to the triceps compared to a traditional bench press.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2187.gif","youtube_id":null,"instructions":["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Grasp the barbell with a reverse grip, hands shoulder-width apart.","Lift the barbell off the rack and hold it directly above your chest with your arms fully extended.","Slowly lower the barbell down towards your chest, keeping your elbows close to your body.","Pause for a moment when the barbell is just above your chest.","Push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]},{"id":"2188","name":"dumbbell seated triceps extension","body_part":"upper arms","target":"triceps","secondary_muscles":["shoulders"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell seated triceps extension is an isolation exercise that targets the triceps, performed while seated and using a dumbbell held with both hands overhead.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2188.gif","youtube_id":null,"instructions":["Sit on a bench with your back straight and feet flat on the ground.","Hold a dumbbell with both hands and extend your arms straight up overhead.","Bend your elbows and lower the dumbbell behind your head, keeping your upper arms close to your ears.","Pause for a moment, then straighten your arms and return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"2189","name":"dumbbells seated triceps extension","body_part":"upper arms","target":"triceps","secondary_muscles":["shoulders"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbells seated triceps extension is an isolation exercise targeting the triceps, performed while seated with a dumbbell held overhead. It is effective for building triceps strength and size.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2189.gif","youtube_id":null,"instructions":["Sit on a bench with your back straight and feet flat on the ground.","Hold a dumbbell in both hands with an overhand grip, and raise it above your head.","Bend your elbows and lower the dumbbell behind your head, keeping your upper arms close to your ears.","Extend your arms and raise the dumbbell back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"219","name":"cable shoulder press","body_part":"shoulders","target":"delts","secondary_muscles":["triceps","upper back"],"equipment":"cable","difficulty":"intermediate","description":"The cable shoulder press is a compound exercise targeting the deltoid muscles using a cable machine. It involves pressing handles overhead from shoulder height, engaging the shoulders, triceps, and upper back.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0219.gif","youtube_id":null,"instructions":["Adjust the cable machine so that the handles are at shoulder height.","Stand facing away from the machine with your feet shoulder-width apart.","Grasp the handles with an overhand grip and bring them up to shoulder level, with your elbows bent and pointing outwards.","Press the handles upwards until your arms are fully extended overhead.","Pause for a moment at the top, then slowly lower the handles back down to shoulder level.","Repeat for the desired number of repetitions."]},{"id":"22","name":"barbell pullover to press","body_part":"back","target":"lats","secondary_muscles":["triceps","chest","shoulders"],"equipment":"barbell","difficulty":"intermediate","description":"The barbell pullover to press is a compound exercise that targets the lats and also works the triceps, chest, and shoulders. It involves lowering a barbell behind your head while lying on a bench, then pressing it back up over your chest.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0022.gif","youtube_id":null,"instructions":["Lie flat on a bench with your head at one end and your feet on the ground.","Hold the barbell with a pronated grip (palms facing away from you) and extend your arms straight above your chest.","Keeping your arms straight, lower the barbell behind your head in an arc-like motion until you feel a stretch in your lats.","Pause for a moment, then reverse the motion and press the barbell back to the starting position above your chest.","Repeat for the desired number of repetitions."]},{"id":"220","name":"cable shrug","body_part":"back","target":"traps","secondary_muscles":["shoulders"],"equipment":"cable","difficulty":"beginner","description":"The cable shrug is an isolation exercise targeting the trapezius muscles, performed using a cable machine. It involves shrugging the shoulders upward while keeping the arms straight, focusing on contracting the traps.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0220.gif","youtube_id":null,"instructions":["Stand facing the cable machine with your feet shoulder-width apart.","Grasp the cable handles with an overhand grip and let your arms hang down in front of you.","Keeping your arms straight, shrug your shoulders up towards your ears.","Hold the contraction for a moment, then slowly lower your shoulders back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"2202","name":"roller hip stretch","body_part":"upper legs","target":"glutes","secondary_muscles":["hamstrings","quadriceps"],"equipment":"roller","difficulty":"beginner","description":"The roller hip stretch is a flexibility and mobility exercise that targets the glutes and also stretches the hamstrings and quadriceps. It uses a foam roller to help release tension and improve range of motion in the hip area.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2202.gif","youtube_id":null,"instructions":["Start by sitting on the ground with your legs extended in front of you.","Place the roller under your glutes, just above your knees.","Lean back and place your hands on the ground behind you for support.","Engage your glutes and slowly roll the roller forward, bending your knees and bringing them towards your chest.","Pause for a moment at the end of the movement, feeling a stretch in your glutes.","Slowly roll the roller back to the starting position, extending your legs.","Repeat for the desired number of repetitions."]},{"id":"2203","name":"roller seated shoulder flexor depresor retractor","body_part":"chest","target":"pectorals","secondary_muscles":["deltoids","triceps"],"equipment":"roller","difficulty":"beginner","description":"The roller seated shoulder flexor depresor retractor is an exercise that targets the pectorals while also engaging the deltoids and triceps. It involves sitting with legs extended, holding a roller, and performing a controlled rolling motion to extend and retract the arms.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2203.gif","youtube_id":null,"instructions":["Sit on a flat surface with your legs extended in front of you.","Hold the roller with both hands, palms facing down, and place it on your thighs.","Lean forward slightly and roll the roller away from your body, extending your arms straight in front of you.","Pause for a moment, then slowly roll the roller back towards your body, bending your arms and bringing the roller back to your thighs.","Repeat for the desired number of repetitions."]},{"id":"2204","name":"roller body saw","body_part":"waist","target":"abs","secondary_muscles":["shoulders","triceps","core"],"equipment":"roller","difficulty":"advanced","description":"The roller body saw is a challenging core exercise that involves using a roller to extend and retract your body while maintaining a plank position. This movement targets the abs and also engages the shoulders, triceps, and overall core stability.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2204.gif","youtube_id":null,"instructions":["Start in a plank position with your forearms on the roller and your body in a straight line.","Engage your core and slowly roll the roller forward, extending your body as far as you can while maintaining control.","Pause for a moment at the furthest point, then slowly roll the roller back towards your starting position.","Repeat for the desired number of repetitions."]},{"id":"2205","name":"roller hip lat stretch","body_part":"upper legs","target":"glutes","secondary_muscles":["hamstrings","quadriceps"],"equipment":"roller","difficulty":"beginner","description":"The roller hip lat stretch is a flexibility exercise that targets the glutes and also stretches the hamstrings and quadriceps. It uses a roller for support and to enhance the stretch, making it accessible for most people with basic mobility and balance.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2205.gif","youtube_id":null,"instructions":["Start by kneeling on the ground with the roller positioned under your hips.","Place your hands on the roller for support.","Slowly roll the roller forward, extending your hips and stretching your glutes.","Hold the stretch for a few seconds, then roll back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"2206","name":"roller reverse crunch","body_part":"waist","target":"abs","secondary_muscles":["hip flexors"],"equipment":"roller","difficulty":"intermediate","description":"The roller reverse crunch is an abdominal exercise that uses a roller held between the feet to increase resistance and challenge core stability. It targets the abs and also engages the hip flexors.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2206.gif","youtube_id":null,"instructions":["Lie flat on your back with your arms extended straight above your head and your legs straight out in front of you.","Place the roller between your feet and grip it with your toes.","Engaging your abs, lift your legs off the ground and curl your knees towards your chest, rolling the roller towards your body.","Pause for a moment at the top, then slowly lower your legs back down to the starting position, rolling the roller away from your body.","Repeat for the desired number of repetitions."]},{"id":"2207","name":"roller side lat stretch","body_part":"back","target":"lats","secondary_muscles":["shoulders","triceps"],"equipment":"roller","difficulty":"beginner","description":"The roller side lat stretch is a flexibility exercise targeting the latissimus dorsi, using a roller to assist in deepening the stretch. It also engages the shoulders and triceps as secondary muscles. This movement is performed by hinging at the hips and rolling the roller forward to stretch the lats.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2207.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and hold the roller with both hands in front of your body.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Extend your arms forward and roll the roller down towards your feet, feeling a stretch in your lats.","Hold the stretch for a few seconds, then slowly roll the roller back up to the starting position.","Repeat for the desired number of repetitions."]},{"id":"2208","name":"roller back stretch","body_part":"back","target":"spine","secondary_muscles":["hamstrings","glutes"],"equipment":"roller","difficulty":"beginner","description":"The roller back stretch is a mobility exercise that uses a foam roller to gently mobilize and stretch the spine, with secondary benefits for the hamstrings and glutes. It is performed by rolling the back over a foam roller from the lower to upper back.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2208.gif","youtube_id":null,"instructions":["Start by sitting on the ground with your legs extended in front of you.","Place the roller perpendicular to your body, just below your glutes.","Slowly roll your body backwards, allowing the roller to move up your back.","Continue rolling until the roller reaches your upper back.","Pause for a moment, then slowly roll back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"2209","name":"roller seated single leg shoulder flexor depresor retractor","body_part":"chest","target":"pectorals","secondary_muscles":["deltoids","triceps"],"equipment":"roller","difficulty":"beginner","description":"This exercise targets the pectoral muscles while also engaging the deltoids and triceps. It involves sitting with legs extended, holding a roller, and performing a controlled shoulder flexion movement.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2209.gif","youtube_id":null,"instructions":["Sit on a flat surface with your legs extended in front of you.","Hold the roller with both hands, palms facing down, and place it on your thighs.","Lean back slightly and engage your core muscles.","Raise the roller up to shoulder level, keeping your arms straight.","Slowly lower the roller back down to your thighs.","Repeat for the desired number of repetitions."]},{"id":"221","name":"cable side bend crunch (bosu ball)","body_part":"waist","target":"abs","secondary_muscles":["obliques"],"equipment":"cable","difficulty":"advanced","description":"The cable side bend crunch (bosu ball) targets the abdominal muscles, particularly the obliques, using a cable machine while standing on a BOSU ball to add instability and challenge balance.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0221.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, holding a cable handle in one hand.","Place the other hand on your hip.","Engage your core and slowly bend sideways towards the hand holding the cable, keeping your back straight.","Pause for a moment at the bottom of the movement, then slowly return to the starting position.","Repeat for the desired number of repetitions, then switch sides."]},{"id":"222","name":"cable side bend","body_part":"waist","target":"abs","secondary_muscles":["obliques"],"equipment":"cable","difficulty":"beginner","description":"The cable side bend is an isolation exercise targeting the oblique muscles and the abs. It involves standing upright and bending sideways at the waist against resistance provided by a cable machine.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0222.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and grasp the cable handle with one hand.","Keep your back straight and your core engaged.","Slowly bend sideways at the waist, lowering the cable handle towards your knee.","Pause for a moment, then return to the starting position.","Repeat on the other side.","Alternate sides for the desired number of repetitions."]},{"id":"223","name":"cable side crunch","body_part":"waist","target":"abs","secondary_muscles":["obliques"],"equipment":"cable","difficulty":"intermediate","description":"The cable side crunch is an isolation exercise targeting the abdominal muscles, particularly the obliques, using a cable machine for resistance. It involves bending sideways at the waist to engage the core.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0223.gif","youtube_id":null,"instructions":["Attach a cable handle to a low pulley and stand sideways to the machine.","Grasp the handle with the hand furthest from the machine and place your other hand on your hip.","Keep your feet shoulder-width apart and your knees slightly bent.","With your abs engaged, bend sideways at the waist, bringing your elbow down towards your hip.","Pause for a moment at the bottom, then slowly return to the starting position.","Repeat for the desired number of repetitions, then switch sides."]},{"id":"224","name":"cable standing back wrist curl","body_part":"lower arms","target":"forearms","secondary_muscles":["biceps","brachialis"],"equipment":"cable","difficulty":"beginner","description":"The cable standing back wrist curl is an isolation exercise targeting the forearms. It is performed using a cable machine and focuses on strengthening the wrist extensors.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0224.gif","youtube_id":null,"instructions":["Stand facing a cable machine with your feet shoulder-width apart.","Hold the cable handle with an overhand grip, palms facing down.","Keep your arms straight and your elbows close to your sides.","Slowly curl your wrists upward, bringing the cable handle towards your body.","Pause for a moment at the top, then slowly lower the cable handle back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"225","name":"cable standing cross-over high reverse fly","body_part":"shoulders","target":"delts","secondary_muscles":["trapezius","rhomboids","rear deltoids"],"equipment":"cable","difficulty":"intermediate","description":"The cable standing cross-over high reverse fly is a shoulder exercise that targets the deltoids, with secondary emphasis on the trapezius, rhomboids, and rear deltoids. It is performed using a cable machine and requires coordination, balance, and control to execute the movement properly.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0225.gif","youtube_id":null,"instructions":["Attach a D-handle to each side of a cable machine at shoulder height.","Stand in the middle of the cable machine with your feet shoulder-width apart.","Grasp the handles with an overhand grip and extend your arms out to the sides, palms facing forward.","Keep a slight bend in your elbows and maintain a straight back throughout the exercise.","Engage your shoulder muscles and squeeze your shoulder blades together as you pull the handles towards the front of your body.","Pause for a moment at the peak of the movement, then slowly return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"226","name":"cable standing crunch","body_part":"waist","target":"abs","secondary_muscles":["obliques"],"equipment":"cable","difficulty":"intermediate","description":"The cable standing crunch is an abdominal exercise performed using a cable machine. It targets the abs and also engages the obliques. The movement involves crunching the torso down against resistance, which increases core strength and stability.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0226.gif","youtube_id":null,"instructions":["Attach a cable handle to a high pulley and stand facing away from the machine.","Hold the handle with both hands and place it behind your head, keeping your elbows bent.","Stand with your feet shoulder-width apart and your knees slightly bent.","Keeping your abs engaged, exhale and crunch your torso down towards your knees, bringing your elbows towards your thighs.","Pause for a moment at the bottom of the movement, then slowly return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"227","name":"cable standing fly","body_part":"chest","target":"pectorals","secondary_muscles":["deltoids","triceps"],"equipment":"cable","difficulty":"intermediate","description":"The cable standing fly is a chest isolation exercise performed using a cable machine. It targets the pectoral muscles and also engages the deltoids and triceps. The movement requires good form, balance, and control to execute safely and effectively.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0227.gif","youtube_id":null,"instructions":["Attach the handles to the cables at chest height.","Stand with your feet shoulder-width apart, facing away from the cable machine.","Grasp the handles with an overhand grip, palms facing forward.","Step forward slightly to create tension in the cables.","Keep your core engaged and your back straight throughout the exercise.","With a slight bend in your elbows, slowly bring your arms forward and together in front of your chest.","Squeeze your chest muscles at the peak of the movement.","Slowly reverse the movement, returning your arms to the starting position.","Repeat for the desired number of repetitions."]},{"id":"2271","name":"left hook (boxing)","body_part":"shoulders","target":"delts","secondary_muscles":["biceps","triceps","forearms"],"equipment":"body weight","difficulty":"intermediate","description":"The left hook in boxing is a bodyweight exercise that targets the deltoids and involves a rotational punching motion. It also engages the biceps, triceps, and forearms, and requires coordination, balance, and core engagement.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2271.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and your knees slightly bent.","Keep your left hand up to protect your face and your right hand by your chin.","Rotate your hips and pivot on your left foot as you extend your left arm forward in a punching motion.","Twist your torso and engage your core muscles to generate power in the punch.","Snap your arm back to the starting position and repeat for the desired number of repetitions."]},{"id":"2272","name":"boxing jab","body_part":"shoulders","target":"delts","secondary_muscles":["triceps","serratus anterior","pectorals","abs","forearms"],"equipment":"body weight","difficulty":"beginner","description":"From a boxing stance, throw a straight lead-hand punch, extending the arm while rotating the lead shoulder and hip, then quickly retract to guard. Performed rhythmically, it emphasizes shoulder endurance, speed, and crisp mechanics.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2272.gif","youtube_id":null,"instructions":["Stand in a boxing stance with lead foot forward, knees soft, chin tucked, hands up at cheek level.","Brace your core and keep the rear hand tight to your face throughout.","Initiate the jab by lightly pushing from the rear foot as you rotate the lead hip and shoulder toward the target.","Extend the lead arm straight ahead, rotating the fist to palm-down near full extension; keep the wrist neutral and avoid locking the elbow.","Let the shoulder protract for reach without shrugging; exhale sharply on the punch.","Snap the hand straight back along the same path to your guard as the hips and shoulders re-center.","Maintain balance and repeat with smooth, quick reps while keeping the rear hand up."]},{"id":"2273","name":"boxing right cross","body_part":"cardio","target":"cardiovascular system","secondary_muscles":["delts","pectorals","triceps","abs","serratus anterior","glutes"],"equipment":"body weight","difficulty":"beginner","description":"From a boxing stance, throw a straight right punch by rotating the hips and shoulders while extending the right arm, then snap it back to guard. Perform rhythmically for conditioning and technique.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2273.gif","youtube_id":null,"instructions":["Stand in an orthodox stance: left foot forward, right foot back shoulder-width, knees soft, hands at cheek level.","Brace your core, tuck your chin, and keep the left hand guarding.","Initiate from the ground: push off the ball of the right foot and rotate the right hip and shoulder forward.","Drive the right fist straight from your chin to the target, turning the palm down at extension with a neutral wrist.","Exhale sharply on the punch and keep a slight bend—do not hyperextend the elbow.","Let the rear heel lift as you pivot; keep the lead foot planted and weight shifting slightly forward.","Retract the right hand immediately along the same path back to your guard.","Reset your stance and repeat smoothly for the desired reps or time."]},{"id":"2274","name":"boxing right uppercut","body_part":"cardio","target":"cardiovascular system","secondary_muscles":["delts","triceps","abs","serratus anterior","glutes","calves"],"equipment":"body weight","difficulty":"beginner","description":"From a boxing stance, throw a right uppercut by driving through the right foot and rotating the hips and torso while bringing the right fist up a tight arc. Return to guard and repeat rhythmically for conditioning.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2274.gif","youtube_id":null,"instructions":["Stand in orthodox stance: left foot forward, right foot back, knees soft, hands up at chin, elbows in.","Settle a bit into the right hip with the right heel light and core braced.","Drive from the floor—push through the ball of the right foot and rotate the hips and torso to the left.","As you rotate, bring the right fist up close to your body in a vertical arc, palm facing you, elbow ~90°, exhaling on the punch.","Stop at chin-to-nose height without overreaching; keep the left hand guarding your face.","Retract the right hand along the same path, reset your hips, and repeat smoothly for reps or time."]},{"id":"2275","name":"boxing left uppercut","body_part":"waist","target":"abs","secondary_muscles":["delts","triceps","serratus anterior","glutes","quads"],"equipment":"body weight","difficulty":"beginner","description":"Stand in a boxing stance and throw a left uppercut by driving from the legs and rotating the hips and torso, lifting the fist on a tight vertical path and returning to guard. Emphasize core rotation, wrist alignment, and quick recoil.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2275.gif","youtube_id":null,"instructions":["Adopt a boxing stance with the left foot forward (orthodox), knees soft, chin tucked, hands at cheek level and elbows in.","Dip slightly by bending the knees and loading the lead (left) hip without collapsing your torso.","Drive through the floor with the left foot, rotate the hips and torso, and let the left shoulder rise as you start the punch.","Keep the left elbow close to your body and send the fist up in front of your torso, palm facing you or slightly inward; do not scoop wide.","Exhale sharply at impact, keeping the wrist straight and forearm vertical under the knuckles.","Stop the punch just in front of your body line, then retract along the same path and return to guard.","Reset your stance without over-rotating or leaning forward, then repeat for reps or time."]},{"id":"228","name":"cable standing hip extension","body_part":"upper legs","target":"glutes","secondary_muscles":["hamstrings","quadriceps"],"equipment":"cable","difficulty":"intermediate","description":"The cable standing hip extension targets the glutes by extending the leg backward against resistance. It also engages the hamstrings and quadriceps as secondary muscles. This exercise is performed using a cable machine and requires balance and core stability.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0228.gif","youtube_id":null,"instructions":["Attach a cable to a low pulley and stand facing away from the machine.","Place the cable around your ankle and stand with your feet shoulder-width apart.","Keep your core engaged and your back straight throughout the exercise.","Slowly extend your leg straight back, squeezing your glutes at the top of the movement.","Pause for a moment, then return to the starting position.","Repeat for the desired number of repetitions.","Switch sides and repeat with the other leg."]},{"id":"2282","name":"lever neck extension (plate loaded)","body_part":"neck","target":"levator scapulae","secondary_muscles":["traps","upper back"],"equipment":"leverage machine","difficulty":"intermediate","description":"Sit on a plate‑loaded neck extension machine with the head pad against the back of your skull and chest secured. Extend the neck to lift the lever, then slowly return to the start under control.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2282.gif","youtube_id":null,"instructions":["Adjust seat so the head pad contacts the back of your skull (not the neck) and load light plates.","Sit upright with chest against the pad, feet flat, and spine neutral; grip the handles for stability.","Begin with a slight chin tuck and eyes forward; avoid slouching or arching the low back.","Exhale and extend the neck by pressing the head back into the pad until the head aligns with the torso—do not hyperextend.","Pause briefly while keeping shoulders relaxed and down.","Inhale and control the return by flexing the neck, bringing the chin slightly toward the chest within a comfortable range.","Move slowly and smoothly; stop if you feel neck pain, tingling, or dizziness."]},{"id":"2283","name":"lever neck left side flexion (plate loaded)","body_part":"neck","target":"levator scapulae","secondary_muscles":["sternocleidomastoid","traps","scalenes"],"equipment":"leverage machine","difficulty":"intermediate","description":"Sit in a plate‑loaded neck flexion machine with the head pad positioned on the left side of your skull above the ear. Brace your torso and laterally flex the neck to bring your left ear toward your left shoulder, then return under control.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2283.gif","youtube_id":null,"instructions":["Set the seat so the machine’s pivot is level with the base of your neck and load an appropriate plate.","Position the left head pad on the bony side of your skull above the ear (not on the jaw or ear).","Sit tall with your back against the pad, feet flat, and grip the handles to stabilize your torso.","Start with your head neutral, chin level, shoulders relaxed—do not shrug.","Exhale as you slowly flex your neck to the left, bringing your ear toward your shoulder without rotating the head.","Pause briefly at a comfortable end range without pinching or pain.","Inhale as you return to neutral under control, keeping the motion slow and the neck aligned."]},{"id":"2284","name":"lever neck right side flexion (plate loaded)","body_part":"neck","target":"levator scapulae","secondary_muscles":["traps","upper back"],"equipment":"leverage machine","difficulty":"intermediate","description":"Sit in a lever neck machine with the right side of your head against the pad and plates loaded to an appropriate weight. Keep your torso stable and laterally flex your neck to the right against the pad, then return under control.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2284.gif","youtube_id":null,"instructions":["Adjust seat and pad so the head pad contacts the right side of your skull just above the ear with your neck in neutral.","Sit tall with feet flat; grip the machine handles to stabilize your torso and keep shoulders down.","Set chin level and eyes forward; avoid rotating the head.","Brace lightly and press the right side of your head into the pad, bringing your ear toward your shoulder.","Move through a comfortable, pain‑free range; do not shrug or twist.","Pause briefly at end range, then return slowly to neutral under control.","Maintain smooth breathing and consistent tension; complete all reps on the right, then train the left for balance."]},{"id":"2285","name":"lever pullover","body_part":"back","target":"lats","secondary_muscles":["triceps","shoulders"],"equipment":"leverage machine","difficulty":"beginner","description":"The lever pullover is a machine-based exercise targeting the latissimus dorsi (lats) and also engaging the triceps and shoulders. It is performed by sitting on a leverage machine, grasping the handles, and pulling them towards the chest in a controlled motion.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2285.gif","youtube_id":null,"instructions":["Adjust the seat and handles of the leverage machine to a comfortable position.","Sit on the machine with your back against the pad and grasp the handles with an overhand grip.","Keep your arms slightly bent and your core engaged.","Slowly pull the handles towards your chest, squeezing your lats.","Pause for a moment at the peak contraction, then slowly return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"2286","name":"lever hip extension v. 2","body_part":"upper legs","target":"glutes","secondary_muscles":["hamstrings"],"equipment":"leverage machine","difficulty":"beginner","description":"The lever hip extension v. 2 is a machine-based exercise that targets the glutes and also works the hamstrings. It involves extending the hips against resistance provided by a leverage machine, making it a controlled and isolated movement for the posterior chain.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2286.gif","youtube_id":null,"instructions":["Adjust the machine to fit your body and sit on it with your back against the backrest.","Place your feet on the footrests and grip the handles for stability.","Engage your glutes and hamstrings, then push against the footrests to extend your hips and raise your legs backward.","Pause for a moment at the top, then slowly lower your legs back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"2287","name":"lever alternate leg press","body_part":"upper legs","target":"quads","secondary_muscles":["hamstrings","glutes"],"equipment":"leverage machine","difficulty":"beginner","description":"The lever alternate leg press is a machine-based exercise targeting the quadriceps, with secondary emphasis on the hamstrings and glutes. It involves pressing one leg at a time against a foot platform, providing a controlled environment for building lower body strength.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2287.gif","youtube_id":null,"instructions":["Adjust the seat and foot platform of the leverage machine to your desired position.","Sit on the machine with your back against the backrest and your feet on the foot platform.","Place your hands on the handles or sides of the machine for stability.","Push one foot against the foot platform, extending your leg until it is almost fully straight.","Pause for a moment, then slowly bend your leg and return to the starting position.","Repeat with the other leg.","Continue alternating legs for the desired number of repetitions."]},{"id":"2288","name":"lever gripper hands","body_part":"lower arms","target":"forearms","secondary_muscles":["biceps","triceps"],"equipment":"leverage machine","difficulty":"beginner","description":"The lever gripper hands exercise targets the forearms using a leverage machine. It involves gripping and squeezing the handles to strengthen the forearm muscles, with secondary activation of the biceps and triceps.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2288.gif","youtube_id":null,"instructions":["Adjust the seat height and grip the handles of the leverage machine.","Keep your back straight and your feet flat on the ground.","Exhale and squeeze the handles, contracting your forearms.","Hold the contraction for a second, then slowly release and return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"2289","name":"lever calf press","body_part":"lower legs","target":"calves","secondary_muscles":["hamstrings"],"equipment":"leverage machine","difficulty":"beginner","description":"The lever calf press is a machine-based exercise targeting the calf muscles. It involves pressing a lever pad with the toes while the heels hang off the edge, focusing on ankle extension to contract the calves. The movement is controlled and supported by the machine, making it accessible for most users.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2289.gif","youtube_id":null,"instructions":["Adjust the seat of the leverage machine so that your shoulders are aligned with the lever pad.","Place your toes on the lever pad, with your heels hanging off the edge.","Grasp the handles or side supports for stability.","Push the lever pad down by extending your ankles, contracting your calf muscles.","Pause for a moment at the bottom of the movement.","Slowly return to the starting position by allowing your heels to rise back up.","Repeat for the desired number of repetitions."]},{"id":"229","name":"cable standing inner curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"cable","difficulty":"beginner","description":"The cable standing inner curl is an isolation exercise targeting the biceps, performed using a cable machine. It emphasizes controlled movement and contraction of the biceps while also engaging the forearms.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0229.gif","youtube_id":null,"instructions":["Stand facing a cable machine with your feet shoulder-width apart.","Grasp the cable handle with an underhand grip, palms facing up.","Keep your elbows close to your sides and your upper arms stationary.","Exhale and curl the cable handle towards your shoulders, contracting your biceps.","Pause for a moment at the top of the movement, squeezing your biceps.","Inhale and slowly lower the cable handle back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"2292","name":"dumbbell rear delt raise","body_part":"shoulders","target":"delts","secondary_muscles":["trapezius","rhomboids"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell rear delt raise is an isolation exercise targeting the rear deltoids, with secondary emphasis on the trapezius and rhomboids. It is performed by hinging at the hips and raising dumbbells out to the sides, focusing on shoulder movement.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2292.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing your body.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Raise your arms out to the sides, keeping a slight bend in your elbows, until they are parallel to the floor.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"2293","name":"dumbbell standing zottman preacher curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell standing Zottman preacher curl is a biceps-focused exercise that also targets the forearms. It combines the preacher curl with a wrist rotation at the top of the movement to emphasize both the biceps and forearm muscles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2293.gif","youtube_id":null,"instructions":["Stand up straight with a dumbbell in each hand, palms facing forward.","Place your upper arms against the preacher bench and keep your elbows slightly bent.","Curl the dumbbells up towards your shoulders while keeping your upper arms stationary.","At the top of the movement, rotate your wrists so that your palms are facing downward.","Slowly lower the dumbbells back to the starting position, rotating your wrists back to the starting position as well.","Repeat for the desired number of repetitions."]},{"id":"2294","name":"dumbbell zottman preacher curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell Zottman preacher curl is an isolation exercise that targets the biceps and forearms. It combines a standard preacher curl with a wrist rotation at the top, emphasizing both the biceps during the curl and the forearms during the lowering phase.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2294.gif","youtube_id":null,"instructions":["Sit on a preacher bench with a dumbbell in each hand, palms facing up and elbows resting on the pad.","Curl the dumbbells up towards your shoulders, keeping your upper arms stationary and your palms facing up.","At the top of the curl, rotate your wrists so that your palms are facing down.","Slowly lower the dumbbells back down to the starting position, rotating your wrists back to the starting position as you do so.","Repeat for the desired number of repetitions."]},{"id":"2297","name":"stability ball crunch (full range hands behind head)","body_part":"waist","target":"abs","secondary_muscles":["hip flexors"],"equipment":"stability ball","difficulty":"intermediate","description":"The stability ball crunch (full range hands behind head) is an abdominal exercise performed on a stability ball, targeting the abs and engaging the hip flexors as secondary muscles. The movement requires core engagement and balance to execute the crunch through a full range of motion while maintaining stability on the ball.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2297.gif","youtube_id":null,"instructions":["Sit on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, slowly curl your upper body forward, bringing your chest towards your knees.","Pause for a moment at the top, then slowly lower your upper body back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"2298","name":"inverted row on bench","body_part":"back","target":"upper back","secondary_muscles":["biceps","forearms"],"equipment":"body weight","difficulty":"beginner","description":"The inverted row on bench is a bodyweight exercise targeting the upper back, performed by pulling your chest up towards a bench while lying underneath it.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2298.gif","youtube_id":null,"instructions":["Set up a bench at a height that allows your body to hang freely underneath it.","Lie face up on the ground with your head towards the bench.","Reach up and grab the bench with an overhand grip, slightly wider than shoulder-width apart.","Position your body so that your heels are on the ground and your arms are fully extended.","Engage your core and squeeze your shoulder blades together as you pull your chest up towards the bench.","Pause for a moment at the top of the movement, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"23","name":"barbell alternate biceps curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"barbell","difficulty":"beginner","description":"The barbell alternate biceps curl is a strength exercise targeting the biceps, performed by alternately curling a barbell with each arm while standing. It also engages the forearms as secondary muscles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0023.gif","youtube_id":null,"instructions":["Stand up straight with your feet shoulder-width apart and hold a barbell in each hand, palms facing forward.","Keep your upper arms stationary and exhale as you curl the weights while contracting your biceps.","Continue to raise the barbells until your biceps are fully contracted and the barbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale as you slowly begin to lower the barbells back to the starting position.","Repeat for the desired number of repetitions, alternating arms."]},{"id":"230","name":"cable standing lift","body_part":"waist","target":"abs","secondary_muscles":["obliques","lower back"],"equipment":"cable","difficulty":"intermediate","description":"The cable standing lift is an exercise targeting the abdominal muscles, especially the obliques and lower back, by using a cable machine to perform a rotational lifting movement.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0230.gif","youtube_id":null,"instructions":["Stand facing the cable machine with your feet shoulder-width apart.","Hold the cable handle with both hands and position it at waist height.","Engage your core and maintain a straight back throughout the exercise.","Keeping your arms straight, exhale and lift the cable handle up towards your opposite shoulder, rotating your torso.","Pause for a moment at the top, then inhale and slowly lower the cable handle back to the starting position.","Repeat for the desired number of repetitions, then switch sides."]},{"id":"2300","name":"inverted row bent knees","body_part":"back","target":"upper back","secondary_muscles":["biceps","forearms"],"equipment":"body weight","difficulty":"beginner","description":"The inverted row with bent knees is a bodyweight exercise targeting the upper back. It involves pulling your chest towards a bar while keeping your body straight and your knees bent, making it more accessible than the straight-leg version.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2300.gif","youtube_id":null,"instructions":["Set up a bar at waist height and lie underneath it.","Grab the bar with an overhand grip, slightly wider than shoulder-width apart.","Position your body so that your heels are on the ground and your body is straight.","Pull your chest up towards the bar by squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"2301","name":"rear leg hook kick","body_part":"upper legs","target":"glutes","secondary_muscles":["hamstrings","abductors","adductors","quads","abs","calves"],"equipment":"body weight","difficulty":"intermediate","description":"From a fighting stance, lift the rear leg to the side and sweep the heel inward across the target in a hooking motion. Pivot on the lead foot, keep the core braced, and maintain your guard throughout.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2301.gif","youtube_id":null,"instructions":["Adopt a fighting stance with the rear foot behind, knees soft, hands up, and core braced.","Pivot on the ball of the lead foot to open the hips while keeping the torso tall.","Chamber the rear leg by lifting the knee out to the side (hip abduction) with the knee bent and foot dorsiflexed.","Sweep the lower leg inward in a horizontal arc, adducting the hip to ‘hook’ the target and striking with the heel or back of the foot.","Re-chamber the leg immediately, then place it back to the starting stance under control.","Exhale on the strike, keep the supporting knee soft, and avoid locking the kicking knee or over-rotating the hips."]},{"id":"2302","name":"front leg hook kick","body_part":"upper legs","target":"adductors","secondary_muscles":["abductors","glutes","quads","hamstrings","abs","calves"],"equipment":"body weight","difficulty":"intermediate","description":"From a fighting stance, lift the lead knee and perform a hook kick by extending slightly past the target, then sweeping inward to strike with the heel. Return the foot to the floor under control while keeping the torso tall and guard up.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2302.gif","youtube_id":null,"instructions":["Stand in fighting stance with the lead foot forward, hands up, and most of your weight on the rear leg.","Pivot on the rear/support foot to open the hips and point the heel slightly outward.","Chamber the lead leg: lift the knee to hip height with the thigh slightly out to the side; dorsiflex the ankle so the toes pull back.","Extend the lower leg a bit past the target, then sweep the foot inward across the midline in a hooking arc, striking with the heel/edge of the sole.","Keep the core braced and the torso upright; do not hyperextend the knee at extension.","Retract the leg immediately along the same path and place the foot down to the starting stance.","Repeat for controlled reps, then switch sides."]},{"id":"2303","name":"front groin kick","body_part":"upper legs","target":"quads","secondary_muscles":["abs","glutes","calves","hamstrings","adductors"],"equipment":"body weight","difficulty":"beginner","description":"Stand in a fighting stance with hands up. Lift the knee and snap the foot forward to groin height striking with the instep, then quickly retract and return to stance.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2303.gif","youtube_id":null,"instructions":["Stand in a staggered stance, feet hip-width apart, knees soft, hands guarding your chin.","Brace your core and center your weight over the support leg without leaning back.","Lift the lead knee toward your chest to chamber the kick, toes pointed slightly downward.","Snap the lower leg forward to groin height, striking with the instep/top of the foot.","Do not lock the knee at extension; stop the kick under control.","Immediately bend the knee to retract the leg along the same path.","Set the foot back under your hip to your original stance and reestablish balance.","Repeat for reps, then switch legs, maintaining posture throughout."]},{"id":"2304","name":"rear axe kick","body_part":"upper legs","target":"hamstrings","secondary_muscles":["glutes","abs","quads","calves","adductors","abductors"],"equipment":"body weight","difficulty":"intermediate","description":"From a fighting stance, lift the rear leg straight up in front of you and then drive the heel straight down like an axe before returning to stance. Keep the core braced and the foot dorsiflexed to strike with the heel.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2304.gif","youtube_id":null,"instructions":["Adopt a fighting stance with feet staggered, hands up, and core braced.","Shift weight to the lead leg and lift the rear knee, dorsiflexing the ankle (toes toward shin).","Extend the rear leg upward in front of you, keeping the leg mostly straight and torso tall.","At your top range, hinge from the hip and drive the heel straight down along the same line.","Land softly with the heel first, then the whole foot, near your centerline.","Retract the leg immediately and return to your fighting stance.","Keep the pelvis neutral, avoid hyperextending the low back, and do not lock the knee at the bottom."]},{"id":"2305","name":"front snap kick","body_part":"upper legs","target":"quads","secondary_muscles":["abs","glutes","hamstrings","calves","adductors"],"equipment":"body weight","difficulty":"intermediate","description":"From a fighting stance, lift (chamber) the knee and snap the lower leg forward to strike with the ball of the foot. Re-chamber immediately and return to your stance while maintaining balance and a braced core.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2305.gif","youtube_id":null,"instructions":["Stand in a fighting stance with one foot forward, hands up, and core braced.","Shift weight to the support leg, keeping a slight bend in that knee and hips square.","Chamber the kick: lift the knee of the kicking leg to about hip height; plantarflex the ankle and pull the toes back to expose the ball of the foot.","Snap the kick forward by rapidly extending the knee, striking a low–to–mid target; exhale and keep the torso tall.","Re-chamber immediately by bending the knee and bringing the heel back under the hip (do not lock the kicking knee).","Set the foot down under control into your stance and repeat for reps, then switch sides."]},{"id":"2306","name":"spin hook kick","body_part":"upper legs","target":"glutes","secondary_muscles":["abductors","adductors","hamstrings","quads","abs","calves"],"equipment":"body weight","difficulty":"advanced","description":"From a fighting stance, rotate and extend the leg in a sweeping arc to strike with the heel as you complete a spin. Maintain a tall posture and controlled re-chamber to return to stance.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2306.gif","youtube_id":null,"instructions":["Start in a fighting stance with feet shoulder-width apart, knees soft, and hands up.","Pivot on the lead foot and turn your head and shoulders first to spot the target, initiating the spin.","Rotate hips and torso, keeping the support heel turned outward to protect the knee.","Chamber the kicking leg by lifting the knee to the side (abduction) with the knee slightly bent.","Extend the leg and sweep the heel across in a hooking path, striking with the back of the heel at the target height.","Keep the core braced and torso upright; do not hyperextend the knee on contact.","Re-chamber the leg after the strike and place it down under control, returning to stance.","Reset balance, then repeat on the same or opposite side."]},{"id":"2307","name":"side kick","body_part":"upper legs","target":"abductors","secondary_muscles":["glutes","quads","hamstrings","calves","abs","obliques"],"equipment":"body weight","difficulty":"intermediate","description":"From an athletic stance, chamber the knee and drive a controlled side kick, leading with the heel. Pivot on the supporting foot, then re-chamber and lower under control.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2307.gif","youtube_id":null,"instructions":["Stand tall in a fighting stance, feet hip-width, hands up, core braced.","Shift weight to the supporting leg, bend it slightly, and pivot the supporting foot so toes turn away from the kicking side.","Lift the opposite knee toward the chest (chamber), heel tucked, toes pulled back, hips stacked.","Extend the leg out to the side, driving the heel toward the target at about hip height; keep the knee soft—do not lock out.","Keep torso upright and pelvis level; maintain a neutral spine throughout.","Briefly hold, then re-chamber the knee along the same path.","Lower the foot to the floor under control and repeat; switch sides evenly."]},{"id":"2308","name":"roundhouse kick","body_part":"upper legs","target":"quads","secondary_muscles":["glutes","abductors","adductors","hamstrings","calves","abs"],"equipment":"body weight","difficulty":"intermediate","description":"From a fighting stance, pivot on the support foot, rotate the hips, and snap the lead leg across the target, then re-chamber and return to stance. Strike with the shin or instep while keeping the core braced and guard up.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2308.gif","youtube_id":null,"instructions":["Stand in fighting stance with feet shoulder-width, rear heel slightly raised and hands up to guard.","Shift weight to the support leg, pivot that foot so the heel turns outward and the hips open.","Chamber the kicking leg by lifting the knee across the body with the shin parallel to the floor.","Snap the kick by rapidly extending the knee, striking with the shin or instep; exhale on impact.","Keep the torso upright, core tight, and eyes on target throughout.","Re-chamber the leg immediately, then place it down under control and return to stance.","Repeat for reps, then switch sides."]},{"id":"2309","name":"heel push kick","body_part":"upper legs","target":"quads","secondary_muscles":["glutes","abs","calves","hamstrings","abductors"],"equipment":"body weight","difficulty":"intermediate","description":"Stand in a fighting stance, raise the lead knee (chamber), then drive the heel straight forward to push the target before quickly re‑chambering and returning to stance. Keep the torso tall and strike with the heel by pulling the toes up.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2309.gif","youtube_id":null,"instructions":["Stand in a staggered stance with hands up, feet hip‑width, core braced, and eyes forward.","Lift the lead knee toward the chest (hip flex), keeping the ankle dorsiflexed so toes point up.","Drive the hips forward and extend the knee to push straight out, striking with the center of the heel.","Keep the supporting foot rooted and pelvis level; avoid leaning back or rotating the hips.","Stop short of locking the knee, then immediately re‑chamber by bending the knee and pulling the leg back.","Return the foot to the floor under control and reset in your stance.","Repeat for reps, then switch sides to train both legs."]},{"id":"231","name":"cable standing one arm triceps extension","body_part":"upper arms","target":"triceps","secondary_muscles":["shoulders"],"equipment":"cable","difficulty":"intermediate","description":"The cable standing one arm triceps extension is an isolation exercise that targets the triceps using a cable machine. It is performed standing, one arm at a time, and requires controlled movement to effectively engage the triceps while minimizing shoulder involvement.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0231.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, facing the cable machine.","Hold the cable handle with your right hand, palm facing down, and position your arm so that it is fully extended and parallel to the ground.","Keep your elbow stationary and close to your body.","Slowly bend your elbow, lowering the cable handle towards the back of your head.","Pause for a moment at the bottom of the movement, then extend your arm back to the starting position.","Repeat for the desired number of repetitions, then switch sides and perform the exercise with your left arm."]},{"id":"2310","name":"spin back kick","body_part":"upper legs","target":"glutes","secondary_muscles":["hamstrings","quads","calves","abs","adductors","spine"],"equipment":"body weight","difficulty":"intermediate","description":"From a fighting stance, rotate on the lead foot, look over your shoulder, then chamber the rear leg and drive the heel straight back. Re-chamber and return to your stance under control.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2310.gif","youtube_id":null,"instructions":["Stand in a fighting stance with feet shoulder-width and hands up.","Shift weight to the lead leg and pivot on its ball, turning your hips and head to spot the target over your shoulder.","Chamber the rear leg by bringing the knee across and heel toward the glute, toes pointing down.","Extend the hip and knee to drive the heel straight back along a linear path, striking with the heel.","Keep the core braced and torso slightly inclined forward; maintain balance on the supporting foot.","Re-chamber the leg immediately after contact, then set it down and return to your stance."]},{"id":"2311","name":"walking on stepmill","body_part":"cardio","target":"cardiovascular system","secondary_muscles":["quadriceps","hamstrings","glutes","calves"],"equipment":"stepmill machine","difficulty":"beginner","description":"Walking on a stepmill is a cardiovascular exercise performed on a machine that simulates stair climbing. It primarily targets the cardiovascular system while also engaging the lower body muscles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2311.gif","youtube_id":null,"instructions":["Adjust the stepmill machine to a comfortable level.","Step onto the machine and place your hands on the handrails for support.","Start walking by placing one foot on a step and then the other, alternating between legs.","Maintain an upright posture and engage your core muscles.","Continue walking for the desired duration or distance.","Gradually increase the intensity or speed as you become more comfortable with the exercise.","Remember to cool down and stretch after completing the exercise."]},{"id":"2312","name":"lying elbow to knee","body_part":"waist","target":"abs","secondary_muscles":["hip flexors","lower back"],"equipment":"body weight","difficulty":"beginner","description":"The lying elbow to knee is a bodyweight abdominal exercise that targets the abs, with secondary emphasis on the hip flexors and lower back. It involves alternating elbow-to-knee movements while lying on your back, engaging the core and promoting coordination.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2312.gif","youtube_id":null,"instructions":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engage your abs and lift your upper body off the ground, bringing your right elbow towards your left knee.","At the same time, extend your right leg straight out and lift it off the ground.","Pause for a moment, then return to the starting position.","Repeat the movement, this time bringing your left elbow towards your right knee and extending your left leg.","Continue alternating sides for the desired number of repetitions."]},{"id":"2315","name":"lever rotary calf","body_part":"lower legs","target":"calves","secondary_muscles":["soleus","ankle stabilizers"],"equipment":"leverage machine","difficulty":"beginner","description":"The lever rotary calf exercise targets the calves using a leverage machine. It involves raising and lowering the heels while seated, focusing on the calf muscles and ankle stabilizers.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2315.gif","youtube_id":null,"instructions":["Adjust the seat height so that your knees are slightly bent and your feet are flat on the footplate.","Place your toes on the footplate, with your heels hanging off the edge.","Grasp the handles or the sides of the machine for stability.","Push through the balls of your feet, raising your heels as high as possible.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"2317","name":"dumbbell seated bent arm lateral raise","body_part":"shoulders","target":"delts","secondary_muscles":["trapezius","rhomboids"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell seated bent arm lateral raise targets the deltoid muscles in the shoulders, with secondary emphasis on the trapezius and rhomboids. It is performed while seated, which helps stabilize the body and focus the effort on the shoulders.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2317.gif","youtube_id":null,"instructions":["Sit on a bench with your back straight and feet flat on the ground.","Hold a dumbbell in each hand with your palms facing your body and your arms bent at a 90-degree angle.","Keeping your elbows bent, raise your arms out to the sides until they are parallel to the ground.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"2318","name":"lever shoulder press v. 3","body_part":"shoulders","target":"delts","secondary_muscles":["triceps","chest"],"equipment":"leverage machine","difficulty":"beginner","description":"The lever shoulder press v. 3 is a machine-based exercise targeting the deltoid muscles of the shoulders. It also engages the triceps and chest as secondary muscles. The movement involves pressing handles upward and forward while seated, providing a stable and controlled environment for developing shoulder strength.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2318.gif","youtube_id":null,"instructions":["Adjust the seat height and backrest of the leverage machine to a comfortable position.","Sit on the machine with your back against the backrest and your feet flat on the floor.","Grasp the handles of the machine with an overhand grip, slightly wider than shoulder-width apart.","Push the handles upward and forward until your arms are fully extended, but not locked.","Pause for a moment at the top, then slowly lower the handles back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"232","name":"cable standing pulldown (with rope)","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms","shoulders"],"equipment":"cable","difficulty":"beginner","description":"The cable standing pulldown (with rope) is an isolation exercise primarily targeting the biceps, with secondary emphasis on the forearms and shoulders. It uses a cable machine with a rope attachment and is performed standing, requiring good form and control.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0232.gif","youtube_id":null,"instructions":["Attach a rope to the cable machine at the highest setting.","Stand facing the machine with your feet shoulder-width apart.","Grasp the rope with an overhand grip, palms facing down.","Keep your back straight and core engaged throughout the exercise.","Pull the rope down towards your thighs, squeezing your biceps.","Pause for a moment at the bottom, then slowly release the rope back up.","Repeat for the desired number of repetitions."]},{"id":"2321","name":"dumbbell standing inner biceps curl v. 2","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell standing inner biceps curl v. 2 is a strength exercise that targets the biceps, with secondary emphasis on the forearms. It involves curling dumbbells while standing, focusing on strict form and biceps contraction.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2321.gif","youtube_id":null,"instructions":["Stand up straight with a dumbbell in each hand, palms facing your torso.","Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward.","While holding your upper arms stationary, curl the weights while contracting your biceps.","Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Slowly begin to bring the dumbbells back to the starting position as your breathe in.","Repeat for the recommended amount of repetitions."]},{"id":"2327","name":"dumbbell reverse grip row (female)","body_part":"back","target":"upper back","secondary_muscles":["biceps","forearms"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell reverse grip row is a strength exercise targeting the upper back, performed with dumbbells and a reverse (underhand) grip. It also engages the biceps and forearms.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2327.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and knees slightly bent.","Hold a dumbbell in each hand with an overhand grip, palms facing your body.","Bend forward at the waist, keeping your back straight and your core engaged.","Let your arms hang straight down, fully extended, with a slight bend in your elbows.","Pull the dumbbells up towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"2328","name":"narrow push-up on exercise ball","body_part":"upper arms","target":"triceps","secondary_muscles":["chest","shoulders"],"equipment":"stability ball","difficulty":"advanced","description":"The narrow push-up on an exercise ball is a challenging upper body exercise that targets the triceps while also engaging the chest and shoulders. The instability of the ball increases the demand on core stability and balance.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2328.gif","youtube_id":null,"instructions":["Place the stability ball on the ground and position yourself in a push-up position with your hands on the ball, slightly narrower than shoulder-width apart.","Engage your core and keep your body in a straight line from head to toe.","Lower your chest towards the ball by bending your elbows, keeping them close to your body.","Pause for a moment at the bottom, then push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."]},{"id":"2329","name":"spine twist","body_part":"waist","target":"abs","secondary_muscles":["obliques","lower back"],"equipment":"body weight","difficulty":"beginner","description":"The spine twist is a bodyweight exercise that targets the abs, obliques, and lower back. It involves sitting on the ground, engaging the core, and twisting the torso side to side, which helps improve core strength and mobility.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2329.gif","youtube_id":null,"instructions":["Sit on the ground with your legs extended in front of you.","Bend your knees and place your feet flat on the ground, hip-width apart.","Place your hands behind your head with your elbows pointing outwards.","Engage your abs and slowly twist your torso to the right, bringing your right elbow towards your left knee.","Pause for a moment at the end of the twist, then slowly return to the starting position.","Repeat the twist to the left side, bringing your left elbow towards your right knee.","Continue alternating sides for the desired number of repetitions."]},{"id":"233","name":"cable standing rear delt row (with rope)","body_part":"shoulders","target":"delts","secondary_muscles":["trapezius","rhomboids","biceps"],"equipment":"cable","difficulty":"intermediate","description":"The cable standing rear delt row (with rope) targets the rear deltoids and upper back muscles using a cable machine and rope attachment. It requires proper form to effectively engage the shoulders and upper back while maintaining core stability.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0233.gif","youtube_id":null,"instructions":["Stand facing a cable machine with your feet shoulder-width apart.","Hold the cable attachment with both hands, palms facing each other, and step back to create tension in the cable.","Keep your back straight and your core engaged.","Pull the cable towards your body, squeezing your shoulder blades together.","Pause for a moment at the peak of the movement, then slowly release the cable back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"2330","name":"cable lat pulldown full range of motion","body_part":"back","target":"lats","secondary_muscles":["biceps","rhomboids","rear deltoids"],"equipment":"cable","difficulty":"beginner","description":"The cable lat pulldown full range of motion is a strength exercise targeting the latissimus dorsi (lats) using a cable machine. It also engages the biceps, rhomboids, and rear deltoids. The movement involves pulling a cable bar down towards the chest while seated, emphasizing a full range of motion for optimal muscle activation.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2330.gif","youtube_id":null,"instructions":["Sit on the lat pulldown machine with your knees positioned under the pads.","Grasp the cable bar with an overhand grip, slightly wider than shoulder-width apart.","Lean back slightly and keep your chest up, maintaining a slight arch in your lower back.","Pull the bar down towards your upper chest, squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, then slowly release the bar back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"2331","name":"cycle cross trainer","body_part":"cardio","target":"cardiovascular system","secondary_muscles":["quadriceps","hamstrings","glutes"],"equipment":"leverage machine","difficulty":"beginner","description":"The cycle cross trainer is a cardiovascular exercise performed on a leverage machine, targeting the cardiovascular system while also engaging the quadriceps, hamstrings, and glutes. It is performed by pedaling in a smooth and controlled motion, with adjustable resistance for varying intensity.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2331.gif","youtube_id":null,"instructions":["Adjust the seat height and position yourself on the cycle cross trainer.","Place your feet on the pedals and grip the handlebars.","Start pedaling in a smooth and controlled motion.","Maintain a steady pace and increase the resistance if desired.","Continue pedaling for the desired duration of your cardio workout."]},{"id":"2333","name":"arm slingers hanging straight legs","body_part":"waist","target":"abs","secondary_muscles":["shoulders","back"],"equipment":"body weight","difficulty":"advanced","description":"The arm slingers hanging straight legs exercise involves hanging from a pull-up bar and lifting your straight legs up in front of you, targeting the abdominal muscles while also engaging the shoulders and back.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2333.gif","youtube_id":null,"instructions":["Hang from a pull-up bar with your arms fully extended and your legs straight down.","Engage your core and lift your legs up in front of you until they are parallel to the ground.","Hold for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"2334","name":"sled lying calf press","body_part":"lower legs","target":"calves","secondary_muscles":["hamstrings","glutes"],"equipment":"sled machine","difficulty":"beginner","description":"The sled lying calf press is a machine-based exercise targeting the calves, performed by pressing a weighted sled away using the balls of the feet while lying on the machine.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2334.gif","youtube_id":null,"instructions":["Adjust the sled machine to a comfortable weight.","Sit on the sled machine with your back against the pad and your feet on the platform.","Place your toes and the balls of your feet on the edge of the platform, with your heels hanging off.","Push the platform away from you by extending your ankles, keeping your knees slightly bent.","Continue pushing until your calves are fully contracted.","Hold the contraction for a moment, then slowly lower the platform back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"2335","name":"lever seated calf press","body_part":"lower legs","target":"calves","secondary_muscles":["soleus","hamstrings"],"equipment":"leverage machine","difficulty":"beginner","description":"The lever seated calf press is a machine-based exercise targeting the calf muscles. It involves pressing a weighted lever with the balls of your feet while seated, focusing on ankle extension to work the calves.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2335.gif","youtube_id":null,"instructions":["Adjust the seat of the machine so that your shoulders are aligned with the lever pad.","Place your toes on the lower portion of the platform and position your knees under the lever pad.","Grasp the handles on the sides of the seat for stability.","Press the lever pad down by extending your ankles, lifting your heels as high as possible.","Pause for a moment at the top of the movement, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"234","name":"cable standing row (v-bar)","body_part":"back","target":"upper back","secondary_muscles":["biceps","shoulders"],"equipment":"cable","difficulty":"beginner","description":"The cable standing row (v-bar) is a compound exercise that targets the upper back using a cable machine and a v-bar attachment. It also engages the biceps and shoulders as secondary muscles. The movement requires proper posture and core engagement to perform safely and effectively.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0234.gif","youtube_id":null,"instructions":["Stand facing the cable machine with your feet shoulder-width apart.","Grasp the v-bar attachment with an overhand grip, palms facing down.","Keep your back straight and your core engaged.","Pull the v-bar towards your body, squeezing your shoulder blades together.","Pause for a moment at the peak of the movement, then slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"235","name":"cable standing shoulder external rotation","body_part":"shoulders","target":"delts","secondary_muscles":["rotator cuff","trapezius"],"equipment":"cable","difficulty":"beginner","description":"The cable standing shoulder external rotation is an exercise that targets the deltoid muscles, particularly focusing on shoulder stability and external rotation. It also engages the rotator cuff and trapezius muscles, making it effective for improving shoulder health and function.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0235.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and your knees slightly bent.","Hold the cable handle with your arm extended in front of you, parallel to the ground.","Keep your elbow slightly bent and your shoulder blades pulled back.","Slowly rotate your arm outward, away from your body, while keeping your elbow in the same position.","Pause for a moment at the end of the movement, then slowly return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"2355","name":"arm slingers hanging bent knee legs","body_part":"waist","target":"abs","secondary_muscles":["shoulders","back"],"equipment":"body weight","difficulty":"intermediate","description":"The arm slingers hanging bent knee legs exercise targets the abdominal muscles by requiring you to hang from a pull-up bar and lift your knees towards your chest. This movement also engages the shoulders and back for stabilization.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2355.gif","youtube_id":null,"instructions":["Hang from a pull-up bar with your arms fully extended and your knees bent at a 90-degree angle.","Engage your core and lift your knees towards your chest, bringing them as close to your elbows as possible.","Slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"236","name":"cable standing twist row (v-bar)","body_part":"back","target":"upper back","secondary_muscles":["biceps","shoulders"],"equipment":"cable","difficulty":"intermediate","description":"The cable standing twist row (v-bar) is a compound exercise that targets the upper back while also engaging the biceps and shoulders. It incorporates a twisting motion, which adds a rotational component to the traditional row, enhancing core engagement and coordination.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0236.gif","youtube_id":null,"instructions":["Attach a v-bar attachment to a cable machine at chest height.","Stand facing the cable machine with your feet shoulder-width apart.","Grasp the v-bar with an overhand grip, palms facing down.","Take a step back to create tension in the cable.","Keep your back straight and core engaged throughout the exercise.","Pull the v-bar towards your torso by retracting your shoulder blades and bending your elbows.","As you pull, twist your torso to one side, squeezing your shoulder blades together.","Pause for a moment at the top of the movement, feeling the contraction in your upper back.","Slowly release the tension and return to the starting position, untwisting your torso.","Repeat the movement for the desired number of repetitions, alternating the twisting direction with each rep."]},{"id":"2363","name":"wide-grip chest dip on high parallel bars","body_part":"chest","target":"pectorals","secondary_muscles":["triceps","shoulders"],"equipment":"body weight","difficulty":"advanced","description":"The wide-grip chest dip on high parallel bars is a bodyweight exercise that targets the pectoral muscles, with secondary emphasis on the triceps and shoulders. It requires significant upper body strength, stability, and control, as well as experience with dip movements.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2363.gif","youtube_id":null,"instructions":["Position yourself on the parallel bars with your arms fully extended and your body suspended in the air.","Lean forward slightly and lower your body by bending your elbows until your chest is just above the bars.","Pause for a moment, then push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."]},{"id":"2364","name":"assisted wide-grip chest dip (kneeling)","body_part":"chest","target":"pectorals","secondary_muscles":["triceps","shoulders"],"equipment":"leverage machine","difficulty":"beginner","description":"The assisted wide-grip chest dip (kneeling) is a machine-based exercise targeting the pectorals, with secondary emphasis on the triceps and shoulders. The assistance from the machine makes it accessible for those who may not yet have the strength for unassisted dips.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2364.gif","youtube_id":null,"instructions":["Adjust the machine to your desired height and secure your knees on the pad.","Grasp the handles with a wide grip and keep your elbows slightly bent.","Lower your body by bending your elbows until your upper arms are parallel to the floor.","Push yourself back up to the starting position by extending your arms.","Repeat for the desired number of repetitions."]},{"id":"2368","name":"split squats","body_part":"upper legs","target":"quads","secondary_muscles":["glutes","hamstrings","calves"],"equipment":"body weight","difficulty":"beginner","description":"Split squats are a lower body exercise that primarily targets the quadriceps, while also engaging the glutes, hamstrings, and calves. This bodyweight movement involves stepping forward into a split stance and lowering the body until the front thigh is parallel to the ground, then returning to the starting position.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2368.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart.","Take a step forward with one foot and place it about two feet in front of the other foot.","Lower your body by bending your knees and hips, keeping your back straight.","Continue lowering until your front thigh is parallel to the ground, and your back knee is hovering just above the ground.","Pause for a moment, then push through your front heel to return to the starting position.","Repeat for the desired number of repetitions, then switch legs and repeat."]},{"id":"237","name":"cable straight arm pulldown (with rope)","body_part":"back","target":"lats","secondary_muscles":["biceps","forearms"],"equipment":"cable","difficulty":"beginner","description":"The cable straight arm pulldown (with rope) is an isolation exercise that targets the latissimus dorsi (lats) using a cable machine and rope attachment. It emphasizes controlled movement and proper form to effectively engage the back muscles while minimizing arm involvement.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0237.gif","youtube_id":null,"instructions":["Attach a rope to the cable machine at the highest setting.","Stand facing the machine with your feet shoulder-width apart.","Grasp the rope with both hands, palms facing down.","Extend your arms fully in front of you, keeping your elbows slightly bent.","Engage your lats and slowly pull the rope down towards your thighs, keeping your arms straight.","Pause for a moment at the bottom, then slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"2371","name":"weighted russian twist v. 2","body_part":"waist","target":"abs","secondary_muscles":["obliques","lower back"],"equipment":"weighted","difficulty":"intermediate","description":"The weighted Russian twist v.2 is a core exercise that targets the abdominal muscles, particularly the obliques, by incorporating rotational movement with added resistance. It requires balance, coordination, and core strength.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2371.gif","youtube_id":null,"instructions":["Sit on the ground with your knees bent and feet flat on the floor.","Hold the weight with both hands in front of your chest.","Lean back slightly to engage your core muscles.","Twist your torso to the right, bringing the weight towards the right side of your body.","Pause for a moment, then twist your torso to the left, bringing the weight towards the left side of your body.","Continue alternating sides for the desired number of repetitions."]},{"id":"238","name":"cable straight arm pulldown","body_part":"back","target":"lats","secondary_muscles":["shoulders","biceps"],"equipment":"cable","difficulty":"beginner","description":"The cable straight arm pulldown is an isolation exercise targeting the latissimus dorsi, performed using a cable machine and a straight bar attachment. It emphasizes keeping the arms straight to maximize lat engagement and minimize biceps involvement.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0238.gif","youtube_id":null,"instructions":["Attach a straight bar to the high pulley of a cable machine.","Stand facing the machine with your feet shoulder-width apart.","Grasp the bar with an overhand grip, keeping your arms straight and your palms facing down.","Engage your lats and pull the bar down towards your thighs, keeping your arms straight throughout the movement.","Pause for a moment at the bottom, then slowly return the bar to the starting position.","Repeat for the desired number of repetitions."]},{"id":"239","name":"cable straight back seated row","body_part":"back","target":"upper back","secondary_muscles":["biceps","forearms","shoulders"],"equipment":"cable","difficulty":"beginner","description":"The cable straight back seated row is a strength exercise targeting the upper back, performed on a cable row machine. It involves pulling the cable handles towards the body while keeping the back straight, engaging the upper back, biceps, forearms, and shoulders.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0239.gif","youtube_id":null,"instructions":["Sit on the cable row machine with your feet flat on the footrests and your knees slightly bent.","Grasp the cable handles with an overhand grip, palms facing down.","Keep your back straight and lean slightly forward from the hips.","Pull the cable handles towards your body, squeezing your shoulder blades together.","Pause for a moment at the peak of the movement, then slowly release the handles back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"2397","name":"dumbbell scott press","body_part":"shoulders","target":"delts","secondary_muscles":["triceps","chest"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell Scott press is a shoulder exercise performed while seated, pressing dumbbells overhead to target the deltoid muscles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2397.gif","youtube_id":null,"instructions":["Sit on a bench with a dumbbell in each hand, palms facing forward.","Raise the dumbbells to shoulder height, with your elbows bent and palms facing forward.","Press the dumbbells upward until your arms are fully extended.","Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"2398","name":"close-grip push-up (on knees)","body_part":"upper arms","target":"triceps","secondary_muscles":["chest","shoulders"],"equipment":"body weight","difficulty":"beginner","description":"The close-grip push-up (on knees) is a bodyweight exercise that primarily targets the triceps, with secondary emphasis on the chest and shoulders. It is performed from a kneeling position, making it more accessible for beginners and those building upper body strength.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2398.gif","youtube_id":null,"instructions":["Start by getting on your hands and knees, with your hands shoulder-width apart and your knees hip-width apart.","Lower your upper body towards the ground by bending your elbows, keeping them close to your sides.","Pause for a moment when your chest is just above the ground.","Push through your palms to straighten your arms and return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"2399","name":"cable seated twist","body_part":"waist","target":"abs","secondary_muscles":["obliques"],"equipment":"cable","difficulty":"intermediate","description":"The cable seated twist is an exercise targeting the abdominal muscles, particularly the obliques, using a cable machine. It involves rotating the torso while seated, providing resistance throughout the movement.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2399.gif","youtube_id":null,"instructions":["Sit on a cable machine with your feet flat on the ground and your knees slightly bent.","Hold the cable handle with both hands and extend your arms straight in front of you.","Keeping your core engaged, slowly rotate your torso to one side, pulling the cable across your body.","Pause for a moment at the end of the range of motion, then slowly rotate back to the starting position.","Repeat on the other side.","Continue alternating sides for the desired number of repetitions."]},{"id":"24","name":"barbell bench front squat","body_part":"upper legs","target":"quads","secondary_muscles":["hamstrings","glutes","calves"],"equipment":"barbell","difficulty":"intermediate","description":"The barbell bench front squat is a compound lower body exercise that targets the quadriceps, with secondary emphasis on the hamstrings, glutes, and calves. It requires holding a barbell in the front rack position and performing a squat, demanding good core stability, balance, and mobility.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0024.gif","youtube_id":null,"instructions":["Start by standing with your feet shoulder-width apart and the barbell resting on your upper chest, just below your collarbone.","Hold the barbell with an overhand grip, keeping your elbows up and your upper arms parallel to the ground.","Lower your body down into a squat position by bending at the knees and hips, keeping your back straight and your chest up.","Pause for a moment at the bottom of the squat, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"240","name":"cable supine reverse fly","body_part":"shoulders","target":"delts","secondary_muscles":["trapezius","rhomboids"],"equipment":"cable","difficulty":"intermediate","description":"The cable supine reverse fly is an isolation exercise targeting the rear deltoids, performed lying face down on a bench while using a cable machine. It emphasizes shoulder strength and stability, with secondary activation of the trapezius and rhomboids.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0240.gif","youtube_id":null,"instructions":["Attach a D-handle to a low pulley cable machine and lie face down on a flat bench.","Grasp the D-handle with each hand, palms facing down, and extend your arms straight out in front of you.","Keeping your arms straight, raise them out to the sides until they are parallel to the floor.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"2400","name":"inverse leg curl (on pull-up cable machine)","body_part":"upper legs","target":"hamstrings","secondary_muscles":["glutes","calves"],"equipment":"body weight","difficulty":"advanced","description":"The inverse leg curl (on pull-up cable machine) is a bodyweight exercise targeting the hamstrings, with secondary emphasis on the glutes and calves. It involves lying face down, attaching ankle straps to a cable machine, and curling the legs towards the glutes.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2400.gif","youtube_id":null,"instructions":["Adjust the cable machine so that the ankle straps are at the lowest setting.","Lie face down on the bench with your legs extended and the ankle straps attached to your feet.","Hold onto the handles of the bench for stability.","Bend your knees and curl your legs towards your glutes, squeezing your hamstrings.","Pause for a moment at the top of the movement, then slowly lower your legs back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"2401","name":"dumbbell biceps curl (with arm blaster)","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell biceps curl (with arm blaster) is an isolation exercise targeting the biceps, using a specialized arm blaster to maintain strict form and minimize shoulder involvement. This exercise is performed with dumbbells and emphasizes biceps strength and hypertrophy.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2401.gif","youtube_id":null,"instructions":["Stand up straight with a dumbbell in each hand, palms facing forward.","Keep your elbows close to your torso and your upper arms stationary.","Exhale and curl the weights while contracting your biceps.","Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"2402","name":"dumbbell hammer curls (with arm blaster)","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell hammer curl with arm blaster is an isolation exercise targeting the biceps and forearms. The arm blaster helps maintain proper form by preventing the elbows from moving forward, increasing biceps activation.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2402.gif","youtube_id":null,"instructions":["Stand up straight with a dumbbell in each hand, palms facing your torso.","Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward.","This will be your starting position.","Now, while holding your upper arm stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Then, inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the recommended amount of repetitions."]},{"id":"2403","name":"dumbbell alternate biceps curl (with arm blaster)","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell alternate biceps curl (with arm blaster) is an isolation exercise targeting the biceps, using an arm blaster to maintain strict form and minimize shoulder involvement. This exercise is performed by alternately curling dumbbells while keeping the upper arms stationary against the arm blaster.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2403.gif","youtube_id":null,"instructions":["Stand up straight with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing forward.","Place the arm blaster on your upper arms, ensuring a secure fit.","Keeping your upper arms stationary, exhale and curl one dumbbell up towards your shoulder while contracting your biceps.","Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly lower the dumbbell back to the starting position.","Repeat the movement with the opposite arm.","Continue alternating arms for the desired number of repetitions."]},{"id":"2404","name":"ez-bar biceps curl (with arm blaster)","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"ez barbell","difficulty":"intermediate","description":"The EZ-bar biceps curl (with arm blaster) is a strength exercise targeting the biceps, using an EZ barbell and an arm blaster to isolate the upper arms and minimize cheating. It is performed standing, with the upper arms stabilized against the arm blaster, curling the barbell upward and then lowering it under control.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2404.gif","youtube_id":null,"instructions":["Stand up straight with your feet shoulder-width apart and hold the ez barbell with an underhand grip, palms facing up.","Place your upper arms against the arm blaster, keeping them stationary throughout the exercise.","Keeping your elbows close to your body, exhale and curl the barbell up towards your shoulders.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the barbell back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]},{"id":"2405","name":"cable triceps pushdown (v-bar) (with arm blaster)","body_part":"upper arms","target":"triceps","secondary_muscles":["forearms"],"equipment":"cable","difficulty":"beginner","description":"The cable triceps pushdown (v-bar) with arm blaster is an isolation exercise targeting the triceps, performed using a cable machine and a v-bar attachment. The arm blaster helps keep the upper arms stationary, increasing triceps engagement.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2405.gif","youtube_id":null,"instructions":["Attach a v-bar attachment to the cable machine at the highest setting.","Stand facing the cable machine with your feet shoulder-width apart.","Grasp the v-bar with an overhand grip, palms facing down, and your hands shoulder-width apart.","Keep your elbows close to your sides and your upper arms stationary throughout the exercise.","Engage your triceps and exhale as you push the v-bar down until your arms are fully extended.","Pause for a moment at the bottom of the movement, squeezing your triceps.","Inhale as you slowly return the v-bar to the starting position, maintaining control.","Repeat for the desired number of repetitions."]},{"id":"2406","name":"cable reverse grip triceps pushdown (sz-bar) (with arm blaster)","body_part":"upper arms","target":"triceps","secondary_muscles":["forearms"],"equipment":"cable","difficulty":"intermediate","description":"The cable reverse grip triceps pushdown (sz-bar) with arm blaster is an isolation exercise targeting the triceps, using a cable machine and an underhand grip for increased emphasis on the triceps' long head. The arm blaster helps keep the upper arms stationary, improving form and muscle engagement.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2406.gif","youtube_id":null,"instructions":["Attach a straight bar to the cable machine at the highest setting.","Stand facing the cable machine with your feet shoulder-width apart.","Grasp the bar with an underhand grip, palms facing up, and your hands shoulder-width apart.","Keep your elbows close to your sides and your upper arms stationary throughout the exercise.","Engage your triceps and slowly push the bar down until your arms are fully extended.","Pause for a moment at the bottom, then slowly return the bar to the starting position.","Repeat for the desired number of repetitions."]},{"id":"2407","name":"barbell biceps curl (with arm blaster)","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"barbell","difficulty":"beginner","description":"The barbell biceps curl with arm blaster is a strength exercise that isolates the biceps by preventing elbow movement and reducing cheating. The arm blaster helps maintain proper form, making the exercise more effective for targeting the biceps.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2407.gif","youtube_id":null,"instructions":["Stand up straight with your feet shoulder-width apart and hold a barbell with an underhand grip, palms facing up.","Place your upper arms against the arm blaster, keeping your elbows close to your torso.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the barbell until your biceps are fully contracted and the bar is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the barbell back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"2408","name":"weighted lying neck extension (with head harness)","body_part":"neck","target":"levator scapulae","secondary_muscles":["traps","upper back"],"equipment":"weighted","difficulty":"intermediate","description":"Lie face down on an incline bench with your chest supported and head hanging off the edge, wearing a head harness with a weight plate attached. Extend the neck to lift the head to neutral, then lower slowly under control.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2408.gif","youtube_id":null,"instructions":["Set an incline bench and attach the head harness so the chain and plate hang directly below the back of your head.","Lie prone with chest on the bench, hips anchored, toes on the floor, and head past the edge.","Brace your core, depress and retract the shoulders; begin with the neck slightly flexed (chin gently tucked).","Extend the neck to lift your head until it aligns with your torso—avoid hyperextension or swinging.","Pause briefly at the top while keeping the torso still.","Lower your head slowly to the start position, maintaining control and a neutral upper back.","Use light to moderate load and stop if you feel sharp neck discomfort."]},{"id":"2409","name":"weighted lying neck flexion (with head harness)","body_part":"neck","target":"levator scapulae","secondary_muscles":["scalenes","longus colli","longus capitis","upper trapezius","deep cervical flexors"],"equipment":"weighted","difficulty":"intermediate","description":"Lie supine on a bench with your head off the edge, wearing a head harness attached to a light weight. Flex the neck to bring the chin toward the chest, then lower under control through a comfortable range.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2409.gif","youtube_id":null,"instructions":["Set a flat bench and lie on your back with shoulders near the edge so your head can move freely; plant your feet and brace your torso.","Fit the head harness snugly and attach a light plate so it provides resistance as you flex the neck.","Start with the neck slightly extended below neutral, eyes up, shoulders relaxed and down.","Initiate with a gentle nod, then curl your chin toward your chest by segmentally flexing the cervical spine.","Pause briefly in the top position without lifting the shoulders or hips.","Lower slowly for 2–3 seconds back to a slight, comfortable extension; keep the motion smooth and pain‑free.","Maintain steady breathing and keep reps strict; stop if form or control degrades."]},{"id":"241","name":"cable triceps pushdown (v-bar)","body_part":"upper arms","target":"triceps","secondary_muscles":["forearms"],"equipment":"cable","difficulty":"beginner","description":"The cable triceps pushdown (v-bar) is an isolation exercise targeting the triceps using a cable machine and a v-bar attachment. It is commonly performed to build strength and muscle definition in the triceps.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0241.gif","youtube_id":null,"instructions":["Attach a v-bar attachment to the cable machine at the highest setting.","Stand facing the cable machine with your feet shoulder-width apart.","Grasp the v-bar with an overhand grip, palms facing down, and your hands shoulder-width apart.","Keep your elbows close to your sides and your upper arms stationary throughout the exercise.","Engage your triceps and exhale as you push the v-bar down until your arms are fully extended.","Pause for a moment at the bottom of the movement, squeezing your triceps.","Inhale as you slowly return the v-bar to the starting position, maintaining control.","Repeat for the desired number of repetitions."]},{"id":"2410","name":"weighted standing neck extension (with head harness)","body_part":"neck","target":"levator scapulae","secondary_muscles":["traps","upper back","spine"],"equipment":"weighted","difficulty":"intermediate","description":"With a head harness attached to a weight plate, stand and hinge slightly so the plate hangs freely. Extend the neck to bring the head to neutral, then lower back under control.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2410.gif","youtube_id":null,"instructions":["Fit the head harness snugly above the ears and across the forehead/occiput; clip the plate to the chain.","Stand feet hip‑width with soft knees, hinge slightly at the hips, and brace your core while keeping the back neutral.","Let the weight hang vertically; depress the shoulders and keep the torso still.","Begin with the neck slightly flexed (chin gently toward chest) without rounding your upper back.","Exhale and extend the neck by driving the back of your head upward until your face is level; avoid hyperextending past neutral.","Pause briefly, then inhale and lower the chin under control for 2–3 seconds; repeat for reps, stopping if you feel neck joint pain or dizziness."]},{"id":"2411","name":"cable seated neck extension (with head harness)","body_part":"neck","target":"levator scapulae","secondary_muscles":["traps","upper back"],"equipment":"cable","difficulty":"intermediate","description":"Sit facing a low cable stack wearing a snug head harness attached to the cable. From a slightly flexed neck position, extend the neck against the cable to neutral or slight extension, then return under control.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2411.gif","youtube_id":null,"instructions":["Set a low pulley and clip the head harness ring to the carabiner.","Sit facing the stack with feet flat and torso upright; slide back until the cable is taut.","Put on the harness with the pad centered on your forehead and the strap snug.","Start with a slight chin tuck and mild neck flexion; keep shoulders down and core braced.","Exhale and extend your neck back until your head reaches neutral or a slight extension—do not arch the lower back.","Pause briefly, then inhale and slowly return to the starting position under control.","Maintain a smooth tempo, avoid jerking, and keep the range pain‑free; do not hyperextend.","Use small load increases and stop if you feel neck joint discomfort or tingling."]},{"id":"2412","name":"cable seated neck flexion (with head harness)","body_part":"neck","target":"levator scapulae","secondary_muscles":["sternocleidomastoid","scalenes","longus colli","longus capitis"],"equipment":"cable","difficulty":"intermediate","description":"Sit facing away from a cable machine with a head harness attached to the cable at about head height. Keeping the torso still, flex the neck to bring the chin toward the chest against the cable’s pull, then return under control.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2412.gif","youtube_id":null,"instructions":["Set a cable pulley roughly at seated head height and select a very light weight.","Sit on a bench facing away from the machine; clip the head harness D‑ring behind your head to the cable.","Sit tall with feet flat, core braced, shoulders relaxed, and neck in neutral alignment.","Pre-tension the cable by scooting forward slightly without extending the neck.","Exhale and flex the neck, nodding the chin toward the chest through a comfortable range without rounding the torso.","Pause briefly, then slowly return to neutral while resisting the pull—do not hyperextend.","Keep the motion smooth and small; stop immediately if you feel pain or dizziness."]},{"id":"2414","name":"barbell standing concentration curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"barbell","difficulty":"intermediate","description":"The barbell standing concentration curl is an isolation exercise targeting the biceps, performed standing with a barbell in one hand while the other hand supports the body. It emphasizes strict form and muscle contraction.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2414.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and hold a barbell in one hand, palm facing up.","Rest your opposite hand on your thigh for support.","Keeping your upper arm stationary, exhale and curl the weight up towards your shoulder.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the weight back down to the starting position.","Repeat for the desired number of repetitions, then switch arms."]},{"id":"242","name":"cable tuck reverse crunch","body_part":"waist","target":"abs","secondary_muscles":["hip flexors"],"equipment":"cable","difficulty":"intermediate","description":"The cable tuck reverse crunch is an abdominal exercise performed with a cable machine. It targets the abs and also works the hip flexors. The movement involves curling the pelvis up and bringing the knees toward the chest while lying on your back, using the resistance of the cable for added intensity.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0242.gif","youtube_id":null,"instructions":["Attach a cable to a low pulley and lie down on a mat facing up.","Hold the cable with both hands and extend your arms straight up above your chest.","Bend your knees and lift your legs up, bringing your knees towards your chest.","At the same time, curl your pelvis up towards your chest, lifting your hips off the ground.","Pause for a moment at the top, then slowly lower your legs and hips back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"2429","name":"frog crunch","body_part":"waist","target":"abs","secondary_muscles":["hip flexors"],"equipment":"body weight","difficulty":"beginner","description":"The frog crunch is a bodyweight abdominal exercise that targets the abs and also engages the hip flexors. It is performed lying on your back, curling your torso up while keeping your feet together and knees bent.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2429.gif","youtube_id":null,"instructions":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"243","name":"cable twist","body_part":"waist","target":"abs","secondary_muscles":["obliques"],"equipment":"cable","difficulty":"intermediate","description":"The cable twist is an exercise targeting the abdominal muscles, particularly the obliques, using a cable machine. It involves twisting the torso against resistance, which helps build core strength and stability.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0243.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, facing the cable machine.","Hold the cable handle with both hands in front of your chest, keeping your arms slightly bent.","Engage your core and twist your torso to the right, pulling the cable across your body.","Pause for a moment at the end of the movement, feeling the contraction in your abs and obliques.","Slowly return to the starting position, resisting the cable's pull.","Repeat the movement to the left side.","Continue alternating sides for the desired number of repetitions."]},{"id":"2432","name":"ez-bar close-grip bench press","body_part":"upper arms","target":"triceps","secondary_muscles":["chest","shoulders"],"equipment":"ez barbell","difficulty":"intermediate","description":"The EZ-bar close-grip bench press is a compound upper body exercise that primarily targets the triceps, with secondary emphasis on the chest and shoulders. It is performed lying on a bench, using a close grip on an EZ barbell to emphasize triceps activation.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2432.gif","youtube_id":null,"instructions":["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Grasp the ez barbell with a close grip, hands shoulder-width apart, palms facing forward.","Lift the barbell off the rack and hold it directly above your chest with your arms fully extended.","Slowly lower the barbell towards your chest, keeping your elbows close to your body.","Pause for a moment when the barbell touches your chest.","Push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]},{"id":"244","name":"cable twisting pull","body_part":"back","target":"lats","secondary_muscles":["shoulders","biceps"],"equipment":"cable","difficulty":"intermediate","description":"The cable twisting pull is an exercise that targets the latissimus dorsi (lats) and incorporates rotational movement, engaging the shoulders and biceps as secondary muscles. It requires a cable machine and involves pulling a handle while rotating the torso, emphasizing both strength and coordination.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0244.gif","youtube_id":null,"instructions":["Attach a cable handle to a low pulley and stand facing the machine.","Grasp the handle with your left hand and step away from the machine, extending your arm fully.","Position your feet shoulder-width apart, with your knees slightly bent.","Keep your back straight and your core engaged throughout the exercise.","Pull the handle towards your body, rotating your torso to the right as you do so.","Squeeze your back muscles at the end of the movement.","Slowly return to the starting position, keeping tension on the cable.","Repeat for the desired number of repetitions, then switch sides and perform with your right hand."]},{"id":"245","name":"cable underhand pulldown","body_part":"back","target":"lats","secondary_muscles":["biceps","forearms"],"equipment":"cable","difficulty":"beginner","description":"The cable underhand pulldown is a strength exercise targeting the latissimus dorsi (lats) with secondary emphasis on the biceps and forearms. It involves pulling a cable bar down towards the chest using an underhand grip, which can help improve back strength and muscle definition.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0245.gif","youtube_id":null,"instructions":["Adjust the cable machine so that the pulldown bar is at a height above your head.","Sit down on the seat and grab the pulldown bar with an underhand grip, hands slightly wider than shoulder-width apart.","Keep your back straight and lean back slightly.","Pull the bar down towards your chest, squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, then slowly release the bar back up to the starting position.","Repeat for the desired number of repetitions."]},{"id":"2459","name":"tire flip","body_part":"upper legs","target":"glutes","secondary_muscles":["hamstrings","quadriceps","core"],"equipment":"tire","difficulty":"advanced","description":"The tire flip is a full-body, explosive strength exercise that primarily targets the glutes, with significant involvement from the hamstrings, quadriceps, and core. It requires lifting and flipping a heavy tire, demanding power, coordination, and proper technique to perform safely.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2459.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, facing the tire.","Bend your knees and hinge at the hips, lowering into a squat position.","Reach down and grab the bottom edge of the tire with both hands, fingers facing towards you.","Engage your glutes and leg muscles, and explosively drive through your legs to lift the tire off the ground.","As the tire flips over, use your upper body strength to guide it and maintain control.","Once the tire is fully flipped, quickly step back and reset your stance.","Repeat for the desired number of repetitions."]},{"id":"246","name":"cable upright row","body_part":"shoulders","target":"delts","secondary_muscles":["traps","biceps"],"equipment":"cable","difficulty":"intermediate","description":"The cable upright row is a strength exercise targeting the deltoids, with secondary emphasis on the traps and biceps. It involves pulling a cable attachment upward towards the chin, leading with the elbows, to engage the shoulder muscles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0246.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, knees slightly bent, and hold the cable attachment with an overhand grip.","Keep your back straight and your core engaged throughout the exercise.","Pull the cable attachment straight up towards your chin, leading with your elbows.","Pause for a moment at the top, squeezing your shoulder blades together.","Slowly lower the cable attachment back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"2462","name":"chest dip on straight bar","body_part":"chest","target":"pectorals","secondary_muscles":["triceps","shoulders"],"equipment":"body weight","difficulty":"advanced","description":"The chest dip on a straight bar is a bodyweight exercise that targets the pectoral muscles, with secondary emphasis on the triceps and shoulders. It requires significant upper body strength, stability, and control.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2462.gif","youtube_id":null,"instructions":["Grab the parallel bars with your palms facing down and your arms fully extended.","Bend your knees and cross your ankles.","Lower your body by bending your arms until your shoulders are below your elbows.","Push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."]},{"id":"2464","name":"cable thibaudeau kayak row","body_part":"back","target":"lats","secondary_muscles":["biceps","rhomboids","rear deltoids"],"equipment":"cable","difficulty":"intermediate","description":"The cable Thibaudeau kayak row is a unilateral rowing exercise that targets the latissimus dorsi using a cable machine. It mimics the motion of a kayak paddle, emphasizing back engagement and unilateral strength.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2464.gif","youtube_id":null,"instructions":["Attach a cable handle to a low pulley and sit facing the machine with your feet flat on the floor.","Grasp the handle with your right hand and extend your arm fully, keeping a slight bend in your elbow.","Lean forward from your hips, keeping your back straight and your abs engaged.","Pull the handle towards your torso by retracting your shoulder blade and bending your elbow, keeping your arm close to your body.","Squeeze your back muscles at the top of the movement, then slowly return to the starting position.","Repeat for the desired number of repetitions, then switch sides and perform with your left arm."]},{"id":"2466","name":"bridge - mountain climber (cross body)","body_part":"waist","target":"abs","secondary_muscles":["glutes","quadriceps","hamstrings","shoulders","triceps"],"equipment":"body weight","difficulty":"intermediate","description":"The bridge - mountain climber (cross body) is a dynamic bodyweight exercise that targets the abs while also engaging the glutes, quadriceps, hamstrings, shoulders, and triceps. It combines core stabilization with a cross-body knee drive, challenging both strength and coordination.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2466.gif","youtube_id":null,"instructions":["Start in a high plank position with your hands directly under your shoulders and your body in a straight line.","Engage your core and lift your right foot off the ground, bringing your right knee towards your left elbow.","Return your right foot to the starting position and repeat the movement with your left foot towards your right elbow.","Continue alternating sides, moving at a controlled pace.","Keep your hips level and avoid lifting your hips too high or sagging them too low.","Maintain a steady breathing pattern throughout the exercise.","Repeat for the desired number of repetitions."]},{"id":"247","name":"cable wrist curl","body_part":"lower arms","target":"forearms","secondary_muscles":["biceps","brachialis"],"equipment":"cable","difficulty":"beginner","description":"The cable wrist curl is an isolation exercise targeting the forearm muscles, particularly the wrist flexors. It is performed using a cable machine and a straight bar, focusing on curling the wrists upward while keeping the forearms stationary.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0247.gif","youtube_id":null,"instructions":["Attach a straight bar to a low pulley cable machine.","Stand facing the machine with your feet shoulder-width apart.","Grasp the bar with an underhand grip, palms facing up, and your hands shoulder-width apart.","Rest your forearms on a bench or pad, with your wrists hanging off the edge.","Keeping your forearms stationary, exhale and curl your wrists upward as far as possible.","Pause for a moment at the top, then inhale and slowly lower the bar back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"2470","name":"dumbbell lying on floor rear delt raise","body_part":"shoulders","target":"delts","secondary_muscles":["trapezius","rhomboids"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell lying on floor rear delt raise is an isolation exercise targeting the rear deltoids. It is performed lying face down on the floor, lifting dumbbells out to the sides to engage the rear shoulders and upper back.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2470.gif","youtube_id":null,"instructions":["Lie face down on the floor with a dumbbell in each hand, palms facing each other.","Extend your arms straight out in front of you, keeping a slight bend in your elbows.","Engaging your shoulder muscles, lift your arms up and out to the sides, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"248","name":"cambered bar lying row","body_part":"back","target":"upper back","secondary_muscles":["biceps","forearms"],"equipment":"barbell","difficulty":"intermediate","description":"The cambered bar lying row is a strength exercise targeting the upper back. It is performed by lying face down on a bench and pulling a barbell towards the chest, emphasizing scapular retraction and upper back engagement.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0248.gif","youtube_id":null,"instructions":["Set up a barbell on the floor and lie face down on a bench with your chest just off the edge.","Reach down and grab the barbell with an overhand grip, slightly wider than shoulder-width apart.","With your legs straight and feet on the ground, lift the barbell off the floor by extending your arms.","Pull the barbell towards your chest, squeezing your shoulder blades together.","Lower the barbell back down to the starting position and repeat for the desired number of repetitions."]},{"id":"25","name":"barbell bench press","body_part":"chest","target":"pectorals","secondary_muscles":["triceps","shoulders"],"equipment":"barbell","difficulty":"intermediate","description":"The barbell bench press is a classic compound exercise that primarily targets the pectoral muscles, while also engaging the triceps and shoulders. It is performed by lying on a bench and pressing a barbell up and down in a controlled manner.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0025.gif","youtube_id":null,"instructions":["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Grasp the barbell with an overhand grip slightly wider than shoulder-width apart.","Lift the barbell off the rack and hold it directly above your chest with your arms fully extended.","Lower the barbell slowly towards your chest, keeping your elbows tucked in.","Pause for a moment when the barbell touches your chest.","Push the barbell back up to the starting position by extending your arms.","Repeat for the desired number of repetitions."]},{"id":"251","name":"chest dip","body_part":"chest","target":"pectorals","secondary_muscles":["triceps","shoulders"],"equipment":"body weight","difficulty":"advanced","description":"The chest dip is a bodyweight exercise performed on parallel bars that primarily targets the pectoral muscles, with secondary emphasis on the triceps and shoulders. It requires significant upper body strength, stability, and control.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0251.gif","youtube_id":null,"instructions":["Position yourself on parallel bars with your arms fully extended and your body straight.","Lower your body by bending your elbows until your shoulders are below your elbows.","Push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."]},{"id":"253","name":"chin-ups (narrow parallel grip)","body_part":"back","target":"upper back","secondary_muscles":["biceps","forearms"],"equipment":"body weight","difficulty":"intermediate","description":"Chin-ups (narrow parallel grip) are a bodyweight exercise targeting the upper back, with significant involvement of the biceps and forearms. The movement requires pulling the body up to a bar using a narrow, parallel grip, emphasizing upper back and arm strength.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0253.gif","youtube_id":null,"instructions":["Hang from a pull-up bar with a narrow parallel grip, palms facing towards you.","Engage your back muscles and pull your body up towards the bar, keeping your elbows close to your body.","Continue pulling until your chin is above the bar.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"2567","name":"seated piriformis stretch","body_part":"upper legs","target":"glutes","secondary_muscles":["hamstrings"],"equipment":"body weight","difficulty":"beginner","description":"The seated piriformis stretch targets the glutes and helps improve flexibility and relieve tension in the piriformis muscle. It is performed seated on the ground, crossing one leg over the other and gently twisting the torso to stretch the gluteal region.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2567.gif","youtube_id":null,"instructions":["Sit on the ground with your legs extended in front of you.","Bend your right knee and place your right foot on the outside of your left knee.","Place your left elbow on the outside of your right knee and gently twist your torso to the right.","Hold the stretch for 20-30 seconds, then switch sides and repeat."]},{"id":"257","name":"circles knee stretch","body_part":"lower legs","target":"calves","secondary_muscles":["hamstrings","quadriceps"],"equipment":"body weight","difficulty":"beginner","description":"The circles knee stretch is a bodyweight exercise that targets the calves and also engages the hamstrings and quadriceps. It involves standing on the balls of your feet with knees bent and rotating the knees in circular motions to improve mobility and flexibility in the lower legs.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0257.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and your hands on your hips.","Bend your knees slightly and lift your heels off the ground, balancing on the balls of your feet.","Keeping your knees bent, rotate your knees in a circular motion, first clockwise and then counterclockwise.","Perform the movement for the desired number of repetitions."]},{"id":"2571","name":"rocking frog stretch","body_part":"upper legs","target":"glutes","secondary_muscles":["hamstrings","quadriceps"],"equipment":"body weight","difficulty":"beginner","description":"The rocking frog stretch is a bodyweight exercise that targets the glutes and also stretches the hamstrings and quadriceps. It involves kneeling, leaning forward, and rocking the hips back to stretch the lower body muscles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2571.gif","youtube_id":null,"instructions":["Start by kneeling on the ground with your knees hip-width apart.","Place your hands on the ground in front of you for support.","Slowly lean forward, shifting your weight onto your hands and extending your legs behind you.","Keep your back straight and engage your glutes as you push your hips back and up towards the ceiling.","Hold this position for a few seconds, feeling a stretch in your glutes.","Slowly return to the starting position by bending your knees and lowering your hips back down.","Repeat for the desired number of repetitions."]},{"id":"2572","name":"roll overs into v sits","body_part":"waist","target":"abs","secondary_muscles":["quads","adductors","glutes","hamstrings"],"equipment":"body weight","difficulty":"advanced","description":"From a supine position, roll your legs overhead into a controlled rollover, then reverse to balance in a V-sit on your sit bones. Use your core to drive the motion and avoid loading the neck.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2572.gif","youtube_id":null,"instructions":["Lie on your back with legs straight together and arms overhead; brace your core and press your lower back gently into the floor.","Lift legs to 90°, posteriorly tilt the pelvis, and articulate the spine off the floor to roll the legs overhead, keeping weight on upper back/shoulders and the neck relaxed.","Stop where you can control the position without cervical pressure, legs long and together.","Sweep the arms forward and begin a controlled reverse roll, segmenting the spine back down as you unfold the legs.","Hinge at the hips to sit up and balance on your sit bones in a V-sit, torso and legs about 45–60 degrees, arms reaching toward toes, chest lifted.","Pause briefly with abs braced, then tuck the pelvis and round the spine to roll back with control.","Exhale as you rise to the V-sit; inhale as you roll back. Move smoothly and do not let the heels slam to the floor."]},{"id":"258","name":"clock push-up","body_part":"chest","target":"pectorals","secondary_muscles":["triceps","shoulders","core"],"equipment":"body weight","difficulty":"advanced","description":"The clock push-up is a dynamic bodyweight exercise that targets the chest, triceps, shoulders, and core. It involves a rotational movement where one arm extends out to the side as you lower into a push-up, increasing the challenge to stability and coordination.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0258.gif","youtube_id":null,"instructions":["Start in a high plank position with your hands directly under your shoulders and your body in a straight line.","Lower your body towards the ground by bending your elbows, keeping them close to your sides.","As you lower, rotate your body to the left, extending your left arm straight out to the side.","Push back up to the starting position, while rotating your body to the center.","Repeat the push-up, this time rotating your body to the right and extending your right arm out to the side.","Continue alternating sides with each repetition."]},{"id":"259","name":"close-grip push-up","body_part":"upper arms","target":"triceps","secondary_muscles":["chest","shoulders"],"equipment":"body weight","difficulty":"intermediate","description":"The close-grip push-up is a bodyweight exercise that primarily targets the triceps, with secondary emphasis on the chest and shoulders. It is performed by placing the hands close together under the shoulders and performing a push-up while keeping the elbows close to the body.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0259.gif","youtube_id":null,"instructions":["Start in a high plank position with your hands placed close together, directly under your shoulders.","Engage your core and lower your body towards the ground, keeping your elbows close to your sides.","Push through your palms to extend your arms and return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"26","name":"barbell bench squat","body_part":"upper legs","target":"quads","secondary_muscles":["glutes","hamstrings","calves"],"equipment":"barbell","difficulty":"intermediate","description":"The barbell bench squat is a compound lower body exercise that primarily targets the quadriceps, while also engaging the glutes, hamstrings, and calves. It involves squatting with a barbell, requiring good technique and strength.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0026.gif","youtube_id":null,"instructions":["Set up a barbell on a squat rack at chest height.","Stand facing away from the rack, with your feet shoulder-width apart.","Bend your knees and lower your body down into a squat position, keeping your back straight and chest up.","Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.","Lift the barbell off the rack and step back, ensuring your feet are still shoulder-width apart.","Lower your body down into a squat, keeping your knees in line with your toes.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"260","name":"cocoons","body_part":"waist","target":"abs","secondary_muscles":["hip flexors","lower back"],"equipment":"body weight","difficulty":"beginner","description":"Cocoons are a bodyweight abdominal exercise that targets the abs, with secondary emphasis on the hip flexors and lower back. The movement involves curling the upper body off the ground to a 45-degree angle, engaging the core throughout.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0260.gif","youtube_id":null,"instructions":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"2611","name":"lever horizontal one leg press","body_part":"upper legs","target":"glutes","secondary_muscles":["quadriceps","hamstrings","calves"],"equipment":"leverage machine","difficulty":"intermediate","description":"The lever horizontal one leg press is a lower body strength exercise performed on a leverage machine. It primarily targets the glutes, with secondary emphasis on the quadriceps, hamstrings, and calves. The exercise involves pressing a footplate away from the body using one leg at a time, which increases the demand for unilateral strength and stability.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2611.gif","youtube_id":null,"instructions":["Adjust the seat of the machine so that your knees are at a 90-degree angle when your feet are on the footplate.","Sit on the machine with your back against the backrest and your feet shoulder-width apart on the footplate.","Place your hands on the handles or sides of the machine for stability.","Push the footplate away from your body by extending your leg, keeping your back against the backrest.","Pause for a moment at the fully extended position, then slowly bend your leg to return to the starting position.","Repeat for the desired number of repetitions, then switch legs."]},{"id":"2612","name":"jump rope","body_part":"cardio","target":"cardiovascular system","secondary_muscles":["calves","quadriceps","hamstrings","glutes"],"equipment":"rope","difficulty":"beginner","description":"Jump rope is a cardiovascular exercise that involves continuously jumping over a swinging rope. It primarily targets the cardiovascular system while also engaging the calves, quadriceps, hamstrings, and glutes.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2612.gif","youtube_id":null,"instructions":["Hold the handles of the jump rope with your hands, palms facing inward.","Stand with your feet shoulder-width apart and knees slightly bent.","Swing the rope over your head and jump over it as it comes towards your feet.","Land softly on the balls of your feet and repeat the jump as the rope comes around again.","Continue jumping for the desired duration or number of repetitions."]},{"id":"2616","name":"cable lateral pulldown with v-bar","body_part":"back","target":"lats","secondary_muscles":["biceps","forearms"],"equipment":"cable","difficulty":"beginner","description":"The cable lateral pulldown with v-bar is a strength exercise targeting the latissimus dorsi (lats) using a cable machine and v-bar attachment. It also engages the biceps and forearms as secondary muscles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2616.gif","youtube_id":null,"instructions":["Sit down on the cable pulldown machine and grab the v-bar attachment with an overhand grip.","Adjust the knee pad so that your thighs are secured under it.","Keep your back straight and lean back slightly.","Pull the v-bar down towards your upper chest while keeping your elbows close to your body.","Squeeze your back muscles at the bottom of the movement.","Slowly return the v-bar to the starting position and repeat for the desired number of repetitions."]},{"id":"262","name":"cross body crunch","body_part":"waist","target":"abs","secondary_muscles":["obliques"],"equipment":"body weight","difficulty":"beginner","description":"The cross body crunch is a bodyweight abdominal exercise that targets the abs and obliques. It involves twisting the torso to bring an elbow towards the opposite knee, engaging the core muscles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0262.gif","youtube_id":null,"instructions":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, lift your upper body off the ground and twist to bring your right elbow towards your left knee.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat on the other side, bringing your left elbow towards your right knee.","Repeat for the desired number of repetitions."]},{"id":"267","name":"crunch (hands overhead)","body_part":"waist","target":"abs","secondary_muscles":["hip flexors"],"equipment":"body weight","difficulty":"intermediate","description":"A crunch variation where the hands are extended overhead, increasing the challenge to the abdominal muscles and requiring greater core engagement.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0267.gif","youtube_id":null,"instructions":["Lie flat on your back with your knees bent and feet flat on the ground.","Extend your arms straight above your head.","Engaging your abs, lift your upper body off the ground, curling forward towards your knees.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"27","name":"barbell bent over row","body_part":"back","target":"upper back","secondary_muscles":["biceps","forearms"],"equipment":"barbell","difficulty":"intermediate","description":"The barbell bent over row is a compound exercise targeting the upper back, requiring the lifter to hinge at the hips and pull a barbell towards the torso. It develops strength and muscle mass in the upper back, biceps, and forearms, and demands good posture and core stability.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0027.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and knees slightly bent.","Bend forward at the hips while keeping your back straight and chest up.","Grasp the barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Pull the barbell towards your lower chest by retracting your shoulder blades and squeezing your back muscles.","Pause for a moment at the top, then slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"2705","name":"dumbbell lying pronation on floor","body_part":"lower arms","target":"forearms","secondary_muscles":["biceps","triceps"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell lying pronation on floor targets the forearms by requiring you to rotate your palms downward while lifting dumbbells, emphasizing forearm strength and stability.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2705.gif","youtube_id":null,"instructions":["Lie flat on the floor with your face down and your arms extended straight out in front of you, holding a dumbbell in each hand.","Rotate your palms so they are facing down towards the floor.","Keeping your arms straight, lift the dumbbells off the floor by contracting your forearms.","Continue lifting until your forearms are fully contracted and the dumbbells are at shoulder level.","Hold for a moment, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"2706","name":"dumbbell lying supination on floor","body_part":"lower arms","target":"forearms","secondary_muscles":["biceps","shoulders"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell lying supination on floor is an isolation exercise targeting the forearms, with secondary engagement of the biceps and shoulders. It involves lying on your back and performing a supination curl motion with dumbbells.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2706.gif","youtube_id":null,"instructions":["Lie flat on your back on the floor with your legs extended and your arms by your sides, holding a dumbbell in each hand.","Rotate your palms to face up, keeping your elbows close to your sides.","Slowly curl the dumbbells towards your shoulders, squeezing your forearms.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"271","name":"crunch (on stability ball)","body_part":"waist","target":"abs","secondary_muscles":["hip flexors"],"equipment":"stability ball","difficulty":"intermediate","description":"The crunch on a stability ball is an abdominal exercise that targets the abs while also engaging the hip flexors. The use of a stability ball increases the challenge to balance and core stability compared to a regular floor crunch.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0271.gif","youtube_id":null,"instructions":["Sit on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Lie back on the ball until your lower back is supported and your upper body is parallel to the floor.","Place your hands behind your head or across your chest.","Engage your abs and lift your upper body towards your knees, curling your torso forward.","Pause for a moment at the top of the movement, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"272","name":"crunch (on stability ball, arms straight)","body_part":"waist","target":"abs","secondary_muscles":["hip flexors"],"equipment":"stability ball","difficulty":"intermediate","description":"The crunch on a stability ball with arms straight is an abdominal exercise that targets the abs while also engaging the hip flexors. The use of a stability ball increases the challenge to balance and core stability.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0272.gif","youtube_id":null,"instructions":["Sit on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Lie back on the ball until your lower back is supported and your upper body is parallel to the floor.","Place your hands behind your head or cross them over your chest.","Engage your abs and lift your upper body off the ball, curling your shoulders towards your hips.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"2736","name":"lever reverse grip lateral pulldown","body_part":"back","target":"lats","secondary_muscles":["biceps","rhomboids","rear deltoids"],"equipment":"leverage machine","difficulty":"beginner","description":"The lever reverse grip lateral pulldown is a machine-based exercise targeting the latissimus dorsi (lats) with a reverse (underhand) grip, also engaging the biceps, rhomboids, and rear deltoids. It is performed on a leverage machine, making it accessible and safe for most users.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2736.gif","youtube_id":null,"instructions":["Adjust the seat height and position yourself on the machine with your knees under the pads and your feet flat on the ground.","Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.","Sit upright with your chest out and shoulders back, maintaining a slight arch in your lower back.","Pull the handles down towards your chest, leading with your elbows and squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, then slowly release the handles back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"274","name":"crunch floor","body_part":"waist","target":"abs","secondary_muscles":["hip flexors"],"equipment":"body weight","difficulty":"beginner","description":"The crunch floor is a classic abdominal exercise performed lying on your back, focusing on strengthening the abs with minimal equipment.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0274.gif","youtube_id":null,"instructions":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engage your abs and lift your shoulders off the ground, curling forward towards your knees.","Pause for a moment at the top, then slowly lower your shoulders back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"2741","name":"ez-barbell standing wide grip biceps curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"ez barbell","difficulty":"beginner","description":"The EZ-barbell standing wide grip biceps curl is a strength exercise targeting the biceps, with secondary emphasis on the forearms. It involves curling an EZ barbell with a wide grip while standing.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2741.gif","youtube_id":null,"instructions":["Stand up straight with your feet shoulder-width apart and hold the ez barbell with an underhand grip, hands wider than shoulder-width apart.","Keep your elbows close to your torso and your upper arms stationary throughout the movement.","Curl the barbell up towards your shoulders by contracting your biceps.","Pause for a moment at the top, then slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"276","name":"dead bug","body_part":"waist","target":"abs","secondary_muscles":["hip flexors","lower back"],"equipment":"body weight","difficulty":"beginner","description":"The dead bug is a core stability exercise that targets the abdominal muscles while also engaging the hip flexors and lower back. It is performed lying on your back, alternating arm and leg movements while maintaining a stable core.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0276.gif","youtube_id":null,"instructions":["Lie flat on your back with your arms extended towards the ceiling.","Bend your knees and lift your legs off the ground, creating a 90-degree angle at your hips and knees.","Engage your core and lower back to press your lower back into the ground.","Slowly lower your right arm and left leg towards the ground, keeping them straight and hovering just above the floor.","Pause for a moment, then return to the starting position.","Repeat the movement with your left arm and right leg.","Continue alternating sides for the desired number of repetitions."]},{"id":"2761","name":"ankle dorsal flexion","body_part":"lower legs","target":"calves","secondary_muscles":["extensor digitorum longus","extensor hallucis longus","peroneus tertius"],"equipment":"body weight","difficulty":"beginner","description":"Stand upright with feet hip-width, heels on the floor. Lift the forefeet by pulling the toes toward your shins, then lower under control.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2761.gif","youtube_id":null,"instructions":["Stand tall with feet hip-width apart; lightly hold a wall or chair for balance if needed.","Keep knees soft, torso upright, and weight centered over your heels.","Actively pull your toes up toward your shins (ankle dorsiflexion) without lifting the heels.","Pause briefly at end range while keeping ankles aligned and not turning the feet out/in.","Lower the forefeet slowly to the floor; avoid letting them drop or slapping the ground.","Repeat for controlled reps, staying within a pain-free range and even between sides."]},{"id":"277","name":"decline crunch","body_part":"waist","target":"abs","secondary_muscles":["hip flexors"],"equipment":"body weight","difficulty":"intermediate","description":"The decline crunch is an abdominal exercise performed on a decline bench, targeting the abs and engaging the hip flexors as secondary muscles. It involves curling the torso upward while lying on a downward-sloping surface.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0277.gif","youtube_id":null,"instructions":["Lie on a decline bench with your feet secured and your knees bent at a 90-degree angle.","Place your hands behind your head or across your chest.","Engage your abs and lift your upper body towards your knees, curling your torso.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"279","name":"decline push-up","body_part":"chest","target":"pectorals","secondary_muscles":["triceps","shoulders"],"equipment":"body weight","difficulty":"intermediate","description":"The decline push-up is a bodyweight exercise that targets the pectoral muscles by elevating the feet, increasing the difficulty compared to a standard push-up. It also engages the triceps and shoulders as secondary muscles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0279.gif","youtube_id":null,"instructions":["Place your hands on the ground slightly wider than shoulder-width apart, with your feet elevated on a stable surface.","Keep your body in a straight line from head to toe, engaging your core muscles.","Lower your chest towards the ground by bending your elbows, keeping them close to your body.","Push through your palms to extend your arms and return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"2795","name":"dumbbell step up lunge","body_part":"upper legs","target":"quads","secondary_muscles":["glutes","hamstrings","adductors","calves","abs"],"equipment":"dumbbell","difficulty":"advanced","description":"Hold dumbbells at your sides and set up in a long split stance with the front foot on a bench and the rear foot elevated on a bench behind you. Lower straight down until the front foot lightly taps the floor, then drive through the front heel to step back up onto the front bench.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2795.gif","youtube_id":null,"instructions":["Place two sturdy benches about a stride apart; hold dumbbells at your sides, chest up, core braced.","Put your front foot flat on the front bench and the top of your rear foot on the rear bench; hips square, eyes forward.","Inhale and descend straight down by bending both knees, keeping the front knee tracking over the middle toes and heel grounded.","Lower until the front foot lightly touches the floor (or front thigh is at least parallel), torso tall and neutral spine.","Exhale and drive through the front heel and mid‑foot to extend the knee and hip, returning to the start atop the benches.","Minimize push from the rear leg; keep dumbbells still and shoulders down.","Pause, re-balance, and complete all reps before switching legs."]},{"id":"2796","name":"dumbbell step-up lunge","body_part":"upper legs","target":"quads","secondary_muscles":["glutes","hamstrings","calves"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell step-up lunge is a compound lower body exercise that targets the quadriceps while also engaging the glutes, hamstrings, and calves. It involves stepping onto a raised platform while holding dumbbells, requiring balance, coordination, and lower body strength.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2796.gif","youtube_id":null,"instructions":["Stand in front of a step or platform with a dumbbell in each hand, palms facing your sides.","Place your right foot on the step, ensuring your entire foot is on the surface.","Push through your right heel and lift your body up onto the step, bringing your left foot up as well.","Once both feet are on the step, lower your left foot back down to the starting position, keeping your right foot on the step.","Repeat the movement, alternating which foot you step up with each time.","Continue for the desired number of repetitions."]},{"id":"2797","name":"barbell squat jump step rear lunge","body_part":"upper legs","target":"quads","secondary_muscles":["glutes","hamstrings","calves","abs","adductors"],"equipment":"barbell","difficulty":"advanced","description":"Set a barbell on your upper back and stand facing a low, stable step. Perform a squat jump to land on the step, then step back into a rear lunge before returning to the start.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2797.gif","youtube_id":null,"instructions":["Rack the barbell across your upper traps with a shoulder-width grip; stand 15–30 cm in front of a sturdy step, feet hip-width and toes slightly out.","Brace your core, set a neutral spine, and sit into a quarter–half squat.","Drive through your feet and jump onto the step, landing softly on both feet with knees tracking over toes and heels down.","Stand tall on the step, then step one foot back to the floor and lower into a controlled rear lunge (front shin vertical, back knee under hip).","Push through the front heel to return to standing on the floor at the start position.","Repeat the jump and alternate the lunge leg each rep while keeping the torso upright and the bar stable.","Use a low step and light load; stop the set if landing control or balance is lost."]},{"id":"2798","name":"barbell squat jump step rear lunge","body_part":"upper legs","target":"quads","secondary_muscles":["glutes","hamstrings","calves"],"equipment":"barbell","difficulty":"advanced","description":"The barbell squat jump step rear lunge is a dynamic lower body exercise that combines a squat jump with a reverse lunge, performed while holding a barbell across the upper back. This movement targets the quadriceps, glutes, hamstrings, and calves, and requires strength, coordination, and balance.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2798.gif","youtube_id":null,"instructions":["Start by standing with your feet shoulder-width apart, holding a barbell across your upper back.","Lower your body into a squat position by bending your knees and pushing your hips back.","Explode upwards, jumping off the ground as high as you can.","Land softly on your feet and immediately step back with one leg into a reverse lunge.","Lower your body down until your front thigh is parallel to the ground, keeping your back straight.","Push through your front heel to return to the starting position.","Repeat the jump and lunge sequence on the other leg.","Continue alternating legs for the desired number of repetitions."]},{"id":"2799","name":"barbell sitted alternate leg raise","body_part":"waist","target":"abs","secondary_muscles":["hip flexors"],"equipment":"barbell","difficulty":"intermediate","description":"The barbell sitted alternate leg raise is an exercise targeting the abdominal muscles and hip flexors. Performed while seated on a bench with a barbell across the thighs, it involves alternately raising each leg while keeping the back straight.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2799.gif","youtube_id":null,"instructions":["Sit on a bench with your back straight and hold a barbell across your thighs.","Keeping your legs straight, lift one leg up as high as possible while keeping the other leg on the ground.","Lower the raised leg back down and repeat with the other leg.","Continue alternating legs for the desired number of repetitions."]},{"id":"28","name":"barbell clean and press","body_part":"upper legs","target":"quads","secondary_muscles":["hamstrings","glutes","shoulders","triceps"],"equipment":"barbell","difficulty":"advanced","description":"The barbell clean and press is a compound exercise that targets the quads and involves lifting a barbell from the floor to the shoulders (clean) and then pressing it overhead (press). It requires strength, coordination, and explosive power.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0028.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and the barbell on the floor in front of you.","Bend your knees and hinge at the hips to lower down and grip the barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Drive through your heels and extend your hips and knees to lift the barbell off the floor, keeping it close to your body.","As the barbell reaches your thighs, explosively extend your hips, shrug your shoulders, and pull the barbell up towards your chest.","As the barbell reaches chest height, quickly drop under it and catch it at shoulder level, with your elbows pointing forward and your palms facing up.","From the catch position, press the barbell overhead by extending your arms and pushing the barbell straight up.","Lower the barbell back down to the starting position and repeat for the desired number of repetitions."]},{"id":"2800","name":"barbell sitted alternate leg raise (female)","body_part":"waist","target":"abs","secondary_muscles":["hip flexors","quadriceps"],"equipment":"barbell","difficulty":"intermediate","description":"The barbell sitted alternate leg raise (female) targets the abdominal muscles while also engaging the hip flexors and quadriceps. The exercise is performed seated on a bench, holding a barbell across the thighs, and alternately raising each leg while keeping it straight.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2800.gif","youtube_id":null,"instructions":["Sit on a bench with your back straight and hold a barbell across your thighs.","Place your hands on the sides of the bench for support.","Keeping your legs straight, lift one leg up as high as possible while keeping it parallel to the ground.","Lower the leg back down and repeat with the other leg.","Continue alternating legs for the desired number of repetitions."]},{"id":"2801","name":"twisted leg raise (female)","body_part":"waist","target":"abs","secondary_muscles":["obliques","hip flexors"],"equipment":"body weight","difficulty":"intermediate","description":"The twisted leg raise (female) is an abdominal exercise that targets the abs, obliques, and hip flexors. It involves lying on your back, lifting your legs, and twisting your hips to engage the core muscles more dynamically.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2801.gif","youtube_id":null,"instructions":["Lie flat on your back with your legs extended and your arms by your sides.","Bend your knees and lift your legs off the ground, bringing them towards your chest.","As you lift your legs, twist your hips to one side, bringing your knees towards your opposite shoulder.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat the movement, this time twisting your hips to the other side.","Continue alternating sides for the desired number of repetitions."]},{"id":"2802","name":"twisted leg raise","body_part":"waist","target":"abs","secondary_muscles":["obliques","hip flexors"],"equipment":"body weight","difficulty":"intermediate","description":"The twisted leg raise is a bodyweight exercise targeting the abdominal muscles, with an emphasis on the obliques and hip flexors. It involves lifting the legs while twisting the hips to engage the core from different angles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2802.gif","youtube_id":null,"instructions":["Lie flat on your back with your legs extended and your arms by your sides.","Place your hands under your glutes for support.","Engage your abs and lift both legs off the ground, keeping them straight.","As you lift your legs, twist your hips to one side, bringing your legs towards your opposite shoulder.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat the movement, this time twisting your hips to the other side.","Continue alternating sides for the desired number of repetitions."]},{"id":"2803","name":"dumbbell supported squat","body_part":"upper legs","target":"quads","secondary_muscles":["glutes","hamstrings","calves"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell supported squat is a lower body exercise targeting the quadriceps, with additional activation of the glutes, hamstrings, and calves. It involves holding dumbbells at your sides while performing a squat, enhancing strength and stability.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2803.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand at your sides.","Keeping your chest up and core engaged, slowly lower your body down by bending your knees and pushing your hips back.","Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"2804","name":"dumbbell supported squat","body_part":"upper legs","target":"quads","secondary_muscles":["glutes","hamstrings","calves","abs"],"equipment":"leverage machine","difficulty":"intermediate","description":"Set up in a sissy-squat/support bench with ankles secured and calves against the pad, holding one or two dumbbells at the chest. Squat by flexing the knees while keeping the torso upright, then drive through the feet to return to standing.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2804.gif","youtube_id":null,"instructions":["Adjust the support so your ankles are snug under the roller and your calves contact the rear pad; stand tall with feet hip-width and toes forward on the platform.","Hold a dumbbell vertically at your chest (goblet) or two dumbbells at your shoulders; brace your core and keep a neutral spine.","Inhale and initiate the descent by bending your knees forward, allowing them to track over your second–third toes while keeping hips relatively extended and torso upright.","Keep heels down and shins guided by the support; do not let the lower back round or knees cave inward.","Lower under control until thighs reach parallel or your comfortable depth without losing foot pressure or spinal position.","Drive through the mid-foot to extend the knees and return to standing, exhaling as you pass the sticking point.","Pause briefly, reset your brace, and repeat for the target reps with smooth, controlled tempo."]},{"id":"2805","name":"dumbbell single leg deadlift with stepbox support","body_part":"upper legs","target":"glutes","secondary_muscles":["hamstrings","lower back"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell single leg deadlift with stepbox support is a unilateral lower body exercise that targets the glutes, with secondary emphasis on the hamstrings and lower back. It challenges balance, stability, and strength, making it suitable for those with some experience in weight training.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2805.gif","youtube_id":null,"instructions":["Stand with your feet hip-width apart, holding a dumbbell in your right hand.","Place your left foot on a stepbox or elevated surface behind you.","Keeping your back straight and core engaged, hinge forward at the hips, lowering the dumbbell towards the ground.","As you lower the dumbbell, simultaneously lift your left leg behind you, maintaining a straight line from head to heel.","Lower the dumbbell until you feel a stretch in your right hamstring, then return to the starting position.","Repeat for the desired number of repetitions, then switch sides."]},{"id":"2806","name":"dumbbell single leg deadlift with stepbox support","body_part":"upper legs","target":"hamstrings","secondary_muscles":["glutes","spine","calves","forearms","abs"],"equipment":"dumbbell","difficulty":"intermediate","description":"Stand on one leg with the other foot lightly supported on a low step/box behind you. Hold a dumbbell in the same-side hand and perform a controlled hip hinge to load the hamstrings, then return to stand tall.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2806.gif","youtube_id":null,"instructions":["Place a low step/box 30–45 cm behind you and lightly rest the toes of the non-working foot on it; stand tall on the working leg holding a dumbbell in the same-side hand, arm straight.","Set the working foot under the hip, keep a soft knee (10–20° bend), brace your core, and keep hips and shoulders square.","Hinge at the hips by pushing them back, keeping the dumbbell close to your shin and the working knee angle nearly constant.","Maintain a neutral spine from head to pelvis; lower until you feel a firm hamstring stretch or your torso nears parallel without rounding.","Keep 80–90% of your weight on the working leg; the rear foot is for balance only, not to push from.","Drive through the working heel, extend the hip, and return to stand without hyperextending the lower back.","Reset your brace and repeat for reps, then switch sides."]},{"id":"2807","name":"dumbbell sumo pull through","body_part":"upper legs","target":"glutes","secondary_muscles":["hamstrings","adductors","spine","quads"],"equipment":"dumbbell","difficulty":"beginner","description":"Stand in a wide sumo stance holding a dumbbell with both hands between the legs. Hinge the hips to let the weight pass back between the thighs, then drive the hips forward to stand tall, pulling the dumbbell through without using the arms.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2807.gif","youtube_id":null,"instructions":["Set feet wider than shoulder width with toes turned out 30–45°, grip one head of the dumbbell with both hands, arms straight and hanging between the legs.","Brace the core, keep a neutral spine, and push the hips back while bending the knees slightly; let the dumbbell travel between the thighs.","Keep shins near vertical, knees tracking over toes, shoulders packed, and weight through mid‑foot to heels.","At the end of the hinge, pause with the torso angled forward without rounding the back.","Drive the feet into the floor and snap the hips forward, squeezing the glutes to stand tall; let the arms stay straight as the dumbbell is pulled forward by hip extension.","Finish with hips and knees fully extended, ribs down, and no low‑back hyperextension.","Repeat by hinging again, guiding the dumbbell back between the legs under control; maintain a smooth tempo and neutral neck throughout."]},{"id":"2808","name":"dumbbell sumo pull through","body_part":"upper legs","target":"glutes","secondary_muscles":["hamstrings","quadriceps","core"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell sumo pull through is a lower body exercise that targets the glutes, with secondary emphasis on the hamstrings, quadriceps, and core. It involves a wide-stance squat and a hip hinge movement, using a dumbbell for resistance.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2808.gif","youtube_id":null,"instructions":["Stand with your feet wider than shoulder-width apart, toes pointed outwards.","Hold a dumbbell with both hands in front of your body, arms extended.","Bend your knees and lower your hips down into a squat position, keeping your back straight.","Lower the dumbbell down between your legs, keeping your arms straight.","Drive through your heels and extend your hips forward, pulling the dumbbell up and in front of your body.","Squeeze your glutes at the top of the movement, then lower the dumbbell back down between your legs.","Repeat for the desired number of repetitions."]},{"id":"2809","name":"barbell split squat (version 2)","body_part":"upper legs","target":"quads","secondary_muscles":["glutes","hamstrings","adductors","calves","abs"],"equipment":"barbell","difficulty":"intermediate","description":"Hold a barbell with both hands at arm’s length in front of your hips and set up in a split stance. Lower straight down into a split squat and drive through the front foot to stand, keeping the bar close and level.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2809.gif","youtube_id":null,"instructions":["Stand tall holding a barbell with an overhand grip just outside your thighs; feet hip-width apart.","Step one foot forward into a long split stance (front foot flat, back heel lifted, toes pointing forward).","Brace your abs, keep your chest up, hips square, and the bar close to your thighs.","Lower straight down by bending both knees; keep the torso tall and the front knee tracking over the middle toes.","Descend until the front thigh is near parallel and the back knee hovers just above the floor; keep weight through the front mid-foot/heel.","Press through the front foot and the ball of the back foot to return to standing without locking the knees.","Keep the bar level and close to the body; avoid letting the front knee cave inward or the heel lift.","Complete all reps on one side, then switch legs and repeat."]},{"id":"2810","name":"barbell split squat v. 2","body_part":"upper legs","target":"quads","secondary_muscles":["glutes","hamstrings","calves"],"equipment":"barbell","difficulty":"intermediate","description":"The barbell split squat v. 2 is a lower body strength exercise that targets the quadriceps, while also engaging the glutes, hamstrings, and calves. It involves stepping forward into a split stance and lowering the body with a barbell across the upper back.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2810.gif","youtube_id":null,"instructions":["Start by standing with your feet shoulder-width apart, holding a barbell across your upper back.","Take a large step forward with your right foot, keeping your torso upright.","Lower your body by bending your knees and hips until your right thigh is parallel to the ground.","Pause for a moment, then push through your right heel to return to the starting position.","Repeat with your left leg forward for the desired number of repetitions."]},{"id":"2811","name":"barbell leg twist press","body_part":"waist","target":"abs","secondary_muscles":["delts","triceps","pectorals","serratus anterior","glutes"],"equipment":"barbell","difficulty":"intermediate","description":"Lie on your back holding a barbell locked out over your chest while rotating bent legs side‑to‑side. This combines a static press with controlled leg twists to train the abs and challenge shoulder stability.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2811.gif","youtube_id":null,"instructions":["Lie supine on the floor, grip the barbell slightly wider than shoulder width, and press to full lockout over the mid‑chest with shoulders set down and back.","Brace your core, press your low back gently into the floor, and lift your legs so hips and knees are at about 90 degrees with feet together.","Keep the bar stacked over your shoulders and elbows locked as you slowly rotate both legs together to the right until your thighs approach the floor without lifting your shoulders or low back.","Pull the legs back to center using your abs, then rotate to the left the same distance.","Maintain a slow, controlled tempo and steady breathing; keep wrists neutral and the bar from drifting.","Limit range if your low back arches or the bar wobbles; use a light load you can stabilize throughout."]},{"id":"2812","name":"dumbbell step-up split squat","body_part":"upper legs","target":"quads","secondary_muscles":["glutes","hamstrings","calves"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell step-up split squat is a lower body exercise that targets the quadriceps, with additional emphasis on the glutes, hamstrings, and calves. It involves stepping up onto a bench or step while holding dumbbells, requiring balance, coordination, and strength.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2812.gif","youtube_id":null,"instructions":["Stand in front of a bench or step with a dumbbell in each hand, palms facing your body.","Place your right foot on the bench or step, ensuring your entire foot is in contact with the surface.","Step up onto the bench or step with your right foot, pushing through your heel to lift your body up.","As you step up, simultaneously lift your left knee towards your chest.","Pause at the top of the movement, then slowly lower your left foot back to the ground while keeping your right foot on the bench or step.","Repeat the movement with your left foot on the bench or step.","Continue alternating between your right and left foot for the desired number of repetitions."]},{"id":"282","name":"decline sit-up","body_part":"waist","target":"abs","secondary_muscles":["hip flexors","lower back"],"equipment":"body weight","difficulty":"intermediate","description":"The decline sit-up is an abdominal exercise performed on a decline bench, targeting the abs with added resistance from gravity. It also engages the hip flexors and lower back as secondary muscles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0282.gif","youtube_id":null,"instructions":["Lie on a decline bench with your feet secured and your knees bent.","Place your hands behind your head or across your chest.","Engage your abs and lift your upper body off the bench, curling forward towards your knees.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"283","name":"diamond push-up","body_part":"upper arms","target":"triceps","secondary_muscles":["chest","shoulders"],"equipment":"body weight","difficulty":"intermediate","description":"The diamond push-up is a bodyweight exercise that primarily targets the triceps, with secondary emphasis on the chest and shoulders. It is performed in a plank position with the hands close together, forming a diamond shape, and requires significant upper body strength and stability.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0283.gif","youtube_id":null,"instructions":["Start in a high plank position with your hands close together, forming a diamond shape with your thumbs and index fingers.","Keep your body in a straight line from head to toe, engaging your core and glutes.","Lower your chest towards the diamond shape formed by your hands, keeping your elbows close to your body.","Pause for a moment at the bottom, then push yourself back up to the starting position.","Repeat for the desired number of repetitions."]},{"id":"284","name":"donkey calf raise","body_part":"lower legs","target":"calves","secondary_muscles":["hamstrings","glutes"],"equipment":"body weight","difficulty":"beginner","description":"The donkey calf raise is a bodyweight exercise that targets the calves. It involves standing with your toes on an elevated surface and raising your heels as high as possible to work the calf muscles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0284.gif","youtube_id":null,"instructions":["Stand with your toes on an elevated surface, such as a step or block.","Place your hands on a stable support, such as a wall or railing, for balance.","Raise your heels as high as possible, lifting your body weight onto the balls of your feet.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"285","name":"dumbbell alternate biceps curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell alternate biceps curl is a classic arm exercise that targets the biceps and also engages the forearms. It involves curling dumbbells alternately while keeping the upper arms stationary, focusing on controlled movement and muscle contraction.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0285.gif","youtube_id":null,"instructions":["Stand up straight with a dumbbell in each hand, palms facing forward and arms fully extended.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions, alternating arms."]},{"id":"286","name":"dumbbell alternate side press","body_part":"shoulders","target":"delts","secondary_muscles":["triceps","core"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell alternate side press is a shoulder exercise where you press one dumbbell overhead at a time, alternating sides. This movement targets the deltoids and also engages the triceps and core for stability.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0286.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder height.","Press one dumbbell overhead while keeping the other dumbbell at shoulder height.","Lower the pressed dumbbell back to shoulder height while pressing the other dumbbell overhead.","Continue alternating sides for the desired number of repetitions."]},{"id":"287","name":"dumbbell arnold press v. 2","body_part":"shoulders","target":"delts","secondary_muscles":["triceps","upper chest"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell Arnold press v. 2 is a shoulder exercise that involves pressing dumbbells overhead while rotating the wrists, targeting the deltoids and engaging the triceps and upper chest.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0287.gif","youtube_id":null,"instructions":["Sit on a bench with back support and hold a dumbbell in each hand at shoulder level, palms facing your body and elbows bent.","Press the dumbbells upward until your arms are fully extended and your palms are facing forward.","Rotate your wrists as you lift, so that your palms end up facing forward at the top of the movement.","Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"288","name":"dumbbell around pullover","body_part":"chest","target":"pectorals","secondary_muscles":["triceps","latissimus dorsi"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell around pullover is a chest exercise performed lying on a bench, where you lower a dumbbell behind your head in an arc and then return to the starting position. It primarily targets the pectorals, with secondary emphasis on the triceps and latissimus dorsi.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0288.gif","youtube_id":null,"instructions":["Lie flat on a bench with your head at one end and your feet firmly on the ground.","Hold a dumbbell with both hands and extend your arms straight above your chest.","Keeping your arms straight, slowly lower the dumbbell behind your head in an arc motion.","Pause for a moment at the bottom, then raise the dumbbell back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"289","name":"dumbbell bench press","body_part":"chest","target":"pectorals","secondary_muscles":["triceps","shoulders"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell bench press is a classic upper body strength exercise that targets the pectoral muscles, with secondary emphasis on the triceps and shoulders. It is performed lying on a bench, pressing dumbbells from chest level to full arm extension.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0289.gif","youtube_id":null,"instructions":["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Hold a dumbbell in each hand, with your palms facing forward and your arms extended above your chest.","Lower the dumbbells slowly to the sides of your chest, keeping your elbows at a 90-degree angle.","Pause for a moment, then push the dumbbells back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]},{"id":"29","name":"barbell clean-grip front squat","body_part":"upper legs","target":"glutes","secondary_muscles":["quadriceps","hamstrings","calves","core"],"equipment":"barbell","difficulty":"intermediate","description":"The barbell clean-grip front squat is a compound lower body exercise that targets the glutes, quadriceps, and hamstrings, while also engaging the core for stability. It requires holding a barbell in the clean grip position on the front of the shoulders, demanding good mobility and strength.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0029.gif","youtube_id":null,"instructions":["Start by standing with your feet shoulder-width apart and the barbell resting on your upper chest, with your elbows pointing forward.","Lower your body by bending your knees and pushing your hips back, as if you are sitting back into a chair.","Keep your chest up and your back straight as you lower down, making sure your knees do not go past your toes.","Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.","Pause for a moment at the bottom, then push through your heels to stand back up, extending your hips and knees.","Repeat for the desired number of repetitions."]},{"id":"290","name":"dumbbell bench seated press","body_part":"shoulders","target":"delts","secondary_muscles":["triceps","chest"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell bench seated press is a strength exercise targeting the deltoid muscles of the shoulders, with secondary emphasis on the triceps and chest. It is performed seated on a bench, pressing dumbbells overhead in a controlled manner.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0290.gif","youtube_id":null,"instructions":["Sit on a bench with a dumbbell in each hand, resting on your thighs.","Lean back and position the dumbbells to the sides of your chest, palms facing forward.","Press the dumbbells upward until your arms are fully extended.","Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"291","name":"dumbbell bench squat","body_part":"upper legs","target":"glutes","secondary_muscles":["quadriceps","hamstrings","calves"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell bench squat is a lower body exercise that targets the glutes, with secondary emphasis on the quadriceps, hamstrings, and calves. It involves squatting down to a bench while holding a dumbbell, which helps guide depth and form.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0291.gif","youtube_id":null,"instructions":["Place a dumbbell on the ground in front of a bench.","Stand facing away from the bench with your feet shoulder-width apart.","Bend at the knees and hips to lower yourself down towards the bench, keeping your chest up and back straight.","Once your glutes touch the bench, push through your heels to stand back up to the starting position.","Repeat for the desired number of repetitions."]},{"id":"292","name":"dumbbell one arm bent-over row","body_part":"back","target":"upper back","secondary_muscles":["biceps","forearms"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell one arm bent-over row is a unilateral strength exercise targeting the upper back, with secondary emphasis on the biceps and forearms. It involves hinging at the hips and pulling a dumbbell towards the chest while maintaining a stable, neutral spine.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0292.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, holding a dumbbell in one hand with your palm facing your body.","Bend your knees slightly and hinge forward at the hips, keeping your back straight and your core engaged.","Let the dumbbell hang straight down towards the floor, with your arm fully extended.","Pull the dumbbell up towards your chest, keeping your elbow close to your body and squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch sides."]},{"id":"293","name":"dumbbell bent over row","body_part":"back","target":"upper back","secondary_muscles":["biceps","forearms"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell bent over row is a compound exercise targeting the upper back, performed by hinging at the hips and pulling dumbbells towards the chest while maintaining a straight back.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0293.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, knees slightly bent, and hold a dumbbell in each hand with your palms facing your body.","Bend forward at the hips, keeping your back straight and your core engaged.","Let your arms hang straight down towards the floor, with your elbows slightly bent.","Pull the dumbbells up towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"294","name":"dumbbell biceps curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell biceps curl is a classic strength exercise that targets the biceps and also works the forearms. It involves curling dumbbells from a fully extended arm position to shoulder level, focusing on controlled movement and muscle contraction.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0294.gif","youtube_id":null,"instructions":["Stand up straight with a dumbbell in each hand, palms facing forward and arms fully extended.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"295","name":"dumbbell clean","body_part":"upper legs","target":"glutes","secondary_muscles":["hamstrings","quadriceps","calves"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell clean is a compound exercise that targets the glutes and also works the hamstrings, quadriceps, and calves. It involves explosive movement, coordination, and proper technique to safely lift the dumbbells from the ground to the shoulders.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0295.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.","Bend your knees and lower your hips into a squat position, keeping your back straight and chest up.","Explosively extend your hips and knees, driving through your heels to jump off the ground.","As you jump, shrug your shoulders and pull the dumbbells up towards your shoulders, keeping them close to your body.","Catch the dumbbells at shoulder height, with your elbows pointing forward and your palms facing up.","Lower the dumbbells back down to the starting position by reversing the movement.","Repeat for the desired number of repetitions."]},{"id":"296","name":"dumbbell close-grip press","body_part":"upper arms","target":"triceps","secondary_muscles":["chest","shoulders"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell close-grip press is an upper arm exercise that primarily targets the triceps, with secondary emphasis on the chest and shoulders. It is performed using dumbbells on a flat bench, focusing on pressing the weights with a close grip to maximize triceps activation.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0296.gif","youtube_id":null,"instructions":["Sit on a flat bench with a dumbbell in each hand, resting on your thighs.","Using your thighs to help raise the dumbbells, lift the dumbbells one at a time so that you can hold them in front of you at shoulder width.","Once at shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. This will be your starting position.","As you breathe in, slowly lower the dumbbells to your side until they are about level with your chest.","As you exhale, use your triceps to lift the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"2963","name":"captains chair straight leg raise","body_part":"waist","target":"abs","secondary_muscles":["hip flexors"],"equipment":"body weight","difficulty":"intermediate","description":"The captain's chair straight leg raise is an abdominal exercise performed on a captain's chair apparatus. It primarily targets the abdominal muscles and also engages the hip flexors. The movement requires core strength and stability to lift and control the legs while keeping the upper body stable.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2963.gif","youtube_id":null,"instructions":["Sit on the captain's chair with your back against the backrest and your forearms resting on the arm pads.","Keep your upper body stable and your back straight.","Engage your abs and lift your legs up in front of you, keeping them straight.","Continue lifting until your legs are parallel to the ground or as high as you can comfortably go.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"297","name":"dumbbell concentration curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell concentration curl is an isolation exercise targeting the biceps, performed while seated with the working arm braced against the inner thigh for strict form.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0297.gif","youtube_id":null,"instructions":["Sit on a bench with your legs spread apart and a dumbbell in one hand, resting your elbow on the inside of your thigh.","Fully extend your arm and hold the dumbbell with an underhand grip.","Keeping your upper arm stationary, exhale and curl the weight up towards your shoulder while contracting your biceps.","Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]},{"id":"298","name":"dumbbell cross body hammer curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell cross body hammer curl is an isolation exercise targeting the biceps and forearms, performed by curling dumbbells across the body toward the opposite shoulder.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0298.gif","youtube_id":null,"instructions":["Stand up straight with a dumbbell in each hand, palms facing your body.","Keep your elbows close to your torso and your upper arms stationary.","Exhale and curl the weights while contracting your biceps, bringing the dumbbells across your body towards your opposite shoulder.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"2987","name":"weighted close grip chin-up on dip cage","body_part":"back","target":"lats","secondary_muscles":["biceps","forearms"],"equipment":"weighted","difficulty":"advanced","description":"The weighted close grip chin-up on dip cage is a challenging upper body exercise that targets the lats, with significant involvement from the biceps and forearms. It requires the use of additional weight, increasing the demand on strength and control.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-2987.gif","youtube_id":null,"instructions":["Stand in front of the dip cage and grab the parallel bars with an underhand grip, hands shoulder-width apart.","Hang from the bars with your arms fully extended, feet off the ground, and body straight.","Engage your back muscles and pull your body up towards the bars, keeping your elbows close to your sides.","Continue pulling until your chin is above the bars, then pause for a moment.","Slowly lower your body back down to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]},{"id":"299","name":"dumbbell cuban press","body_part":"shoulders","target":"delts","secondary_muscles":["triceps","upper back"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell Cuban press is a shoulder exercise that combines external rotation and pressing to target the deltoids, triceps, and upper back. It is often used to improve shoulder strength and stability, as well as to promote healthy shoulder movement patterns.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0299.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder height with your palms facing down.","Keeping your core engaged and your elbows slightly bent, press the dumbbells up and overhead until your arms are fully extended.","Rotate your wrists so that your palms are facing forward.","Slowly lower the dumbbells back to the starting position, rotating your wrists back to the starting position as you do so.","Repeat for the desired number of repetitions."]},{"id":"3","name":"air bike","body_part":"waist","target":"abs","secondary_muscles":["hip flexors"],"equipment":"body weight","difficulty":"beginner","description":"The air bike is a bodyweight exercise targeting the abdominal muscles and hip flexors. It involves a pedaling motion while lying on your back, alternating elbow-to-knee contact to engage the core.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0003.gif","youtube_id":null,"instructions":["Lie flat on your back with your hands placed behind your head.","Lift your legs off the ground and bend your knees at a 90-degree angle.","Bring your right elbow towards your left knee while simultaneously straightening your right leg.","Return to the starting position and repeat the movement on the opposite side, bringing your left elbow towards your right knee while straightening your left leg.","Continue alternating sides in a pedaling motion for the desired number of repetitions."]},{"id":"30","name":"barbell close-grip bench press","body_part":"upper arms","target":"triceps","secondary_muscles":["chest","shoulders"],"equipment":"barbell","difficulty":"intermediate","description":"The barbell close-grip bench press is a compound exercise primarily targeting the triceps, with secondary emphasis on the chest and shoulders. It is performed by lying on a bench, gripping the barbell with a close grip, and pressing the weight up and down while keeping the elbows close to the body.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0030.gif","youtube_id":null,"instructions":["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Grasp the barbell with a close grip, slightly narrower than shoulder-width apart.","Unrack the barbell and lower it slowly towards your chest, keeping your elbows close to your body.","Pause for a moment when the barbell touches your chest.","Push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]},{"id":"300","name":"dumbbell deadlift","body_part":"upper legs","target":"glutes","secondary_muscles":["hamstrings","lower back"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell deadlift is a compound exercise targeting the glutes, with secondary emphasis on the hamstrings and lower back. It involves lifting dumbbells from the ground by hinging at the hips and extending through the legs and back.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0300.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, toes pointing forward.","Hold a dumbbell in each hand, palms facing your body, arms extended downwards.","Bend at your hips and knees, lowering the dumbbells towards the ground while keeping your back straight.","Push through your heels and extend your hips and knees, lifting the dumbbells back up to the starting position.","Repeat for the desired number of repetitions."]},{"id":"3006","name":"resistance band seated hip abduction","body_part":"upper legs","target":"abductors","secondary_muscles":["glutes","hamstrings"],"equipment":"resistance band","difficulty":"beginner","description":"A seated exercise using a resistance band to target the hip abductors by pushing the knees apart against resistance. This movement also engages the glutes and hamstrings.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3006.gif","youtube_id":null,"instructions":["Sit on a chair or bench with your back straight and feet flat on the ground.","Wrap the resistance band around your thighs, just above your knees.","Place your hands on the sides of the chair or bench for support.","Engage your abductors (outer thigh muscles) and slowly push your knees apart, against the resistance of the band.","Pause for a moment at the end of the movement, then slowly bring your knees back together.","Repeat for the desired number of repetitions."]},{"id":"3007","name":"resistance band leg extension","body_part":"upper legs","target":"quads","secondary_muscles":["hamstrings"],"equipment":"resistance band","difficulty":"beginner","description":"The resistance band leg extension targets the quadriceps by extending the leg against the resistance of a band, helping to build strength and endurance in the upper legs.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3007.gif","youtube_id":null,"instructions":["Attach the resistance band to a sturdy anchor point and secure it around your ankle.","Stand facing the anchor point with your feet shoulder-width apart.","Keeping your core engaged and your upper body stable, extend your leg straight out in front of you.","Pause for a moment at the top, then slowly return your leg to the starting position.","Repeat for the desired number of repetitions, then switch legs."]},{"id":"301","name":"dumbbell decline bench press","body_part":"chest","target":"pectorals","secondary_muscles":["triceps","shoulders"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell decline bench press is a chest exercise performed on a decline bench, targeting the lower pectorals. It also engages the triceps and shoulders as secondary muscles. The movement involves pressing dumbbells upward from a declined position, requiring good form and control.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0301.gif","youtube_id":null,"instructions":["Lie down on a decline bench with your feet secured and your head lower than your hips.","Hold a dumbbell in each hand and extend your arms straight up above your chest, palms facing forward.","Lower the dumbbells slowly to the sides of your chest, keeping your elbows at a 90-degree angle.","Push the dumbbells back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]},{"id":"3010","name":"ez bar lying bent arms pullover","body_part":"back","target":"lats","secondary_muscles":["triceps","chest"],"equipment":"ez barbell","difficulty":"intermediate","description":"The EZ bar lying bent arms pullover is a strength exercise targeting the lats, with secondary emphasis on the triceps and chest. It involves lying on a bench and moving the EZ barbell in an arc over and behind the head, requiring control and stability.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3010.gif","youtube_id":null,"instructions":["Lie flat on a bench with your head at one end and your feet on the floor.","Hold the EZ barbell with a pronated grip (palms facing away from you) and your hands shoulder-width apart.","Extend your arms straight above your chest, keeping a slight bend in your elbows.","Lower the barbell in an arc motion behind your head, maintaining the slight bend in your elbows.","Pause for a moment, then return the barbell to the starting position by reversing the arc motion.","Repeat for the desired number of repetitions."]},{"id":"3011","name":"incline scapula push up","body_part":"chest","target":"serratus anterior","secondary_muscles":["triceps","shoulders"],"equipment":"body weight","difficulty":"beginner","description":"The incline scapula push up is a bodyweight exercise performed on an incline bench that primarily targets the serratus anterior. It also engages the triceps and shoulders. The movement emphasizes scapular retraction and protraction, helping to improve shoulder stability and strength.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3011.gif","youtube_id":null,"instructions":["Set up an incline bench at a 45-degree angle.","Place your hands on the bench slightly wider than shoulder-width apart.","Position your feet on the ground, hip-width apart.","Lower your chest towards the bench, keeping your elbows tucked in.","As you lower, retract your shoulder blades, squeezing your scapulae together.","Push through your palms to extend your arms and return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"3012","name":"scapula dips","body_part":"back","target":"traps","secondary_muscles":["rhomboids","deltoids"],"equipment":"body weight","difficulty":"beginner","description":"Scapula dips are a bodyweight exercise targeting the traps and upper back, focusing on scapular retraction and depression. This movement helps improve shoulder stability and strength.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3012.gif","youtube_id":null,"instructions":["Start by standing with your feet shoulder-width apart and your arms extended in front of you.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Lower your body by bending your elbows and retracting your shoulder blades, as if you are trying to squeeze a pencil between them.","Pause for a moment at the bottom, then push through your hands to extend your elbows and return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"3013","name":"low glute bridge on floor","body_part":"upper legs","target":"glutes","secondary_muscles":["hamstrings","core"],"equipment":"body weight","difficulty":"beginner","description":"The low glute bridge on floor is a bodyweight exercise that targets the glutes while also engaging the hamstrings and core. It is performed by lying on your back, lifting your hips off the ground, and squeezing your glutes at the top of the movement.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3013.gif","youtube_id":null,"instructions":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your arms by your sides, palms facing down.","Engage your glutes and core, then lift your hips off the ground until your body forms a straight line from your knees to your shoulders.","Pause for a moment at the top, squeezing your glutes.","Slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"3016","name":"curl-up","body_part":"waist","target":"abs","secondary_muscles":["hip flexors"],"equipment":"body weight","difficulty":"beginner","description":"The curl-up is a bodyweight exercise targeting the abdominal muscles. It involves lying on your back, bending your knees, and curling your upper body towards your knees to engage the abs.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3016.gif","youtube_id":null,"instructions":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"3017","name":"barbell pendlay row","body_part":"back","target":"upper back","secondary_muscles":["biceps","forearms"],"equipment":"barbell","difficulty":"intermediate","description":"The barbell Pendlay row is a strength exercise targeting the upper back, performed by pulling a barbell from the floor to the upper abdomen with strict form.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3017.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and your knees slightly bent.","Bend forward at the hips, keeping your back straight and your chest up.","Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.","Pull the barbell towards your upper abdomen, squeezing your shoulder blades together.","Lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"3019","name":"bench pull-ups","body_part":"back","target":"lats","secondary_muscles":["biceps","forearms"],"equipment":"body weight","difficulty":"beginner","description":"Bench pull-ups are a bodyweight exercise targeting the lats, performed by pulling your chest up to a horizontal bar or surface while keeping your body straight. This movement also engages the biceps and forearms.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3019.gif","youtube_id":null,"instructions":["Position yourself under a bar or a sturdy horizontal surface that is at chest height.","Grab the bar or surface with an overhand grip, slightly wider than shoulder-width apart.","Hang with your arms fully extended and your body straight.","Pull your chest towards the bar or surface by squeezing your shoulder blades together and bending your elbows.","Continue pulling until your chin is above the bar or surface.","Lower yourself back down to the starting position with control.","Repeat for the desired number of repetitions."]},{"id":"302","name":"dumbbell decline fly","body_part":"chest","target":"pectorals","secondary_muscles":["shoulders"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell decline fly is a chest exercise performed on a decline bench, targeting the lower pectoral muscles. It involves lowering dumbbells out to the sides in a wide arc and then bringing them back together, emphasizing chest muscle stretch and contraction.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0302.gif","youtube_id":null,"instructions":["Lie on a decline bench with your feet secured and your head lower than your hips.","Hold a dumbbell in each hand with your palms facing each other and your arms extended above your chest.","Lower the dumbbells out to the sides in a wide arc until you feel a stretch in your chest.","Pause for a moment, then squeeze your chest muscles to bring the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"3021","name":"scapula push-up","body_part":"chest","target":"serratus anterior","secondary_muscles":["triceps","shoulders"],"equipment":"body weight","difficulty":"beginner","description":"The scapula push-up is a bodyweight exercise that targets the serratus anterior and helps improve scapular mobility and stability. It is performed in a high plank position, focusing on the movement of the shoulder blades rather than the elbows.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3021.gif","youtube_id":null,"instructions":["Start in a high plank position with your hands directly under your shoulders and your body in a straight line.","Lower your chest towards the ground, keeping your elbows close to your body.","As you lower, squeeze your shoulder blades together and push your chest forward.","Pause for a moment at the bottom, then push back up to the starting position.","Repeat for the desired number of repetitions."]},{"id":"303","name":"dumbbell decline hammer press","body_part":"chest","target":"pectorals","secondary_muscles":["triceps","shoulders"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell decline hammer press is a chest exercise performed on a decline bench using dumbbells. It targets the lower pectorals and also engages the triceps and shoulders. The hammer grip (palms facing each other) emphasizes the inner chest and triceps while reducing shoulder strain.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0303.gif","youtube_id":null,"instructions":["Lie on a decline bench with your feet secured and your head lower than your hips.","Hold a dumbbell in each hand with your palms facing each other and your arms extended above your chest.","Lower the dumbbells to the sides of your chest, keeping your elbows slightly bent.","Press the dumbbells back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]},{"id":"304","name":"dumbbell decline shrug v. 2","body_part":"back","target":"traps","secondary_muscles":["shoulders","rhomboids"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell decline shrug v. 2 targets the trapezius muscles by having the user lie face down on a decline bench and perform a shrugging motion with dumbbells, emphasizing the upper back and shoulders.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0304.gif","youtube_id":null,"instructions":["Set up a decline bench at a 45-degree angle.","Lie face down on the bench with your chest and stomach resting on it.","Hold a dumbbell in each hand with your palms facing each other and your arms fully extended.","Keeping your arms straight, raise your shoulders as high as possible while squeezing your shoulder blades together.","Hold the contraction for a brief pause, then lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"305","name":"dumbbell decline shrug","body_part":"back","target":"traps","secondary_muscles":["shoulders","rhomboids"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell decline shrug is an isolation exercise targeting the trapezius muscles. It is performed lying face down on a decline bench, holding dumbbells with arms extended, and shrugging the shoulders upward.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0305.gif","youtube_id":null,"instructions":["Set up a decline bench at a 45-degree angle.","Lie face down on the bench with your chest and stomach resting against it.","Hold a dumbbell in each hand with your arms fully extended towards the floor.","Keeping your arms straight, raise your shoulders towards your ears as high as possible.","Hold the contraction for a moment, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"306","name":"dumbbell decline triceps extension","body_part":"upper arms","target":"triceps","secondary_muscles":["shoulders"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell decline triceps extension is an isolation exercise targeting the triceps, performed on a decline bench to increase the stretch and activation of the triceps muscles. It also engages the shoulders as secondary muscles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0306.gif","youtube_id":null,"instructions":["Lie on a decline bench with your head lower than your feet and hold a dumbbell in each hand, palms facing each other.","Extend your arms fully, keeping your elbows close to your head.","Lower the dumbbells slowly behind your head, bending your elbows.","Pause for a moment, then raise the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"307","name":"dumbbell decline twist fly","body_part":"chest","target":"pectorals","secondary_muscles":["shoulders","triceps"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell decline twist fly is a chest exercise performed on a decline bench, targeting the pectoral muscles while also engaging the shoulders and triceps. The movement involves lowering dumbbells in a wide arc with a twisting motion, increasing the stretch and contraction of the chest.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0307.gif","youtube_id":null,"instructions":["Lie down on a decline bench with your head lower than your hips.","Hold a dumbbell in each hand with your palms facing each other and your arms extended straight up over your chest.","Lower the dumbbells out to the sides in a wide arc until you feel a stretch in your chest.","As you lower the dumbbells, twist your wrists so that your palms face forward at the bottom of the movement.","Reverse the motion and bring the dumbbells back up to the starting position, squeezing your chest muscles at the top.","Repeat for the desired number of repetitions."]},{"id":"308","name":"dumbbell fly","body_part":"chest","target":"pectorals","secondary_muscles":["shoulders"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell fly is a chest exercise performed lying on a bench, using dumbbells to stretch and contract the pectoral muscles through a wide arc motion.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0308.gif","youtube_id":null,"instructions":["Lie flat on a bench with a dumbbell in each hand, palms facing each other.","Extend your arms straight up over your chest, with a slight bend in your elbows.","Keeping a slight bend in your elbows, lower your arms out to the sides in a wide arc until you feel a stretch in your chest.","Pause for a moment, then reverse the movement and bring the dumbbells back up to the starting position.","Repeat for the desired number of repetitions."]},{"id":"309","name":"dumbbell front raise v. 2","body_part":"shoulders","target":"delts","secondary_muscles":["trapezius","biceps"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell front raise v. 2 is a shoulder exercise that targets the deltoid muscles. It involves lifting dumbbells in front of the body to shoulder height, focusing on controlled movement and proper form.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0309.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing your thighs.","Keep your back straight and engage your core.","Slowly lift the dumbbells in front of you, with your arms straight, until they are at shoulder level.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"31","name":"barbell curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"barbell","difficulty":"beginner","description":"The barbell curl is a classic strength exercise targeting the biceps, performed by curling a barbell from the thighs to the shoulders while keeping the elbows close to the torso.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0031.gif","youtube_id":null,"instructions":["Stand up straight with your feet shoulder-width apart and hold a barbell with an underhand grip, palms facing forward.","Keep your elbows close to your torso and exhale as you curl the weights while contracting your biceps.","Continue to raise the bar until your biceps are fully contracted and the bar is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale as you slowly begin to lower the bar back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"310","name":"dumbbell front raise","body_part":"shoulders","target":"delts","secondary_muscles":["biceps","trapezius"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell front raise is a shoulder exercise that targets the deltoid muscles, particularly the anterior (front) portion. It also engages the biceps and trapezius as secondary muscles. The movement involves lifting dumbbells in front of the body to shoulder height, focusing on controlled motion and proper form.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0310.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing your thighs.","Keeping your arms straight, exhale and lift the dumbbells in front of you until they are at shoulder level.","Pause for a moment at the top, then inhale and slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"311","name":"dumbbell full can lateral raise","body_part":"shoulders","target":"delts","secondary_muscles":["traps","rotator cuff"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell full can lateral raise is a shoulder exercise that targets the deltoids and also engages the traps and rotator cuff. It involves raising dumbbells to the sides with a slight bend in the elbows, mimicking the motion of pouring from a can, which helps reduce shoulder impingement risk.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0311.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing your body.","Keep your back straight and engage your core.","Raise your arms out to the sides, keeping a slight bend in your elbows, until they are parallel to the ground.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"3116","name":"band fixed back underhand pulldown","body_part":"back","target":"lats","secondary_muscles":["biceps","rhomboids","rear deltoids"],"equipment":"band","difficulty":"beginner","description":"The band fixed back underhand pulldown is a resistance band exercise targeting the latissimus dorsi (lats) and also working the biceps, rhomboids, and rear deltoids. It mimics the motion of a traditional lat pulldown but uses a resistance band anchored above the head.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3116.gif","youtube_id":null,"instructions":["Attach the band to a sturdy anchor point above your head.","Stand facing the anchor point with your feet shoulder-width apart.","Grasp the band with an underhand grip, hands slightly wider than shoulder-width apart.","Step back to create tension in the band, keeping your arms fully extended.","Engage your core and squeeze your shoulder blades together.","Pull the band down towards your chest, leading with your elbows.","Pause for a moment at the bottom of the movement, feeling the contraction in your lats.","Slowly release the tension in the band and return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"3117","name":"band fixed back close grip pulldown","body_part":"back","target":"lats","secondary_muscles":["biceps","forearms"],"equipment":"band","difficulty":"beginner","description":"The band fixed back close grip pulldown is an exercise targeting the latissimus dorsi (lats) using a resistance band anchored above the user. It mimics the traditional cable pulldown but uses a band for resistance, making it accessible and effective for building back strength.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3117.gif","youtube_id":null,"instructions":["Attach the band to a fixed point above you, such as a pull-up bar or sturdy beam.","Sit down on a bench or chair facing the band, with your feet flat on the ground and your knees bent.","Grasp the band with a close grip, palms facing towards you.","Keep your back straight and engage your core.","Pull the band down towards your chest, squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, feeling the contraction in your lats.","Slowly release the band back to the starting position, maintaining control throughout the movement.","Repeat for the desired number of repetitions."]},{"id":"3119","name":"potty squat","body_part":"waist","target":"abs","secondary_muscles":["quadriceps","glutes"],"equipment":"body weight","difficulty":"beginner","description":"The potty squat is a bodyweight exercise that targets the abs while also engaging the quadriceps and glutes. It involves squatting down as if sitting on a chair, maintaining a straight back and upright chest, and then returning to a standing position.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3119.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, toes pointing slightly outward.","Lower your body down by bending your knees and pushing your hips back as if you were sitting on a chair.","Keep your chest up and your back straight throughout the movement.","Lower yourself until your thighs are parallel to the ground or as low as you can comfortably go.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"312","name":"dumbbell hammer curl v. 2","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell hammer curl v. 2 is a biceps-focused exercise performed with dumbbells, emphasizing the brachialis and forearm muscles. It is performed standing, with palms facing the torso, and involves curling the weights while keeping the upper arms stationary.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0312.gif","youtube_id":null,"instructions":["Stand up straight with a dumbbell in each hand, palms facing your torso.","Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward.","This will be your starting position.","Now, keeping the upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Then, inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the recommended amount of repetitions."]},{"id":"3122","name":"resistance band seated shoulder press","body_part":"shoulders","target":"delts","secondary_muscles":["triceps","upper back"],"equipment":"resistance band","difficulty":"beginner","description":"The resistance band seated shoulder press is an overhead pressing exercise performed while seated, using a resistance band to target the deltoid muscles. It also engages the triceps and upper back as secondary muscles. This exercise is suitable for building shoulder strength and stability, and is accessible for most fitness levels due to the controlled movement and support provided by the seated position.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3122.gif","youtube_id":null,"instructions":["Sit on a chair or bench with your back straight and feet flat on the ground.","Hold the resistance band with both hands, palms facing forward, and bring it up to shoulder level.","Press the band overhead, extending your arms fully.","Pause for a moment at the top, then slowly lower the band back down to shoulder level.","Repeat for the desired number of repetitions."]},{"id":"3123","name":"resistance band seated biceps curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"resistance band","difficulty":"beginner","description":"The resistance band seated biceps curl is an upper arm exercise that targets the biceps using a resistance band while seated, making it accessible and safe for most fitness levels.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3123.gif","youtube_id":null,"instructions":["Sit on a chair or bench with your back straight and feet flat on the ground.","Hold the resistance band with an underhand grip, palms facing up, and arms extended down by your sides.","Keeping your upper arms stationary, exhale and curl the resistance band up towards your shoulders.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the resistance band back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"3124","name":"resistance band seated chest press","body_part":"chest","target":"pectorals","secondary_muscles":["shoulders","triceps"],"equipment":"resistance band","difficulty":"beginner","description":"The resistance band seated chest press is a chest-focused exercise performed while sitting, using a resistance band to provide tension. It targets the pectoral muscles and also works the shoulders and triceps. This movement is performed by pressing the band forward from the chest while seated, making it accessible and safe for most fitness levels.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3124.gif","youtube_id":null,"instructions":["Sit on a chair or bench with your back straight and feet flat on the ground.","Hold the resistance band handles in each hand, with your palms facing down and elbows bent at a 90-degree angle.","Extend your arms forward, pushing the resistance band away from your chest.","Pause for a moment at the end of the movement, then slowly return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"3125","name":"resistance band foot external rotation","body_part":"lower legs","target":"calves","secondary_muscles":["peroneus longus","peroneus brevis","peroneus tertius","extensor digitorum longus"],"equipment":"resistance band","difficulty":"beginner","description":"Sit on a bench with a light loop band around both forefeet; one foot anchors the band while the other rotates outward against the resistance. Keep the heel down and move only at the ankle to train the lateral lower-leg muscles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3125.gif","youtube_id":null,"instructions":["Sit tall on a bench or chair with knees bent ~90° and both feet flat, hip‑width apart.","Loop a small resistance band around the forefeet; keep the non‑working foot still to act as the anchor.","Brace your core, keep the working heel planted and shin vertical.","Rotate the working foot outward (eversion/external rotation), leading with the little toe; do not let the knee or hip twist.","Pause briefly at end range without pain, feeling the outer lower leg engage.","Return slowly to neutral under control; avoid the band snapping back.","Complete reps, then switch sides; keep movements small, smooth, and pain‑free."]},{"id":"3126","name":"resistance band foot plantar flexion","body_part":"lower legs","target":"calves","secondary_muscles":["tibialis posterior","flexor hallucis longus","flexor digitorum longus","peroneus longus"],"equipment":"resistance band","difficulty":"beginner","description":"Seated, loop a resistance band around the ball of the working foot and anchor the other end securely. Plantarflex the ankle by pointing the toes against the band, then return under control.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3126.gif","youtube_id":null,"instructions":["Sit tall on a bench or chair with knees at ~90° and the working heel lightly on the floor.","Loop the band around the ball of the working foot; anchor the other end under your opposite foot or hold it to create light tension.","Set the ankle in neutral (shin vertical, foot at 90°).","Press through the ball of the foot to plantarflex, pointing the toes away while keeping the knee still and heel gently grounded.","Pause briefly at end range without letting the ankle roll inward or outward.","Slowly return to the start over 2–3 seconds, controlling the resistance.","Repeat for reps, then switch sides; stop if you feel sharp pain in the Achilles or ankle joint."]},{"id":"3127","name":"resistance band foot eversion","body_part":"lower legs","target":"calves","secondary_muscles":["tibialis anterior","extensor digitorum longus","extensor hallucis longus"],"equipment":"resistance band","difficulty":"beginner","description":"Seated with a band looped around the ball of the working foot and anchored under the opposite foot, rotate the sole outward against the band. This isolates the ankle evertors to strengthen the lateral lower leg and support the ankle.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3127.gif","youtube_id":null,"instructions":["Sit tall on a chair with knees at 90 degrees and feet flat.","Loop the band around the ball of the working foot; anchor the other end under the opposite foot so it pulls the forefoot inward.","Keep the working heel lightly on the floor and the knee still; ankle starts neutral.","Evert the foot by sweeping the forefoot outward against the band without rotating the knee or hip.","Pause 1–2 seconds at end range, keeping toes relaxed and the arch lifted.","Return slowly to neutral under control, maintaining light tension in the band.","Complete 10–20 reps, then switch sides; adjust band length to achieve a pain‑free, controlled range."]},{"id":"3128","name":"resistance band foot inversion","body_part":"lower legs","target":"calves","secondary_muscles":["tibialis anterior","flexor digitorum longus","flexor hallucis longus","gastrocnemius","soleus"],"equipment":"resistance band","difficulty":"beginner","description":"Sit with a resistance band looped around the forefoot of the working leg and anchored laterally so it pulls the foot outward. Rotate the foot inward against the band to strengthen the medial ankle stabilizers, keeping the shin still.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3128.gif","youtube_id":null,"instructions":["Sit tall with knees bent ~90°, heel of the working foot on the floor and toes slightly dorsiflexed.","Loop the band around the forefoot and anchor it to the outside (under the opposite foot or a sturdy object) so it pulls laterally.","Brace the lower leg; do not let the knee or hip move.","Pull the inside edge of the foot inward (invert) against the band in a slow, controlled motion.","Pause 1–2 seconds at end range without pain or cramping.","Return slowly to neutral under control; avoid letting the band snap you back or everting past neutral.","Keep heel down and avoid excessive plantarflexion; breathe steadily.","Complete desired reps, then switch sides."]},{"id":"313","name":"dumbbell hammer curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell hammer curl is a strength exercise targeting the biceps and forearms. It is performed by curling dumbbells with a neutral grip (palms facing each other), which emphasizes the brachialis and brachioradialis muscles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0313.gif","youtube_id":null,"instructions":["Stand up straight with a dumbbell in each hand, palms facing your torso.","Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward.","This will be your starting position.","Now, keeping the upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Then, inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the recommended amount of repetitions."]},{"id":"3132","name":"potty squat with support","body_part":"upper legs","target":"glutes","secondary_muscles":["quadriceps","hamstrings","calves"],"equipment":"body weight","difficulty":"beginner","description":"The potty squat with support is a bodyweight exercise targeting the glutes, performed with the assistance of a stable support for balance. It is suitable for those developing lower body strength and proper squat mechanics.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3132.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, toes pointing slightly outward.","Hold onto a stable support, such as a chair or wall, for balance.","Lower your body down into a squat position by bending your knees and pushing your hips back.","Keep your chest up and your back straight throughout the movement.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"314","name":"dumbbell incline bench press","body_part":"chest","target":"pectorals","secondary_muscles":["shoulders","triceps"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell incline bench press is a compound upper body exercise that targets the upper portion of the pectoral muscles, with additional emphasis on the shoulders and triceps. It is performed on an incline bench using dumbbells, requiring stability and control throughout the movement.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0314.gif","youtube_id":null,"instructions":["Set up an incline bench at a 45-degree angle.","Sit on the bench with your feet flat on the ground and your back pressed firmly against the bench.","Hold a dumbbell in each hand, palms facing forward, and lift them to shoulder height.","Slowly lower the dumbbells to the sides of your chest, keeping your elbows at a 90-degree angle.","Push the dumbbells back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]},{"id":"3142","name":"smith sumo squat","body_part":"upper legs","target":"glutes","secondary_muscles":["quadriceps","hamstrings","calves"],"equipment":"smith machine","difficulty":"beginner","description":"The smith sumo squat is a lower body exercise performed on a smith machine, targeting the glutes with secondary emphasis on the quadriceps, hamstrings, and calves. The wide stance and guided bar path make it accessible for those developing squat technique and lower body strength.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3142.gif","youtube_id":null,"instructions":["Set up the smith machine with the barbell at hip height.","Stand with your feet wider than shoulder-width apart, toes pointing outwards.","Position yourself under the barbell, resting it on your upper back and shoulders.","Engage your core and keep your chest up as you lower your body down into a squat position, pushing your hips back and bending your knees.","Lower yourself until your thighs are parallel to the ground, or as low as you can comfortably go.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"3144","name":"resistance band seated straight back row","body_part":"back","target":"upper back","secondary_muscles":["biceps","shoulders"],"equipment":"resistance band","difficulty":"beginner","description":"The resistance band seated straight back row targets the upper back muscles and is performed seated on the floor with a resistance band looped around the feet. It emphasizes scapular retraction and upper back strength.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3144.gif","youtube_id":null,"instructions":["Sit on the floor with your legs extended and loop the resistance band around your feet.","Hold the ends of the resistance band with your hands, palms facing each other.","Keep your back straight and lean slightly back, engaging your core.","Pull the resistance band towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"3145","name":"push-up plus","body_part":"chest","target":"pectorals","secondary_muscles":["triceps","shoulders"],"equipment":"body weight","difficulty":"intermediate","description":"The push-up plus is a variation of the standard push-up that adds an extra movement at the top of the push-up by protracting the shoulder blades, which further engages the serratus anterior and improves shoulder stability.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3145.gif","youtube_id":null,"instructions":["Start in a high plank position with your hands slightly wider than shoulder-width apart and your body in a straight line from head to heels.","Lower your body towards the ground by bending your elbows, keeping them close to your sides.","Once your chest is just above the ground, push through your hands to extend your arms and lift your upper body up.","At the top of the movement, protract your shoulder blades by pushing your upper back towards the ceiling.","Pause for a moment, then reverse the movement by retracting your shoulder blades and lowering your body back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"3147","name":"pelvic tilt","body_part":"waist","target":"abs","secondary_muscles":["lower back"],"equipment":"body weight","difficulty":"beginner","description":"The pelvic tilt is a bodyweight exercise that targets the abdominal muscles and helps improve core stability and lower back health. It is often used in rehabilitation and as a foundational movement for beginners.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3147.gif","youtube_id":null,"instructions":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands by your sides.","Engage your abs and tilt your pelvis upward, pressing your lower back into the ground.","Hold this position for a few seconds, focusing on contracting your abs.","Release the tilt and return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"3149","name":"chin tuck","body_part":"neck","target":"spine","secondary_muscles":["levator scapulae","traps","upper back"],"equipment":"body weight","difficulty":"beginner","description":"Sit or stand tall with neutral posture. Glide your head straight back to create a gentle double-chin, aligning the cervical spine; hold briefly, then return to neutral.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3149.gif","youtube_id":null,"instructions":["Sit or stand upright with shoulders relaxed and eyes looking straight ahead.","Brace lightly through your midsection and keep your jaw relaxed.","Without tilting your head up or down, draw your chin straight backward as if sliding your head along a track.","Feel the back of your neck lengthen and the front of your neck gently engage; keep eyes level.","Hold for 3–5 seconds while breathing normally.","Slowly return to the starting position and repeat for 8–12 controlled reps."]},{"id":"315","name":"dumbbell incline biceps curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell incline biceps curl is a strength exercise targeting the biceps, performed on an incline bench to increase the stretch and activation of the biceps muscle. It also engages the forearms as secondary muscles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0315.gif","youtube_id":null,"instructions":["Sit on an incline bench with a dumbbell in each hand, palms facing forward, and arms fully extended.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"3150","name":"assisted chin tuck","body_part":"neck","target":"spine","secondary_muscles":["upper back","traps"],"equipment":"assisted","difficulty":"beginner","description":"Stand tall with your back near a wall and use your fingers to gently guide your chin straight backward to align the head over the spine. This assisted chin tuck reinforces cervical retraction without neck flexion or extension.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3150.gif","youtube_id":null,"instructions":["Stand with your upper back close to a wall, feet hip‑width, knees soft, chest tall.","Place one or two fingers on the tip of your chin to guide the motion; keep eyes level.","Without tilting the head, glide your chin straight back, making a small “double chin.”","Lightly touch the back of your head to the wall at the base of the skull while keeping the neck long.","Hold 3–5 seconds, breathe normally, and keep shoulders relaxed (no shrugging).","Slowly release to the start position and repeat for controlled reps.","Avoid jutting the chin forward, looking up/down, or opening the mouth during the movement."]},{"id":"3156","name":"bodyweight standing close-grip one arm row","body_part":"back","target":"upper back","secondary_muscles":["biceps","forearms"],"equipment":"body weight","difficulty":"intermediate","description":"The bodyweight standing close-grip one arm row is a unilateral exercise targeting the upper back, performed with body weight and focusing on pulling strength and stability.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3156.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, knees slightly bent, and hold a dumbbell in one hand with a neutral grip.","Bend forward at the hips, keeping your back straight and your core engaged.","Pull the dumbbell up towards your chest, keeping your elbow close to your body and squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch sides."]},{"id":"3158","name":"bodyweight standing close-grip row","body_part":"back","target":"upper back","secondary_muscles":["biceps","forearms"],"equipment":"body weight","difficulty":"beginner","description":"The bodyweight standing close-grip row targets the upper back using only body weight for resistance. It involves pulling a bar or handles towards the body while maintaining a bent-over position, focusing on squeezing the shoulder blades together.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3158.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and knees slightly bent.","Bend forward at the waist, keeping your back straight and your core engaged.","Extend your arms straight in front of you, gripping the bar or handles with a close grip.","Pull the bar or handles towards your body, squeezing your shoulder blades together.","Pause for a moment at the top of the movement, then slowly release and return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"316","name":"dumbbell incline breeding","body_part":"chest","target":"pectorals","secondary_muscles":["shoulders","triceps"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell incline breeding (likely a typo for 'dumbbell incline bench press' or 'dumbbell incline fly') is a chest exercise performed on an incline bench using dumbbells. It targets the upper chest (pectorals) and also works the shoulders and triceps.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0316.gif","youtube_id":null,"instructions":["Set up an incline bench at a 45-degree angle.","Sit on the bench with your back against the pad and feet flat on the ground.","Hold a dumbbell in each hand with an overhand grip, palms facing forward.","Start with your arms fully extended, perpendicular to the ground.","Lower the dumbbells slowly to the sides of your chest, keeping your elbows at a 90-degree angle.","Pause for a moment at the bottom, then push the dumbbells back up to the starting position.","Repeat for the desired number of repetitions."]},{"id":"3161","name":"bodyweight standing one arm row (with towel)","body_part":"back","target":"upper back","secondary_muscles":["biceps","forearms"],"equipment":"body weight","difficulty":"beginner","description":"A bodyweight exercise targeting the upper back, performed by pulling a towel with one arm while standing, engaging the biceps and forearms as secondary muscles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3161.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, knees slightly bent, and hold a towel with one hand.","Bend forward at the hips, keeping your back straight and your core engaged.","Pull the towel towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the towel back to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]},{"id":"3162","name":"bodyweight standing one arm row","body_part":"back","target":"upper back","secondary_muscles":["biceps","forearms"],"equipment":"body weight","difficulty":"beginner","description":"The bodyweight standing one arm row is a unilateral exercise targeting the upper back, performed by hinging at the hips and pulling a weight toward the chest with one arm.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3162.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, knees slightly bent, and hold a dumbbell in one hand.","Bend forward at the hips, keeping your back straight and your core engaged.","Let the dumbbell hang straight down in front of you, with your arm fully extended.","Pull the dumbbell up towards your chest, keeping your elbow close to your body.","Squeeze your shoulder blades together at the top of the movement.","Lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch sides."]},{"id":"3165","name":"bodyweight standing row (with towel)","body_part":"back","target":"upper back","secondary_muscles":["biceps","shoulders"],"equipment":"body weight","difficulty":"beginner","description":"The bodyweight standing row (with towel) is a back exercise that targets the upper back using a towel for resistance. It also engages the biceps and shoulders. The movement is performed by pulling the towel towards your chest while maintaining a strong posture.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3165.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and hold a towel in front of you with both hands.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Pull the towel towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"3166","name":"bodyweight standing row","body_part":"back","target":"upper back","secondary_muscles":["biceps","shoulders"],"equipment":"body weight","difficulty":"beginner","description":"The bodyweight standing row is a back exercise that targets the upper back using only body weight for resistance. It also engages the biceps and shoulders as secondary muscles. The movement involves pulling a bar or handles towards the body while standing, focusing on squeezing the shoulder blades together.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3166.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and knees slightly bent.","Grasp a bar or handles with an overhand grip, palms facing down.","Keep your back straight and core engaged.","Pull the bar or handles towards your body, squeezing your shoulder blades together.","Pause for a moment at the top of the movement.","Slowly release and extend your arms back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"3167","name":"bodyweight squatting row (with towel)","body_part":"back","target":"upper back","secondary_muscles":["biceps","shoulders"],"equipment":"body weight","difficulty":"beginner","description":"The bodyweight squatting row (with towel) is a compound exercise that targets the upper back while also engaging the biceps and shoulders. It combines a squat with a rowing motion using a towel for resistance, making it a functional movement that develops strength and coordination.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3167.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, holding a towel in front of you with your palms facing down.","Bend your knees and lower your body into a squat position, keeping your back straight and your chest up.","As you lower into the squat, simultaneously pull the towel towards your chest, squeezing your shoulder blades together.","Pause for a moment at the bottom of the squat, then slowly return to the starting position while extending your arms.","Repeat for the desired number of repetitions."]},{"id":"3168","name":"bodyweight squatting row","body_part":"back","target":"upper back","secondary_muscles":["biceps","shoulders"],"equipment":"body weight","difficulty":"intermediate","description":"The bodyweight squatting row is a compound exercise that targets the upper back while also engaging the biceps and shoulders. It combines a squatting motion with a rowing movement, requiring coordination and strength.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3168.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, holding onto a sturdy object or suspension trainer with your arms extended.","Lower your body into a squat position, keeping your back straight and your knees behind your toes.","From the squat position, pull your body up towards the object or suspension trainer, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"317","name":"dumbbell incline curl v. 2","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell incline curl v. 2 is a biceps-focused exercise performed on an incline bench. It isolates the biceps and forearms, requiring controlled movement to maximize muscle engagement.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0317.gif","youtube_id":null,"instructions":["Sit on an incline bench with a dumbbell in each hand, palms facing forward and arms fully extended.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"318","name":"dumbbell incline curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell incline curl is an isolation exercise targeting the biceps. Performed on an incline bench, it emphasizes the stretch and contraction of the biceps by reducing the involvement of the shoulders. This exercise is effective for building biceps strength and size.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0318.gif","youtube_id":null,"instructions":["Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, palms facing forward.","Rest your upper arms on the incline bench and let your elbows hang down, fully extending your arms.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"319","name":"dumbbell incline fly","body_part":"chest","target":"pectorals","secondary_muscles":["shoulders"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell incline fly is a chest exercise performed on an incline bench, targeting the upper pectoral muscles. It involves lowering dumbbells out to the sides in a wide arc and then bringing them back together, emphasizing a stretch and contraction of the chest.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0319.gif","youtube_id":null,"instructions":["Set an incline bench to a 45-degree angle.","Sit on the bench with a dumbbell in each hand, palms facing each other.","Lie back on the bench and press the dumbbells up to the starting position, directly above your chest.","Lower the dumbbells out to the sides in a wide arc until you feel a stretch in your chest.","Pause for a moment, then squeeze your chest muscles to bring the dumbbells back up to the starting position.","Repeat for the desired number of repetitions."]},{"id":"3193","name":"glute-ham raise","body_part":"upper legs","target":"hamstrings","secondary_muscles":["glutes","lower back"],"equipment":"body weight","difficulty":"advanced","description":"The glute-ham raise is a bodyweight exercise that primarily targets the hamstrings, with secondary emphasis on the glutes and lower back. It is performed on a glute-ham raise machine and requires significant strength and control to execute properly.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3193.gif","youtube_id":null,"instructions":["Adjust the glute-ham raise machine to fit your body.","Position yourself face down on the machine with your ankles secured.","Place your hands on your chest or cross them over your chest.","Engage your hamstrings and glutes to lift your upper body up towards the ceiling.","Continue lifting until your body is in a straight line from your head to your heels.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"3194","name":"frankenstein squat","body_part":"upper legs","target":"glutes","secondary_muscles":["quadriceps","hamstrings","calves"],"equipment":"barbell","difficulty":"intermediate","description":"The Frankenstein squat is a variation of the squat where the barbell is held in front of the body with straight arms, challenging the glutes, quadriceps, hamstrings, and calves. This exercise emphasizes posture, core stability, and lower body strength.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3194.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and hold the barbell in front of your body with straight arms.","Keeping your back straight, lower your body by bending at the knees and hips, as if sitting back into a chair.","Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.","Pause for a moment, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"3195","name":"lever lying two-one leg curl","body_part":"upper legs","target":"hamstrings","secondary_muscles":["glutes"],"equipment":"leverage machine","difficulty":"intermediate","description":"The lever lying two-one leg curl is an isolation exercise targeting the hamstrings using a leverage machine. It involves curling the legs towards the glutes while lying on the machine, focusing on one leg at a time for increased intensity and muscle engagement.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3195.gif","youtube_id":null,"instructions":["Adjust the machine to fit your body and sit on it with your back against the backrest.","Place your legs on the lever pad, just above your ankles.","Grasp the handles on the sides of the machine for support.","Keeping your upper body still, exhale and curl your legs up towards your glutes.","Pause for a moment at the top, then inhale and slowly lower your legs back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"3196","name":"quick feet run","body_part":"cardio","target":"cardiovascular system","secondary_muscles":["quads","hamstrings","glutes","calves","abs"],"equipment":"body weight","difficulty":"beginner","description":"A fast-feet drill performed in place to elevate heart rate and improve leg turnover. Run on the balls of your feet with short, rapid steps while keeping an athletic, upright posture.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3196.gif","youtube_id":null,"instructions":["Stand tall with feet hip-width apart, knees slightly bent, and elbows at about 90 degrees.","Engage your core and lean your torso forward just a few degrees, staying on the balls of your feet.","Begin taking very short, rapid steps in place, minimizing ground contact time.","Pump your arms in opposition to your legs while keeping shoulders relaxed and down.","Keep hips level, torso upright, and land quietly on the forefoot—avoid heel striking and excessive vertical bounce.","Maintain a brisk, steady rhythm for the prescribed time; stop if posture or cadence breaks down."]},{"id":"3197","name":"prancing","body_part":"lower legs","target":"calves","secondary_muscles":["glutes","hamstrings","quads","abs"],"equipment":"body weight","difficulty":"beginner","description":"Stand tall and alternately rise onto one forefoot while lowering the other heel, mimicking a light prancing motion. Keep the torso upright and move through a full ankle range with controlled rhythm.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3197.gif","youtube_id":null,"instructions":["Stand with feet hip-width apart, toes pointing forward, arms relaxed or in a gentle running swing for balance.","Shift weight to your right forefoot and press through the ball of the foot to lift the right heel high; keep the knee soft, not locked.","Keep the left heel lightly on the ground as you rise on the right, maintaining an upright torso and braced core.","Lower the right heel under control as you transfer weight to the left forefoot.","Lift the left heel high while the right foot returns to flat, continuing to alternate sides in a smooth rhythm.","Maintain even tempo, forefoot contact, and neutral ankles (don’t roll outward or inward).","Breathe steadily and stop before losing form or bouncing excessively."]},{"id":"3198","name":"zigzag hops","body_part":"lower legs","target":"calves","secondary_muscles":["quads","glutes","hamstrings","abductors","adductors"],"equipment":"body weight","difficulty":"intermediate","description":"Set 4–6 cones in a straight line and stand to one side of the first cone. Hop diagonally from side to side over the line of cones, moving forward in a zigzag on the balls of your feet.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3198.gif","youtube_id":null,"instructions":["Stand athletic: feet hip-width, knees softly bent, chest up, eyes forward.","Load through the hips and ankles and hop diagonally over the line to the opposite side of the next cone, landing on the balls of your feet.","Absorb the landing softly by bending the ankles, knees, and hips while keeping knees tracking over toes.","Immediately rebound into the next diagonal hop, using arm swing for balance and rhythm.","Maintain a neutral torso and keep hops low-to-moderate and quick to emphasize control and reactivity.","Continue hopping past all cones, then walk back to recover and repeat for the desired reps or time.","If form degrades, slow the pace or reduce hop distance/height."]},{"id":"3199","name":"skips","body_part":"cardio","target":"cardiovascular system","secondary_muscles":["glutes","quads","hamstrings","calves","abs"],"equipment":"body weight","difficulty":"beginner","description":"From a tall stance, perform rhythmic skipping steps, driving one knee up with an opposite arm swing while lightly hopping off the stance foot. Land softly and alternate sides to elevate heart rate and coordination.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3199.gif","youtube_id":null,"instructions":["Stand tall with feet hip-width, arms bent about 90°, core braced, and eyes forward.","Push through the ball of your left foot to hop as you drive your right knee to hip height and swing the left arm forward/right arm back.","Land softly on your left forefoot with a slight bend in the ankle, knee, and hip; keep your torso upright.","Step onto your right foot and immediately hop, driving the left knee up with an opposite arm swing.","Maintain quick, light ground contacts, knees tracking over toes, and dorsiflex the airborne foot.","Alternate sides continuously for time or distance while breathing steadily and avoiding excessive forward lean."]},{"id":"32","name":"barbell deadlift","body_part":"upper legs","target":"glutes","secondary_muscles":["hamstrings","lower back"],"equipment":"barbell","difficulty":"intermediate","description":"The barbell deadlift is a compound strength exercise that targets the glutes, hamstrings, and lower back. It involves lifting a loaded barbell from the ground to a standing position, emphasizing proper form and core engagement.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0032.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and the barbell on the ground in front of you.","Bend your knees and hinge at the hips to lower your torso and grip the barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Keep your back straight and chest lifted as you drive through your heels to lift the barbell off the ground, extending your hips and knees.","As you stand up straight, squeeze your glutes and keep your core engaged.","Lower the barbell back down to the ground by bending at the hips and knees, keeping your back straight.","Repeat for the desired number of repetitions."]},{"id":"320","name":"dumbbell incline hammer curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell incline hammer curl is an upper arm exercise that targets the biceps and also works the forearms. It is performed while sitting on an incline bench, which increases the stretch on the biceps and challenges the muscles through a greater range of motion.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0320.gif","youtube_id":null,"instructions":["Sit on an incline bench with a dumbbell in each hand, palms facing your torso and arms fully extended.","Keep your back against the bench and your feet flat on the floor.","While keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"3200","name":"lever bent-over row with v-bar","body_part":"back","target":"upper back","secondary_muscles":["biceps","forearms"],"equipment":"leverage machine","difficulty":"intermediate","description":"The lever bent-over row with v-bar is a machine-based exercise targeting the upper back, with secondary emphasis on the biceps and forearms. It involves pulling a v-bar attachment towards the abdomen while maintaining a bent-over position, focusing on squeezing the shoulder blades together.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3200.gif","youtube_id":null,"instructions":["Adjust the seat height and position yourself facing the machine.","Grasp the v-bar with an overhand grip, keeping your back straight and your knees slightly bent.","Pull the v-bar towards your abdomen, squeezing your shoulder blades together.","Pause for a moment at the top of the movement, then slowly release the weight back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"3201","name":"quarter sit-up","body_part":"waist","target":"abs","secondary_muscles":["hip flexors"],"equipment":"body weight","difficulty":"beginner","description":"The quarter sit-up is an abdominal exercise that involves lifting your upper body off the ground to about a 45-degree angle, focusing on engaging the abs with minimal hip flexor involvement.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3201.gif","youtube_id":null,"instructions":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"3202","name":"half sit-up (male)","body_part":"waist","target":"abs","secondary_muscles":["hip flexors"],"equipment":"body weight","difficulty":"beginner","description":"The half sit-up (male) is an abdominal exercise performed with body weight. It involves curling the upper body off the ground to a 45-degree angle, primarily targeting the abs and secondarily engaging the hip flexors.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3202.gif","youtube_id":null,"instructions":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"3203","name":"prisoner half sit-up (male)","body_part":"waist","target":"abs","secondary_muscles":["hip flexors"],"equipment":"body weight","difficulty":"beginner","description":"The prisoner half sit-up is an abdominal exercise performed with body weight, focusing on the abs and hip flexors. It involves lying on your back, hands behind your head, and curling your torso up to a 45-degree angle before lowering back down.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3203.gif","youtube_id":null,"instructions":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"3204","name":"arms overhead full sit-up (male)","body_part":"waist","target":"abs","secondary_muscles":["hip flexors","lower back"],"equipment":"body weight","difficulty":"intermediate","description":"The arms overhead full sit-up is a bodyweight abdominal exercise where you lie on your back with arms extended overhead and perform a full sit-up, engaging the abs, hip flexors, and lower back.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3204.gif","youtube_id":null,"instructions":["Lie flat on your back with your knees bent and feet flat on the ground.","Extend your arms overhead, keeping them straight.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is upright.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"321","name":"dumbbell incline hammer press","body_part":"chest","target":"pectorals","secondary_muscles":["shoulders","triceps"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell incline hammer press is a chest exercise performed on an incline bench using dumbbells, with a neutral grip (palms facing each other). It targets the upper chest (pectorals) and also works the shoulders and triceps.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0321.gif","youtube_id":null,"instructions":["Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, resting on your thighs.","Lie back on the bench and position the dumbbells at shoulder level with your palms facing each other.","Press the dumbbells up and away from your body until your arms are fully extended.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"3211","name":"kneeling push-up (male)","body_part":"chest","target":"pectorals","secondary_muscles":["triceps","shoulders"],"equipment":"body weight","difficulty":"beginner","description":"The kneeling push-up (male) is a bodyweight exercise targeting the pectorals, with secondary emphasis on the triceps and shoulders. It is performed from a kneeling position, making it a less challenging variation of the standard push-up, suitable for building foundational upper body strength.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3211.gif","youtube_id":null,"instructions":["Start by kneeling on the ground with your hands shoulder-width apart, fingers pointing forward.","Extend your legs behind you, resting on the balls of your feet, so that your body forms a straight line from head to heels.","Engage your core and lower your body towards the ground by bending your elbows, keeping them close to your sides.","Continue lowering until your chest is just above the ground, then push back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."]},{"id":"3212","name":"basic toe touch (male)","body_part":"upper legs","target":"glutes","secondary_muscles":["hamstrings","calves"],"equipment":"body weight","difficulty":"beginner","description":"The basic toe touch is a bodyweight exercise that primarily targets the glutes, with secondary emphasis on the hamstrings and calves. It involves bending forward at the waist to reach towards the toes, providing a stretch to the posterior chain.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3212.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and your arms by your sides.","Bend forward at the waist, keeping your back straight and your knees slightly bent.","Reach down towards your toes with your hands, keeping your legs as straight as possible.","Pause for a moment at the bottom, then slowly return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"3213","name":"side-to-side toe touch (male)","body_part":"waist","target":"abs","secondary_muscles":["obliques","hip flexors"],"equipment":"body weight","difficulty":"beginner","description":"The side-to-side toe touch is a bodyweight exercise targeting the abs, obliques, and hip flexors. It involves bending at the waist to touch each foot alternately, promoting core engagement and flexibility.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3213.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and your arms extended to the sides.","Bend at the waist to the right, reaching your right hand towards your right foot while keeping your left hand extended to the side.","Return to the starting position and then bend at the waist to the left, reaching your left hand towards your left foot while keeping your right hand extended to the side.","Repeat the side-to-side bending motion for the desired number of repetitions."]},{"id":"3214","name":"arms apart circular toe touch (male)","body_part":"upper legs","target":"glutes","secondary_muscles":["hamstrings","quadriceps","calves"],"equipment":"body weight","difficulty":"intermediate","description":"The arms apart circular toe touch is a bodyweight exercise that targets the glutes, hamstrings, quadriceps, and calves. It involves bending forward at the waist to touch your toes with one hand while lifting the opposite leg behind you, alternating sides to challenge balance and flexibility.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3214.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and arms extended to the sides.","Keeping your legs straight, bend forward at the waist and reach down towards your toes with your right hand.","As you reach down, simultaneously lift your left leg straight up behind you, maintaining balance.","Return to the starting position and repeat the movement with your left hand reaching towards your toes and your right leg lifting up behind you.","Continue alternating sides for the desired number of repetitions."]},{"id":"3215","name":"hands reversed clasped circular toe touch (male)","body_part":"upper legs","target":"glutes","secondary_muscles":["hamstrings","quadriceps","calves"],"equipment":"body weight","difficulty":"beginner","description":"This exercise involves standing with feet shoulder-width apart, bending forward at the waist, clasping hands behind the legs, and performing a circular motion with the arms to touch the toes, targeting the glutes and stretching the lower body.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3215.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and your arms extended to the sides.","Bend forward at the waist, keeping your back straight and your knees slightly bent.","Reach down with your hands and clasp them together behind your legs.","Slowly raise your hands up and over your head in a circular motion, keeping your legs straight.","Continue the circular motion until your hands touch your toes.","Reverse the motion and bring your hands back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"3216","name":"chest tap push-up (male)","body_part":"chest","target":"pectorals","secondary_muscles":["triceps","shoulders"],"equipment":"body weight","difficulty":"advanced","description":"The chest tap push-up is a challenging bodyweight exercise that targets the pectorals while also engaging the triceps and shoulders. It requires strength, coordination, and balance as you momentarily support your body with one hand while tapping your chest with the other.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3216.gif","youtube_id":null,"instructions":["Start in a high plank position with your hands slightly wider than shoulder-width apart and your body in a straight line.","Lower your body towards the ground by bending your elbows, keeping them close to your sides.","As you lower yourself, tap your chest with your right hand.","Push yourself back up to the starting position.","Repeat the movement, this time tapping your chest with your left hand.","Continue alternating sides for the desired number of repetitions."]},{"id":"3217","name":"modified hindu push-up (male)","body_part":"chest","target":"pectorals","secondary_muscles":["triceps","shoulders","core"],"equipment":"body weight","difficulty":"intermediate","description":"The modified Hindu push-up is a bodyweight exercise that targets the pectorals while also engaging the triceps, shoulders, and core. It involves a dynamic movement pattern that combines elements of a push-up with a downward dog-like position, challenging both strength and mobility.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3217.gif","youtube_id":null,"instructions":["Start in a push-up position with your hands slightly wider than shoulder-width apart and your feet hip-width apart.","Lower your body towards the ground, bending your elbows and keeping your core engaged.","As you lower your body, shift your weight back and lift your hips up towards the ceiling, creating an inverted V shape with your body.","Continue to lower your body until your chest is just above the ground, then reverse the movement, pushing your hips back down and extending your arms to return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"3218","name":"hands clasped circular toe touch (male)","body_part":"upper legs","target":"glutes","secondary_muscles":["hamstrings","quadriceps","calves"],"equipment":"body weight","difficulty":"beginner","description":"The hands clasped circular toe touch is a bodyweight exercise that targets the glutes and also engages the hamstrings, quadriceps, and calves. It involves hinging at the hips and making a circular motion with your hands towards your toes, promoting flexibility and mobility in the lower body.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3218.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and your hands clasped together in front of your chest.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Lower your hands towards your toes in a circular motion, reaching as far as you can without straining.","Pause for a moment at the bottom, then slowly return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"3219","name":"scissor jumps (male)","body_part":"cardio","target":"cardiovascular system","secondary_muscles":["quadriceps","hamstrings","calves"],"equipment":"body weight","difficulty":"intermediate","description":"Scissor jumps are a plyometric cardio exercise that involves jumping and alternating the crossing of your legs in mid-air. This movement elevates the heart rate and challenges coordination and lower body strength.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3219.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart.","Jump off the ground and simultaneously cross your right leg in front of your left leg.","As you land, quickly switch legs, crossing your left leg in front of your right leg.","Continue alternating legs and jumping as quickly as possible.","Repeat for the desired number of repetitions."]},{"id":"322","name":"dumbbell incline inner biceps curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell incline inner biceps curl is an isolation exercise targeting the biceps, performed on an incline bench to increase the stretch and activation of the muscle. It also engages the forearms as secondary muscles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0322.gif","youtube_id":null,"instructions":["Sit on an incline bench with a dumbbell in each hand, palms facing each other.","Rest your upper arms on the bench, allowing your elbows to hang down and your palms to face forward.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"3220","name":"astride jumps (male)","body_part":"cardio","target":"cardiovascular system","secondary_muscles":["quadriceps","hamstrings","calves"],"equipment":"body weight","difficulty":"beginner","description":"Astride jumps (male) are a plyometric cardio exercise that involves jumping explosively from a squat position, spreading the legs and arms in the air, and landing softly. This movement targets the cardiovascular system while also engaging the quadriceps, hamstrings, and calves.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3220.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart.","Bend your knees and lower your body into a squat position.","Jump explosively upwards, extending your legs and arms.","While in the air, spread your legs apart and bring your arms out to the sides.","Land softly with your feet shoulder-width apart, bending your knees to absorb the impact.","Repeat for the desired number of repetitions."]},{"id":"3221","name":"half knee bends (male)","body_part":"cardio","target":"cardiovascular system","secondary_muscles":["quadriceps","hamstrings","glutes"],"equipment":"body weight","difficulty":"beginner","description":"Half knee bends (male) are a bodyweight exercise that primarily targets the cardiovascular system while also engaging the quadriceps, hamstrings, and glutes. The movement involves bending the knees and lowering the body as if sitting back into a chair, then returning to standing. This exercise is often used for light cardio, warm-ups, or rehabilitation.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3221.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart.","Bend your knees and lower your body down as if you were sitting back into a chair.","Keep your chest up and your weight in your heels.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"3222","name":"semi squat jump (male)","body_part":"cardio","target":"cardiovascular system","secondary_muscles":["quadriceps","hamstrings","calves"],"equipment":"body weight","difficulty":"intermediate","description":"The semi squat jump is a plyometric exercise that targets the cardiovascular system while also engaging the quadriceps, hamstrings, and calves. It involves performing a partial squat followed by an explosive jump, making it effective for improving cardiovascular fitness, lower body power, and coordination.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3222.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart.","Bend your knees and lower your body into a squat position.","Jump explosively, extending your hips and knees while swinging your arms for momentum.","Land softly on the balls of your feet and immediately go into the next repetition.","Repeat for the desired number of repetitions."]},{"id":"3223","name":"star jump (male)","body_part":"cardio","target":"cardiovascular system","secondary_muscles":["quadriceps","hamstrings","calves"],"equipment":"body weight","difficulty":"beginner","description":"The star jump (male) is a plyometric cardio exercise that involves jumping explosively while spreading the arms and legs out to form a star shape in the air. It targets the cardiovascular system and also engages the quadriceps, hamstrings, and calves.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3223.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and your arms by your sides.","Bend your knees slightly and jump up explosively.","As you jump, spread your legs and extend your arms out to the sides, forming a star shape with your body.","Land softly on the balls of your feet with your knees slightly bent.","Repeat for the desired number of repetitions."]},{"id":"3224","name":"jack jump (male)","body_part":"cardio","target":"cardiovascular system","secondary_muscles":["quadriceps","calves"],"equipment":"body weight","difficulty":"beginner","description":"A dynamic bodyweight exercise that involves jumping with feet apart and arms overhead, then returning to the starting position. This movement elevates the heart rate and targets the cardiovascular system, with secondary emphasis on the quadriceps and calves.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3224.gif","youtube_id":null,"instructions":["Stand with your feet together and your arms by your sides.","Jump up, spreading your feet apart and raising your arms above your head.","As you land, quickly jump back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"323","name":"dumbbell incline one arm lateral raise","body_part":"shoulders","target":"delts","secondary_muscles":["trapezius","triceps"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell incline one arm lateral raise is a shoulder isolation exercise performed on an incline bench. It targets the deltoid muscles and helps improve shoulder strength and stability.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0323.gif","youtube_id":null,"instructions":["Sit on an incline bench with a dumbbell in one hand, resting it on your thigh.","Lean forward and position your upper arm against the inside of your thigh.","Raise the dumbbell to the side, keeping your arm slightly bent and your palm facing down.","Continue lifting until your arm is parallel to the floor.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]},{"id":"3231","name":"two toe touch (male)","body_part":"back","target":"spine","secondary_muscles":["hamstrings","glutes"],"equipment":"body weight","difficulty":"beginner","description":"The two toe touch (male) is a bodyweight exercise that primarily targets the spine, with secondary emphasis on the hamstrings and glutes. It involves bending forward at the waist to touch your toes, promoting flexibility and mobility in the posterior chain.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3231.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and your arms extended out to the sides.","Bend forward at the waist, keeping your back straight and your knees slightly bent.","Reach down towards your toes with both hands, keeping your legs straight.","Pause for a moment at the bottom, then slowly return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"3234","name":"hyght dumbbell fly","body_part":"chest","target":"pectorals","secondary_muscles":["shoulders"],"equipment":"dumbbell","difficulty":"intermediate","description":"The hyght dumbbell fly is a chest exercise performed on a bench using dumbbells. It targets the pectoral muscles and also engages the shoulders. The movement involves lowering the dumbbells in a wide arc to stretch the chest and then bringing them back together above the chest.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3234.gif","youtube_id":null,"instructions":["Lie flat on a bench with a dumbbell in each hand, palms facing each other.","Extend your arms straight up over your chest, with a slight bend in your elbows.","Keeping a slight bend in your elbows, lower the dumbbells out to the sides in a wide arc until you feel a stretch in your chest.","Pause for a moment, then reverse the movement and bring the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"3235","name":"cable assisted inverse leg curl","body_part":"upper legs","target":"hamstrings","secondary_muscles":["glutes","calves"],"equipment":"cable","difficulty":"intermediate","description":"The cable assisted inverse leg curl is an exercise targeting the hamstrings, performed using a cable machine to provide resistance as you curl your legs toward your glutes while lying face down.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3235.gif","youtube_id":null,"instructions":["Adjust the cable machine so that the ankle attachment is at the lowest setting.","Lie face down on the bench with your legs straight and the ankle attachment secured to your ankles.","Hold onto the handles of the bench for stability.","Keeping your upper body stationary, exhale and curl your legs up towards your glutes by flexing your knees.","Pause for a moment at the top of the movement, squeezing your hamstrings.","Inhale and slowly lower your legs back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"3236","name":"resistance band hip thrusts on knees (female)","body_part":"upper legs","target":"glutes","secondary_muscles":["hamstrings","quadriceps"],"equipment":"resistance band","difficulty":"beginner","description":"Resistance band hip thrusts on knees (female) target the glutes primarily, with secondary activation of the hamstrings and quadriceps. The exercise is performed by kneeling, using a resistance band for added tension, and thrusting the hips forward to engage the glutes.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3236.gif","youtube_id":null,"instructions":["Start by kneeling on the ground with your knees hip-width apart and your feet flexed.","Wrap the resistance band around your thighs, just above your knees.","Place your hands on your hips or extend them out in front of you for balance.","Engage your glutes and core muscles.","Push your hips forward and squeeze your glutes as you lift your knees off the ground, extending your hips until your thighs are parallel to the ground.","Hold the position for a moment, then slowly lower your knees back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"3237","name":"landmine lateral raise","body_part":"shoulders","target":"delts","secondary_muscles":["traps","upper back"],"equipment":"barbell","difficulty":"intermediate","description":"The landmine lateral raise is a shoulder exercise performed using a barbell anchored at one end (landmine setup). It targets the deltoids and also engages the traps and upper back. The movement involves lifting the barbell laterally to shoulder height, emphasizing shoulder strength and stability.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3237.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and knees slightly bent.","Hold the barbell with an overhand grip, resting it on the front of your shoulders.","Keeping your core engaged and back straight, lift the barbell up and away from your body, raising it to shoulder height.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"3239","name":"kneeling plank tap shoulder (male)","body_part":"waist","target":"abs","secondary_muscles":["shoulders","triceps"],"equipment":"body weight","difficulty":"beginner","description":"The kneeling plank tap shoulder is a core stability exercise that targets the abs while also engaging the shoulders and triceps. It requires maintaining a stable plank position while alternately tapping each shoulder with the opposite hand, challenging balance and coordination.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3239.gif","youtube_id":null,"instructions":["Start in a kneeling position with your hands on the ground, shoulder-width apart.","Extend your legs behind you, resting on your toes, and lift your body into a plank position.","Keeping your core engaged and your hips stable, lift one hand off the ground and tap the opposite shoulder.","Return the hand to the ground and repeat with the other hand.","Continue alternating sides for the desired number of repetitions."]},{"id":"324","name":"dumbbell incline palm-in press","body_part":"chest","target":"pectorals","secondary_muscles":["shoulders","triceps"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell incline palm-in press is a chest exercise performed on an incline bench with dumbbells, focusing on the upper pectorals while also engaging the shoulders and triceps. The palms face each other throughout the movement, which can reduce shoulder strain and emphasize the inner chest.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0324.gif","youtube_id":null,"instructions":["Set up an incline bench at a 45-degree angle.","Sit on the bench with a dumbbell in each hand, palms facing each other.","Plant your feet firmly on the ground and keep your back straight against the bench.","Start with the dumbbells at shoulder level, elbows bent and palms facing each other.","Press the dumbbells up and away from your body, extending your arms fully.","Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"3240","name":"exercise ball on the wall calf raise (tennis ball between knees)","body_part":"lower legs","target":"calves","secondary_muscles":["quadriceps","hamstrings"],"equipment":"dumbbell","difficulty":"intermediate","description":"This exercise targets the calves by performing a calf raise while standing against a wall with an exercise ball supporting the lower back and a tennis ball held between the knees. Dumbbells are held for added resistance, and the movement requires balance and coordination.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3240.gif","youtube_id":null,"instructions":["Stand with your back against a wall and place an exercise ball between your lower back and the wall.","Position your feet shoulder-width apart and slightly in front of you.","Hold a dumbbell in each hand, with your arms extended by your sides.","Place a tennis ball between your knees.","Raise your heels off the ground, lifting your body up onto your toes.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"3241","name":"exercise ball on the wall calf raise (tennis ball between ankles)","body_part":"lower legs","target":"calves","secondary_muscles":["hamstrings","quadriceps"],"equipment":"dumbbell, exercise ball, tennis ball","difficulty":"intermediate","description":"This exercise targets the calves by performing a calf raise while holding a dumbbell in each hand, using an exercise ball for back support against the wall, and squeezing a tennis ball between the ankles to increase activation and control.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3241.gif","youtube_id":null,"instructions":["Stand facing a wall with your feet shoulder-width apart.","Place an exercise ball between the wall and your lower back.","Hold a dumbbell in each hand, with your arms extended by your sides.","Place a tennis ball between your ankles.","Raise your heels off the ground, lifting your body up onto your toes.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"325","name":"dumbbell incline raise","body_part":"shoulders","target":"delts","secondary_muscles":["trapezius","triceps"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell incline raise is a shoulder exercise performed on an incline bench, targeting the deltoid muscles. It also engages the trapezius and triceps as secondary muscles. The movement involves raising dumbbells from shoulder height to overhead while maintaining a stable position on the bench.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0325.gif","youtube_id":null,"instructions":["Sit on an incline bench with a dumbbell in each hand, resting on your thighs.","Lean back on the bench and raise the dumbbells to shoulder height, palms facing forward.","Keeping your back against the bench, exhale and raise the dumbbells above your head, fully extending your arms.","Pause for a moment at the top, then inhale and slowly lower the dumbbells back to shoulder height.","Repeat for the desired number of repetitions."]},{"id":"326","name":"dumbbell incline rear lateral raise","body_part":"shoulders","target":"delts","secondary_muscles":["traps","rhomboids"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell incline rear lateral raise targets the rear deltoids with secondary emphasis on the traps and rhomboids. It is performed on an incline bench to isolate the rear shoulder muscles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0326.gif","youtube_id":null,"instructions":["Set up an incline bench at a 45-degree angle.","Sit on the bench with your chest against the backrest and hold a dumbbell in each hand.","Extend your arms straight down with your palms facing each other.","Keeping a slight bend in your elbows, raise your arms out to the sides until they are parallel to the ground.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"327","name":"dumbbell incline row","body_part":"back","target":"upper back","secondary_muscles":["biceps","shoulders"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell incline row is a strength exercise targeting the upper back, performed on an incline bench with dumbbells. It emphasizes scapular retraction and upper back development while also engaging the biceps and shoulders.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0327.gif","youtube_id":null,"instructions":["Set up an incline bench at a 45-degree angle.","Grab a dumbbell in each hand and sit on the bench with your chest against the incline.","Extend your arms fully, allowing the dumbbells to hang straight down from your shoulders.","Pull the dumbbells up towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"328","name":"dumbbell incline shoulder raise","body_part":"chest","target":"serratus anterior","secondary_muscles":["deltoids","trapezius"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell incline shoulder raise targets the serratus anterior and also works the deltoids and trapezius. It is performed on an incline bench and involves raising dumbbells above the head while maintaining control and proper form.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0328.gif","youtube_id":null,"instructions":["Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, palms facing down.","Rest the dumbbells on your thighs and lean back onto the bench.","Use your thighs to help raise the dumbbells to shoulder height, then rotate your wrists so that your palms are facing forward.","Exhale and slowly raise the dumbbells above your head, keeping a slight bend in your elbows.","Pause for a moment at the top, then inhale and slowly lower the dumbbells back to shoulder height.","Repeat for the desired number of repetitions."]},{"id":"3281","name":"smith full squat","body_part":"upper legs","target":"glutes","secondary_muscles":["quadriceps","hamstrings","calves"],"equipment":"smith machine","difficulty":"beginner","description":"The smith full squat is a compound lower body exercise performed using a smith machine. It primarily targets the glutes, with secondary emphasis on the quadriceps, hamstrings, and calves. The smith machine provides stability, making it accessible to those who may not be comfortable with free-weight squats, but still requires proper form and core engagement.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3281.gif","youtube_id":null,"instructions":["Set up the smith machine with the barbell at shoulder height.","Stand with your feet shoulder-width apart, toes slightly turned out.","Step under the bar and position it across your upper back, resting on your traps.","Grip the bar with your hands slightly wider than shoulder-width apart.","Unrack the bar and take a step back, maintaining a stable stance.","Keeping your chest up and core engaged, initiate the squat by pushing your hips back and bending your knees.","Lower your body until your thighs are parallel to the ground, or as low as your flexibility allows.","Pause for a moment at the bottom, then drive through your heels to return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"3286","name":"weighted muscle up","body_part":"back","target":"lats","secondary_muscles":["biceps","triceps","shoulders","chest"],"equipment":"weighted","difficulty":"advanced","description":"The weighted muscle up is an advanced compound exercise that targets the lats and involves pulling your body above a bar with added resistance. It requires significant upper body strength, coordination, and technique, making it suitable for experienced athletes.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3286.gif","youtube_id":null,"instructions":["Start by hanging from a pull-up bar with your palms facing away from you and your hands slightly wider than shoulder-width apart.","Engage your core and pull your body up towards the bar, leading with your chest.","As you reach the top of the movement, transition your grip so that your palms are facing towards you.","Continue pulling yourself up until your chest reaches the bar, then pause for a moment.","Slowly lower yourself back down to the starting position, maintaining control throughout the movement.","Repeat for the desired number of repetitions."]},{"id":"3287","name":"elbow dips","body_part":"upper arms","target":"triceps","secondary_muscles":["chest","shoulders"],"equipment":"body weight","difficulty":"beginner","description":"Elbow dips are a bodyweight exercise targeting the triceps, performed using a bench or chair. The movement involves lowering and raising the body by bending and straightening the elbows while keeping the back close to the bench.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3287.gif","youtube_id":null,"instructions":["Sit on the edge of a bench or chair with your hands gripping the edge next to your hips.","Slide your hips forward off the bench and straighten your legs, keeping your heels on the ground.","Bend your elbows and lower your body towards the ground, keeping your back close to the bench.","Pause for a moment at the bottom, then push through your hands to straighten your arms and lift your body back up to the starting position.","Repeat for the desired number of repetitions."]},{"id":"3288","name":"korean dips","body_part":"chest","target":"pectorals","secondary_muscles":["triceps","shoulders"],"equipment":"body weight","difficulty":"advanced","description":"Korean dips are a challenging bodyweight exercise performed on parallel bars, targeting the pectorals, triceps, and shoulders. The movement requires significant upper body strength, shoulder mobility, and stability, as the body is lowered deeply between the bars before pressing back up.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3288.gif","youtube_id":null,"instructions":["Position yourself between two parallel bars with your arms extended and supporting your body weight.","Lower your body by bending your elbows until your upper arms are parallel to the ground.","Pause for a moment, then push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."]},{"id":"3289","name":"impossible dips","body_part":"upper arms","target":"triceps","secondary_muscles":["chest","shoulders"],"equipment":"body weight","difficulty":"advanced","description":"Impossible dips are a challenging bodyweight exercise performed between two parallel bars, focusing on the triceps while also engaging the chest and shoulders. The movement requires significant upper body strength and control, as well as experience with dip variations.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3289.gif","youtube_id":null,"instructions":["Position yourself between two parallel bars with your arms fully extended and your body suspended in the air.","Bend your knees and cross your ankles.","Lower your body by bending your elbows until your upper arms are parallel to the ground.","Pause for a moment, then push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."]},{"id":"329","name":"dumbbell incline shrug","body_part":"back","target":"traps","secondary_muscles":["shoulders"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell incline shrug targets the trapezius muscles by having the lifter sit on an incline bench and perform a shrugging motion with dumbbells. This variation emphasizes the upper traps and can help improve posture and upper back strength.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0329.gif","youtube_id":null,"instructions":["Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand.","Place your feet flat on the ground and let your arms hang straight down with your palms facing your body.","Keeping your arms straight, shrug your shoulders up towards your ears as high as possible.","Hold the contraction for a moment, then slowly lower your shoulders back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"3290","name":"weighted one hand pull up","body_part":"back","target":"lats","secondary_muscles":["biceps","forearms"],"equipment":"weighted","difficulty":"advanced","description":"The weighted one hand pull up is an advanced bodyweight exercise that targets the latissimus dorsi (lats) and also engages the biceps and forearms. By adding weight, this movement significantly increases the strength and coordination required, making it a challenging exercise for experienced athletes.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3290.gif","youtube_id":null,"instructions":["Grab the pull-up bar with an overhand grip, slightly wider than shoulder-width apart.","Hang from the bar with your arm fully extended and your body straight.","Engage your core and pull your body up towards the bar by bending your elbow and squeezing your back muscles.","Continue pulling until your chin is above the bar.","Lower your body back down to the starting position with control.","Repeat for the desired number of repetitions."]},{"id":"3291","name":"stalder press","body_part":"upper arms","target":"triceps","secondary_muscles":["shoulders","core"],"equipment":"body weight","difficulty":"advanced","description":"The stalder press is a challenging bodyweight exercise that primarily targets the triceps, while also engaging the shoulders and core. It involves a combination of squatting and pressing movements, requiring significant strength, balance, and coordination.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3291.gif","youtube_id":null,"instructions":["Start by standing with your feet shoulder-width apart and your arms extended overhead.","Bend your knees slightly and engage your core.","Lower your body down into a squat position while keeping your arms extended overhead.","As you squat down, press your arms down towards the ground, engaging your triceps.","Pause for a moment at the bottom of the squat, then push through your heels to stand back up while simultaneously raising your arms back overhead.","Repeat for the desired number of repetitions."]},{"id":"3292","name":"elevator","body_part":"back","target":"upper back","secondary_muscles":["shoulders","trapezius"],"equipment":"body weight","difficulty":"beginner","description":"The elevator is a bodyweight exercise targeting the upper back. It involves bending forward at the waist while keeping the back straight, then returning to a standing position. This movement helps strengthen the upper back and improves posture.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3292.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and your knees slightly bent.","Place your hands on your hips or cross them in front of your chest.","Keeping your back straight, slowly bend forward at the waist, lowering your upper body towards the ground.","Pause for a moment at the bottom, then slowly raise your upper body back up to the starting position.","Repeat for the desired number of repetitions."]},{"id":"3293","name":"archer pull up","body_part":"back","target":"lats","secondary_muscles":["biceps","forearms"],"equipment":"body weight","difficulty":"advanced","description":"The archer pull up is a challenging bodyweight exercise that targets the lats and requires significant strength, coordination, and control. It involves pulling up with one arm while the other remains straight, alternating sides with each repetition.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3293.gif","youtube_id":null,"instructions":["Start by hanging from a pull-up bar with an overhand grip, slightly wider than shoulder-width apart.","Engage your core and pull your shoulder blades down and back.","As you pull yourself up, bend one arm and bring your elbow towards your side, while keeping the other arm straight.","Continue pulling until your chin is above the bar and your bent arm is fully flexed.","Lower yourself back down with control, straightening the bent arm and repeating the movement on the other side.","Alternate sides with each repetition."]},{"id":"3294","name":"archer push up","body_part":"chest","target":"pectorals","secondary_muscles":["triceps","shoulders","core"],"equipment":"body weight","difficulty":"advanced","description":"The archer push up is a challenging bodyweight exercise that targets the pectorals and also works the triceps, shoulders, and core. It involves performing a push-up while extending one arm out to the side, increasing the load on the working arm and requiring significant strength, balance, and coordination.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3294.gif","youtube_id":null,"instructions":["Start in a push-up position with your hands slightly wider than shoulder-width apart.","Extend one arm straight out to the side, parallel to the ground.","Lower your body by bending your elbows, keeping your back straight and core engaged.","Push back up to the starting position.","Repeat on the other side, extending the opposite arm out to the side.","Continue alternating sides for the desired number of repetitions."]},{"id":"3295","name":"front lever reps","body_part":"back","target":"upper back","secondary_muscles":["core","shoulders"],"equipment":"body weight","difficulty":"advanced","description":"The front lever is an advanced calisthenics exercise that targets the upper back, core, and shoulders. It requires significant strength, body control, and coordination to maintain a horizontal position while hanging from a bar.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3295.gif","youtube_id":null,"instructions":["Hang from a pull-up bar with an overhand grip, palms facing away from you.","Engage your core and pull your shoulder blades down and back.","Keeping your body straight, lift your legs up until they are parallel to the ground.","Hold this position for as long as you can, aiming for 10-20 seconds.","Slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"3296","name":"front lever","body_part":"waist","target":"abs","secondary_muscles":["lats","shoulders","forearms"],"equipment":"body weight","difficulty":"advanced","description":"The front lever is a challenging bodyweight exercise that targets the abs and requires significant strength and control from the lats, shoulders, and forearms. It involves holding your body parallel to the ground while hanging from a pull-up bar.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3296.gif","youtube_id":null,"instructions":["Start by hanging from a pull-up bar with an overhand grip, hands shoulder-width apart.","Engage your core and pull your shoulder blades down and back.","Bend your knees and tuck them towards your chest.","Simultaneously, lift your legs up and extend them straight out in front of you, keeping your body parallel to the ground.","Hold this position for as long as you can, aiming for a full front lever position.","To release, slowly lower your legs back down and return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"3297","name":"back lever","body_part":"back","target":"upper back","secondary_muscles":["biceps","forearms","core"],"equipment":"body weight","difficulty":"advanced","description":"The back lever is a challenging bodyweight exercise performed on a pull-up bar, requiring significant strength, balance, and body control. It targets the upper back and also engages the biceps, forearms, and core.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3297.gif","youtube_id":null,"instructions":["Start by hanging from a pull-up bar with an overhand grip, hands slightly wider than shoulder-width apart.","Engage your core and pull your shoulder blades down and back.","Bend your knees and tuck them towards your chest.","Slowly lift your legs up, keeping them straight, until your body is parallel to the ground.","Hold this position for a few seconds, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"3298","name":"straddle planche","body_part":"waist","target":"abs","secondary_muscles":["shoulders","triceps","chest"],"equipment":"body weight","difficulty":"advanced","description":"The straddle planche is an advanced bodyweight exercise that targets the abs while also engaging the shoulders, triceps, and chest. It requires significant core strength, balance, and coordination to hold the body parallel to the ground with only the hands supporting the weight.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3298.gif","youtube_id":null,"instructions":["Start in a push-up position with your hands shoulder-width apart and your feet spread wide apart.","Engage your core and slowly shift your weight forward, bringing your shoulders over your hands.","Bend your elbows and lower your body towards the ground, keeping your elbows close to your sides.","Pause for a moment at the bottom, then push through your hands to straighten your arms and lift your body back up to the starting position.","Repeat for the desired number of repetitions."]},{"id":"3299","name":"full planche","body_part":"waist","target":"abs","secondary_muscles":["shoulders","chest","triceps"],"equipment":"body weight","difficulty":"advanced","description":"The full planche is an advanced bodyweight exercise that requires significant core strength, balance, and upper body control. It involves holding your body parallel to the ground, supported only by your hands, with no other contact points.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3299.gif","youtube_id":null,"instructions":["Start in a push-up position with your hands shoulder-width apart and your fingers pointing forward.","Engage your core and slowly shift your weight forward, lifting your feet off the ground.","Continue shifting your weight forward until your body is parallel to the ground, balancing on your hands.","Hold this position for as long as you can, maintaining a straight body line.","Slowly lower your feet back to the ground and return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"33","name":"barbell decline bench press","body_part":"chest","target":"pectorals","secondary_muscles":["triceps","shoulders"],"equipment":"barbell","difficulty":"intermediate","description":"The barbell decline bench press is a compound exercise targeting the lower portion of the pectoral muscles. It is performed on a decline bench, requiring the lifter to press a barbell upward from a declined position, engaging the chest, triceps, and shoulders.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0033.gif","youtube_id":null,"instructions":["Lie on a decline bench with your feet secured and your head lower than your hips.","Grasp the barbell with an overhand grip slightly wider than shoulder-width apart.","Unrack the barbell and lower it slowly towards your chest, keeping your elbows tucked in.","Pause for a moment at the bottom, then push the barbell back up to the starting position.","Repeat for the desired number of repetitions."]},{"id":"330","name":"dumbbell incline triceps extension","body_part":"upper arms","target":"triceps","secondary_muscles":["shoulders"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell incline triceps extension is an isolation exercise targeting the triceps, performed on an incline bench to increase the stretch and activation of the triceps muscles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0330.gif","youtube_id":null,"instructions":["Sit on an incline bench with a dumbbell in each hand, palms facing inwards.","Extend your arms fully overhead, keeping your elbows close to your head.","Lower the dumbbells behind your head by bending your elbows, keeping your upper arms stationary.","Pause for a moment, then raise the dumbbells back to the starting position by extending your arms.","Repeat for the desired number of repetitions."]},{"id":"3300","name":"lean planche","body_part":"waist","target":"abs","secondary_muscles":["shoulders","chest","triceps"],"equipment":"body weight","difficulty":"advanced","description":"The lean planche is a challenging bodyweight exercise that targets the abdominal muscles while also engaging the shoulders, chest, and triceps. It requires significant core strength, balance, and upper body control as you lean your body forward in a plank-like position, shifting your weight past your hands.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3300.gif","youtube_id":null,"instructions":["Start in a push-up position with your hands shoulder-width apart and your body straight.","Engage your core and slowly shift your weight forward, bringing your shoulders past your hands.","Keep your elbows slightly bent and your body straight as you lean forward.","Hold this position for a few seconds, then slowly return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"3301","name":"frog planche","body_part":"waist","target":"abs","secondary_muscles":["shoulders","chest","triceps"],"equipment":"body weight","difficulty":"advanced","description":"The frog planche is an advanced bodyweight exercise that targets the abs while also engaging the shoulders, chest, and triceps. It requires significant core strength, balance, and upper body control.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3301.gif","youtube_id":null,"instructions":["Start in a push-up position with your hands shoulder-width apart and your feet together.","Bend your elbows and lower your body towards the ground, keeping your back straight.","As you lower your body, lift your feet off the ground and bring your knees towards your chest.","Hold this position for a few seconds, then extend your legs back out and push yourself back up to the starting position.","Repeat for the desired number of repetitions."]},{"id":"3302","name":"handstand","body_part":"upper arms","target":"triceps","secondary_muscles":["shoulders","core"],"equipment":"body weight","difficulty":"advanced","description":"The handstand is a bodyweight exercise that primarily targets the triceps, while also engaging the shoulders and core. It requires significant balance, strength, and coordination to perform safely and effectively.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3302.gif","youtube_id":null,"instructions":["Find an open space with enough room to perform a handstand.","Place your hands on the ground shoulder-width apart, fingers pointing forward.","Kick your legs up towards the wall, using your core and shoulders to maintain balance.","Once in a handstand position, engage your triceps to support your body weight.","Hold the handstand for as long as you can maintain balance.","To come down, slowly lower your legs back to the ground.","Repeat for the desired number of repetitions."]},{"id":"3303","name":"flag","body_part":"waist","target":"abs","secondary_muscles":["obliques","shoulders"],"equipment":"body weight","difficulty":"advanced","description":"The flag is an advanced bodyweight exercise that targets the abs and requires significant core, shoulder, and grip strength. It involves gripping a vertical pole and lifting the body horizontally, holding a straight line parallel to the ground.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3303.gif","youtube_id":null,"instructions":["Start by gripping a vertical pole with both hands, palms facing each other, and arms fully extended.","Engage your core and lift your legs off the ground, keeping them straight.","Using your core and upper body strength, raise your legs until they are parallel to the ground.","Hold this position for as long as you can, maintaining a straight body line.","Slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"3304","name":"skin the cat","body_part":"back","target":"upper back","secondary_muscles":["shoulders","core"],"equipment":"body weight","difficulty":"advanced","description":"Skin the cat is a gymnastic movement performed on a bar, where you hang, lift your legs over your head, rotate your body through your arms, and then return to the starting position. It requires significant upper body and core strength, as well as shoulder mobility and coordination.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3304.gif","youtube_id":null,"instructions":["Start by hanging from a bar with your arms fully extended and your body relaxed.","Engage your core and lift your legs up, bringing your knees towards your chest.","Continue to lift your legs up and over your head, allowing your body to pass through the arms.","Once your legs are fully extended over your head, begin to lower them back down towards the starting position.","As you lower your legs, allow your body to pass back through the arms until you are hanging with your arms fully extended again.","Repeat for the desired number of repetitions."]},{"id":"3305","name":"barbell thruster","body_part":"shoulders","target":"delts","secondary_muscles":["quadriceps","glutes","hamstrings","core"],"equipment":"barbell","difficulty":"intermediate","description":"The barbell thruster is a compound exercise that combines a front squat with an overhead press, targeting the shoulders and engaging multiple muscle groups for strength and power.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3305.gif","youtube_id":null,"instructions":["Start by standing with your feet shoulder-width apart, holding a barbell at shoulder height with an overhand grip.","Lower into a squat position by bending your knees and pushing your hips back.","As you reach the bottom of the squat, explosively drive through your heels to stand up, simultaneously pressing the barbell overhead.","Lower the barbell back to shoulder height as you lower back into the squat position.","Repeat for the desired number of repetitions."]},{"id":"3306","name":"strongman fingal's fingers","body_part":"upper legs","target":"glutes","secondary_muscles":["hamstrings","quads","calves","delts","traps","forearms"],"equipment":"leverage machine","difficulty":"advanced","description":"Lift a hinged strongman pole (Fingal’s Finger) from the ground and drive it up using leg and hip extension, then press and walk it past vertical to tip it over. Reset on the opposite side and repeat for reps or distance.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3306.gif","youtube_id":null,"instructions":["Stand with feet shoulder-width at the free end of the hinged pole, shins close to the implement.","Grip the end securely with both hands underneath, chest up, shoulders packed, and spine neutral.","Brace your core, pull the pole tight to your body, and initiate the lift by driving through your heels, extending knees and hips together.","Keep the implement close as it rises past the knees; re-adjust your hand position if needed to transition from lifting to pushing.","Continue hip and knee extension while driving the pole upward; as it nears vertical, step forward under it and press through the arms to guide it over.","Finish by tipping the pole past its balance point under control, letting it fall safely to the opposite side.","Reset your stance on the new side, re-brace, and repeat. Avoid jerking, twisting, or rounding your back at any point."]},{"id":"3307","name":"strongman keg toss","body_part":"upper legs","target":"glutes","secondary_muscles":["hamstrings","quads","calves","delts","traps","abs"],"equipment":"weighted","difficulty":"advanced","description":"Explosive toss of a weighted keg using a powerful hip hinge and triple extension to project the load overhead. Set up in a shoulder‑width stance, hinge to load the hips, then drive upward to release the keg while keeping a neutral spine.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3307.gif","youtube_id":null,"instructions":["Clear a safe landing zone in front of you and stand shoulder‑width apart with the keg slightly in front, gripping the rims/sides securely.","Hinge at the hips with a flat back, soften the knees, and brace your abs as you pull the keg to swing slightly between your legs.","Drive through the floor and extend hips, knees, and ankles explosively, squeezing the glutes as the keg travels upward.","Keep the chest tall, shrug, and guide the keg overhead with straightening arms; release when the keg is on a rising arc slightly above eye level.","Finish tall with hips and knees locked out, keeping your body out of the keg’s path.","Let the keg land in the clear area, then walk to it and reset your stance and grip for the next repetition."]},{"id":"331","name":"dumbbell incline twisted flyes","body_part":"chest","target":"pectorals","secondary_muscles":["shoulders","triceps"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell incline twisted flye is a chest exercise performed on an incline bench, targeting the upper pectorals with an added wrist rotation for increased muscle activation.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0331.gif","youtube_id":null,"instructions":["Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, palms facing each other.","Lie back on the bench and press the dumbbells up to the starting position, directly above your chest, with your arms extended.","Lower the dumbbells out to the sides in a wide arc until you feel a stretch in your chest.","As you lower the dumbbells, rotate your wrists so that your palms face forward at the bottom of the movement.","Reverse the motion and bring the dumbbells back up to the starting position, squeezing your chest muscles together at the top.","Repeat for the desired number of repetitions."]},{"id":"3312","name":"weighted muscle up (on bar)","body_part":"back","target":"lats","secondary_muscles":["biceps","triceps","shoulders","forearms"],"equipment":"weighted","difficulty":"advanced","description":"The weighted muscle up (on bar) is an advanced calisthenics exercise that combines a pull-up with a dip, performed while adding extra weight. It targets the lats and also works the biceps, triceps, shoulders, and forearms. This movement requires significant upper body strength, coordination, and technique, especially when performed with additional weight.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3312.gif","youtube_id":null,"instructions":["Start by hanging from a pull-up bar with your palms facing away from you and your hands slightly wider than shoulder-width apart.","Engage your core and pull your shoulder blades down and back.","Bend your elbows and pull your chest towards the bar, keeping your body straight.","Once your chest reaches the bar, push down with your hands and drive your elbows back, lifting your body above the bar.","Pause at the top of the movement, then slowly lower yourself back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"3313","name":"weighted straight bar dip","body_part":"chest","target":"pectorals","secondary_muscles":["triceps","shoulders"],"equipment":"weighted","difficulty":"advanced","description":"The weighted straight bar dip is a compound chest exercise performed on parallel bars with added weight for increased resistance. It primarily targets the pectorals, with significant involvement of the triceps and shoulders.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3313.gif","youtube_id":null,"instructions":["Position yourself between parallel bars with your arms fully extended and your body straight.","Lower your body by bending your elbows until your upper arms are parallel to the ground.","Pause for a moment, then push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."]},{"id":"3314","name":"straddle maltese","body_part":"waist","target":"abs","secondary_muscles":["shoulders","chest"],"equipment":"body weight","difficulty":"advanced","description":"The straddle maltese is an advanced bodyweight exercise performed on rings, targeting the abs with significant involvement of the shoulders and chest. It requires exceptional core strength, shoulder stability, and body control, making it a challenging movement for experienced athletes.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3314.gif","youtube_id":null,"instructions":["Start by hanging from a pair of rings with your arms fully extended and your body in a straight line.","Spread your legs wide apart, forming a straddle position.","Engage your core and slowly lower your body until your arms are parallel to the ground.","Hold this position for a few seconds, then push yourself back up to the starting position.","Repeat for the desired number of repetitions."]},{"id":"3315","name":"full maltese","body_part":"waist","target":"abs","secondary_muscles":["shoulders","chest"],"equipment":"body weight","difficulty":"advanced","description":"The full maltese is an advanced bodyweight exercise that primarily targets the abs, with significant involvement of the shoulders and chest. It requires a high degree of core strength, balance, and body control, making it a challenging movement for most practitioners.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3315.gif","youtube_id":null,"instructions":["Start by standing with your feet shoulder-width apart and your arms extended straight out to the sides.","Slowly lean forward, keeping your arms straight, until your upper body is parallel to the ground.","Engage your core and hold this position for a few seconds.","Return to the starting position by pushing through your feet and standing back up.","Repeat for the desired number of repetitions."]},{"id":"3316","name":"barbell weightlifting complex","body_part":"upper legs","target":"quads","secondary_muscles":["glutes","hamstrings","calves","delts","traps","abs"],"equipment":"olympic barbell","difficulty":"advanced","description":"Using a light-to-moderate Olympic barbell, perform a continuous sequence of a power clean to the front rack, one front squat, and a push press before returning the bar to the floor. Maintain a neutral spine and keep the bar close to the body throughout.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3316.gif","youtube_id":null,"instructions":["Stand with feet hip-width, bar over midfoot, hands just outside legs; brace and set a neutral spine.","Initiate a power clean: push through the floor, extend hips and knees violently, shrug, then pull under and catch the bar on the shoulders with elbows high.","Set feet shoulder-width and perform one controlled front squat to comfortable depth, keeping torso upright and knees tracking over toes; stand tall.","Dip 2-3 inches by bending knees and hips together, then drive up and press the bar overhead to full lockout (push press) with ribs down.","Lower the bar back to the front rack, then to the hips, and guide it to the floor with control to reset.","Repeat the sequence for the prescribed reps, stopping if bar speed slows or form degrades."]},{"id":"3317","name":"strongman car flip","body_part":"upper legs","target":"glutes","secondary_muscles":["hamstrings","quads","calves","traps","upper back","forearms"],"equipment":"tire","difficulty":"advanced","description":"Face the front edge of a heavy flip implement and squat to hook your hands under the lip. Drive through your legs and hips to lift, then step and push the object over under control.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3317.gif","youtube_id":null,"instructions":["Stand facing the object with feet just outside shoulder width and toes slightly out; brace your core and set a neutral spine.","Hinge and squat to reach under the edge with a mixed or supinated grip, keeping the object close to your shins and chest up.","Pack the lats and take the slack out, then drive through your heels to extend knees and hips together to bring the object to mid‑thigh.","As it rises, step one foot forward and transition one or both hands to a pushing position on the edge.","Continue driving hips forward and use your legs and chest to tip the object past its balance point—do not curl with the arms.","Push it over and guide the descent, keeping fingers clear of the landing zone.","Reset your stance, re-brace, and repeat for the next rep, avoiding rounding or twisting under load."]},{"id":"3318","name":"swing 360","body_part":"cardio","target":"cardiovascular system","secondary_muscles":["shoulders","core"],"equipment":"body weight","difficulty":"beginner","description":"The swing 360 is a dynamic bodyweight exercise that targets the cardiovascular system while also engaging the shoulders and core. It involves swinging the arms in a circular motion while rotating the torso, making it a great movement for increasing heart rate and improving coordination.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3318.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and knees slightly bent.","Hold your arms straight out in front of you, parallel to the ground.","Engage your core and swing your arms in a circular motion, rotating your torso as you do so.","Continue the circular motion, swinging your arms and rotating your torso for the desired number of repetitions.","Remember to breathe throughout the exercise."]},{"id":"332","name":"dumbbell iron cross","body_part":"shoulders","target":"delts","secondary_muscles":["triceps","chest"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell iron cross is a shoulder exercise that targets the deltoids by raising the arms out to the sides while holding dumbbells, forming a T shape with the body. It also engages the triceps and chest as secondary muscles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0332.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand at your sides.","Raise your arms out to the sides until they are parallel to the ground, forming a T shape with your body.","Pause for a moment, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"3327","name":"full planche push-up","body_part":"chest","target":"pectorals","secondary_muscles":["shoulders","triceps","core"],"equipment":"body weight","difficulty":"advanced","description":"The full planche push-up is an advanced bodyweight exercise that targets the pectorals, shoulders, triceps, and core. It requires significant strength, balance, and coordination as you perform a push-up while balancing your entire body off the ground with only your hands.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3327.gif","youtube_id":null,"instructions":["Start in a push-up position with your hands placed slightly wider than shoulder-width apart.","Engage your core and lower your body down towards the ground, keeping your elbows close to your sides.","As you lower yourself, lean your body forward and lift your feet off the ground, balancing on your hands.","Continue to lower your body until your chest is just above the ground.","Push through your hands and extend your arms to lift your body back up to the starting position.","Maintain a straight line from your head to your heels throughout the movement.","Repeat for the desired number of repetitions."]},{"id":"333","name":"dumbbell kickback","body_part":"upper arms","target":"triceps","secondary_muscles":["shoulders"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell kickback is an isolation exercise targeting the triceps. It involves extending the arm backward while keeping the upper arm stationary, effectively working the triceps and engaging the shoulders as secondary muscles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0333.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and hold a dumbbell in each hand.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Bring your upper arms close to your sides, with your elbows bent at a 90-degree angle.","Extend your arms straight back, squeezing your triceps at the top of the movement.","Pause for a moment, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"334","name":"dumbbell lateral raise","body_part":"shoulders","target":"delts","secondary_muscles":["traps"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell lateral raise is an isolation exercise that targets the deltoid muscles, particularly the lateral (side) head. It is commonly used to build shoulder width and strength.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0334.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing your body.","Keep your back straight and engage your core.","Raise your arms out to the sides until they are parallel to the floor, keeping a slight bend in your elbows.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"335","name":"dumbbell lateral to front raise","body_part":"shoulders","target":"delts","secondary_muscles":["trapezius","biceps"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell lateral to front raise is a shoulder exercise that targets the deltoids by combining both lateral and front raises in one movement. It also engages the trapezius and biceps as secondary muscles. This exercise helps build shoulder strength and stability.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0335.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing your body.","Keep your back straight and engage your core.","Raise your arms out to the sides until they are parallel to the ground, keeping a slight bend in your elbows.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Next, raise your arms in front of you until they are parallel to the ground, again keeping a slight bend in your elbows.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"336","name":"dumbbell lunge","body_part":"upper legs","target":"glutes","secondary_muscles":["quadriceps","hamstrings","calves"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell lunge is a lower body exercise that targets the glutes, quadriceps, hamstrings, and calves. It involves stepping forward into a lunge position while holding dumbbells, then returning to the starting position and alternating legs.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0336.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand.","Take a step forward with your right foot, lowering your body into a lunge position.","Keep your back straight and your chest up as you lower your body.","Push through your right heel to return to the starting position.","Repeat with your left leg.","Alternate legs for the desired number of repetitions."]},{"id":"3360","name":"bear crawl","body_part":"cardio","target":"cardiovascular system","secondary_muscles":["core","shoulders","triceps"],"equipment":"body weight","difficulty":"intermediate","description":"The bear crawl is a full-body movement that targets the cardiovascular system while also engaging the core, shoulders, and triceps. It involves crawling on all fours with knees off the ground, requiring coordination and endurance.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3360.gif","youtube_id":null,"instructions":["Start on all fours with your hands directly under your shoulders and your knees directly under your hips.","Lift your knees slightly off the ground, keeping your back flat and your core engaged.","Move your right hand and left foot forward simultaneously, followed by your left hand and right foot.","Continue crawling forward, alternating your hand and foot movements.","Maintain a steady pace and keep your core tight throughout the exercise.","Continue for the desired distance or time."]},{"id":"3361","name":"skater hops","body_part":"cardio","target":"cardiovascular system","secondary_muscles":["quadriceps","hamstrings","glutes","calves"],"equipment":"body weight","difficulty":"intermediate","description":"Skater hops are a dynamic, lateral jumping exercise that targets the cardiovascular system while also engaging the lower body muscles. The movement mimics a speed skater's motion, helping to improve agility, coordination, and cardiovascular endurance.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3361.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart.","Bend your knees slightly and jump to the right, landing on your right foot.","As you land, swing your left leg behind your right leg and tap the ground with your left toes.","Immediately jump to the left, landing on your left foot.","As you land, swing your right leg behind your left leg and tap the ground with your right toes.","Continue alternating sides, jumping and tapping the ground with each leg.","Repeat for the desired number of repetitions."]},{"id":"337","name":"dumbbell lying extension (across face)","body_part":"upper arms","target":"triceps","secondary_muscles":["shoulders"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell lying extension (across face) is an isolation exercise targeting the triceps, performed lying on a bench while extending a dumbbell in an arc behind the head.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0337.gif","youtube_id":null,"instructions":["Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.","Hold a dumbbell with both hands and extend your arms straight up above your chest, palms facing each other.","Keeping your upper arms stationary, slowly lower the dumbbell in an arc behind your head until your forearms are parallel to the ground.","Pause for a moment, then contract your triceps to bring the dumbbell back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"338","name":"dumbbell lying elbow press","body_part":"upper arms","target":"triceps","secondary_muscles":["chest","shoulders"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell lying elbow press is an upper arm exercise targeting the triceps, performed while lying on a bench and pressing dumbbells by extending the elbows.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0338.gif","youtube_id":null,"instructions":["Lie flat on a bench with a dumbbell in each hand, palms facing each other and arms extended straight up over your chest.","Lower the dumbbells towards your shoulders by bending your elbows, keeping your upper arms stationary.","Pause for a moment at the bottom, then press the dumbbells back up to the starting position by extending your elbows.","Repeat for the desired number of repetitions."]},{"id":"339","name":"dumbbell lying femoral","body_part":"upper legs","target":"hamstrings","secondary_muscles":["glutes"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell lying femoral exercise targets the hamstrings and also works the glutes. It involves lying on your back, bending your knees, and using a dumbbell for resistance as you bring your feet towards your glutes.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0339.gif","youtube_id":null,"instructions":["Lie flat on your back with your legs extended and a dumbbell resting on your lower abdomen.","Bend your knees and bring the dumbbell towards your glutes, keeping your feet flat on the ground.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"34","name":"barbell decline bent arm pullover","body_part":"back","target":"lats","secondary_muscles":["triceps","chest"],"equipment":"barbell","difficulty":"intermediate","description":"The barbell decline bent arm pullover is a compound exercise primarily targeting the lats, performed on a decline bench with a barbell. It also engages the triceps and chest as secondary muscles. The movement requires good control and strength to safely lower and lift the barbell over the head while maintaining proper form.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0034.gif","youtube_id":null,"instructions":["Lie down on a decline bench with your head lower than your hips and your feet secured.","Hold a barbell with a pronated grip (palms facing away from you) and extend your arms straight above your chest.","Lower the barbell behind your head in a controlled manner, keeping your arms slightly bent.","Pause for a moment, then raise the barbell back to the starting position by contracting your lats.","Repeat for the desired number of repetitions."]},{"id":"340","name":"dumbbell lying hammer press","body_part":"chest","target":"pectorals","secondary_muscles":["triceps","shoulders"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell lying hammer press is a chest exercise performed on a bench with dumbbells held in a neutral grip (palms facing each other). It targets the pectorals while also engaging the triceps and shoulders.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0340.gif","youtube_id":null,"instructions":["Lie flat on a bench with a dumbbell in each hand, palms facing each other and arms extended straight up.","Lower the dumbbells to the sides of your chest, keeping your elbows at a 90-degree angle.","Press the dumbbells back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]},{"id":"341","name":"dumbbell lying one arm deltoid rear","body_part":"shoulders","target":"delts","secondary_muscles":["trapezius","rhomboids"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell lying one arm deltoid rear is an isolation exercise targeting the rear deltoids, performed lying face down on a bench and raising a dumbbell to activate the back of the shoulder.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0341.gif","youtube_id":null,"instructions":["Lie face down on a flat bench with a dumbbell in one hand, palm facing inwards.","Extend your arm straight down towards the floor, keeping it close to your body.","Raise your arm up and back, squeezing your shoulder blade towards your spine.","Pause for a moment at the top, then slowly lower your arm back down to the starting position.","Repeat for the desired number of repetitions, then switch arms."]},{"id":"3418","name":"l-pull-up","body_part":"back","target":"lats","secondary_muscles":["biceps","forearms"],"equipment":"body weight","difficulty":"advanced","description":"The L-pull-up is a challenging bodyweight exercise that targets the lats while also engaging the core, biceps, and forearms. It requires the lifter to maintain an 'L' position with the legs extended straight out in front, parallel to the ground, throughout the pull-up movement.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3418.gif","youtube_id":null,"instructions":["Grab the pull-up bar with an overhand grip, slightly wider than shoulder-width apart.","Hang with your arms fully extended and your body straight.","Engage your lats and biceps to pull your body up towards the bar, keeping your elbows close to your body.","Continue pulling until your chin is above the bar.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"3419","name":"l-sit on floor","body_part":"waist","target":"abs","secondary_muscles":["hip flexors"],"equipment":"body weight","difficulty":"advanced","description":"The L-sit on floor is a challenging core exercise that targets the abdominal muscles and hip flexors. It requires significant core strength, balance, and coordination to lift and hold the legs parallel to the floor while supporting the body with the arms.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3419.gif","youtube_id":null,"instructions":["Sit on the floor with your legs extended in front of you.","Place your hands on the floor beside your hips, fingers pointing forward.","Engage your core and lift your legs off the ground, keeping them straight.","Try to bring your legs parallel to the floor, forming an 'L' shape with your body.","Hold this position for as long as you can.","Slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"342","name":"dumbbell lying one arm press v. 2","body_part":"chest","target":"pectorals","secondary_muscles":["triceps","shoulders"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell lying one arm press v. 2 is a unilateral chest exercise performed on a bench, focusing on the pectorals while also engaging the triceps and shoulders. It requires stability and coordination due to the single-arm movement.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0342.gif","youtube_id":null,"instructions":["Lie flat on a bench with your back supported and feet flat on the ground.","Hold a dumbbell in one hand with your palm facing towards your feet.","Extend your arm straight up towards the ceiling, keeping your elbow slightly bent.","Slowly lower the dumbbell down towards your chest, keeping your elbow close to your body.","Pause for a moment at the bottom, then push the dumbbell back up to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]},{"id":"3420","name":"v-sit on floor","body_part":"waist","target":"abs","secondary_muscles":["hip flexors"],"equipment":"body weight","difficulty":"advanced","description":"The V-sit on floor is a core exercise that targets the abdominal muscles and also engages the hip flexors. It requires balance, core strength, and coordination as you hold your body in a V-shape, balancing on your tailbone.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3420.gif","youtube_id":null,"instructions":["Sit on the floor with your legs extended in front of you.","Lean back slightly and lift your legs off the ground, keeping them straight.","Simultaneously, lift your upper body off the ground and reach your arms towards your legs.","Hold this position for a few seconds, then slowly lower your upper body and legs back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"343","name":"dumbbell lying one arm press","body_part":"chest","target":"pectorals","secondary_muscles":["triceps","shoulders"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell lying one arm press is a unilateral chest exercise performed on a bench, focusing on the pectorals while also engaging the triceps and shoulders. It challenges stability and coordination due to the single-arm movement.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0343.gif","youtube_id":null,"instructions":["Lie flat on a bench with a dumbbell in one hand and your feet flat on the ground.","Hold the dumbbell at shoulder level with your palm facing forward.","Press the dumbbell upward until your arm is fully extended.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]},{"id":"3433","name":"swimmer kicks v. 2 (male)","body_part":"upper legs","target":"glutes","secondary_muscles":["hamstrings","quadriceps","calves"],"equipment":"body weight","difficulty":"intermediate","description":"Swimmer kicks v. 2 (male) is a bodyweight exercise targeting the glutes, with secondary emphasis on the hamstrings, quadriceps, and calves. It involves lying face down and performing a flutter kick motion with the legs while keeping the chest and legs elevated off the ground.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3433.gif","youtube_id":null,"instructions":["Lie face down on a mat with your arms extended overhead.","Engage your core and lift your chest and legs off the ground simultaneously.","Kick your legs up and down in a fluttering motion, as if you were swimming.","Continue kicking for the desired number of repetitions.","Lower your chest and legs back down to the starting position."]},{"id":"344","name":"dumbbell lying one arm pronated triceps extension","body_part":"upper arms","target":"triceps","secondary_muscles":["shoulders"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell lying one arm pronated triceps extension is an isolation exercise targeting the triceps, performed lying on a bench with a single dumbbell in a pronated (palm down) grip. It emphasizes triceps strength and stability, with some involvement of the shoulders.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0344.gif","youtube_id":null,"instructions":["Lie flat on a bench with your back and head supported, and your feet flat on the ground.","Hold a dumbbell in one hand with your palm facing down, and extend your arm straight up above your shoulder.","Keeping your upper arm stationary, slowly lower the dumbbell behind your head by bending your elbow.","Pause for a moment at the bottom, then extend your arm back up to the starting position.","Repeat for the desired number of repetitions, then switch arms."]},{"id":"345","name":"dumbbell lying one arm rear lateral raise","body_part":"shoulders","target":"delts","secondary_muscles":["traps","rhomboids"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell lying one arm rear lateral raise is an isolation exercise targeting the rear deltoids, performed lying face down on a bench. It helps develop shoulder strength and stability, with additional engagement of the traps and rhomboids.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0345.gif","youtube_id":null,"instructions":["Lie face down on a flat bench with a dumbbell in one hand, hanging towards the floor.","Keep your arm straight and lift the dumbbell out to the side, away from your body.","Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]},{"id":"346","name":"dumbbell lying one arm supinated triceps extension","body_part":"upper arms","target":"triceps","secondary_muscles":["forearms"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell lying one arm supinated triceps extension is an isolation exercise targeting the triceps, performed lying on a bench with a single dumbbell in an underhand grip.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0346.gif","youtube_id":null,"instructions":["Lie flat on a bench with your back and head supported, and your feet flat on the ground.","Hold a dumbbell in one hand with an underhand grip, and extend your arm straight up above your shoulder.","Keeping your upper arm stationary, slowly lower the dumbbell behind your head by bending your elbow.","Pause for a moment at the bottom, then extend your arm back up to the starting position.","Repeat for the desired number of repetitions, then switch arms."]},{"id":"347","name":"dumbbell lying pronation","body_part":"lower arms","target":"forearms","secondary_muscles":["biceps","shoulders"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell lying pronation is an exercise targeting the forearms, specifically focusing on pronation strength. It is performed lying face down on a bench, holding dumbbells, and rotating the wrists to work the forearm muscles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0347.gif","youtube_id":null,"instructions":["Lie flat on a bench with your chest facing down and your arms extended straight down, holding a dumbbell in each hand.","Rotate your palms so they are facing up.","Keeping your upper arms stationary, exhale and curl the dumbbells as you rotate your palms to face down.","Inhale and slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"3470","name":"forward lunge (male)","body_part":"upper legs","target":"glutes","secondary_muscles":["quadriceps","hamstrings","calves"],"equipment":"body weight","difficulty":"beginner","description":"The forward lunge is a bodyweight exercise targeting the glutes, with secondary emphasis on the quadriceps, hamstrings, and calves. It involves stepping forward into a lunge position and returning to standing, alternating legs.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3470.gif","youtube_id":null,"instructions":["Stand with your feet hip-width apart and hands on your hips.","Take a big step forward with your right foot, lowering your body into a lunge position.","Bend your right knee to about 90 degrees, keeping your knee aligned with your ankle.","Push off with your right foot and return to the starting position.","Repeat with your left leg, alternating sides for the desired number of repetitions."]},{"id":"348","name":"dumbbell lying rear lateral raise","body_part":"shoulders","target":"delts","secondary_muscles":["traps","rhomboids"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell lying rear lateral raise is an isolation exercise targeting the rear deltoids, performed lying face down on a bench to minimize momentum and maximize shoulder engagement.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0348.gif","youtube_id":null,"instructions":["Lie face down on a flat bench with a dumbbell in each hand, palms facing each other.","Extend your arms straight down towards the floor, keeping a slight bend in your elbows.","Engaging your shoulder muscles, lift your arms out to the sides until they are parallel to the floor.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"349","name":"dumbbell lying supination","body_part":"lower arms","target":"forearms","secondary_muscles":["biceps","shoulders"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell lying supination is an isolation exercise targeting the forearms, specifically focusing on the supinator muscles. It also engages the biceps and shoulders as secondary muscles. The movement involves curling dumbbells while lying on a bench, emphasizing forearm rotation and strength.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0349.gif","youtube_id":null,"instructions":["Lie flat on a bench with your feet flat on the ground.","Hold a dumbbell in each hand with your palms facing up and your arms fully extended.","Keeping your upper arms stationary, curl the dumbbells towards your shoulders by contracting your forearms.","Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"35","name":"barbell decline close grip to skull press","body_part":"upper arms","target":"triceps","secondary_muscles":["chest","shoulders"],"equipment":"barbell","difficulty":"intermediate","description":"The barbell decline close grip to skull press is a compound exercise targeting the triceps, performed on a decline bench with a close grip on the barbell. It combines elements of a close grip press and a skull crusher, challenging both triceps strength and stability.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0035.gif","youtube_id":null,"instructions":["Lie on a decline bench with your head lower than your feet and hold a barbell with a close grip.","Lower the barbell towards your forehead by bending your elbows, keeping your upper arms stationary.","Pause for a moment, then extend your arms to press the barbell back up to the starting position.","Repeat for the desired number of repetitions."]},{"id":"350","name":"dumbbell lying supine curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell lying supine curl is an isolation exercise targeting the biceps, performed while lying flat on a bench. It emphasizes strict form and minimizes cheating by stabilizing the body.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0350.gif","youtube_id":null,"instructions":["Lie flat on a bench with a dumbbell in each hand, palms facing up and arms fully extended.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"351","name":"dumbbell lying triceps extension","body_part":"upper arms","target":"triceps","secondary_muscles":["shoulders"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell lying triceps extension is an isolation exercise targeting the triceps, performed while lying on a bench and extending the arms with dumbbells.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0351.gif","youtube_id":null,"instructions":["Lie flat on a bench with a dumbbell in each hand, palms facing each other.","Extend your arms straight up over your chest, keeping your elbows close to your body.","Lower the dumbbells down towards your forehead, bending your elbows.","Pause for a moment, then extend your arms back up to the starting position.","Repeat for the desired number of repetitions."]},{"id":"352","name":"dumbbell neutral grip bench press","body_part":"upper arms","target":"triceps","secondary_muscles":["chest","shoulders"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell neutral grip bench press is a pressing exercise performed on a bench using dumbbells with palms facing each other. It primarily targets the triceps, with secondary emphasis on the chest and shoulders.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0352.gif","youtube_id":null,"instructions":["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Hold a dumbbell in each hand with a neutral grip (palms facing each other) and your arms extended straight up over your chest.","Slowly lower the dumbbells down towards your chest, keeping your elbows close to your body.","Pause for a moment at the bottom, then push the dumbbells back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]},{"id":"3523","name":"glute bridge two legs on bench (male)","body_part":"upper legs","target":"glutes","secondary_muscles":["hamstrings","core"],"equipment":"body weight","difficulty":"beginner","description":"The glute bridge with two legs on a bench is a bodyweight exercise that targets the glutes, with secondary emphasis on the hamstrings and core. It involves lifting the hips off the ground while the upper back rests on a bench, creating a straight line from knees to shoulders.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3523.gif","youtube_id":null,"instructions":["Sit on the edge of a bench with your back against it and your feet flat on the ground.","Place your hands on the bench beside your hips for support.","Engage your glutes and hamstrings, then lift your hips off the bench until your body forms a straight line from your knees to your shoulders.","Pause for a moment at the top, then slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"353","name":"dumbbell one arm concentration curl (on stability ball)","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell one arm concentration curl (on stability ball) is an isolation exercise targeting the biceps, performed while seated on a stability ball to increase core engagement and balance requirements.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0353.gif","youtube_id":null,"instructions":["Sit on a stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Hold a dumbbell in one hand with your palm facing up and your arm extended down towards the floor.","Rest your elbow on the inside of your thigh, just above the knee.","Keeping your upper arm stationary, exhale and curl the dumbbell up towards your shoulder while contracting your biceps.","Pause for a moment at the top of the movement, then inhale and slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch arms and repeat."]},{"id":"3533","name":"quads (bodyweight squat)","body_part":"upper legs","target":"quads","secondary_muscles":["hamstrings","glutes"],"equipment":"body weight","difficulty":"beginner","description":"A bodyweight squat exercise primarily targeting the quadriceps, with secondary activation of the hamstrings and glutes. This movement is fundamental for lower body strength and can be performed without equipment.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3533.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart.","Lower your body by bending your knees and pushing your hips back as if sitting on a chair.","Keep your chest up and your back straight.","Lower yourself until your thighs are parallel to the ground.","Push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"354","name":"dumbbell one arm kickback","body_part":"upper arms","target":"triceps","secondary_muscles":["shoulders"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell one arm kickback is an isolation exercise targeting the triceps. It is performed by hinging at the hips, keeping the back straight, and extending the arm back while holding a dumbbell.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0354.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and hold a dumbbell in your right hand.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Bring your right elbow up to your side, keeping it bent at a 90-degree angle.","Extend your right arm straight back, squeezing your triceps at the top of the movement.","Slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch sides."]},{"id":"3541","name":"dumbbell incline y-raise","body_part":"back","target":"upper back","secondary_muscles":["shoulders","rear deltoids"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell incline Y-raise is an upper back exercise performed on an incline bench, targeting the upper back, shoulders, and rear deltoids. It involves raising the arms in a Y shape while lying face down on an incline bench, emphasizing scapular stability and shoulder health.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3541.gif","youtube_id":null,"instructions":["Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, palms facing inwards.","Lean forward slightly and let your arms hang straight down, keeping a slight bend in your elbows.","Raise your arms out to the sides and up in a Y shape until they are parallel to the ground.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"3542","name":"dumbbell incline t-raise","body_part":"shoulders","target":"delts","secondary_muscles":["traps","rhomboids"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell incline T-raise is an isolation exercise targeting the deltoids, performed on an incline bench to emphasize shoulder and upper back muscles. It requires good form and control to avoid swinging and to properly engage the target muscles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3542.gif","youtube_id":null,"instructions":["Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, palms facing inwards.","Lean forward and let your arms hang straight down, perpendicular to the floor.","Keeping your arms straight, raise them out to the sides until they are parallel to the floor, forming a 'T' shape with your body.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"3543","name":"bodyweight drop jump squat","body_part":"upper legs","target":"glutes","secondary_muscles":["quadriceps","hamstrings","calves"],"equipment":"body weight","difficulty":"intermediate","description":"The bodyweight drop jump squat is a plyometric exercise targeting the glutes, with secondary emphasis on the quadriceps, hamstrings, and calves. It involves explosive jumping and rapid foot movement, challenging coordination, power, and lower body strength.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3543.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart.","Lower your body into a squat position by bending your knees and pushing your hips back.","Jump up explosively, extending your hips, knees, and ankles.","While in mid-air, quickly bring your feet together.","Land softly on the balls of your feet and immediately drop back into a squat position.","Repeat for the desired number of repetitions."]},{"id":"3544","name":"bodyweight incline side plank","body_part":"waist","target":"abs","secondary_muscles":["obliques","shoulders"],"equipment":"body weight","difficulty":"beginner","description":"The bodyweight incline side plank is a core stability exercise that targets the abs, with secondary emphasis on the obliques and shoulders. It involves holding a plank position on your side with your body supported by your forearm and feet, focusing on maintaining a straight line and engaging the core.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3544.gif","youtube_id":null,"instructions":["Start by lying on your side with your legs extended and stacked on top of each other.","Place your forearm on the ground directly below your shoulder, with your elbow bent at a 90-degree angle.","Engage your core and lift your hips off the ground, creating a straight line from your head to your feet.","Hold this position for the desired amount of time.","Lower your hips back down to the ground and repeat on the other side."]},{"id":"3545","name":"dumbbell incline alternate press","body_part":"chest","target":"pectorals","secondary_muscles":["shoulders","triceps"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell incline alternate press is a chest exercise performed on an incline bench, pressing dumbbells alternately to target the upper chest, shoulders, and triceps.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3545.gif","youtube_id":null,"instructions":["Sit on an incline bench with a dumbbell in each hand, resting on your thighs.","Lean back on the bench and use your thighs to help raise the dumbbells to shoulder height, palms facing forward.","Once at shoulder height, rotate your wrists so that the palms of your hands are facing forward.","Push the dumbbells up with your chest and shoulders, extending your arms fully.","Lower the dumbbells back down to the starting position, keeping your elbows slightly bent.","Repeat for the desired number of repetitions, alternating arms."]},{"id":"3546","name":"dumbbell seated alternate shoulder","body_part":"shoulders","target":"delts","secondary_muscles":["triceps","upper back"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell seated alternate shoulder press is a strength exercise targeting the deltoids, performed while seated and alternating arms for each press. It also engages the triceps and upper back as secondary muscles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3546.gif","youtube_id":null,"instructions":["Sit on a bench with your back straight and feet flat on the ground.","Hold a dumbbell in each hand, palms facing inwards, and raise them to shoulder height.","Press one dumbbell up overhead while keeping the other dumbbell at shoulder height.","Lower the raised dumbbell back to shoulder height while simultaneously pressing the other dumbbell up overhead.","Continue alternating between arms for the desired number of repetitions."]},{"id":"3547","name":"dumbbell seated biceps curl to shoulder press","body_part":"upper arms","target":"biceps","secondary_muscles":["shoulders"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell seated biceps curl to shoulder press is a compound exercise that targets the biceps and shoulders. It combines a biceps curl with a shoulder press, making it effective for building upper arm and shoulder strength.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3547.gif","youtube_id":null,"instructions":["Sit on a bench with your back straight and feet flat on the ground.","Hold a dumbbell in each hand with your palms facing forward and arms fully extended.","Keeping your elbows close to your sides, curl the dumbbells up towards your shoulders.","Once your forearms are vertical, rotate your wrists so that your palms are facing forward.","Press the dumbbells overhead until your arms are fully extended.","Lower the dumbbells back down to the starting position by reversing the movement.","Repeat for the desired number of repetitions."]},{"id":"3548","name":"dumbbell single arm overhead carry","body_part":"shoulders","target":"delts","secondary_muscles":["traps","core"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell single arm overhead carry is a functional exercise that targets the deltoids while also engaging the traps and core. It challenges shoulder stability, core strength, and coordination as you walk while holding a dumbbell overhead.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3548.gif","youtube_id":null,"instructions":["Stand tall with your feet shoulder-width apart, holding a dumbbell in one hand.","Raise the dumbbell overhead, fully extending your arm.","Engage your core and keep your back straight as you walk forward, maintaining the dumbbell overhead.","Continue walking for the desired distance or time.","Switch hands and repeat the exercise."]},{"id":"355","name":"dumbbell one arm lateral raise","body_part":"shoulders","target":"delts","secondary_muscles":["trapezius","triceps"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell one arm lateral raise is an isolation exercise targeting the deltoid muscles, particularly the lateral (side) head. It also engages the trapezius and triceps as secondary muscles. This exercise helps build shoulder strength and definition, and is commonly used in strength training routines.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0355.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, holding a dumbbell in one hand with your palm facing your body.","Keep your back straight and your core engaged throughout the exercise.","Raise the dumbbell to the side, keeping your arm straight and your palm facing down.","Continue lifting until your arm is parallel to the ground.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]},{"id":"3552","name":"quick feet v. 2","body_part":"upper legs","target":"quads","secondary_muscles":["calves","hamstrings"],"equipment":"body weight","difficulty":"beginner","description":"Quick feet v. 2 is a bodyweight exercise that involves rapidly moving your feet up and down in place, focusing on speed and agility. It targets the quadriceps while also engaging the calves and hamstrings.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3552.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and your arms by your sides.","Begin by rapidly moving your feet up and down, as if you were running in place.","Keep your movements quick and light, focusing on staying on the balls of your feet.","Continue for the desired duration or number of repetitions."]},{"id":"356","name":"dumbbell one arm lateral raise with support","body_part":"shoulders","target":"delts","secondary_muscles":["trapezius","rotator cuff"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell one arm lateral raise with support is an isolation exercise targeting the deltoid muscles of the shoulder. By using a support, it allows for better form and focus on the shoulder muscles, reducing the risk of using momentum or improper technique.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0356.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and hold a dumbbell in one hand, with your palm facing your body.","Place your other hand on a stable surface, such as a bench or wall, for support.","Keep your back straight and engage your core.","Raise the dumbbell out to the side, keeping your arm straight and your palm facing down.","Continue lifting until your arm is parallel to the ground.","Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch sides."]},{"id":"3560","name":"dumbbell standing alternate hammer curl and press","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms","shoulders"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell standing alternate hammer curl and press is a compound exercise that targets the biceps, forearms, and shoulders. It involves curling a dumbbell with a neutral grip and then pressing it overhead, alternating arms each repetition.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3560.gif","youtube_id":null,"instructions":["Stand up straight with a dumbbell in each hand, palms facing your body.","Keep your elbows close to your torso and your back straight.","Exhale and curl the dumbbell in your right hand towards your shoulder, keeping your upper arm stationary.","Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.","Inhale and slowly lower the dumbbell back to the starting position.","Repeat the curl with your left hand.","After completing the curl with your left hand, exhale and press the dumbbell in your right hand overhead.","Extend your arm fully and hold for a moment at the top.","Inhale and slowly lower the dumbbell back to the starting position.","Repeat the press with your left hand.","Continue alternating between curls and presses for the desired number of repetitions."]},{"id":"3561","name":"glute bridge march","body_part":"upper legs","target":"glutes","secondary_muscles":["hamstrings","quadriceps"],"equipment":"body weight","difficulty":"intermediate","description":"The glute bridge march is a bodyweight exercise that targets the glutes while also engaging the hamstrings and quadriceps. It involves holding a glute bridge position and alternately lifting each knee towards the chest in a marching motion, challenging hip stability and core strength.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3561.gif","youtube_id":null,"instructions":["Lie flat on your back with your knees bent and feet flat on the ground.","Engage your glutes and lift your hips off the ground, forming a straight line from your knees to your shoulders.","While keeping your hips lifted, lift one foot off the ground and bring your knee towards your chest.","Lower your foot back to the ground and repeat the movement with the other leg.","Continue alternating legs in a marching motion while maintaining the bridge position.","Repeat for the desired number of repetitions."]},{"id":"3562","name":"barbell glute bridge two legs on bench (male)","body_part":"upper legs","target":"glutes","secondary_muscles":["hamstrings","core"],"equipment":"barbell","difficulty":"intermediate","description":"The barbell glute bridge with two legs on a bench is a compound lower body exercise that primarily targets the glutes, while also engaging the hamstrings and core. It is performed by resting your upper back on a bench, placing a barbell across your hips, and driving your hips upward to create a straight line from your knees to your shoulders.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3562.gif","youtube_id":null,"instructions":["Start by sitting on the edge of a bench with your upper back resting against it and your feet flat on the ground, hip-width apart.","Place a barbell across your hips, holding it securely with both hands.","Engage your glutes and core muscles, then press through your heels to lift your hips off the bench, creating a straight line from your knees to your shoulders.","Pause for a moment at the top, squeezing your glutes.","Slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"3563","name":"cable one arm pulldown","body_part":"back","target":"lats","secondary_muscles":["biceps","forearms"],"equipment":"cable","difficulty":"intermediate","description":"The cable one arm pulldown is a unilateral exercise that targets the latissimus dorsi using a cable machine. It also engages the biceps and forearms as secondary muscles. The movement requires good form and control to isolate the lats and avoid compensatory movements.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3563.gif","youtube_id":null,"instructions":["Attach a single handle to a high pulley cable machine.","Stand facing the machine with your feet shoulder-width apart.","Grasp the handle with an overhand grip and extend your arm fully.","Keep your back straight and your core engaged.","Pull the handle down towards your side while keeping your elbow close to your body.","Pause for a moment at the bottom of the movement, squeezing your lat muscle.","Slowly release the handle back to the starting position.","Repeat for the desired number of repetitions.","Switch sides and repeat the exercise with the other arm."]},{"id":"358","name":"dumbbell one arm reverse wrist curl","body_part":"lower arms","target":"forearms","secondary_muscles":["wrist extensors"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell one arm reverse wrist curl targets the forearms and wrist extensors by requiring the lifter to curl a dumbbell upward using only the wrist, with the forearm supported on the thigh. This exercise helps build forearm strength and endurance.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0358.gif","youtube_id":null,"instructions":["Sit on a bench or chair with your feet flat on the ground.","Hold a dumbbell in one hand with an overhand grip, palm facing down.","Rest your forearm on your thigh, with your wrist hanging off the edge.","Slowly lower the dumbbell towards the ground by flexing your wrist.","Pause for a moment at the bottom, then slowly curl your wrist back up towards your body.","Repeat for the desired number of repetitions, then switch to the other arm."]},{"id":"3582","name":"lunge with jump","body_part":"upper legs","target":"glutes","secondary_muscles":["quadriceps","hamstrings","calves"],"equipment":"body weight","difficulty":"advanced","description":"The lunge with jump is a dynamic lower body exercise that combines a traditional lunge with a plyometric jump, targeting the glutes and also engaging the quadriceps, hamstrings, and calves. It requires balance, coordination, and explosive strength.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3582.gif","youtube_id":null,"instructions":["Start by standing with your feet shoulder-width apart.","Take a step forward with your right foot, lowering your body into a lunge position.","Push off with your right foot and jump into the air, switching the position of your feet mid-air.","Land softly with your left foot forward and immediately lower your body into a lunge position.","Continue alternating between lunges and jumps for the desired number of repetitions."]},{"id":"359","name":"dumbbell one arm reverse fly (with support)","body_part":"shoulders","target":"delts","secondary_muscles":["trapezius","rhomboids"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell one arm reverse fly (with support) is an isolation exercise targeting the rear deltoids, with additional activation of the trapezius and rhomboids. It is performed seated, with one arm supported on a bench for stability, making it accessible for those developing shoulder strength and control.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0359.gif","youtube_id":null,"instructions":["Sit on a bench with your feet flat on the ground and your back straight.","Hold a dumbbell in one hand with your palm facing inwards.","Lean forward and place your free hand on the bench for support.","Keep your arm slightly bent and raise it out to the side until it is parallel to the ground.","Pause for a moment at the top, then slowly lower your arm back down to the starting position.","Repeat for the desired number of repetitions, then switch arms."]},{"id":"36","name":"barbell decline wide-grip press","body_part":"chest","target":"pectorals","secondary_muscles":["triceps","shoulders"],"equipment":"barbell","difficulty":"intermediate","description":"The barbell decline wide-grip press is a compound chest exercise performed on a decline bench using a barbell with a wide grip. It targets the lower portion of the pectoral muscles and also engages the triceps and shoulders.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0036.gif","youtube_id":null,"instructions":["Lie on a decline bench with your feet secured and your head lower than your hips.","Grasp the barbell with a wide grip, slightly wider than shoulder-width apart.","Lower the barbell to your chest, keeping your elbows out to the sides.","Push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]},{"id":"360","name":"dumbbell one arm shoulder press v. 2","body_part":"shoulders","target":"delts","secondary_muscles":["triceps","upper back"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell one arm shoulder press v. 2 is a unilateral overhead pressing exercise that targets the deltoid muscles, while also engaging the triceps and upper back for stabilization. This movement helps build shoulder strength and stability, and challenges core engagement due to the single-arm nature of the exercise.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0360.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and hold a dumbbell in one hand at shoulder level, palm facing forward.","Engage your core and press the dumbbell straight up overhead, fully extending your arm.","Pause for a moment at the top, then slowly lower the dumbbell back to shoulder level.","Repeat for the desired number of repetitions, then switch to the other arm."]},{"id":"361","name":"dumbbell one arm shoulder press","body_part":"shoulders","target":"delts","secondary_muscles":["triceps","upper back"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell one arm shoulder press is a unilateral overhead pressing exercise that targets the deltoid muscles, with secondary emphasis on the triceps and upper back. It requires core stability and coordination to maintain balance while pressing with one arm.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0361.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and hold a dumbbell in one hand at shoulder level, palm facing forward.","Press the dumbbell upward until your arm is fully extended overhead.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]},{"id":"362","name":"dumbbell one arm triceps extension (on bench)","body_part":"upper arms","target":"triceps","secondary_muscles":["shoulders"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell one arm triceps extension (on bench) is an isolation exercise targeting the triceps, performed while seated on a bench. It involves extending the arm overhead with a dumbbell to work the triceps, with the shoulders acting as a secondary stabilizer.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0362.gif","youtube_id":null,"instructions":["Sit on a bench with your back straight and feet flat on the ground.","Hold a dumbbell in one hand and place your other hand on the bench for support.","Raise the dumbbell overhead, keeping your upper arm close to your head and your elbow pointing forward.","Lower the dumbbell behind your head by bending your elbow, keeping your upper arm stationary.","Extend your arm back up to the starting position, fully straightening your elbow.","Repeat for the desired number of repetitions, then switch arms."]},{"id":"363","name":"dumbbell one arm upright row","body_part":"shoulders","target":"delts","secondary_muscles":["traps","biceps"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell one arm upright row is a unilateral shoulder exercise that targets the deltoids, with secondary emphasis on the traps and biceps. It involves lifting a dumbbell with one arm in an upright rowing motion.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0363.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, holding a dumbbell in one hand with an overhand grip.","Let the dumbbell hang at arm's length in front of your thighs, with your palm facing your body.","Keeping your back straight and your core engaged, exhale and lift the dumbbell straight up towards your chin, leading with your elbow.","Pause for a moment at the top, then inhale and slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]},{"id":"3635","name":"dumbbell contralateral forward lunge","body_part":"upper legs","target":"glutes","secondary_muscles":["quadriceps","hamstrings","calves"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell contralateral forward lunge is a lower body exercise that targets the glutes, with secondary emphasis on the quadriceps, hamstrings, and calves. It involves stepping forward with one leg while holding a dumbbell in the opposite hand, challenging strength, balance, and coordination.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3635.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand.","Take a step forward with your right foot, keeping your back straight and core engaged.","Lower your body by bending both knees until your right thigh is parallel to the ground.","Push through your right heel to return to the starting position.","Repeat with your left leg.","Alternate legs for the desired number of repetitions."]},{"id":"3636","name":"high knee against wall","body_part":"cardio","target":"cardiovascular system","secondary_muscles":["quadriceps","hamstrings","glutes","calves"],"equipment":"body weight","difficulty":"beginner","description":"High knee against wall is a bodyweight cardio exercise that involves running in place while bringing your knees up high, using a wall for balance and support. It targets the cardiovascular system and also works the quadriceps, hamstrings, glutes, and calves.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3636.gif","youtube_id":null,"instructions":["Stand facing a wall with your feet hip-width apart.","Place your hands on the wall for support.","Engage your core and lift your right knee up towards your chest, while keeping your left foot on the ground.","Quickly switch legs, bringing your left knee up towards your chest and lowering your right foot back down.","Continue alternating legs in a running motion, bringing your knees up as high as possible.","Maintain a fast pace and keep your upper body stable throughout the exercise.","Repeat for the desired duration or number of repetitions."]},{"id":"3637","name":"wheel run","body_part":"cardio","target":"cardiovascular system","secondary_muscles":["quadriceps","hamstrings","calves"],"equipment":"body weight","difficulty":"advanced","description":"The wheel run is a dynamic exercise that targets the cardiovascular system while also engaging the core, quadriceps, hamstrings, and calves. It involves rolling a wheel forward and backward from a plank position, requiring both strength and coordination.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3637.gif","youtube_id":null,"instructions":["Start in a plank position with your hands on the wheel and your body straight.","Engage your core and start rolling the wheel forward by extending your arms.","Continue rolling until your body is fully extended and your arms are overhead.","Reverse the movement by pulling the wheel back towards your body, using your core and arms.","Repeat for the desired number of repetitions."]},{"id":"3638","name":"push to run","body_part":"cardio","target":"cardiovascular system","secondary_muscles":["quadriceps","hamstrings","calves"],"equipment":"body weight","difficulty":"intermediate","description":"The 'push to run' exercise combines a push-up with a running-in-place motion, alternating knees towards the chest in a plank position. This movement elevates the heart rate and challenges both upper body strength and cardiovascular endurance.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3638.gif","youtube_id":null,"instructions":["Start in a push-up position with your hands shoulder-width apart and your body in a straight line.","Lower your chest towards the ground by bending your elbows, keeping your body straight.","Push through your hands to extend your arms and return to the starting position.","Quickly bring one knee towards your chest, then quickly switch and bring the other knee towards your chest.","Continue alternating knees as fast as you can while maintaining good form.","Continue for the desired duration or number of repetitions."]},{"id":"3639","name":"bent knee lying twist (male)","body_part":"upper legs","target":"glutes","secondary_muscles":["obliques","hip flexors"],"equipment":"body weight","difficulty":"beginner","description":"The bent knee lying twist (male) is a bodyweight exercise that targets the glutes and also engages the obliques and hip flexors. It involves lying on your back with bent knees and twisting them side to side, which helps improve flexibility and mobility in the lower back and hips.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3639.gif","youtube_id":null,"instructions":["Lie flat on your back with your knees bent and feet flat on the ground.","Extend your arms out to the sides, perpendicular to your body.","Keeping your knees together, slowly lower them to one side, aiming to touch the ground with your knees.","Pause for a moment, then engage your core and slowly lift your knees back to the starting position.","Repeat the movement to the other side.","Continue alternating sides for the desired number of repetitions."]},{"id":"364","name":"dumbbell one arm wrist curl","body_part":"lower arms","target":"forearms","secondary_muscles":["biceps","brachialis"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell one arm wrist curl is an isolation exercise targeting the forearm muscles, particularly the wrist flexors. It is performed seated, with the forearm supported and the wrist curling a dumbbell upward.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0364.gif","youtube_id":null,"instructions":["Sit on a bench or chair with your feet flat on the ground.","Hold a dumbbell in one hand with an underhand grip, resting your forearm on your thigh.","Allow your wrist to extend, letting the dumbbell roll down towards your fingers.","Slowly curl your wrist back up, bringing the dumbbell towards your forearm.","Repeat for the desired number of repetitions, then switch to the other hand."]},{"id":"3640","name":"knee touch crunch","body_part":"waist","target":"abs","secondary_muscles":["hip flexors"],"equipment":"body weight","difficulty":"beginner","description":"The knee touch crunch is a bodyweight abdominal exercise that targets the abs and also engages the hip flexors. It involves alternating reaching across the body to touch the opposite knee while performing a crunch motion.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3640.gif","youtube_id":null,"instructions":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, lift your shoulder blades off the ground and reach your right hand towards your left knee.","Return to the starting position and repeat, this time reaching your left hand towards your right knee.","Continue alternating sides for the desired number of repetitions."]},{"id":"3641","name":"weighted kneeling step with swing","body_part":"shoulders","target":"delts","secondary_muscles":["triceps","core"],"equipment":"weighted","difficulty":"intermediate","description":"The weighted kneeling step with swing is a dynamic exercise that targets the deltoids while also engaging the triceps and core. It involves swinging weights overhead from a kneeling position, requiring coordination, balance, and strength.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3641.gif","youtube_id":null,"instructions":["Start in a kneeling position with your knees hip-width apart and your back straight.","Hold a weight in each hand, with your arms extended straight down in front of you.","Engage your core and swing the weights up and overhead, keeping your arms straight.","Lower the weights back down to the starting position and repeat for the desired number of repetitions."]},{"id":"3642","name":"weighted stretch lunge","body_part":"upper legs","target":"glutes","secondary_muscles":["quadriceps","hamstrings","calves"],"equipment":"weighted","difficulty":"intermediate","description":"The weighted stretch lunge is a lower body exercise that targets the glutes while also engaging the quadriceps, hamstrings, and calves. It involves stepping forward into a lunge position while holding weights, then returning to the starting position and alternating legs.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3642.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart.","Take a step forward with your right foot, keeping your back straight.","Lower your body by bending your knees until your right thigh is parallel to the ground.","Push through your right heel to return to the starting position.","Repeat with your left leg.","Continue alternating legs for the desired number of repetitions."]},{"id":"3643","name":"weighted cossack squats (male)","body_part":"upper legs","target":"glutes","secondary_muscles":["quadriceps","hamstrings","calves"],"equipment":"weighted","difficulty":"advanced","description":"Weighted cossack squats are a lower body exercise targeting the glutes, quadriceps, hamstrings, and calves. This movement requires significant balance, mobility, and strength, as you shift your weight laterally and squat deeply on one leg while holding a weight.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3643.gif","youtube_id":null,"instructions":["Stand with your feet wider than shoulder-width apart and toes pointing slightly outward.","Hold a weight in front of your chest with both hands.","Shift your weight to one side and lower your body by bending the knee of the side you shifted towards, while keeping the other leg straight.","Go as low as you can while maintaining balance and keeping your chest up.","Push through the heel of the bent leg to return to the starting position.","Repeat on the other side, alternating between legs."]},{"id":"3644","name":"weighted lunge with swing","body_part":"upper legs","target":"glutes","secondary_muscles":["quadriceps","hamstrings","calves"],"equipment":"weighted","difficulty":"intermediate","description":"The weighted lunge with swing is a dynamic lower body exercise that combines a traditional lunge with an upper body swinging motion using weights. This movement targets the glutes primarily, while also engaging the quadriceps, hamstrings, and calves. The swinging motion adds a coordination and balance challenge.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3644.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, holding a weight in each hand.","Take a step forward with your right foot, lowering your body into a lunge position.","As you lunge forward, swing the weights forward and upward, keeping your arms straight.","Push off with your right foot and return to the starting position, swinging the weights back down.","Repeat with your left foot and continue alternating legs for the desired number of repetitions."]},{"id":"3645","name":"single leg bridge with outstretched leg","body_part":"upper legs","target":"glutes","secondary_muscles":["hamstrings","quadriceps"],"equipment":"body weight","difficulty":"intermediate","description":"The single leg bridge with outstretched leg is a bodyweight exercise targeting the glutes, with secondary emphasis on the hamstrings and quadriceps. It challenges stability and unilateral strength by requiring you to lift your hips while keeping one leg extended.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3645.gif","youtube_id":null,"instructions":["Lie on your back with your knees bent and feet flat on the ground.","Extend one leg straight out in front of you.","Engage your glutes and lift your hips off the ground, forming a straight line from your knees to your shoulders.","Hold for a moment at the top, then slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions, then switch legs."]},{"id":"365","name":"dumbbell over bench neutral wrist curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell over bench neutral wrist curl is an isolation exercise targeting the biceps and forearms. It is performed seated, with the forearms resting on a bench and the wrists hanging off the edge, curling dumbbells upward with a neutral grip.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0365.gif","youtube_id":null,"instructions":["Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand, palms facing up.","Rest your forearms on the bench, allowing your wrists to hang off the edge.","Keeping your upper arms stationary, exhale and curl the dumbbells up towards your shoulders.","Pause for a moment at the top, then inhale and slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"3655","name":"walking high knees lunge","body_part":"cardio","target":"cardiovascular system","secondary_muscles":["quadriceps","hamstrings","glutes","calves"],"equipment":"body weight","difficulty":"beginner","description":"The walking high knees lunge is a dynamic exercise that combines high knee raises with forward lunges, targeting the cardiovascular system while also engaging the quadriceps, hamstrings, glutes, and calves. It is performed using only body weight and is effective for improving cardiovascular endurance, coordination, and lower body strength.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3655.gif","youtube_id":null,"instructions":["Stand with your feet hip-width apart.","Lift your right knee up towards your chest as high as you can while balancing on your left leg.","Step forward with your right foot and lower your body into a lunge position, bending both knees to a 90-degree angle.","Push off with your right foot and bring your left knee up towards your chest.","Step forward with your left foot and lower your body into a lunge position.","Continue alternating legs and lunging forward, keeping your core engaged and maintaining a steady pace.","Repeat for the desired number of repetitions."]},{"id":"3656","name":"short stride run","body_part":"cardio","target":"cardiovascular system","secondary_muscles":["quadriceps","hamstrings","calves"],"equipment":"body weight","difficulty":"beginner","description":"Short stride run is a cardiovascular exercise performed by running with quick, short steps, either in place or moving forward. It primarily targets the cardiovascular system and also engages the quadriceps, hamstrings, and calves.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3656.gif","youtube_id":null,"instructions":["Find an open space or a treadmill to perform the exercise.","Stand tall with your feet hip-width apart.","Start jogging in place, lifting your knees high and pumping your arms.","After a few seconds, start taking short strides forward, maintaining a quick pace.","Continue running with short strides for the desired duration or distance."]},{"id":"366","name":"dumbbell over bench one arm neutral wrist curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell over bench one arm neutral wrist curl is an isolation exercise targeting the biceps and forearms. It is performed seated, with the arm extended over a bench and the wrist in a neutral position, curling the dumbbell towards the shoulder.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0366.gif","youtube_id":null,"instructions":["Sit on a bench with a dumbbell in one hand and your arm extended over the bench, palm facing up.","Keep your upper arm stationary and curl the dumbbell towards your shoulder, keeping your wrist in a neutral position.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]},{"id":"3662","name":"pike-to-cobra push-up","body_part":"upper legs","target":"glutes","secondary_muscles":["core","shoulders","triceps"],"equipment":"body weight","difficulty":"advanced","description":"The pike-to-cobra push-up is a dynamic bodyweight exercise that combines elements of a push-up, pike, and cobra pose. It targets the glutes primarily, while also engaging the core, shoulders, and triceps. The movement requires transitioning between an inverted V (pike) position and a cobra pose, demanding strength, flexibility, and coordination.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3662.gif","youtube_id":null,"instructions":["Start in a push-up position with your hands slightly wider than shoulder-width apart and your feet together.","Engage your core and lift your hips up towards the ceiling, forming an inverted V shape with your body.","Lower your upper body towards the ground by bending your elbows, keeping them close to your body.","As you lower down, shift your weight forward and transition into a cobra pose by straightening your arms and lifting your chest up.","Reverse the movement by bending your elbows and lowering your chest back down towards the ground.","Push through your hands to return to the inverted V position.","Continue the movement by lowering your hips back down towards the ground, returning to the starting push-up position.","Repeat for the desired number of repetitions."]},{"id":"3663","name":"reverse plank with leg lift","body_part":"waist","target":"abs","secondary_muscles":["glutes","hamstrings","shoulders"],"equipment":"body weight","difficulty":"advanced","description":"The reverse plank with leg lift is a challenging core exercise that targets the abs while also engaging the glutes, hamstrings, and shoulders. It requires maintaining a strong reverse plank position while alternately lifting each leg, demanding significant core strength, balance, and coordination.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3663.gif","youtube_id":null,"instructions":["Sit on the ground with your legs extended in front of you and your hands resting on the ground behind you, fingers pointing towards your feet.","Press through your hands and lift your hips off the ground, coming into a reverse plank position.","Engage your core and lift one leg off the ground, extending it straight up towards the ceiling.","Hold for a moment, then lower your leg back down.","Repeat with the other leg.","Continue alternating legs for the desired number of repetitions."]},{"id":"3664","name":"dumbbell side plank with rear fly","body_part":"back","target":"upper back","secondary_muscles":["shoulders","core"],"equipment":"dumbbell","difficulty":"advanced","description":"The dumbbell side plank with rear fly is a compound exercise that combines core stability with upper back and shoulder strength. It requires holding a side plank position while performing a rear fly with a dumbbell, challenging balance, coordination, and strength.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3664.gif","youtube_id":null,"instructions":["Start by lying on your side with your legs extended and stacked on top of each other.","Place your forearm on the ground directly below your shoulder, keeping your elbow bent at a 90-degree angle.","Hold a dumbbell in your top hand, with your arm extended straight down towards the ground.","Engage your core and lift your hips off the ground, creating a straight line from your head to your heels.","While maintaining the side plank position, lift the dumbbell up towards the ceiling, squeezing your shoulder blades together.","Lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch sides."]},{"id":"3665","name":"power point plank","body_part":"waist","target":"abs","secondary_muscles":["shoulders","triceps","glutes"],"equipment":"body weight","difficulty":"intermediate","description":"The power point plank is a dynamic core exercise that involves transitioning between a high plank and a forearm plank position, challenging core stability, shoulder strength, and coordination.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3665.gif","youtube_id":null,"instructions":["Start in a high plank position with your hands directly under your shoulders and your body in a straight line from head to toe.","Engage your core and squeeze your glutes to maintain a stable position.","Lower your body down onto your forearms, one arm at a time, maintaining a straight line from head to toe.","Hold this position for the desired amount of time, keeping your core and glutes engaged.","To return to the starting position, push through your forearms and lift your body back up into a high plank position.","Repeat for the desired number of repetitions."]},{"id":"3666","name":"walking on incline treadmill","body_part":"cardio","target":"cardiovascular system","secondary_muscles":["quadriceps","hamstrings","calves"],"equipment":"leverage machine","difficulty":"beginner","description":"Walking on an incline treadmill is a cardiovascular exercise performed on a treadmill with the incline set to increase intensity. It primarily targets the cardiovascular system while also engaging the quadriceps, hamstrings, and calves.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3666.gif","youtube_id":null,"instructions":["Adjust the incline level on the treadmill to your desired intensity.","Stand on the treadmill with your feet shoulder-width apart.","Start walking at a comfortable pace, ensuring that you maintain proper form.","Engage your core muscles and keep your back straight throughout the exercise.","Continue walking on the incline treadmill for the desired duration of your cardio workout.","Gradually decrease the incline and speed of the treadmill to cool down before stopping."]},{"id":"3667","name":"side lying hip adduction (male)","body_part":"upper legs","target":"adductors","secondary_muscles":["glutes","hamstrings"],"equipment":"body weight","difficulty":"beginner","description":"The side lying hip adduction (male) is a bodyweight exercise targeting the adductors, performed while lying on your side and lifting the top leg upward.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3667.gif","youtube_id":null,"instructions":["Lie on your side with your legs straight and stacked on top of each other.","Place your bottom arm under your head for support.","Engage your adductors and lift your top leg as high as possible without rotating your hips or leaning backward.","Pause for a moment at the top, then slowly lower your leg back down to the starting position.","Repeat for the desired number of repetitions, then switch sides."]},{"id":"3669","name":"standing archer","body_part":"back","target":"upper back","secondary_muscles":["shoulders","biceps","forearms"],"equipment":"body weight","difficulty":"beginner","description":"The standing archer is a bodyweight exercise that targets the upper back and involves rotational movement of the torso, mimicking the motion of drawing a bowstring. It also engages the shoulders, biceps, and forearms.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3669.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and your knees slightly bent.","Extend your arms straight out in front of you at shoulder height, parallel to the ground.","Rotate your torso to the right, keeping your arms extended and your back straight.","As you rotate, extend your right arm forward and your left arm back, mimicking the motion of drawing a bowstring.","Hold the position for a moment, then return to the starting position.","Repeat the motion, this time rotating your torso to the left and extending your left arm forward and your right arm back.","Continue alternating sides for the desired number of repetitions."]},{"id":"367","name":"dumbbell over bench one arm wrist curl","body_part":"lower arms","target":"forearms","secondary_muscles":["biceps","shoulders"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell over bench one arm wrist curl is an isolation exercise targeting the forearm muscles. It is performed seated, with the forearm resting on a bench and the wrist curling a dumbbell upward.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0367.gif","youtube_id":null,"instructions":["Sit on a bench with your feet flat on the ground and hold a dumbbell in one hand, palm facing down.","Rest your forearm on the bench with your wrist hanging off the edge.","Slowly curl your wrist upwards, bringing the dumbbell towards your forearm.","Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]},{"id":"3670","name":"weighted decline sit-up","body_part":"waist","target":"abs","secondary_muscles":["hip flexors","lower back"],"equipment":"weighted","difficulty":"intermediate","description":"The weighted decline sit-up is an abdominal exercise performed on a decline bench with added resistance. It primarily targets the abs while also engaging the hip flexors and lower back. This variation increases the intensity compared to standard sit-ups, requiring greater core strength and control.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3670.gif","youtube_id":null,"instructions":["Lie flat on a decline bench with your feet secured under the foot pads.","Place your hands behind your head or across your chest.","Engage your abs and slowly lift your upper body off the bench, curling forward until your torso is perpendicular to the ground.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"3671","name":"ski step","body_part":"cardio","target":"cardiovascular system","secondary_muscles":["quadriceps","hamstrings","glutes","calves"],"equipment":"body weight","difficulty":"beginner","description":"The ski step is a dynamic, bodyweight exercise that mimics the motion of skiing. It involves lateral jumps from side to side, engaging the cardiovascular system while also working the lower body muscles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3671.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart.","Bend your knees slightly and keep your back straight.","Jump to the right, landing on your right foot while swinging your left leg behind your right leg.","Immediately jump to the left, landing on your left foot while swinging your right leg behind your left leg.","Continue alternating jumps from side to side, mimicking a skiing motion.","Repeat for the desired number of repetitions."]},{"id":"3672","name":"back and forth step","body_part":"cardio","target":"cardiovascular system","secondary_muscles":["quadriceps","hamstrings","glutes","calves"],"equipment":"body weight","difficulty":"beginner","description":"A dynamic bodyweight exercise that alternates stepping forward and backward, targeting the cardiovascular system and lower body muscles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3672.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart.","Step forward with your right foot, bending your knee and lowering your body into a lunge position.","Push off with your right foot and step back to the starting position.","Repeat the movement with your left foot, alternating legs with each step.","Continue stepping back and forth, maintaining a steady pace.","Repeat for the desired duration or number of repetitions."]},{"id":"3679","name":"sit-up with arms on chest","body_part":"waist","target":"abs","secondary_muscles":["hip flexors"],"equipment":"body weight","difficulty":"beginner","description":"The sit-up with arms on chest is a classic abdominal exercise that targets the abs and also engages the hip flexors. It is performed by lying on your back, crossing your arms over your chest, and lifting your upper body towards your knees.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3679.gif","youtube_id":null,"instructions":["Lie flat on your back with your knees bent and feet flat on the ground.","Cross your arms over your chest.","Engaging your abs, lift your upper body off the ground towards your knees.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"368","name":"dumbbell over bench reverse wrist curl","body_part":"lower arms","target":"forearms","secondary_muscles":["biceps","brachialis"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell over bench reverse wrist curl is an isolation exercise targeting the forearms, specifically the wrist extensors. It is performed seated with the forearms resting on a bench and the wrists hanging off the edge, curling the dumbbells upward with the backs of the hands facing up.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0368.gif","youtube_id":null,"instructions":["Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand, palms facing down.","Rest your forearms on the bench, allowing your wrists to hang off the edge.","Slowly curl your wrists upward, bringing the dumbbells towards your body.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"369","name":"dumbbell over bench wrist curl","body_part":"lower arms","target":"forearms","secondary_muscles":["biceps","brachialis"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell over bench wrist curl is an isolation exercise targeting the forearms. It is performed by sitting on a bench with your forearms resting on the bench, palms up, and curling your wrists upward with dumbbells.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0369.gif","youtube_id":null,"instructions":["Sit on a bench with your forearms resting on the bench and your palms facing up, holding a dumbbell in each hand.","Allow your wrists to hang over the edge of the bench.","Slowly curl your wrists upward, squeezing your forearms at the top of the movement.","Pause for a moment, then slowly lower your wrists back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"3697","name":"cable kneeling rear delt row (with rope) (male)","body_part":"shoulders","target":"delts","secondary_muscles":["trapezius","rhomboids","biceps"],"equipment":"cable","difficulty":"intermediate","description":"The cable kneeling rear delt row (with rope) targets the rear deltoids and upper back muscles, requiring the user to kneel and pull a rope attachment toward their body while maintaining a strong core and stable posture.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3697.gif","youtube_id":null,"instructions":["Attach a rope handle to a low cable pulley and kneel down facing the machine.","Grasp the rope with a neutral grip (palms facing each other) and extend your arms fully in front of you.","Keeping your back straight and core engaged, pull the rope towards your body by retracting your shoulder blades.","Squeeze your shoulder blades together at the end of the movement and hold for a brief pause.","Slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"3698","name":"inchworm v. 2","body_part":"waist","target":"abs","secondary_muscles":["shoulders","hamstrings"],"equipment":"body weight","difficulty":"beginner","description":"The inchworm v. 2 is a bodyweight exercise that targets the abs while also engaging the shoulders and hamstrings. It involves moving from a standing position to a plank and back, promoting core strength, flexibility, and coordination.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3698.gif","youtube_id":null,"instructions":["Start in a standing position with your feet hip-width apart.","Bend forward at the waist and place your hands on the ground in front of you.","Walk your hands forward until you are in a high plank position, with your body in a straight line from head to toe.","Keeping your legs straight, walk your feet towards your hands, bringing your hips up towards the ceiling.","Continue walking your hands forward, repeating the movement for the desired number of repetitions."]},{"id":"3699","name":"shoulder tap","body_part":"waist","target":"abs","secondary_muscles":["shoulders","triceps"],"equipment":"body weight","difficulty":"intermediate","description":"Shoulder taps are a bodyweight exercise performed in a high plank position, targeting the abs while also engaging the shoulders and triceps. The movement requires you to alternate tapping your shoulders with the opposite hand, challenging core stability and coordination.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3699.gif","youtube_id":null,"instructions":["Start in a high plank position with your hands directly under your shoulders and your body in a straight line.","Engage your core and lift your right hand off the ground, reaching across to tap your left shoulder.","Place your right hand back on the ground and repeat with your left hand tapping your right shoulder.","Continue alternating shoulder taps while keeping your hips and torso stable.","Repeat for the desired number of repetitions."]},{"id":"37","name":"barbell decline wide-grip pullover","body_part":"back","target":"lats","secondary_muscles":["triceps","chest"],"equipment":"barbell","difficulty":"intermediate","description":"The barbell decline wide-grip pullover is a compound exercise performed on a decline bench, targeting the lats while also engaging the triceps and chest. It requires a barbell and involves lowering the weight behind the head with straight arms, then returning to the starting position.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0037.gif","youtube_id":null,"instructions":["Lie on a decline bench with your head lower than your hips and your feet secured.","Hold a barbell with a wide grip and extend your arms straight above your chest.","Lower the barbell behind your head in a controlled manner, keeping your arms straight.","Pause for a moment, then raise the barbell back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"370","name":"dumbbell preacher hammer curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell preacher hammer curl is an isolation exercise targeting the biceps and forearms. It is performed with dumbbells while keeping the upper arms stationary, focusing on strict form to maximize biceps engagement.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0370.gif","youtube_id":null,"instructions":["Stand up straight with a dumbbell in each hand, palms facing your torso.","Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward.","This will be your starting position.","Now, keeping the upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Then, inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the recommended amount of repetitions."]},{"id":"371","name":"dumbbell plyo squat","body_part":"upper legs","target":"glutes","secondary_muscles":["quadriceps","hamstrings","calves"],"equipment":"dumbbell","difficulty":"advanced","description":"The dumbbell plyo squat is a dynamic lower body exercise that combines a squat with a plyometric jump, performed while holding dumbbells. It targets the glutes, quadriceps, hamstrings, and calves, and requires explosive power, coordination, and balance.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0371.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand at your sides.","Lower your body into a squat position by bending your knees and pushing your hips back.","As you reach the bottom of the squat, explode upward, jumping off the ground.","While in the air, quickly switch the position of your feet, landing with your opposite foot forward.","Immediately lower your body back into a squat position and repeat the jump, switching your feet again.","Continue alternating the position of your feet with each jump for the desired number of repetitions."]},{"id":"372","name":"dumbbell preacher curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell preacher curl is an isolation exercise targeting the biceps, performed on a preacher bench to minimize shoulder involvement and maximize biceps engagement.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0372.gif","youtube_id":null,"instructions":["Sit on a preacher curl bench with your upper arms resting on the pad and your chest against it.","Hold a dumbbell in each hand with your palms facing up and your arms fully extended.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"373","name":"dumbbell pronate-grip triceps extension","body_part":"upper arms","target":"triceps","secondary_muscles":["forearms"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell pronate-grip triceps extension is an upper arm exercise that targets the triceps using a dumbbell with a pronated (palms-down) grip. It is performed seated, with the dumbbell extended overhead and lowered behind the head.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0373.gif","youtube_id":null,"instructions":["Sit on a bench or chair with your back straight and feet flat on the ground.","Hold a dumbbell with both hands, palms facing down, and extend your arms straight up overhead.","Keeping your upper arms close to your head and elbows pointing forward, slowly lower the dumbbell behind your head by bending your elbows.","Pause for a moment, then extend your arms back up to the starting position.","Repeat for the desired number of repetitions."]},{"id":"374","name":"dumbbell prone incline curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell prone incline curl is an isolation exercise targeting the biceps, performed while lying face down on an incline bench. This position minimizes cheating and emphasizes strict biceps contraction.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0374.gif","youtube_id":null,"instructions":["Adjust the bench to a 45-degree incline.","Lie face down on the bench with your chest and stomach resting against it.","Hold a dumbbell in each hand with your palms facing down and your arms fully extended.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"375","name":"dumbbell pullover","body_part":"chest","target":"pectorals","secondary_muscles":["latissimus dorsi","triceps"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell pullover is a chest exercise performed lying on a bench, where you lower a dumbbell behind your head and then bring it back over your chest, targeting the pectorals and also engaging the lats and triceps.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0375.gif","youtube_id":null,"instructions":["Lie flat on a bench with your head at one end and your feet on the floor.","Hold a dumbbell with both hands and extend your arms straight above your chest.","Keeping a slight bend in your elbows, slowly lower the dumbbell behind your head until you feel a stretch in your chest and shoulders.","Pause for a moment, then raise the dumbbell back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"3758","name":"lever standing chest press","body_part":"chest","target":"pectorals","secondary_muscles":["shoulders","triceps"],"equipment":"leverage machine","difficulty":"beginner","description":"The lever standing chest press is a machine-based exercise that targets the pectoral muscles, with secondary emphasis on the shoulders and triceps. It is performed standing, using a leverage machine, and involves pressing handles forward from chest level to full extension.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3758.gif","youtube_id":null,"instructions":["Adjust the seat height and position yourself on the machine with your feet flat on the ground.","Grasp the handles with an overhand grip and position your hands at chest level.","Push the handles forward until your arms are fully extended, keeping your elbows slightly bent.","Pause for a moment, then slowly bring the handles back towards your chest, maintaining control throughout the movement.","Repeat for the desired number of repetitions."]},{"id":"3759","name":"lever seated good morning","body_part":"upper legs","target":"glutes","secondary_muscles":["hamstrings","lower back"],"equipment":"leverage machine","difficulty":"intermediate","description":"The lever seated good morning is a machine-based exercise targeting the glutes, with secondary emphasis on the hamstrings and lower back. It involves hinging at the hips while seated, using a leverage machine to provide resistance.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3759.gif","youtube_id":null,"instructions":["Adjust the seat height so that your hips are slightly higher than your knees.","Sit on the machine with your back against the pad and your feet flat on the footrests.","Grasp the handles or the sides of the seat for stability.","Keeping your back straight, slowly lean forward from your hips until your upper body is parallel to the ground.","Pause for a moment, then slowly return to the starting position by pushing through your glutes and hamstrings.","Repeat for the desired number of repetitions."]},{"id":"376","name":"dumbbell raise","body_part":"shoulders","target":"delts","secondary_muscles":["traps","rhomboids"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell raise is a shoulder exercise that targets the deltoid muscles, with secondary emphasis on the traps and rhomboids. It involves lifting dumbbells out to the sides to shoulder height, focusing on controlled movement and proper form.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0376.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing your body.","Keep your back straight and engage your core.","Raise your arms out to the sides until they are parallel to the floor, keeping a slight bend in your elbows.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"3760","name":"lever seated crunch v. 2","body_part":"waist","target":"abs","secondary_muscles":["obliques","hip flexors"],"equipment":"leverage machine","difficulty":"beginner","description":"The lever seated crunch v. 2 is an abdominal exercise performed on a leverage machine. It targets the abs, with secondary emphasis on the obliques and hip flexors. The movement involves crunching forward against resistance, making it a controlled and effective core strengthening exercise.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3760.gif","youtube_id":null,"instructions":["Sit on the leverage machine with your back against the pad and your feet secured under the footpads.","Place your hands on the handles or the sides of the seat for support.","Engage your abs and slowly crunch forward, bringing your chest towards your knees.","Pause for a moment at the top of the movement, squeezing your abs.","Slowly return to the starting position, allowing your back to round slightly.","Repeat for the desired number of repetitions."]},{"id":"3769","name":"curtsey squat","body_part":"upper legs","target":"glutes","secondary_muscles":["quadriceps","hamstrings","calves"],"equipment":"body weight","difficulty":"beginner","description":"The curtsey squat is a lower body exercise that targets the glutes and also works the quadriceps, hamstrings, and calves. It involves stepping one leg diagonally behind and across the body, bending both knees to lower into a squat, and then returning to the starting position. This movement challenges balance and coordination in addition to strength.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3769.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart.","Take a step diagonally behind and across your body with your right foot, crossing it behind your left leg.","Bend both knees as if you were curtsying, lowering your body towards the ground.","Keep your torso upright and your weight on your front foot.","Push through your front foot to return to the starting position.","Repeat on the other side, stepping diagonally behind and across your body with your left foot."]},{"id":"377","name":"dumbbell rear delt row (shoulder)","body_part":"shoulders","target":"delts","secondary_muscles":["trapezius","rhomboids"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell rear delt row (shoulder) is an exercise targeting the rear deltoids, as well as the trapezius and rhomboids. It involves a bent-over position and rowing motion to strengthen the upper back and shoulders.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0377.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and knees slightly bent.","Hold a dumbbell in each hand with your palms facing your body.","Bend forward at the waist, keeping your back straight and your core engaged.","Extend your arms straight down towards the floor, with a slight bend in your elbows.","Raise the dumbbells out to the sides, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"378","name":"dumbbell rear fly","body_part":"shoulders","target":"delts","secondary_muscles":["trapezius","rhomboids"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell rear fly is an isolation exercise that targets the rear deltoids, with secondary emphasis on the trapezius and rhomboids. It is performed by hinging at the hips, maintaining a straight back, and lifting dumbbells out to the sides while squeezing the shoulder blades together.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0378.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and hold a dumbbell in each hand.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Extend your arms straight down towards the ground, palms facing each other.","Keeping a slight bend in your elbows, lift your arms out to the sides and squeeze your shoulder blades together.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"3785","name":"incline push-up (on box)","body_part":"chest","target":"pectorals","secondary_muscles":["triceps","shoulders"],"equipment":"body weight","difficulty":"beginner","description":"The incline push-up (on box) is a bodyweight exercise that targets the pectoral muscles, with secondary emphasis on the triceps and shoulders. It is performed by placing the hands on an elevated surface, such as a box, and executing a push-up motion.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3785.gif","youtube_id":null,"instructions":["Place your hands on the edge of a box or elevated surface, slightly wider than shoulder-width apart.","Extend your legs behind you, resting on the balls of your feet, creating a straight line from your head to your heels.","Lower your chest towards the box by bending your elbows, keeping your body in a straight line.","Pause for a moment at the bottom, then push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."]},{"id":"379","name":"dumbbell rear lateral raise (support head)","body_part":"shoulders","target":"delts","secondary_muscles":["traps","rhomboids"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell rear lateral raise (support head) is an isolation exercise targeting the rear deltoids, with secondary emphasis on the traps and rhomboids. It involves hinging forward at the hips and raising dumbbells out to the sides, focusing on shoulder stability and control.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0379.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and hold a dumbbell in each hand.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Raise your arms out to the sides, keeping a slight bend in your elbows, until they are parallel to the ground.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"38","name":"barbell drag curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"barbell","difficulty":"intermediate","description":"The barbell drag curl is a biceps-focused exercise that involves curling a barbell while keeping the elbows pulled back, emphasizing the contraction of the biceps and minimizing shoulder involvement. It also engages the forearms as secondary muscles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0038.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and hold a barbell with an underhand grip, palms facing up.","Let the barbell hang at arm's length in front of your thighs.","Keeping your upper arms stationary, curl the barbell up towards your chest by contracting your biceps.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"380","name":"dumbbell rear lateral raise","body_part":"shoulders","target":"delts","secondary_muscles":["traps","rhomboids"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell rear lateral raise is an isolation exercise targeting the rear deltoids, with secondary emphasis on the traps and rhomboids. It is performed by hinging at the hips and raising dumbbells out to the sides, focusing on shoulder movement.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0380.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing your body.","Bend your knees slightly and hinge forward at the hips, keeping your back straight and core engaged.","Raise your arms out to the sides, keeping a slight bend in your elbows, until they are parallel to the floor.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"381","name":"dumbbell rear lunge","body_part":"upper legs","target":"glutes","secondary_muscles":["quadriceps","hamstrings","calves"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell rear lunge is a lower body exercise that targets the glutes, with secondary emphasis on the quadriceps, hamstrings, and calves. It involves stepping backward into a lunge while holding dumbbells, challenging balance and unilateral leg strength.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0381.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand.","Take a step backward with your right foot, lowering your body into a lunge position.","Bend your left knee and lower your body until your left thigh is parallel to the ground.","Pause for a moment, then push through your left heel to return to the starting position.","Repeat on the other side, stepping back with your left foot."]},{"id":"382","name":"dumbbell reverse grip biceps curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell reverse grip biceps curl is an exercise targeting the biceps and forearms, performed by curling dumbbells with an overhand grip.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0382.gif","youtube_id":null,"instructions":["Stand up straight with a dumbbell in each hand, palms facing down and arms fully extended.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"383","name":"dumbbell reverse fly","body_part":"shoulders","target":"delts","secondary_muscles":["trapezius","rhomboids"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell reverse fly is an exercise that targets the rear deltoids, with secondary emphasis on the trapezius and rhomboids. It is performed by hinging at the hips, keeping the back straight, and lifting dumbbells out to the sides in a controlled manner.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0383.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and hold a dumbbell in each hand.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Extend your arms straight down in front of you, palms facing each other.","Keeping a slight bend in your elbows, raise your arms out to the sides until they are parallel to the ground.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"384","name":"dumbbell reverse preacher curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell reverse preacher curl is an isolation exercise targeting the biceps and forearms. It is performed seated on a preacher bench, with the upper arms resting on the pad and dumbbells held in an underhand grip. The movement involves curling the dumbbells upward while keeping the upper arms stationary, emphasizing the biceps and forearm muscles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0384.gif","youtube_id":null,"instructions":["Sit on a preacher bench with your upper arms resting on the pad and your chest against the support.","Hold a dumbbell in each hand with an underhand grip, palms facing up.","Keeping your upper arms stationary, exhale and curl the dumbbells as you contract your biceps.","Continue to curl the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"385","name":"dumbbell reverse wrist curl","body_part":"lower arms","target":"forearms","secondary_muscles":["biceps","brachialis"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell reverse wrist curl is an isolation exercise targeting the forearms, specifically the extensor muscles. It is performed seated, with the forearms resting on the thighs and the wrists curling the dumbbells upward using an overhand grip.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0385.gif","youtube_id":null,"instructions":["Sit on a bench or chair with your feet flat on the ground.","Hold a dumbbell in each hand with an overhand grip, palms facing down.","Rest your forearms on your thighs, allowing your wrists to hang off the edge.","Slowly curl your wrists upward, bringing the dumbbells towards your body.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"386","name":"dumbbell rotation reverse fly","body_part":"shoulders","target":"delts","secondary_muscles":["trapezius","rhomboids"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell rotation reverse fly is a shoulder exercise that targets the deltoids, with secondary emphasis on the trapezius and rhomboids. It involves hinging at the hips and lifting dumbbells out to the sides with a rotational component.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0386.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing inwards.","Bend your knees slightly and hinge forward at the hips, keeping your back straight and chest up.","Raise your arms out to the sides, keeping a slight bend in your elbows, until they are parallel to the floor.","Rotate your arms so that your palms are facing downwards.","Slowly lower your arms back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"387","name":"dumbbell seated alternate front raise","body_part":"shoulders","target":"delts","secondary_muscles":["trapezius","biceps"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell seated alternate front raise is a shoulder exercise that targets the deltoids, with secondary emphasis on the trapezius and biceps. It is performed seated, which helps stabilize the body and isolate the shoulder muscles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0387.gif","youtube_id":null,"instructions":["Sit on a bench with your back straight and feet flat on the ground.","Hold a dumbbell in each hand with your palms facing your body and arms extended down by your sides.","Keeping your arms straight, raise one dumbbell in front of you until it is parallel to the ground.","Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.","Repeat with the other arm.","Alternate between arms for the desired number of repetitions."]},{"id":"388","name":"dumbbell seated alternate press","body_part":"shoulders","target":"delts","secondary_muscles":["triceps","chest"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell seated alternate press is a shoulder exercise performed while seated, pressing one dumbbell overhead at a time in an alternating fashion. This movement targets the deltoid muscles and also engages the triceps and chest as secondary muscles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0388.gif","youtube_id":null,"instructions":["Sit on a bench with a dumbbell in each hand, palms facing forward.","Raise the dumbbells to shoulder height, with your elbows bent and palms facing forward.","Press one dumbbell up overhead, fully extending your arm.","Lower the dumbbell back down to shoulder height.","Repeat with the other arm.","Continue alternating arms for the desired number of repetitions."]},{"id":"3885","name":"double under jump rope","body_part":"cardio","target":"cardiovascular system","secondary_muscles":["calves","quads","hamstrings","glutes","forearms","delts"],"equipment":"rope","difficulty":"advanced","description":"Stand tall with a jump rope behind your heels, elbows close to your sides. Jump slightly higher than a single-under while snapping the wrists so the rope passes under your feet twice before you land.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3885.gif","youtube_id":null,"instructions":["Set rope length: stand on the middle and ensure handles reach roughly armpit height.","Hold handles lightly with elbows tucked and wrists slightly in front of hips; brace your core and look forward.","Begin with a few single-unders to establish rhythm on the balls of your feet.","Jump vertically a bit higher and whip the wrists quickly so the rope makes two revolutions during one jump.","Keep the torso tall with relaxed shoulders; do not tuck knees or kick heels back.","Land softly on the mid- to forefoot and absorb impact through ankles and knees.","Reset with singles if you miss, then resume double-unders for the desired reps or time while breathing steadily."]},{"id":"3886","name":"dumbbell complex push up row clean and press","body_part":"shoulders","target":"delts","secondary_muscles":["pectorals","triceps","lats","abs","quads","glutes"],"equipment":"dumbbell","difficulty":"advanced","description":"Start in a high plank holding two dumbbells. Perform a push-up, row each dumbbell, then transition to a clean and overhead press before returning to the plank.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3886.gif","youtube_id":null,"instructions":["Place two dumbbells on the floor shoulder-width apart and grip the handles in a high plank; feet hip–shoulder width, core braced, wrists neutral.","Lower into a controlled push-up, keeping a straight line from head to heels.","Shift weight slightly and row the right dumbbell toward your ribs without rotating the torso; return it to the floor and repeat with the left.","Jump or step your feet to the outside of the dumbbells, keeping your back flat and hips down.","Drive through the legs and hips to clean the dumbbells to the shoulders, catching with elbows forward in a partial squat.","Stand tall and press the dumbbells overhead until arms are fully extended and ribs stay down.","Lower the dumbbells back to the shoulders, then hinge to place them on the floor with a neutral spine.","Kick or step your feet back to the plank position and repeat for the next rep."]},{"id":"3887","name":"jump box over (male)","body_part":"upper legs","target":"quads","secondary_muscles":["glutes","hamstrings","calves","abs"],"equipment":"body weight","difficulty":"intermediate","description":"Stand to one side of a stable plyo box and jump laterally onto and over it, landing on the floor on the opposite side. Move explosively but land softly with control on each contact.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3887.gif","youtube_id":null,"instructions":["Place a stable box in open space and stand beside it with feet hip‑width, knees soft, and chest up.","Brace your core, hinge slightly at the hips, and dip into a quarter‑squat while swinging the arms back.","Drive through the feet to jump up and laterally onto the box, landing softly with both feet flat, knees tracking over toes.","Immediately continue across the top and descend to the far side by a small hop or controlled step, landing softly on mid‑foot and absorbing with the hips and knees.","Reset posture on the floor, turn to face the box from the new side, and repeat back.","Keep a neutral spine throughout; avoid valgus knee collapse and do not catch the toes on the box.","If control or landing quality degrades, step down or lower the box height."]},{"id":"3888","name":"dumbbell one arm snatch","body_part":"upper legs","target":"glutes","secondary_muscles":["hamstrings","quadriceps","core"],"equipment":"dumbbell","difficulty":"advanced","description":"The dumbbell one arm snatch is a dynamic, full-body movement that targets the glutes, hamstrings, quadriceps, and core. It requires explosive power, coordination, and balance as you lift a dumbbell from the ground to overhead in one fluid motion.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-3888.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, holding a dumbbell in one hand with an overhand grip.","Bend your knees slightly and hinge forward at the hips, keeping your back straight and chest up.","Lower the dumbbell towards the ground, keeping it close to your body.","Explosively extend your hips, knees, and ankles, driving the dumbbell upwards in a straight line.","As the dumbbell reaches shoulder height, quickly rotate your hand and punch it overhead, fully extending your arm.","Catch the dumbbell overhead with a slight bend in your knees and hips.","Lower the dumbbell back down to the starting position in a controlled manner.","Repeat for the desired number of repetitions, then switch to the other arm."]},{"id":"389","name":"dumbbell seated bench extension","body_part":"upper arms","target":"triceps","secondary_muscles":["shoulders"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell seated bench extension is an upper arm exercise targeting the triceps. It involves sitting on a bench, holding a dumbbell overhead with both hands, and lowering it behind the head before extending the arms back up.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0389.gif","youtube_id":null,"instructions":["Sit on a bench with your back straight and feet flat on the ground.","Hold a dumbbell with both hands and extend your arms straight up above your head.","Slowly lower the dumbbell behind your head, keeping your elbows close to your ears.","Pause for a moment, then raise the dumbbell back up to the starting position.","Repeat for the desired number of repetitions."]},{"id":"39","name":"barbell front chest squat","body_part":"upper legs","target":"glutes","secondary_muscles":["quadriceps","hamstrings","calves","core"],"equipment":"barbell","difficulty":"intermediate","description":"The barbell front chest squat is a compound lower body exercise that targets the glutes and also works the quadriceps, hamstrings, calves, and core. It involves holding a barbell at the front of the chest and performing a squat, which requires strength, balance, and proper technique.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0039.gif","youtube_id":null,"instructions":["Start by standing with your feet shoulder-width apart, toes slightly turned out.","Hold the barbell in front of your chest with your hands shoulder-width apart, elbows pointing forward.","Engage your core and keep your chest up as you lower your body down into a squat position, pushing your hips back and bending your knees.","Lower until your thighs are parallel to the ground, or as low as you can comfortably go.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"390","name":"dumbbell seated biceps curl (on stability ball)","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell seated biceps curl (on stability ball) is a biceps-focused exercise performed while seated on a stability ball, which adds an element of balance and core engagement. It targets the biceps and also works the forearms as secondary muscles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0390.gif","youtube_id":null,"instructions":["Sit on a stability ball with your feet flat on the ground and your back straight.","Hold a dumbbell in each hand with your palms facing forward and your arms fully extended.","Keeping your upper arms stationary, exhale and curl the dumbbells while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"391","name":"dumbbell seated curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell seated curl is a strength exercise targeting the biceps, performed while seated to minimize body movement and focus on arm isolation.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0391.gif","youtube_id":null,"instructions":["Sit on a bench with your feet flat on the ground and a dumbbell in each hand, palms facing forward.","Keep your back straight and your elbows close to your torso.","Exhale and curl the dumbbells up towards your shoulders, contracting your biceps.","Pause for a moment at the top, then inhale and slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"392","name":"dumbbell seated front raise","body_part":"shoulders","target":"delts","secondary_muscles":["trapezius","biceps"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell seated front raise is a shoulder exercise that targets the deltoid muscles. It is performed while seated, which helps to isolate the shoulders and minimize momentum, making it a controlled movement for building shoulder strength.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0392.gif","youtube_id":null,"instructions":["Sit on a bench with your feet flat on the ground and a dumbbell in each hand, resting on your thighs.","Keep your back straight and core engaged.","Raise the dumbbells in front of you, with your palms facing down, until they are at shoulder level.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"393","name":"dumbbell seated inner biceps curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell seated inner biceps curl targets the biceps and forearms by having the lifter sit on a bench, rest their upper arms on their thighs, and curl dumbbells upward. This isolates the biceps and minimizes momentum, making it an effective strength-building exercise.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0393.gif","youtube_id":null,"instructions":["Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand, palms facing up.","Rest your upper arms on your thighs, allowing the dumbbells to hang down.","Keeping your upper arms stationary, curl the dumbbells up towards your shoulders by contracting your biceps.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"394","name":"dumbbell seated kickback","body_part":"upper arms","target":"triceps","secondary_muscles":["shoulders"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell seated kickback is an isolation exercise targeting the triceps, performed while seated with dumbbells. It requires maintaining a stable posture and proper form to effectively engage the triceps.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0394.gif","youtube_id":null,"instructions":["Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand.","Bend your knees slightly and lean forward from your hips, keeping your back straight.","Bring your upper arms close to your sides and keep your elbows bent at a 90-degree angle.","Extend your arms straight back, squeezing your triceps at the top of the movement.","Pause for a moment, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"395","name":"dumbbell seated lateral raise v. 2","body_part":"shoulders","target":"delts","secondary_muscles":["traps","triceps"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell seated lateral raise (version 2) is an isolation exercise targeting the deltoid muscles. It is performed while seated, which helps minimize momentum and focuses the effort on the shoulder muscles. This exercise is commonly used to build shoulder width and strength.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0395.gif","youtube_id":null,"instructions":["Sit on a bench with your feet flat on the ground and a dumbbell in each hand, resting on your thighs.","Keep your back straight and core engaged.","Raise the dumbbells to your sides with a slight bend in your elbows, until your arms are parallel to the ground.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"396","name":"dumbbell seated lateral raise","body_part":"shoulders","target":"delts","secondary_muscles":["traps","upper back"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell seated lateral raise is an isolation exercise targeting the deltoid muscles of the shoulders. It is performed while seated, which helps minimize momentum and focuses the effort on the shoulder muscles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0396.gif","youtube_id":null,"instructions":["Sit on a bench with your feet flat on the ground and a dumbbell in each hand, resting on your thighs.","Keep your back straight and core engaged.","Raise the dumbbells to your sides with a slight bend in your elbows, until your arms are parallel to the ground.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"397","name":"dumbbell seated neutral wrist curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell seated neutral wrist curl targets the biceps and forearms by having the lifter curl dumbbells with a neutral grip while seated, focusing on wrist and forearm strength.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0397.gif","youtube_id":null,"instructions":["Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand, palms facing each other.","Rest your forearms on your thighs, allowing the dumbbells to hang down.","Keeping your wrists in a neutral position, curl the dumbbells up towards your shoulders.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"398","name":"dumbbell seated one arm kickback","body_part":"upper arms","target":"triceps","secondary_muscles":["shoulders"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell seated one arm kickback is an isolation exercise targeting the triceps, performed while seated on a bench. It requires a dumbbell and focuses on extending the arm backward to engage the triceps.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0398.gif","youtube_id":null,"instructions":["Sit on a bench with your feet flat on the ground and hold a dumbbell in one hand.","Bend your torso forward at the waist, keeping your back straight and parallel to the ground.","Extend your arm straight back, keeping your elbow close to your body.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]},{"id":"399","name":"dumbbell seated one arm rotate","body_part":"lower arms","target":"forearms","secondary_muscles":["shoulders","biceps"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell seated one arm rotate is an isolation exercise targeting the forearms, with secondary emphasis on the shoulders and biceps. It involves rotating the forearm outward while keeping the upper arm stationary, helping to improve forearm strength and mobility.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0399.gif","youtube_id":null,"instructions":["Sit on a bench with your back straight and hold a dumbbell in one hand, resting it on your thigh.","Raise the dumbbell up to shoulder height, keeping your elbow close to your body.","Rotate your forearm outward, away from your body, while keeping your upper arm stationary.","Pause for a moment at the top, then slowly rotate your forearm back to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]},{"id":"40","name":"barbell front raise and pullover","body_part":"chest","target":"pectorals","secondary_muscles":["deltoids","triceps"],"equipment":"barbell","difficulty":"intermediate","description":"The barbell front raise and pullover is a compound exercise targeting the pectorals, with secondary emphasis on the deltoids and triceps. It involves raising a barbell in front of the body and then performing a pullover motion behind the head, requiring strength, coordination, and shoulder mobility.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0040.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, palms facing down.","Keep your arms straight and raise the barbell in front of you until it reaches shoulder height.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Next, lower the barbell behind your head, keeping your arms straight.","Pause for a moment at the bottom, then raise the barbell back up to the starting position.","Repeat for the desired number of repetitions."]},{"id":"400","name":"dumbbell seated one leg calf raise","body_part":"lower legs","target":"calves","secondary_muscles":["hamstrings","glutes"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell seated one leg calf raise is an isolation exercise targeting the calf muscles, performed while seated with a dumbbell placed on the working thigh. It helps build strength and muscle in the calves, with some engagement of the hamstrings and glutes for stabilization.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0400.gif","youtube_id":null,"instructions":["Sit on a bench or chair with your feet flat on the ground and a dumbbell resting on your right thigh.","Extend your left leg straight out in front of you, keeping your foot flexed.","Place the ball of your right foot on an elevated surface, such as a step or weight plate.","Using your calf muscles, raise your right heel as high as possible.","Pause for a moment at the top, then slowly lower your heel back down to the starting position.","Repeat for the desired number of repetitions, then switch legs."]},{"id":"401","name":"dumbbell seated palms up wrist curl","body_part":"lower arms","target":"forearms","secondary_muscles":["biceps","shoulders"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell seated palms up wrist curl is an isolation exercise targeting the forearm muscles, specifically the wrist flexors. It is performed seated, with the forearms resting on the thighs and the wrists curling the dumbbells upward.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0401.gif","youtube_id":null,"instructions":["Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand, palms facing up.","Rest your forearms on your thighs, allowing your wrists to hang off the edge.","Slowly curl your wrists upward, squeezing your forearms at the top of the movement.","Pause for a moment, then lower your wrists back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"402","name":"dumbbell seated preacher curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell seated preacher curl is an isolation exercise targeting the biceps, performed while seated on a preacher bench to minimize momentum and maximize biceps engagement.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0402.gif","youtube_id":null,"instructions":["Sit on a preacher curl bench with your feet flat on the floor.","Hold a dumbbell in one hand with an underhand grip, resting your upper arm against the preacher pad.","Keeping your upper arm stationary, exhale and curl the dumbbell up towards your shoulder.","Pause for a moment at the top, then inhale and slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch arms."]},{"id":"403","name":"dumbbell seated reverse grip concentration curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell seated reverse grip concentration curl is an isolation exercise targeting the biceps, performed while seated with a dumbbell and a reverse (underhand) grip. It emphasizes strict form and muscle contraction.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0403.gif","youtube_id":null,"instructions":["Sit on a bench with your feet flat on the ground and hold a dumbbell in one hand, palm facing up.","Rest your elbow on the inside of your thigh, just above the knee.","Keeping your upper arm stationary, exhale and curl the dumbbell towards your shoulder.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]},{"id":"404","name":"dumbbell seated shoulder press (parallel grip)","body_part":"shoulders","target":"delts","secondary_muscles":["triceps","upper back"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell seated shoulder press (parallel grip) is a strength exercise targeting the deltoids, performed while seated with dumbbells held in a neutral grip. It also engages the triceps and upper back as secondary muscles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0404.gif","youtube_id":null,"instructions":["Sit on a bench with a dumbbell in each hand, palms facing inward.","Raise the dumbbells to shoulder height, elbows bent and palms facing forward.","Press the dumbbells upward until your arms are fully extended overhead.","Pause for a moment at the top, then slowly lower the dumbbells back to shoulder height.","Repeat for the desired number of repetitions."]},{"id":"405","name":"dumbbell seated shoulder press","body_part":"shoulders","target":"delts","secondary_muscles":["triceps","upper back"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell seated shoulder press is a strength exercise targeting the deltoid muscles of the shoulders. It is performed while seated, pressing dumbbells overhead to build shoulder and upper arm strength.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0405.gif","youtube_id":null,"instructions":["Sit on a bench with a dumbbell in each hand, resting on your thighs.","Raise the dumbbells to shoulder height, palms facing forward.","Press the dumbbells upward until your arms are fully extended overhead.","Pause for a moment at the top, then slowly lower the dumbbells back to shoulder height.","Repeat for the desired number of repetitions."]},{"id":"406","name":"dumbbell shrug","body_part":"back","target":"traps","secondary_muscles":["shoulders"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell shrug is an isolation exercise that targets the trapezius muscles. It involves lifting the shoulders towards the ears while holding dumbbells, focusing on building strength and size in the upper back.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0406.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and hold a dumbbell in each hand with your palms facing your body.","Keep your arms straight and let the dumbbells hang by your sides.","Raise your shoulders as high as possible, as if you are trying to touch your ears with your shoulders.","Hold the contraction for a second, then slowly lower your shoulders back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"407","name":"dumbbell side bend","body_part":"waist","target":"abs","secondary_muscles":["obliques"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell side bend is an isolation exercise targeting the oblique muscles and abs. It involves holding a dumbbell in one hand and bending sideways at the waist to work the core.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0407.gif","youtube_id":null,"instructions":["Stand up straight with your feet shoulder-width apart and hold a dumbbell in one hand, letting it hang down by your side.","Keeping your back straight and your core engaged, slowly bend sideways at the waist towards the opposite side of the dumbbell, lowering the weight as far as you comfortably can.","Pause for a moment, then slowly return to the starting position.","Repeat for the desired number of repetitions, then switch sides and repeat."]},{"id":"408","name":"dumbbell side lying one hand raise","body_part":"shoulders","target":"delts","secondary_muscles":["trapezius","rhomboids"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell side lying one hand raise targets the deltoid muscles and is performed lying on your side, lifting a dumbbell with one arm to shoulder height. This exercise isolates the shoulder muscles and helps improve strength and stability.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0408.gif","youtube_id":null,"instructions":["Lie on your side with your legs extended and your head supported by your arm.","Hold a dumbbell in your top hand with your palm facing down.","Keeping your arm straight, raise the dumbbell up to shoulder height.","Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch sides."]},{"id":"409","name":"dumbbell single leg calf raise","body_part":"lower legs","target":"calves","secondary_muscles":["ankles"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell single leg calf raise is a unilateral lower leg exercise that targets the calves, performed while holding a dumbbell for added resistance. It challenges balance and strength by isolating one leg at a time.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0409.gif","youtube_id":null,"instructions":["Stand on the edge of a step or platform with your heels hanging off and your toes on the step.","Hold a dumbbell in one hand and place your other hand on a wall or railing for support.","Raise your heel as high as possible, lifting your body up onto your toes.","Pause for a moment at the top, then slowly lower your heel back down below the step.","Repeat for the desired number of repetitions, then switch to the other leg."]},{"id":"41","name":"barbell front raise","body_part":"shoulders","target":"delts","secondary_muscles":["biceps","triceps"],"equipment":"barbell","difficulty":"beginner","description":"The barbell front raise is a shoulder exercise that targets the deltoids by lifting a barbell from the thighs to shoulder height with straight arms.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0041.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and hold a barbell in front of your thighs with an overhand grip.","Keep your arms straight and lift the barbell forward and upward until it reaches shoulder level.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"410","name":"dumbbell single leg split squat","body_part":"upper legs","target":"quads","secondary_muscles":["glutes","hamstrings","calves"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell single leg split squat is a unilateral lower body exercise that targets the quadriceps, with secondary emphasis on the glutes, hamstrings, and calves. It requires balance, coordination, and strength, as one leg is elevated and the movement is performed with added resistance from dumbbells.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0410.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand.","Take a step forward with one foot and position your feet so that your front foot is flat on the ground and your back foot is elevated on a bench or step.","Lower your body by bending your front knee and hip, keeping your back knee slightly bent and your back heel off the ground.","Continue lowering until your front thigh is parallel to the ground, then push through your front heel to return to the starting position.","Repeat for the desired number of repetitions, then switch legs and repeat."]},{"id":"411","name":"dumbbell single leg squat","body_part":"upper legs","target":"glutes","secondary_muscles":["quadriceps","hamstrings","calves"],"equipment":"dumbbell","difficulty":"advanced","description":"The dumbbell single leg squat is a challenging lower body exercise that targets the glutes while also engaging the quadriceps, hamstrings, and calves. It requires balance, coordination, and strength, as you perform a squat on one leg while holding dumbbells for added resistance.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0411.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand.","Extend one leg forward and keep it off the ground throughout the exercise.","Bend your standing leg and lower your body down as if sitting back into a chair.","Keep your chest up and your back straight.","Pause for a moment at the bottom, then push through your heel to return to the starting position.","Repeat for the desired number of repetitions, then switch legs."]},{"id":"413","name":"dumbbell squat","body_part":"upper legs","target":"glutes","secondary_muscles":["quadriceps","hamstrings","calves"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell squat is a lower body strength exercise that targets the glutes, quadriceps, and hamstrings, while also engaging the calves. It is performed by holding a dumbbell in each hand and squatting down and up with proper form.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0413.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand at your sides.","Keeping your chest up and core engaged, lower your body down by bending at the knees and hips, as if sitting back into a chair.","Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"414","name":"dumbbell standing alternate overhead press","body_part":"shoulders","target":"delts","secondary_muscles":["triceps","core"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell standing alternate overhead press is a shoulder exercise that involves pressing dumbbells overhead one arm at a time while standing. This movement targets the deltoid muscles and also engages the triceps and core for stability.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0414.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder level with your palms facing forward.","Press one dumbbell overhead, fully extending your arm.","Lower the dumbbell back to shoulder level.","Repeat with the other arm.","Continue alternating arms for the desired number of repetitions."]},{"id":"415","name":"dumbbell standing alternate raise","body_part":"shoulders","target":"delts","secondary_muscles":["traps","forearms"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell standing alternate raise is a shoulder exercise that targets the deltoid muscles by lifting dumbbells alternately to the side, improving shoulder strength and stability.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0415.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing your body.","Keep your back straight and your core engaged.","Raise one dumbbell to the side, keeping your arm straight and your palm facing down.","Continue lifting until your arm is parallel to the ground.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat with the other arm.","Alternate between arms for the desired number of repetitions."]},{"id":"416","name":"dumbbell standing biceps curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell standing biceps curl is a classic strength exercise that targets the biceps and also engages the forearms. It involves curling dumbbells from a standing position, focusing on controlled movement and muscle contraction.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0416.gif","youtube_id":null,"instructions":["Stand up straight with a dumbbell in each hand, palms facing forward and arms fully extended.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"417","name":"dumbbell standing calf raise","body_part":"lower legs","target":"calves","secondary_muscles":["ankles"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell standing calf raise is an exercise that targets the calf muscles by lifting the heels off the ground while holding dumbbells for added resistance.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0417.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand.","Raise your heels off the ground as high as possible, using your calves.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"418","name":"dumbbell standing concentration curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell standing concentration curl is an isolation exercise targeting the biceps, performed while standing and using one arm at a time for focused contraction.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0418.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and hold a dumbbell in one hand, with your arm fully extended and palm facing inwards.","Place your opposite hand on your thigh for support.","Keeping your upper arm stationary, exhale and curl the dumbbell towards your shoulder by contracting your biceps.","Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]},{"id":"419","name":"dumbbell standing front raise above head","body_part":"shoulders","target":"delts","secondary_muscles":["trapezius","biceps"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell standing front raise above head is a shoulder exercise that targets the deltoids by lifting dumbbells from thigh level to above the head in a controlled motion.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0419.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.","Keep your arms straight and lift the dumbbells in front of you, raising them above your head.","Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"42","name":"barbell front squat","body_part":"upper legs","target":"glutes","secondary_muscles":["quadriceps","hamstrings","calves","core"],"equipment":"barbell","difficulty":"intermediate","description":"The barbell front squat is a compound lower body exercise that targets the glutes, quadriceps, and hamstrings, while also engaging the core for stability. The barbell is held in front of the shoulders, requiring good mobility and core strength to maintain proper posture throughout the movement.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0042.gif","youtube_id":null,"instructions":["Start by standing with your feet shoulder-width apart, toes slightly turned out.","Hold the barbell in front of your shoulders, resting it on your collarbone and shoulders.","Engage your core and keep your chest up as you lower your body down into a squat position, pushing your hips back and bending your knees.","Lower until your thighs are parallel to the ground, or as low as you can comfortably go.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"420","name":"dumbbell standing kickback","body_part":"upper arms","target":"triceps","secondary_muscles":["shoulders"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell standing kickback is an isolation exercise targeting the triceps, performed by hinging at the hips and extending the arms backward with dumbbells.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0420.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and hold a dumbbell in each hand.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Extend your arms straight back, squeezing your triceps at the top of the movement.","Pause for a moment, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"421","name":"dumbbell standing one arm concentration curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell standing one arm concentration curl is an isolation exercise targeting the biceps, performed while standing and focusing on one arm at a time for increased muscle engagement.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0421.gif","youtube_id":null,"instructions":["Stand up straight with your feet shoulder-width apart and hold a dumbbell in one hand, palm facing up.","Place your free hand on your thigh for support.","Keeping your upper arm stationary, exhale and curl the dumbbell towards your shoulder by contracting your biceps.","Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]},{"id":"422","name":"dumbbell standing one arm curl (over incline bench)","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell standing one arm curl (over incline bench) is an isolation exercise targeting the biceps, performed by standing and curling a dumbbell with one arm while using an incline bench for support.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0422.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, holding a dumbbell in one hand with your palm facing forward.","Place your other hand on an incline bench for support.","Keeping your upper arm stationary, exhale and curl the dumbbell towards your shoulder by contracting your biceps.","Pause for a moment at the top, then inhale and slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]},{"id":"423","name":"dumbbell standing one arm extension","body_part":"upper arms","target":"triceps","secondary_muscles":["shoulders"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell standing one arm extension is an isolation exercise targeting the triceps. It involves holding a dumbbell overhead with one arm and extending the elbow to lift the weight, focusing on triceps engagement.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0423.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, holding a dumbbell in one hand.","Raise the dumbbell overhead, fully extending your arm.","Keep your upper arm close to your head and perpendicular to the ground.","Slowly lower the dumbbell behind your head, bending your elbow.","Pause for a moment, then raise the dumbbell back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"424","name":"dumbbell standing one arm palm in press","body_part":"shoulders","target":"delts","secondary_muscles":["triceps","core"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell standing one arm palm in press is a unilateral shoulder exercise that targets the deltoids while also engaging the triceps and core for stabilization. It is performed standing, pressing a dumbbell overhead with one arm at a time, palm facing inward.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0424.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, holding a dumbbell in one hand at shoulder height with your palm facing inwards.","Engage your core and keep your back straight.","Press the dumbbell upwards until your arm is fully extended.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]},{"id":"4240","name":"resistance band horizontal pallof press","body_part":"waist","target":"abs","secondary_muscles":["glutes","delts","pectorals","triceps"],"equipment":"resistance band","difficulty":"beginner","description":"Stand perpendicular to a chest-height anchored resistance band, holding it at your sternum with both hands. Brace your core and press the band straight out in front of you, resisting any rotation, then return under control.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-4240.gif","youtube_id":null,"instructions":["Anchor the band at chest height and stand sideways to it, feet hip-width, knees softly bent.","Grip the band with both hands at your sternum; stack ribs over pelvis and set a neutral spine.","Square hips and shoulders forward, away from the anchor; tense glutes and brace the abs.","Exhale and press the band straight out from your sternum until elbows are extended without shrugging.","Pause while resisting the band’s pull—do not let the torso rotate.","Inhale and draw the hands back to the sternum under control, maintaining alignment.","Complete reps, then switch sides to train the opposite direction."]},{"id":"4241","name":"resistance band shuttle","body_part":"upper legs","target":"abductors","secondary_muscles":["glutes","quads","hamstrings","calves","abs"],"equipment":"resistance band","difficulty":"beginner","description":"Loop a resistance band around your ankles, assume an athletic quarter-squat, and shuffle laterally while keeping constant band tension. Move for the set distance, then reverse while maintaining knee alignment and a stable torso.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-4241.gif","youtube_id":null,"instructions":["Place a light-to-moderate loop band around your ankles and stand hip-width with toes forward.","Drop into a quarter-squat: hips back, chest up, core braced, knees tracking over toes.","Create slight outward tension on the band so the knees don’t collapse inward.","Step laterally with the lead foot 12–24 inches, then bring the trail foot in just enough to keep the band taut—no slack.","Keep hips level, feet parallel, and weight through midfoot/heels as you shuffle for the prescribed steps or distance.","Pause under control, then reverse direction leading with the opposite leg for equal distance.","Maintain a steady tempo and neutral spine; avoid torso rotation or letting knees cave inward.","Reset if posture or tension is lost before continuing."]},{"id":"4242","name":"broad jump to vertical","body_part":"upper legs","target":"quads","secondary_muscles":["glutes","hamstrings","calves","abs","adductors"],"equipment":"body weight","difficulty":"advanced","description":"From an athletic stance, jump forward in a powerful standing broad jump. Absorb the landing and immediately transition into a vertical jump, then land softly and reset.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-4242.gif","youtube_id":null,"instructions":["Stand with feet hip‑to‑shoulder width, toes slightly out, core braced, eyes forward.","Hinge and descend to a quarter–half squat with heels down and neutral spine, arms sweeping back.","Explosively swing the arms forward and triple‑extend hips, knees, and ankles to broad jump ahead.","Land softly on mid‑to‑forefoot then heels, feet under hips, knees tracking over toes, hips back.","Quickly absorb and rebound: swing the arms and drive straight up into a vertical jump.","Reach tall while keeping the torso upright and core tight.","Land softly again with knees and hips slightly bent; stabilize.","Reset spacing and repeat only while maintaining knee alignment and controlled landings."]},{"id":"4243","name":"medicine ball overhead throw","body_part":"upper arms","target":"triceps","secondary_muscles":["delts","pectorals","serratus anterior","traps","abs"],"equipment":"medicine ball","difficulty":"intermediate","description":"Stand holding a medicine ball at your chest with feet shoulder-width. Dip and then explosively extend through the hips, shoulders, and elbows to throw the ball overhead and forward to a partner or wall.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-4243.gif","youtube_id":null,"instructions":["Stand tall with feet shoulder-width and hold the medicine ball at mid‑chest, elbows under the ball and wrists neutral.","Brace your core and take a small dip by bending hips and knees while keeping the torso upright.","Drive through the legs and extend the hips, then rapidly flex the shoulders and extend the elbows to launch the ball overhead and forward.","Release the ball slightly above forehead level at a 30–45° angle while keeping the ribcage down to avoid low‑back arching.","Finish tall on the toes with arms extended and eyes forward.","Catch the return (or retrieve the ball) with soft knees and a neutral spine.","Reset, inhale, and repeat powerful, crisp throws; exhale on each release."]},{"id":"4244","name":"kettlebell overhead carry","body_part":"shoulders","target":"delts","secondary_muscles":["traps","serratus anterior","triceps","abs","upper back","glutes"],"equipment":"kettlebell","difficulty":"intermediate","description":"Stand tall and press a kettlebell overhead with both hands on the horns, locking the elbows with the biceps near the ears. Maintain a stacked rib‑cage–pelvis position and walk under control for distance or time while keeping the kettlebell directly over your midfoot.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-4244.gif","youtube_id":null,"instructions":["Select a moderate kettlebell, hold it by the horns at chest height, then press it overhead until elbows are straight and wrists neutral.","Set your position: ribs down, pelvis neutral, abs and glutes braced; biceps align with or slightly behind the ears.","Actively reach the kettlebell to the ceiling so the shoulder blades upwardly rotate; keep the weight stacked over the midfoot.","Begin walking with small, controlled steps and a tall posture—no leaning, rib flare, or low‑back arch.","Keep the kettlebell stable (no drifting forward/back), eyes forward, and breathe behind the brace.","Turn carefully as needed without losing overhead lockout or trunk alignment.","After the set, stop, lower the kettlebell to the chest with control, then to the floor."]},{"id":"4245","name":"single leg board jump","body_part":"upper legs","target":"quads","secondary_muscles":["glutes","hamstrings","calves","adductors","abductors","abs"],"equipment":"body weight","difficulty":"intermediate","description":"Stand on one leg facing a low board or marked landing spot. Load into a quarter squat and explosively hop forward to land softly on the same leg, stabilizing before the next rep.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-4245.gif","youtube_id":null,"instructions":["Stand tall on one leg facing the board/target, core braced, hip–knee–toe aligned.","Hinge slightly and descend into a quarter squat, arms sweeping back, free leg behind for balance.","Drive through the standing foot, extending ankle, knee, and hip to jump forward.","Swing the arms forward to assist, keeping the torso controlled and knee tracking over toes.","Land softly on the same foot, ball-to-heel, with knee bent and hips back.","Hold and stabilize for 1–2 seconds without the knee collapsing inward.","Reset posture and repeat for reps, then switch legs."]},{"id":"425","name":"dumbbell standing one arm reverse curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell standing one arm reverse curl targets the biceps and forearms using a dumbbell with an overhand grip, emphasizing the brachialis and forearm extensors.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0425.gif","youtube_id":null,"instructions":["Stand up straight with your feet shoulder-width apart and hold a dumbbell in one hand with an overhand grip.","Keep your arm fully extended and close to your body, with your palm facing down.","Slowly curl the dumbbell up towards your shoulder, keeping your upper arm stationary.","Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]},{"id":"4253","name":"medicine ball crunch","body_part":"waist","target":"abs","secondary_muscles":["obliques","hip flexors","serratus anterior"],"equipment":"medicine ball","difficulty":"intermediate","description":"Lie on your back with knees bent and feet flat, holding a medicine ball against your chest. Curl your torso to lift the shoulder blades off the floor, then return under control.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-4253.gif","youtube_id":null,"instructions":["Lie supine with knees bent ~90° and feet hip-width apart; hold the medicine ball against your chest with elbows tucked.","Posteriorly tilt the pelvis to lightly flatten the low back; brace the abs and keep the neck neutral with a slight chin tuck.","Exhale and curl the trunk, lifting head, shoulders, and upper back until the shoulder blades just clear the floor; keep the ball touching your chest.","Pause briefly and squeeze the abs; do not pull with the arms or jut the chin forward.","Inhale and lower slowly, placing the spine back down segment by segment until the shoulder blades touch.","Maintain a small, controlled range and steady tension; stop if you feel low-back discomfort or hip flexor dominance."]},{"id":"4254","name":"single leg vertical jump","body_part":"upper legs","target":"quads","secondary_muscles":["glutes","hamstrings","calves","abs"],"equipment":"body weight","difficulty":"advanced","description":"Stand on one leg, dip into a quarter squat, then explode straight up using an arm swing. Land softly on the same leg, absorb the force, and reset before the next rep.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-4254.gif","youtube_id":null,"instructions":["Stand tall on one leg with the other knee slightly flexed and arms by your sides.","Engage your core, keep your chest up, and align the stance knee over the toes.","Hinge slightly at the hips and dip into a quarter squat to load the leg.","Swing the arms upward and drive through the whole foot, extending hip, knee, and ankle to jump vertically.","Lift the non-jumping knee up as you reach maximal height while keeping the torso neutral.","Land quietly on the same leg with a soft knee and hip, absorbing the impact through hip–knee–ankle.","Reset balance and repeat for reps, then switch legs. Keep the knee tracking over the toes and avoid valgus collapse."]},{"id":"4255","name":"straight leg hip bridge","body_part":"upper legs","target":"hamstrings","secondary_muscles":["glutes","abs","spine","calves"],"equipment":"body weight","difficulty":"intermediate","description":"Lie on your back with legs straight and heels on the floor, arms across chest. Drive through the heels to lift the hips until your body forms a straight line from shoulders to ankles, then lower with control.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-4255.gif","youtube_id":null,"instructions":["Lie supine with legs straight hip-width apart, heels on the floor and toes pointed up.","Brace the core and lightly posteriorly tilt the pelvis; keep knees extended without locking out.","Press the heels into the floor and squeeze the hamstrings and glutes to lift the hips.","Raise until your shoulders, hips, and ankles align; keep ribs down and neck neutral.","Pause 1–2 seconds while maintaining straight legs and level hips.","Lower the hips slowly to the floor without arching the lower back.","Exhale on the lift, inhale on the descent, and repeat for reps."]},{"id":"4256","name":"stepdown squat","body_part":"upper legs","target":"quads","secondary_muscles":["glutes","hamstrings","calves","abductors","abs"],"equipment":"body weight","difficulty":"intermediate","description":"Stand on a stable step with one leg as the support and the other foot hanging off the edge. Lower under control until the free heel lightly taps the floor, then drive back up to stand tall.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-4256.gif","youtube_id":null,"instructions":["Stand tall on a sturdy step 15–30 cm high; toes forward, hands on hips or out for balance.","Shift your weight fully over the working leg, keeping pelvis level and core braced.","Bend the stance knee and hip to descend, letting the free heel reach toward the floor in front.","Track the stance knee over the second–third toe; do not let it cave inward.","Lightly tap the floor with the free heel without transferring weight to it.","Press through the stance midfoot/heel to extend the knee and hip and return to the start.","Complete all reps under slow control, then switch legs."]},{"id":"4257","name":"shuffle","body_part":"cardio","target":"cardiovascular system","secondary_muscles":["quads","glutes","hamstrings","calves","abductors","adductors"],"equipment":"body weight","difficulty":"intermediate","description":"Start in a low athletic stance and move laterally with quick, short steps, staying on the balls of your feet. Shuffle side to side while keeping your hips low and torso stable to elevate heart rate.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-4257.gif","youtube_id":null,"instructions":["Stand in an athletic stance: feet hip–shoulder width, knees bent, hips back, chest up, arms ready.","Brace your core and stay light on the balls of your feet.","Push off the trail foot and step the lead foot laterally; quickly slide the trail foot in without crossing.","Keep hips low and level; track knees over toes and avoid letting them cave inward.","Take 2–4 quick shuffles in one direction, then plant the outside foot and reverse.","Move fast but controlled, landing softly each step, and continue for the set time or distance."]},{"id":"4258","name":"backwards run","body_part":"cardio","target":"cardiovascular system","secondary_muscles":["quads","hamstrings","glutes","calves","abs"],"equipment":"body weight","difficulty":"intermediate","description":"Run in reverse on a clear, flat surface using short, quick steps and a soft mid/forefoot landing. Keep an upright torso, core braced, and pump the arms while periodically checking behind you for safety.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-4258.gif","youtube_id":null,"instructions":["Choose a clear, obstacle‑free lane; face forward with tall posture and brace your core.","Shift weight slightly onto the balls of your feet and initiate movement by pushing the ground away to step backward.","Land softly on the mid/forefoot with knees slightly bent; keep feet under your hips to avoid overstriding.","Maintain an upright torso, neutral spine, and look over your shoulder periodically (or use a spotter) to steer.","Pump arms naturally opposite the legs and keep a quick, compact cadence.","Breathe steadily and stop or turn around to reorient whenever you lose clear visibility."]},{"id":"426","name":"dumbbell standing overhead press","body_part":"shoulders","target":"delts","secondary_muscles":["triceps","upper back"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell standing overhead press is a compound exercise targeting the deltoids, performed by pressing dumbbells overhead from shoulder height while standing.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0426.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder level with your palms facing forward.","Press the dumbbells upward until your arms are fully extended overhead.","Pause for a moment at the top, then slowly lower the dumbbells back down to shoulder level.","Repeat for the desired number of repetitions."]},{"id":"427","name":"dumbbell standing palms in press","body_part":"shoulders","target":"delts","secondary_muscles":["triceps","chest"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell standing palms in press is a shoulder exercise that targets the deltoids, with secondary emphasis on the triceps and chest. It involves pressing dumbbells overhead while keeping the palms facing inward, which can be easier on the shoulder joints compared to a traditional overhead press.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0427.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder level with your palms facing inwards.","Keeping your core engaged and your back straight, press the dumbbells upwards until your arms are fully extended overhead.","Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"428","name":"dumbbell standing preacher curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell standing preacher curl is an isolation exercise targeting the biceps, performed while standing and bracing the upper arms against a preacher or incline bench for strict form.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0428.gif","youtube_id":null,"instructions":["Stand upright with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing forward.","Rest the back of your upper arms against the preacher bench or an incline bench, with your elbows slightly bent.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"429","name":"dumbbell standing reverse curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell standing reverse curl is an exercise targeting the biceps and forearms, performed by curling dumbbells with an overhand grip while standing.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0429.gif","youtube_id":null,"instructions":["Stand up straight with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing your body.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"43","name":"barbell full squat","body_part":"upper legs","target":"glutes","secondary_muscles":["quadriceps","hamstrings","calves","core"],"equipment":"barbell","difficulty":"intermediate","description":"The barbell full squat is a compound lower body exercise that targets the glutes and also works the quadriceps, hamstrings, calves, and core. It involves squatting down with a barbell placed across the upper back, requiring strength, balance, and proper technique.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0043.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, toes slightly turned out.","Hold the barbell across your upper back, resting it on your traps or rear delts.","Engage your core and keep your chest up as you begin to lower your body down.","Bend at the knees and hips, pushing your hips back and down as if sitting into a chair.","Lower yourself until your thighs are parallel to the ground or slightly below.","Keep your knees in line with your toes and your weight in your heels.","Drive through your heels to stand back up, extending your hips and knees.","Repeat for the desired number of repetitions."]},{"id":"430","name":"dumbbell standing triceps extension","body_part":"upper arms","target":"triceps","secondary_muscles":["shoulders"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell standing triceps extension is an isolation exercise targeting the triceps, performed by raising a dumbbell overhead and extending the arm. It also engages the shoulders as secondary muscles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0430.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and hold a dumbbell in one hand.","Raise the dumbbell overhead, keeping your arm straight.","Bend your elbow and lower the dumbbell behind your head, keeping your upper arm stationary.","Extend your arm back up to the starting position.","Repeat for the desired number of repetitions."]},{"id":"431","name":"dumbbell step-up","body_part":"upper legs","target":"glutes","secondary_muscles":["quadriceps","hamstrings","calves"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell step-up is a lower body exercise that targets the glutes, quadriceps, and hamstrings, while also engaging the calves. It involves stepping onto a raised platform while holding dumbbells, which increases resistance and challenges balance and coordination.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0431.gif","youtube_id":null,"instructions":["Stand in front of a bench or step with a dumbbell in each hand, palms facing your body.","Place your right foot on the bench or step, ensuring your entire foot is in contact with the surface.","Push through your right heel and lift your body up onto the bench or step, straightening your right leg.","Bring your left foot up onto the bench or step, standing fully upright.","Step back down with your left foot, followed by your right foot, returning to the starting position.","Repeat for the desired number of repetitions, then switch legs."]},{"id":"432","name":"dumbbell stiff leg deadlift","body_part":"upper legs","target":"glutes","secondary_muscles":["hamstrings","lower back"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell stiff leg deadlift is a lower body exercise that targets the glutes and hamstrings, with additional activation of the lower back. It involves hinging at the hips while keeping the legs mostly straight, emphasizing a stretch and contraction in the posterior chain.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0432.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.","Keeping your back straight and your core engaged, hinge at the hips and lower the dumbbells towards the ground, allowing a slight bend in your knees.","Lower the dumbbells until you feel a stretch in your hamstrings, then squeeze your glutes and push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"433","name":"dumbbell straight arm pullover","body_part":"chest","target":"pectorals","secondary_muscles":["latissimus dorsi","triceps"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell straight arm pullover is a chest exercise that also targets the lats and triceps. It involves lying on a bench and moving a dumbbell in an arc over and behind your head while keeping your arms straight.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0433.gif","youtube_id":null,"instructions":["Lie flat on a bench with your head at one end and your feet planted firmly on the ground.","Hold a dumbbell with both hands and extend your arms straight above your chest.","Keeping your arms straight, slowly lower the dumbbell behind your head in an arc-like motion.","Pause for a moment, then raise the dumbbell back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"434","name":"dumbbell straight leg deadlift","body_part":"upper legs","target":"glutes","secondary_muscles":["hamstrings","lower back"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell straight leg deadlift is a strength exercise targeting the glutes, hamstrings, and lower back. It involves hinging at the hips while keeping the back straight and lowering dumbbells toward the ground, then returning to the starting position.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0434.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.","Keeping your back straight and your core engaged, hinge at the hips and lower the dumbbells towards the ground, allowing your torso to lean forward.","Continue lowering the dumbbells until you feel a stretch in your hamstrings, keeping your knees slightly bent.","Pause for a moment at the bottom, then engage your glutes and hamstrings to lift your torso back up to the starting position.","Repeat for the desired number of repetitions."]},{"id":"436","name":"dumbbell tate press","body_part":"upper arms","target":"triceps","secondary_muscles":["shoulders"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell Tate press is an upper arm exercise primarily targeting the triceps, with secondary involvement of the shoulders. It is performed with dumbbells while seated on a flat bench, involving a unique pressing motion that emphasizes triceps activation.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0436.gif","youtube_id":null,"instructions":["Sit on a flat bench with a dumbbell in each hand, palms facing each other.","Raise the dumbbells to shoulder height, then rotate your wrists so that your palms are facing away from you.","Press the dumbbells up until your arms are fully extended, then lower them back down to shoulder height.","Rotate your wrists back to the starting position and repeat for the desired number of repetitions."]},{"id":"437","name":"dumbbell upright row","body_part":"shoulders","target":"delts","secondary_muscles":["traps","biceps"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell upright row is a strength exercise targeting the deltoids, with secondary emphasis on the traps and biceps. It involves lifting dumbbells from thigh level to chin height, leading with the elbows.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0437.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.","Let the dumbbells hang in front of your thighs, with your arms fully extended.","Keeping your back straight and your core engaged, exhale and lift the dumbbells straight up towards your chin, leading with your elbows.","Pause for a moment at the top, then inhale and slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"438","name":"dumbbell w-press","body_part":"shoulders","target":"delts","secondary_muscles":["triceps","chest"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell W-press is a shoulder exercise performed with dumbbells, focusing on the deltoid muscles. It involves pressing the weights overhead from a 'W' position, engaging the shoulders, triceps, and chest.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0438.gif","youtube_id":null,"instructions":["Sit on a bench with a dumbbell in each hand, palms facing forward.","Raise the dumbbells to shoulder height, elbows bent and palms facing forward.","Press the dumbbells upward until your arms are fully extended overhead.","Lower the dumbbells back to shoulder height.","Repeat for the desired number of repetitions."]},{"id":"439","name":"dumbbell zottman curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell Zottman curl is a biceps exercise that incorporates both a standard curl and a reverse curl, targeting the biceps and forearms. It involves rotating the wrists at the top of the movement to work both muscle groups effectively.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0439.gif","youtube_id":null,"instructions":["Stand up straight with a dumbbell in each hand, palms facing your body.","Keep your elbows close to your torso and rotate your palms to face forward.","Curl the dumbbells up to your shoulders while keeping your upper arms stationary.","At the top of the movement, rotate your wrists so that your palms are facing away from your body.","Slowly lower the dumbbells back to the starting position, rotating your palms back to facing your body.","Repeat for the desired number of repetitions."]},{"id":"44","name":"barbell good morning","body_part":"upper legs","target":"hamstrings","secondary_muscles":["lower back"],"equipment":"barbell","difficulty":"intermediate","description":"The barbell good morning is a compound exercise that targets the hamstrings and lower back. It involves hinging at the hips with a barbell on your upper back, requiring good form and core stability to perform safely.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0044.gif","youtube_id":null,"instructions":["Start by standing with your feet shoulder-width apart and the barbell resting on your upper back.","Keeping your back straight and your core engaged, hinge forward at the hips, pushing your buttocks back as if you were trying to touch the wall behind you with your glutes.","Lower your torso until it is parallel to the ground, feeling a stretch in your hamstrings.","Pause for a moment, then return to the starting position by squeezing your glutes and pushing your hips forward.","Repeat for the desired number of repetitions."]},{"id":"443","name":"elbow-to-knee","body_part":"waist","target":"abs","secondary_muscles":["obliques"],"equipment":"body weight","difficulty":"beginner","description":"The elbow-to-knee exercise is a bodyweight movement targeting the abdominal muscles, especially the abs and obliques, through a twisting, crunch-like motion.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0443.gif","youtube_id":null,"instructions":["Start by lying flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engage your abs and lift your upper body off the ground, bringing your right elbow towards your left knee.","At the same time, bring your left knee towards your right elbow, creating a twisting motion.","Pause for a moment at the top, then slowly lower your upper body and extend your legs back to the starting position.","Repeat the movement, this time bringing your left elbow towards your right knee and your right knee towards your left elbow.","Continue alternating sides for the desired number of repetitions."]},{"id":"445","name":"ez barbell anti gravity press","body_part":"shoulders","target":"delts","secondary_muscles":["triceps","chest"],"equipment":"ez barbell","difficulty":"intermediate","description":"The EZ barbell anti gravity press is a shoulder exercise performed with an EZ barbell. It targets the deltoids and also works the triceps and chest. The movement involves pressing the barbell overhead from shoulder height while standing.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0445.gif","youtube_id":null,"instructions":["Start by standing with your feet shoulder-width apart and holding the ez barbell with an overhand grip.","Raise the barbell to shoulder height, keeping your elbows slightly bent and your palms facing forward.","Press the barbell overhead, extending your arms fully.","Lower the barbell back to shoulder height and repeat for the desired number of repetitions."]},{"id":"446","name":"ez barbell close-grip curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"ez barbell","difficulty":"beginner","description":"The EZ barbell close-grip curl is a biceps-focused exercise performed with an EZ barbell using a close, underhand grip. It targets the biceps and also engages the forearms as secondary muscles. The movement involves curling the barbell towards the shoulders while keeping the elbows close to the torso.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0446.gif","youtube_id":null,"instructions":["Stand up straight with your feet shoulder-width apart and hold the ez barbell with an underhand grip, hands shoulder-width apart.","Keep your elbows close to your torso and your upper arms stationary throughout the movement.","Curl the barbell up towards your shoulders, contracting your biceps.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"447","name":"ez barbell curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"ez barbell","difficulty":"beginner","description":"The EZ barbell curl is a classic arm exercise that targets the biceps using an EZ curl bar. It is performed standing, with an underhand grip, and involves curling the bar up towards the shoulders while keeping the elbows close to the torso.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0447.gif","youtube_id":null,"instructions":["Stand up straight with your feet shoulder-width apart and hold the ez barbell with an underhand grip, palms facing up.","Keep your elbows close to your torso and your upper arms stationary throughout the movement.","Exhale as you curl the barbell up towards your shoulders, contracting your biceps.","Pause for a moment at the top, then inhale as you slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"448","name":"ez barbell decline close grip face press","body_part":"upper arms","target":"triceps","secondary_muscles":["chest","shoulders"],"equipment":"ez barbell","difficulty":"intermediate","description":"The EZ barbell decline close grip face press is a triceps-focused exercise performed on a decline bench using an EZ barbell. It also engages the chest and shoulders as secondary muscles. The movement requires control and proper form to avoid injury, especially due to the bar path near the face and the decline position.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0448.gif","youtube_id":null,"instructions":["Lie on a decline bench with your head lower than your feet.","Grasp the ez barbell with a close grip, palms facing each other.","Extend your arms straight up above your chest, keeping your elbows close to your body.","Lower the barbell towards your forehead by bending your elbows.","Pause for a moment, then press the barbell back up to the starting position.","Repeat for the desired number of repetitions."]},{"id":"449","name":"ez barbell incline triceps extension","body_part":"upper arms","target":"triceps","secondary_muscles":["shoulders"],"equipment":"ez barbell","difficulty":"intermediate","description":"The EZ barbell incline triceps extension is an isolation exercise targeting the triceps, performed on an incline bench using an EZ bar. It requires good form to avoid shoulder strain and to effectively work the triceps.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0449.gif","youtube_id":null,"instructions":["Set up an incline bench at a 45-degree angle.","Sit on the bench with your back against the pad and hold the ez barbell with an overhand grip.","Extend your arms fully overhead, keeping your elbows close to your head.","Lower the barbell behind your head by bending your elbows, keeping your upper arms stationary.","Pause for a moment, then extend your arms back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"45","name":"barbell guillotine bench press","body_part":"chest","target":"pectorals","secondary_muscles":["shoulders","triceps"],"equipment":"barbell","difficulty":"advanced","description":"The barbell guillotine bench press is a variation of the bench press where the bar is lowered to the neck instead of the chest, placing greater emphasis on the upper pectorals. This exercise requires careful control and proper technique to avoid injury.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0045.gif","youtube_id":null,"instructions":["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.","Lower the barbell slowly towards your neck, keeping your elbows pointed outwards.","Pause for a moment when the barbell is just above your neck.","Push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]},{"id":"450","name":"ez barbell jm bench press","body_part":"upper arms","target":"triceps","secondary_muscles":["chest","shoulders"],"equipment":"ez barbell","difficulty":"advanced","description":"The EZ Barbell JM Bench Press is a triceps-focused pressing movement performed on a bench using an EZ bar. It combines elements of a close-grip bench press and a triceps extension, targeting the triceps while also engaging the chest and shoulders.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0450.gif","youtube_id":null,"instructions":["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Grasp the ez barbell with an overhand grip, slightly wider than shoulder-width apart.","Lower the barbell to your chest, keeping your elbows tucked in close to your body.","Push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]},{"id":"451","name":"ez barbell reverse grip curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"ez barbell","difficulty":"beginner","description":"The EZ barbell reverse grip curl is an isolation exercise targeting the biceps, with additional activation of the forearms. It is performed using an EZ barbell with an underhand grip, focusing on curling the barbell upwards while keeping the elbows close to the torso.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0451.gif","youtube_id":null,"instructions":["Stand up straight with your feet shoulder-width apart and hold the ez barbell with an underhand grip.","Keep your elbows close to your torso and your upper arms stationary throughout the exercise.","Curl the barbell upwards by contracting your biceps, while exhaling.","Continue to raise the barbell until your biceps are fully contracted and the barbell is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Slowly begin to bring the barbell back to the starting position as you inhale.","Repeat for the desired number of repetitions."]},{"id":"452","name":"ez barbell reverse grip preacher curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"ez barbell","difficulty":"intermediate","description":"The EZ barbell reverse grip preacher curl is an isolation exercise targeting the biceps, with additional activation of the forearms. It is performed seated on a preacher bench, using an EZ barbell with a reverse (underhand) grip.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0452.gif","youtube_id":null,"instructions":["Sit on a preacher bench with your chest against the pad and your feet flat on the floor.","Grasp the ez barbell with an underhand grip, hands shoulder-width apart.","Rest your upper arms on the pad, allowing your forearms to hang down.","Keeping your upper arms stationary, exhale and curl the barbell up towards your shoulders.","Pause for a moment at the top, then inhale and slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"453","name":"ez barbell seated triceps extension","body_part":"upper arms","target":"triceps","secondary_muscles":["shoulders"],"equipment":"ez barbell","difficulty":"intermediate","description":"The EZ barbell seated triceps extension is an isolation exercise targeting the triceps, performed while seated with an EZ barbell. It emphasizes triceps strength and development, with some involvement of the shoulders for stabilization.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0453.gif","youtube_id":null,"instructions":["Sit on a bench with your back straight and feet flat on the ground.","Hold the ez barbell with an overhand grip, hands shoulder-width apart.","Raise the barbell overhead, fully extending your arms.","Keeping your upper arms stationary, lower the barbell behind your head by bending your elbows.","Pause for a moment, then raise the barbell back to the starting position by extending your arms.","Repeat for the desired number of repetitions."]},{"id":"454","name":"ez barbell spider curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"ez barbell","difficulty":"intermediate","description":"The EZ barbell spider curl is an isolation exercise targeting the biceps, performed with the upper arms supported on a preacher bench or stability ball to minimize cheating and maximize biceps engagement.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0454.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and hold the ez barbell with an underhand grip, palms facing up.","Rest your upper arms on a preacher bench or stability ball, allowing your elbows to hang down.","Keeping your upper arms stationary, exhale and curl the barbell up towards your shoulders.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"455","name":"finger curls","body_part":"lower arms","target":"forearms","secondary_muscles":["wrist flexors","grip muscles"],"equipment":"barbell","difficulty":"beginner","description":"Finger curls are an isolation exercise targeting the forearms, specifically the finger flexors and grip muscles. This movement helps improve grip strength and forearm development.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0455.gif","youtube_id":null,"instructions":["Sit on a bench with your feet flat on the ground and hold a barbell with an underhand grip, palms facing up.","Rest your forearms on your thighs, allowing your wrists to hang off the edge.","Slowly curl your fingers towards your palms, squeezing the barbell tightly.","Hold the contraction for a moment, then slowly release your fingers back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"456","name":"flexion leg sit up (bent knee)","body_part":"waist","target":"abs","secondary_muscles":["hip flexors"],"equipment":"body weight","difficulty":"intermediate","description":"The flexion leg sit up (bent knee) is an abdominal exercise performed with body weight. It involves curling the upper body and bringing the knees toward the chest simultaneously, targeting the abs and hip flexors.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0456.gif","youtube_id":null,"instructions":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","At the same time, lift your legs off the ground, bending your knees and bringing them towards your chest.","Pause for a moment at the top, then slowly lower your upper body and legs back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"457","name":"flexion leg sit up (straight arm)","body_part":"waist","target":"abs","secondary_muscles":["hip flexors","quadriceps"],"equipment":"body weight","difficulty":"intermediate","description":"The flexion leg sit up (straight arm) is an abdominal exercise performed with body weight. It involves lying flat, extending the arms overhead, and simultaneously lifting the upper body and legs to meet in the middle, targeting the abs and engaging the hip flexors and quadriceps.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0457.gif","youtube_id":null,"instructions":["Lie flat on your back with your legs extended and arms straight above your head.","Engaging your abs, lift your upper body off the ground while simultaneously lifting your legs towards your chest.","Reach your hands towards your toes as you lift your upper body and legs.","Pause for a moment at the top, then slowly lower your upper body and legs back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"458","name":"floor fly (with barbell)","body_part":"chest","target":"pectorals","secondary_muscles":["deltoids","triceps"],"equipment":"barbell","difficulty":"intermediate","description":"The floor fly with barbell is a chest exercise performed lying on the floor, focusing on stretching and contracting the pectoral muscles while using a barbell for resistance.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0458.gif","youtube_id":null,"instructions":["Lie flat on your back on the floor with your knees bent and feet flat on the ground.","Hold a barbell with an overhand grip, arms extended straight up over your chest.","Slowly lower the barbell out to the sides, keeping a slight bend in your elbows.","Lower the barbell until your arms are parallel to the floor, feeling a stretch in your chest.","Pause for a moment, then squeeze your chest muscles to bring the barbell back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"459","name":"flutter kicks","body_part":"upper legs","target":"glutes","secondary_muscles":["hip flexors","lower abs"],"equipment":"body weight","difficulty":"beginner","description":"Flutter kicks are a bodyweight exercise performed lying on your back, where you lift your legs off the ground and alternate kicking them up and down in a fluttering motion. This movement primarily targets the glutes, with secondary emphasis on the hip flexors and lower abs.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0459.gif","youtube_id":null,"instructions":["Lie flat on your back with your legs extended and your hands by your sides.","Engage your core and lift your legs off the ground about 6 inches.","Keeping your legs straight, alternate lifting one leg slightly higher than the other.","Continue this fluttering motion for the desired number of repetitions."]},{"id":"46","name":"barbell hack squat","body_part":"upper legs","target":"glutes","secondary_muscles":["quadriceps","hamstrings","calves"],"equipment":"barbell","difficulty":"intermediate","description":"The barbell hack squat is a lower body strength exercise that targets the glutes, quadriceps, hamstrings, and calves. It involves holding a barbell behind the legs and performing a squat motion, emphasizing the posterior chain and quadriceps.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0046.gif","youtube_id":null,"instructions":["Start by standing with your feet shoulder-width apart and your toes slightly turned out.","Hold the barbell behind your legs, resting it on your upper thighs.","Lower your body by bending at the knees and hips, keeping your back straight and your chest up.","Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.","Pause for a moment, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"462","name":"front and back neck stretch","body_part":"neck","target":"levator scapulae","secondary_muscles":["upper trapezius","sternocleidomastoid","scalenes","suboccipitals"],"equipment":"body weight","difficulty":"beginner","description":"Stand or sit tall and use your hand(s) to gently guide the head into forward flexion to stretch the back of the neck, then into slight extension to stretch the front of the neck. Move slowly and only to a mild, comfortable stretch.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0462.gif","youtube_id":null,"instructions":["Stand or sit upright with feet grounded, shoulders relaxed, and eyes forward.","For the back-of-neck stretch: place one or both hands on the crown and gently draw the chin toward the chest until you feel a mild stretch along the back of the neck.","Keep your torso tall without rounding the upper back; hold 15–30 seconds and breathe steadily.","Return the head to neutral slowly.","For the front-of-neck stretch: keep hands light for support and gently look upward, lengthening the front of the neck without collapsing or pinching the back of the neck.","Hold 10–20 seconds, breathing calmly, then return to neutral.","Repeat 1–3 times per direction; stop if you feel pain, tingling, or dizziness."]},{"id":"464","name":"front plank with twist","body_part":"waist","target":"abs","secondary_muscles":["obliques","shoulders"],"equipment":"body weight","difficulty":"intermediate","description":"The front plank with twist is a core exercise that targets the abs and obliques while also engaging the shoulders. It involves rotating the torso while maintaining a plank position, which challenges stability and coordination.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0464.gif","youtube_id":null,"instructions":["Start in a high plank position with your hands directly under your shoulders and your body in a straight line from head to toe.","Engage your core and glutes to maintain a stable position.","Rotate your torso to the right, lifting your right arm and extending it towards the ceiling.","Keep your hips and legs stable as you twist.","Hold for a moment, then return to the starting position.","Repeat the twist on the left side.","Continue alternating sides for the desired number of repetitions."]},{"id":"466","name":"gironda sternum chin","body_part":"back","target":"lats","secondary_muscles":["biceps","rhomboids","rear deltoids"],"equipment":"body weight","difficulty":"advanced","description":"The Gironda sternum chin is a challenging bodyweight exercise that targets the lats and requires pulling your chest up to the bar, emphasizing a strong contraction in the upper back. It also engages the biceps, rhomboids, and rear deltoids.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0466.gif","youtube_id":null,"instructions":["Stand facing a high bar with your feet shoulder-width apart.","Reach up and grab the bar with an overhand grip, slightly wider than shoulder-width apart.","Hang from the bar with your arms fully extended and your body straight.","Engage your lats and biceps to pull your chest up towards the bar, leading with your sternum.","Pause for a moment at the top, then slowly lower yourself back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"467","name":"gorilla chin","body_part":"waist","target":"abs","secondary_muscles":["forearms","biceps"],"equipment":"body weight","difficulty":"advanced","description":"The gorilla chin is a challenging bodyweight exercise that targets the abs while also engaging the forearms and biceps. It involves a pull-up motion with a strong core contraction to bring the chin above the bar.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0467.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and your knees slightly bent.","Grasp a pull-up bar with an overhand grip, slightly wider than shoulder-width apart.","Hang from the bar with your arms fully extended and your palms facing away from you.","Engage your core and pull your body up towards the bar, bringing your chin above the bar.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"469","name":"groin crunch","body_part":"waist","target":"abs","secondary_muscles":["hip flexors","inner thighs"],"equipment":"body weight","difficulty":"beginner","description":"The groin crunch is a bodyweight exercise targeting the abdominal muscles, with secondary emphasis on the hip flexors and inner thighs. It involves lying on your back, bringing your knees towards your chest while engaging your core.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0469.gif","youtube_id":null,"instructions":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, lift your legs off the ground, bringing your knees towards your chest.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"47","name":"barbell incline bench press","body_part":"chest","target":"pectorals","secondary_muscles":["shoulders","triceps"],"equipment":"barbell","difficulty":"intermediate","description":"The barbell incline bench press is a compound upper-body exercise that targets the upper portion of the pectoral muscles, with secondary emphasis on the shoulders and triceps. It is performed on an incline bench using a barbell, making it a staple in strength training routines for developing chest size and strength.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0047.gif","youtube_id":null,"instructions":["Set up an incline bench at a 45-degree angle.","Lie down on the bench with your feet flat on the ground.","Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.","Unrack the barbell and lower it slowly towards your chest, keeping your elbows at a 45-degree angle.","Pause for a moment at the bottom, then push the barbell back up to the starting position.","Repeat for the desired number of repetitions."]},{"id":"471","name":"handstand push-up","body_part":"upper arms","target":"triceps","secondary_muscles":["shoulders","chest","core"],"equipment":"body weight","difficulty":"advanced","description":"The handstand push-up is a challenging bodyweight exercise that targets the triceps, shoulders, chest, and core. It requires significant upper body strength, balance, and coordination, as well as experience with inversion movements.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0471.gif","youtube_id":null,"instructions":["Find a wall and face away from it, standing a few feet away.","Place your hands on the ground shoulder-width apart and kick your feet up against the wall, coming into a handstand position.","Bend your elbows and lower your head towards the ground, keeping your body in a straight line.","Push through your hands and extend your arms to return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"472","name":"hanging leg raise","body_part":"waist","target":"abs","secondary_muscles":["hip flexors"],"equipment":"body weight","difficulty":"advanced","description":"The hanging leg raise is a bodyweight exercise that targets the abdominal muscles and hip flexors. It requires hanging from a pull-up bar and lifting the legs up in front of the body, engaging the core throughout the movement.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0472.gif","youtube_id":null,"instructions":["Hang from a pull-up bar with your arms fully extended and your palms facing away from you.","Engage your core and lift your legs up in front of you, keeping them straight.","Continue lifting until your legs are parallel to the ground or as high as you can comfortably go.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"473","name":"hanging pike","body_part":"waist","target":"abs","secondary_muscles":["hip flexors","shoulders"],"equipment":"body weight","difficulty":"advanced","description":"The hanging pike is a challenging core exercise performed by hanging from a pull-up bar and lifting the legs straight up to form a 'V' shape with the body, targeting the abdominal muscles and hip flexors.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0473.gif","youtube_id":null,"instructions":["Hang from a pull-up bar with your arms fully extended and your palms facing away from you.","Engage your core and lift your legs up towards the bar, keeping them straight.","Continue lifting until your body forms a 'V' shape, with your legs parallel to the ground.","Hold the position for a moment, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"474","name":"hanging straight leg hip raise","body_part":"waist","target":"abs","secondary_muscles":["hip flexors"],"equipment":"body weight","difficulty":"advanced","description":"The hanging straight leg hip raise is an advanced core exercise that targets the abdominal muscles and hip flexors. It requires significant core strength, grip strength, and control to perform the movement safely and effectively while hanging from a pull-up bar.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0474.gif","youtube_id":null,"instructions":["Hang from a pull-up bar with your arms fully extended and your palms facing away from you.","Engage your core and lift your legs up in front of you until they are parallel to the ground.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"475","name":"hanging straight leg raise","body_part":"waist","target":"abs","secondary_muscles":["hip flexors"],"equipment":"body weight","difficulty":"advanced","description":"The hanging straight leg raise is an advanced core exercise performed by hanging from a pull-up bar and lifting the legs straight up in front of the body. It primarily targets the abdominal muscles and also engages the hip flexors.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0475.gif","youtube_id":null,"instructions":["Hang from a pull-up bar with your arms fully extended and your palms facing away from you.","Engage your core and lift your legs up in front of you, keeping them straight.","Continue lifting until your legs are parallel to the ground or as high as you can comfortably go.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"476","name":"hanging straight twisting leg hip raise","body_part":"waist","target":"abs","secondary_muscles":["obliques","hip flexors"],"equipment":"body weight","difficulty":"advanced","description":"The hanging straight twisting leg hip raise is a challenging core exercise that targets the abs, obliques, and hip flexors. It requires hanging from a pull-up bar, lifting the legs, and twisting the hips to engage the entire core.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0476.gif","youtube_id":null,"instructions":["Hang from a pull-up bar with your arms fully extended and your legs straight.","Engage your core and lift your legs up towards your chest, keeping them straight.","Once your legs are parallel to the ground, twist your hips to one side, bringing your legs towards that side.","Pause for a moment, then return to the starting position.","Repeat the movement, but this time twist your hips to the opposite side.","Continue alternating sides for the desired number of repetitions."]},{"id":"48","name":"barbell incline reverse-grip press","body_part":"upper arms","target":"triceps","secondary_muscles":["chest","shoulders"],"equipment":"barbell","difficulty":"intermediate","description":"The barbell incline reverse-grip press is a compound upper body exercise that targets the triceps while also engaging the chest and shoulders. It is performed on an incline bench using a reverse (underhand) grip on the barbell.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0048.gif","youtube_id":null,"instructions":["Set up an incline bench at a 45-degree angle.","Lie back on the bench and grasp the barbell with a reverse grip, hands slightly wider than shoulder-width apart.","Unrack the barbell and lower it towards your upper chest, keeping your elbows tucked in.","Pause for a moment at the bottom, then push the barbell back up to the starting position.","Repeat for the desired number of repetitions."]},{"id":"484","name":"hip raise (bent knee)","body_part":"waist","target":"abs","secondary_muscles":["glutes","hamstrings"],"equipment":"body weight","difficulty":"beginner","description":"The hip raise (bent knee) is a bodyweight exercise that targets the abdominal muscles, with secondary emphasis on the glutes and hamstrings. It involves lifting the hips off the ground while lying on your back with knees bent, engaging the core and posterior chain.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0484.gif","youtube_id":null,"instructions":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands by your sides, palms facing down.","Engage your core and glutes, then lift your hips off the ground until your body forms a straight line from your knees to your shoulders.","Pause for a moment at the top, then slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"488","name":"hyperextension (on bench)","body_part":"back","target":"spine","secondary_muscles":["glutes","hamstrings"],"equipment":"body weight","difficulty":"beginner","description":"The hyperextension (on bench) is a bodyweight exercise that targets the spinal erectors and lower back, while also engaging the glutes and hamstrings. It is performed on a hyperextension bench, requiring the user to lower and raise their upper body while keeping the back straight.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0488.gif","youtube_id":null,"instructions":["Adjust the hyperextension bench so that your hips are resting comfortably on the pad and your feet are secured.","Cross your arms over your chest or place your hands behind your head.","Slowly lower your upper body towards the ground while keeping your back straight.","Pause for a moment at the bottom, then raise your upper body back up until it is in line with your legs.","Repeat for the desired number of repetitions."]},{"id":"489","name":"hyperextension","body_part":"back","target":"spine","secondary_muscles":["glutes","hamstrings"],"equipment":"body weight","difficulty":"beginner","description":"The hyperextension is a bodyweight exercise that targets the spinal erectors and lower back, with secondary emphasis on the glutes and hamstrings. It is performed on a hyperextension bench and involves lowering and raising the upper body while keeping the back straight.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0489.gif","youtube_id":null,"instructions":["Adjust the hyperextension bench so that your upper thighs are resting on the pad and your feet are secured.","Cross your arms over your chest or place your hands behind your head.","Lower your upper body towards the ground while keeping your back straight.","Pause for a moment at the bottom, then raise your upper body back up until it is in line with your legs.","Repeat for the desired number of repetitions."]},{"id":"49","name":"barbell incline row","body_part":"back","target":"upper back","secondary_muscles":["biceps","forearms"],"equipment":"barbell","difficulty":"intermediate","description":"The barbell incline row is a compound exercise targeting the upper back, performed while lying face down on an incline bench and pulling a barbell towards the chest.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0049.gif","youtube_id":null,"instructions":["Set up an incline bench at a 45-degree angle.","Lie face down on the bench with your chest against the pad and your feet flat on the ground.","Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.","Keep your back straight and your core engaged.","Pull the barbell towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"490","name":"incline close-grip push-up","body_part":"upper arms","target":"triceps","secondary_muscles":["chest","shoulders"],"equipment":"body weight","difficulty":"beginner","description":"The incline close-grip push-up is a bodyweight exercise that targets the triceps, with secondary emphasis on the chest and shoulders. It is performed by placing the hands on an elevated surface, keeping the elbows close to the body, and performing a push-up motion.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0490.gif","youtube_id":null,"instructions":["Place your hands on an elevated surface, such as a bench or step, slightly wider than shoulder-width apart.","Extend your legs behind you, resting on the balls of your feet, with your body forming a straight line from head to heels.","Lower your chest towards the elevated surface by bending your elbows, keeping them close to your sides.","Pause for a moment at the bottom, then push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."]},{"id":"491","name":"incline leg hip raise (leg straight)","body_part":"waist","target":"abs","secondary_muscles":["hip flexors"],"equipment":"body weight","difficulty":"intermediate","description":"The incline leg hip raise (leg straight) is an abdominal exercise performed on an incline bench. It targets the abs and also works the hip flexors. The movement requires you to lift your straight legs upward while lying on an incline, emphasizing core control and strength.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0491.gif","youtube_id":null,"instructions":["Lie on an incline bench with your back flat against the bench and your legs extended straight out in front of you.","Place your hands on the sides of the bench for support.","Engaging your abs, lift your legs off the bench, raising them as high as you can while keeping them straight.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"492","name":"incline push up depth jump","body_part":"chest","target":"pectorals","secondary_muscles":["triceps","shoulders","core"],"equipment":"body weight","difficulty":"advanced","description":"The incline push up depth jump is a dynamic exercise that combines an incline push-up with a plyometric depth jump. It targets the chest, triceps, shoulders, and core, and requires both upper body strength and lower body explosiveness.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0492.gif","youtube_id":null,"instructions":["Find an elevated surface, such as a bench or step, and place your hands shoulder-width apart on the edge.","Step your feet back, keeping your body in a straight line from head to heels.","Lower your chest towards the edge of the surface, bending your elbows and keeping your body aligned.","Push through your palms to extend your arms and return to the starting position.","Jump off the edge of the surface, landing softly with your knees slightly bent.","Repeat the push-up and depth jump for the desired number of repetitions."]},{"id":"493","name":"incline push-up","body_part":"chest","target":"pectorals","secondary_muscles":["triceps","shoulders"],"equipment":"body weight","difficulty":"beginner","description":"The incline push-up is a bodyweight exercise that targets the pectoral muscles by performing a push-up with the hands elevated on a surface such as a bench or step. This variation reduces the load compared to a standard push-up, making it more accessible for beginners.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0493.gif","youtube_id":null,"instructions":["Place your hands on an elevated surface, such as a bench or step, slightly wider than shoulder-width apart.","Extend your legs behind you, resting on the balls of your feet, creating a straight line from your head to your heels.","Lower your chest towards the elevated surface by bending your elbows, keeping your body in a straight line.","Pause for a moment at the bottom, then push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."]},{"id":"494","name":"incline reverse grip push-up","body_part":"chest","target":"pectorals","secondary_muscles":["triceps","shoulders"],"equipment":"body weight","difficulty":"intermediate","description":"The incline reverse grip push-up is a bodyweight exercise targeting the pectorals, performed with hands on an elevated surface and palms facing towards you (reverse grip). It emphasizes the upper chest and triceps while requiring stability and control.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0494.gif","youtube_id":null,"instructions":["Place your hands on the edge of a bench or elevated surface, slightly wider than shoulder-width apart.","Extend your legs behind you, resting on the balls of your feet, creating a straight line from your head to your heels.","Lower your chest towards the bench by bending your elbows, keeping them close to your sides.","Pause for a moment at the bottom, then push yourself back up to the starting position by extending your arms.","Repeat for the desired number of repetitions."]},{"id":"495","name":"incline twisting sit-up","body_part":"waist","target":"abs","secondary_muscles":["obliques"],"equipment":"body weight","difficulty":"intermediate","description":"The incline twisting sit-up is an abdominal exercise performed on an incline bench, targeting the abs and obliques by adding a rotational movement to the traditional sit-up.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0495.gif","youtube_id":null,"instructions":["Set up an incline bench at a 45-degree angle.","Lie down on the bench with your feet secured under the foot pads.","Place your hands behind your head or across your chest.","Engage your abs and lift your upper body off the bench, curling forward.","As you curl up, twist your torso to one side, bringing your elbow towards the opposite knee.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat the movement, this time twisting your torso to the other side.","Continue alternating sides for the desired number of repetitions."]},{"id":"496","name":"inverse leg curl (bench support)","body_part":"upper legs","target":"hamstrings","secondary_muscles":["glutes","calves"],"equipment":"body weight","difficulty":"intermediate","description":"The inverse leg curl (bench support) is a bodyweight exercise targeting the hamstrings, performed lying face down on a bench while curling the legs toward the glutes.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0496.gif","youtube_id":null,"instructions":["Lie face down on a bench with your hips at the edge and your legs extended straight behind you.","Hold onto the bench for support.","Keeping your upper body still, bend your knees and curl your legs towards your glutes.","Pause for a moment at the top, then slowly extend your legs back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"497","name":"inverted row v. 2","body_part":"back","target":"upper back","secondary_muscles":["biceps","forearms"],"equipment":"body weight","difficulty":"beginner","description":"The inverted row v. 2 is a bodyweight exercise targeting the upper back, performed by pulling your chest up to a bar or suspension trainer while keeping your body straight. It also engages the biceps and forearms.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0497.gif","youtube_id":null,"instructions":["Set up a bar at waist height on a Smith machine or use a suspension trainer.","Stand facing the bar or suspension trainer and grab it with an overhand grip, hands shoulder-width apart.","Walk your feet forward, leaning back until your body is at a slight angle.","Keep your body straight and pull your chest up towards the bar or handles, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower yourself back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"498","name":"inverted row with straps","body_part":"back","target":"upper back","secondary_muscles":["biceps","forearms"],"equipment":"body weight","difficulty":"intermediate","description":"The inverted row with straps is a bodyweight exercise targeting the upper back, performed using suspension straps. It requires pulling your chest towards the handles while maintaining a straight body position.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0498.gif","youtube_id":null,"instructions":["Set up a suspension trainer or straps at chest height.","Stand facing the anchor point and grab the handles with an overhand grip.","Walk your feet forward, leaning back until your body is at an angle.","Keep your body straight and engage your core.","Pull your chest towards the handles, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower yourself back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"499","name":"inverted row","body_part":"back","target":"upper back","secondary_muscles":["biceps","forearms"],"equipment":"body weight","difficulty":"beginner","description":"The inverted row is a bodyweight exercise that targets the upper back and also works the biceps and forearms. It involves pulling your chest up to a bar or suspension trainer while keeping your body straight, making it an effective movement for building upper body strength and improving posture.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0499.gif","youtube_id":null,"instructions":["Set up a bar at waist height or use a suspension trainer.","Stand facing the bar or suspension trainer, with your feet shoulder-width apart.","Grab the bar or handles with an overhand grip, slightly wider than shoulder-width apart.","Lean back, keeping your body straight and your heels on the ground.","Pull your chest towards the bar or handles, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower yourself back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"50","name":"barbell incline shoulder raise","body_part":"chest","target":"serratus anterior","secondary_muscles":["deltoids","trapezius"],"equipment":"barbell","difficulty":"intermediate","description":"The barbell incline shoulder raise is performed on an incline bench and targets the serratus anterior, with secondary emphasis on the deltoids and trapezius. The movement involves raising a barbell overhead from shoulder height while seated on an incline bench.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0050.gif","youtube_id":null,"instructions":["Set up an incline bench at a 45-degree angle.","Sit on the bench with your back against the pad and feet flat on the ground.","Hold a barbell with an overhand grip, slightly wider than shoulder-width apart.","Lift the barbell up to shoulder height, keeping your elbows slightly bent.","Slowly raise the barbell overhead, extending your arms fully.","Pause for a moment at the top, then slowly lower the barbell back to shoulder height.","Repeat for the desired number of repetitions."]},{"id":"500","name":"isometric wipers","body_part":"chest","target":"pectorals","secondary_muscles":["shoulders","triceps","core"],"equipment":"body weight","difficulty":"advanced","description":"Isometric wipers are a challenging bodyweight exercise that targets the pectorals while also engaging the shoulders, triceps, and core. The movement requires significant core strength and control as you move your legs side to side while keeping your upper body stable.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0500.gif","youtube_id":null,"instructions":["Start by lying flat on your back on a mat or bench.","Extend your arms straight out to the sides, perpendicular to your body.","Engage your core and lift both legs off the ground, keeping them together and straight.","Slowly lower your legs to one side, aiming to touch the ground with your feet while maintaining control.","Pause for a moment, then use your core to lift your legs back to the starting position.","Repeat the movement, this time lowering your legs to the opposite side.","Continue alternating sides for the desired number of repetitions."]},{"id":"501","name":"jack burpee","body_part":"cardio","target":"cardiovascular system","secondary_muscles":["quadriceps","hamstrings","calves","shoulders","triceps","core"],"equipment":"body weight","difficulty":"advanced","description":"The jack burpee is a high-intensity, full-body exercise that combines a squat, push-up, and jump to elevate heart rate and improve cardiovascular fitness while also engaging multiple muscle groups.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0501.gif","youtube_id":null,"instructions":["Start in a standing position with your feet shoulder-width apart.","Lower your body into a squat position, placing your hands on the ground in front of you.","Kick your feet back, landing in a push-up position.","Perform a push-up, lowering your chest to the ground and then pushing back up.","Jump your feet forward, landing in a squat position.","Jump up explosively, reaching your arms overhead.","Land softly and immediately lower back into the squat position to begin the next repetition."]},{"id":"507","name":"jackknife sit-up","body_part":"waist","target":"abs","secondary_muscles":["hip flexors"],"equipment":"body weight","difficulty":"intermediate","description":"The jackknife sit-up is a bodyweight exercise targeting the abdominal muscles. It involves simultaneously lifting the legs and upper body to meet in the middle, engaging the core and hip flexors.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0507.gif","youtube_id":null,"instructions":["Lie flat on your back with your legs extended and your arms overhead.","Engage your core and lift your legs and upper body simultaneously, reaching your hands towards your toes.","Pause for a moment at the top, then slowly lower your legs and upper body back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"508","name":"janda sit-up","body_part":"waist","target":"abs","secondary_muscles":["hip flexors","lower back"],"equipment":"body weight","difficulty":"advanced","description":"The Janda sit-up is an advanced abdominal exercise that emphasizes the abs while minimizing hip flexor involvement. It requires significant core strength and proper technique to perform safely and effectively.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0508.gif","youtube_id":null,"instructions":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"51","name":"barbell jefferson squat","body_part":"upper legs","target":"glutes","secondary_muscles":["quadriceps","hamstrings","calves"],"equipment":"barbell","difficulty":"intermediate","description":"The barbell Jefferson squat is a compound lower body exercise that targets the glutes, quadriceps, hamstrings, and calves. It involves holding a barbell between the legs and performing a squat with a staggered stance, alternating foot positions with each repetition.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0051.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and toes slightly turned out.","Hold the barbell with an overhand grip, resting it on the front of your body, just below your waist.","Step your left foot forward and your right foot back, keeping your feet shoulder-width apart.","Bend your knees and lower your body down into a squat position, keeping your back straight and chest up.","Push through your heels to stand back up to the starting position.","Repeat the movement, alternating your forward and back foot with each repetition."]},{"id":"513","name":"jump squat v. 2","body_part":"upper legs","target":"glutes","secondary_muscles":["quadriceps","hamstrings","calves"],"equipment":"body weight","difficulty":"intermediate","description":"The jump squat v. 2 is a plyometric lower body exercise that targets the glutes, quadriceps, hamstrings, and calves. It involves explosive jumping from a squat position and landing softly before repeating the movement.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0513.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart.","Lower your body into a squat position by bending your knees and pushing your hips back.","Jump explosively, extending your hips and knees fully.","Land softly on the balls of your feet and immediately lower your body back into a squat position.","Repeat for the desired number of repetitions."]},{"id":"514","name":"jump squat","body_part":"upper legs","target":"glutes","secondary_muscles":["quadriceps","hamstrings","calves"],"equipment":"body weight","difficulty":"intermediate","description":"The jump squat is a plyometric exercise that targets the glutes and also works the quadriceps, hamstrings, and calves. It involves squatting down and then jumping explosively, making it effective for building lower body power and explosiveness.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0514.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart.","Lower your body into a squat position by bending your knees and pushing your hips back.","Jump explosively off the ground, extending your hips, knees, and ankles.","While in mid-air, quickly bring your arms forward for balance.","Land softly on the balls of your feet and immediately go into the next repetition.","Repeat for the desired number of repetitions."]},{"id":"517","name":"kettlebell advanced windmill","body_part":"waist","target":"abs","secondary_muscles":["obliques","shoulders"],"equipment":"kettlebell","difficulty":"advanced","description":"The kettlebell advanced windmill is a challenging exercise that targets the abs and obliques while also engaging the shoulders. It requires balance, coordination, and strength, particularly in the core and shoulders, as you hold a kettlebell overhead and hinge at the hips to lower your torso.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0517.gif","youtube_id":null,"instructions":["Stand with your feet wider than shoulder-width apart, toes pointing slightly outward.","Hold a kettlebell in your right hand, with your arm extended overhead and your palm facing forward.","Rotate your left foot slightly to the right, and shift your weight onto your left leg.","Bend your left knee and hinge at the hip, lowering your torso towards the left side.","Keep your right arm extended overhead and your eyes on the kettlebell.","As you lower your torso, allow your right leg to straighten and your right foot to pivot slightly.","Lower your torso until you feel a stretch in your left hamstring and your right arm is pointing towards the ground.","Pause for a moment, then engage your core and push through your left heel to return to the starting position.","Repeat for the desired number of repetitions, then switch sides."]},{"id":"518","name":"kettlebell alternating hang clean","body_part":"lower arms","target":"forearms","secondary_muscles":["shoulders","traps","core"],"equipment":"kettlebell","difficulty":"intermediate","description":"The kettlebell alternating hang clean is a dynamic exercise targeting the forearms, with significant involvement of the shoulders, traps, and core. It requires coordination, explosive power, and proper technique to safely transition the kettlebell from the hang to the rack position while alternating arms.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0518.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, holding a kettlebell in each hand with an overhand grip.","Bend your knees slightly and hinge forward at the hips, keeping your back straight and chest up.","Allow the kettlebells to hang in front of your body with your arms fully extended.","In one fluid motion, explosively extend your hips, shrug your shoulders, and pull the kettlebells up towards your shoulders.","As the kettlebells reach shoulder height, rotate your wrists and catch the kettlebells in the rack position, with your palms facing inward and the kettlebells resting on the outside of your forearms.","Lower the kettlebells back down to the starting position and repeat the movement with the opposite arm.","Continue alternating arms for the desired number of repetitions."]},{"id":"519","name":"kettlebell alternating press on floor","body_part":"chest","target":"pectorals","secondary_muscles":["shoulders","triceps"],"equipment":"kettlebell","difficulty":"intermediate","description":"The kettlebell alternating press on floor is a chest exercise performed while lying on the floor, pressing kettlebells alternately with each arm. This movement targets the pectorals and also works the shoulders and triceps.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0519.gif","youtube_id":null,"instructions":["Start by lying on your back on the floor with your knees bent and feet flat on the ground.","Hold a kettlebell in each hand, with your palms facing towards your feet and your arms extended straight up towards the ceiling.","Lower one kettlebell down towards your shoulder while keeping the other kettlebell extended straight up.","Press the lowered kettlebell back up to the starting position while simultaneously lowering the other kettlebell down towards your shoulder.","Continue alternating the press motion with each kettlebell for the desired number of repetitions."]},{"id":"52","name":"barbell jm bench press","body_part":"upper arms","target":"triceps","secondary_muscles":["chest","shoulders"],"equipment":"barbell","difficulty":"advanced","description":"The barbell JM bench press is a triceps-focused pressing movement that combines elements of a close-grip bench press and a triceps extension. It is performed lying on a bench, lowering the barbell to the chest with elbows tucked, and pressing back up.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0052.gif","youtube_id":null,"instructions":["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.","Lower the barbell to your chest, keeping your elbows tucked in close to your body.","Push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]},{"id":"520","name":"kettlebell alternating press","body_part":"shoulders","target":"delts","secondary_muscles":["triceps","core"],"equipment":"kettlebell","difficulty":"intermediate","description":"The kettlebell alternating press is a shoulder exercise where you press one kettlebell overhead at a time, alternating arms. This movement targets the deltoids and also engages the triceps and core for stability.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0520.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, holding a kettlebell in each hand at shoulder height.","Press one kettlebell overhead, fully extending your arm.","Lower the kettlebell back to shoulder height.","Repeat with the other arm.","Continue alternating arms for the desired number of repetitions."]},{"id":"5201","name":"dumbbell waiter biceps curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms","shoulders"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell waiter biceps curl is an isolation exercise targeting the biceps, performed with dumbbells. It also engages the forearms and shoulders as secondary muscles. The movement requires basic strength and coordination, making it suitable for most fitness levels.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-5201.gif","youtube_id":null,"instructions":["Stand up straight with a dumbbell in each hand, palms facing forward.","Keep your upper arms close to your body and your elbows tucked in.","Slowly curl the dumbbells up towards your shoulders, keeping your wrists straight.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"521","name":"kettlebell alternating renegade row","body_part":"back","target":"upper back","secondary_muscles":["core","shoulders"],"equipment":"kettlebell","difficulty":"advanced","description":"The kettlebell alternating renegade row is a compound exercise that targets the upper back while also engaging the core and shoulders. It requires maintaining a plank position while performing alternating rows with kettlebells, challenging both strength and stability.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0521.gif","youtube_id":null,"instructions":["Start in a high plank position with your hands gripping the kettlebells and your feet hip-width apart.","Engage your core and keep your body in a straight line from head to heels.","Pull one kettlebell up towards your chest, keeping your elbow close to your body.","Lower the kettlebell back down to the starting position and repeat with the other arm.","Continue alternating arms for the desired number of repetitions."]},{"id":"522","name":"kettlebell alternating row","body_part":"back","target":"upper back","secondary_muscles":["biceps","forearms"],"equipment":"kettlebell","difficulty":"intermediate","description":"The kettlebell alternating row is a compound exercise targeting the upper back, performed by alternating rowing movements with kettlebells while maintaining a bent-over position.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0522.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, knees slightly bent, and hold a kettlebell in each hand with your palms facing your body.","Bend forward at the hips, keeping your back straight and your core engaged.","Pull one kettlebell up towards your chest, keeping your elbow close to your body and squeezing your shoulder blades together.","Lower the kettlebell back down to the starting position and repeat with the other arm.","Continue alternating arms for the desired number of repetitions."]},{"id":"523","name":"kettlebell arnold press","body_part":"shoulders","target":"delts","secondary_muscles":["triceps","upper back"],"equipment":"kettlebell","difficulty":"intermediate","description":"The kettlebell Arnold press is a shoulder exercise that involves pressing kettlebells overhead while rotating the wrists, targeting the deltoids and engaging the triceps and upper back. It requires coordination and control due to the rotational movement and the instability of kettlebells.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0523.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, holding a kettlebell in each hand at shoulder height with your palms facing towards you.","Engage your core and press the kettlebells overhead, rotating your palms to face forward as you extend your arms.","Pause at the top of the movement, then slowly lower the kettlebells back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"524","name":"kettlebell bent press","body_part":"waist","target":"abs","secondary_muscles":["shoulders","triceps","obliques"],"equipment":"kettlebell","difficulty":"advanced","description":"The kettlebell bent press is a complex movement that targets the abs while also engaging the shoulders, triceps, and obliques. It requires strength, coordination, and mobility to perform safely and effectively.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0524.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, holding a kettlebell in your right hand.","Bend your knees slightly and press the kettlebell overhead with your right arm, keeping your elbow locked.","Rotate your torso to the left, shifting your weight onto your left foot.","Bend your left knee and lower your torso towards the ground, keeping your right arm extended overhead.","As you lower, keep your eyes on the kettlebell and your chest lifted.","Once your left hand touches the ground, push through your left foot and straighten your left leg, driving your hips forward.","As you drive your hips forward, use your core and right arm to press the kettlebell back up to the starting position.","Repeat for the desired number of repetitions, then switch sides."]},{"id":"525","name":"kettlebell bottoms up clean from the hang position","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms","shoulders"],"equipment":"kettlebell","difficulty":"advanced","description":"The kettlebell bottoms up clean from the hang position is a dynamic exercise that targets the biceps while also engaging the forearms and shoulders. It requires coordination, grip strength, and control to stabilize the kettlebell in the bottoms-up position.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0525.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, holding a kettlebell in one hand with an overhand grip.","Bend your knees slightly and hinge forward at the hips, keeping your back straight and chest up.","Allow the kettlebell to hang down between your legs, with your arm fully extended.","In one fluid motion, explosively extend your hips and knees while pulling the kettlebell up towards your shoulder.","As the kettlebell reaches shoulder height, rotate your wrist so that the bottom of the kettlebell is facing up.","Catch the kettlebell at shoulder height with your elbow bent and your palm facing up.","Lower the kettlebell back down to the starting position by reversing the movement.","Repeat for the desired number of repetitions, then switch sides."]},{"id":"526","name":"kettlebell double alternating hang clean","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms","shoulders"],"equipment":"kettlebell","difficulty":"intermediate","description":"The kettlebell double alternating hang clean is a dynamic exercise that targets the biceps while also engaging the forearms and shoulders. It involves explosive hip and knee extension to lift the kettlebells from a hanging position to shoulder height in an alternating fashion.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0526.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, holding a kettlebell in each hand with an overhand grip.","Bend your knees slightly and hinge forward at the hips, keeping your back straight and chest up.","Allow the kettlebells to hang straight down in front of your body.","In one fluid motion, explosively extend your hips and knees while shrugging your shoulders.","As the kettlebells rise, pull them up towards your shoulders, keeping your elbows high and out to the sides.","Catch the kettlebells at shoulder height, with your palms facing inward and your elbows pointing forward.","Lower the kettlebells back down to the starting position and repeat for the desired number of repetitions."]},{"id":"527","name":"kettlebell double jerk","body_part":"shoulders","target":"delts","secondary_muscles":["triceps","core"],"equipment":"kettlebell","difficulty":"advanced","description":"The kettlebell double jerk is a dynamic overhead pressing movement that involves using two kettlebells. It requires explosive power, coordination, and proper technique to safely drive the weights overhead using a combination of leg and upper body strength.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0527.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, holding a kettlebell in each hand at shoulder height.","Bend your knees slightly and engage your core.","Press the kettlebells overhead, fully extending your arms.","Bend your knees and quickly drop into a partial squat.","Explosively extend your hips and knees, driving the kettlebells overhead.","Lock out your arms and catch the kettlebells overhead with your knees slightly bent.","Stand up straight and return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"528","name":"kettlebell double push press","body_part":"shoulders","target":"delts","secondary_muscles":["triceps","core"],"equipment":"kettlebell","difficulty":"intermediate","description":"The kettlebell double push press is a compound movement that targets the shoulders (delts) and involves explosive power from the lower body to drive two kettlebells overhead. It requires coordination, strength, and proper technique to perform safely.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0528.gif","youtube_id":null,"instructions":["Start by standing with your feet shoulder-width apart, holding a kettlebell in each hand at shoulder height.","Bend your knees slightly and engage your core.","Initiate the movement by explosively extending your hips, knees, and ankles, driving the kettlebells overhead.","As the kettlebells reach the top, press them fully overhead, locking out your arms.","Lower the kettlebells back to the starting position by bending your elbows and bringing them back down to shoulder height.","Repeat for the desired number of repetitions."]},{"id":"529","name":"kettlebell double snatch","body_part":"shoulders","target":"delts","secondary_muscles":["trapezius","forearms","core"],"equipment":"kettlebell","difficulty":"advanced","description":"The kettlebell double snatch is a dynamic, full-body movement that targets the shoulders (delts) and also engages the trapezius, forearms, and core. It requires explosive power, coordination, and proper technique to perform safely and effectively.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0529.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, holding a kettlebell in each hand at arm's length in front of your thighs.","Bend your knees slightly and hinge forward at the hips, keeping your back flat and chest up.","In one explosive motion, extend your hips, knees, and ankles, and simultaneously pull the kettlebells up towards your shoulders.","As the kettlebells reach shoulder level, rotate your wrists and punch the kettlebells overhead, fully extending your arms.","Lower the kettlebells back down to the starting position and repeat for the desired number of repetitions."]},{"id":"53","name":"barbell jump squat","body_part":"upper legs","target":"glutes","secondary_muscles":["quadriceps","hamstrings","calves"],"equipment":"barbell","difficulty":"advanced","description":"The barbell jump squat is a dynamic lower body exercise that combines the traditional squat with an explosive jump, performed while holding a barbell across the upper back. This exercise targets the glutes and also works the quadriceps, hamstrings, and calves. It is a plyometric movement that develops power, strength, and explosiveness in the legs.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0053.gif","youtube_id":null,"instructions":["Start by standing with your feet shoulder-width apart, holding a barbell across your upper back.","Lower your body into a squat position by bending your knees and pushing your hips back.","Once you reach the bottom of the squat, explode upwards by jumping off the ground.","As you jump, extend your hips, knees, and ankles, pushing through your toes.","Land softly back into the squat position and immediately repeat the movement for the desired number of repetitions."]},{"id":"530","name":"kettlebell double windmill","body_part":"waist","target":"abs","secondary_muscles":["shoulders","hamstrings"],"equipment":"kettlebell","difficulty":"advanced","description":"The kettlebell double windmill is a dynamic exercise that targets the abs while also engaging the shoulders and hamstrings. It requires holding a kettlebell overhead and bending at the waist, demanding core strength, shoulder stability, and hamstring flexibility.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0530.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, holding a kettlebell in your right hand.","Extend your right arm overhead, keeping your eyes on the kettlebell.","Rotate your left foot 45 degrees to the left and your right foot 90 degrees to the right.","Bend at the waist to the left, keeping your right arm extended overhead.","Lower the kettlebell towards the ground, reaching towards your left foot.","Pause for a moment, then engage your core and push through your right foot to return to the starting position.","Repeat for the desired number of repetitions, then switch sides."]},{"id":"531","name":"kettlebell extended range one arm press on floor","body_part":"chest","target":"pectorals","secondary_muscles":["triceps","shoulders"],"equipment":"kettlebell","difficulty":"intermediate","description":"The kettlebell extended range one arm press on floor is a unilateral chest exercise performed on the floor, emphasizing the pectorals while also engaging the triceps and shoulders. It requires stability, control, and strength to press the kettlebell through an extended range of motion.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0531.gif","youtube_id":null,"instructions":["Start by lying on your back on the floor with your knees bent and feet flat on the ground.","Hold a kettlebell in one hand, with your palm facing towards your feet.","Extend your arm straight up towards the ceiling, keeping your elbow locked and your wrist straight.","Slowly lower the kettlebell back down to the starting position, maintaining control throughout the movement.","Repeat for the desired number of repetitions, then switch to the other arm."]},{"id":"532","name":"kettlebell figure 8","body_part":"waist","target":"abs","secondary_muscles":["shoulders","forearms"],"equipment":"kettlebell","difficulty":"intermediate","description":"The kettlebell figure 8 is a dynamic core exercise that involves passing a kettlebell between your legs in a figure 8 pattern, engaging the abs, shoulders, and forearms while also challenging coordination and stability.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0532.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, holding a kettlebell in one hand.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Pass the kettlebell between your legs, switching hands as it reaches the back of your legs.","As the kettlebell comes forward, pass it to the other hand between your legs.","Continue passing the kettlebell between your legs in a figure 8 motion.","Maintain a steady pace and engage your core throughout the exercise.","Repeat for the desired number of repetitions."]},{"id":"533","name":"kettlebell front squat","body_part":"upper legs","target":"glutes","secondary_muscles":["quadriceps","hamstrings","calves"],"equipment":"kettlebell","difficulty":"intermediate","description":"The kettlebell front squat is a lower body exercise that targets the glutes and also works the quadriceps, hamstrings, and calves. It involves holding a kettlebell at chest height and performing a squat, emphasizing core engagement and proper squat mechanics.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0533.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, toes slightly turned out.","Hold the kettlebell with both hands in front of your chest, close to your body.","Engage your core and keep your chest up as you lower your hips down and back, as if sitting into a chair.","Lower until your thighs are parallel to the ground, or as low as you can comfortably go.","Drive through your heels to stand back up, squeezing your glutes at the top.","Repeat for the desired number of repetitions."]},{"id":"534","name":"kettlebell goblet squat","body_part":"upper legs","target":"glutes","secondary_muscles":["quadriceps","hamstrings","calves"],"equipment":"kettlebell","difficulty":"beginner","description":"The kettlebell goblet squat is a lower body exercise that targets the glutes while also engaging the quadriceps, hamstrings, and calves. It involves holding a kettlebell close to the chest and performing a squat, making it a great movement for building strength and improving squat technique.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0534.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, holding a kettlebell close to your chest with both hands.","Keeping your chest up and core engaged, lower your body down into a squat position by bending at the knees and hips.","Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"535","name":"kettlebell hang clean","body_part":"upper legs","target":"hamstrings","secondary_muscles":["glutes","quadriceps","calves"],"equipment":"kettlebell","difficulty":"intermediate","description":"The kettlebell hang clean is a dynamic exercise that targets the hamstrings and also works the glutes, quadriceps, and calves. It involves swinging a kettlebell from between the legs up to the rack position at the shoulder, requiring explosive hip extension, coordination, and proper technique to perform safely.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0535.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, holding a kettlebell in front of your thighs.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Lower the kettlebell towards the ground, allowing it to swing between your legs.","Quickly extend your hips and knees, using the momentum to swing the kettlebell up to shoulder height.","As the kettlebell reaches shoulder height, rotate your wrists and catch the kettlebell in the rack position, with your elbow tucked in and the kettlebell resting on your forearm.","Lower the kettlebell back down to the starting position between your legs, and repeat for the desired number of repetitions."]},{"id":"536","name":"kettlebell lunge pass through","body_part":"upper legs","target":"glutes","secondary_muscles":["quadriceps","hamstrings","calves"],"equipment":"kettlebell","difficulty":"intermediate","description":"The kettlebell lunge pass through is a dynamic lower body exercise that combines a traditional lunge with a kettlebell hand-off beneath the front thigh, challenging balance, coordination, and strength.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0536.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, holding a kettlebell in front of your chest with both hands.","Take a step forward with your right foot, lowering your body into a lunge position.","As you lunge forward, pass the kettlebell under your right thigh and transfer it to your left hand.","Push off with your right foot to return to the starting position, while simultaneously passing the kettlebell back to your right hand.","Repeat the lunge on the opposite side, passing the kettlebell under your left thigh.","Continue alternating lunges and passing the kettlebell between hands for the desired number of repetitions."]},{"id":"537","name":"kettlebell one arm clean and jerk","body_part":"shoulders","target":"delts","secondary_muscles":["triceps","core"],"equipment":"kettlebell","difficulty":"advanced","description":"The kettlebell one arm clean and jerk is a dynamic, compound exercise that targets the deltoids while also engaging the triceps and core. It requires coordination, explosive power, and proper technique to perform safely and effectively.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0537.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, holding a kettlebell in one hand with an overhand grip.","Bend your knees slightly and hinge at the hips, lowering the kettlebell between your legs.","Explosively extend your hips, knees, and ankles, using the momentum to swing the kettlebell up to shoulder height.","As the kettlebell reaches shoulder height, rotate your wrist and punch your hand straight up, locking out your arm overhead.","Lower the kettlebell back down to the starting position and repeat for the desired number of repetitions."]},{"id":"538","name":"kettlebell one arm jerk","body_part":"shoulders","target":"delts","secondary_muscles":["triceps","core"],"equipment":"kettlebell","difficulty":"intermediate","description":"The kettlebell one arm jerk is a dynamic overhead pressing movement that involves using the legs and hips to help drive a kettlebell overhead with one arm. It requires coordination, timing, and strength, especially in the shoulders, triceps, and core.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0538.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, holding a kettlebell in one hand at shoulder height.","Bend your knees slightly and engage your core.","Press the kettlebell overhead in a straight line, fully extending your arm.","As you press the kettlebell overhead, simultaneously dip your knees and quickly straighten them to generate momentum.","As the kettlebell reaches its highest point, quickly drop underneath it by bending your knees and hips.","Catch the kettlebell with a slight bend in your knees and hips, and your arm fully extended overhead.","Stand up straight, fully extending your knees and hips, and stabilize the kettlebell overhead.","Lower the kettlebell back to the starting position by bending your knees and hips, and repeat for the desired number of repetitions."]},{"id":"539","name":"kettlebell one arm military press to the side","body_part":"shoulders","target":"delts","secondary_muscles":["triceps","core"],"equipment":"kettlebell","difficulty":"intermediate","description":"The kettlebell one arm military press to the side is a unilateral overhead pressing movement that targets the deltoids, with secondary emphasis on the triceps and core for stabilization. It requires balance, coordination, and shoulder strength.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0539.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, holding a kettlebell in one hand at shoulder height.","Engage your core and keep your back straight.","Press the kettlebell overhead, extending your arm fully.","Pause for a moment at the top, then slowly lower the kettlebell back to the starting position.","Repeat for the desired number of repetitions, then switch sides."]},{"id":"54","name":"barbell lunge","body_part":"upper legs","target":"glutes","secondary_muscles":["quadriceps","hamstrings","calves"],"equipment":"barbell","difficulty":"intermediate","description":"The barbell lunge is a compound lower body exercise that targets the glutes, quadriceps, hamstrings, and calves. It involves stepping forward with a barbell on your upper back and lowering your body into a lunge position before returning to standing.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0054.gif","youtube_id":null,"instructions":["Start by standing with your feet shoulder-width apart and a barbell resting on your upper back.","Take a step forward with your right foot, keeping your torso upright.","Lower your body by bending your right knee until your thigh is parallel to the ground.","Push through your right heel to return to the starting position.","Repeat with your left leg, alternating legs for the desired number of repetitions."]},{"id":"540","name":"kettlebell one arm push press","body_part":"shoulders","target":"delts","secondary_muscles":["triceps","core"],"equipment":"kettlebell","difficulty":"intermediate","description":"The kettlebell one arm push press is a compound exercise that targets the deltoids while also engaging the triceps and core. It involves pressing a kettlebell overhead with one arm, using a slight leg drive to assist the movement.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0540.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, holding a kettlebell in one hand at shoulder level.","Bend your knees slightly and engage your core.","Press the kettlebell overhead by extending your arm and fully extending your legs.","Lower the kettlebell back to the starting position by bending your knees and bringing the kettlebell back to your shoulder.","Repeat for the desired number of repetitions, then switch sides."]},{"id":"541","name":"kettlebell one arm row","body_part":"back","target":"upper back","secondary_muscles":["biceps","forearms"],"equipment":"kettlebell","difficulty":"intermediate","description":"The kettlebell one arm row is a unilateral pulling exercise that targets the upper back, with secondary emphasis on the biceps and forearms. It requires maintaining a stable hip hinge position while rowing the kettlebell with one arm, promoting strength and muscle development in the upper back and improving core stability.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0541.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, holding a kettlebell in one hand with an overhand grip.","Bend your knees slightly and hinge forward at the hips, keeping your back straight and your core engaged.","Pull the kettlebell up towards your chest, keeping your elbow close to your body and squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the kettlebell back down to the starting position.","Repeat for the desired number of repetitions, then switch sides and repeat with the other arm."]},{"id":"542","name":"kettlebell one arm snatch","body_part":"shoulders","target":"delts","secondary_muscles":["trapezius","forearms","core"],"equipment":"kettlebell","difficulty":"advanced","description":"The kettlebell one arm snatch is a dynamic, full-body exercise that targets the shoulders (delts) and also engages the trapezius, forearms, and core. It requires explosive power, coordination, and proper technique to perform safely and effectively.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0542.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, holding a kettlebell in one hand between your legs.","Bend your knees slightly and hinge at the hips, lowering the kettlebell towards the ground.","Explosively extend your hips and knees, using the momentum to swing the kettlebell up towards your shoulder.","As the kettlebell reaches shoulder height, rotate your hand and punch it straight up overhead, fully extending your arm.","Lower the kettlebell back down between your legs and repeat for the desired number of repetitions."]},{"id":"543","name":"kettlebell pirate supper legs","body_part":"shoulders","target":"delts","secondary_muscles":["triceps","forearms"],"equipment":"kettlebell","difficulty":"intermediate","description":"The kettlebell pirate supper legs exercise targets the deltoids and involves lifting a kettlebell from shoulder height to overhead, requiring strength and stability.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0543.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, holding a kettlebell in one hand.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Raise the kettlebell up to shoulder height, keeping your elbow close to your body.","Extend your arm fully overhead, straightening your elbow.","Lower the kettlebell back down to shoulder height, then return to the starting position.","Repeat for the desired number of repetitions, then switch sides."]},{"id":"544","name":"kettlebell pistol squat","body_part":"upper legs","target":"glutes","secondary_muscles":["quadriceps","hamstrings","calves"],"equipment":"kettlebell","difficulty":"advanced","description":"The kettlebell pistol squat is a challenging single-leg squat variation that targets the glutes, quadriceps, hamstrings, and calves. It requires significant strength, balance, and mobility, as well as experience with both pistol squats and kettlebell handling.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0544.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, holding a kettlebell in front of your chest with both hands.","Lift your left foot off the ground and extend it forward, keeping it parallel to the ground.","Slowly lower your body down into a squat position, keeping your right foot flat on the ground and your left leg extended.","Pause for a moment at the bottom of the squat, then push through your right heel to return to the starting position.","Repeat for the desired number of repetitions, then switch legs."]},{"id":"545","name":"kettlebell plyo push-up","body_part":"chest","target":"pectorals","secondary_muscles":["triceps","shoulders","core"],"equipment":"kettlebell","difficulty":"advanced","description":"The kettlebell plyo push-up is an explosive push-up variation performed with hands on kettlebells, targeting the chest, triceps, shoulders, and core. It requires significant upper body strength, stability, and coordination, as well as explosive power to lift the hands off the kettlebells and land safely.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0545.gif","youtube_id":null,"instructions":["Start in a high plank position with your hands on the kettlebells, shoulder-width apart.","Lower your chest towards the ground, keeping your elbows close to your body.","Push through your hands explosively, lifting your hands off the kettlebells and extending your arms fully.","Land softly back on the kettlebells and immediately lower your chest back down for the next repetition.","Repeat for the desired number of repetitions."]},{"id":"546","name":"kettlebell seated press","body_part":"shoulders","target":"delts","secondary_muscles":["triceps","core"],"equipment":"kettlebell","difficulty":"intermediate","description":"The kettlebell seated press is a shoulder exercise performed while seated, pressing kettlebells overhead to target the deltoids, with secondary emphasis on the triceps and core.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0546.gif","youtube_id":null,"instructions":["Sit on a bench with your back straight and feet flat on the ground.","Hold a kettlebell in each hand at shoulder height, palms facing forward.","Press the kettlebells overhead, fully extending your arms.","Lower the kettlebells back to shoulder height.","Repeat for the desired number of repetitions."]},{"id":"547","name":"kettlebell seesaw press","body_part":"shoulders","target":"delts","secondary_muscles":["triceps","core"],"equipment":"kettlebell","difficulty":"intermediate","description":"The kettlebell seesaw press is a shoulder exercise that involves pressing kettlebells overhead in an alternating fashion, challenging both strength and coordination.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0547.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, holding a kettlebell in each hand at shoulder height.","Press one kettlebell overhead while keeping the other kettlebell at shoulder height.","Lower the pressed kettlebell back to shoulder height while simultaneously pressing the other kettlebell overhead.","Continue alternating the pressing motion, creating a seesaw-like movement.","Repeat for the desired number of repetitions."]},{"id":"548","name":"kettlebell sumo high pull","body_part":"back","target":"traps","secondary_muscles":["shoulders","glutes","hamstrings"],"equipment":"kettlebell","difficulty":"intermediate","description":"The kettlebell sumo high pull is a compound exercise that targets the traps and also works the shoulders, glutes, and hamstrings. It involves a wide-stance squat combined with an explosive pull of the kettlebell to chin height.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0548.gif","youtube_id":null,"instructions":["Stand with your feet wider than shoulder-width apart, toes pointing outwards.","Hold a kettlebell with both hands in front of your body, arms extended downwards.","Bend your knees and lower your hips into a squat position, keeping your back straight.","Drive through your heels and explosively extend your hips and knees, pulling the kettlebell up towards your chin.","As you pull the kettlebell up, keep your elbows high and wide, and squeeze your shoulder blades together.","Lower the kettlebell back down to the starting position and repeat for the desired number of repetitions."]},{"id":"549","name":"kettlebell swing","body_part":"upper legs","target":"glutes","secondary_muscles":["hamstrings","core"],"equipment":"kettlebell","difficulty":"intermediate","description":"The kettlebell swing is a dynamic exercise that targets the glutes and also engages the hamstrings and core. It involves swinging a kettlebell between the legs and up to shoulder height using hip drive and momentum.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0549.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, toes pointed slightly outward.","Hold the kettlebell with both hands in front of your body, arms extended.","Bend your knees slightly and hinge at the hips, pushing your butt back.","Swing the kettlebell back between your legs, keeping your arms straight and maintaining a flat back.","Drive your hips forward and swing the kettlebell up to shoulder height, using the momentum generated by your hips.","Allow the kettlebell to swing back down between your legs and repeat the movement for the desired number of repetitions."]},{"id":"55","name":"barbell lying close-grip press","body_part":"upper arms","target":"triceps","secondary_muscles":["chest","shoulders"],"equipment":"barbell","difficulty":"intermediate","description":"The barbell lying close-grip press is a compound upper body exercise that primarily targets the triceps, with secondary emphasis on the chest and shoulders. It is performed lying on a bench, using a close grip on the barbell to increase triceps activation.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0055.gif","youtube_id":null,"instructions":["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Grasp the barbell with a close grip, hands shoulder-width apart, palms facing towards your feet.","Lift the barbell off the rack and hold it directly above your chest with your arms fully extended.","Slowly lower the barbell towards your chest, keeping your elbows close to your body.","Pause for a moment when the barbell touches your chest, then push it back up to the starting position.","Repeat for the desired number of repetitions."]},{"id":"550","name":"kettlebell thruster","body_part":"shoulders","target":"delts","secondary_muscles":["quadriceps","glutes","core"],"equipment":"kettlebell","difficulty":"intermediate","description":"The kettlebell thruster is a compound exercise that combines a squat with an overhead press, targeting the shoulders while also engaging the quadriceps, glutes, and core. It requires coordination, strength, and some experience with kettlebell handling.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0550.gif","youtube_id":null,"instructions":["Start by standing with your feet shoulder-width apart, holding a kettlebell in front of your chest with both hands, palms facing each other.","Lower into a squat position by bending your knees and pushing your hips back, keeping your chest up and your back straight.","As you reach the bottom of the squat, explosively drive through your heels to stand up, simultaneously pressing the kettlebell overhead.","Lock out your arms at the top of the movement, fully extending your elbows.","Lower the kettlebell back to the starting position by reversing the movement, bending your elbows and lowering the weight back to your chest.","Repeat for the desired number of repetitions."]},{"id":"551","name":"kettlebell turkish get up (squat style)","body_part":"upper legs","target":"glutes","secondary_muscles":["quadriceps","hamstrings","core"],"equipment":"kettlebell","difficulty":"advanced","description":"The kettlebell Turkish get up (squat style) is a complex, full-body movement that targets the glutes and also works the quadriceps, hamstrings, and core. It requires strength, coordination, balance, and mobility, making it a challenging exercise.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0551.gif","youtube_id":null,"instructions":["Start by lying on your back with your legs extended and the kettlebell held in your right hand, arm fully extended above your shoulder.","Bend your right knee and place your right foot flat on the ground, keeping your left leg extended.","Pressing through your right foot, lift your hips off the ground, coming into a bridge position.","Slide your left leg underneath your body, bending your left knee and placing your left foot flat on the ground.","Rotate your torso to the left, bringing your left hand to the ground for support.","Pressing through your right foot and left hand, lift your torso off the ground, coming into a kneeling position.","From the kneeling position, stand up, keeping the kettlebell extended overhead.","Reverse the movement to return to the starting position.","Repeat the exercise on the other side, starting with the kettlebell in your left hand."]},{"id":"552","name":"kettlebell two arm clean","body_part":"shoulders","target":"delts","secondary_muscles":["traps","forearms"],"equipment":"kettlebell","difficulty":"intermediate","description":"The kettlebell two arm clean is a dynamic movement that targets the deltoids while also engaging the traps and forearms. It requires coordination, explosive power, and proper technique to safely transition the kettlebell from the ground to the rack position.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0552.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, holding a kettlebell in front of your thighs with both hands, palms facing towards you.","Bend your knees slightly and hinge at the hips, lowering the kettlebell towards the ground.","Explosively extend your hips and knees, using the momentum to pull the kettlebell up towards your shoulders.","As the kettlebell reaches shoulder height, rotate your wrists and catch the kettlebell in the rack position, with your elbows tucked in and the kettlebell resting on the back of your forearm.","Lower the kettlebell back down to the starting position and repeat for the desired number of repetitions."]},{"id":"553","name":"kettlebell two arm military press","body_part":"shoulders","target":"delts","secondary_muscles":["triceps","upper back"],"equipment":"kettlebell","difficulty":"intermediate","description":"The kettlebell two arm military press is a shoulder exercise that involves pressing two kettlebells overhead from shoulder level, targeting the deltoids and engaging the triceps and upper back.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0553.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, holding a kettlebell in each hand at shoulder level with your palms facing forward.","Engage your core and press the kettlebells overhead, fully extending your arms.","Pause for a moment at the top, then slowly lower the kettlebells back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"554","name":"kettlebell windmill","body_part":"waist","target":"abs","secondary_muscles":["obliques","shoulders"],"equipment":"kettlebell","difficulty":"advanced","description":"The kettlebell windmill is a compound exercise that targets the abs and obliques while also engaging the shoulders and improving overall core stability and mobility. It requires holding a kettlebell overhead and bending at the waist, demanding strength, balance, and coordination.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0554.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, holding a kettlebell in your right hand overhead.","Rotate your left foot outwards about 45 degrees and keep your right foot pointing forward.","Bend your torso to the left side, keeping your right arm extended overhead and your eyes on the kettlebell.","Lower your torso as far as you can while keeping your right arm straight and your left arm extended to the side.","Pause for a moment, then return to the starting position by pushing through your right foot and engaging your obliques.","Repeat for the desired number of repetitions, then switch sides."]},{"id":"555","name":"kick out sit","body_part":"upper legs","target":"hamstrings","secondary_muscles":["quadriceps","glutes"],"equipment":"body weight","difficulty":"beginner","description":"The kick out sit is a bodyweight exercise that targets the hamstrings while also engaging the quadriceps and glutes. It involves sitting on the edge of a bench or chair, extending the legs out, and then returning to the starting position.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0555.gif","youtube_id":null,"instructions":["Sit on the edge of a bench or chair with your feet flat on the ground and your knees bent at a 90-degree angle.","Lean back slightly and place your hands on the edge of the bench or chair for support.","Engaging your hamstrings, lift your feet off the ground and extend your legs straight out in front of you.","Pause for a moment at the top, then slowly bend your knees and bring your feet back towards your body.","Repeat for the desired number of repetitions."]},{"id":"558","name":"kipping muscle up","body_part":"back","target":"lats","secondary_muscles":["biceps","triceps","shoulders","core"],"equipment":"body weight","difficulty":"advanced","description":"The kipping muscle up is a dynamic bodyweight exercise that combines a pull-up with a dip, using momentum to transition from below to above the bar. It primarily targets the lats and requires significant upper body strength, coordination, and explosive power.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0558.gif","youtube_id":null,"instructions":["Start by hanging from a pull-up bar with an overhand grip, hands slightly wider than shoulder-width apart.","Engage your core and use a swinging motion to generate momentum.","As you swing forward, pull your chest towards the bar, using your lats and biceps to initiate the movement.","Continue the upward motion until your chest reaches the bar, then transition into a dip position by pushing down on the bar and extending your arms.","Lower yourself back down to the starting position by bending your arms and controlling the descent.","Repeat for the desired number of repetitions."]},{"id":"56","name":"barbell lying close-grip triceps extension","body_part":"upper arms","target":"triceps","secondary_muscles":["shoulders"],"equipment":"barbell","difficulty":"intermediate","description":"The barbell lying close-grip triceps extension is a strength exercise targeting the triceps, performed lying on a bench with a barbell using a close grip. It emphasizes triceps development and also engages the shoulders as secondary muscles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0056.gif","youtube_id":null,"instructions":["Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.","Grasp the barbell with a close grip, hands shoulder-width apart, palms facing up.","Extend your arms fully, lifting the barbell above your chest.","Keeping your upper arms stationary, slowly lower the barbell towards your forehead by bending your elbows.","Pause for a moment at the bottom, then extend your arms back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"562","name":"landmine 180","body_part":"waist","target":"abs","secondary_muscles":["obliques","quadriceps"],"equipment":"barbell","difficulty":"intermediate","description":"The landmine 180 is a rotational core exercise performed with a barbell anchored at one end. It targets the abs and obliques, requiring the lifter to swing the barbell in an arc from side to side, engaging the core, hips, and legs for stability and power.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0562.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and hold the barbell with both hands in front of your chest.","Bend your knees slightly and rotate your torso to the right, swinging the barbell down towards your right hip.","As you reach the bottom of the movement, quickly reverse the motion and rotate your torso to the left, swinging the barbell up and across your body towards your left shoulder.","Continue this twisting motion, alternating sides, for the desired number of repetitions."]},{"id":"57","name":"barbell lying extension","body_part":"upper arms","target":"triceps","secondary_muscles":["shoulders"],"equipment":"barbell","difficulty":"intermediate","description":"The barbell lying extension, also known as a skullcrusher, is a strength exercise targeting the triceps. It involves lying on a bench and lowering a barbell towards the forehead by bending the elbows, then extending the arms back up.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0057.gif","youtube_id":null,"instructions":["Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.","Hold the barbell with an overhand grip, hands shoulder-width apart, and extend your arms straight up over your chest.","Keeping your upper arms stationary, slowly lower the barbell towards your forehead by bending your elbows.","Pause for a moment, then extend your arms back up to the starting position.","Repeat for the desired number of repetitions."]},{"id":"570","name":"leg pull in flat bench","body_part":"waist","target":"abs","secondary_muscles":["hip flexors","lower back"],"equipment":"body weight","difficulty":"beginner","description":"The leg pull in flat bench is an abdominal exercise performed on a flat bench using only body weight. It targets the abs and also works the hip flexors and lower back. The movement involves pulling the knees toward the chest while sitting on a bench, requiring core strength and stability.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0570.gif","youtube_id":null,"instructions":["Sit on a flat bench with your legs extended straight out in front of you.","Place your hands on the bench beside your hips for support.","Engage your abs and lift your legs off the ground, bringing your knees towards your chest.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"571","name":"lever alternating narrow grip seated row","body_part":"back","target":"upper back","secondary_muscles":["biceps","forearms"],"equipment":"leverage machine","difficulty":"intermediate","description":"The lever alternating narrow grip seated row is a machine-based exercise targeting the upper back, performed by alternately pulling each handle towards the torso while maintaining proper posture.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0571.gif","youtube_id":null,"instructions":["Adjust the seat height and footplate position to ensure proper alignment.","Sit on the machine with your back straight and feet flat on the footplate.","Grasp the handles with a narrow grip, palms facing each other.","Keep your chest up and shoulders back throughout the exercise.","Pull one handle towards your torso while keeping the other handle stationary.","Squeeze your shoulder blades together at the end of the movement.","Slowly return the handle to the starting position and repeat with the other side.","Continue alternating sides for the desired number of repetitions."]},{"id":"572","name":"lever assisted chin-up","body_part":"back","target":"lats","secondary_muscles":["biceps","forearms"],"equipment":"leverage machine","difficulty":"beginner","description":"The lever assisted chin-up is a machine-based exercise that helps users perform chin-ups with assistance, making it easier to build strength in the lats, biceps, and forearms. It is ideal for those who are not yet able to perform unassisted chin-ups.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0572.gif","youtube_id":null,"instructions":["Adjust the leverage machine to your desired resistance level.","Stand on the foot platform and grip the handles with an overhand grip, slightly wider than shoulder-width apart.","Hang with your arms fully extended, keeping your body straight.","Engage your back muscles and pull your body up towards the handles, leading with your chest.","Continue pulling until your chin is above the handles.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"573","name":"lever back extension","body_part":"back","target":"spine","secondary_muscles":["glutes","hamstrings"],"equipment":"leverage machine","difficulty":"beginner","description":"The lever back extension is a machine-based exercise targeting the muscles of the lower back (spine extensors), with secondary emphasis on the glutes and hamstrings. It is performed by sitting on a leverage machine, securing the feet, and extending the back against resistance.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0573.gif","youtube_id":null,"instructions":["Adjust the machine to fit your body size and range of motion.","Sit on the machine with your back against the pad and your feet secured.","Place your hands on the handles or grip bars.","Engage your core and slowly lean forward, allowing your back to round slightly.","Pause for a moment at the bottom position, feeling a stretch in your lower back.","Using your back muscles, slowly raise your torso back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"574","name":"lever bent over row","body_part":"back","target":"upper back","secondary_muscles":["biceps","forearms"],"equipment":"barbell","difficulty":"intermediate","description":"The lever bent over row is a compound strength exercise targeting the upper back, performed with a barbell. It requires good posture, core stability, and proper technique to avoid injury.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0574.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and knees slightly bent.","Hold the barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Bend forward at the hips, keeping your back straight and chest up.","Pull the barbell towards your lower chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"575","name":"lever bicep curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"leverage machine","difficulty":"beginner","description":"The lever bicep curl is a machine-based exercise targeting the biceps, with secondary emphasis on the forearms. It is performed using a leverage machine, which provides guided resistance and stability, making it accessible for most users.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0575.gif","youtube_id":null,"instructions":["Adjust the seat height and position yourself on the machine with your back against the pad.","Grasp the handles with an underhand grip, palms facing up, and keep your elbows close to your sides.","Exhale and curl the handles upward, contracting your biceps.","Pause for a moment at the top of the movement, squeezing your biceps.","Inhale and slowly lower the handles back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]},{"id":"576","name":"lever chest press","body_part":"chest","target":"pectorals","secondary_muscles":["triceps","shoulders"],"equipment":"leverage machine","difficulty":"beginner","description":"The lever chest press is a machine-based exercise that targets the pectoral muscles, with secondary emphasis on the triceps and shoulders. It is performed on a leverage machine, providing guided movement for safety and stability.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0576.gif","youtube_id":null,"instructions":["Adjust the seat height and position yourself on the machine with your back flat against the pad.","Grasp the handles with an overhand grip and position your elbows at a 90-degree angle.","Push the handles forward until your arms are fully extended, exhaling during the movement.","Pause briefly at the end of the movement, then slowly return to the starting position, inhaling as you do so.","Repeat for the desired number of repetitions."]},{"id":"577","name":"lever chest press","body_part":"chest","target":"pectorals","secondary_muscles":["triceps","shoulders"],"equipment":"leverage machine","difficulty":"beginner","description":"The lever chest press is a machine-based exercise targeting the pectoral muscles. It provides a controlled pressing movement, making it suitable for building chest strength with added support and stability from the machine.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0577.gif","youtube_id":null,"instructions":["Adjust the seat height and position yourself on the machine with your back flat against the pad.","Grasp the handles with an overhand grip and position your elbows at a 90-degree angle.","Push the handles forward until your arms are fully extended, exhaling during the movement.","Pause briefly at the end of the movement, then slowly return to the starting position, inhaling as you do so.","Repeat for the desired number of repetitions."]},{"id":"578","name":"lever deadlift","body_part":"upper legs","target":"glutes","secondary_muscles":["hamstrings","quadriceps"],"equipment":"leverage machine","difficulty":"beginner","description":"The lever deadlift is a machine-based exercise targeting the glutes, with secondary emphasis on the hamstrings and quadriceps. It is performed on a leverage machine, providing guided movement and stability, making it accessible to a wide range of users.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0578.gif","youtube_id":null,"instructions":["Adjust the seat height and foot platform to your desired position.","Sit on the machine with your back against the pad and your feet flat on the foot platform.","Grasp the handles or the sides of the seat for stability.","Engage your glutes and hamstrings, and push through your heels to lift the weight up.","Keep your back straight and avoid rounding your shoulders.","Extend your hips fully at the top of the movement, squeezing your glutes.","Lower the weight back down in a controlled manner, keeping tension on your glutes and hamstrings.","Repeat for the desired number of repetitions."]},{"id":"579","name":"lever front pulldown","body_part":"back","target":"lats","secondary_muscles":["biceps","rhomboids","rear deltoids"],"equipment":"leverage machine","difficulty":"beginner","description":"The lever front pulldown is a machine-based exercise targeting the latissimus dorsi (lats) and is commonly used to build back strength and muscle mass. It involves pulling handles down towards the chest while seated, using a leverage machine.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0579.gif","youtube_id":null,"instructions":["Adjust the seat height and position yourself on the machine with your knees under the pads and your feet flat on the ground.","Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.","Sit upright with your chest lifted and your shoulders back, maintaining a slight arch in your lower back.","Engage your lats and pull the handles down towards your chest, squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, then slowly release the handles back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"58","name":"barbell lying lifting (on hip)","body_part":"upper legs","target":"glutes","secondary_muscles":["hamstrings","quadriceps"],"equipment":"barbell","difficulty":"beginner","description":"The barbell lying lifting (on hip) exercise primarily targets the glutes and also works the hamstrings and quadriceps. It involves lying on your back on a bench, placing a barbell across your hips, and lifting your hips upward by engaging your glutes.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0058.gif","youtube_id":null,"instructions":["Lie flat on your back on a bench with your feet flat on the ground and your knees bent.","Hold the barbell with an overhand grip and position it on your hips.","Engaging your glutes, lift your hips off the bench until your body forms a straight line from your knees to your shoulders.","Pause for a moment at the top, then slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"580","name":"lever gripless shrug","body_part":"back","target":"traps","secondary_muscles":["shoulders","forearms"],"equipment":"leverage machine","difficulty":"beginner","description":"The lever gripless shrug is performed on a leverage machine to target the trapezius muscles by elevating the shoulders without gripping the handles. This isolates the traps and minimizes forearm involvement.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0580.gif","youtube_id":null,"instructions":["Adjust the seat height and position yourself on the leverage machine.","Grasp the handles with your palms facing inwards and your arms fully extended.","Keeping your back straight, exhale and elevate your shoulders as high as possible.","Hold the contraction for a brief moment, then inhale and slowly lower your shoulders back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"581","name":"lever high row","body_part":"back","target":"upper back","secondary_muscles":["biceps","rear deltoids"],"equipment":"leverage machine","difficulty":"beginner","description":"The lever high row is a machine-based exercise targeting the upper back, with secondary emphasis on the biceps and rear deltoids. It is performed by sitting on a leverage machine, gripping the handles, and pulling them towards the body while keeping the chest against the pad.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0581.gif","youtube_id":null,"instructions":["Adjust the seat height and foot platform to a comfortable position.","Sit on the machine with your chest against the pad and your feet flat on the foot platform.","Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.","Keep your back straight and engage your core.","Pull the handles towards your body, squeezing your shoulder blades together.","Pause for a moment at the peak of the movement, then slowly release the handles back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"582","name":"lever kneeling leg curl","body_part":"upper legs","target":"hamstrings","secondary_muscles":["glutes"],"equipment":"leverage machine","difficulty":"intermediate","description":"The lever kneeling leg curl is an isolation exercise targeting the hamstrings, performed on a leverage machine while kneeling. It primarily works the hamstrings and also engages the glutes as secondary muscles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0582.gif","youtube_id":null,"instructions":["Adjust the machine to fit your body and select the desired weight.","Kneel on the machine facing downwards, with your knees resting on the pad and your feet secured under the footpads.","Grasp the handles or the sides of the machine for stability.","Keeping your upper body stationary, exhale and curl your legs up towards your glutes by flexing your knees.","Pause for a moment at the top of the movement, squeezing your hamstrings.","Inhale and slowly lower your legs back to the starting position, fully extending your knees.","Repeat for the desired number of repetitions."]},{"id":"583","name":"lever kneeling twist","body_part":"waist","target":"abs","secondary_muscles":["obliques","lower back"],"equipment":"leverage machine","difficulty":"intermediate","description":"The lever kneeling twist is an abdominal exercise performed on a leverage machine, targeting the abs with secondary emphasis on the obliques and lower back. The movement involves twisting the torso from side to side while kneeling, engaging the core muscles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0583.gif","youtube_id":null,"instructions":["Adjust the seat height and position yourself on the machine with your knees resting on the pads and your upper body facing forward.","Grasp the handles or the sides of the machine for stability.","Keeping your core engaged, twist your torso to one side as far as comfortably possible.","Pause for a moment, then slowly return to the starting position.","Repeat the twist to the opposite side.","Continue alternating sides for the desired number of repetitions."]},{"id":"584","name":"lever lateral raise","body_part":"shoulders","target":"delts","secondary_muscles":["traps","upper back"],"equipment":"leverage machine","difficulty":"beginner","description":"The lever lateral raise is a machine-based exercise targeting the deltoid muscles of the shoulders. It involves raising the arms out to the sides against resistance, primarily working the lateral deltoids, with secondary emphasis on the traps and upper back. The machine provides stability, making it accessible for those with less experience.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0584.gif","youtube_id":null,"instructions":["Adjust the seat height and position yourself on the machine with your back against the pad.","Grasp the handles with an overhand grip and keep your arms straight.","Exhale and raise your arms out to the sides until they are parallel to the floor.","Pause for a moment at the top, then inhale and slowly lower your arms back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"585","name":"lever leg extension","body_part":"upper legs","target":"quads","secondary_muscles":["hamstrings"],"equipment":"leverage machine","difficulty":"beginner","description":"The lever leg extension is an isolation exercise performed on a leverage machine to target the quadriceps. It involves extending the knees to lift a weight, primarily working the front of the thighs.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0585.gif","youtube_id":null,"instructions":["Adjust the seat height and backrest of the machine to fit your body.","Sit on the machine with your back against the backrest and your feet on the footpad.","Grasp the handles or sidebars for stability.","Extend your legs forward by straightening your knees, lifting the weight.","Pause for a moment at the top, then slowly lower the weight back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"586","name":"lever lying leg curl","body_part":"upper legs","target":"hamstrings","secondary_muscles":["calves"],"equipment":"leverage machine","difficulty":"beginner","description":"The lever lying leg curl is an isolation exercise targeting the hamstrings, performed on a leverage machine. It involves curling the legs upward against resistance while lying face down, emphasizing hamstring contraction and control.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0586.gif","youtube_id":null,"instructions":["Adjust the machine to fit your body and select the desired weight.","Lie face down on the machine with your legs straight and your heels against the padded lever.","Grasp the handles or the sides of the machine for stability.","Keeping your upper body stationary, exhale and curl your legs up as far as possible without lifting your hips off the pad.","Hold the contracted position for a brief pause as you squeeze your hamstrings.","Inhale and slowly lower the lever back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"587","name":"lever military press","body_part":"shoulders","target":"delts","secondary_muscles":["triceps","upper chest"],"equipment":"leverage machine","difficulty":"beginner","description":"The lever military press is a shoulder exercise performed on a leverage machine, primarily targeting the deltoid muscles. It also engages the triceps and upper chest as secondary muscles. The machine provides stability, making it suitable for those developing strength and technique.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0587.gif","youtube_id":null,"instructions":["Adjust the seat height and position yourself on the machine with your back against the backrest.","Grasp the handles with an overhand grip and position your hands slightly wider than shoulder-width apart.","Push the handles upward until your arms are fully extended, but do not lock your elbows.","Pause for a moment at the top, then slowly lower the handles back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"588","name":"lever narrow grip seated row","body_part":"back","target":"upper back","secondary_muscles":["biceps","forearms"],"equipment":"leverage machine","difficulty":"beginner","description":"The lever narrow grip seated row is a machine-based exercise targeting the upper back, with secondary emphasis on the biceps and forearms. It involves pulling handles towards the torso while seated, focusing on squeezing the shoulder blades together.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0588.gif","youtube_id":null,"instructions":["Adjust the seat height and footrests to ensure proper form.","Sit on the machine with your feet flat on the footrests and your knees slightly bent.","Grasp the handles with a narrow grip, palms facing each other.","Keep your back straight and lean slightly forward.","Pull the handles towards your torso, squeezing your shoulder blades together.","Pause for a moment at the peak of the movement.","Slowly release the handles and return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"589","name":"lever one arm bent over row","body_part":"back","target":"upper back","secondary_muscles":["biceps","forearms"],"equipment":"barbell","difficulty":"intermediate","description":"The lever one arm bent over row is a unilateral back exercise performed with a barbell. It targets the upper back and also works the biceps and forearms. The movement requires maintaining a stable bent-over position while rowing the weight with one arm, demanding core stability and coordination.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0589.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, knees slightly bent, and hold a barbell with an overhand grip.","Bend forward at the hips, keeping your back straight and your head up.","Let the barbell hang in front of you with your arms fully extended.","Pull the barbell up towards your chest, keeping your elbows close to your body.","Squeeze your shoulder blades together at the top of the movement.","Lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"59","name":"barbell lying preacher curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"barbell","difficulty":"intermediate","description":"The barbell lying preacher curl is an isolation exercise targeting the biceps, performed on a preacher bench to minimize shoulder involvement and maximize biceps engagement.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0059.gif","youtube_id":null,"instructions":["Sit on a preacher bench with your chest against the pad and your arms extended over the edge, holding a barbell with an underhand grip.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the bar until your biceps are fully contracted and the bar is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the barbell back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"590","name":"lever one arm shoulder press","body_part":"shoulders","target":"delts","secondary_muscles":["triceps","upper back"],"equipment":"leverage machine","difficulty":"beginner","description":"The lever one arm shoulder press is a machine-based exercise targeting the deltoid muscles of the shoulder. It is performed one arm at a time, allowing for focused muscle engagement and unilateral strength development. The exercise also involves the triceps and upper back as secondary muscles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0590.gif","youtube_id":null,"instructions":["Adjust the seat height and position yourself on the machine with your back against the pad.","Grasp the lever handle with one hand and position your elbow at a 90-degree angle.","Press the lever upward until your arm is fully extended overhead.","Pause for a moment at the top, then slowly lower the lever back down to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]},{"id":"591","name":"lever overhand triceps dip","body_part":"upper arms","target":"triceps","secondary_muscles":["chest","shoulders"],"equipment":"leverage machine","difficulty":"beginner","description":"The lever overhand triceps dip is a machine-based exercise targeting the triceps, with secondary emphasis on the chest and shoulders. It involves lowering and raising the body using a leverage machine, which provides stability and controlled resistance.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0591.gif","youtube_id":null,"instructions":["Adjust the machine to the appropriate height and secure your body in position.","Grasp the handles with an overhand grip and position your body so that your arms are fully extended.","Lower your body by bending your elbows, keeping your upper arms close to your sides.","Continue lowering until your upper arms are parallel to the floor.","Pause for a moment, then push yourself back up to the starting position by extending your elbows.","Repeat for the desired number of repetitions."]},{"id":"592","name":"lever preacher curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"leverage machine","difficulty":"beginner","description":"The lever preacher curl is a strength training exercise performed on a leverage machine, primarily targeting the biceps with secondary activation of the forearms. It involves curling the handles upward while keeping the upper arms supported on a pad, which isolates the biceps and minimizes cheating.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0592.gif","youtube_id":null,"instructions":["Adjust the seat height and position yourself on the leverage machine.","Place your upper arms on the pad and grip the handles with an underhand grip.","Keep your back straight and your elbows positioned on the pad.","Exhale and curl your forearms towards your upper arms, contracting your biceps.","Pause for a moment at the top of the movement, squeezing your biceps.","Inhale and slowly lower the handles back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"593","name":"lever reverse hyperextension","body_part":"upper legs","target":"glutes","secondary_muscles":["hamstrings","lower back"],"equipment":"leverage machine","difficulty":"intermediate","description":"The lever reverse hyperextension is a machine-based exercise targeting the glutes, with secondary emphasis on the hamstrings and lower back. It involves lying face down on a leverage machine and lifting the legs upward using the glutes and hamstrings.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0593.gif","youtube_id":null,"instructions":["Adjust the leverage machine to fit your body and secure your feet in the foot pads.","Lie face down on the machine with your upper body hanging off the edge and your hips resting on the pad.","Cross your arms over your chest or place them behind your head.","Engage your glutes and hamstrings to lift your legs upward until they are parallel to the ground.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"594","name":"lever seated calf raise","body_part":"lower legs","target":"calves","secondary_muscles":["soleus","ankle stabilizers"],"equipment":"leverage machine","difficulty":"beginner","description":"The lever seated calf raise is a machine-based exercise that targets the calf muscles, particularly the gastrocnemius and soleus. It is performed while seated, using a leverage machine to provide resistance as you raise and lower your heels.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0594.gif","youtube_id":null,"instructions":["Adjust the seat height so that your knees are slightly bent and your feet are flat on the footplate.","Place your toes on the footplate with your heels hanging off the edge.","Grasp the handles or the sides of the seat for stability.","Push through the balls of your feet to raise your heels as high as possible.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"595","name":"lever seated crunch (chest pad)","body_part":"waist","target":"abs","secondary_muscles":["obliques"],"equipment":"leverage machine","difficulty":"beginner","description":"The lever seated crunch (chest pad) is an abdominal exercise performed on a leverage machine. It primarily targets the abs and also engages the obliques. The movement involves controlled flexion and extension of the torso against resistance, making it suitable for building core strength.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0595.gif","youtube_id":null,"instructions":["Adjust the seat height and chest pad position according to your comfort.","Sit on the machine with your back against the chest pad and your feet flat on the floor.","Grasp the handles or side bars for stability.","Engage your abs and slowly lean back, allowing the chest pad to move with you.","Pause for a moment at the maximum contraction, feeling the tension in your abs.","Slowly return to the starting position by contracting your abs and pulling yourself back up.","Repeat for the desired number of repetitions."]},{"id":"596","name":"lever seated fly","body_part":"chest","target":"pectorals","secondary_muscles":["deltoids","trapezius"],"equipment":"leverage machine","difficulty":"beginner","description":"The lever seated fly is a machine-based exercise targeting the pectoral muscles, performed by bringing the handles together in front of the chest while seated.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0596.gif","youtube_id":null,"instructions":["Adjust the seat height and position yourself on the machine with your back against the pad.","Grasp the handles with a pronated grip and keep your elbows slightly bent.","Exhale and push the handles forward, bringing them together in front of your chest.","Pause for a moment, squeezing your chest muscles.","Inhale and slowly return to the starting position, allowing your chest muscles to stretch.","Repeat for the desired number of repetitions."]},{"id":"597","name":"lever seated hip abduction","body_part":"upper legs","target":"abductors","secondary_muscles":["glutes","hamstrings"],"equipment":"leverage machine","difficulty":"beginner","description":"The lever seated hip abduction is a machine-based exercise that targets the hip abductor muscles. It is performed while seated, pushing the legs apart against resistance provided by the machine.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0597.gif","youtube_id":null,"instructions":["Adjust the seat height so that your knees are at a 90-degree angle.","Sit on the machine with your back against the backrest and your feet on the footrests.","Place your hands on the side handles for stability.","Engage your abductors and slowly push your legs apart, away from the midline of your body.","Pause for a moment at the end of the movement, then slowly bring your legs back together to the starting position.","Repeat for the desired number of repetitions."]},{"id":"598","name":"lever seated hip adduction","body_part":"upper legs","target":"adductors","secondary_muscles":["hamstrings","glutes"],"equipment":"leverage machine","difficulty":"beginner","description":"The lever seated hip adduction is a machine-based exercise targeting the adductor muscles of the inner thighs. It is performed by bringing the legs together against resistance while seated.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0598.gif","youtube_id":null,"instructions":["Adjust the seat height and position yourself on the machine with your back against the backrest.","Place your feet on the footrests and grasp the handles for stability.","Engage your adductor muscles and slowly bring your legs together, squeezing your inner thighs.","Pause for a moment at the peak contraction, then slowly return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"599","name":"lever seated leg curl","body_part":"upper legs","target":"hamstrings","secondary_muscles":["calves"],"equipment":"leverage machine","difficulty":"beginner","description":"The lever seated leg curl is a machine-based exercise that targets the hamstrings. It involves curling your lower legs against resistance while seated, isolating the hamstrings and minimizing involvement from other muscle groups.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0599.gif","youtube_id":null,"instructions":["Adjust the machine to fit your body and sit on it with your back against the backrest.","Place your lower legs under the padded lever, just above your ankles.","Grasp the handles on the sides of the machine for support.","Keeping your upper legs stationary, exhale and curl your legs up as far as possible.","Hold the contracted position for a brief pause as you squeeze your hamstrings.","Inhale and slowly lower the lever back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"6","name":"alternate heel touchers","body_part":"waist","target":"abs","secondary_muscles":["obliques"],"equipment":"body weight","difficulty":"beginner","description":"Alternate heel touchers is a bodyweight exercise targeting the abdominal muscles, particularly the obliques. It involves lying on your back, lifting your shoulders, and reaching side to side to touch your heels, engaging your core throughout.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0006.gif","youtube_id":null,"instructions":["Lie flat on your back with your knees bent and feet flat on the ground.","Extend your arms straight out to the sides, parallel to the ground.","Engaging your abs, lift your shoulders off the ground and reach your right hand towards your right heel.","Return to the starting position and repeat on the left side, reaching your left hand towards your left heel.","Continue alternating sides for the desired number of repetitions."]},{"id":"60","name":"barbell lying triceps extension skull crusher","body_part":"upper arms","target":"triceps","secondary_muscles":["shoulders"],"equipment":"barbell","difficulty":"intermediate","description":"The barbell lying triceps extension, also known as the skull crusher, is a strength exercise that targets the triceps. Performed lying on a bench, it involves lowering a barbell to the forehead and extending the arms back up, requiring control and proper form to avoid injury.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0060.gif","youtube_id":null,"instructions":["Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.","Hold the barbell with an overhand grip, hands shoulder-width apart, and extend your arms straight up over your chest.","Keeping your upper arms stationary, slowly lower the barbell towards your forehead by bending your elbows.","Pause for a moment when the barbell is just above your forehead, then extend your arms back up to the starting position.","Repeat for the desired number of repetitions."]},{"id":"600","name":"lever seated leg raise crunch","body_part":"waist","target":"abs","secondary_muscles":["hip flexors"],"equipment":"leverage machine","difficulty":"intermediate","description":"The lever seated leg raise crunch is an abdominal exercise performed on a leverage machine. It targets the abs and also works the hip flexors. The movement involves raising the legs and curling the torso forward simultaneously, providing a challenging core workout.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0600.gif","youtube_id":null,"instructions":["Sit on the leverage machine with your back against the backrest and your feet on the footrests.","Grasp the handles or sidebars for stability.","Engage your abs and slowly raise your legs up towards your chest, curling your torso forward at the same time.","Pause for a moment at the top, then slowly lower your legs and torso back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"601","name":"lever seated reverse fly (parallel grip)","body_part":"shoulders","target":"delts","secondary_muscles":["trapezius","rhomboids"],"equipment":"leverage machine","difficulty":"beginner","description":"The lever seated reverse fly (parallel grip) is a machine-based exercise targeting the rear deltoids, with secondary emphasis on the trapezius and rhomboids. It involves pulling the handles back and outward while seated, focusing on squeezing the shoulder blades together.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0601.gif","youtube_id":null,"instructions":["Adjust the seat height and position yourself on the machine with your chest against the pad and your feet flat on the floor.","Grasp the handles with a parallel grip, palms facing each other, and keep your arms slightly bent.","Exhale and squeeze your shoulder blades together as you pull the handles back and outward, away from your body.","Pause for a moment at the peak contraction, then inhale and slowly return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"602","name":"lever seated reverse fly","body_part":"shoulders","target":"delts","secondary_muscles":["trapezius","rhomboids"],"equipment":"leverage machine","difficulty":"beginner","description":"The lever seated reverse fly is a machine-based exercise targeting the rear deltoids, with secondary emphasis on the trapezius and rhomboids. It is performed seated, using a leverage machine, which provides stability and helps isolate the target muscles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0602.gif","youtube_id":null,"instructions":["Adjust the seat height and position yourself on the machine with your chest against the pad and your feet flat on the floor.","Grasp the handles with an overhand grip and keep your arms slightly bent.","Exhale and squeeze your shoulder blades together as you pull the handles back and outward, away from your body.","Pause for a moment at the peak contraction, then inhale and slowly return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"603","name":"lever shoulder press","body_part":"shoulders","target":"delts","secondary_muscles":["triceps","chest"],"equipment":"leverage machine","difficulty":"beginner","description":"The lever shoulder press is a machine-based exercise targeting the deltoid muscles, with secondary emphasis on the triceps and chest. It is performed using a leverage machine, providing guided movement for safety and stability.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0603.gif","youtube_id":null,"instructions":["Adjust the seat height and position yourself on the machine with your back against the backrest.","Grasp the handles with an overhand grip and position your hands at shoulder level.","Push the handles upward until your arms are fully extended, but do not lock your elbows.","Pause for a moment at the top, then slowly lower the handles back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"604","name":"lever shrug","body_part":"back","target":"traps","secondary_muscles":["shoulders"],"equipment":"leverage machine","difficulty":"beginner","description":"The lever shrug is a machine-based exercise targeting the trapezius muscles. It involves elevating the shoulders while keeping the arms straight, using a leverage machine for resistance.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0604.gif","youtube_id":null,"instructions":["Adjust the seat height and position yourself on the leverage machine with your back against the pad.","Grasp the handles with an overhand grip and keep your arms straight.","Keeping your back straight, lift your shoulders up towards your ears as high as possible.","Hold the contraction for a moment, then slowly lower your shoulders back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"605","name":"lever standing calf raise","body_part":"lower legs","target":"calves","secondary_muscles":["soleus","ankle stabilizers"],"equipment":"leverage machine","difficulty":"beginner","description":"The lever standing calf raise is a strength exercise performed on a leverage machine, targeting the calves. It involves raising and lowering the heels while standing, using resistance provided by the machine.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0605.gif","youtube_id":null,"instructions":["Adjust the machine to your height and stand with your feet shoulder-width apart.","Place your shoulders under the pads and hold onto the handles for stability.","Raise your heels as high as possible by extending your ankles.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"606","name":"lever t bar row","body_part":"back","target":"upper back","secondary_muscles":["biceps","forearms"],"equipment":"leverage machine","difficulty":"beginner","description":"The lever T bar row is a machine-based exercise targeting the upper back, with secondary emphasis on the biceps and forearms. It is performed seated with the chest supported, reducing lower back strain and allowing for focused engagement of the upper back muscles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0606.gif","youtube_id":null,"instructions":["Adjust the seat height and footplate position to ensure proper alignment.","Sit on the machine with your chest against the pad and your feet flat on the footplate.","Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.","Keep your back straight and engage your core.","Pull the handles towards your torso, squeezing your shoulder blades together.","Pause for a moment at the peak contraction, then slowly release the handles back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"607","name":"lever triceps extension","body_part":"upper arms","target":"triceps","secondary_muscles":["shoulders"],"equipment":"leverage machine","difficulty":"beginner","description":"The lever triceps extension is an isolation exercise performed on a leverage machine to target the triceps. It involves extending the arms against resistance, focusing on triceps activation while minimizing shoulder involvement.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0607.gif","youtube_id":null,"instructions":["Adjust the seat height and position yourself on the machine with your back against the pad.","Grasp the handles with an overhand grip and fully extend your arms in front of you.","Keeping your upper arms stationary, slowly lower the handles towards your forehead by bending your elbows.","Pause for a moment at the bottom, then push the handles back up to the starting position by extending your arms.","Repeat for the desired number of repetitions."]},{"id":"609","name":"london bridge","body_part":"back","target":"upper back","secondary_muscles":["shoulders","biceps","forearms"],"equipment":"rope","difficulty":"beginner","description":"The London Bridge exercise targets the upper back using a rope attached to a high anchor point. It involves pulling the rope towards the body while squeezing the shoulder blades together, engaging the upper back, shoulders, biceps, and forearms.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0609.gif","youtube_id":null,"instructions":["Attach the rope to a high anchor point.","Stand facing away from the anchor point with your feet shoulder-width apart.","Grasp the rope with an overhand grip, palms facing down.","Lean forward slightly, keeping your back straight and core engaged.","Pull the rope towards your body, squeezing your shoulder blades together.","Pause for a moment at the peak of the movement, then slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"61","name":"barbell lying triceps extension","body_part":"upper arms","target":"triceps","secondary_muscles":["shoulders"],"equipment":"barbell","difficulty":"intermediate","description":"The barbell lying triceps extension is a strength exercise targeting the triceps, performed by lying on a bench and lowering a barbell towards the forehead before extending the arms back up.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0061.gif","youtube_id":null,"instructions":["Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.","Hold the barbell with an overhand grip, hands shoulder-width apart, and extend your arms straight up over your chest.","Keeping your upper arms stationary, slowly lower the barbell towards your forehead by bending your elbows.","Pause for a moment at the bottom, then extend your arms back up to the starting position.","Repeat for the desired number of repetitions."]},{"id":"613","name":"lying (side) quads stretch","body_part":"upper legs","target":"quads","secondary_muscles":["hamstrings"],"equipment":"body weight","difficulty":"beginner","description":"A static stretch performed lying on your side to target the quadriceps, often used to improve flexibility and reduce muscle tightness.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0613.gif","youtube_id":null,"instructions":["Lie on your side with your legs straight.","Bend your top leg and grab your ankle or foot with your hand.","Gently pull your ankle or foot towards your glutes until you feel a stretch in your quads.","Hold the stretch for 20-30 seconds.","Release the stretch and repeat on the other side."]},{"id":"620","name":"lying leg raise flat bench","body_part":"waist","target":"abs","secondary_muscles":["hip flexors"],"equipment":"body weight","difficulty":"intermediate","description":"The lying leg raise flat bench is an abdominal exercise performed on a flat bench using only body weight. It primarily targets the abs and also engages the hip flexors. The movement involves lifting straight legs up towards the ceiling while lying flat, then lowering them back down under control.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0620.gif","youtube_id":null,"instructions":["Lie flat on a flat bench with your back pressed against it.","Place your hands under your glutes for support.","Keep your legs straight and together, and lift them up towards the ceiling.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"624","name":"march sit (wall)","body_part":"upper legs","target":"glutes","secondary_muscles":["quadriceps","hamstrings","calves"],"equipment":"body weight","difficulty":"intermediate","description":"The march sit (wall) is a lower body exercise performed with body weight, targeting the glutes and also engaging the quadriceps, hamstrings, and calves. It involves holding a wall sit position while alternately lifting each knee towards the chest, mimicking a marching motion.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0624.gif","youtube_id":null,"instructions":["Stand with your back against a wall and your feet hip-width apart.","Slowly slide your back down the wall until your knees are bent at a 90-degree angle.","Lift your right foot off the ground and bring your knee towards your chest.","Lower your right foot back down and lift your left foot off the ground, bringing your knee towards your chest.","Continue alternating between lifting your right and left foot for the desired number of repetitions."]},{"id":"627","name":"mixed grip chin-up","body_part":"back","target":"lats","secondary_muscles":["biceps","forearms"],"equipment":"body weight","difficulty":"intermediate","description":"The mixed grip chin-up is a bodyweight exercise targeting the lats, with secondary emphasis on the biceps and forearms. It involves pulling your body up to a bar using a mixed grip, which challenges grip strength and upper body pulling power.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0627.gif","youtube_id":null,"instructions":["Grab the pull-up bar with an underhand grip (palms facing towards you) and your hands slightly wider than shoulder-width apart.","Hang from the bar with your arms fully extended and your feet off the ground.","Engage your back muscles and pull your body up towards the bar, leading with your chest.","Continue pulling until your chin is above the bar.","Pause for a moment at the top, then slowly lower your body back down to the starting position with control.","Repeat for the desired number of repetitions."]},{"id":"628","name":"monster walk","body_part":"upper legs","target":"glutes","secondary_muscles":["hamstrings","quadriceps"],"equipment":"body weight (with resistance band)","difficulty":"beginner","description":"The monster walk is a lower body exercise that targets the glutes and also works the hamstrings and quadriceps. It is typically performed with a resistance band around the ankles to increase intensity. The movement involves stepping side-to-side while maintaining tension in the band and a slight knee bend.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0628.gif","youtube_id":null,"instructions":["Place a resistance band around your ankles.","Stand with your feet shoulder-width apart and slightly bend your knees.","Take a step to the side with your right foot, maintaining tension on the resistance band.","Follow with your left foot, stepping to the side to return to the starting position.","Repeat for the desired number of repetitions, then switch sides."]},{"id":"63","name":"barbell narrow stance squat","body_part":"upper legs","target":"glutes","secondary_muscles":["quadriceps","hamstrings","calves"],"equipment":"barbell","difficulty":"intermediate","description":"The barbell narrow stance squat is a lower body strength exercise that targets the glutes, with significant involvement of the quadriceps, hamstrings, and calves. It is performed by holding a barbell across the upper back and squatting with a narrow stance, emphasizing the inner thighs and glutes.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0063.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and toes pointing slightly outward.","Hold the barbell across your upper back, resting it on your traps or rear delts.","Engage your core and keep your chest up as you slowly lower your body by bending your knees and pushing your hips back.","Continue lowering until your thighs are parallel to the ground or slightly below.","Pause for a moment, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"630","name":"mountain climber","body_part":"cardio","target":"cardiovascular system","secondary_muscles":["core","shoulders","triceps"],"equipment":"body weight","difficulty":"beginner","description":"Mountain climbers are a dynamic bodyweight exercise that targets the cardiovascular system while also engaging the core, shoulders, and triceps. The movement mimics a running motion in a plank position, making it effective for both cardio and muscular endurance.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0630.gif","youtube_id":null,"instructions":["Start in a high plank position with your hands directly under your shoulders and your body in a straight line.","Engage your core and bring your right knee towards your chest, then quickly switch and bring your left knee towards your chest.","Continue alternating legs in a running motion, keeping your hips low and your core engaged.","Maintain a steady pace and breathe evenly throughout the exercise.","Repeat for the desired number of repetitions."]},{"id":"631","name":"muscle up","body_part":"back","target":"lats","secondary_muscles":["biceps","triceps","shoulders","chest"],"equipment":"body weight","difficulty":"advanced","description":"The muscle up is a challenging bodyweight exercise that combines a pull-up with a dip, requiring significant upper body strength, coordination, and explosive power. It targets the lats primarily, with secondary engagement of the biceps, triceps, shoulders, and chest.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0631.gif","youtube_id":null,"instructions":["Start by hanging from a pull-up bar with your palms facing away from you and your arms fully extended.","Engage your core and pull your body up towards the bar, leading with your chest.","As you reach the top of the movement, transition your grip so that your palms are facing towards you.","Continue pulling yourself up until your chest is above the bar and your arms are fully flexed.","Reverse the movement by slowly lowering yourself back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"633","name":"neck bridge prone","body_part":"neck","target":"levator scapulae","secondary_muscles":["traps","upper back","abs"],"equipment":"body weight","difficulty":"advanced","description":"Kneel on a padded surface and place your forehead on the mat with hands for support, hips high. Shift your weight between forehead and toes in small, controlled rocks to strengthen the neck while keeping a tucked-chin position.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0633.gif","youtube_id":null,"instructions":["Place a thick pad on the floor; kneel with toes tucked, hands under shoulders, and forehead on the pad.","Gently tuck the chin to create a long neck and brace your abs.","Press into your forehead and toes to lift the knees slightly, raising the hips into a pike.","With hands lightly assisting, slowly shift your body forward to load the forehead without collapsing the neck.","Pause briefly, then shift back to reduce load while maintaining alignment and steady breathing.","Perform small, pain-free rocks for reps, keeping movements slow and controlled.","Lower the knees back to the floor to exit the position."]},{"id":"634","name":"negative crunch","body_part":"waist","target":"abs","secondary_muscles":["hip flexors"],"equipment":"body weight","difficulty":"beginner","description":"The negative crunch is an abdominal exercise focusing on the eccentric (lowering) phase of the crunch to increase core strength and control.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0634.gif","youtube_id":null,"instructions":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"635","name":"oblique crunches floor","body_part":"waist","target":"abs","secondary_muscles":["obliques"],"equipment":"body weight","difficulty":"beginner","description":"Oblique crunches on the floor target the abdominal muscles, especially the obliques, by incorporating a twisting motion as you crunch up. This exercise is performed lying on your back, using only body weight, and is suitable for most fitness levels.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0635.gif","youtube_id":null,"instructions":["Lie on your back with your knees bent and feet flat on the floor.","Place your hands behind your head or cross them over your chest.","Engage your abs and lift your shoulder blades off the floor, rotating your torso to one side.","Pause for a moment, then lower your shoulder blades back down to the floor.","Repeat on the other side, alternating sides with each repetition."]},{"id":"636","name":"olympic barbell hammer curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"olympic barbell","difficulty":"intermediate","description":"The olympic barbell hammer curl is a strength exercise targeting the biceps and forearms. It involves curling an Olympic barbell with a neutral grip, emphasizing both the biceps and brachialis muscles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0636.gif","youtube_id":null,"instructions":["Stand up straight with your feet shoulder-width apart and hold an Olympic barbell with an overhand grip.","Let the barbell hang at arm's length in front of your thighs, with your palms facing your body.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the barbell until your biceps are fully contracted and the barbell is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the barbell back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"637","name":"olympic barbell triceps extension","body_part":"upper arms","target":"triceps","secondary_muscles":["shoulders"],"equipment":"olympic barbell","difficulty":"intermediate","description":"The olympic barbell triceps extension is a strength exercise targeting the triceps, performed by raising an Olympic barbell overhead and lowering it behind the head before extending the arms back up.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0637.gif","youtube_id":null,"instructions":["Start by standing with your feet shoulder-width apart and holding the barbell with an overhand grip.","Raise the barbell above your head, fully extending your arms.","Keeping your upper arms close to your head, slowly lower the barbell behind your head by bending your elbows.","Pause for a moment, then extend your arms back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"638","name":"one arm chin-up","body_part":"back","target":"lats","secondary_muscles":["biceps","forearms"],"equipment":"body weight","difficulty":"advanced","description":"The one arm chin-up is a highly advanced bodyweight exercise that targets the latissimus dorsi (lats) and requires significant strength, coordination, and grip power. It is performed by pulling your body up to a bar using only one arm, with the other hand optionally supporting the wrist.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0638.gif","youtube_id":null,"instructions":["Stand facing a pull-up bar with your feet shoulder-width apart.","Reach up and grab the bar with an underhand grip, with one hand gripping the bar and the other hand holding your wrist for support.","Hang from the bar with your arm fully extended, keeping your body straight and your core engaged.","Pull yourself up towards the bar by bending your elbow and squeezing your back muscles.","Continue pulling until your chin is above the bar, then slowly lower yourself back down to the starting position.","Repeat for the desired number of repetitions, then switch arms and repeat."]},{"id":"639","name":"one arm dip","body_part":"upper arms","target":"triceps","secondary_muscles":["chest","shoulders"],"equipment":"body weight","difficulty":"advanced","description":"The one arm dip is a challenging bodyweight exercise that targets the triceps, with secondary emphasis on the chest and shoulders. It requires significant upper body strength, balance, and coordination, as you support your body weight with one arm while performing the dip motion.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0639.gif","youtube_id":null,"instructions":["Stand facing away from a bench or chair, with your feet shoulder-width apart.","Place one hand on the bench or chair behind you, fingers pointing towards your body.","Extend your legs out in front of you, keeping your heels on the ground.","Bend your elbows and lower your body towards the ground, keeping your back close to the bench or chair.","Pause for a moment at the bottom, then push through your palms to straighten your arms and return to the starting position.","Repeat for the desired number of repetitions, then switch sides and repeat with the other arm."]},{"id":"64","name":"barbell one arm bent over row","body_part":"back","target":"upper back","secondary_muscles":["biceps","forearms"],"equipment":"barbell","difficulty":"intermediate","description":"The barbell one arm bent over row is a unilateral strength exercise targeting the upper back, requiring balance, coordination, and core stability. It is performed by bending at the hips, keeping the back straight, and rowing a barbell with one arm while maintaining a stable position.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0064.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, knees slightly bent, and hold a barbell with one hand using an overhand grip.","Bend forward at the hips, keeping your back straight and your head in a neutral position.","Pull the barbell up towards your chest, keeping your elbow close to your body and squeezing your shoulder blades together.","Lower the barbell back down to the starting position in a controlled manner.","Repeat for the desired number of repetitions, then switch to the other arm."]},{"id":"640","name":"one arm slam (with medicine ball)","body_part":"waist","target":"abs","secondary_muscles":["shoulders","back"],"equipment":"medicine ball","difficulty":"intermediate","description":"The one arm slam with a medicine ball is a dynamic exercise targeting the abs, shoulders, and back. It involves forcefully slamming a medicine ball to the ground with one arm, requiring core strength, power, and coordination.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0640.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, holding the medicine ball with one hand in front of your waist.","Bend your knees slightly and engage your core.","Raise the medicine ball above your head, fully extending your arm.","Forcefully slam the medicine ball down to the ground, using your core and shoulders to generate power.","Catch the medicine ball on the bounce and repeat for the desired number of repetitions."]},{"id":"641","name":"otis up","body_part":"waist","target":"abs","secondary_muscles":["hip flexors","lower back"],"equipment":"weighted","difficulty":"intermediate","description":"The Otis Up is a weighted abdominal exercise that targets the abs, with secondary emphasis on the hip flexors and lower back. It involves curling the torso up from a lying position, requiring core strength and stability.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0641.gif","youtube_id":null,"instructions":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"642","name":"outside leg kick push-up","body_part":"upper legs","target":"glutes","secondary_muscles":["quadriceps","hamstrings","calves"],"equipment":"body weight","difficulty":"advanced","description":"The outside leg kick push-up is a dynamic bodyweight exercise that combines a traditional push-up with a lateral leg kick, targeting the glutes and engaging the quadriceps, hamstrings, and calves. This movement challenges upper body strength, core stability, coordination, and lower body mobility.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0642.gif","youtube_id":null,"instructions":["Start in a push-up position with your hands slightly wider than shoulder-width apart and your feet together.","Lower your body towards the ground by bending your elbows, keeping your back straight and core engaged.","As you push back up, kick one leg out to the side, extending it fully and engaging your glutes.","Return your leg to the starting position and repeat the push-up, alternating legs with each repetition.","Continue alternating leg kicks and push-ups for the desired number of repetitions."]},{"id":"643","name":"overhead triceps stretch","body_part":"upper arms","target":"triceps","secondary_muscles":["shoulders"],"equipment":"body weight","difficulty":"beginner","description":"The overhead triceps stretch is a static stretching exercise that targets the triceps and also stretches the shoulders. It is performed by extending one arm overhead, bending at the elbow, and using the opposite hand to gently pull the elbow for a deeper stretch.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0643.gif","youtube_id":null,"instructions":["Stand or sit upright with your feet shoulder-width apart.","Extend one arm overhead, bending at the elbow so that your hand reaches towards the opposite shoulder blade.","With your other hand, gently pull the elbow of the extended arm towards the opposite side of your head, feeling a stretch in your triceps.","Hold the stretch for 15-30 seconds, then release.","Repeat on the other side."]},{"id":"648","name":"power clean","body_part":"upper legs","target":"hamstrings","secondary_muscles":["glutes","quadriceps","calves"],"equipment":"barbell","difficulty":"advanced","description":"The power clean is a compound Olympic weightlifting movement that involves lifting a barbell from the floor to the shoulders in one explosive motion. It targets the hamstrings, glutes, quadriceps, and calves, and requires significant strength, coordination, and technique.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0648.gif","youtube_id":null,"instructions":["Start with the barbell on the ground in front of you, with your feet shoulder-width apart.","Bend down and grip the barbell with an overhand grip, slightly wider than shoulder-width apart.","Keep your back straight and chest up as you lift the barbell off the ground, extending your hips and knees.","As the barbell reaches your mid-thigh, explosively pull it upwards, shrugging your shoulders and pulling your elbows high and to the sides.","As the barbell reaches its highest point, quickly drop underneath it, rotating your elbows around and catching the barbell on your shoulders in a front squat position.","Stand up with the barbell, fully extending your hips and knees.","Lower the barbell back down to the starting position, keeping control of the weight throughout the movement.","Repeat for the desired number of repetitions."]},{"id":"65","name":"barbell one arm floor press","body_part":"upper arms","target":"triceps","secondary_muscles":["chest","shoulders"],"equipment":"barbell","difficulty":"intermediate","description":"The barbell one arm floor press is a unilateral pressing exercise that targets the triceps while also engaging the chest and shoulders. It requires the lifter to stabilize the barbell with one arm while lying on the floor, which increases the demand on core stability and coordination.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0065.gif","youtube_id":null,"instructions":["Lie flat on your back on the floor with your knees bent and feet flat on the ground.","Hold the barbell with one hand, palm facing up, and extend your arm straight up over your chest.","Slowly lower the barbell towards your chest, keeping your elbow close to your body.","Pause for a moment at the bottom, then push the barbell back up to the starting position.","Repeat for the desired number of repetitions, then switch arms."]},{"id":"650","name":"pull-in (on stability ball)","body_part":"waist","target":"abs","secondary_muscles":["hip flexors"],"equipment":"stability ball","difficulty":"intermediate","description":"The pull-in on a stability ball is an abdominal exercise that also engages the hip flexors. It requires balance and core strength as you bring your knees toward your chest while stabilizing your body on the ball.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0650.gif","youtube_id":null,"instructions":["Start by sitting on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Place your hands on the sides of the stability ball for support.","Engage your abs and slowly roll your hips forward, bringing your knees towards your chest.","Pause for a moment at the top of the movement, then slowly extend your legs back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"651","name":"pull up (neutral grip)","body_part":"back","target":"lats","secondary_muscles":["biceps","forearms"],"equipment":"body weight","difficulty":"intermediate","description":"The neutral grip pull-up is a bodyweight exercise targeting the latissimus dorsi (lats) and also engaging the biceps and forearms. It is performed by hanging from a pull-up bar with palms facing each other, pulling the chin above the bar, and lowering back down with control.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0651.gif","youtube_id":null,"instructions":["Hang from a pull-up bar with a neutral grip (palms facing each other) and your arms fully extended.","Engage your core and squeeze your shoulder blades together.","Pull your body up towards the bar by bending your elbows and driving your elbows down towards your hips.","Continue pulling until your chin is above the bar.","Pause for a moment at the top, then slowly lower your body back down to the starting position with control.","Repeat for the desired number of repetitions."]},{"id":"653","name":"push-up (bosu ball)","body_part":"chest","target":"pectorals","secondary_muscles":["triceps","shoulders","core"],"equipment":"bosu ball","difficulty":"intermediate","description":"The push-up (bosu ball) is a variation of the traditional push-up performed with hands on a BOSU ball, increasing instability and engaging more core and stabilizer muscles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0653.gif","youtube_id":null,"instructions":["Place the bosu ball on the ground with the flat side facing up.","Position yourself in a push-up position with your hands on the outer edges of the bosu ball.","Engage your core and lower your body down towards the bosu ball by bending your elbows.","Push yourself back up to the starting position by extending your arms.","Repeat for the desired number of repetitions."]},{"id":"655","name":"push-up (on stability ball)","body_part":"chest","target":"pectorals","secondary_muscles":["triceps","shoulders","core"],"equipment":"stability ball","difficulty":"advanced","description":"The push-up on a stability ball is a challenging variation of the traditional push-up that requires additional balance and core engagement. By placing your hands on a stability ball, you increase the instability of the movement, forcing your chest, triceps, shoulders, and core to work harder to maintain proper form.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0655.gif","youtube_id":null,"instructions":["Place the stability ball on the ground and position yourself facing down with your hands on the ball, shoulder-width apart.","Extend your legs straight out behind you, balancing on your toes.","Engage your core and lower your chest towards the ball by bending your elbows, keeping your body in a straight line.","Pause for a moment at the bottom, then push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."]},{"id":"656","name":"push-up (on stability ball)","body_part":"chest","target":"pectorals","secondary_muscles":["triceps","shoulders","core"],"equipment":"stability ball","difficulty":"advanced","description":"The push-up on a stability ball is a challenging variation of the traditional push-up that increases instability, requiring greater core engagement and balance. It primarily targets the pectorals, with significant involvement from the triceps, shoulders, and core.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0656.gif","youtube_id":null,"instructions":["Place the stability ball on the ground and position yourself facing down with your hands on the ball, shoulder-width apart.","Extend your legs straight out behind you, balancing on your toes.","Engage your core and lower your chest towards the ball by bending your elbows, keeping your body in a straight line.","Pause for a moment at the bottom, then push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."]},{"id":"658","name":"push-up (wall) v. 2","body_part":"chest","target":"pectorals","secondary_muscles":["triceps","shoulders"],"equipment":"body weight","difficulty":"beginner","description":"The wall push-up is a beginner-friendly variation of the traditional push-up, performed standing and pressing against a wall. It primarily targets the pectorals, with secondary emphasis on the triceps and shoulders. This exercise is ideal for those new to strength training or individuals seeking a low-impact alternative to floor push-ups.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0658.gif","youtube_id":null,"instructions":["Stand facing a wall, about arm's length away.","Place your hands on the wall at shoulder height, slightly wider than shoulder-width apart.","Step back with your feet, keeping them hip-width apart.","Engage your core and keep your body in a straight line from head to heels.","Bend your elbows and lower your chest towards the wall, keeping your body straight.","Pause for a moment, then push yourself back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"659","name":"push-up (wall)","body_part":"chest","target":"pectorals","secondary_muscles":["triceps","deltoids"],"equipment":"body weight","difficulty":"beginner","description":"The wall push-up is a beginner-friendly variation of the traditional push-up, performed standing and pressing against a wall. It primarily targets the pectorals, with secondary emphasis on the triceps and deltoids. This exercise is ideal for those new to strength training or individuals needing a low-impact alternative.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0659.gif","youtube_id":null,"instructions":["Stand facing a wall, about arm's length away.","Place your hands on the wall at shoulder height, slightly wider than shoulder-width apart.","Step back a few feet, keeping your body straight and your feet hip-width apart.","Bend your elbows and lower your chest towards the wall, keeping your body in a straight line.","Push back up to the starting position, straightening your arms.","Repeat for the desired number of repetitions."]},{"id":"66","name":"barbell one arm side deadlift","body_part":"upper legs","target":"glutes","secondary_muscles":["hamstrings","quadriceps","lower back"],"equipment":"barbell","difficulty":"advanced","description":"The barbell one arm side deadlift is a unilateral deadlift variation that targets the glutes, hamstrings, quadriceps, and lower back. It requires holding a barbell in one hand and performing a deadlift motion to the side of the body, challenging balance, grip strength, and core stability.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0066.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, holding a barbell in one hand with an overhand grip.","Keep your back straight and your core engaged.","Bend at the hips and lower the barbell towards the outside of your leg, keeping your arm straight and your chest up.","Lower the barbell as far as you can while maintaining good form.","Pause for a moment, then slowly return to the starting position.","Repeat for the desired number of repetitions, then switch sides."]},{"id":"660","name":"push-up close-grip off dumbbell","body_part":"upper arms","target":"triceps","secondary_muscles":["chest","shoulders"],"equipment":"dumbbell","difficulty":"intermediate","description":"The push-up close-grip off dumbbell is a variation of the push-up that targets the triceps, with additional emphasis on the chest and shoulders. It is performed by gripping dumbbells placed on the ground, which increases the range of motion and challenges stability.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0660.gif","youtube_id":null,"instructions":["Start in a push-up position with your hands placed close together, directly under your shoulders.","Hold a dumbbell in each hand, resting them on the ground.","Lower your body towards the ground by bending your elbows, keeping them close to your sides.","Push through your palms to extend your arms and return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"661","name":"push-up inside leg kick","body_part":"upper legs","target":"glutes","secondary_muscles":["quadriceps","hamstrings","calves","core"],"equipment":"body weight","difficulty":"intermediate","description":"The push-up inside leg kick is a dynamic bodyweight exercise that combines a standard push-up with a lateral leg kick, targeting the glutes and engaging the core, quadriceps, hamstrings, and calves. It requires coordination, balance, and strength.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0661.gif","youtube_id":null,"instructions":["Start in a push-up position with your hands slightly wider than shoulder-width apart and your feet together.","Lower your body towards the ground by bending your elbows, keeping your back straight and your core engaged.","As you push back up, lift one leg off the ground and kick it out to the side, keeping it straight.","Lower your leg back down and repeat the push-up, then switch to the other leg.","Continue alternating leg kicks with each push-up repetition."]},{"id":"662","name":"push-up","body_part":"chest","target":"pectorals","secondary_muscles":["triceps","deltoids","core"],"equipment":"body weight","difficulty":"beginner","description":"The push-up is a classic bodyweight exercise that targets the pectoral muscles, triceps, deltoids, and core. It is performed by lowering and raising the body using the arms while maintaining a straight line from head to heels.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0662.gif","youtube_id":null,"instructions":["Start in a high plank position with your hands slightly wider than shoulder-width apart and your feet together.","Engage your core and lower your body towards the ground by bending your elbows, keeping your body in a straight line.","Pause for a moment when your chest is just above the ground, then push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."]},{"id":"663","name":"push-up medicine ball","body_part":"chest","target":"pectorals","secondary_muscles":["triceps","shoulders","core"],"equipment":"medicine ball","difficulty":"advanced","description":"The push-up medicine ball is a challenging variation of the traditional push-up that requires you to place both hands on a medicine ball. This increases the demand on your chest, triceps, shoulders, and core, while also challenging your balance and stability.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0663.gif","youtube_id":null,"instructions":["Start in a high plank position with your hands on the medicine ball, shoulder-width apart.","Engage your core and lower your body towards the ground by bending your elbows, keeping your back straight.","Push through your palms to extend your arms and return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"664","name":"push-up to side plank","body_part":"waist","target":"abs","secondary_muscles":["shoulders","chest","triceps"],"equipment":"body weight","difficulty":"intermediate","description":"The push-up to side plank is a compound bodyweight exercise that combines a traditional push-up with a rotational movement into a side plank. This exercise targets the abs while also engaging the shoulders, chest, and triceps, and challenges core stability and balance.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0664.gif","youtube_id":null,"instructions":["Start in a push-up position with your hands shoulder-width apart and your body in a straight line.","Lower your body towards the ground by bending your elbows, keeping your core engaged.","Push back up to the starting position.","Shift your weight onto your left hand and rotate your body to the right, lifting your right arm towards the ceiling.","Hold the side plank position for a few seconds, then return to the starting position.","Repeat the push-up and side plank on the opposite side.","Continue alternating sides for the desired number of repetitions."]},{"id":"666","name":"raise single arm push-up","body_part":"chest","target":"pectorals","secondary_muscles":["triceps","shoulders","core"],"equipment":"body weight","difficulty":"advanced","description":"The raise single arm push-up is a challenging bodyweight exercise that targets the pectorals while also engaging the triceps, shoulders, and core. It requires significant strength, balance, and coordination as one arm is extended out to the side while performing a push-up.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0666.gif","youtube_id":null,"instructions":["Start in a push-up position with your hands slightly wider than shoulder-width apart and your feet together.","Extend one arm straight out to the side, parallel to the ground.","Lower your body towards the ground by bending your elbows, keeping your back straight and core engaged.","Push back up to the starting position, using your chest muscles to lift your body.","Repeat with the other arm extended."]},{"id":"668","name":"rear decline bridge","body_part":"upper legs","target":"glutes","secondary_muscles":["hamstrings","lower back"],"equipment":"body weight","difficulty":"beginner","description":"The rear decline bridge is a bodyweight exercise targeting the glutes, with secondary emphasis on the hamstrings and lower back. It involves lifting the hips off the ground while lying on your back, engaging the posterior chain.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0668.gif","youtube_id":null,"instructions":["Lie on your back with your feet flat on the ground and your knees bent.","Place your arms by your sides with your palms facing down.","Engage your glutes and hamstrings, and lift your hips off the ground until your body forms a straight line from your knees to your shoulders.","Hold this position for a few seconds, then slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"669","name":"rear deltoid stretch","body_part":"shoulders","target":"delts","secondary_muscles":["trapezius","rhomboids"],"equipment":"body weight","difficulty":"beginner","description":"The rear deltoid stretch is a bodyweight exercise targeting the deltoid muscles, particularly the rear (posterior) delts. It also stretches the trapezius and rhomboids. This movement is commonly used to improve shoulder flexibility and relieve tension.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0669.gif","youtube_id":null,"instructions":["Stand tall with your feet shoulder-width apart.","Extend your right arm across your chest, placing your left hand on your right elbow.","Gently pull your right arm towards your left shoulder, feeling a stretch in your right shoulder.","Hold the stretch for 15-30 seconds, then release.","Repeat on the other side."]},{"id":"67","name":"barbell one arm snatch","body_part":"shoulders","target":"delts","secondary_muscles":["traps","forearms","core"],"equipment":"barbell","difficulty":"advanced","description":"The barbell one arm snatch is an explosive, full-body movement that targets the shoulders (delts) and also engages the traps, forearms, and core. It requires coordination, balance, and strength to perform safely and effectively.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0067.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, toes pointing slightly outwards.","Hold the barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Bend your knees and lower your hips into a squat position, keeping your back straight and chest up.","Explosively extend your hips, knees, and ankles, driving the barbell upwards.","As the barbell reaches chest level, pull it upwards with your arm, keeping it close to your body.","Rotate your elbow under the barbell and extend your arm fully overhead, locking out your elbow.","Lower the barbell back down to the starting position in a controlled manner.","Repeat for the desired number of repetitions, then switch arms."]},{"id":"670","name":"rear pull-up","body_part":"back","target":"lats","secondary_muscles":["biceps","forearms"],"equipment":"body weight","difficulty":"advanced","description":"The rear pull-up is a bodyweight exercise targeting the latissimus dorsi (lats) and also engaging the biceps and forearms. It involves pulling your body up to a bar with an overhand grip, focusing on back strength and control.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0670.gif","youtube_id":null,"instructions":["Grab the pull-up bar with an overhand grip, slightly wider than shoulder-width apart.","Hang from the bar with your arms fully extended and your body straight.","Engage your back muscles and pull your body up towards the bar, keeping your elbows close to your body.","Continue pulling until your chin is above the bar.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"672","name":"reverse dip","body_part":"upper arms","target":"triceps","secondary_muscles":["chest","shoulders"],"equipment":"body weight","difficulty":"intermediate","description":"The reverse dip is a bodyweight exercise targeting the triceps, performed between two parallel bars. It also engages the chest and shoulders as secondary muscles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0672.gif","youtube_id":null,"instructions":["Position yourself between two parallel bars with your arms fully extended and your body straight.","Lower your body by bending your elbows until your upper arms are parallel to the ground.","Pause for a moment, then push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."]},{"id":"673","name":"reverse grip machine lat pulldown","body_part":"back","target":"lats","secondary_muscles":["biceps","forearms"],"equipment":"leverage machine","difficulty":"beginner","description":"The reverse grip machine lat pulldown targets the latissimus dorsi using a leverage machine and an underhand grip, also engaging the biceps and forearms. It is performed seated with controlled movement, focusing on pulling the handles down to the chest and squeezing the shoulder blades together.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0673.gif","youtube_id":null,"instructions":["Adjust the seat height and position yourself on the machine with your knees under the pads and your feet flat on the ground.","Grasp the handles with an underhand grip, slightly wider than shoulder-width apart.","Sit upright with your chest out and shoulders back, maintaining a slight arch in your lower back.","Pull the handles down towards your chest, squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, then slowly release the handles back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"674","name":"reverse grip pull-up","body_part":"back","target":"lats","secondary_muscles":["biceps","forearms"],"equipment":"body weight","difficulty":"intermediate","description":"The reverse grip pull-up is a bodyweight exercise targeting the lats, performed by pulling the body up to a bar with an underhand grip. It also engages the biceps and forearms.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0674.gif","youtube_id":null,"instructions":["Grab the pull-up bar with an underhand grip, hands shoulder-width apart.","Hang from the bar with your arms fully extended and your body straight.","Engage your back muscles and pull your body up towards the bar, leading with your chest.","Continue pulling until your chin is above the bar.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"675","name":"reverse hyper extension (on stability ball)","body_part":"upper legs","target":"glutes","secondary_muscles":["hamstrings","lower back"],"equipment":"stability ball","difficulty":"intermediate","description":"The reverse hyper extension on a stability ball targets the glutes, with secondary emphasis on the hamstrings and lower back. It requires balance and core stability due to the use of the stability ball, making it more challenging than a floor-based version.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0675.gif","youtube_id":null,"instructions":["Lie face down on a stability ball with your hips resting on the ball and your legs extended straight behind you.","Place your hands on the ground in front of you for stability.","Engaging your glutes and hamstrings, lift your legs up towards the ceiling as high as you can.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"677","name":"ring dips","body_part":"upper arms","target":"triceps","secondary_muscles":["chest","shoulders"],"equipment":"body weight","difficulty":"advanced","description":"Ring dips are a challenging bodyweight exercise performed on gymnastic rings, primarily targeting the triceps, with significant engagement of the chest and shoulders. The instability of the rings requires considerable strength, balance, and coordination.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0677.gif","youtube_id":null,"instructions":["Start by hanging from the rings with your arms fully extended and your body straight.","Lower your body by bending your elbows until your shoulders are below your elbows.","Push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."]},{"id":"678","name":"rocky pull-up pulldown","body_part":"back","target":"lats","secondary_muscles":["biceps","forearms"],"equipment":"body weight","difficulty":"intermediate","description":"The rocky pull-up pulldown is a bodyweight exercise targeting the lats, with secondary emphasis on the biceps and forearms. It involves pulling the body up to a bar and lowering it under control, requiring significant upper body strength and coordination.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0678.gif","youtube_id":null,"instructions":["Stand in front of a pull-up bar with your feet shoulder-width apart.","Reach up and grab the bar with an overhand grip, slightly wider than shoulder-width apart.","Hang from the bar with your arms fully extended and your body straight.","Engage your back muscles and pull your body up towards the bar, leading with your chest.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"68","name":"barbell one leg squat","body_part":"upper legs","target":"quads","secondary_muscles":["glutes","hamstrings","calves"],"equipment":"barbell","difficulty":"advanced","description":"The barbell one leg squat is a challenging lower body exercise that targets the quadriceps while also engaging the glutes, hamstrings, and calves. It requires significant balance, strength, and coordination, as you perform a squat on one leg while holding a barbell across your upper back.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0068.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and hold a barbell across your upper back.","Lift one foot off the ground and extend it forward, keeping it parallel to the ground.","Bend your standing leg and lower your body down as if sitting back into a chair, keeping your chest up and your back straight.","Lower yourself until your thigh is parallel to the ground, then push through your heel to return to the starting position.","Repeat for the desired number of repetitions, then switch legs and repeat."]},{"id":"680","name":"rope climb","body_part":"back","target":"upper back","secondary_muscles":["forearms","biceps","shoulders"],"equipment":"rope","difficulty":"advanced","description":"The rope climb is a challenging upper body exercise that targets the upper back, forearms, biceps, and shoulders. It requires significant grip strength, coordination, and core stability, as well as the ability to use both the upper and lower body to ascend and descend a rope safely.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0680.gif","youtube_id":null,"instructions":["Stand facing the rope with your feet shoulder-width apart.","Grab the rope with both hands, palms facing towards you.","Bend your knees slightly and engage your core.","Begin pulling yourself up the rope by alternating hand-over-hand movements.","Use your legs to assist in the upward movement.","Continue climbing until you reach the desired height or the top of the rope.","To descend, reverse the hand-over-hand movement while controlling your descent.","Repeat for the desired number of repetitions."]},{"id":"684","name":"run (equipment)","body_part":"cardio","target":"cardiovascular system","secondary_muscles":["quadriceps","hamstrings","calves"],"equipment":"body weight","difficulty":"beginner","description":"Running in place is a cardiovascular exercise that elevates the heart rate and improves overall endurance. It requires no equipment and can be performed anywhere, making it accessible for most fitness levels.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0684.gif","youtube_id":null,"instructions":["Start by standing upright with your feet hip-width apart.","Engage your core and keep your upper body relaxed.","Begin jogging in place, lifting your knees up towards your chest and landing softly on the balls of your feet.","Maintain a steady pace and continue jogging for the desired duration or distance.","Remember to breathe deeply and maintain good posture throughout the exercise."]},{"id":"685","name":"run","body_part":"cardio","target":"cardiovascular system","secondary_muscles":["quadriceps","hamstrings","calves"],"equipment":"body weight","difficulty":"beginner","description":"Running is a fundamental cardiovascular exercise that involves jogging or running in place or over a distance. It primarily targets the cardiovascular system and also engages the lower body muscles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0685.gif","youtube_id":null,"instructions":["Start by standing upright with your feet hip-width apart.","Engage your core and keep your upper body relaxed.","Begin jogging in place, lifting your knees up towards your chest and landing softly on the balls of your feet.","Maintain a steady pace and continue jogging for the desired duration or distance.","Remember to breathe deeply and maintain good posture throughout the exercise."]},{"id":"687","name":"russian twist","body_part":"waist","target":"abs","secondary_muscles":["obliques"],"equipment":"body weight","difficulty":"intermediate","description":"The Russian twist is a core exercise that targets the abdominal muscles and obliques. It involves rotating the torso from side to side while balancing on the sit bones, often with the feet lifted off the ground.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0687.gif","youtube_id":null,"instructions":["Sit on the ground with your knees bent and feet flat on the floor.","Lean back slightly while keeping your back straight and your core engaged.","Hold your hands together in front of your chest or hold a weight if desired.","Lift your feet off the ground, balancing on your sit bones.","Twist your torso to the right, bringing your hands or weight towards the right side of your body.","Pause for a moment, then twist your torso to the left, bringing your hands or weight towards the left side of your body.","Continue alternating sides for the desired number of repetitions."]},{"id":"688","name":"scapular pull-up","body_part":"back","target":"traps","secondary_muscles":["biceps","rhomboids","rear deltoids"],"equipment":"body weight","difficulty":"beginner","description":"The scapular pull-up is a bodyweight exercise that targets the trapezius muscles and helps improve scapular control and shoulder stability. It is performed by hanging from a pull-up bar and retracting the shoulder blades without bending the elbows.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0688.gif","youtube_id":null,"instructions":["Start by hanging from a pull-up bar with your palms facing away from you and your arms fully extended.","Retract your shoulder blades by pulling them down and back.","Engage your back muscles and pull your body up towards the bar, focusing on squeezing your shoulder blades together.","Pause for a moment at the top of the movement, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"689","name":"seated leg raise","body_part":"waist","target":"abs","secondary_muscles":["hip flexors"],"equipment":"body weight","difficulty":"beginner","description":"The seated leg raise is an abdominal exercise performed while sitting on a bench. It primarily targets the abs and also engages the hip flexors. The movement involves raising the legs while keeping them straight, which requires core strength and stability.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0689.gif","youtube_id":null,"instructions":["Sit on a flat bench with your back straight and your feet flat on the ground.","Place your hands on the sides of the bench for support.","Keeping your legs straight, slowly raise them up in front of you until they are parallel to the ground.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"69","name":"barbell overhead squat","body_part":"upper legs","target":"quads","secondary_muscles":["glutes","hamstrings","calves","core"],"equipment":"barbell","difficulty":"advanced","description":"The barbell overhead squat is a compound exercise that targets the quads and requires holding a barbell overhead while performing a squat. It demands significant strength, balance, mobility, and coordination.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0069.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and toes slightly turned out.","Hold the barbell with a wide grip, positioning it overhead with your arms fully extended.","Engage your core and lower your body down into a squat position, keeping your chest up and knees tracking over your toes.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"690","name":"seated lower back stretch","body_part":"back","target":"lats","secondary_muscles":["glutes","hamstrings"],"equipment":"body weight","difficulty":"beginner","description":"A gentle stretch performed while seated to target the lower back and lats, also engaging the glutes and hamstrings. This exercise is suitable for improving flexibility and relieving tension in the lower back area.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0690.gif","youtube_id":null,"instructions":["Sit on the edge of a chair with your feet flat on the ground.","Place your hands on your thighs or on the sides of the chair for support.","Slowly lean forward from your hips, keeping your back straight.","Feel the stretch in your lower back and hold for 20-30 seconds.","Slowly return to the starting position and repeat for the desired number of repetitions."]},{"id":"691","name":"seated side crunch (wall)","body_part":"waist","target":"abs","secondary_muscles":["obliques"],"equipment":"body weight","difficulty":"beginner","description":"The seated side crunch (wall) is an abdominal exercise performed while sitting on the floor with your back against a wall. It targets the abs and obliques by having you lean side to side, bringing your elbow toward your hip.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0691.gif","youtube_id":null,"instructions":["Sit on the floor with your back against a wall and your legs extended in front of you.","Bend your knees and place your feet flat on the floor, hip-width apart.","Place your hands behind your head with your elbows pointing outwards.","Engage your abs and lean to one side, bringing your elbow towards your hip.","Pause for a moment, then return to the starting position.","Repeat on the other side.","Continue alternating sides for the desired number of repetitions."]},{"id":"696","name":"self assisted inverse leg curl (on floor)","body_part":"upper legs","target":"hamstrings","secondary_muscles":["glutes","calves"],"equipment":"body weight","difficulty":"intermediate","description":"The self assisted inverse leg curl (on floor) is a bodyweight exercise targeting the hamstrings, with secondary emphasis on the glutes and calves. It involves curling the legs towards the glutes while keeping the hips lifted, requiring significant hamstring strength and control.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0696.gif","youtube_id":null,"instructions":["Lie flat on your back with your legs extended and your arms by your sides.","Bend your knees and place your feet flat on the ground, hip-width apart.","Lift your hips off the ground, engaging your glutes and hamstrings.","Slowly curl your legs towards your glutes, keeping your hips lifted.","Pause for a moment at the top, then slowly extend your legs back to the starting position.","Lower your hips back down to the ground.","Repeat for the desired number of repetitions."]},{"id":"697","name":"self assisted inverse leg curl","body_part":"upper legs","target":"hamstrings","secondary_muscles":["glutes","calves"],"equipment":"body weight","difficulty":"beginner","description":"The self assisted inverse leg curl is a bodyweight exercise targeting the hamstrings, with secondary emphasis on the glutes and calves. It involves curling the legs towards the chest while lying on your back, using your hands for support if needed.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0697.gif","youtube_id":null,"instructions":["Lie flat on your back on a mat or bench with your legs extended.","Place your hands by your sides or under your glutes for support.","Bend your knees and lift your feet off the ground, bringing your thighs towards your chest.","Pause for a moment at the top, then slowly lower your legs back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"699","name":"shoulder tap push-up","body_part":"chest","target":"pectorals","secondary_muscles":["triceps","core"],"equipment":"body weight","difficulty":"intermediate","description":"The shoulder tap push-up is a bodyweight exercise that combines a standard push-up with an alternating shoulder tap at the top of each rep. This movement challenges the chest, triceps, and core while also requiring balance and coordination to stabilize the body during the shoulder tap.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0699.gif","youtube_id":null,"instructions":["Start in a high plank position with your hands slightly wider than shoulder-width apart and your body in a straight line from head to heels.","Lower your body towards the ground by bending your elbows, keeping them close to your sides.","As you push back up, lift your right hand off the ground and tap your left shoulder.","Return your right hand to the ground and repeat the push-up, this time lifting your left hand and tapping your right shoulder.","Continue alternating shoulder taps with each push-up repetition.","Maintain a stable core and avoid excessive hip rotation throughout the exercise.","Repeat for the desired number of repetitions."]},{"id":"7","name":"alternate lateral pulldown","body_part":"back","target":"lats","secondary_muscles":["biceps","rhomboids"],"equipment":"cable","difficulty":"beginner","description":"The alternate lateral pulldown is a cable machine exercise targeting the latissimus dorsi, with secondary emphasis on the biceps and rhomboids. It involves pulling handles towards the chest in an alternating fashion, focusing on back strength and muscle engagement.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0007.gif","youtube_id":null,"instructions":["Sit on the cable machine with your back straight and feet flat on the ground.","Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.","Lean back slightly and pull the handles towards your chest, squeezing your shoulder blades together.","Pause for a moment at the peak of the movement, then slowly release the handles back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"70","name":"barbell preacher curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"barbell","difficulty":"beginner","description":"The barbell preacher curl is an isolation exercise that targets the biceps by using a preacher bench to stabilize the upper arms, minimizing shoulder movement and maximizing biceps engagement. It is performed with a barbell and is effective for building biceps strength and size.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0070.gif","youtube_id":null,"instructions":["Sit on a preacher bench with your upper arms resting on the pad and your chest against the support.","Grasp the barbell with an underhand grip, slightly wider than shoulder-width apart.","Keeping your upper arms stationary, exhale and curl the barbell up towards your shoulders.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"705","name":"side bridge v. 2","body_part":"waist","target":"abs","secondary_muscles":["obliques","glutes"],"equipment":"body weight","difficulty":"intermediate","description":"The side bridge v. 2 is a core stability exercise performed on the floor using only body weight. It targets the abs, with secondary emphasis on the obliques and glutes. The movement involves holding a side plank position, which challenges core strength and stability.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0705.gif","youtube_id":null,"instructions":["Lie on your side with your legs extended and stacked on top of each other.","Place your forearm on the ground directly below your shoulder, with your elbow bent at a 90-degree angle.","Engage your core and lift your hips off the ground, creating a straight line from your head to your feet.","Hold this position for the desired amount of time.","Lower your hips back down to the starting position.","Repeat on the other side."]},{"id":"709","name":"side hip (on parallel bars)","body_part":"waist","target":"abs","secondary_muscles":["obliques","hip flexors"],"equipment":"body weight","difficulty":"advanced","description":"The side hip (on parallel bars) is a challenging core exercise that targets the abs, obliques, and hip flexors by requiring you to lift your legs to the side while supporting your body weight on parallel bars.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0709.gif","youtube_id":null,"instructions":["Stand between two parallel bars with your feet shoulder-width apart.","Place your hands on the bars and lift your body off the ground, supporting your weight on your arms.","Engage your abs and slowly lift your legs to the side, keeping them straight.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"71","name":"barbell press sit-up","body_part":"waist","target":"abs","secondary_muscles":["shoulders","chest"],"equipment":"barbell","difficulty":"advanced","description":"The barbell press sit-up is an advanced abdominal exercise that combines a traditional sit-up with a barbell press, engaging the abs, shoulders, and chest. It requires significant core strength, coordination, and balance to safely press the barbell while performing the sit-up motion.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0071.gif","youtube_id":null,"instructions":["Lie flat on your back on a mat with your knees bent and feet flat on the ground.","Hold the barbell with an overhand grip, resting it on your chest.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"710","name":"side hip abduction","body_part":"upper legs","target":"abductors","secondary_muscles":["glutes","quadriceps"],"equipment":"body weight","difficulty":"beginner","description":"Side hip abduction is a bodyweight exercise that targets the hip abductors, helping to strengthen the outer thighs and hips. It also engages the glutes and quadriceps as secondary muscles. This movement is commonly used for strengthening, mobility, and rehabilitation purposes.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0710.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and your hands on your hips.","Shift your weight to one leg and lift the opposite leg out to the side, keeping it straight.","Pause for a moment at the top, then slowly lower your leg back down to the starting position.","Repeat on the other side.","Continue alternating sides for the desired number of repetitions."]},{"id":"713","name":"side neck stretch","body_part":"neck","target":"levator scapulae","secondary_muscles":["traps","upper back","delts"],"equipment":"body weight","difficulty":"beginner","description":"Stand or sit tall and gently tilt your head to bring one ear toward the same-side shoulder to stretch the opposite side of the neck. Keep shoulders level and relaxed, hold the stretch, then switch sides.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0713.gif","youtube_id":null,"instructions":["Stand or sit upright with feet hip-width apart, chest tall, and shoulders relaxed and down.","Keep your gaze forward and chin level (neutral neck).","Slowly tilt your head to the right, bringing your right ear toward your right shoulder without lifting or shrugging the shoulder.","Stop at a mild stretch on the left side of the neck and breathe steadily; hold 15–30 seconds.","Return to neutral slowly.","Repeat to the left side for 15–30 seconds; perform 2–3 rounds per side, moving gently and without pain."]},{"id":"716","name":"side push neck stretch","body_part":"neck","target":"levator scapulae","secondary_muscles":["trapezius","sternocleidomastoid"],"equipment":"body weight","difficulty":"beginner","description":"The side push neck stretch is a gentle stretching exercise targeting the levator scapulae and other neck muscles. It helps improve flexibility and relieve tension in the neck and upper shoulders.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0716.gif","youtube_id":null,"instructions":["Stand or sit up straight with your shoulders relaxed.","Tilt your head to the right, bringing your right ear towards your right shoulder.","Place your right hand on the left side of your head and gently apply pressure to increase the stretch.","Hold the stretch for 15-30 seconds.","Repeat on the other side, tilting your head to the left and applying pressure with your left hand.","Repeat the stretch 2-3 times on each side."]},{"id":"717","name":"side push-up","body_part":"upper arms","target":"triceps","secondary_muscles":["shoulders","chest","core"],"equipment":"body weight","difficulty":"intermediate","description":"The side push-up is a bodyweight exercise that primarily targets the triceps, while also engaging the shoulders, chest, and core. It is performed by lying on your side and pressing your body up using your bottom arm, which challenges your upper arm strength and stability.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0717.gif","youtube_id":null,"instructions":["Start by lying on your side with your legs extended and stacked on top of each other.","Place your bottom hand on the ground directly under your shoulder, fingers pointing forward.","Press through your bottom hand to lift your body off the ground, keeping your legs straight and your core engaged.","Extend your top arm straight up towards the ceiling, creating a straight line from your head to your heels.","Lower your body back down to the starting position with control.","Repeat for the desired number of repetitions, then switch sides."]},{"id":"72","name":"barbell prone incline curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"barbell","difficulty":"intermediate","description":"The barbell prone incline curl is a biceps-focused exercise performed lying face down on an incline bench. This position isolates the biceps and minimizes cheating by preventing the use of momentum or swinging. It primarily targets the biceps, with secondary engagement of the forearms.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0072.gif","youtube_id":null,"instructions":["Set up an incline bench at a 45-degree angle.","Lie face down on the bench with your chest and stomach resting against it.","Hold a barbell with an underhand grip, shoulder-width apart.","Extend your arms fully, allowing the barbell to hang down towards the floor.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the barbell until your biceps are fully contracted and the bar is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the barbell back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"720","name":"side-to-side chin","body_part":"back","target":"lats","secondary_muscles":["biceps","forearms"],"equipment":"body weight","difficulty":"advanced","description":"The side-to-side chin is a bodyweight exercise targeting the lats, performed by pulling yourself up to a bar and shifting your chin from one side to the other at the top of the movement. This variation increases the challenge to the lats and requires greater strength and control than a standard chin-up.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0720.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and your knees slightly bent.","Grasp a pull-up bar with an overhand grip, hands slightly wider than shoulder-width apart.","Hang from the bar with your arms fully extended and your body relaxed.","Pull yourself up by bending your elbows and bringing your chin towards the bar, while keeping your body straight.","Once your chin is above the bar, lower yourself back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"721","name":"side wrist pull stretch","body_part":"lower arms","target":"forearms","secondary_muscles":["wrists","hands"],"equipment":"body weight","difficulty":"beginner","description":"The side wrist pull stretch is a bodyweight exercise that targets the forearms and helps improve flexibility and mobility in the wrists and hands. It is performed by extending one arm to the side and gently pulling the hand towards the body with the opposite hand, creating a stretch in the forearm.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0721.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and your arms extended in front of you.","Extend your right arm out to the side, parallel to the ground, with your palm facing down.","With your left hand, grab your right hand and gently pull it towards your body, feeling a stretch in your right forearm.","Hold the stretch for 15-30 seconds, then release.","Repeat on the other side."]},{"id":"725","name":"single arm push-up","body_part":"chest","target":"pectorals","secondary_muscles":["triceps","shoulders","core"],"equipment":"body weight","difficulty":"advanced","description":"The single arm push-up is a challenging bodyweight exercise that targets the pectorals while also engaging the triceps, shoulders, and core. It requires significant strength, balance, and coordination, making it suitable for advanced practitioners.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0725.gif","youtube_id":null,"instructions":["Start in a push-up position with your hands shoulder-width apart and one hand placed slightly wider than the other.","Engage your core and lower your body towards the ground by bending your elbows, keeping your back straight.","As you lower yourself, shift your weight to one side and lift the opposite arm off the ground, extending it straight out to the side.","Push through your chest and triceps to raise your body back up to the starting position, while simultaneously lowering your extended arm back to the ground.","Repeat the movement, alternating the arm you extend with each repetition."]},{"id":"727","name":"single leg calf raise (on a dumbbell)","body_part":"lower legs","target":"calves","secondary_muscles":["ankles","feet"],"equipment":"dumbbell","difficulty":"intermediate","description":"The single leg calf raise (on a dumbbell) is a lower leg exercise that targets the calves, with secondary emphasis on the ankles and feet. It involves balancing on one leg while holding a dumbbell and performing a calf raise, which increases the challenge to balance and strength.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0727.gif","youtube_id":null,"instructions":["Stand with your feet hip-width apart and hold a dumbbell in one hand.","Lift one foot off the ground and balance on the other foot.","Slowly raise your heel as high as possible, using your calf muscles.","Pause for a moment at the top, then slowly lower your heel back down.","Repeat for the desired number of repetitions, then switch to the other leg."]},{"id":"73","name":"barbell pullover","body_part":"back","target":"lats","secondary_muscles":["chest","triceps"],"equipment":"barbell","difficulty":"intermediate","description":"The barbell pullover is a strength exercise that targets the latissimus dorsi (lats) and also engages the chest and triceps. It involves lying on a bench and moving a barbell in an arc from above the chest to behind the head, emphasizing a stretch and contraction of the upper body muscles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0073.gif","youtube_id":null,"instructions":["Lie flat on a bench with your head at one end and your feet on the floor.","Hold a barbell with a shoulder-width grip and extend your arms straight above your chest.","Keeping your arms straight, lower the barbell behind your head in a controlled manner until you feel a stretch in your lats.","Pause for a moment, then raise the barbell back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"730","name":"single leg platform slide","body_part":"upper legs","target":"hamstrings","secondary_muscles":["glutes","quadriceps"],"equipment":"body weight","difficulty":"intermediate","description":"The single leg platform slide is a bodyweight exercise targeting the hamstrings, with secondary emphasis on the glutes and quadriceps. It involves sliding one foot backward on a platform while maintaining balance and core engagement.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0730.gif","youtube_id":null,"instructions":["Start by standing with one foot on a platform or slide board.","Bend your knee slightly and slide the foot on the platform backward, extending your leg.","Keep your core engaged and maintain a straight posture throughout the movement.","Slowly return to the starting position by sliding your foot back to the initial position.","Repeat the movement for the desired number of repetitions, then switch legs."]},{"id":"735","name":"sit-up v. 2","body_part":"waist","target":"abs","secondary_muscles":["hip flexors"],"equipment":"body weight","difficulty":"beginner","description":"The sit-up v. 2 is a bodyweight abdominal exercise that targets the abs and also engages the hip flexors. It involves curling the torso up from a lying position to a 45-degree angle, then lowering back down.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0735.gif","youtube_id":null,"instructions":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"738","name":"sled 45° calf press","body_part":"lower legs","target":"calves","secondary_muscles":["hamstrings"],"equipment":"sled machine","difficulty":"beginner","description":"The sled 45° calf press is a machine-based exercise that targets the calves by pressing a weighted sled away using the balls of your feet, focusing on ankle extension.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0738.gif","youtube_id":null,"instructions":["Adjust the sled machine to a 45-degree angle.","Place your feet on the sled platform with your toes pointing forward.","Push the sled platform away from you by extending your ankles and calves.","Pause for a moment at the top, then slowly lower the sled platform back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"739","name":"sled 45° leg press","body_part":"upper legs","target":"glutes","secondary_muscles":["quadriceps","hamstrings","calves"],"equipment":"sled machine","difficulty":"beginner","description":"The sled 45° leg press is a compound lower body exercise performed on a sled machine. It primarily targets the glutes, with secondary emphasis on the quadriceps, hamstrings, and calves. The exercise involves pushing a weighted footplate away from the body while seated at a 45-degree angle, making it a popular choice for building lower body strength.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0739.gif","youtube_id":null,"instructions":["Adjust the seat and footplate of the sled machine to a comfortable position.","Sit on the sled machine with your back against the backrest and your feet shoulder-width apart on the footplate.","Grip the handles on the sides of the seat for stability.","Push the footplate away from your body by extending your legs, keeping your heels on the footplate.","Continue pushing until your legs are almost fully extended, but without locking your knees.","Pause for a moment at the top of the movement, then slowly lower the footplate back towards your body by bending your knees.","Repeat for the desired number of repetitions."]},{"id":"74","name":"barbell rack pull","body_part":"upper legs","target":"glutes","secondary_muscles":["hamstrings","lower back"],"equipment":"barbell","difficulty":"intermediate","description":"The barbell rack pull is a compound strength exercise that targets the glutes, hamstrings, and lower back. It involves lifting a barbell from a rack set at knee height, focusing on hip extension and posterior chain activation.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0074.gif","youtube_id":null,"instructions":["Set up a barbell on a rack at knee height.","Stand with your feet shoulder-width apart, toes pointing slightly outwards.","Bend at the hips and knees to lower yourself down and grip the barbell with an overhand grip, hands shoulder-width apart.","Engage your core and lift the barbell by extending your hips and knees, pulling your shoulders back and squeezing your glutes at the top.","Lower the barbell back down to the starting position by bending at the hips and knees.","Repeat for the desired number of repetitions."]},{"id":"740","name":"sled 45° leg wide press","body_part":"upper legs","target":"glutes","secondary_muscles":["quadriceps","hamstrings","calves"],"equipment":"sled machine","difficulty":"beginner","description":"The sled 45° leg wide press is a compound lower body exercise performed on a sled machine set at a 45-degree angle. It targets the glutes primarily, with significant involvement from the quadriceps, hamstrings, and calves. The wide stance emphasizes the glutes and inner thighs more than a standard leg press.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0740.gif","youtube_id":null,"instructions":["Adjust the sled machine to a 45-degree angle.","Sit on the sled machine with your back against the pad and your feet on the foot platform.","Position your feet wider than shoulder-width apart.","Push against the foot platform to extend your legs and straighten your knees.","Pause for a moment at the end of the movement, then slowly bend your knees to return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"741","name":"sled closer hack squat","body_part":"upper legs","target":"glutes","secondary_muscles":["quadriceps","hamstrings","calves"],"equipment":"sled machine","difficulty":"intermediate","description":"The sled closer hack squat is a lower body exercise performed on a sled machine, primarily targeting the glutes while also engaging the quadriceps, hamstrings, and calves. It involves squatting with your back against a pad and feet on a platform, moving the weight by extending and flexing the knees and hips.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0741.gif","youtube_id":null,"instructions":["Adjust the sled machine to a comfortable weight and position yourself with your back against the pad.","Place your feet shoulder-width apart on the platform, toes slightly pointed outwards.","Grip the handles on the sides of the machine for stability.","Engage your core and slowly lower your body by bending your knees and hips, keeping your back straight.","Continue lowering until your thighs are parallel to the ground or slightly below.","Pause for a moment at the bottom, then push through your heels to extend your legs and return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"742","name":"sled forward angled calf raise","body_part":"lower legs","target":"calves","secondary_muscles":["hamstrings","glutes"],"equipment":"sled machine","difficulty":"beginner","description":"The sled forward angled calf raise is a resistance exercise performed on a sled machine, targeting the calf muscles. The movement involves raising and lowering the heels while the toes remain on the platform, using the sled machine for added resistance.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0742.gif","youtube_id":null,"instructions":["Adjust the sled machine to a comfortable weight and position yourself on the machine with your toes on the platform and your heels hanging off.","Place your hands on the handles or the sides of the machine for support.","Engage your calves and slowly raise your heels as high as possible, pushing against the resistance of the sled.","Pause for a moment at the top of the movement, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"743","name":"sled hack squat","body_part":"upper legs","target":"glutes","secondary_muscles":["quadriceps","hamstrings","calves"],"equipment":"sled machine","difficulty":"intermediate","description":"The sled hack squat is a lower body strength exercise performed on a sled machine. It primarily targets the glutes, with secondary emphasis on the quadriceps, hamstrings, and calves. The movement involves squatting down with the support of the sled machine, which helps guide the motion and provides stability.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0743.gif","youtube_id":null,"instructions":["Adjust the sled machine to a comfortable position for your height.","Stand with your feet shoulder-width apart on the platform, toes slightly pointed outwards.","Hold onto the handles or bars for stability.","Lower your body by bending your knees and hips, keeping your back straight and chest up.","Continue lowering until your thighs are parallel to the ground or slightly below.","Pause for a moment, then push through your heels to raise your body back up to the starting position.","Repeat for the desired number of repetitions."]},{"id":"744","name":"sled lying squat","body_part":"upper legs","target":"glutes","secondary_muscles":["quadriceps","hamstrings","calves"],"equipment":"sled machine","difficulty":"beginner","description":"The sled lying squat is a lower body exercise performed on a sled machine, targeting the glutes as the primary muscle group. It also engages the quadriceps, hamstrings, and calves. The movement involves lying on your back, pushing the sled upward with your legs, and then lowering it back down in a controlled manner.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0744.gif","youtube_id":null,"instructions":["Adjust the sled machine to a comfortable weight.","Lie on your back on the sled machine with your feet on the footplate.","Position your feet shoulder-width apart and slightly angled outwards.","Grip the handles of the sled machine for stability.","Engage your glutes and core muscles.","Push through your heels and extend your legs to lift the sled.","Lower the sled back down by bending your knees and hips.","Repeat for the desired number of repetitions."]},{"id":"746","name":"smith back shrug","body_part":"back","target":"traps","secondary_muscles":["shoulders"],"equipment":"smith machine","difficulty":"beginner","description":"The smith back shrug is a strength exercise targeting the trapezius muscles, performed using a smith machine. It involves lifting the shoulders straight up towards the ears while holding a barbell, focusing on squeezing the traps at the top of the movement.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0746.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and your knees slightly bent.","Grasp the barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Keep your arms straight and allow the barbell to hang in front of your thighs.","Lift your shoulders straight up towards your ears, squeezing your traps at the top.","Hold for a moment, then lower your shoulders back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"747","name":"smith behind neck press","body_part":"shoulders","target":"delts","secondary_muscles":["triceps","upper back"],"equipment":"smith machine","difficulty":"advanced","description":"The smith behind neck press is a shoulder exercise performed on a smith machine, targeting the deltoids with secondary emphasis on the triceps and upper back. The movement involves pressing a barbell from behind the neck to overhead, requiring good shoulder mobility and stability.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0747.gif","youtube_id":null,"instructions":["Adjust the seat height of the smith machine so that the bar is at shoulder level.","Stand with your feet shoulder-width apart and your knees slightly bent.","Grasp the bar with an overhand grip, slightly wider than shoulder-width apart.","Lift the bar off the rack and step back, maintaining a stable stance.","Lower the bar down to the back of your neck, keeping your elbows pointing forward.","Press the bar up overhead until your arms are fully extended.","Pause for a moment at the top, then slowly lower the bar back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"748","name":"smith bench press","body_part":"chest","target":"pectorals","secondary_muscles":["triceps","shoulders"],"equipment":"smith machine","difficulty":"beginner","description":"The smith bench press is a chest exercise performed on a smith machine, which provides a guided bar path for pressing movements. It primarily targets the pectorals, with secondary emphasis on the triceps and shoulders. The smith machine offers additional stability compared to a free-weight bench press, making it accessible for those with less experience or those seeking a safer alternative to heavy pressing.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0748.gif","youtube_id":null,"instructions":["Adjust the height of the smith machine bar to chest level.","Lie flat on the bench with your feet firmly planted on the ground.","Grip the bar with an overhand grip slightly wider than shoulder-width apart.","Unrack the bar and lower it towards your chest, keeping your elbows tucked in.","Pause for a moment when the bar touches your chest.","Push the bar back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]},{"id":"749","name":"smith bent knee good morning","body_part":"upper legs","target":"glutes","secondary_muscles":["hamstrings","lower back"],"equipment":"smith machine","difficulty":"intermediate","description":"The smith bent knee good morning is a lower body exercise performed on a Smith machine. It primarily targets the glutes, with secondary emphasis on the hamstrings and lower back. The movement involves hinging at the hips with a slight knee bend, lowering the torso while keeping the back straight, and then returning to the starting position.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0749.gif","youtube_id":null,"instructions":["Start by standing with your feet shoulder-width apart, toes pointing forward.","Place the barbell across your upper back, resting it on your traps.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Lower your torso until it is parallel to the ground, feeling a stretch in your hamstrings.","Engage your glutes and hamstrings to raise your torso back up to the starting position.","Repeat for the desired number of repetitions."]},{"id":"75","name":"barbell rear delt raise","body_part":"shoulders","target":"delts","secondary_muscles":["traps","rhomboids"],"equipment":"barbell","difficulty":"intermediate","description":"The barbell rear delt raise is an isolation exercise targeting the rear deltoids, with secondary emphasis on the traps and rhomboids. It is performed by hinging at the hips and raising a barbell out to the sides, focusing on shoulder movement.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0075.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, palms facing down.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Raise the barbell out to the sides, keeping your arms straight, until they are parallel to the ground.","Pause for a moment at the top, then slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"750","name":"smith chair squat","body_part":"upper legs","target":"quads","secondary_muscles":["glutes","hamstrings","calves"],"equipment":"smith machine","difficulty":"beginner","description":"The smith chair squat is a lower body exercise performed using a smith machine. It primarily targets the quadriceps, with secondary emphasis on the glutes, hamstrings, and calves. The guided bar path of the smith machine provides stability, making it suitable for those developing squat technique or seeking a safer alternative to free-weight squats.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0750.gif","youtube_id":null,"instructions":["Adjust the height of the smith machine bar to a comfortable position.","Stand with your feet shoulder-width apart, toes slightly turned out.","Place the barbell across your upper back, resting it on your traps.","Engage your core and keep your chest up as you slowly lower your body by bending your knees and hips.","Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.","Pause for a moment, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"751","name":"smith close-grip bench press","body_part":"upper arms","target":"triceps","secondary_muscles":["chest","shoulders"],"equipment":"smith machine","difficulty":"intermediate","description":"The smith close-grip bench press is a compound exercise performed on a smith machine, targeting the triceps with secondary emphasis on the chest and shoulders. It involves pressing a barbell with a close grip, which increases triceps activation.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0751.gif","youtube_id":null,"instructions":["Adjust the seat height and position yourself on the bench with your feet flat on the ground.","Grasp the barbell with a close grip, slightly narrower than shoulder-width apart.","Lower the barbell towards your chest, keeping your elbows close to your body.","Pause for a moment at the bottom, then push the barbell back up to the starting position.","Repeat for the desired number of repetitions."]},{"id":"752","name":"smith deadlift","body_part":"upper legs","target":"glutes","secondary_muscles":["hamstrings","quadriceps","lower back"],"equipment":"smith machine","difficulty":"beginner","description":"The smith deadlift is a compound lower body exercise performed using a smith machine. It primarily targets the glutes, with secondary emphasis on the hamstrings, quadriceps, and lower back. The smith machine provides a guided bar path, which can help with stability and form for those learning the deadlift movement.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0752.gif","youtube_id":null,"instructions":["Set up the smith machine with the bar at hip height.","Stand with your feet shoulder-width apart, toes pointing slightly outward.","Bend at the hips and knees, keeping your back straight and chest up, and grip the bar with an overhand grip slightly wider than shoulder-width apart.","Engage your core and lift the bar by extending your hips and knees, keeping the bar close to your body.","Stand up straight, fully extending your hips and knees.","Lower the bar back down by bending at the hips and knees, maintaining control and keeping your back straight.","Repeat for the desired number of repetitions."]},{"id":"753","name":"smith decline bench press","body_part":"chest","target":"pectorals","secondary_muscles":["triceps","shoulders"],"equipment":"smith machine","difficulty":"intermediate","description":"The smith decline bench press is a chest exercise performed on a decline bench using a smith machine. It primarily targets the pectoral muscles, with secondary emphasis on the triceps and shoulders. The smith machine provides guided movement, making it safer and more stable than a free-weight decline bench press.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0753.gif","youtube_id":null,"instructions":["Adjust the decline bench to the desired angle.","Lie down on the bench with your feet secured under the foot pads.","Grasp the barbell with an overhand grip slightly wider than shoulder-width apart.","Unrack the barbell and lower it slowly towards your chest, keeping your elbows tucked in.","Pause for a moment at the bottom, then push the barbell back up to the starting position.","Repeat for the desired number of repetitions."]},{"id":"754","name":"smith decline reverse-grip press","body_part":"chest","target":"pectorals","secondary_muscles":["triceps","shoulders"],"equipment":"smith machine","difficulty":"intermediate","description":"The smith decline reverse-grip press is a chest exercise performed on a smith machine in a decline position, using a reverse (underhand) grip to target the lower pectorals and engage the triceps and shoulders.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0754.gif","youtube_id":null,"instructions":["Adjust the smith machine to a decline position.","Lie down on the bench with your feet secured under the foot pads.","Grasp the barbell with a reverse grip, hands slightly wider than shoulder-width apart.","Unrack the barbell and lower it towards your chest, keeping your elbows tucked in.","Pause for a moment at the bottom, then push the barbell back up to the starting position.","Repeat for the desired number of repetitions."]},{"id":"755","name":"smith hack squat","body_part":"upper legs","target":"glutes","secondary_muscles":["quadriceps","hamstrings","calves"],"equipment":"smith machine","difficulty":"intermediate","description":"The smith hack squat is a lower body exercise performed on a smith machine, targeting the glutes as the primary muscle group, with secondary emphasis on the quadriceps, hamstrings, and calves. It involves squatting with the barbell resting on the upper traps and shoulders, providing stability and support for the movement.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0755.gif","youtube_id":null,"instructions":["Adjust the barbell on the smith machine to an appropriate height for your body.","Stand with your feet shoulder-width apart, toes slightly pointed outwards.","Position yourself under the barbell, resting it on your upper traps and shoulders.","Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.","Engage your core and keep your chest up as you unrack the barbell.","Take a step back and position your feet slightly wider than shoulder-width apart.","Bend your knees and lower your body down, keeping your chest up and back straight.","Continue descending until your thighs are parallel to the ground or slightly below.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"756","name":"smith hip raise","body_part":"waist","target":"abs","secondary_muscles":["glutes","hamstrings"],"equipment":"smith machine","difficulty":"intermediate","description":"The smith hip raise is an exercise performed on a smith machine that primarily targets the abdominal muscles, with secondary emphasis on the glutes and hamstrings. It involves raising the hips off the ground while keeping the body aligned, engaging the core and lower body.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0756.gif","youtube_id":null,"instructions":["Position yourself on the smith machine with your back against the pad and your feet shoulder-width apart.","Place your hands on the barbell, slightly wider than shoulder-width apart.","Engage your core and glutes, then push through your heels to raise your hips off the ground.","Continue lifting until your body forms a straight line from your knees to your shoulders.","Hold for a moment at the top, then slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"757","name":"smith incline bench press","body_part":"chest","target":"pectorals","secondary_muscles":["shoulders","triceps"],"equipment":"smith machine","difficulty":"beginner","description":"The smith incline bench press is a chest exercise performed on a smith machine with the bench set at a 30-45 degree incline. It primarily targets the upper pectorals, with secondary emphasis on the shoulders and triceps. The smith machine provides stability, making it accessible for those with less experience, but still requires proper form and control.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0757.gif","youtube_id":null,"instructions":["Adjust the bench to a 30-45 degree incline.","Sit on the bench with your back flat against the pad and feet firmly on the ground.","Grasp the barbell with an overhand grip slightly wider than shoulder-width apart.","Unrack the barbell and lower it slowly towards your upper chest, keeping your elbows slightly tucked in.","Pause for a moment at the bottom, then push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]},{"id":"758","name":"smith incline reverse-grip press","body_part":"chest","target":"pectorals","secondary_muscles":["triceps","shoulders"],"equipment":"smith machine","difficulty":"intermediate","description":"The smith incline reverse-grip press is a chest exercise performed on a smith machine with an incline bench. It targets the pectoral muscles using a reverse (underhand) grip, which also engages the triceps and shoulders. The smith machine provides stability, but the reverse grip and incline angle require good coordination and some experience.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0758.gif","youtube_id":null,"instructions":["Adjust the seat of the smith machine to a comfortable incline angle.","Sit on the machine with your back against the pad and your feet flat on the ground.","Grasp the bar with an overhand grip that is slightly wider than shoulder-width apart.","Unrack the bar and lower it slowly towards your chest, keeping your elbows tucked in.","Pause for a moment when the bar is just above your chest.","Push the bar back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]},{"id":"759","name":"smith incline shoulder raises","body_part":"chest","target":"serratus anterior","secondary_muscles":["deltoids","trapezius"],"equipment":"smith machine","difficulty":"intermediate","description":"Smith incline shoulder raises target the serratus anterior and are performed on a smith machine. The movement involves raising the barbell upwards while standing at an incline, focusing on shoulder and upper chest engagement.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0759.gif","youtube_id":null,"instructions":["Adjust the smith machine to an incline position.","Stand facing the machine with your feet shoulder-width apart.","Grasp the bar with an overhand grip, slightly wider than shoulder-width apart.","Keep your back straight and core engaged.","Raise the barbell up towards the ceiling, leading with your elbows.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"76","name":"barbell rear delt row","body_part":"shoulders","target":"delts","secondary_muscles":["trapezius","rhomboids","biceps"],"equipment":"barbell","difficulty":"intermediate","description":"The barbell rear delt row is a compound exercise targeting the rear deltoids, with secondary emphasis on the trapezius, rhomboids, and biceps. It involves pulling a barbell towards the chest while bent over, focusing on squeezing the shoulder blades together to engage the upper back and rear shoulders.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0076.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and knees slightly bent.","Hold a barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Bend forward at the hips, keeping your back straight and chest up.","Pull the barbell towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"760","name":"smith leg press","body_part":"upper legs","target":"glutes","secondary_muscles":["quadriceps","hamstrings","calves"],"equipment":"smith machine","difficulty":"beginner","description":"The smith leg press is a lower body exercise performed on a smith machine, targeting the glutes with secondary emphasis on the quadriceps, hamstrings, and calves. It involves pressing a footplate away from the body while seated, using the legs to extend and flex at the knees and hips.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0760.gif","youtube_id":null,"instructions":["Adjust the seat and footplate of the smith machine to a comfortable position.","Sit on the machine with your back against the backrest and your feet shoulder-width apart on the footplate.","Grasp the handles or sides of the machine for stability.","Push the footplate away from you by extending your legs, keeping your back against the backrest.","Pause for a moment at the fully extended position.","Slowly bend your knees and lower the footplate back towards you, returning to the starting position.","Repeat for the desired number of repetitions."]},{"id":"761","name":"smith narrow row","body_part":"back","target":"upper back","secondary_muscles":["biceps","rear deltoids"],"equipment":"smith machine","difficulty":"beginner","description":"The smith narrow row is a machine-based rowing exercise targeting the upper back, performed with a narrow grip to emphasize the upper back muscles and rear deltoids. It is performed on a Smith machine, which provides guided movement for added stability.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0761.gif","youtube_id":null,"instructions":["Adjust the seat height and position yourself on the machine with your feet flat on the floor.","Grasp the handles with an overhand grip, slightly narrower than shoulder-width apart.","Keep your back straight and your chest up as you pull the handles towards your body, squeezing your shoulder blades together.","Pause for a moment at the peak of the movement, then slowly release the handles back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"762","name":"smith rear delt row","body_part":"shoulders","target":"delts","secondary_muscles":["trapezius","rhomboids","biceps"],"equipment":"smith machine","difficulty":"beginner","description":"The smith rear delt row is a machine-based exercise targeting the rear deltoids, with secondary emphasis on the trapezius, rhomboids, and biceps. It involves pulling a bar towards your chest while keeping your chest against a pad, focusing on squeezing the shoulder blades together.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0762.gif","youtube_id":null,"instructions":["Adjust the seat height and position yourself on the machine with your chest against the pad and your feet flat on the ground.","Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.","Keep your back straight and your core engaged as you pull the handles towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top of the movement, then slowly release the handles back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"763","name":"smith reverse calf raises","body_part":"lower legs","target":"calves","secondary_muscles":["hamstrings"],"equipment":"smith machine","difficulty":"beginner","description":"The smith reverse calf raises is a lower leg exercise performed on a smith machine, primarily targeting the calves and secondarily engaging the hamstrings. The movement involves raising and lowering the heels while standing on a step, using the smith machine bar for support.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0763.gif","youtube_id":null,"instructions":["Adjust the smith machine bar to a height just below your shoulders.","Stand facing the bar with your feet hip-width apart and toes pointing forward.","Place the balls of your feet on the edge of a step or platform, with your heels hanging off.","Hold onto the bar for support, keeping your back straight and core engaged.","Raise your heels as high as possible, lifting your body weight onto the balls of your feet.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"764","name":"smith reverse-grip press","body_part":"chest","target":"pectorals","secondary_muscles":["triceps","shoulders"],"equipment":"smith machine","difficulty":"intermediate","description":"The smith reverse-grip press is a chest exercise performed on a smith machine using a reverse (underhand) grip. This variation targets the upper chest and also engages the triceps and shoulders. The smith machine provides stability, making it suitable for those looking to focus on form and muscle activation.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0764.gif","youtube_id":null,"instructions":["Adjust the height of the smith machine bar to chest level.","Stand facing the bar with your feet shoulder-width apart.","Grasp the bar with an overhand grip, hands slightly wider than shoulder-width apart.","Step back and position yourself with a slight bend in your knees.","Keep your chest up and core engaged throughout the exercise.","Lower the bar towards your chest, keeping your elbows tucked in.","Pause for a moment at the bottom, then push the bar back up to the starting position.","Repeat for the desired number of repetitions."]},{"id":"765","name":"smith seated shoulder press","body_part":"shoulders","target":"delts","secondary_muscles":["triceps","upper back"],"equipment":"smith machine","difficulty":"beginner","description":"The smith seated shoulder press is a machine-based exercise targeting the deltoid muscles of the shoulders. It provides stability and support, making it suitable for those looking to build shoulder strength with reduced risk of losing balance. The movement also engages the triceps and upper back as secondary muscles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0765.gif","youtube_id":null,"instructions":["Adjust the seat height so that the handles are at shoulder level.","Sit on the machine with your back against the pad and your feet flat on the floor.","Grasp the handles with an overhand grip and lift them off the supports, extending your arms fully.","Lower the handles down to shoulder level, keeping your elbows slightly bent.","Press the handles up overhead until your arms are fully extended.","Pause for a moment at the top, then slowly lower the handles back down to shoulder level.","Repeat for the desired number of repetitions."]},{"id":"766","name":"smith shoulder press","body_part":"shoulders","target":"delts","secondary_muscles":["triceps","upper back"],"equipment":"smith machine","difficulty":"beginner","description":"The smith shoulder press is a compound exercise performed on a smith machine that targets the deltoid muscles of the shoulders. It provides stability for the lifter, making it easier to focus on pressing strength and muscle development.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0766.gif","youtube_id":null,"instructions":["Adjust the seat height and position yourself on the smith machine with your feet shoulder-width apart.","Grasp the bar with an overhand grip, slightly wider than shoulder-width apart.","Lift the bar off the rack and position it at shoulder level, with your elbows bent and palms facing forward.","Press the bar upward until your arms are fully extended overhead.","Pause for a moment at the top, then slowly lower the bar back down to shoulder level.","Repeat for the desired number of repetitions."]},{"id":"767","name":"smith shrug","body_part":"back","target":"traps","secondary_muscles":["shoulders"],"equipment":"smith machine","difficulty":"beginner","description":"The smith shrug is an exercise performed on a Smith machine to target the trapezius muscles. It involves lifting the shoulders towards the ears while holding a barbell, focusing on squeezing the traps at the top of the movement.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0767.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and your knees slightly bent.","Grasp the barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Keep your arms straight and your shoulders relaxed.","Lift your shoulders up towards your ears, squeezing your traps at the top.","Hold for a moment, then slowly lower your shoulders back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"768","name":"smith single leg split squat","body_part":"upper legs","target":"quads","secondary_muscles":["glutes","hamstrings"],"equipment":"smith machine","difficulty":"intermediate","description":"The smith single leg split squat is a lower body exercise performed using a smith machine. It targets the quadriceps while also engaging the glutes and hamstrings. The exercise requires balance and unilateral strength, as one leg is elevated behind you on a bench or step.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0768.gif","youtube_id":null,"instructions":["Stand in front of the smith machine with your feet shoulder-width apart.","Place one foot behind you on a bench or step, with your toes pointing forward.","Hold onto the smith machine bar for stability.","Bend your front knee and lower your body down into a lunge position, keeping your back straight.","Pause for a moment at the bottom, then push through your front heel to return to the starting position.","Repeat for the desired number of repetitions, then switch legs."]},{"id":"769","name":"smith sprint lunge","body_part":"upper legs","target":"glutes","secondary_muscles":["quadriceps","hamstrings","calves"],"equipment":"smith machine","difficulty":"advanced","description":"The smith sprint lunge is a lower body exercise performed using a smith machine. It targets the glutes primarily, with secondary emphasis on the quadriceps, hamstrings, and calves. The movement involves stepping back and placing one foot on the barbell, then performing a lunge, which challenges balance, strength, and coordination.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0769.gif","youtube_id":null,"instructions":["Set up the smith machine with the barbell at hip height.","Stand facing away from the machine with your feet shoulder-width apart.","Step back with your right foot and place it on the barbell, resting the top of your foot on the bar.","Bend your left knee and lower your body into a lunge position, keeping your back straight.","Push through your left heel to return to the starting position.","Repeat on the other side, stepping back with your left foot.","Continue alternating sides for the desired number of repetitions."]},{"id":"77","name":"barbell rear lunge v. 2","body_part":"upper legs","target":"glutes","secondary_muscles":["quadriceps","hamstrings","calves"],"equipment":"barbell","difficulty":"intermediate","description":"The barbell rear lunge v. 2 is a lower body exercise that targets the glutes and also engages the quadriceps, hamstrings, and calves. It involves stepping backward into a lunge position while holding a barbell across your upper back, then returning to the starting position.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0077.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and hold a barbell across your upper back.","Take a step backward with your right foot, landing on the ball of your foot.","Bend both knees to lower your body until your left thigh is parallel to the ground.","Push through your left heel to return to the starting position.","Repeat with the other leg."]},{"id":"770","name":"smith squat","body_part":"upper legs","target":"glutes","secondary_muscles":["quadriceps","hamstrings","calves"],"equipment":"smith machine","difficulty":"beginner","description":"The smith squat is a lower body exercise performed using a smith machine. It primarily targets the glutes, with secondary emphasis on the quadriceps, hamstrings, and calves. The guided bar path of the smith machine provides stability, making it suitable for those learning proper squat form or looking to focus on muscle activation without balancing a free barbell.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0770.gif","youtube_id":null,"instructions":["Set up the smith machine with the barbell at an appropriate height for your squat.","Stand with your feet shoulder-width apart, toes slightly turned out.","Position yourself under the barbell, resting it on your upper traps and shoulders.","Grip the barbell with a wide grip, slightly wider than shoulder-width apart.","Engage your core and unrack the barbell, stepping back to clear the rack.","Keeping your chest up and back straight, initiate the squat by bending at the hips and knees.","Lower your body until your thighs are parallel to the ground or slightly below.","Pause for a moment at the bottom, then drive through your heels to return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"771","name":"smith standing back wrist curl","body_part":"lower arms","target":"forearms","secondary_muscles":["biceps","triceps"],"equipment":"smith machine","difficulty":"beginner","description":"The smith standing back wrist curl is an isolation exercise targeting the forearms, performed using a smith machine. It involves curling the wrists upwards while holding the barbell with an overhand grip, focusing on forearm strength.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0771.gif","youtube_id":null,"instructions":["Stand facing the smith machine with your feet shoulder-width apart.","Grasp the barbell with an overhand grip, hands shoulder-width apart.","Keep your back straight and your elbows close to your body.","Slowly curl your wrists upwards, bringing the barbell towards your body.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"772","name":"smith standing behind head military press","body_part":"shoulders","target":"delts","secondary_muscles":["triceps","upper back"],"equipment":"smith machine","difficulty":"advanced","description":"The smith standing behind head military press is a shoulder exercise performed using a smith machine. The movement targets the deltoids and involves pressing a barbell from behind the head to overhead while standing.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0772.gif","youtube_id":null,"instructions":["Adjust the seat height of the smith machine so that the bar is at shoulder level.","Stand with your feet shoulder-width apart and your knees slightly bent.","Grasp the bar with an overhand grip, slightly wider than shoulder-width apart.","Lift the bar off the rack and step back, maintaining a stable stance.","Position the bar behind your head, resting on your upper traps.","Keep your core engaged and your chest lifted throughout the exercise.","Press the bar overhead by extending your arms, fully straightening them.","Pause briefly at the top of the movement, then slowly lower the bar back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"773","name":"smith standing leg calf raise","body_part":"lower legs","target":"calves","secondary_muscles":["hamstrings","glutes"],"equipment":"smith machine","difficulty":"beginner","description":"The smith standing leg calf raise is a lower leg exercise performed using a smith machine. It primarily targets the calves, with secondary emphasis on the hamstrings and glutes. The movement involves raising the heels to stand on the toes, then lowering back down, using the smith machine for stability and added resistance.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0773.gif","youtube_id":null,"instructions":["Adjust the smith machine bar to a height that allows you to stand with your feet flat on the ground and your shoulders under the bar.","Position yourself under the bar with your feet shoulder-width apart and your toes pointing forward.","Place your hands on the bar for stability.","Engage your calves and slowly raise your heels off the ground, lifting your body up onto your toes.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"774","name":"smith standing military press","body_part":"shoulders","target":"delts","secondary_muscles":["triceps","upper back"],"equipment":"smith machine","difficulty":"intermediate","description":"The Smith standing military press is a compound exercise targeting the deltoid muscles of the shoulders, performed using a Smith machine for added stability. It also engages the triceps and upper back as secondary muscles. The fixed bar path of the Smith machine can make the movement more accessible for those learning the overhead press, but it still requires good shoulder mobility and core stability.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0774.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and your knees slightly bent.","Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.","Lift the barbell off the rack and bring it down to shoulder level, with your palms facing forward.","Press the barbell upward until your arms are fully extended overhead.","Pause for a moment at the top, then slowly lower the barbell back down to shoulder level.","Repeat for the desired number of repetitions."]},{"id":"775","name":"smith upright row","body_part":"shoulders","target":"delts","secondary_muscles":["traps","biceps"],"equipment":"smith machine","difficulty":"intermediate","description":"The smith upright row is a shoulder exercise performed on a smith machine, targeting the deltoids and also engaging the traps and biceps. It involves pulling a barbell upwards towards the chin while keeping the elbows higher than the wrists.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0775.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, facing the smith machine.","Grasp the barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Keep your back straight and your core engaged.","Pull the barbell up towards your chin, leading with your elbows.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"776","name":"snatch pull","body_part":"upper legs","target":"quads","secondary_muscles":["hamstrings","glutes","calves"],"equipment":"barbell","difficulty":"advanced","description":"The snatch pull is a compound Olympic weightlifting movement that develops explosive power and strength in the lower body, particularly targeting the quads, hamstrings, and glutes. It requires coordination, balance, and proper technique to perform safely and effectively.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0776.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and the barbell on the ground in front of you.","Bend your knees and hinge at the hips to lower into a squat position, gripping the barbell with an overhand grip.","Keep your back straight and chest up as you drive through your heels to lift the barbell off the ground, extending your hips and knees.","As the barbell reaches hip level, explosively pull it upwards, shrugging your shoulders and pulling your elbows high and to the sides.","As the barbell reaches its highest point, quickly drop underneath it, pulling yourself into a deep squat position.","Catch the barbell overhead with your arms fully extended and your knees bent.","Stand up by extending your hips and knees, keeping the barbell overhead.","Lower the barbell back down to the starting position by reversing the movement.","Repeat for the desired number of repetitions."]},{"id":"777","name":"spell caster","body_part":"waist","target":"abs","secondary_muscles":["obliques","lower back"],"equipment":"dumbbell","difficulty":"beginner","description":"The spell caster is a rotational core exercise performed with a dumbbell, targeting the abs and obliques. It involves hinging at the waist and rotating the torso while moving the dumbbell from side to side.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0777.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and hold a dumbbell in one hand.","Bend your knees slightly and hinge forward at the waist, keeping your back straight.","Extend your arm with the dumbbell towards the opposite foot, rotating your torso as you do so.","Return to the starting position and repeat on the other side.","Continue alternating sides for the desired number of repetitions."]},{"id":"778","name":"spider crawl push up","body_part":"upper legs","target":"glutes","secondary_muscles":["core","chest","shoulders"],"equipment":"body weight","difficulty":"advanced","description":"The spider crawl push up is a challenging bodyweight exercise that combines a push-up with a dynamic knee drive, targeting the glutes, core, chest, and shoulders. It requires coordination, strength, and stability.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0778.gif","youtube_id":null,"instructions":["Start in a push-up position with your hands slightly wider than shoulder-width apart and your feet together.","Bring your right knee towards your right elbow, keeping it off the ground.","As you bring your right knee back, simultaneously lower your body towards the ground by bending your elbows.","Push back up to the starting position and repeat with your left knee towards your left elbow.","Continue alternating sides for the desired number of repetitions."]},{"id":"78","name":"barbell rear lunge","body_part":"upper legs","target":"glutes","secondary_muscles":["quadriceps","hamstrings","calves"],"equipment":"barbell","difficulty":"intermediate","description":"The barbell rear lunge is a compound lower body exercise that targets the glutes, with secondary emphasis on the quadriceps, hamstrings, and calves. It involves stepping backward into a lunge position while supporting a barbell on the upper back, requiring balance, coordination, and strength.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0078.gif","youtube_id":null,"instructions":["Start by standing with your feet shoulder-width apart and a barbell resting on your upper back.","Take a step backward with your right foot, landing on the ball of your foot.","Bend both knees to lower your body until your left thigh is parallel to the ground.","Push through your left heel to return to the starting position.","Repeat with the other leg."]},{"id":"786","name":"squat jerk","body_part":"upper legs","target":"quads","secondary_muscles":["glutes","hamstrings","calves","core"],"equipment":"barbell","difficulty":"advanced","description":"The squat jerk is an advanced Olympic weightlifting movement that combines a squat and a jerk, requiring explosive power, coordination, and balance. It targets the quads primarily, with significant involvement from the glutes, hamstrings, calves, and core.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0786.gif","youtube_id":null,"instructions":["Start with the barbell resting on your shoulders, with your feet shoulder-width apart.","Lower your body into a squat position, keeping your chest up and your knees tracking over your toes.","As you reach the bottom of the squat, explosively drive through your legs and push the barbell overhead.","As the barbell reaches its peak, quickly drop into a split position, with one foot forward and one foot back.","Catch the barbell overhead with your arms fully extended and your back knee slightly touching the ground.","Stand up from the split position, bringing your feet back together.","Lower the barbell back to your shoulders and repeat for the desired number of repetitions."]},{"id":"788","name":"standing behind neck press","body_part":"shoulders","target":"delts","secondary_muscles":["triceps","upper back"],"equipment":"barbell","difficulty":"advanced","description":"The standing behind neck press is a barbell exercise targeting the deltoids, performed by pressing a barbell from behind the neck to overhead while standing. It also engages the triceps and upper back.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0788.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and hold the barbell behind your neck with an overhand grip.","Keep your back straight and core engaged.","Press the barbell overhead by extending your arms, fully extending your elbows.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"79","name":"barbell reverse wrist curl v. 2","body_part":"lower arms","target":"forearms","secondary_muscles":["biceps","brachialis"],"equipment":"barbell","difficulty":"beginner","description":"The barbell reverse wrist curl v. 2 is an isolation exercise that targets the forearms, specifically the extensor muscles. It is performed seated, with the forearms resting on the thighs and the wrists curling a barbell upward using an overhand grip.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0079.gif","youtube_id":null,"instructions":["Sit on a bench with your feet flat on the ground and your knees bent.","Hold a barbell with an overhand grip, palms facing down, and your hands shoulder-width apart.","Rest your forearms on your thighs, allowing your wrists to hang off the edge.","Keeping your forearms stationary, exhale and curl your wrists upward as far as possible.","Hold the contracted position for a brief pause, then inhale and slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"794","name":"standing lateral stretch","body_part":"back","target":"lats","secondary_muscles":["shoulders","obliques"],"equipment":"body weight","difficulty":"beginner","description":"The standing lateral stretch is a bodyweight exercise that targets the lats and stretches the sides of the torso. It also engages the shoulders and obliques. This movement is performed by standing with feet shoulder-width apart, extending the arms, and leaning to each side to stretch the lateral muscles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0794.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and your knees slightly bent.","Extend your arms straight out to the sides, parallel to the ground.","Slowly lean your upper body to one side, feeling a stretch in your side and lats.","Hold the stretch for 15-30 seconds.","Return to the starting position and repeat on the other side.","Repeat for the desired number of repetitions."]},{"id":"795","name":"standing single leg curl","body_part":"upper legs","target":"hamstrings","secondary_muscles":["glutes"],"equipment":"body weight","difficulty":"beginner","description":"The standing single leg curl is a bodyweight exercise targeting the hamstrings and glutes. It involves balancing on one leg while curling the opposite heel toward the glutes, emphasizing hamstring activation and single-leg stability.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0795.gif","youtube_id":null,"instructions":["Stand with your feet hip-width apart and your hands on your hips.","Shift your weight onto your left leg and lift your right foot off the ground, bending your knee.","Slowly curl your right heel towards your glutes, squeezing your hamstring.","Pause for a moment at the top, then slowly lower your right foot back down to the starting position.","Repeat for the desired number of repetitions, then switch legs."]},{"id":"796","name":"standing wheel rollerout","body_part":"waist","target":"abs","secondary_muscles":["lower back","shoulders"],"equipment":"wheel roller","difficulty":"advanced","description":"The standing wheel rollout is an advanced core exercise that primarily targets the abdominal muscles, while also engaging the lower back and shoulders. It requires significant core strength, balance, and control to perform safely and effectively.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0796.gif","youtube_id":null,"instructions":["Start by standing tall with your feet shoulder-width apart and the wheel roller in front of you.","Bend at your waist and slowly roll the wheel forward, keeping your back straight and your core engaged.","Continue rolling forward until you feel a stretch in your abs and your body is extended as far as possible.","Pause for a moment, then slowly roll the wheel back towards your body, returning to the starting position.","Repeat for the desired number of repetitions."]},{"id":"798","name":"stationary bike walk","body_part":"cardio","target":"cardiovascular system","secondary_muscles":["quadriceps","hamstrings","calves"],"equipment":"leverage machine","difficulty":"beginner","description":"The stationary bike walk is a cardiovascular exercise performed on a leverage machine (stationary bike). It primarily targets the cardiovascular system and also engages the quadriceps, hamstrings, and calves. The exercise involves pedaling at a steady pace, with the option to adjust resistance for increased intensity.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0798.gif","youtube_id":null,"instructions":["Adjust the seat height and position on the stationary bike to ensure proper alignment.","Place your feet on the pedals and secure them with the straps if available.","Start pedaling at a comfortable pace, keeping your back straight and core engaged.","Maintain a steady rhythm and increase the resistance level if desired.","Continue pedaling for the desired duration of your cardio workout.","Cool down by gradually reducing your pace and resistance level.","Stretch your leg muscles after the workout to prevent tightness and promote recovery."]},{"id":"80","name":"barbell reverse curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"barbell","difficulty":"beginner","description":"The barbell reverse curl is an exercise targeting the biceps and forearms, performed by curling a barbell with an overhand grip.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0080.gif","youtube_id":null,"instructions":["Stand up straight with your feet shoulder-width apart and hold a barbell with an overhand grip, palms facing down.","Keep your upper arms stationary and exhale as you curl the barbell upward, contracting your biceps.","Continue to raise the barbell until your biceps are fully contracted and the barbell is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale as you slowly lower the barbell back to the starting position, keeping your upper arms stationary.","Repeat for the desired number of repetitions."]},{"id":"803","name":"superman push-up","body_part":"chest","target":"pectorals","secondary_muscles":["core","shoulders"],"equipment":"body weight","difficulty":"advanced","description":"The superman push-up is a challenging bodyweight exercise that targets the pectorals while also engaging the core and shoulders. It involves alternating the extension of opposite arms and legs during the push-up, requiring significant balance, strength, and coordination.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0803.gif","youtube_id":null,"instructions":["Start in a high plank position with your hands slightly wider than shoulder-width apart and your feet together.","Engage your core and lower your body towards the ground, keeping your elbows close to your sides.","As you lower your body, simultaneously lift your right arm and left leg off the ground, extending them straight out.","Pause for a moment at the top, then lower your arm and leg back down while pushing yourself back up to the starting position.","Repeat the movement, this time lifting your left arm and right leg.","Continue alternating sides for the desired number of repetitions."]},{"id":"805","name":"suspended abdominal fallout","body_part":"waist","target":"abs","secondary_muscles":["obliques","hip flexors"],"equipment":"body weight","difficulty":"advanced","description":"The suspended abdominal fallout is a challenging core exercise performed with a suspension trainer. It targets the abs and also engages the obliques and hip flexors. The movement requires significant core strength, stability, and control to maintain proper form while leaning forward and returning to the starting position.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0805.gif","youtube_id":null,"instructions":["Attach a suspension trainer to a high anchor point and adjust the straps to waist height.","Stand facing away from the anchor point and hold the handles with your arms extended in front of you.","Lean forward at the waist, keeping your body straight and your core engaged.","Lower your body as far as you can while maintaining control and tension in your abs.","Pause for a moment at the bottom, then slowly raise your body back up to the starting position.","Repeat for the desired number of repetitions."]},{"id":"806","name":"suspended push-up","body_part":"chest","target":"pectorals","secondary_muscles":["triceps","shoulders","core"],"equipment":"body weight","difficulty":"advanced","description":"The suspended push-up is a challenging variation of the traditional push-up performed using a suspension trainer. This exercise increases instability, requiring greater core engagement and upper body strength.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0806.gif","youtube_id":null,"instructions":["Find a suspension trainer and adjust it to an appropriate height.","Stand facing away from the anchor point and hold the handles with an overhand grip.","Walk your feet forward, leaning your body forward until your weight is supported by the suspension trainer.","Keep your body straight from head to heels, engage your core, and lower your chest towards the handles.","Push through your chest and arms to return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"807","name":"suspended reverse crunch","body_part":"waist","target":"abs","secondary_muscles":["hip flexors"],"equipment":"body weight","difficulty":"advanced","description":"The suspended reverse crunch is an advanced core exercise performed by hanging from a pull-up bar and curling the knees up towards the chest, targeting the abdominal muscles and hip flexors.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0807.gif","youtube_id":null,"instructions":["Hang from a pull-up bar with your arms fully extended and your palms facing away from you.","Engage your core and lift your knees up towards your chest, curling your pelvis towards your ribcage.","Pause for a moment at the top, then slowly lower your knees back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"808","name":"suspended row","body_part":"back","target":"upper back","secondary_muscles":["biceps","shoulders"],"equipment":"body weight","difficulty":"intermediate","description":"The suspended row is a bodyweight exercise performed using a suspension trainer. It targets the upper back and also engages the biceps and shoulders. The movement requires pulling your chest towards the handles while maintaining a straight body position, making it effective for building upper body strength and stability.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0808.gif","youtube_id":null,"instructions":["Set up a suspension trainer at an appropriate height.","Stand facing the anchor point with your feet shoulder-width apart.","Hold the handles with an overhand grip, palms facing each other.","Lean back, keeping your body straight and your heels on the ground.","Pull your chest towards the handles, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower yourself back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"809","name":"suspended split squat","body_part":"upper legs","target":"quads","secondary_muscles":["glutes","hamstrings","calves"],"equipment":"body weight","difficulty":"advanced","description":"The suspended split squat is a lower body exercise that targets the quads, with secondary emphasis on the glutes, hamstrings, and calves. It is performed using body weight and a suspension trainer, requiring balance, strength, and coordination.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0809.gif","youtube_id":null,"instructions":["Stand facing away from a suspension trainer with your feet shoulder-width apart.","Extend one leg forward and place the top of your foot in the foot cradle of the suspension trainer.","Bend your standing leg and lower your body down into a lunge position, keeping your chest up and your knee in line with your toes.","Push through your heel to return to the starting position.","Repeat for the desired number of repetitions, then switch legs."]},{"id":"81","name":"barbell reverse preacher curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"barbell","difficulty":"intermediate","description":"The barbell reverse preacher curl is an isolation exercise targeting the biceps and forearms. It is performed on a preacher bench with an overhand grip, emphasizing the brachialis and forearm extensors.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0081.gif","youtube_id":null,"instructions":["Sit on a preacher bench with your chest against the pad and your arms extended straight down, holding a barbell with an overhand grip.","Keeping your upper arms stationary, exhale and curl the barbell upward while contracting your biceps.","Continue to raise the barbell until your biceps are fully contracted and the barbell is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"810","name":"toe touch sit (wall)","body_part":"waist","target":"abs","secondary_muscles":["quads","glutes","hamstrings","calves","upper back"],"equipment":"body weight","difficulty":"intermediate","description":"Stand with your back lightly touching a wall, balance on one leg, lift the opposite leg in front, and reach to touch its toes while sitting the hips back. Return to standing under control and repeat on the other side.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0810.gif","youtube_id":null,"instructions":["Stand tall with your back lightly in contact with a wall, feet about hip-width and 12–18 inches in front of the wall.","Shift weight to the standing leg, brace your abs, and lift the opposite leg in front with the knee slightly bent and toes pulled up.","Reach toward the lifted foot’s toes as you sit your hips back and down, keeping light contact with the wall and your chest up.","Keep the standing knee tracking over the toes; do not let it cave inward.","Briefly touch the toes (or reach as far as control allows) without rounding your lower back.","Drive through the standing heel and engage your core to return to the start. Switch legs and repeat."]},{"id":"811","name":"trap bar deadlift","body_part":"upper legs","target":"glutes","secondary_muscles":["hamstrings","quadriceps","lower back"],"equipment":"trap bar","difficulty":"intermediate","description":"The trap bar deadlift is a compound lower body exercise that targets the glutes, hamstrings, quadriceps, and lower back. It is performed using a trap bar, which allows for a more upright torso and can be easier on the lower back compared to a conventional barbell deadlift.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0811.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and the trap bar on the ground in front of you.","Bend at the hips and knees to lower yourself down and grip the handles of the trap bar with an overhand grip.","Keep your back straight and chest up as you begin to lift the trap bar off the ground by extending your hips and knees.","As you lift, focus on driving through your heels and squeezing your glutes at the top of the movement.","Lower the trap bar back down to the ground by bending at the hips and knees, keeping your back straight throughout the movement.","Repeat for the desired number of repetitions."]},{"id":"812","name":"triceps dip (bench leg)","body_part":"upper arms","target":"triceps","secondary_muscles":["chest","shoulders"],"equipment":"body weight","difficulty":"beginner","description":"The triceps dip (bench leg) is a bodyweight exercise targeting the triceps, performed using a bench for support. It also engages the chest and shoulders as secondary muscles. The movement involves lowering and raising the body using the arms while keeping the legs extended and feet on the ground.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0812.gif","youtube_id":null,"instructions":["Sit on the edge of a bench with your hands gripping the edge, fingers pointing forward.","Walk your feet forward, sliding your butt off the bench, and straighten your arms.","Bend your elbows and lower your body towards the ground, keeping your back close to the bench.","Push through your palms to straighten your arms and return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"813","name":"triceps dip (between benches)","body_part":"upper arms","target":"triceps","secondary_muscles":["chest","shoulders"],"equipment":"body weight","difficulty":"intermediate","description":"The triceps dip (between benches) is a bodyweight exercise targeting the triceps, performed by supporting your weight on your hands between two benches and lowering and raising your body.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0813.gif","youtube_id":null,"instructions":["Sit on a bench with your hands gripping the edge of the bench, fingers pointing forward.","Slide your butt off the bench, supporting your weight with your hands.","Bend your elbows and lower your body towards the ground, keeping your back close to the bench.","Pause for a moment at the bottom, then push yourself back up to the starting position.","Repeat for the desired number of repetitions."]},{"id":"814","name":"triceps dip","body_part":"upper arms","target":"triceps","secondary_muscles":["chest","shoulders"],"equipment":"body weight","difficulty":"beginner","description":"The triceps dip is a bodyweight exercise that targets the triceps and also engages the chest and shoulders. It is performed using a bench or chair and involves lowering and raising the body using the arms.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0814.gif","youtube_id":null,"instructions":["Sit on the edge of a bench or chair with your hands gripping the edge, fingers pointing forward.","Slide your butt off the bench, supporting your weight with your hands.","Bend your elbows and lower your body towards the ground, keeping your back close to the bench.","Pause for a moment at the bottom, then push yourself back up to the starting position.","Repeat for the desired number of repetitions."]},{"id":"815","name":"triceps dips floor","body_part":"upper arms","target":"triceps","secondary_muscles":["chest","shoulders"],"equipment":"body weight","difficulty":"beginner","description":"A bodyweight exercise targeting the triceps, performed using the floor or a stable surface like a chair or bench. It also engages the chest and shoulders as secondary muscles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0815.gif","youtube_id":null,"instructions":["Sit on the edge of a chair or bench with your hands next to your hips, fingers pointing forward.","Slide your butt off the front of the chair with your legs extended in front of you.","Straighten your arms, keeping a little bend in your elbows to keep tension on your triceps and off your elbow joints.","Slowly bend your elbows to lower your body toward the floor until your elbows are at about a 90-degree angle.","Once you reach the bottom of the movement, press down into the chair to straighten your elbows, returning to the starting position.","Repeat for the desired number of repetitions."]},{"id":"816","name":"triceps press","body_part":"upper arms","target":"triceps","secondary_muscles":["shoulders"],"equipment":"body weight","difficulty":"beginner","description":"The triceps press is a bodyweight exercise targeting the triceps, with secondary emphasis on the shoulders. It involves pressing your body away from the ground using your triceps strength, typically performed in a standing position with arms extended forward.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0816.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and your knees slightly bent.","Extend your arms straight out in front of you, parallel to the ground.","Bend your elbows and lower your body towards the ground, keeping your upper arms close to your sides.","Pause for a moment at the bottom, then push yourself back up to the starting position.","Repeat for the desired number of repetitions."]},{"id":"817","name":"triceps stretch","body_part":"upper arms","target":"triceps","secondary_muscles":["shoulders"],"equipment":"body weight","difficulty":"beginner","description":"A static stretch targeting the triceps and shoulders, performed by extending one arm overhead and gently pulling the elbow with the opposite hand.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0817.gif","youtube_id":null,"instructions":["Stand or sit upright with your back straight.","Extend one arm overhead, bending it at the elbow.","Place your opposite hand on the bent elbow and gently pull it towards your head.","Hold the stretch for 15-30 seconds, feeling a gentle stretch in your triceps.","Release the stretch and repeat on the other arm."]},{"id":"818","name":"twin handle parallel grip lat pulldown","body_part":"back","target":"lats","secondary_muscles":["biceps","rhomboids","rear deltoids"],"equipment":"cable","difficulty":"beginner","description":"The twin handle parallel grip lat pulldown is a cable machine exercise targeting the latissimus dorsi, with secondary emphasis on the biceps, rhomboids, and rear deltoids. It involves pulling parallel handles down towards the chest while seated, focusing on squeezing the shoulder blades together.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0818.gif","youtube_id":null,"instructions":["Adjust the seat height and position yourself facing the cable machine.","Grasp the handles with an overhand grip, hands shoulder-width apart.","Sit down and position your thighs under the thigh pads, keeping your feet flat on the floor.","Lean back slightly and keep your chest up, maintaining a neutral spine.","Pull the handles down towards your upper chest, squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, feeling the contraction in your lats.","Slowly release the handles and return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"82","name":"barbell reverse wrist curl","body_part":"lower arms","target":"forearms","secondary_muscles":["biceps","brachialis"],"equipment":"barbell","difficulty":"beginner","description":"The barbell reverse wrist curl is an isolation exercise targeting the forearms, specifically the wrist extensors. It is performed seated, with the forearms resting on the thighs and the wrists curling a barbell upward using an overhand grip.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0082.gif","youtube_id":null,"instructions":["Sit on a bench with your feet flat on the ground and hold a barbell with an overhand grip, palms facing down.","Rest your forearms on your thighs, allowing your wrists to hang off the edge.","Slowly curl your wrists upward, bringing the barbell towards your body.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"826","name":"vertical leg raise (on parallel bars)","body_part":"waist","target":"abs","secondary_muscles":["hip flexors"],"equipment":"body weight","difficulty":"advanced","description":"The vertical leg raise (on parallel bars) is an abdominal exercise performed by hanging from parallel bars and lifting the legs up in front of the body, targeting the abs and hip flexors.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0826.gif","youtube_id":null,"instructions":["Hang from the parallel bars with your arms fully extended and your body straight.","Engage your core and lift your legs up in front of you, keeping them straight.","Continue lifting until your legs are parallel to the ground or slightly higher.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"83","name":"barbell rollerout from bench","body_part":"waist","target":"abs","secondary_muscles":["shoulders","triceps"],"equipment":"barbell","difficulty":"advanced","description":"The barbell rollout from bench is an advanced core exercise that targets the abdominal muscles, with secondary emphasis on the shoulders and triceps. It requires significant core strength, stability, and control to perform safely and effectively.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0083.gif","youtube_id":null,"instructions":["Start by kneeling on the floor with a barbell placed on a bench in front of you.","Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.","Keeping your core engaged and your back straight, slowly roll the barbell forward, extending your arms in front of you.","Continue rolling the barbell forward until your body is fully extended and your arms are overhead.","Pause for a moment at the fully extended position, then slowly roll the barbell back towards your body, returning to the starting position.","Repeat for the desired number of repetitions."]},{"id":"830","name":"weighted bench dip","body_part":"upper arms","target":"triceps","secondary_muscles":["chest","shoulders"],"equipment":"weighted","difficulty":"intermediate","description":"The weighted bench dip is an upper body exercise that targets the triceps, with secondary emphasis on the chest and shoulders. It involves lowering and raising your body using your arms while your feet are on the floor and your hands are on a bench, with added weight for increased resistance.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0830.gif","youtube_id":null,"instructions":["Sit on a bench with your hands gripping the edge, fingers pointing forward.","Slide your butt off the bench, supporting your weight with your hands.","Lower your body by bending your elbows until your upper arms are parallel to the floor.","Push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."]},{"id":"832","name":"weighted crunch","body_part":"waist","target":"abs","secondary_muscles":["obliques"],"equipment":"weighted","difficulty":"intermediate","description":"The weighted crunch is an abdominal exercise that increases resistance to strengthen the abs and obliques. It is performed lying on your back, holding a weight on your chest, and curling your upper body upward.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0832.gif","youtube_id":null,"instructions":["Lie flat on your back with your knees bent and feet flat on the ground.","Hold a weight plate or dumbbell on your chest.","Engage your abs and lift your upper body off the ground, curling forward until your shoulder blades are off the ground.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"833","name":"weighted donkey calf raise","body_part":"lower legs","target":"calves","secondary_muscles":["hamstrings","glutes"],"equipment":"weighted","difficulty":"intermediate","description":"The weighted donkey calf raise is a calf-focused exercise performed on a raised platform, where the lifter raises and lowers their heels while holding additional weight. This movement targets the calves and also engages the hamstrings and glutes as secondary muscles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0833.gif","youtube_id":null,"instructions":["Stand on a raised platform with your toes on the edge and your heels hanging off.","Hold onto a stable object for support.","Raise your heels as high as possible by extending your ankles.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"834","name":"weighted front raise","body_part":"shoulders","target":"delts","secondary_muscles":["biceps","forearms"],"equipment":"weighted","difficulty":"beginner","description":"The weighted front raise is a shoulder exercise that targets the deltoids by lifting dumbbells in front of the body. It also engages the biceps and forearms as secondary muscles. The movement requires control and proper form to avoid swinging or using momentum.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0834.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing your thighs.","Keeping your arms straight, exhale and lift the dumbbells in front of you until they are at shoulder level.","Pause for a moment at the top, then inhale and slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"835","name":"weighted hyperextension (on stability ball)","body_part":"back","target":"spine","secondary_muscles":["glutes","hamstrings"],"equipment":"weighted","difficulty":"intermediate","description":"The weighted hyperextension on a stability ball targets the spinal erectors and is performed by lying face down on a stability ball, anchoring the feet, and extending the back while holding additional weight. This exercise also engages the glutes and hamstrings as secondary muscles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0835.gif","youtube_id":null,"instructions":["Position yourself face down on a stability ball with your hips resting on the ball and your feet against a wall for stability.","Place your hands behind your head or cross them over your chest.","Engage your core and slowly lift your upper body off the ball, extending your back until your body forms a straight line.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"838","name":"weighted lying side lifting head (with head harness)","body_part":"neck","target":"levator scapulae","secondary_muscles":["traps","upper back"],"equipment":"weighted","difficulty":"intermediate","description":"Lie on your side on a bench wearing a head harness attached to a small plate, with your head hanging just off the edge. Side-bend your neck to lift the weight, then lower it under control without rotating.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0838.gif","youtube_id":null,"instructions":["Attach a light plate to the head harness, secure it snugly, and lie on your side on a bench with shoulders and hips stacked.","Position your head just off the bench edge so the weight hangs toward the floor; lightly tuck your chin and keep the neck neutral.","Hold the bench for stability and keep shoulders relaxed; do not rotate your head.","Exhale and laterally flex your neck to lift your head toward your upper shoulder until your head is roughly in line with your torso.","Pause briefly at the top with control.","Inhale and slowly lower back to the start over 2–3 seconds, avoiding any bouncing or excessive range.","Complete the set, then carefully remove the weight and repeat on the opposite side."]},{"id":"84","name":"barbell rollerout","body_part":"waist","target":"abs","secondary_muscles":["lower back"],"equipment":"barbell","difficulty":"advanced","description":"The barbell rollout is an advanced core exercise that targets the abdominal muscles and also engages the lower back. It requires significant core strength, stability, and control to perform safely and effectively.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0084.gif","youtube_id":null,"instructions":["Kneel on the floor and hold a barbell with both hands, shoulder-width apart.","Roll the barbell forward, extending your arms and keeping your core engaged.","Continue rolling forward until your body is fully extended and your arms are overhead.","Pause for a moment, then slowly roll the barbell back towards your knees, maintaining control.","Repeat for the desired number of repetitions."]},{"id":"840","name":"weighted overhead crunch (on stability ball)","body_part":"waist","target":"abs","secondary_muscles":["obliques","lower back"],"equipment":"weighted","difficulty":"intermediate","description":"The weighted overhead crunch on a stability ball targets the abdominal muscles while also engaging the obliques and lower back. The use of a stability ball increases the balance and core stabilization requirements, and holding a weight overhead adds resistance, making the movement more challenging.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0840.gif","youtube_id":null,"instructions":["Sit on a stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Hold a weight plate or dumbbell with both hands and extend your arms overhead.","Engage your abs and slowly curl your torso forward, bringing your chest towards your knees.","Pause for a moment at the top, then slowly lower your torso back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"841","name":"weighted pull-up","body_part":"back","target":"lats","secondary_muscles":["biceps","forearms"],"equipment":"weighted","difficulty":"advanced","description":"The weighted pull-up is an advanced variation of the standard pull-up, where additional weight is used to increase resistance. This exercise primarily targets the latissimus dorsi (lats) and also engages the biceps and forearms. It requires significant upper body strength, coordination, and experience to perform safely and effectively.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0841.gif","youtube_id":null,"instructions":["Grab the pull-up bar with an overhand grip, slightly wider than shoulder-width apart.","Hang from the bar with your arms fully extended and your body straight.","Engage your back muscles and pull your body up towards the bar, keeping your elbows close to your body.","Continue pulling until your chin is above the bar.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"844","name":"weighted round arm","body_part":"shoulders","target":"delts","secondary_muscles":["triceps","upper back"],"equipment":"weighted","difficulty":"intermediate","description":"The weighted round arm is a shoulder exercise that targets the deltoids while also engaging the triceps and upper back. It involves lifting weights in a controlled, circular motion, which requires good form and coordination.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0844.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and hold a dumbbell in each hand.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Raise your arms out to the sides, keeping a slight bend in your elbows.","Continue lifting your arms until they are parallel to the ground.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"845","name":"weighted russian twist (legs up)","body_part":"waist","target":"abs","secondary_muscles":["obliques","hip flexors"],"equipment":"weighted","difficulty":"intermediate","description":"The weighted Russian twist (legs up) is a core exercise that targets the abdominal muscles, particularly the obliques, while also engaging the hip flexors. The movement involves twisting the torso from side to side while holding a weight and keeping the legs elevated, which increases the challenge to balance and core stability.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0845.gif","youtube_id":null,"instructions":["Sit on the ground with your knees bent and feet lifted off the ground, keeping your legs together.","Hold the weight with both hands in front of your chest, keeping your elbows slightly bent.","Lean back slightly to engage your core muscles.","Twist your torso to the right, bringing the weight towards the ground on your right side.","Pause for a moment, then twist your torso to the left, bringing the weight towards the ground on your left side.","Continue alternating sides for the desired number of repetitions."]},{"id":"846","name":"weighted russian twist","body_part":"waist","target":"abs","secondary_muscles":["obliques","lower back"],"equipment":"weighted","difficulty":"intermediate","description":"The weighted Russian twist is a core exercise that targets the abs and obliques, performed by twisting the torso while holding a weight or medicine ball.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0846.gif","youtube_id":null,"instructions":["Sit on the ground with your knees bent and your feet flat on the floor.","Hold a weight or medicine ball with both hands in front of your chest.","Lean back slightly, keeping your back straight and your core engaged.","Slowly twist your torso to the right, bringing the weight or medicine ball towards the floor on your right side.","Pause for a moment, then twist your torso to the left, bringing the weight or medicine ball towards the floor on your left side.","Continue alternating sides for the desired number of repetitions."]},{"id":"847","name":"weighted seated bicep curl (on stability ball)","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"medicine ball","difficulty":"intermediate","description":"A bicep curl performed while seated on a stability ball, using a medicine ball for resistance. This variation challenges core stability and balance in addition to targeting the biceps.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0847.gif","youtube_id":null,"instructions":["Sit on a stability ball with your feet flat on the ground and your back straight.","Hold a medicine ball with an underhand grip, palms facing up, and let your arms hang down by your sides.","Keeping your upper arms stationary, exhale and curl the medicine ball up towards your shoulders.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the medicine ball back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"848","name":"weighted seated neck extension (with head harness)","body_part":"neck","target":"levator scapulae","secondary_muscles":["traps","splenius capitis","splenius cervicis","semispinalis capitis"],"equipment":"weighted","difficulty":"intermediate","description":"Sit on a bench wearing a head harness attached to a weight plate. With your torso braced and chin tucked, extend your neck to raise the weight, then lower back under control.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0848.gif","youtube_id":null,"instructions":["Sit near the edge of a bench with feet flat and torso slightly leaned forward; rest forearms on thighs to brace.","Secure the head harness so it sits snug and level; attach a small weight plate to the front ring.","Start with your chin gently tucked and neck flexed so the plate hangs vertically below your head.","Keeping your torso still, extend your neck by lifting your head until it aligns with your torso—avoid hyperextension.","Pause briefly at the top, then lower your head slowly to the starting position through a comfortable, pain‑free range.","Breathe out as you extend and in as you lower; move steadily without jerking and stop if you feel neck pain."]},{"id":"849","name":"weighted seated twist (on stability ball)","body_part":"waist","target":"abs","secondary_muscles":["obliques","lower back"],"equipment":"weighted","difficulty":"intermediate","description":"The weighted seated twist on a stability ball is an exercise that targets the abdominal muscles, particularly the obliques, while also engaging the lower back. It requires core strength, balance, and coordination due to the instability of the ball and the added resistance from the weight.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0849.gif","youtube_id":null,"instructions":["Sit on a stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Hold a weight plate or dumbbell with both hands close to your chest.","Engage your core and slowly rotate your torso to one side, keeping your hips stable.","Pause for a moment at the end of the rotation, then slowly return to the starting position.","Repeat the rotation to the other side.","Continue alternating sides for the desired number of repetitions."]},{"id":"85","name":"barbell romanian deadlift","body_part":"upper legs","target":"glutes","secondary_muscles":["hamstrings","lower back"],"equipment":"barbell","difficulty":"intermediate","description":"The barbell Romanian deadlift is a strength exercise targeting the glutes, with secondary emphasis on the hamstrings and lower back. It involves hinging at the hips while maintaining a straight back, lowering a barbell to feel a stretch in the hamstrings, and then returning to a standing position.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0085.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and your toes pointing forward.","Hold the barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Bend at the hips, keeping your back straight and your knees slightly bent.","Lower the barbell towards the ground, keeping it close to your body.","Feel the stretch in your hamstrings as you lower the barbell.","Once you feel a stretch in your hamstrings, push your hips forward and stand up straight.","Squeeze your glutes at the top of the movement.","Lower the barbell back down to the starting position and repeat for the desired number of repetitions."]},{"id":"850","name":"weighted side bend (on stability ball)","body_part":"waist","target":"abs","secondary_muscles":["obliques","lower back"],"equipment":"weighted","difficulty":"intermediate","description":"The weighted side bend on a stability ball targets the abdominal muscles, particularly the obliques, and also engages the lower back. The use of a stability ball increases the balance and core activation required, while the added weight increases resistance for strength gains.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0850.gif","youtube_id":null,"instructions":["Sit on a stability ball with your feet shoulder-width apart and flat on the ground.","Hold a weight in one hand and place your other hand on your hip.","Engage your core and slowly bend sideways towards the weighted side, keeping your back straight.","Pause for a moment at the bottom, then slowly return to the starting position.","Repeat for the desired number of repetitions, then switch sides."]},{"id":"851","name":"weighted sissy squat","body_part":"upper legs","target":"quads","secondary_muscles":["glutes","hamstrings","calves"],"equipment":"weighted","difficulty":"advanced","description":"The weighted sissy squat is a challenging lower body exercise that targets the quadriceps while also engaging the glutes, hamstrings, and calves. It requires balance, strength, and coordination, especially when performed with added weight.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0851.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and your toes pointing slightly outward.","Hold a weight in front of your chest with both hands, or place a barbell across your upper back.","Keeping your chest up and your core engaged, slowly lower your body down by bending at the knees and hips.","Continue lowering until your thighs are parallel to the ground or as low as you can comfortably go.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"852","name":"weighted squat","body_part":"upper legs","target":"glutes","secondary_muscles":["quadriceps","hamstrings","calves"],"equipment":"weighted","difficulty":"intermediate","description":"A weighted squat is a compound lower-body exercise that targets the glutes, quadriceps, hamstrings, and calves. It involves holding a weight while performing a squat, increasing resistance and intensity.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0852.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, toes pointing slightly outward.","Hold a weight in front of your chest or on your shoulders.","Engage your core and keep your chest up as you lower your hips down and back, as if sitting into a chair.","Lower until your thighs are parallel to the ground, or as low as you can comfortably go.","Push through your heels to stand back up, squeezing your glutes at the top.","Repeat for the desired number of repetitions."]},{"id":"853","name":"weighted standing curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"weighted","difficulty":"beginner","description":"The weighted standing curl is a classic strength exercise targeting the biceps, performed with dumbbells while standing. It also engages the forearms as secondary muscles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0853.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing forward.","Keep your elbows close to your torso and exhale as you curl the weights up to shoulder level.","Pause for a moment at the top, then inhale as you slowly lower the weights back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"854","name":"weighted standing hand squeeze","body_part":"lower arms","target":"forearms","secondary_muscles":["biceps","triceps"],"equipment":"weighted","difficulty":"beginner","description":"The weighted standing hand squeeze is an exercise targeting the forearms, performed by squeezing weights in each hand while standing. This movement helps to improve grip strength and forearm endurance.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0854.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and hold a weight in each hand.","Extend your arms straight in front of you, palms facing each other.","Squeeze your hands together as hard as you can, engaging your forearms.","Hold the squeeze for a few seconds, then release.","Repeat for the desired number of repetitions."]},{"id":"856","name":"weighted svend press","body_part":"chest","target":"pectorals","secondary_muscles":["shoulders","triceps"],"equipment":"weighted","difficulty":"intermediate","description":"The weighted Svend press is a chest exercise performed by pressing a weight plate out in front of the body, emphasizing the pectoral muscles while also engaging the shoulders and triceps.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0856.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and hold a weight plate in front of your chest with both hands.","Keep your elbows slightly bent and your palms facing each other.","Press the weight plate straight out in front of you, fully extending your arms.","Pause for a moment at the end of the movement, then slowly bring the weight plate back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"857","name":"wheel rollout","body_part":"waist","target":"abs","secondary_muscles":["lower back"],"equipment":"wheel roller","difficulty":"advanced","description":"The wheel rollout is an advanced core exercise that targets the abdominal muscles and also engages the lower back. It requires significant core strength, stability, and control to perform safely and effectively.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0857.gif","youtube_id":null,"instructions":["Kneel on the floor and place the wheel roller in front of you.","Place your hands on the handles of the wheel roller and extend your arms straight out in front of you.","Engage your core muscles and slowly roll the wheel forward, keeping your back straight and your abs tight.","Continue rolling forward until your body is fully extended and your arms are overhead.","Pause for a moment, then slowly roll the wheel back towards your knees, maintaining control and keeping your abs engaged.","Repeat for the desired number of repetitions."]},{"id":"858","name":"wind sprints","body_part":"waist","target":"abs","secondary_muscles":["quadriceps","hamstrings","calves"],"equipment":"body weight","difficulty":"intermediate","description":"Wind sprints are high-intensity running intervals performed over a short distance or time, focusing on explosive speed and cardiovascular endurance. They primarily target the abs for stabilization, while also engaging the quadriceps, hamstrings, and calves.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0858.gif","youtube_id":null,"instructions":["Find an open space or a track to perform the exercise.","Start by standing with your feet shoulder-width apart.","Begin running as fast as you can, pumping your arms and driving your knees up.","Continue sprinting for a specific distance or time period.","Rest and repeat for the desired number of repetitions."]},{"id":"859","name":"wrist rollerer","body_part":"lower arms","target":"forearms","secondary_muscles":["biceps","triceps"],"equipment":"weighted","difficulty":"intermediate","description":"The wrist roller is an exercise that targets the forearms by using a weighted rope or bar. It involves rolling a weight up and down using wrist flexion and extension, which helps build forearm strength and endurance.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0859.gif","youtube_id":null,"instructions":["Attach a weight to one end of a rope or bar.","Hold the other end of the rope or bar with both hands, palms facing down.","Stand with your feet shoulder-width apart and your arms fully extended in front of you.","Slowly roll the weight up towards your hands by flexing your wrists.","Pause for a moment at the top, then slowly lower the weight back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"86","name":"barbell seated behind head military press","body_part":"shoulders","target":"delts","secondary_muscles":["triceps","upper back"],"equipment":"barbell","difficulty":"advanced","description":"The barbell seated behind head military press is a compound shoulder exercise that targets the deltoids, with secondary emphasis on the triceps and upper back. It requires good shoulder mobility and stability, as well as proper technique to avoid injury.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0086.gif","youtube_id":null,"instructions":["Sit on a bench with your back straight and feet flat on the ground.","Hold the barbell with an overhand grip, slightly wider than shoulder-width apart.","Lift the barbell off the rack and bring it down to shoulder level, behind your head.","Press the barbell upward until your arms are fully extended.","Lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"860","name":"cable kickback","body_part":"upper arms","target":"triceps","secondary_muscles":["shoulders"],"equipment":"cable","difficulty":"beginner","description":"The cable kickback is an isolation exercise targeting the triceps, performed using a cable machine. It involves extending the arm backward against resistance to work the triceps, with some secondary engagement of the shoulders.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0860.gif","youtube_id":null,"instructions":["Stand facing a cable machine with your feet shoulder-width apart.","Hold the cable handle with your right hand and step back to create tension in the cable.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Keep your upper arm close to your body and your elbow bent at a 90-degree angle.","Extend your forearm backward, straightening your arm fully.","Pause for a moment, then slowly return to the starting position.","Repeat for the desired number of repetitions, then switch sides."]},{"id":"861","name":"cable seated row","body_part":"back","target":"upper back","secondary_muscles":["biceps","forearms"],"equipment":"cable","difficulty":"beginner","description":"The cable seated row is a strength exercise that targets the upper back, with secondary emphasis on the biceps and forearms. It is performed using a cable row machine and involves pulling handles towards the torso while maintaining a straight back and squeezing the shoulder blades together.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0861.gif","youtube_id":null,"instructions":["Sit on the cable row machine with your feet flat on the footrests and your knees slightly bent.","Grasp the handles with an overhand grip, keeping your back straight and your shoulders relaxed.","Pull the handles towards your body, squeezing your shoulder blades together.","Pause for a moment at the peak of the movement, then slowly release the handles back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"862","name":"cable twist (up-down)","body_part":"waist","target":"abs","secondary_muscles":["obliques","lower back"],"equipment":"cable","difficulty":"intermediate","description":"The cable twist (up-down) is an exercise that targets the abdominal muscles, especially the obliques and lower back, by using a cable machine to add resistance to rotational movements of the torso.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0862.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, facing the cable machine.","Hold the cable handle with both hands in front of your chest, keeping your arms slightly bent.","Engage your core and slowly rotate your torso to one side, keeping your hips and legs stable.","Pause for a moment at the end of the rotation, then slowly return to the starting position.","Repeat the rotation to the opposite side.","Continue alternating sides for the desired number of repetitions."]},{"id":"863","name":"dumbbell lying external shoulder rotation","body_part":"shoulders","target":"delts","secondary_muscles":["rotator cuff","triceps"],"equipment":"dumbbell","difficulty":"beginner","description":"The dumbbell lying external shoulder rotation is an exercise that targets the deltoid muscles and the rotator cuff, helping to improve shoulder stability and strength. It is performed lying on your side, rotating the forearm upward while keeping the upper arm against the side.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0863.gif","youtube_id":null,"instructions":["Lie on your side on a flat bench with your upper arm against your side and your elbow bent 90 degrees.","Hold a dumbbell in your hand with your palm facing down.","Keeping your upper arm against your side, slowly rotate your forearm upward as far as possible.","Pause for a moment at the top, then slowly lower your forearm back down to the starting position.","Repeat for the desired number of repetitions, then switch sides."]},{"id":"864","name":"dumbbell upright shoulder external rotation","body_part":"shoulders","target":"delts","secondary_muscles":["rotator cuff","trapezius"],"equipment":"dumbbell","difficulty":"intermediate","description":"The dumbbell upright shoulder external rotation is an exercise that targets the deltoids and also engages the rotator cuff and trapezius muscles. It involves raising the arms to shoulder height and externally rotating the shoulders while holding dumbbells.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0864.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and hold a dumbbell in each hand with your palms facing your body.","Raise your arms out to the sides until they are parallel to the ground, keeping your elbows slightly bent.","Rotate your arms externally, bringing the dumbbells up towards your head while keeping your elbows in the same position.","Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"865","name":"lying leg-hip raise","body_part":"waist","target":"abs","secondary_muscles":["hip flexors"],"equipment":"body weight","difficulty":"beginner","description":"The lying leg-hip raise is an abdominal exercise performed on the floor using only body weight. It targets the abs and also works the hip flexors. The movement involves lifting the legs and hips off the ground while keeping the core engaged, then lowering them back down with control.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0865.gif","youtube_id":null,"instructions":["Lie flat on your back with your legs extended and your arms by your sides.","Place your hands under your glutes for support.","Engage your core and lift your legs off the ground, raising them towards the ceiling.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"866","name":"weighted hanging leg-hip raise","body_part":"waist","target":"abs","secondary_muscles":["hip flexors","lower back"],"equipment":"weighted","difficulty":"advanced","description":"The weighted hanging leg-hip raise is an advanced core exercise that targets the abdominal muscles, with additional emphasis on the hip flexors and lower back. The movement requires hanging from a pull-up bar while lifting weighted legs up to engage the core.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0866.gif","youtube_id":null,"instructions":["Hang from a pull-up bar with your arms fully extended and your palms facing away from you.","Engage your core and lift your legs up in front of you, keeping them straight.","Continue lifting until your legs are parallel to the ground or slightly higher.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"868","name":"cable curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"cable","difficulty":"beginner","description":"The cable curl is a strength exercise targeting the biceps, performed using a cable machine. It involves curling a cable attachment towards the shoulders while keeping the elbows close to the body, providing constant tension on the biceps throughout the movement.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0868.gif","youtube_id":null,"instructions":["Stand facing the cable machine with your feet shoulder-width apart.","Grasp the cable attachment with an underhand grip, palms facing up.","Keep your elbows close to your sides and your upper arms stationary.","Exhale and curl the cable attachment towards your shoulders, contracting your biceps.","Pause for a moment at the top of the movement, squeezing your biceps.","Inhale and slowly lower the cable attachment back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"869","name":"lever shoulder press v. 2","body_part":"shoulders","target":"delts","secondary_muscles":["triceps","chest"],"equipment":"leverage machine","difficulty":"beginner","description":"The lever shoulder press v. 2 is a machine-based exercise targeting the deltoid muscles, with secondary emphasis on the triceps and chest. It is performed seated on a leverage machine, pressing handles upward and forward to work the shoulders.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0869.gif","youtube_id":null,"instructions":["Adjust the seat height and backrest of the leverage machine to a comfortable position.","Sit on the machine with your back against the backrest and your feet flat on the floor.","Grasp the handles of the machine with an overhand grip, slightly wider than shoulder-width apart.","Push the handles upward and forward until your arms are fully extended, but not locked.","Pause for a moment at the top, then slowly lower the handles back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"87","name":"barbell seated bradford rocky press","body_part":"shoulders","target":"delts","secondary_muscles":["triceps","upper back"],"equipment":"barbell","difficulty":"intermediate","description":"The barbell seated Bradford Rocky press is a shoulder exercise performed while seated, focusing on pressing a barbell overhead to target the deltoids. It also engages the triceps and upper back as secondary muscles. The movement requires good shoulder mobility, core stability, and pressing strength.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0087.gif","youtube_id":null,"instructions":["Sit on a bench with your back straight and feet flat on the ground.","Hold the barbell with an overhand grip, slightly wider than shoulder-width apart.","Lift the barbell to shoulder height, keeping your elbows slightly bent and pointing forward.","Press the barbell overhead, fully extending your arms.","Lower the barbell back to shoulder height and repeat for the desired number of repetitions."]},{"id":"870","name":"butt-ups","body_part":"waist","target":"abs","secondary_muscles":["hip flexors","lower back"],"equipment":"body weight","difficulty":"beginner","description":"Butt-ups are a bodyweight exercise targeting the abdominal muscles. The movement involves lying on your back, lifting your legs towards your chest, and engaging your core to raise your hips off the ground. This exercise also works the hip flexors and lower back as secondary muscles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0870.gif","youtube_id":null,"instructions":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands by your sides, palms facing down.","Engaging your abs, lift your legs off the ground, bringing your knees towards your chest.","At the top of the movement, squeeze your abs and pause for a moment.","Slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"871","name":"tuck crunch","body_part":"waist","target":"abs","secondary_muscles":["hip flexors"],"equipment":"body weight","difficulty":"beginner","description":"The tuck crunch is a bodyweight abdominal exercise that targets the abs and also engages the hip flexors. It involves curling the upper body and bringing the knees toward the chest simultaneously, making it an effective core strengthening movement.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0871.gif","youtube_id":null,"instructions":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, lift your shoulder blades off the ground and bring your knees towards your chest, simultaneously curling your upper body towards your knees.","Pause for a moment at the top, then slowly lower your shoulder blades and extend your legs back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"872","name":"reverse crunch","body_part":"waist","target":"abs","secondary_muscles":["hip flexors"],"equipment":"body weight","difficulty":"beginner","description":"The reverse crunch is a bodyweight exercise that targets the abdominal muscles, especially the lower abs, by curling the hips off the floor and bringing the knees toward the chest.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0872.gif","youtube_id":null,"instructions":["Lie flat on your back with your arms extended along your sides.","Bend your knees and lift your feet off the ground, bringing your thighs perpendicular to the floor.","Contract your abs and curl your hips off the floor, bringing your knees towards your chest.","Pause for a moment at the top, then slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"873","name":"cable reverse crunch","body_part":"waist","target":"abs","secondary_muscles":["hip flexors"],"equipment":"cable","difficulty":"intermediate","description":"The cable reverse crunch is an abdominal exercise that utilizes a cable machine to add resistance to the traditional reverse crunch movement. It primarily targets the abs and also engages the hip flexors.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0873.gif","youtube_id":null,"instructions":["Attach a cable to a low pulley and lie down facing up on a mat.","Hold the cable with both hands and extend your arms straight up towards the ceiling.","Bend your knees and lift your legs up, bringing your thighs towards your chest.","While keeping your upper body stable, curl your pelvis up towards your chest, lifting your hips off the mat.","Pause for a moment at the top, then slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"874","name":"cable standing crunch (with rope attachment)","body_part":"waist","target":"abs","secondary_muscles":["obliques"],"equipment":"cable","difficulty":"intermediate","description":"The cable standing crunch (with rope attachment) is an abdominal exercise performed using a cable machine and rope attachment. It targets the abs and also engages the obliques. The movement involves crunching the torso forward against resistance, providing a challenging core workout.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0874.gif","youtube_id":null,"instructions":["Attach a rope to a cable machine at chest height.","Stand facing away from the machine with your feet shoulder-width apart.","Hold the rope with both hands and bring it behind your head, keeping your elbows bent.","Engage your abs and slowly crunch your torso forward, bringing your elbows towards your knees.","Pause for a moment at the top of the crunch, then slowly return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"88","name":"barbell seated calf raise","body_part":"lower legs","target":"calves","secondary_muscles":["hamstrings","quadriceps"],"equipment":"barbell","difficulty":"beginner","description":"The barbell seated calf raise is an exercise that targets the calf muscles by lifting a barbell placed on the thighs while seated. It primarily focuses on strengthening the calves and also engages the hamstrings and quadriceps as secondary muscles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0088.gif","youtube_id":null,"instructions":["Sit on a bench with your feet flat on the floor and a barbell resting on your thighs.","Place the balls of your feet on a raised platform, such as a block or step.","Position the barbell across your thighs and hold it securely with your hands.","Keeping your back straight and your core engaged, lift your heels off the ground by extending your ankles.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"89","name":"barbell seated close-grip concentration curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"barbell","difficulty":"intermediate","description":"The barbell seated close-grip concentration curl is an isolation exercise targeting the biceps, performed while seated with a barbell using a close grip. It emphasizes strict form and biceps contraction by bracing the upper arms against the inner thighs.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0089.gif","youtube_id":null,"instructions":["Sit on a bench with your feet flat on the floor and hold a barbell with an underhand grip, hands shoulder-width apart.","Rest your upper arms against your inner thighs, just above your knees, and let the barbell hang down in front of you.","Keeping your upper arms stationary, exhale and curl the barbell up towards your shoulders, contracting your biceps.","Hold the contracted position for a brief pause, then inhale and slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"9","name":"assisted chest dip (kneeling)","body_part":"chest","target":"pectorals","secondary_muscles":["triceps","shoulders"],"equipment":"leverage machine","difficulty":"beginner","description":"The assisted chest dip (kneeling) is a chest-focused exercise performed on a leverage machine, where the user kneels on a pad for support. This machine-assisted variation helps reduce the load, making it accessible for those building strength or learning proper dip technique.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0009.gif","youtube_id":null,"instructions":["Adjust the machine to your desired height and secure your knees on the pad.","Grasp the handles with your palms facing down and your arms fully extended.","Lower your body by bending your elbows until your upper arms are parallel to the floor.","Pause for a moment, then push yourself back up to the starting position.","Repeat for the desired number of repetitions."]},{"id":"90","name":"barbell seated good morning","body_part":"upper legs","target":"glutes","secondary_muscles":["hamstrings","lower back"],"equipment":"barbell","difficulty":"intermediate","description":"The barbell seated good morning is a strength exercise that targets the glutes, with secondary emphasis on the hamstrings and lower back. It involves sitting on a bench with a barbell on your upper back, hinging forward at the hips, and returning to the upright position.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0090.gif","youtube_id":null,"instructions":["Sit on a bench with your feet flat on the ground and a barbell resting on your upper back.","Keep your back straight and your chest up.","Slowly hinge forward at the hips, lowering your torso towards the ground.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"91","name":"barbell seated overhead press","body_part":"shoulders","target":"delts","secondary_muscles":["triceps","upper back"],"equipment":"barbell","difficulty":"intermediate","description":"The barbell seated overhead press is a compound strength exercise targeting the deltoid muscles of the shoulders. It also engages the triceps and upper back as secondary muscles. This movement is performed seated, which helps stabilize the lower body and focus the effort on the upper body. It requires proper technique and shoulder mobility to perform safely and effectively.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0091.gif","youtube_id":null,"instructions":["Sit on a bench with your back straight and feet flat on the ground.","Hold the barbell with an overhand grip, slightly wider than shoulder-width apart.","Lift the barbell off the rack and bring it to shoulder level, with your elbows bent and palms facing forward.","Press the barbell overhead by extending your arms fully.","Pause for a moment at the top, then slowly lower the barbell back to shoulder level.","Repeat for the desired number of repetitions."]},{"id":"92","name":"barbell seated overhead triceps extension","body_part":"upper arms","target":"triceps","secondary_muscles":["shoulders"],"equipment":"barbell","difficulty":"intermediate","description":"The barbell seated overhead triceps extension is an exercise that targets the triceps by extending the arms overhead while seated, using a barbell for resistance. It also engages the shoulders as secondary muscles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0092.gif","youtube_id":null,"instructions":["Sit on a bench with your back straight and feet flat on the ground.","Hold a barbell with an overhand grip, hands shoulder-width apart, and raise it overhead.","Lower the barbell behind your head by bending your elbows, keeping your upper arms close to your head.","Pause for a moment, then extend your arms to raise the barbell back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"94","name":"barbell seated twist","body_part":"waist","target":"abs","secondary_muscles":["obliques","lower back"],"equipment":"barbell","difficulty":"intermediate","description":"The barbell seated twist is an exercise that targets the abdominal muscles, particularly the obliques and lower back, by rotating the torso while seated and holding a barbell.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0094.gif","youtube_id":null,"instructions":["Sit on a flat bench with your feet flat on the ground and your knees bent.","Hold a barbell with both hands in front of your chest, keeping your elbows slightly bent.","Engage your core and slowly twist your torso to one side, keeping your back straight.","Pause for a moment at the end of the twist, then slowly rotate back to the starting position.","Repeat the twist to the other side.","Continue alternating sides for the desired number of repetitions."]},{"id":"95","name":"barbell shrug","body_part":"back","target":"traps","secondary_muscles":["shoulders"],"equipment":"barbell","difficulty":"beginner","description":"The barbell shrug is a strength exercise targeting the trapezius muscles. It involves lifting the shoulders towards the ears while holding a barbell, focusing on building upper back and neck strength.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0095.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and hold a barbell in front of you with an overhand grip.","Keep your arms straight and your back straight throughout the exercise.","Lift your shoulders up towards your ears as high as possible, squeezing your traps at the top.","Hold for a moment, then slowly lower your shoulders back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"96","name":"barbell side bent v. 2","body_part":"waist","target":"abs","secondary_muscles":["obliques","lower back"],"equipment":"barbell","difficulty":"intermediate","description":"The barbell side bent v. 2 is an exercise targeting the abdominal muscles, particularly the obliques, by bending the torso side to side while holding a barbell. It also engages the lower back for stability.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0096.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and hold a barbell with both hands, palms facing down.","Keep your back straight and core engaged throughout the exercise.","Slowly bend your torso to the right side, lowering the barbell towards your right knee.","Pause for a moment, then return to the starting position.","Repeat the movement on the left side.","Continue alternating sides for the desired number of repetitions."]},{"id":"968","name":"band alternating biceps curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"band","difficulty":"beginner","description":"The band alternating biceps curl is an exercise targeting the biceps using a resistance band. It involves curling one arm at a time while keeping the elbows close to the body, providing resistance throughout the movement.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0968.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and hold the band with an underhand grip, palms facing up.","Keep your elbows close to your sides and slowly curl one arm up towards your shoulder, squeezing your biceps at the top.","Lower the arm back down to the starting position and repeat with the other arm.","Continue alternating arms for the desired number of repetitions."]},{"id":"969","name":"band alternating v-up","body_part":"waist","target":"abs","secondary_muscles":["hip flexors"],"equipment":"band","difficulty":"intermediate","description":"The band alternating v-up is an abdominal exercise that targets the abs and hip flexors. It involves lying on your back, holding a resistance band, and simultaneously lifting your legs and upper body while alternating leg positions.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0969.gif","youtube_id":null,"instructions":["Lie flat on your back with your legs straight and your arms extended overhead, holding the band.","Engage your abs and lift your legs and upper body off the ground simultaneously, reaching your hands towards your toes.","As you lower your legs and upper body back down, switch the position of your legs, crossing one over the other.","Repeat the movement, alternating the position of your legs with each repetition.","Continue for the desired number of repetitions."]},{"id":"97","name":"barbell side split squat v. 2","body_part":"upper legs","target":"quads","secondary_muscles":["glutes","hamstrings","calves"],"equipment":"barbell","difficulty":"intermediate","description":"The barbell side split squat v. 2 is a lower body exercise that targets the quadriceps while also engaging the glutes, hamstrings, and calves. It involves stepping laterally into a squat position while holding a barbell across the upper back, requiring strength, balance, and coordination.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0097.gif","youtube_id":null,"instructions":["Stand with your feet wider than shoulder-width apart, toes pointing slightly outwards.","Hold a barbell across your upper back, resting it on your shoulders.","Take a big step to the side with your right foot, keeping your left foot planted.","Bend your right knee and lower your body down into a squat position, keeping your chest up and your back straight.","Push through your right heel to return to the starting position.","Repeat on the other side, stepping out with your left foot.","Continue alternating sides for the desired number of repetitions."]},{"id":"970","name":"band assisted pull-up","body_part":"back","target":"lats","secondary_muscles":["biceps","forearms"],"equipment":"band","difficulty":"beginner","description":"The band assisted pull-up is a variation of the traditional pull-up that uses a resistance band to provide assistance, making it easier to perform the movement. This exercise targets the latissimus dorsi (lats) and also works the biceps and forearms. It is commonly used to build strength and improve pull-up technique, especially for those who are not yet able to perform unassisted pull-ups.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0970.gif","youtube_id":null,"instructions":["Attach the band to a pull-up bar or sturdy anchor point.","Step onto the band and grip the bar with your palms facing away from you, hands slightly wider than shoulder-width apart.","Hang with your arms fully extended, keeping your core engaged and your shoulders down and back.","Pull your body up towards the bar by squeezing your shoulder blades together and driving your elbows down towards your hips.","Continue pulling until your chin is above the bar, then slowly lower yourself back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"971","name":"band assisted wheel rollerout","body_part":"waist","target":"abs","secondary_muscles":["lower back"],"equipment":"band","difficulty":"intermediate","description":"The band assisted wheel rollout is an abdominal exercise that uses a resistance band to help control the movement and reduce the difficulty compared to a standard ab wheel rollout. It targets the abs and also engages the lower back for stability.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0971.gif","youtube_id":null,"instructions":["Kneel on the floor and hold the handles of the band with both hands, palms facing down.","Place the band on the ground in front of you and position your hands shoulder-width apart.","Engage your core and slowly roll the wheel forward, extending your body as far as you can while maintaining control.","Pause for a moment at the furthest point, then slowly roll the wheel back towards your knees to return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"972","name":"band bicycle crunch","body_part":"waist","target":"abs","secondary_muscles":["hip flexors","obliques"],"equipment":"band","difficulty":"intermediate","description":"The band bicycle crunch is a core exercise that targets the abs, with additional emphasis on the hip flexors and obliques. The use of a resistance band increases the challenge, requiring greater core stability and strength.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0972.gif","youtube_id":null,"instructions":["Lie flat on your back with your hands behind your head and your knees bent.","Lift your feet off the ground and bring your right knee towards your chest while simultaneously twisting your torso to bring your left elbow towards your right knee.","Straighten your right leg while bringing your left knee towards your chest and twisting your torso to bring your right elbow towards your left knee.","Continue alternating the twisting motion, as if you are pedaling a bicycle, while keeping your core engaged throughout the movement.","Repeat for the desired number of repetitions."]},{"id":"974","name":"band close-grip pulldown","body_part":"back","target":"lats","secondary_muscles":["biceps","forearms"],"equipment":"band","difficulty":"beginner","description":"The band close-grip pulldown is a resistance exercise targeting the latissimus dorsi (lats) using a resistance band anchored overhead. It mimics the motion of a cable pulldown but uses a band for resistance, making it accessible and effective for home workouts.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0974.gif","youtube_id":null,"instructions":["Attach the band to a high anchor point, such as a pull-up bar or sturdy beam.","Stand facing the anchor point and grab the band with an underhand grip, hands shoulder-width apart.","Step back to create tension in the band, keeping your feet hip-width apart.","Engage your core and keep your back straight as you pull the band down towards your chest, squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, then slowly release the band back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"975","name":"band close-grip push-up","body_part":"upper arms","target":"triceps","secondary_muscles":["chest","shoulders"],"equipment":"band","difficulty":"intermediate","description":"The band close-grip push-up is a variation of the traditional push-up that uses a resistance band to increase tension and target the triceps more effectively. The close hand placement emphasizes the triceps, while the band adds extra resistance throughout the movement.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0975.gif","youtube_id":null,"instructions":["Place a band around your upper arms, just above the elbows.","Assume a push-up position with your hands directly under your shoulders and your body in a straight line from head to heels.","Bend your elbows and lower your chest towards the ground, keeping your elbows close to your sides.","Push through your palms to extend your arms and return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"976","name":"band concentration curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms"],"equipment":"band","difficulty":"beginner","description":"The band concentration curl is an isolation exercise targeting the biceps using a resistance band. It is performed seated, with the working arm braced against the thigh to minimize cheating and maximize biceps engagement.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0976.gif","youtube_id":null,"instructions":["Sit on a bench or chair with your legs spread apart and your feet flat on the ground.","Hold one end of the band in your hand and step on the other end with your foot on the same side.","Lean forward slightly and rest your elbow on the inside of your thigh, just above the knee.","With your palm facing up, slowly curl your hand towards your shoulder, keeping your upper arm stationary.","Pause for a moment at the top, then slowly lower your hand back down to the starting position.","Repeat for the desired number of repetitions, then switch sides."]},{"id":"977","name":"band front lateral raise","body_part":"shoulders","target":"delts","secondary_muscles":["traps","upper back"],"equipment":"band","difficulty":"beginner","description":"The band front lateral raise is a shoulder exercise that targets the deltoid muscles. Using a resistance band, you lift your arms straight in front of you, working the shoulders and upper back.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0977.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and hold the band in front of your thighs with your palms facing down.","Keep your arms straight and lift the band up in front of you until your arms are parallel to the ground.","Pause for a moment at the top, then slowly lower the band back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"978","name":"band front raise","body_part":"shoulders","target":"delts","secondary_muscles":["triceps","upper back"],"equipment":"band","difficulty":"beginner","description":"The band front raise is an exercise targeting the deltoid muscles of the shoulders. It is performed by standing on a resistance band and raising the arms straight in front of the body to shoulder height, then lowering them back down. This movement helps build shoulder strength and stability, with secondary activation of the triceps and upper back.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0978.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and hold the band in front of your thighs with your palms facing down.","Keep your arms straight and slowly raise them forward until they are parallel to the ground.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"979","name":"band horizontal pallof press","body_part":"waist","target":"abs","secondary_muscles":["obliques","glutes"],"equipment":"band","difficulty":"beginner","description":"The band horizontal Pallof press is an anti-rotation core exercise that targets the abs and obliques, helping to build core stability and strength. It is performed using a resistance band anchored at waist height.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0979.gif","youtube_id":null,"instructions":["Attach the band to a sturdy anchor point at waist height.","Stand perpendicular to the anchor point with your feet shoulder-width apart.","Grasp the band handle with both hands and step away from the anchor point to create tension in the band.","Bring your hands to your chest, keeping your elbows bent and close to your body.","Engage your core and maintain a stable stance.","Extend your arms straight out in front of you, pushing the band away from your body.","Hold the extended position for a few seconds, focusing on maintaining tension in your core.","Slowly bring your hands back to your chest, resisting the pull of the band.","Repeat for the desired number of repetitions."]},{"id":"98","name":"barbell side split squat","body_part":"upper legs","target":"quads","secondary_muscles":["glutes","hamstrings","calves"],"equipment":"barbell","difficulty":"intermediate","description":"The barbell side split squat is a lower body exercise that targets the quadriceps while also engaging the glutes, hamstrings, and calves. It requires holding a barbell across the upper back and performing a wide-stance squat, emphasizing lateral movement and stability.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0098.gif","youtube_id":null,"instructions":["Stand with your feet wider than shoulder-width apart, toes pointing slightly outward.","Hold a barbell across your upper back, resting it on your traps.","Engage your core and keep your chest up as you lower your body down into a squat position, bending at the knees and hips.","As you lower, push your knees out to the sides and keep your weight on your heels.","Lower until your thighs are parallel to the ground, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"980","name":"band bent-over hip extension","body_part":"upper legs","target":"glutes","secondary_muscles":["hamstrings","lower back"],"equipment":"band","difficulty":"beginner","description":"The band bent-over hip extension is an exercise targeting the glutes, performed by extending one leg back against resistance from a band while maintaining a bent-over position. It also engages the hamstrings and lower back.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0980.gif","youtube_id":null,"instructions":["Attach the band to a sturdy anchor point at ankle height.","Stand facing away from the anchor point with your feet shoulder-width apart.","Step back to create tension in the band, keeping your knees slightly bent.","Hinge at the hips and lean forward, maintaining a neutral spine.","Extend your right leg straight back, squeezing your glutes at the top.","Lower your right leg back down and repeat with the left leg.","Continue alternating legs for the desired number of repetitions."]},{"id":"981","name":"band jack knife sit-up","body_part":"waist","target":"abs","secondary_muscles":["hip flexors"],"equipment":"band","difficulty":"intermediate","description":"The band jack knife sit-up is an abdominal exercise that uses a resistance band to increase difficulty. It targets the abs and also works the hip flexors. The movement involves simultaneously lifting the legs and upper body while holding a resistance band, requiring core strength and coordination.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0981.gif","youtube_id":null,"instructions":["Lie flat on your back with your legs straight and your arms extended overhead, holding the band.","Engage your abs and lift your legs and upper body simultaneously, bringing your hands towards your feet.","Pause for a moment at the top, then slowly lower your legs and upper body back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"982","name":"band lying hip external rotation","body_part":"upper legs","target":"glutes","secondary_muscles":["gluteus medius (posterior fibers)","piriformis","obturator internus/externus","gemellus superior/inferior"],"equipment":"band","difficulty":"beginner","description":"Anchor a light band beside you and loop it around one ankle. Lying prone with knees bent to 90°, rotate the hip to draw the foot inward across the midline against the band, then return with control.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0982.gif","youtube_id":null,"instructions":["Anchor the band to a fixed point at ankle height on the working side and loop it around the ankle.","Lie face down with hips square, forehead on hands, and both knees bent to about 90°; keep thighs on the floor.","Start with the band pulling the working foot outward; brace your core and keep the pelvis still.","Externally rotate the hip to move the foot inward across the midline while keeping the knees together and thigh down.","Pause briefly at end range without arching the lower back or lifting the thigh.","Slowly let the band draw the foot back to the start, maintaining control and pelvic stability.","Keep the motion smooth from the hip only; repeat for the set, then switch sides."]},{"id":"983","name":"band kneeling one arm pulldown","body_part":"back","target":"lats","secondary_muscles":["biceps","rhomboids"],"equipment":"band","difficulty":"beginner","description":"The band kneeling one arm pulldown is a resistance band exercise targeting the latissimus dorsi (lats) and also engaging the biceps and rhomboids. It involves kneeling and pulling a resistance band from overhead down to your side, focusing on controlled movement and muscle engagement.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0983.gif","youtube_id":null,"instructions":["Attach the band to a sturdy anchor point above your head.","Kneel down and hold the band with one hand, palm facing down.","Extend your arm fully overhead, keeping your elbow slightly bent.","Engage your lat muscles and pull the band down towards your side, bringing your elbow towards your ribcage.","Pause for a moment at the bottom, then slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions, then switch sides."]},{"id":"984","name":"band lying hip internal rotation","body_part":"upper legs","target":"glutes","secondary_muscles":["hamstrings","quadriceps"],"equipment":"band","difficulty":"beginner","description":"The band lying hip internal rotation is an exercise that targets the glutes and helps improve hip mobility and strength. It is performed lying on your back with a resistance band looped around your feet, focusing on rotating the knees outward while keeping the feet together.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0984.gif","youtube_id":null,"instructions":["Lie on your back with your legs straight and a resistance band looped around your feet.","Bend your knees and bring them towards your chest, keeping your feet together.","Slowly rotate your knees outwards, away from each other, while keeping your feet together.","Pause for a moment at the end of the rotation, then slowly return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"985","name":"band kneeling twisting crunch","body_part":"waist","target":"abs","secondary_muscles":["obliques"],"equipment":"band","difficulty":"intermediate","description":"The band kneeling twisting crunch is an abdominal exercise that targets the abs and obliques using a resistance band. It involves kneeling and twisting the torso against the resistance of the band, engaging the core muscles.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0985.gif","youtube_id":null,"instructions":["Attach the band to a sturdy anchor point at waist height.","Kneel down facing away from the anchor point and hold the band with both hands, keeping your elbows bent and close to your sides.","Engage your abs and slowly twist your torso to one side, bringing your hands towards your opposite hip.","Pause for a moment, then slowly return to the starting position.","Repeat on the other side.","Continue alternating sides for the desired number of repetitions."]},{"id":"986","name":"band one arm overhead biceps curl","body_part":"upper arms","target":"biceps","secondary_muscles":["forearms","shoulders"],"equipment":"band","difficulty":"beginner","description":"The band one arm overhead biceps curl is an isolation exercise targeting the biceps, performed with a resistance band. It involves curling the arm overhead while keeping the upper arm stationary, providing resistance throughout the movement.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0986.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and place one end of the band under your foot.","Hold the other end of the band with your arm fully extended overhead, palm facing forward.","Keeping your upper arm stationary, curl your forearm towards your shoulder, squeezing your biceps.","Pause for a moment at the top, then slowly lower your forearm back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]},{"id":"987","name":"band one arm single leg split squat","body_part":"upper legs","target":"quads","secondary_muscles":["glutes","hamstrings"],"equipment":"band","difficulty":"intermediate","description":"The band one arm single leg split squat is a lower body exercise that targets the quadriceps, with secondary emphasis on the glutes and hamstrings. It involves performing a split squat on one leg with the rear foot elevated and a resistance band around the ankles, challenging balance and unilateral strength.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0987.gif","youtube_id":null,"instructions":["Stand with your feet hip-width apart and place a resistance band around your ankles.","Extend one leg forward and rest the top of your foot on a bench or step behind you.","Hold onto a support with one hand for balance.","Bend your standing leg and lower your body down into a squat position, keeping your knee in line with your toes.","Push through your heel to return to the starting position.","Repeat for the desired number of repetitions, then switch legs."]},{"id":"988","name":"band one arm standing low row","body_part":"back","target":"upper back","secondary_muscles":["biceps","shoulders"],"equipment":"band","difficulty":"beginner","description":"The band one arm standing low row is a resistance band exercise targeting the upper back, performed by pulling a band anchored at waist height towards your waist with one arm while standing.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0988.gif","youtube_id":null,"instructions":["Attach the band to a stable anchor point at waist height.","Stand facing the anchor point with your feet shoulder-width apart.","Hold the band with one hand, palm facing inward, and step back to create tension in the band.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Pull the band towards your waist, squeezing your shoulder blades together.","Pause for a moment at the top of the movement, then slowly release the band back to the starting position.","Repeat for the desired number of repetitions, then switch sides."]},{"id":"989","name":"band one arm twisting chest press","body_part":"chest","target":"pectorals","secondary_muscles":["shoulders","triceps"],"equipment":"band","difficulty":"intermediate","description":"The band one arm twisting chest press is a unilateral chest exercise using a resistance band. It targets the pectorals while also engaging the shoulders and triceps. The twisting motion adds a rotational component, increasing core activation and coordination demands.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0989.gif","youtube_id":null,"instructions":["Attach the band to a sturdy anchor point at chest height.","Stand with your side facing the anchor point and grab the band with one hand.","Step away from the anchor point to create tension in the band.","Position your feet shoulder-width apart and slightly bend your knees.","Bring your hand holding the band across your body, towards the opposite shoulder.","While maintaining tension in the band, push your hand forward and away from your body, extending your arm.","Slowly return to the starting position and repeat for the desired number of repetitions.","Switch sides and repeat the exercise with the other hand."]},{"id":"99","name":"barbell single leg split squat","body_part":"upper legs","target":"quads","secondary_muscles":["glutes","hamstrings","calves"],"equipment":"barbell","difficulty":"intermediate","description":"The barbell single leg split squat is a lower body exercise that targets the quadriceps while also engaging the glutes, hamstrings, and calves. It requires balance, coordination, and strength, as you perform a squat movement with one leg forward and a barbell across your upper back.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0099.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart, holding a barbell across your upper back.","Take a large step forward with one leg, keeping your torso upright.","Lower your body by bending your front knee and hip, while keeping your back leg straight.","Continue lowering until your front thigh is parallel to the ground.","Pause for a moment, then push through your front heel to return to the starting position.","Repeat for the desired number of repetitions, then switch legs."]},{"id":"990","name":"band one arm twisting seated row","body_part":"back","target":"upper back","secondary_muscles":["biceps","shoulders"],"equipment":"band","difficulty":"intermediate","description":"The band one arm twisting seated row is a resistance exercise targeting the upper back, with secondary emphasis on the biceps and shoulders. It incorporates a twisting motion to engage the core and improve rotational strength.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0990.gif","youtube_id":null,"instructions":["Sit on a bench or chair with your feet flat on the ground and your back straight.","Hold the band with one hand and extend your arm fully in front of you.","Keeping your back straight, pull the band towards your body by bending your elbow and squeezing your shoulder blades together.","At the same time, twist your torso towards the side of the pulling arm.","Pause for a moment at the top, then slowly release the tension in the band and return to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]},{"id":"991","name":"band pull through","body_part":"upper legs","target":"glutes","secondary_muscles":["hamstrings","lower back"],"equipment":"band","difficulty":"beginner","description":"The band pull through is a hip hinge exercise that targets the glutes, hamstrings, and lower back using a resistance band. It is performed by hinging at the hips while facing away from an anchored band, then driving the hips forward to stand upright.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0991.gif","youtube_id":null,"instructions":["Attach a resistance band to a sturdy anchor point at ground level.","Stand facing away from the anchor point with your feet shoulder-width apart.","Step forward to create tension in the band, keeping your knees slightly bent.","Hinge at the hips and push your glutes back, maintaining a slight bend in your knees.","Lower your torso until it is parallel to the ground, feeling a stretch in your hamstrings.","Drive your hips forward and squeeze your glutes to return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"992","name":"band push sit-up","body_part":"waist","target":"abs","secondary_muscles":["shoulders","chest"],"equipment":"band","difficulty":"intermediate","description":"The band push sit-up is an abdominal exercise that incorporates resistance from a band to increase the challenge on the core muscles. It also engages the shoulders and chest as stabilizers during the movement.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0992.gif","youtube_id":null,"instructions":["Attach the band securely to a stable anchor point.","Lie flat on your back with your knees bent and feet flat on the ground.","Hold the band with both hands and extend your arms straight up towards the ceiling.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"993","name":"band reverse fly","body_part":"shoulders","target":"delts","secondary_muscles":["upper back","trapezius"],"equipment":"band","difficulty":"beginner","description":"The band reverse fly is an exercise that targets the deltoid muscles of the shoulders, as well as the upper back and trapezius. It is performed using a resistance band attached to a stationary object, and involves pulling the band apart with straight arms to strengthen the rear delts and upper back.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0993.gif","youtube_id":null,"instructions":["Attach the band to a stationary object at chest height.","Stand with your feet shoulder-width apart and hold the band with both hands in front of you.","Keep your arms straight and lift them out to the sides until they are parallel to the ground.","Squeeze your shoulder blades together at the top of the movement.","Slowly lower your arms back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"994","name":"band reverse wrist curl","body_part":"lower arms","target":"forearms","secondary_muscles":["forearms"],"equipment":"band","difficulty":"beginner","description":"The band reverse wrist curl is an isolation exercise targeting the forearms, specifically the wrist extensors, using a resistance band. It is performed seated, with the forearms resting on the thighs and the wrists curling upward against the resistance of the band.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0994.gif","youtube_id":null,"instructions":["Sit on a bench or chair with your feet flat on the ground.","Hold the band with an overhand grip, palms facing down, and wrap it around your fingers.","Rest your forearms on your thighs, with your wrists hanging off the edge.","Slowly curl your wrists upward, squeezing your forearms.","Pause for a moment at the top, then slowly lower your wrists back down to the starting position.","Repeat for the desired number of repetitions."]},{"id":"995","name":"band seated hip external rotation","body_part":"upper legs","target":"glutes","secondary_muscles":["gluteus medius","gluteus minimus","piriformis","obturator internus"],"equipment":"band","difficulty":"beginner","description":"Sit at the edge of a bench with a light band looped around the working ankle and anchored to the outside of that leg. Keep the knee bent 90° and rotate the hip to draw the foot inward against the band, then return with control.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0995.gif","youtube_id":null,"instructions":["Sit tall at the bench edge with hips and knees at about 90°, feet hanging or lightly touching the floor.","Loop a light band around the working ankle and attach the other end to a lateral anchor at ankle height so it pulls the lower leg outward.","Brace your core, keep the thigh vertical and the knee pointing straight ahead.","Without moving the knee, externally rotate the hip to bring the foot inward toward the midline against the band’s tension.","Pause briefly at end range without leaning or letting the thigh drift.","Slowly return to neutral under control; avoid snapping the band.","Perform all reps, then switch sides. Keep the range small and pain-free."]},{"id":"996","name":"band seated hip internal rotation","body_part":"upper legs","target":"glutes","secondary_muscles":["hamstrings","quadriceps"],"equipment":"band","difficulty":"beginner","description":"The band seated hip internal rotation is an exercise that targets the glutes and helps improve hip mobility and strength. It is performed while seated, using a resistance band to provide external resistance as you rotate your knees outward.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0996.gif","youtube_id":null,"instructions":["Sit on a chair or bench with your back straight and feet flat on the ground.","Place a resistance band around your thighs, just above your knees.","Keep your knees bent at a 90-degree angle and your feet shoulder-width apart.","Engage your glutes and slowly rotate your knees outward, pushing against the resistance of the band.","Pause for a moment at the end of the movement, then slowly return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"997","name":"band shoulder press","body_part":"shoulders","target":"delts","secondary_muscles":["triceps","upper back"],"equipment":"band","difficulty":"beginner","description":"The band shoulder press is a resistance exercise targeting the deltoid muscles of the shoulders, using a resistance band for added tension. It also engages the triceps and upper back as secondary muscles. The movement involves pressing the band overhead from shoulder height, making it a fundamental strength exercise for the upper body.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0997.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and place the band under your feet.","Hold the band with your palms facing forward and raise your hands to shoulder height, elbows bent.","Press the band overhead, fully extending your arms.","Pause for a moment at the top, then slowly lower the band back to shoulder height.","Repeat for the desired number of repetitions."]},{"id":"998","name":"band side triceps extension","body_part":"upper arms","target":"triceps","secondary_muscles":["shoulders"],"equipment":"band","difficulty":"beginner","description":"The band side triceps extension is an exercise targeting the triceps using a resistance band. It also engages the shoulders as secondary muscles. The movement involves extending the arms out to the sides and bending the elbows to bring the hands toward the shoulders, then returning to the starting position.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0998.gif","youtube_id":null,"instructions":["Stand with your feet shoulder-width apart and hold the band with both hands, palms facing down.","Extend your arms straight out to the sides, keeping them parallel to the ground.","Slowly bend your elbows and bring your hands towards your shoulders, keeping your upper arms still.","Pause for a moment, then slowly extend your arms back out to the starting position.","Repeat for the desired number of repetitions."]},{"id":"999","name":"band single leg calf raise","body_part":"lower legs","target":"calves","secondary_muscles":["ankles","feet"],"equipment":"band","difficulty":"intermediate","description":"The band single leg calf raise is a lower leg exercise that targets the calves using a resistance band. It also engages the ankles and feet, helping to improve strength and stability in the lower leg. The movement is performed one leg at a time, which increases the balance and coordination required.","gif_url":"https://lkopadfjqjaqmivkyzgw.supabase.co/storage/v1/object/public/exercise-gifs/exercisedb-0999.gif","youtube_id":null,"instructions":["Stand with your feet hip-width apart and place the band around the ball of your left foot.","Hold onto a stable object for balance if needed.","Slowly raise your left heel off the ground, lifting your body weight onto the ball of your foot.","Pause for a moment at the top, then slowly lower your left heel back down to the starting position.","Repeat for the desired number of repetitions, then switch to the right leg."]}]$exercises_seed$::jsonb
)
